<?php
/**
 * HRMS — single-file backend API.
 * Every request goes through this one file: api.php?action=...
 *
 * Actions:
 *   login                     POST  {username, password}
 *   me                        GET   (auth)
 *   setup_admin                GET   one-time — creates admin/Admin@123, then refuses to run again
 *   departments.list           GET   (auth)
 *   departments.save           POST  (auth: Admin/HR)  {department_id?, department_name}
 *   departments.delete         POST  (auth: Admin/HR)  {department_id}
 *   employees.list             GET   (auth)  ?search=&department_id=
 *   employees.get              GET   (auth)  ?id=
 *   employees.save             POST  (auth: Admin/HR)  {employee_id?, full_name, joining_date, ...}
 *   employees.delete           POST  (auth: Admin/HR)  {employee_id}
 *   document_types.list        GET   (auth)
 *   document_types.save        POST  (auth: Admin/HR)  {document_type_id?, document_name, is_required}
 *   employee_documents.list    GET   (auth)  ?employee_id=
 *   employee_documents.upload  POST  (auth: Admin/HR)  multipart/form-data: employee_id, document_type_id,
 *                                     document_file, document_number?, issue_date?, expiry_date?, remarks?
 *   employee_documents.update  POST  (auth: Admin/HR)  JSON {employee_document_id, document_type_id, document_number?,
 *                                     issue_date?, expiry_date?, remarks?} — OR multipart/form-data with the same
 *                                     fields plus an optional document_file to replace the stored file.
 *   employee_documents.delete  POST  (auth: Admin/HR)  {employee_document_id}
 *   agreements.send            POST  (auth: Admin/HR)  {template_id, employee_ids[]}
 *                                     Employees who already saved a signature are signed instantly
 *                                     (auto_signed = 1); the rest stay pending for them to sign.
 *   agreements.cancel          POST  (auth: Admin/HR)  {agreement_id} — removes a pending request
 *   dashboard.stats            GET   (auth)
 *
 * Auth: either
 *   Authorization: Bearer <token>   (returned by the login action)
 *   X-API-Key: <API_KEY>            (static dev/testing key, treated as Admin)
 */

// ---------------- CORS ----------------
header('Access-Control-Allow-Origin: *');
header('Access-Control-Allow-Methods: GET, POST, OPTIONS');
header('Access-Control-Allow-Headers: Content-Type, Authorization, X-API-Key');
header('Content-Type: application/json; charset=UTF-8');
// Never let the browser, the hosting CDN or a proxy answer an API call from a saved copy —
// otherwise a change (e.g. a shift time) is saved but the next read still shows the old value.
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');
header('X-LiteSpeed-Cache-Control: no-cache');

if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {
    http_response_code(200);
    exit;
}

// ---------------- Timezone (IST) ----------------
// Hostinger's server runs on UTC — force Indian time for all date()/time()
// calls (punch times, manual order dates, etc).
date_default_timezone_set('Asia/Kolkata');

// Big live Shopify fetches (multi-day/month ranges) need more than the
// default 30s / 128M.
@set_time_limit(300);
@ini_set('memory_limit', '512M');

// ---------------- config.php (optional) ----------------
// Settings that shouldn't live in this file — the mailbox password for
// agreement emails, and any DB override — go in config.php in this same
// folder. It is loaded first, so anything it defines wins over the
// defaults below.
if (is_file(__DIR__ . '/config.php')) require_once __DIR__ . '/config.php';

// ---------------- DB credentials ----------------
// Real values belong in config.php (gitignored). Placeholders here so nothing secret is committed.
if (!defined('DB_HOST')) define('DB_HOST', '127.0.0.1');
if (!defined('DB_NAME')) define('DB_NAME', 'your_db_name');
if (!defined('DB_USER')) define('DB_USER', 'your_db_user');
if (!defined('DB_PASS')) define('DB_PASS', '');

// Signs the login tokens — set a long random value in config.php
if (!defined('APP_SECRET')) define('APP_SECRET', '');

// Static dev/testing key for VS Code / REST Client — set in config.php if needed
if (!defined('API_KEY')) define('API_KEY', '');
// Shown in the sidebar (with the layout.js build) so you can see at a glance
// which api.php is live. Bump when you change api.php.
define('HRMS_BUILD', '261105.1');
define('LAYOUT_MIN', '261101.1');   // oldest layout.js that has every current page in its menu

// Targets page: minimum gap between real Shopify syncs for a given month,
// enforced here on the server so it applies no matter how many browsers/
// admins have the page open — not a per-browser localStorage throttle.
define('TARGETS_SYNC_INTERVAL_SECONDS', 300); // 5 minutes

// How long before the day's start time an arrival still counts as "today".
// Day start 10:00 -> a punch in from 06:00 onwards is today; before that it is
// taken as a night shift belonging to the previous day.
define('PUNCH_EARLY_WINDOW_MINUTES', 240);

// A busy shared MySQL sometimes refuses a connection for a moment (too many connections, restart): try up to 3 times
// before giving up, and say WHY when it does fail so it can be fixed (the error number only — never host / user / password).
$pdo = null; $dbErr = null;
$dbWait = [150000, 300000, 600000, 1200000, 2000000];   // 0.15 s, 0.3 s, 0.6 s, 1.2 s, 2 s: a refused connection usually frees up within a second, so the first retries are short
for ($dbTry = 0; $dbTry < 6 && !$pdo; $dbTry++) {   // 6 tries, about 4 s in the worst case
    if ($dbTry) usleep($dbWait[$dbTry - 1] + mt_rand(0, 100000));
    try {
        $pdo = new PDO(
            "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4",
            DB_USER,
            DB_PASS,
            [
                PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES   => false,
                // Optional (config.php: define('DB_PERSISTENT', true);): keep the connection open between requests so a busy page does not
                // open and close 10+ connections a second. Best on a VPS with PHP-FPM; off by default so shared hosting behaves as before.
                PDO::ATTR_PERSISTENT         => defined('DB_PERSISTENT') && DB_PERSISTENT,
            ]
        );
        if (defined('DB_PERSISTENT') && DB_PERSISTENT) {   // a kept connection must start every request clean: no half-open transaction, no lock left by a request that died
            try { if ($pdo->inTransaction()) $pdo->rollBack(); $pdo->query("SELECT RELEASE_ALL_LOCKS()")->fetchAll(); } catch (Throwable $e) { }
        }
        $pdo->exec("SET time_zone = '+05:30'");
    } catch (PDOException $e) {
        $pdo = null; $dbErr = $e;
    }
}
if (!$pdo) {
    $dbNo = preg_match('/\[(\d{3,4})\]/', $dbErr ? $dbErr->getMessage() : '', $dbm) ? (int)$dbm[1] : 0;
    $dbWhy = [1040 => 'too many connections', 1203 => 'this database user has too many open connections', 1226 => 'hourly connection limit reached', 1045 => 'access denied',
              1049 => 'database not found', 2002 => 'database server not reachable', 2006 => 'database server went away', 2013 => 'connection lost'][$dbNo] ?? '';
    json_response(['error' => 'Database connection failed' . ($dbNo ? ' (error ' . $dbNo . ($dbWhy ? ': ' . $dbWhy : '') . ')' : '') . '.'], 500);
}
$HAS_SIG_COL = ensure_signature_column($pdo);

// ---------------- helpers ----------------

/**
 * employees.signature_file is an optional cache column. Older databases
 * don't have it. Create it once if missing; if that isn't possible, every
 * code path below still works without it (the uploaded Digital Signature
 * document is the primary source anyway).
 */
function ensure_signature_column(PDO $pdo): bool
{
    static $has = null;
    if ($has !== null) return $has;
    $flag = sys_get_temp_dir() . '/hrms_sigcol_ok';
    if (is_file($flag)) return $has = true;
    try {
        $col = $pdo->query("SHOW COLUMNS FROM employees LIKE 'signature_file'")->fetch();
        if (!$col) {
            $pdo->exec("ALTER TABLE employees ADD COLUMN signature_file VARCHAR(255) NULL DEFAULT NULL");
        }
        @file_put_contents($flag, '1');
        return $has = true;
    } catch (PDOException $e) {
        return $has = false;
    }
}
/** employees.gender: 'M' / 'F' / NULL (not set). Female employees: the shoe photo still taken at Punch In, but any footwear is accepted. */
function ensure_gender_column(PDO $pdo): bool
{
    static $has = null;
    if ($has !== null) return $has;
    $flag = sys_get_temp_dir() . '/hrms_gendercol_ok';
    if (is_file($flag)) return $has = true;
    try {
        if (!$pdo->query("SHOW COLUMNS FROM employees LIKE 'gender'")->fetch()) $pdo->exec("ALTER TABLE employees ADD COLUMN gender CHAR(1) NULL DEFAULT NULL");
        @file_put_contents($flag, '1');
        return $has = true;
    } catch (PDOException $e) { return $has = false; }
}
function clean_gender($g): ?string
{
    $g = strtoupper(substr(trim((string)$g), 0, 1));
    return in_array($g, ['M', 'F'], true) ? $g : null;
}
function employee_is_female(PDO $pdo, int $empId): bool
{
    static $c = [];
    if (isset($c[$empId])) return $c[$empId];
    if (!$empId || !ensure_gender_column($pdo)) return $c[$empId] = false;
    try { $st = $pdo->prepare("SELECT gender FROM employees WHERE employee_id = ?"); $st->execute([$empId]); return $c[$empId] = ((string)$st->fetchColumn() === 'F'); }
    catch (PDOException $e) { return $c[$empId] = false; }
}
/** The sidebar flags (who may see what). Used by me.flags and by bd.menu_ctx. */
function me_flags_data(PDO $pdo, array $auth): array
{
        $isSales = false;
        if (!empty($auth['employee_id'])) {
            $stmt = $pdo->prepare(
                "SELECT d.department_name FROM employees e
                 LEFT JOIN departments d ON d.department_id = e.department_id
                 WHERE e.employee_id = ?"
            );
            $stmt->execute([$auth['employee_id']]);
            $dept = (string)$stmt->fetchColumn();
            $isSales = stripos($dept, 'sales') !== false;
        }
        $perms = [];
        $role = $auth['role'] ?? '';
        if ($role === 'Admin') $perms = array_keys(all_permissions());
        elseif ($role === 'HR') {
            $perms = role_permissions($pdo, 'HR');
            if (!$perms) $perms = array_values(array_diff(array_keys(all_permissions()), ['approvals', 'users', 'leave']));
        }
        else $perms = role_permissions($pdo, $role); // custom roles AND Employee
        if (strcasecmp(trim((string)$role), 'Employee') === 0 && in_array('allocation', $perms, true) && !allocation_employee_allowed($pdo, $auth)) $perms = array_values(array_diff($perms, ['allocation']));
        $hasSalary = false;
        if (!empty($auth['employee_id'])) {
            $sStmt = $pdo->prepare("SELECT monthly_salary FROM employees WHERE employee_id = ?");
            $sStmt->execute([$auth['employee_id']]);
            $hasSalary = (float)$sStmt->fetchColumn() > 0;
        }
    return ['is_sales' => $isSales, 'has_salary' => $hasSalary, 'has_employee' => !empty($auth['employee_id']), 'permissions' => $perms, 'role' => $role, 'build' => HRMS_BUILD, 'layout_min' => LAYOUT_MIN];
}

/** Used by bd.menu_ctx: while capture is on, json_response() hands its answer back instead of sending it. */
class JrCapture extends Exception { public $data; public $httpCode; public function __construct($data, $code) { parent::__construct('captured'); $this->data = $data; $this->httpCode = $code; } }
function json_response($data, int $code = 200): void
{
    if (!empty($GLOBALS['__jr_cap'])) { throw new JrCapture($data, $code); }
    $j = json_encode($data);
    if ($j === false) {   // broken text (half a letter / emoji) used to make the answer EMPTY, which screens read as "nothing" — keep the answer, mark the broken bits
        $j = json_encode($data, JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR);
        if ($j === false) { $code = 500; $j = '{"error":"The server could not write its answer (' . addslashes(json_last_error_msg()) . ')."}'; }
    }
    // The Help page probes read calls WITHOUT parameters; a harmless 'not found / missing field' answer then showed up as a red error in the browser console.
    // For those probes only (?probe=1, GET) such answers are sent as 200 (same text inside); real pages and real errors are unchanged.
    if (isset($_GET['probe']) && $_GET['probe'] === '1' && ($_SERVER['REQUEST_METHOD'] ?? '') === 'GET' && ($code === 404 || $code === 422) && stripos($j, 'unknown action') === false) $code = 200;
    http_response_code($code);
    echo $j;
    exit;
}

// A PHP fatal error would otherwise be a blank HTTP 500 ("Server error (500)"). Answer with JSON that names what failed and where.
register_shutdown_function(function () {
    $e = error_get_last();
    if (!$e || !in_array($e['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR, E_RECOVERABLE_ERROR], true)) return;
    if (!headers_sent()) { http_response_code(500); header('Content-Type: application/json; charset=utf-8'); }
    echo json_encode(['error' => 'Server error: ' . mb_substr((string)$e['message'], 0, 300) . ' (' . basename((string)$e['file']) . ' line ' . (int)$e['line'] . ')']);
});

function json_input(): array
{
    $raw = file_get_contents('php://input');
    $data = json_decode($raw, true);
    return is_array($data) ? $data : [];
}

function generate_token(array $payload, int $ttlSeconds = 2592000): string // 30 days
{
    $payload['exp'] = time() + $ttlSeconds;
    $json = json_encode($payload);
    $b64 = rtrim(strtr(base64_encode($json), '+/', '-_'), '=');
    $sig = hash_hmac('sha256', $b64, APP_SECRET);
    return $b64 . '.' . $sig;
}

function verify_token(?string $token): ?array
{
    if (!$token || strpos($token, '.') === false) {
        return null;
    }
    [$b64, $sig] = explode('.', $token, 2);
    $expected = hash_hmac('sha256', $b64, APP_SECRET);
    if (!hash_equals($expected, $sig)) {
        return null;
    }
    $json = base64_decode(strtr($b64, '-_', '+/'));
    $payload = json_decode($json, true);
    if (!is_array($payload) || !isset($payload['exp']) || $payload['exp'] < time()) {
        return null;
    }
    return $payload;
}

function get_bearer_token(): ?string
{
    $header = null;
    if (function_exists('getallheaders')) {
        foreach (getallheaders() as $k => $v) {
            if (strtolower($k) === 'authorization') {
                $header = $v;
                break;
            }
        }
    }
    if (!$header && isset($_SERVER['HTTP_AUTHORIZATION'])) {
        $header = $_SERVER['HTTP_AUTHORIZATION'];
    }
    if (!$header && isset($_SERVER['REDIRECT_HTTP_AUTHORIZATION'])) {
        $header = $_SERVER['REDIRECT_HTTP_AUTHORIZATION'];
    }
    if ($header && stripos($header, 'Bearer ') === 0) {
        return substr($header, 7);
    }
    return null;
}

function get_api_key_header(): ?string
{
    if (function_exists('getallheaders')) {
        foreach (getallheaders() as $k => $v) {
            if (strtolower($k) === 'x-api-key') {
                return $v;
            }
        }
    }
    return $_SERVER['HTTP_X_API_KEY'] ?? null;
}

function require_auth(): array
{
    $apiKey = get_api_key_header();
    if ($apiKey && hash_equals(API_KEY, $apiKey)) {
        // Dev/testing access via static key — treated as full Admin.
        return ['user_id' => 0, 'employee_id' => null, 'username' => 'api-key', 'role' => 'Admin'];
    }

    $payload = verify_token(get_bearer_token());
    if (!$payload) {
        json_response(['error' => 'Unauthorized. Please log in again.'], 401);
    }
    return refresh_auth($payload);
}

/**
 * The login token carries the role it was issued with. Re-read the user's
 * current role / employee link from the users table on every request, so a
 * role change on the Users page applies at once — no log out / log in.
 */
function refresh_auth(array $payload): array
{
    global $pdo;
    static $cache = [];
    $uid = (int)($payload['user_id'] ?? 0);
    if ($uid <= 0) return $payload;
    if (!array_key_exists($uid, $cache)) {
        try {
            $st = $pdo->prepare("SELECT username, role, employee_id FROM users WHERE user_id = ? LIMIT 1");
            $st->execute([$uid]);
            $cache[$uid] = $st->fetch() ?: null;
        } catch (PDOException $e) {
            $cache[$uid] = false; // lookup failed — fall back to the token
        }
    }
    $row = $cache[$uid];
    if ($row === null) json_response(['error' => 'This login no longer exists. Please log in again.'], 401);
    if ($row) {
        $payload['role'] = (string)$row['role'];
        $payload['employee_id'] = $row['employee_id'];
        $payload['username'] = (string)$row['username'];
    }
    return $payload;
}

