/**
 * Extra ticks that also open an action: the pages that call it. action_permission() names ONE module per action; a page of another module that
 * needs the same action (Commission reading the commission rules, Targets reading attendance, Orders using the conversation tools …) lists it here,
 * so a role given that page is not stopped half-way on it. Read the match as a prefix, like action_permission().
 */
function action_page_perms(string $action): array
{
    static $map = [
        'convo.' => ['orders'],                         // Orders page: conversation analyser / playbook
        'order_ratings.' => ['orders', 'allocation'],   // ⭐ rate orders from the Orders page (a sales head / manager) as well as Order Allocation
        'premsg.' => ['orders'],                        // Orders page: pre-messages
        'target_rule.' => ['orders'],                   // Orders page: the automatic target rule
        'attendance.list' => ['targets'],               // Targets page reads who was present
        'queries.assign_list' => ['targets'],           // Targets page reads the query assignment
        'day_timing.save' => ['targets'],               // Targets page: working time of the day
        'day_timing.get' => ['targets', 'performance', 'allocation', 'commission'],
        'commission_rules.list' => ['commission'],      // Commission page shows the rules it pays by
        'commission_rules.code_list' => ['commission'],
        'commission_rules.manual_list' => ['commission'],
        'addons.' => ['allocation'],                    // Order Allocation: add-ons
        'employees.list' => ['dashboard', 'leave_requests', 'documents', 'agreements', 'approvals', 'targets', 'performance', 'commission', 'allocation'],
        'document_types.list' => ['dashboard', 'approvals'],
        'employee_documents.list' => ['dashboard', 'approvals'],
        'employee_documents.approve' => ['approvals'],
        'employee_documents.decline' => ['approvals'],
        'employees.approve' => ['approvals'],
        'employees.decline' => ['approvals'],
        'dashboard.stats' => ['approvals'],
        'departments.list' => ['attendance', 'employees', 'documents'],
        'footwear.' => ['attendance'],
    ];
    $out = [];
    foreach ($map as $prefix => $perms) if (strpos($action, $prefix) === 0) $out = array_merge($out, $perms);
    return $out;
}

