        'employee_sources.sync' => 'employees',
        'sales_db.' => 'orders',
        'fs_check' => 'dashboard',
        'schema_check' => 'dashboard',
        'targets.' => 'targets',
        'employees.set_daily_target' => 'targets',
        'performance.' => 'performance',
        'order_ratings.' => 'performance',   // per-order star ratings on the Performance page
        'employees.set_color' => 'assign_queries',
        'queries.hourly' => 'assign_queries',
        'queries.assign' => 'assign_queries',
        'queries.assign_set' => 'assign_queries',
        'queries.panel_hour_set' => 'assign_queries',
        'queries.' => 'performance',
        'salary' => 'salary',
        'commission_rules.' => 'commission_rules',
        'report_detail.' => 'detailed_report',
        'penalties.' => 'penalties',
        'commission_page.' => 'commission',
        'budget.' => 'commission',            // Total Budgeting uses the Commission permission
        'commission.' => 'targets',
        'agreement' => 'agreements',
        'departments.' => 'departments',
        'employees.' => 'employees',
        'document' => 'documents',
        'whatsapp' => 'whatsapp_groups',
        'excel' => 'excel_files',
        'history' => 'decline_history',
        'approvals.' => 'approvals',
        'users.' => 'users',
        'roles.' => 'users',
    ];
    foreach ($map as $prefix => $perm) {
        if (strpos($action, $prefix) === 0 || ($prefix[strlen($prefix) - 1] !== '.' && strpos($action, $prefix) !== false)) {
            return $perm;
        }
    }
    return null;
}

/**
 * roles.known_modules remembers which modules existed when the role was
 * last saved. A module added to the app later is unknown to that saved
 * tick list, so HR (default access: everything except Approvals / Users)
 * gets it automatically instead of silently losing the new page until an
 * Admin re-saves the role.
 */
function ensure_roles_known_column(PDO $pdo): void
{
    static $done = false;
    if ($done) return;
    $done = true;
    $flag = sys_get_temp_dir() . '/hrms_roles_known_ok';
    if (is_file($flag)) return;
    try {
        $col = $pdo->query("SHOW COLUMNS FROM roles LIKE 'known_modules'")->fetch();
        if (!$col) $pdo->exec("ALTER TABLE roles ADD COLUMN known_modules TEXT NULL");
        @file_put_contents($flag, '1');
    } catch (PDOException $e) {}
}

/** Modules that did not exist when this role was last saved. */
function role_new_modules(?string $knownJson): array
{
    $all = array_keys(all_permissions());
    // Saved before known_modules existed: only the modules that were in the
    // app at that time count as known. Everything added since (Order
    // Allocation, Office Locations, Order Codes, …) is new to that role.
    $addedSince = ['allocation', 'offices', 'order_codes', 'retail', 'order_targets', 'commission', 'leave_requests', 'leave', 'order_code_lock'];
    $known = $knownJson ? (json_decode($knownJson, true) ?: []) : array_diff($all, $addedSince);
    return array_values(array_diff($all, $known));
}

function role_permissions(PDO $pdo, string $roleName): array
{
    static $cache = [];
    if (!isset($cache[$roleName])) {
        ensure_roles_known_column($pdo);
        // Case- and space-insensitive: "Sales head" and "sales head" are the same role.
        try {
            $stmt = $pdo->prepare("SELECT permissions, known_modules FROM roles WHERE LOWER(TRIM(role_name)) = LOWER(TRIM(?))");
            $stmt->execute([$roleName]);
            $row = $stmt->fetch();
            $perms = $row && $row['permissions'] ? (json_decode($row['permissions'], true) ?: []) : [];
            if ($row && $perms && strcasecmp(trim($roleName), 'Employee') !== 0) {
                // HR and every custom role automatically get a module that was
                // added to the app AFTER their ticks were last saved (except
                // Approvals / Users). Admin can untick it on the Roles page —
                // saving there records the module as known, so the untick
                // sticks. The Employee role stays portal-only unless ticked.
                // 'order_code_lock' goes to HR automatically, to every other role only when Admin ticks it.
                $noAuto = ['approvals', 'users', 'leave', 'detailed_report', 'visit_approval', 'finance', 'analytics', 'inventory', 'retail_store', 'rs_counter', 'rs_tasks', 'rs_manage'];   // 'detailed_report' (ad spend, ROAS, collection) and 'visit_approval' are ticked by Admin per role, never automatic
                if (strcasecmp(trim($roleName), 'HR') !== 0) $noAuto[] = 'order_code_lock';
                foreach (role_new_modules($row['known_modules'] ?? null) as $m) {
                    if (!in_array($m, $noAuto, true) && !in_array($m, $perms, true)) $perms[] = $m;   // 'leave' (My Leave) is handed out by Admin per role, never automatically
                }
            }
            $cache[$roleName] = $perms;
        } catch (PDOException $e) {
            $cache[$roleName] = []; // roles table missing — only system roles work
        }
    }
    return $cache[$roleName];
}

function user_can(array $authPayload, string $perm): bool
{
    global $pdo;
    $role = $authPayload['role'] ?? '';
    if ($role === 'Admin') return true;
    if ($role === 'HR') {
        $perms = role_permissions($pdo, 'HR');
        if ($perms) return in_array($perm, $perms, true);
        // No custom ticks saved yet: original default access.
        return !in_array($perm, ['approvals', 'users', 'leave', 'visit_approval', 'finance'], true);
    }
    if ($role === 'Employee') {
        // Employee is portal-only by default, but Admin can grant admin-side
        // modules to the Employee role from the Roles page.
        if ($perm === 'allocation' && !allocation_employee_allowed($pdo, $authPayload)) return false;
        return in_array($perm, role_permissions($pdo, 'Employee'), true);
    }
    return in_array($perm, role_permissions($pdo, $role), true);
}

/**
 * Order Allocation for the Employee role is limited by department. Admin picks the departments on the Order Allocation
 * page (setting allocation_departments, a JSON list of department names). Until a choice is saved, only Sales Executive,
 * Sales Head and Sales Helper may open it. Admin, HR and custom roles are not affected — their Roles-page ticks decide.
 */
function allocation_departments_saved(PDO $pdo): ?array
{
    $raw = setting_get($pdo, 'allocation_departments', null);
    if ($raw === null || $raw === '') return null;
    $a = json_decode((string)$raw, true);
    return is_array($a) ? array_values(array_filter(array_map(fn($x) => trim((string)$x), $a), fn($x) => $x !== '')) : null;
}
function allocation_dept_norm(string $s): string
{
    return trim(preg_replace('/\s+/', ' ', mb_strtolower($s)));
}
/** Department names that may open Order Allocation: the saved choice, else the Sales Executive / Head / Helper departments. */
function allocation_allowed_departments(PDO $pdo): array
{
    $saved = allocation_departments_saved($pdo);
    if ($saved !== null) return $saved;
    $out = [];
    try { foreach ($pdo->query("SELECT department_name FROM departments ORDER BY department_name")->fetchAll() as $r) if (sales_sheet_role_ok((string)$r['department_name'], '')) $out[] = (string)$r['department_name']; } catch (PDOException $e) {}
    return $out;
}
/** May this login open Order Allocation? Only the Employee role is checked, by the employee's department. */
function allocation_employee_allowed(PDO $pdo, array $auth): bool
{
    if (strcasecmp(trim((string)($auth['role'] ?? '')), 'Employee') !== 0) return true;
    $eid = (int)($auth['employee_id'] ?? 0);
    if (!$eid) return false;
    static $cache = [];
    if (array_key_exists($eid, $cache)) return $cache[$eid];
    $ok = false;
    try {
        $st = $pdo->prepare("SELECT d.department_name, e.designation FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.employee_id = ?");
        $st->execute([$eid]);
        $r = $st->fetch();
        if ($r) {
            $dept = trim((string)($r['department_name'] ?? ''));
            if (allocation_departments_saved($pdo) === null) {
                $ok = sales_sheet_role_ok($dept, (string)($r['designation'] ?? ''));     // not chosen yet: Sales Executive / Head / Helper (a general "Sales" department by Designation)
            } else {
                $ok = $dept !== '' && in_array(allocation_dept_norm($dept), array_map('allocation_dept_norm', allocation_departments_saved($pdo)), true);
            }
        }
    } catch (PDOException $e) {}
    return $cache[$eid] = $ok;
}

function require_role(array $allowedRoles, array $authPayload): void
{
    global $action;
    $role = $authPayload['role'] ?? '';
    if ($role === 'Admin') return;
    $perm = action_permission((string)$action);
    // HR follows its Roles-page ticks like any other role (all modules
    // except Approvals / Users until ticks are saved); an action with no
    // module keeps the old open access for HR.
    if (in_array($role, $allowedRoles, true) && ($role !== 'HR' || $perm === null)) return;

    // Allowed when the role has this action's module granted.
    if ($perm !== null && user_can($authPayload, $perm)) return;

    // …or the role has the tick of a PAGE that uses this action: giving a page on the Roles page gives everything that page needs, not only its menu entry.
    foreach (action_page_perms((string)$action) as $pp) if (user_can($authPayload, $pp)) return;

    // Say exactly what's missing, so it can be fixed on the Roles page.
    $labels = all_permissions();
    $module = $perm !== null ? ($labels[$perm] ?? $perm) : null;
    $msg = $module
        ? "Your role \"$role\" doesn't include the $module module. Ask an Admin to tick \"$module\" for \"$role\" on the Roles page."
        : 'You do not have permission to do this.';
    json_response(['error' => $msg, 'role' => $role, 'module' => $perm], 403);
}

/**
 * Who may use My Leave (apply / see own requests / cancel): the Employee role always, Admin always, every other role
 * (HR, custom roles) only when Admin ticked "My Leave" for it on the Roles page.
 */
function require_leave_access(array $auth): void
{
    $role = (string)($auth['role'] ?? '');
    if ($role === 'Admin' || strcasecmp(trim($role), 'Employee') === 0) return;
    if (user_can($auth, 'leave')) return;
    json_response([
        'error' => "Your role \"$role\" cannot apply for leave yet. Ask an Admin to tick \"My Leave (apply for own leave)\" for \"$role\" on the Roles page.",
        'role' => $role, 'module' => 'leave',
    ], 403);
}

/**
 * The Orders page controls (Employee sheet, attendance / target / code edits, Cancel) belong to everyone who has the
 * Shopify Orders page — not only Admin / HR. The Employee role keeps its own-orders-only view and never gets them.
 */
function orders_page_controls(array $auth): bool
{
    $role = strtolower(trim((string)($auth['role'] ?? '')));
    if ($role === 'employee') return false;
    return ($auth['role'] ?? '') === 'Admin' || user_can($auth, 'orders');
}

/**
 * Add-ons are entered from the Performance page (Admin / HR / roles with Performance) and from the Order Allocation
 * page (any role that has Order Allocation). The Employee role can never add or remove one from Order Allocation.
 */
function require_addons_access(array $auth): void
{
    $role = strtolower(trim((string)($auth['role'] ?? '')));
    if ($role !== 'employee' && user_can($auth, 'allocation')) return;
    require_role(['Admin', 'HR'], $auth);
}

function generate_employee_code(PDO $pdo): string
{
    $stmt = $pdo->query(
        "SELECT employee_code FROM employees
         WHERE employee_code LIKE 'EMP%'
         ORDER BY employee_id DESC LIMIT 1"
    );
    $last = $stmt->fetchColumn();
    $next = 1;
    if ($last && preg_match('/(\d+)$/', $last, $m)) {
        $next = (int)$m[1] + 1;
    }
    return 'EMP' . str_pad((string)$next, 4, '0', STR_PAD_LEFT);
}

/**
 * Replace an employee's WhatsApp group memberships with the given set.
 * $groupIds: array of ids, or a JSON string of that array (multipart sends it
 * as a string), or null = "not provided, leave memberships untouched".
 */
function sync_employee_groups(PDO $pdo, int $employeeId, $groupIds): void
{
    if ($groupIds === null) return;
    if (is_string($groupIds)) {
        $decoded = json_decode($groupIds, true);
        $groupIds = is_array($decoded) ? $decoded : [];
    }
    if (!is_array($groupIds)) return;

    $pdo->prepare("DELETE FROM employee_whatsapp_groups WHERE employee_id = ?")->execute([$employeeId]);
    $ins = $pdo->prepare("INSERT IGNORE INTO employee_whatsapp_groups (employee_id, group_id) VALUES (?, ?)");
    foreach ($groupIds as $gid) {
        if ((int)$gid > 0) $ins->execute([$employeeId, (int)$gid]);
    }
}

/**
 * Same pattern for Excel/Google Sheet file memberships (manual mapping).
 */
function sync_employee_excel_files(PDO $pdo, int $employeeId, $fileIds): void
{
    if ($fileIds === null) return;
    if (is_string($fileIds)) {
        $decoded = json_decode($fileIds, true);
        $fileIds = is_array($decoded) ? $decoded : [];
    }
    if (!is_array($fileIds)) return;

    $pdo->prepare("DELETE FROM employee_excel_files WHERE employee_id = ?")->execute([$employeeId]);
    $ins = $pdo->prepare("INSERT IGNORE INTO employee_excel_files (employee_id, file_id) VALUES (?, ?)");
    foreach ($fileIds as $fid) {
        if ((int)$fid > 0) $ins->execute([$employeeId, (int)$fid]);
    }
}

/**
 * Store Groups: which storefront(s) a sales employee is assigned to
 * (TM Perfume House / TM4U). Manually ticked per employee,
 * same pattern as WhatsApp Groups — an employee can belong to any number of
 * the three, including none or all. Backs the group filter on Targets,
 * Assign Queries and Performance.
 */
function store_group_options(): array
{
    return ['tmph' => 'TM Perfume House', 'tmsg' => 'TM Shower Gel'];   // TM4U was removed: only these two panels are used
}

function ensure_store_groups_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_storegroups_ok_v3';
    if (is_file($flag)) return $done = true;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS employee_store_groups (
                employee_id INT NOT NULL,
                group_key VARCHAR(10) NOT NULL,
                PRIMARY KEY (employee_id, group_key)
            )"
        );
        // Older installs created group_key as ENUM('tmph','tm4u'):
        // widen it so the new panel (TM Shower Gel) fits.
        try { $pdo->exec("ALTER TABLE employee_store_groups MODIFY group_key VARCHAR(10) NOT NULL"); } catch (PDOException $e) {}
        // TM4U was removed (one-time clean-up): everyone who was in TM4U is now in TM Perfume House, and the TM4U assignment is deleted.
        try {
            $pdo->exec("INSERT IGNORE INTO employee_store_groups (employee_id, group_key) SELECT employee_id, 'tmph' FROM employee_store_groups WHERE group_key = 'tm4u'");
            $pdo->exec("DELETE FROM employee_store_groups WHERE group_key = 'tm4u'");
        } catch (PDOException $e) {}
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

function sync_employee_store_groups(PDO $pdo, int $employeeId, $groupKeys): void
{
    if ($groupKeys === null) return;
    if (is_string($groupKeys)) {
        $decoded = json_decode($groupKeys, true);
        $groupKeys = is_array($decoded) ? $decoded : [];
    }
    if (!is_array($groupKeys)) return;
    if (!ensure_store_groups_table($pdo)) return;

    $valid = array_keys(store_group_options());
    $pdo->prepare("DELETE FROM employee_store_groups WHERE employee_id = ?")->execute([$employeeId]);
    $ins = $pdo->prepare("INSERT IGNORE INTO employee_store_groups (employee_id, group_key) VALUES (?, ?)");
    foreach ($groupKeys as $g) {
        if (in_array($g, $valid, true)) $ins->execute([$employeeId, $g]);
    }
}

/** All store-group keys assigned to one employee, e.g. ['tmph','tm4u']. */
function employee_store_groups(PDO $pdo, int $employeeId): array
{
    if (!ensure_store_groups_table($pdo)) return [];
    $stmt = $pdo->prepare("SELECT group_key FROM employee_store_groups WHERE employee_id = ?");
    $stmt->execute([$employeeId]);
    return $stmt->fetchAll(PDO::FETCH_COLUMN);
}

/**
 * Appends a "belongs to this store group" filter to a query already joining
 * the employees table as `e`. Returns [sql_fragment, params] to splice in;
 * sql_fragment is '' (no filter) when $groupKey is empty/invalid.
 */
function store_group_filter_sql(PDO $pdo, ?string $groupKey): array
{
    $valid = array_keys(store_group_options());
    if (!$groupKey || !in_array($groupKey, $valid, true)) return ['', []];
    if (!ensure_store_groups_table($pdo)) return ['', []];
    return [
        " AND EXISTS (SELECT 1 FROM employee_store_groups esg WHERE esg.employee_id = e.employee_id AND esg.group_key = ?)",
        [$groupKey],
    ];
}

/** attendance.edited_by — set when Admin/HR types the times by hand. */
function ensure_attendance_edited_column(PDO $pdo): bool
{
    static $has = null;
    if ($has !== null) return $has;
    $flag = sys_get_temp_dir() . '/hrms_att_edited_ok';
    if (is_file($flag)) return $has = true;
    try {
        $col = $pdo->query("SHOW COLUMNS FROM attendance LIKE 'edited_by'")->fetch();
        if (!$col) $pdo->exec("ALTER TABLE attendance ADD COLUMN edited_by VARCHAR(100) NULL DEFAULT NULL");
        @file_put_contents($flag, '1');
        return $has = true;
    } catch (PDOException $e) {
        return $has = false;
    }
}

/** Day marks (WFH / Leave / Half leave / Holiday / Week off) — the same table the salary calculation reads. */
function ensure_day_marks_table(PDO $pdo): bool
{
    static $ok = null;
    if ($ok !== null) return $ok;
    $flag = sys_get_temp_dir() . '/hrms_day_marks_ok';
    if (is_file($flag)) return $ok = true;
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS day_marks (
            mark_id INT AUTO_INCREMENT PRIMARY KEY,
            mark_date DATE NOT NULL,
            employee_id INT NOT NULL,
            mark VARCHAR(20) NOT NULL,
            UNIQUE KEY uq_day_mark (mark_date, employee_id)
        )");
        @file_put_contents($flag, '1');
        return $ok = true;
    } catch (PDOException $e) { return $ok = false; }
}
/** employee_id => mark for every employee marked on a date range ("date|id" keys when $to differs from $from). */
function day_marks_between(PDO $pdo, string $from, string $to, int $empId = 0): array
{
    $out = [];
    if (!ensure_day_marks_table($pdo)) return $out;
    try {
        $st = $pdo->prepare("SELECT mark_date, employee_id, mark FROM day_marks WHERE mark_date BETWEEN ? AND ?" . ($empId ? " AND employee_id = ?" : ""));
        $st->execute($empId ? [$from, $to, $empId] : [$from, $to]);
        foreach ($st->fetchAll() as $r) $out[(string)$r['mark_date'] . '|' . (int)$r['employee_id']] = (string)$r['mark'];
    } catch (PDOException $e) {}
    return $out;
}

/**
 * The employee's unfinished shift, if any: punched in within the last 20
 * hours and not punched out yet. Shifts run past midnight (2 PM -> 1 AM), so
 * "today's row" alone would tell a 1 AM punch-out that they never punched in.
 * An older forgotten punch-out doesn't block the next day (HR fixes it by hand).
 */
/**
 * ---------------- Office locations (geo-fenced punch) ----------------
 * offices: every place punching is allowed (centre + radius). Any employee
 * may punch from ANY active office — the nearest one is the one checked.
 * punch_attempts logs every punch try with its distance so refused ones
 * can be reviewed on the Attendance page.
 */
function ensure_offices_tables(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_offices_ok';
    if (is_file($flag)) return $done = true;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS offices (
                office_id INT AUTO_INCREMENT PRIMARY KEY,
                office_name VARCHAR(120) NOT NULL,
                address VARCHAR(255) NULL,
                lat DECIMAL(10,7) NOT NULL,
                lng DECIMAL(10,7) NOT NULL,
                radius_m INT NOT NULL DEFAULT 100,
                is_active TINYINT(1) NOT NULL DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )"
        );
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS punch_attempts (
                attempt_id INT AUTO_INCREMENT PRIMARY KEY,
                employee_id INT NOT NULL,
                punch_type VARCHAR(3) NOT NULL,
                office_id INT NULL,
                distance_m INT NULL,
                lat DECIMAL(10,7) NULL,
                lng DECIMAL(10,7) NULL,
                accuracy_m INT NULL,
                result VARCHAR(10) NOT NULL,
                reason VARCHAR(255) NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )"
        );
        foreach ([
            "ALTER TABLE attendance ADD COLUMN in_office_id INT NULL",
            "ALTER TABLE attendance ADD COLUMN in_distance_m INT NULL",
            "ALTER TABLE attendance ADD COLUMN out_office_id INT NULL",
            "ALTER TABLE attendance ADD COLUMN out_distance_m INT NULL",
        ] as $sql) {
            try { $pdo->exec($sql); } catch (PDOException $e) { /* already there */ }
        }
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

/** Distance in metres between two GPS points (haversine). */
function geo_distance_m(float $lat1, float $lng1, float $lat2, float $lng2): float
{
    $r = 6371000.0;
    $dLat = deg2rad($lat2 - $lat1); $dLng = deg2rad($lng2 - $lng1);
    $a = sin($dLat / 2) ** 2 + cos(deg2rad($lat1)) * cos(deg2rad($lat2)) * sin($dLng / 2) ** 2;
    return 2 * $r * asin(min(1.0, sqrt($a)));
}

/** All active office locations. */
function active_offices(PDO $pdo): array
{
    if (!ensure_offices_tables($pdo)) return [];
    try { return $pdo->query("SELECT * FROM offices WHERE is_active = 1 ORDER BY office_name")->fetchAll(); }
    catch (PDOException $e) { return []; }
}

/**
 * Decide whether a punch from (lat,lng) is inside ANY active office; the
 * nearest office is the one reported. GPS is never exact: the reported
 * accuracy (up to 30 m of it) is added to the allowed radius so someone
 * standing at the door isn't refused by a 20 m wobble.
 * Returns [ok, nearest office|null, distance|null, reason].
 */
function geo_check_punch(PDO $pdo, int $empId, ?float $lat, ?float $lng, ?float $acc): array
{
    $offices = active_offices($pdo);
    if (!$offices) return [false, null, null, 'No office location has been added yet — ask Admin to add one on the Office Locations page.'];
    if ($lat === null || $lng === null) return [false, null, null, 'Location not received — allow location access for this site and try again.'];
    $best = null; $bestDist = null; $tol = min(30, max(0, (int)round($acc ?? 0)));
    foreach ($offices as $o) {
        $d = geo_distance_m($lat, $lng, (float)$o['lat'], (float)$o['lng']);
        if ($d <= (int)$o['radius_m'] + $tol) return [true, $o, $d, ''];          // inside this one
        if ($bestDist === null || $d < $bestDist) { $best = $o; $bestDist = $d; }
    }
    $far = $bestDist >= 1000 ? round($bestDist / 1000, 1) . ' km' : round($bestDist) . ' m';
    return [false, $best, $bestDist, 'You are ' . $far . ' from ' . $best['office_name'] . ' (nearest office) — you must be within ' . (int)$best['radius_m'] . ' m of an office to punch.'];
}

function log_punch_attempt(PDO $pdo, int $empId, string $type, ?array $office, ?float $dist, ?float $lat, ?float $lng, ?float $acc, bool $ok, string $reason): void
{
    try {
        $pdo->prepare("INSERT INTO punch_attempts (employee_id, punch_type, office_id, distance_m, lat, lng, accuracy_m, result, reason) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
            ->execute([$empId, $type, $office['office_id'] ?? null, $dist === null ? null : (int)round($dist), $lat, $lng, $acc === null ? null : (int)round($acc), $ok ? 'ok' : 'refused', $ok ? null : mb_substr($reason, 0, 255)]);
    } catch (PDOException $e) {}
}

function attendance_open_row(PDO $pdo, int $empId): ?array
{
    $st = $pdo->prepare(
        "SELECT * FROM attendance WHERE employee_id = ? AND punch_in IS NOT NULL AND punch_out IS NULL
           AND punch_in >= ? ORDER BY punch_in DESC LIMIT 1"
    );
    $st->execute([$empId, date('Y-m-d H:i:s', time() - 20 * 3600)]);
    return $st->fetch() ?: null;
}

/**
 * Delete punch photos older than 48 hours (files + DB references).
 * The attendance record itself (times, verified status) is kept forever.
 */
function attendance_cleanup_photos(PDO $pdo): void
{
    proof_cleanup_old($pdo);
    // Old photos only need clearing now and then; the Attendance page polls every 15 s.
    $stamp = sys_get_temp_dir() . '/hrms_att_photo_cleanup';
    if (is_file($stamp) && time() - (int)@filemtime($stamp) < 600) return;
    @touch($stamp);
    $cutoffIn = date('Y-m-d H:i:s', time() - 48 * 3600);
    $stmt = $pdo->prepare(
        "SELECT attendance_id, punch_in, punch_out, punch_in_photo, punch_out_photo
         FROM attendance
         WHERE (punch_in_photo IS NOT NULL AND punch_in < ?)
            OR (punch_out_photo IS NOT NULL AND punch_out < ?)"
    );
    $stmt->execute([$cutoffIn, $cutoffIn]);
    foreach ($stmt->fetchAll() as $r) {
        $sets = [];
        if ($r['punch_in_photo'] && $r['punch_in'] < $cutoffIn) {
            if (file_exists(__DIR__ . '/' . $r['punch_in_photo'])) @unlink(__DIR__ . '/' . $r['punch_in_photo']);
            $sets[] = "punch_in_photo = NULL";
        }
        if ($r['punch_out_photo'] && $r['punch_out'] && $r['punch_out'] < $cutoffIn) {
            if (file_exists(__DIR__ . '/' . $r['punch_out_photo'])) @unlink(__DIR__ . '/' . $r['punch_out_photo']);
            $sets[] = "punch_out_photo = NULL";
        }
        if ($sets) {
            $pdo->exec("UPDATE attendance SET " . implode(', ', $sets) . " WHERE attendance_id = " . (int)$r['attendance_id']);
        }
    }
}

/**
 * Map of lowercase sales tag -> employee, for attributing Shopify orders.
 */
function sales_tag_map(PDO $pdo): array
{
    $map = [];
    $q = $pdo->query("SELECT employee_id, full_name, sales_tag FROM employees WHERE status != 'ex' AND sales_tag IS NOT NULL AND sales_tag != ''");
    foreach ($q->fetchAll() as $e) {
        $map[mb_strtolower(trim($e['sales_tag']))] = ['id' => (int)$e['employee_id'], 'name' => $e['full_name']];
    }
    return $map;
}

function match_salesman(array $map, string $tags): ?array
{
    foreach (explode(',', $tags) as $t) {
        $t = mb_strtolower(trim($t));
        if ($t !== '' && isset($map[$t])) return $map[$t];
    }
    return null;
}

/**
 * ---------------- Local order cache ----------------
 * Orders are mirrored into the shop_orders table so pages read instantly
 * from MySQL. Shopify is only queried for fresh/missing ranges.
 */
function orders_upsert(PDO $pdo, string $storeKey, array $orders): int
{
    if (!$orders) return 0;
    $stmt = $pdo->prepare(
        "INSERT INTO shop_orders
            (shopify_id, store_key, order_name, created_at, customer, phone, items, total,
             currency, financial_status, fulfillment_status, tags, ml_total, ml10, dti, colors, outstanding, xparts, pay_ref, synced_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
         ON DUPLICATE KEY UPDATE
            order_name = VALUES(order_name), created_at = VALUES(created_at),
            customer = VALUES(customer), phone = VALUES(phone), items = VALUES(items),
            total = VALUES(total), currency = VALUES(currency),
            financial_status = VALUES(financial_status),
            fulfillment_status = VALUES(fulfillment_status),
            tags = VALUES(tags), ml_total = COALESCE(VALUES(ml_total), ml_total), ml10 = COALESCE(VALUES(ml10), ml10), dti = COALESCE(VALUES(dti), dti), colors = COALESCE(VALUES(colors), colors), outstanding = COALESCE(VALUES(outstanding), outstanding), xparts = COALESCE(VALUES(xparts), xparts), pay_ref = IF(VALUES(pay_ref) = '' AND pay_ref IS NOT NULL AND pay_ref <> '', pay_ref, COALESCE(VALUES(pay_ref), pay_ref)), synced_at = NOW()"
    );
    $n = 0;
    foreach ($orders as $o) {
        $created = date('Y-m-d H:i:s', strtotime($o['created_at']));
        $stmt->execute([
            $o['id'], $storeKey, $o['order_name'], $created,
            $o['customer'] ?? '', $o['phone'] ?? '', (int)($o['items'] ?? 0),
            (float)$o['total'], $o['currency'] ?? 'INR',
            $o['financial_status'] ?? '', $o['fulfillment_status'] ?? 'unfulfilled',
            (string)($o['tags'] ?? ''),
            isset($o['ml']) ? (int)$o['ml'] : null, isset($o['ml10']) ? (int)$o['ml10'] : null,
            array_key_exists('dti', $o) && $o['dti'] !== null ? ($o['dti'] ? json_encode($o['dti'], JSON_UNESCAPED_UNICODE) : '') : null,
            is_array($o['colors'] ?? null) ? json_encode(['dg' => (int)$o['colors']['dg'], 'lg' => (int)$o['colors']['lg'], 'wh' => (int)$o['colors']['wh'], 'other' => (int)$o['colors']['other']]) : null,
            isset($o['outstanding']) && $o['outstanding'] !== null ? round((float)$o['outstanding'], 2) : null,
            array_key_exists('xparts', $o) && $o['xparts'] !== null ? json_encode($o['xparts'], JSON_UNESCAPED_UNICODE) : null,
            isset($o['pay_ref']) ? mb_substr((string)$o['pay_ref'], 0, 200) : null,
        ]);
        $n++;
        try { order_auto_alloc($pdo, $storeKey, $o); } catch (Throwable $e) { }   // 🤖 a new order is allocated to the chat's salesperson at once
    }
    return $n;
}

/**
 * Fetch a date range from Shopify (all stores in parallel) and upsert into
 * the cache. Returns number of orders synced; store errors appended to $errors.
 */
/** 🤖 AUTO-ALLOCATION of ONE order — runs by itself the moment an order reaches HRMS (Shopify webhook / order sync → orders_upsert), when the Allocation
 *  page loads, and every few minutes from the WhatsApp engine (wa_auto_alloc), so nobody ever has to press anything.
 *  The order goes to the salesperson who holds the customer's WhatsApp chat (order mobile or the extra mobile), when the customer wrote to us in the
 *  7 days before the order. Type: chat source campaign / community → Campaign, everything else → Query. Panel: TM Perfume House for its own store.
 *  Left PENDING (with the reason, shown on the Allocation page): no mobile, no chat, chat not given to a salesperson, last message too old, ₹0 order,
 *  older than 2 days. Never touches an order a person allocated, nor one the robot did once (a person's Undo / change is never redone).
 *  Returns ['emp','type','house','by','at'] when it allocated, the reason (string) when it left it, '' when there was nothing to do. */
/** 📢 Query or Campaign for an order of this WhatsApp chat (one rule for the automatic allocation and the Manual order): the chat came on the
 *  campaign number, is marked Campaign / Community, or our campaign was sent to the customer in the 7 days before the order. $c = the wa_contacts row (+ camp_tag). */
function order_chat_type(PDO $pdo, array $c, int $t = 0): string
{
    return ((int)($c['camp_tag'] ?? 0) === 1 || in_array((string)($c['source'] ?? ''), ['campaign', 'community'], true) || (function_exists('wa_got_campaign') && wa_got_campaign($pdo, (string)($c['phone'] ?? ''), date('Y-m-d H:i:s', $t ?: time()), 7))) ? 'campaign' : 'query';
}
function order_auto_alloc(PDO $pdo, string $sk, array $o)
{
    static $ready = null, $q = [];
    $oid = (string)($o['id'] ?? $o['shopify_id'] ?? ''); if ($oid === '' || $sk === '' || $sk === 'mysales' || strpos($sk, 'mysales') === 0) return '';
    $t = strtotime((string)($o['created_at'] ?? '')); if (!$t || $t < time() - 2 * 86400) return '';   // only new orders (the last 2 days)
    if ($ready === null) {
        $ready = false;
        try {
            if (!ensure_order_allocations_table($pdo)) return '';
            $pdo->exec("CREATE TABLE IF NOT EXISTS wa_auto_alloc_done (source VARCHAR(20) NOT NULL, order_id VARCHAR(40) NOT NULL, at DATETIME NOT NULL, PRIMARY KEY (source, order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
            $pdo->exec("CREATE TABLE IF NOT EXISTS wa_auto_alloc_why (source VARCHAR(20) NOT NULL, order_id VARCHAR(40) NOT NULL, why VARCHAR(160) NOT NULL DEFAULT '', at DATETIME NOT NULL, PRIMARY KEY (source, order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
            $q['has'] = $pdo->prepare("SELECT 1 FROM order_allocations WHERE source = ? AND order_id = ?");
            $q['done'] = $pdo->prepare("SELECT 1 FROM wa_auto_alloc_done WHERE source = ? AND order_id = ?");
            $q['mark'] = $pdo->prepare("INSERT IGNORE INTO wa_auto_alloc_done (source, order_id, at) VALUES (?, ?, ?)");
            $q['why'] = $pdo->prepare("INSERT INTO wa_auto_alloc_why (source, order_id, why, at) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE why = VALUES(why), at = VALUES(at)");
            $q['ins'] = $pdo->prepare("INSERT IGNORE INTO order_allocations (source, order_id, house, order_type, employee_id, is_direct, allocated_by) VALUES (?, ?, ?, ?, ?, 0, 'auto (WhatsApp)')");
            try { $q['c'] = $pdo->prepare("SELECT c.phone, c.assigned_emp, c.source, c.last_in_at, COALESCE(n.camp_tag, 0) AS camp_tag FROM wa_contacts c LEFT JOIN wa_numbers n ON n.id = c.last_number_id WHERE c.phone = ?"); }
            catch (Throwable $e) { $q['c'] = $pdo->prepare("SELECT phone, assigned_emp, source, last_in_at, 0 AS camp_tag FROM wa_contacts WHERE phone = ?"); }   // before the campaign-number column exists
            try { $q['ex'] = $pdo->prepare("SELECT phone FROM order_extra_phones WHERE source = ? AND order_id = ?"); } catch (Throwable $e) { $q['ex'] = null; }
            try { $q['cn'] = $pdo->prepare("SELECT 1 FROM wa_messages m JOIN wa_numbers n ON n.id = m.number_id WHERE m.phone = ? AND m.dir = 'in' AND n.camp_tag = 1 AND m.ts >= ? LIMIT 1"); } catch (Throwable $e) { $q['cn'] = null; }   // 📢 the customer wrote to the campaign number (any day in the last 60)
            $ready = true;
        } catch (Throwable $e) { return ''; }   // no WhatsApp tables on this install: nothing to do
    }
    if (!$ready) return '';
    $why = function (string $txt) use ($q, $sk, $oid) { try { $q['why']->execute([$sk, $oid, mb_substr($txt, 0, 160), date('Y-m-d H:i:s')]); } catch (Throwable $e) { } return $txt; };
    try {
        $q['has']->execute([$sk, $oid]); if ($q['has']->fetchColumn()) return '';      // a person allocated it
        $q['done']->execute([$sk, $oid]); if ($q['done']->fetchColumn()) return '';    // the robot did it once already
        if ((float)($o['total'] ?? 0) <= 0) return $why('₹0 order (replacement)');
        $key = function ($p) { $d = preg_replace('/\D+/', '', (string)$p) ?? ''; return strlen($d) > 10 ? substr($d, -10) : $d; };
        $phones = [$key($o['phone'] ?? '')];
        if ($q['ex']) { try { $q['ex']->execute([$sk, $oid]); $p2 = (string)$q['ex']->fetchColumn(); if ($p2 !== '') $phones[] = $key($p2); } catch (Throwable $e) { } }
        $phones = array_values(array_filter(array_unique($phones), fn($p) => strlen($p) === 10));
        if (!$phones) return $why('no mobile number on the order');
        $c = null; $seen = null;
        foreach ($phones as $ph) { $q['c']->execute([$ph]); $x = $q['c']->fetch(PDO::FETCH_ASSOC); if ($x) { $seen = $seen ?: $x; if ((int)$x['assigned_emp'] > 0) { $c = $x; break; } } }
        if (!$seen) return $why('no WhatsApp chat with this number');
        if (!$c) return $why('the WhatsApp chat is not given to any salesperson');
        if (empty($c['last_in_at'])) return $why('the customer never wrote to us on WhatsApp');
        $li = strtotime((string)$c['last_in_at']); if ($li < $t - 7 * 86400 && $li < time() - 7 * 86400) return $why('last WhatsApp message ' . date('j M', $li) . ' — older than 7 days');
        $house = $sk === 'tmperfumehouse' ? 'tmph' : order_house($sk, (string)($o['tags'] ?? '')); if ($house === '') return $why('panel not clear from the order');
        $type = order_chat_type($pdo, $c, $t);   // 📢 Campaign = a real campaign reply (chat marked Campaign / Community, or our campaign sent in the 7 days before the order); website / ad texts stay Query
        $emp = (int)$c['assigned_emp']; $q['ins']->execute([$sk, $oid, $house, $type, $emp]);
        if ($q['ins']->rowCount() < 1) return '';
        $now = date('Y-m-d H:i:s'); $q['mark']->execute([$sk, $oid, $now]);
        try { $pdo->prepare("DELETE FROM wa_auto_alloc_why WHERE source = ? AND order_id = ?")->execute([$sk, $oid]); } catch (Throwable $e) { }
        if (function_exists('wa_event')) { try { wa_event($pdo, (string)$c['phone'], '🧾 Order ' . ($o['order_name'] ?? '') . ' allocated to ' . (employee_names_by_id($pdo)[$emp] ?? 'the salesperson') . ' · ' . ucfirst($type) . ' (automatic)'); } catch (Throwable $e) { } }
        return ['emp' => $emp, 'type' => $type, 'house' => $house, 'by' => 'auto (WhatsApp)', 'at' => $now];
    } catch (Throwable $e) { return ''; }
}

function orders_sync_range(PDO $pdo, string $dateFrom, string $dateTo, int $rounds, array &$errors): int
{
    $stores = shopify_stores();
    $tokens = [];
    foreach ($stores as $key => $store) {
        if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
        $token = shopify_get_token($key, $store);
        if (is_array($token)) { $errors[] = $token['error']; unset($stores[$key]); continue; }
        $tokens[$key] = $token;
    }
    if (!$stores) return 0;

    $results = shopify_fetch_all($stores, $tokens, $dateFrom, $dateTo, $rounds, false, false);   // only what Shopify has (the manual WM- orders are already in shop_orders)
    $total = 0;
    foreach ($results as $key => $st) {
        if ($st['error']) { $errors[] = $st['error']; continue; }
        $total += orders_upsert($pdo, $key, $st['orders']);
    }
    return $total;
}

/**
 * Per-month "last real Shopify sync" timestamp for the Targets page, so the
 * 5-minute throttle is shared across every browser/admin instead of each
 * one keeping its own localStorage clock.
 */
function targets_sync_state_file(string $month): string
{
    return sys_get_temp_dir() . '/hrms_targets_sync_' . preg_replace('/[^0-9\-]/', '', $month) . '.txt';
}
function targets_sync_seconds_ago(string $month): ?int
{
    $f = targets_sync_state_file($month);
    if (!is_file($f)) return null;
    $last = (int)@file_get_contents($f);
    return $last > 0 ? max(0, time() - $last) : null;
}
function targets_sync_mark(string $month): void
{
    @file_put_contents(targets_sync_state_file($month), (string)time());
}

/**
 * Keep the cache fresh before reading a range:
 * - recent window (yesterday+today) re-synced at most every 3 minutes
 * - a requested range with no cached rows gets a one-time backfill
 */
/**
 * Business-day timing. A business day runs from its start time until the
 * next day's start time (default 10:00 every day). Admin/HR can set a
 * different start per weekday (e.g. Sunday 12:00, so Saturday runs
 * Sat 10:00 -> Sun 12:00). One rule used by every page and sync.
 */
function ensure_day_timing_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return;
    if (function_exists('schema_done') && schema_done($pdo, __FUNCTION__, __FILE__)) { $done = true; return; }   // set up once per upload
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS day_timing (weekday TINYINT PRIMARY KEY, start_time CHAR(5) NOT NULL DEFAULT '10:00')");
        if (function_exists('schema_mark')) schema_mark($pdo, __FUNCTION__, __FILE__);
    } catch (PDOException $e) { /* read falls back to 10:00 */ }
    $done = true;
}
/** [0 (Sun) .. 6 (Sat)] => 'HH:MM' */
function day_timing_get(PDO $pdo): array
{
    static $cache = null;
    if ($cache !== null) return $cache;
    $out = array_fill(0, 7, '10:00');
    ensure_day_timing_table($pdo);
    try {
        foreach ($pdo->query("SELECT weekday, start_time FROM day_timing")->fetchAll() as $r) {
            $wd = (int)$r['weekday'];
            if ($wd >= 0 && $wd <= 6 && preg_match('/^\d{2}:\d{2}$/', (string)$r['start_time'])) $out[$wd] = (string)$r['start_time'];
        }
    } catch (PDOException $e) {}
    return $cache = $out;
}
/** Start-of-day time for a calendar date, 'HH:MM'. */
function day_start_for(PDO $pdo, string $date): string
{
    return day_timing_get($pdo)[(int)date('w', strtotime($date))];
}
/** Business day a moment (local time, 'Y-m-d H:i:s' or a timestamp) belongs to. */
function biz_day_of(PDO $pdo, $when): string
{
    $ts = is_int($when) ? $when : strtotime((string)$when);
    $date = date('Y-m-d', $ts);
    if (date('H:i', $ts) < day_start_for($pdo, $date)) $date = date('Y-m-d', strtotime($date . ' -1 day'));
    return $date;
}

/** Minutes a time is before that day's start time (0 when it is at or after the start). */
function minutes_before_day_start(PDO $pdo, int $ts): int
{
    $date = date('Y-m-d', $ts);
    $start = strtotime($date . ' ' . day_start_for($pdo, $date) . ':00');
    return $ts < $start ? (int)round(($start - $ts) / 60) : 0;
}

/**
 * The attendance day a PUNCH IN belongs to.
 *
 * The business day runs from the Day timing start (default 10:00) to the same
 * time next morning, which is right for a punch OUT after midnight. But someone
 * who reaches the office EARLY — say 9:30 for a 10:00 start — is early for
 * today, not working yesterday's day. So a punch in up to
 * PUNCH_EARLY_WINDOW_MINUTES before the day start counts as today; anything
 * earlier than that is treated as a night shift that began the previous day.
 */
function punch_in_day(PDO $pdo, int $ts): string
{
    $early = minutes_before_day_start($pdo, $ts);
    if ($early > 0 && $early <= PUNCH_EARLY_WINDOW_MINUTES) return date('Y-m-d', $ts);
    return biz_day_of($pdo, $ts);
}
function biz_today(PDO $pdo): string
{
    return biz_day_of($pdo, time());
}
/**
 * The attendance day right now, using the same early-arrival rule as a punch
 * in — so an employee whose own shift starts before the Day timing start
 * (9:00 against a 10:00 day start) is counted on today, not yesterday.
 */
function attendance_day_now(PDO $pdo): string
{
    return punch_in_day($pdo, time());
}
/** [start datetime, end datetime] covering business days $dateFrom..$dateTo. */
function biz_window(PDO $pdo, string $dateFrom, string $dateTo): array
{
    $next = date('Y-m-d', strtotime($dateTo . ' +1 day'));
    $start = $dateFrom . ' ' . day_start_for($pdo, $dateFrom) . ':00';
    $end = date('Y-m-d H:i:s', strtotime($next . ' ' . day_start_for($pdo, $next) . ':00') - 1);
    return [$start, $end];
}

function orders_ensure_fresh(PDO $pdo, string $dateFrom, string $dateTo, array &$errors): void
{
    $bizToday = biz_today($pdo);

    // Recent freshness
    if ($dateTo >= $bizToday) {
        $stateFile = sys_get_temp_dir() . '/hrms_orders_last_sync.txt';
        $last = (int)@file_get_contents($stateFile);
        if (time() - $last > 180) {
            @file_put_contents($stateFile, (string)time());
            orders_sync_range($pdo, date('Y-m-d', strtotime($bizToday . ' -1 day')), $bizToday, 8, $errors);
        }
    }

    // Backfill: nothing cached in the requested window yet
    $chk = $pdo->prepare(
        "SELECT COUNT(*) FROM shop_orders WHERE created_at >= ? AND created_at <= ?"
    );
    $chk->execute(biz_window($pdo, $dateFrom, $dateTo));
    if ((int)$chk->fetchColumn() === 0 && $dateFrom < $bizToday) {
        orders_sync_range($pdo, $dateFrom, $dateTo, 40, $errors);
    }
}

/**
 * Orders older than yesterday are read from the local cache, so a COD order that was paid later would keep its old
 * status. Every 30 minutes the last ~10 days are re-synced from Shopify (after the answer has been sent when the
 * server allows it, so nobody waits for it).
 */
function orders_settle_due(): bool
{
    return time() - (int)@file_get_contents(sys_get_temp_dir() . '/hrms_orders_settle.txt') > 1800;
}
function orders_settle_old_days(PDO $pdo): void
{
    $stamp = sys_get_temp_dir() . '/hrms_orders_settle.txt';
    if (time() - (int)@file_get_contents($stamp) <= 1800) return;
    @file_put_contents($stamp, (string)time());
    $today = biz_today($pdo);
    $from = date('Y-m-d', strtotime($today . ' -10 day'));
    $to = date('Y-m-d', strtotime($today . ' -2 day'));
    $errs = [];
    try { orders_sync_range($pdo, $from, $to, 40, $errs); } catch (Throwable $e) { /* next time */ }
}

// ---------------- Shopify stores ----------------
// One entry per store. Apps created in the new Shopify Dev Dashboard don't
// expose a shpat_ token — instead we exchange the app's Client ID + Secret
// for an access token automatically (client credentials grant) and cache it.
function shopify_stores(): array
{
    // Credentials live in config.php (gitignored). Optional SHOPIFY_STORES override wins.
    if (defined('SHOPIFY_STORES') && is_array(SHOPIFY_STORES)) {
        return SHOPIFY_STORES;
    }
    return [
        'tmperfumehouse' => [
            'label'         => 'TM Perfume House',
            'domain'        => defined('SHOPIFY_DOMAIN') ? SHOPIFY_DOMAIN : 'tmfragrance.myshopify.com',
            'client_id'     => defined('SHOPIFY_CLIENT_ID') ? SHOPIFY_CLIENT_ID : '',
            'client_secret' => defined('SHOPIFY_CLIENT_SECRET') ? SHOPIFY_CLIENT_SECRET : '',
        ],
    ];
}

/**
 * Get an Admin API access token for a store via the client credentials
 * grant, caching it in the system temp dir until shortly before expiry.
 */
function shopify_get_token(string $key, array $store)
{
    $cacheFile = sys_get_temp_dir() . '/shopify_token_' . $key . '.json';
    if (is_file($cacheFile)) {
        $cached = json_decode((string)file_get_contents($cacheFile), true);
        if (is_array($cached) && !empty($cached['token']) && ($cached['expires'] ?? 0) > time() + 120) {
            return $cached['token'];
        }
    }

    $ch = curl_init("https://{$store['domain']}/admin/oauth/access_token");
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST => true,
        CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
        CURLOPT_POSTFIELDS => json_encode([
            'client_id' => $store['client_id'],
            'client_secret' => $store['client_secret'],
            'grant_type' => 'client_credentials',
        ]),
        CURLOPT_TIMEOUT => 20,
    ]);
    $resp = curl_exec($ch);
    $status = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($resp === false || $status !== 200) {
        return ['error' => $store['label'] . ': could not get access token (HTTP ' . $status . '). Check Client ID/Secret and that the app is installed on this store.'];
    }
    $data = json_decode($resp, true);
    if (empty($data['access_token'])) {
        return ['error' => $store['label'] . ': token response missing access_token.'];
    }

    $token = $data['access_token'];
    $ttl = isset($data['expires_in']) ? (int)$data['expires_in'] : 86000;
    @file_put_contents($cacheFile, json_encode(['token' => $token, 'expires' => time() + $ttl]));
    return $token;
}

// ---------------- Order codes ----------------
// Every order (Shopify stores + MySales) can carry ONE code of our own, e.g.
// AG00123. The code is stored here and, for Shopify orders, also written as
// a tag on the order.
function ensure_order_codes_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
