/** Days a request covers: a half day is 0.5, otherwise every calendar day from..to. */
function leave_days(string $type, string $from, string $to): float
{
    if ($type === 'half_leave') return 0.5;
    return (float)(((strtotime($to) - strtotime($from)) / 86400) + 1);
}

/** Free-leave units already used per month (YYYY-MM): leave / half-leave day marks plus the employee's pending requests. */
function leave_used_by_month(PDO $pdo, int $empId, string $fromDate): array
{
    $used = [];
    try {
        $st = $pdo->prepare("SELECT mark_date, mark FROM day_marks WHERE employee_id = ? AND mark_date >= ? AND mark IN ('leave','half_leave')");
        $st->execute([$empId, $fromDate]);
        foreach ($st->fetchAll() as $r) { $m = substr((string)$r['mark_date'], 0, 7); $used[$m] = ($used[$m] ?? 0) + ($r['mark'] === 'half_leave' ? 0.5 : 1); }
    } catch (PDOException $e) {}
    try {
        $st = $pdo->prepare("SELECT leave_type, date_from, date_to FROM leave_requests WHERE employee_id = ? AND status = 'pending' AND leave_type IN ('leave','half_leave') AND date_to >= ?");
        $st->execute([$empId, $fromDate]);
        foreach ($st->fetchAll() as $r) {
            if ($r['leave_type'] === 'half_leave') { $m = substr((string)$r['date_from'], 0, 7); $used[$m] = ($used[$m] ?? 0) + 0.5; continue; }
            for ($d = (string)$r['date_from']; $d <= (string)$r['date_to']; $d = date('Y-m-d', strtotime($d . ' +1 day'))) { $m = substr($d, 0, 7); $used[$m] = ($used[$m] ?? 0) + 1; }
        }
    } catch (PDOException $e) {}
    return $used;
}

