/**
 * Read orders straight from the MySales panel database (u897577217_sales),
 * which lives on the same Hostinger account. Requires the HRMS DB user to be
 * assigned to that database in hPanel -> Databases.
 */
function sales_db(): ?PDO
{
    static $pdo = null;
    static $failed = false;
    if ($pdo !== null || $failed) return $pdo;
    // The panel database sometimes refuses a connection for a moment (Hostinger's per-user connection limit when many pages load
    // at once, or a short restart): try up to 4 times before giving up, instead of failing the whole page on the first refusal.
    $last = '';
    // Credentials: put SALES_DB_USER / SALES_DB_PASS in config.php (see Q_K_wiring.md). The literals below are only a fallback so nothing breaks until you do; delete them afterwards.
    foreach ([0, 300000, 800000, 1500000] as $wait) {
        if ($wait) usleep($wait);
        try {
            $pdo = new PDO(
                "mysql:host=" . DB_HOST . ";dbname=u897577217_sales;charset=utf8mb4",
                defined('SALES_DB_USER') ? SALES_DB_USER : 'u897577217_sales',
                defined('SALES_DB_PASS') ? SALES_DB_PASS : 'Agevole@409',
                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC, PDO::ATTR_TIMEOUT => 8]
            );
            $pdo->exec("SET time_zone = '+05:30'");
            return $pdo;
        } catch (PDOException $e) {
            $pdo = null;
            $last = $e->getMessage();
            // wrong user / password / no access: retrying will not help
            if (preg_match('/1044|1045|1049|Access denied|Unknown database/i', $last)) break;
        }
    }
    $failed = true;
    $GLOBALS['sales_db_error'] = $last;
    error_log('sales_db: ' . $last);
    return null;
}
/** Plain-words reason the MySales database could not be opened. */
function sales_db_problem(string $label): string
{
    $e = (string)($GLOBALS['sales_db_error'] ?? '');
    if (preg_match('/1044|1045|Access denied/i', $e)) return $label . ': cannot open the sales database — access denied (in hPanel > Databases, check the u897577217_sales user and password).';
    if (preg_match('/1049|Unknown database/i', $e)) return $label . ': the sales database u897577217_sales was not found.';
    if (preg_match('/1040|1203|Too many connections|max_user_connections/i', $e)) return $label . ': the sales database is busy right now (too many connections) — the page will load it on the next refresh.';
    return $label . ': the sales database did not answer right now' . ($e !== '' ? ' (' . mb_substr($e, 0, 90) . ')' : '') . ' — refresh in a moment.';
}

function fetch_custom_store(array $cs, string $dateFrom, string $dateTo): array
{
    $db = sales_db();
    if (!$db) {
        return ['error' => sales_db_problem($cs['label'])];
    }

    $table = $cs['table'];
    $nm = sales_order_name_sql($db, $table);         // the customer's name stored with the order (as on the panel's invoice)
    try {
        // Salesman comes from the broadcast the order was created under:
        //   order.broadcastId -> contactnumber.userId -> salesman.name
        // A broadcast shared by more than one user can't identify who made
        // the sale, so those are deliberately left unattributed rather than
        // credited to whichever row the database happened to return first.
        $stmt = $db->prepare(
            "SELECT o.id, o.customerNumber, o.`date`, o.`time`, o.prepaid, o.COD,
                    COALESCE(NULLIF(o.totalAmount, 0), o.finalPrice) AS amount,
                    o.overall_quantity, o.isRTO, o.delivered, o.in_transit,
                    o.broadcastId,
                    b.name AS broadcast_name,
                    CASE WHEN cn.user_count = 1 THEN s.name ELSE NULL END AS salesman_name,
                    cn.user_count, {$nm['select']}
             FROM `$table` o
             LEFT JOIN broadcast b ON b.id = o.broadcastId
             LEFT JOIN (
                 SELECT broadcastId, MIN(userId) AS userId, COUNT(DISTINCT userId) AS user_count
                 FROM contactnumber GROUP BY broadcastId
             ) cn ON cn.broadcastId = o.broadcastId
             LEFT JOIN salesman s ON s.id = cn.userId
             {$nm['join']}
             WHERE o.`date` BETWEEN ? AND ?
             ORDER BY o.`date` DESC, o.id DESC
             LIMIT 10000"
        );
        $stmt->execute([$dateFrom, $dateTo]);
    } catch (PDOException $e) {
        return ['error' => $cs['label'] . ': query failed on table ' . $table . ' — ' . $e->getMessage()];
    }

    $orders = [];
    foreach ($stmt->fetchAll() as $r) {
        // Combine date + stored time text; fall back to noon so day grouping
        // stays on the recorded date.
        $ts = strtotime(trim($r['date'] . ' ' . (string)$r['time']));
        if ($ts === false) $ts = strtotime($r['date'] . ' 12:00');

        $prepaid = (float)($r['prepaid'] ?? 0);
        $cod = (float)($r['COD'] ?? 0);
        if ($cod > 0 && $prepaid > 0) $payment = 'partially_paid';
        elseif ($cod > 0) $payment = 'cod';
        else $payment = 'paid';

        if ((int)($r['isRTO'] ?? 0) === 1) $fulfillment = 'RTO';
        elseif (!empty($r['delivered'])) $fulfillment = 'fulfilled';
        elseif (!empty($r['in_transit'])) $fulfillment = 'in transit';
        else $fulfillment = 'unfulfilled';

        $orders[] = [
            'id' => $r['id'],
            'order_name' => '#' . $r['id'],
            'biz_date' => $r['date'], // panel's recorded day is authoritative for grouping
            'created_at' => date('Y-m-d\TH:i:s', $ts) . '+05:30',
            'customer' => trim((string)($r['cust_name'] ?? '')) !== '' ? mb_substr(trim((string)$r['cust_name']), 0, 80) : 'Guest',
            'phone' => (string)($r['customerNumber'] ?? ''),
            'items' => (int)($r['overall_quantity'] ?? 1),
            'total' => (string)($r['amount'] ?? '0'),
            'currency' => 'INR',
            'financial_status' => $payment,
            'paid' => $payment === 'partially_paid' ? round($prepaid, 2) : null,
            'outstanding' => $payment === 'partially_paid' ? round($cod, 2) : null,
            'fulfillment_status' => $fulfillment,
            'broadcast' => $r['broadcast_name'] ?? '',
            'panel_salesman' => $r['salesman_name'] ?? '',
            'salesman_shared' => (int)($r['user_count'] ?? 0) > 1,
        ];
    }
    // The panel keeps only the customer's mobile number: find the real name by that number (instead of "Guest").
    // Orders whose own row has no name: find it by the mobile number (other panel tables, Shopify orders, Shopify customers).
    $noName = array_values(array_filter($orders, fn($o) => $o['customer'] === 'Guest'));
    $names = $noName ? customer_names_by_phone($db, $table, array_column($noName, 'phone')) : [];
    global $pdo;
    $miss = [];
    foreach ($noName as $o) { $k = phone_tail10($o['phone']); if ($k !== '' && empty($names[$k])) $miss[$k] = true; }
    if ($miss && $pdo instanceof PDO) $names += phone_names_from_shopify($pdo, array_keys($miss));
    foreach ($orders as &$o) { if ($o['customer'] !== 'Guest') continue; $k = phone_tail10($o['phone']); if ($k !== '' && !empty($names[$k])) $o['customer'] = $names[$k]; }
    unset($o);
    return ['orders' => $orders];
}

/** Column looks like a person's name (customer / client / buyer …), not a product, salesman, broadcast, file … name. */
function sales_col_is_name(string $c): bool
{
    if (!preg_match('/name/i', $c)) return (bool)preg_match('/^(customer|client|buyer|receiver|consignee)$/i', $c);
    return !preg_match('/broadcast|sales|seller|product|item|file|image|img|photo|brand|city|state|country|company|shop|store|panel|user_?name|admin|created|updated|courier|agent|staff|employee|category|variant|sku|perfume|bank|template|campaign|group|domain|host|db|table|column/i', $c);
}
/** Column holds a mobile number. */
function sales_col_is_phone(string $c): bool
{
    return (bool)preg_match('/mobile|phone|contact|whats_?app|number|^mob_?no$|^mob$/i', $c) && !preg_match('/order|invoice|bill|awb|track|gst|pin|account|alt|alternate|serial|batch|lot|ref|id$/i', $c);
}
/** How much a name column looks like the CUSTOMER's name (higher = better). */
function sales_name_rank(string $c): int
{
    if (preg_match('/cust|client|buyer|receiver|consignee|bill|ship/i', $c)) return 3;
    if (preg_match('/^(full_?name|name|fname|first_?name)$/i', $c)) return 2;
    return 1;
}
/**
 * The customer's name ON THE ORDER ITSELF, the way the panel's own invoice shows it ("Customer Details → Name"):
 * a name column on the order table, or the customer row the order points to (customerId → customer table).
 * Returns ['select' => SQL expression aliased cust_name, 'join' => extra JOIN, 'how' => text] — found once a day from the column names.
 */
function sales_order_name_sql(PDO $db, string $table): array
{
    $none = ['select' => "'' AS cust_name", 'join' => '', 'how' => 'no name column found on the order'];
    $flag = sys_get_temp_dir() . '/hrms_sales_ordername_' . md5($table) . '_v2.json';
    if (is_file($flag) && filemtime($flag) > time() - 86400) { $j = json_decode((string)@file_get_contents($flag), true); if (is_array($j)) return $j; }
    $res = $none;
    try {
        $cols = $db->query("SHOW COLUMNS FROM `" . str_replace('`', '', $table) . "`")->fetchAll(PDO::FETCH_COLUMN);
        $nameCols = array_values(array_filter($cols, 'sales_col_is_name'));
        usort($nameCols, fn($a, $b) => sales_name_rank($b) <=> sales_name_rank($a));
        if ($nameCols) {
            $parts = array_map(fn($c) => "NULLIF(TRIM(o.`$c`), '')", $nameCols);
            $res = ['select' => 'COALESCE(' . implode(', ', $parts) . ", '') AS cust_name", 'join' => '', 'how' => 'order columns: ' . implode(', ', $nameCols)];
        } else {
            // the order points to a customer / address row
            $fk = array_values(array_filter($cols, fn($c) => (bool)preg_match('/^(customer|cust|client|buyer|address|shipping|billing)_?id$/i', $c)));
            if ($fk) {
                $fkBase = strtolower(preg_replace('/_?id$/i', '', $fk[0]));            // customerId -> customer, addressId -> address
                $cand = array_values(array_filter($db->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN), fn($t) => preg_match('/customer|client|buyer|address|shipping|billing/i', $t) && !preg_match('/contactnumber|broadcast/i', $t)));
                usort($cand, fn($a, $b) => (stripos($b, $fkBase) !== false) <=> (stripos($a, $fkBase) !== false));   // the table named like the column first
                foreach ($cand as $t) {
                    $tc = $db->query("SHOW COLUMNS FROM `" . str_replace('`', '', $t) . "`")->fetchAll(PDO::FETCH_COLUMN);
                    $nc = array_values(array_filter($tc, 'sales_col_is_name'));
                    if (!$nc || !in_array('id', array_map('strtolower', $tc), true)) continue;
                    usort($nc, fn($a, $b) => sales_name_rank($b) <=> sales_name_rank($a));
                    $res = ['select' => "COALESCE(NULLIF(TRIM(cu.`{$nc[0]}`), ''), '') AS cust_name", 'join' => "LEFT JOIN `$t` cu ON cu.id = o.`{$fk[0]}`", 'how' => "o.{$fk[0]} → $t.{$nc[0]}"];
                    break;
                }
            }
        }
    } catch (PDOException $e) { $res = $none; }
    @file_put_contents($flag, json_encode($res));
    return $res;
}

/** Last 10 digits of a mobile number ('' when shorter). */
function phone_tail10(string $p): string
{
    $d = preg_replace('/\D+/', '', $p);
    return strlen($d) >= 10 ? substr($d, -10) : '';
}

/**
 * Customer name for each mobile number asked for (last 10 digits => name). Only the numbers on the page are looked up —
 * never a whole table — so a page load stays light even with lakhs of customers:
 *   1. MySales tables that keep a name next to a mobile number (the `user` customer table — firstName + lastName — wins,
 *      then order tables, customer / address tables, other tables, broadcast contact lists last),
 *   2. the newest Shopify order with the same number (shop_orders), counter / WhatsApp orders (manual_orders) and names
 *      found earlier on Shopify customers (phone_name_lookup) fill numbers still without a name.
 * Answers (also "no name") are kept 6 hours in one small file, so the same numbers are not asked again on the next load.
 */
function customer_names_by_phone(?PDO $sdb, string $table, array $phones): array
{
    $want = [];
    foreach ($phones as $p) { $k = phone_tail10((string)$p); if ($k !== '') $want[$k] = true; }
    if (!$want) return [];
    $file = sys_get_temp_dir() . '/hrms_phone_names_v4.json';
    $now = time(); $ttl = 6 * 3600;
    $cache = is_file($file) ? (json_decode((string)@file_get_contents($file), true) ?: []) : [];
    $out = []; $todo = [];
    foreach (array_keys($want) as $k) {
        $c = $cache[$k] ?? null;
        if (is_array($c) && ($now - (int)($c[1] ?? 0)) < $ttl) { if ((string)$c[0] !== '') $out[$k] = (string)$c[0]; }
        else $todo[] = (string)$k;
    }
    if (!$todo) return $out;

    $t0 = microtime(true);
    $map = [];
    $put = function (string $phone, string $name, bool $override) use (&$map): void {
        $k = phone_tail10($phone); $name = trim(preg_replace('/\s+/', ' ', $name));
        $name = preg_replace('/^[A-Za-z]{1,3}\d{2,}\s+(?=\S)/', '', $name);                                     // "P2146 Vidit" -> "Vidit"
        if ($k === '' || $name === '' || preg_match('/^(guest|na|n\/a|null|-|0)$/i', $name) || ctype_digit(str_replace(' ', '', $name))) return;
        if (preg_match('/\d/', $name) && !preg_match('/\s/', $name)) return;                                      // a code like "A2888" is not a name
        if ($override || !isset($map[$k])) $map[$k] = mb_substr($name, 0, 80);
    };
    $chunks = array_chunk($todo, 400);
    $variants = function (array $ch): array { $v = []; foreach ($ch as $t) { $v[] = $t; $v[] = '91' . $t; $v[] = '+91' . $t; $v[] = '0' . $t; $v[] = '+91 ' . $t; } return $v; };

    if ($sdb) {
        foreach (sales_name_sources($sdb) as [$pri, $t, $n, $p]) {
            foreach ($chunks as $ch) {
                if (microtime(true) - $t0 > 12) break 2;
                $v = $variants($ch);
                try {
                    $st = $sdb->prepare("SELECT `$p`, $n AS nm FROM `$t` WHERE `$p` IN (" . implode(',', array_fill(0, count($v), '?')) . ")");
                    $st->execute($v);
                    while ($r = $st->fetch(PDO::FETCH_NUM)) $put((string)$r[0], (string)$r[1], true);
                } catch (PDOException $e) { break; }
            }
        }
    }
    global $pdo;
    if ($pdo instanceof PDO) {
        $tail = "RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(%s,' ',''),'-',''),'+',''),'(',''),10)";
        foreach ($chunks as $ch) {
            if (microtime(true) - $t0 > 16) break;
            $in = implode(',', array_fill(0, count($ch), '?'));
            if (ensure_shop_orders_table($pdo)) {
                try { $st = $pdo->prepare("SELECT phone, customer FROM shop_orders WHERE customer <> '' AND customer <> 'Guest' AND phone <> '' AND " . sprintf($tail, 'phone') . " IN ($in) ORDER BY created_at DESC"); $st->execute($ch); while ($r = $st->fetch(PDO::FETCH_NUM)) $put((string)$r[0], (string)$r[1], false); } catch (PDOException $e) {}
            }
            try { $st = $pdo->prepare("SELECT phone, customer_name FROM manual_orders WHERE customer_name <> '' AND " . sprintf($tail, 'phone') . " IN ($in) ORDER BY order_date DESC"); $st->execute($ch); while ($r = $st->fetch(PDO::FETCH_NUM)) $put((string)$r[0], (string)$r[1], false); } catch (PDOException $e) {}
            if (ensure_phone_lookup_table($pdo)) { try { $st = $pdo->prepare("SELECT phone10, name FROM phone_name_lookup WHERE name <> '' AND phone10 IN ($in)"); $st->execute($ch); while ($r = $st->fetch(PDO::FETCH_NUM)) $put((string)$r[0], (string)$r[1], false); } catch (PDOException $e) {} }
        }
    }
    $done = microtime(true) - $t0 <= 16;          // ran out of time: keep only the names found, ask the rest again next load
    $fresh = [];
    foreach ($todo as $k) { if (isset($map[$k])) { $out[$k] = $map[$k]; $fresh[$k] = [$map[$k], $now]; } elseif ($done) $fresh[$k] = ['', $now]; }
    if ($fresh) {
        $fh = @fopen($file, 'c+');
        if ($fh && flock($fh, LOCK_EX)) {
            $cur = json_decode((string)stream_get_contents($fh), true) ?: [];
            foreach ($cur as $k => $c) if (!is_array($c) || ($now - (int)($c[1] ?? 0)) >= $ttl) unset($cur[$k]);
            $cur = $fresh + $cur;
            ftruncate($fh, 0); rewind($fh); fwrite($fh, json_encode($cur, JSON_UNESCAPED_UNICODE)); fflush($fh); flock($fh, LOCK_UN);
        }
        if ($fh) fclose($fh);
    }
    return $out;
}

/** MySales tables that keep a customer name next to a mobile number, weakest first (the best source is read last and wins). Found once a day. */
function sales_name_sources(PDO $sdb): array
{
    static $mem = null;
    if ($mem !== null) return $mem;
    $file = sys_get_temp_dir() . '/hrms_sales_namesrc_v1.json';
    if (is_file($file) && filemtime($file) > time() - 86400) { $j = json_decode((string)@file_get_contents($file), true); if (is_array($j)) { $GLOBALS['sales_name_sources'] = array_map(fn($f) => $f[1] . '.' . $f[4] . ' (by ' . $f[3] . ')', $j); return $mem = $j; } }
    $found = [];
    try {
        foreach ($sdb->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN) as $t) {
            if (preg_match('/salesman|admin|staff|employee|log|session|setting|migration|password|token/i', $t)) continue;
            $cols = $sdb->query("SHOW COLUMNS FROM `" . str_replace('`', '', $t) . "`")->fetchAll(PDO::FETCH_COLUMN);
            $nc = array_values(array_filter($cols, 'sales_col_is_name')); $pc = array_values(array_filter($cols, 'sales_col_is_phone'));
            if (!$nc || !$pc) continue;
            usort($nc, fn($a, $b) => sales_name_rank($b) <=> sales_name_rank($a));
            // the panel's customer table (`user`: firstName + lastName + mobileNumber) is what its invoice prints, so it wins over everything
            $pri = preg_match('/^users?$/i', $t) ? -1 : (preg_match('/^order/i', $t) ? 0 : (preg_match('/customer|client|buyer|address|shipping|billing|invoice/i', $t) ? 1 : (preg_match('/contact|broadcast/i', $t) ? 3 : 2)));
            $first = current(array_filter($cols, fn($c) => (bool)preg_match('/^(first_?name|fname)$/i', $c)));
            $last  = current(array_filter($cols, fn($c) => (bool)preg_match('/^(last_?name|lname|sur_?name)$/i', $c)));
            $expr = ($first && $last) ? "CONCAT_WS(' ', NULLIF(TRIM(`$first`), ''), NULLIF(TRIM(`$last`), ''))" : "`{$nc[0]}`";
            $found[] = [$pri, $t, $expr, $pc[0], ($first && $last) ? "$first + $last" : $nc[0]];
        }
    } catch (PDOException $e) { return $mem = []; }
    usort($found, fn($a, $b) => $b[0] <=> $a[0]);
    @file_put_contents($file, json_encode($found));
    $GLOBALS['sales_name_sources'] = array_map(fn($f) => $f[1] . '.' . $f[4] . ' (by ' . $f[3] . ')', $found);
    return $mem = $found;
}
function ensure_phone_lookup_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) { $done = true; return $done; }
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS phone_name_lookup (phone10 CHAR(10) NOT NULL PRIMARY KEY, name VARCHAR(80) NOT NULL DEFAULT '', source VARCHAR(30) NOT NULL DEFAULT '', checked_at DATETIME NOT NULL)");
        if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['phone_name_lookup']); return $done = true;
    } catch (PDOException $e) { return $done = false; }
}
/**
 * Numbers still without a name: ask the Shopify stores' customer list (a customer who never ordered on a store that sends us
 * webhooks, or ordered before the order copy started). A few numbers per page load, each number asked at most once a week;
 * the answer (or "not found") is kept in phone_name_lookup. Needs the app's read_customers access — without it this stays quiet.
 */
function phone_names_from_shopify(PDO $pdo, array $tails, int $max = 12, float $budget = 6.0): array
{
    $found = [];
    if (!$tails || !ensure_phone_lookup_table($pdo)) return $found;
    $flagNoScope = sys_get_temp_dir() . '/hrms_no_customer_scope';
    if (is_file($flagNoScope) && filemtime($flagNoScope) > time() - 86400) return $found;
    $in = implode(',', array_fill(0, count($tails), '?'));
    $seen = [];
    try { $q = $pdo->prepare("SELECT phone10 FROM phone_name_lookup WHERE phone10 IN ($in) AND checked_at > ?"); $q->execute(array_merge($tails, [date('Y-m-d H:i:s', time() - 7 * 86400)])); $seen = array_flip($q->fetchAll(PDO::FETCH_COLUMN)); } catch (PDOException $e) {}
    $todo = array_slice(array_values(array_filter($tails, fn($t) => !isset($seen[$t]))), 0, $max);
    if (!$todo) return $found;
    $stores = [];
    foreach (shopify_stores() as $k => $st) { if (strpos($st['client_id'], 'PASTE_') !== false) continue; $tok = shopify_get_token($k, $st); if (!is_array($tok)) $stores[$k] = [$st, $tok]; }
    if (!$stores) return $found;
    $t0 = microtime(true);
    $save = $pdo->prepare("INSERT INTO phone_name_lookup (phone10, name, source, checked_at) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE name = VALUES(name), source = VALUES(source), checked_at = VALUES(checked_at)");
    foreach ($todo as $t) {
        if (microtime(true) - $t0 > $budget) break;
        $name = ''; $src = '';
        foreach ($stores as $k => [$st, $tok]) {
            $url = "https://{$st['domain']}/admin/api/2024-10/customers/search.json?" . http_build_query(['query' => 'phone:+91' . $t, 'fields' => 'first_name,last_name,phone', 'limit' => 1]);
            $ch = curl_init($url);
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => ['X-Shopify-Access-Token: ' . $tok], CURLOPT_TIMEOUT => 6, CURLOPT_CONNECTTIMEOUT => 4]);
            $resp = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
            if ($code === 403 || $code === 401) { @touch($flagNoScope); return $found; }       // the app may not read customers: stop asking for a day
            if ($code !== 200) continue;
            $c = (json_decode((string)$resp, true)['customers'][0] ?? null);
            $nm = $c ? trim(((string)($c['first_name'] ?? '')) . ' ' . ((string)($c['last_name'] ?? ''))) : '';
            if ($nm !== '' && !preg_match('/^(guest|na|null)$/i', $nm)) { $name = mb_substr($nm, 0, 80); $src = 'shopify:' . $k; break; }
        }
        try { $save->execute([$t, $name, $src, date('Y-m-d H:i:s')]); } catch (PDOException $e) {}
        if ($name !== '') $found[$t] = $name;
    }
    if ($found) { $f = sys_get_temp_dir() . '/hrms_phone_names_v4.json'; $c = is_file($f) ? (json_decode((string)@file_get_contents($f), true) ?: []) : []; foreach ($found as $k => $v) $c[$k] = [$v, time()]; @file_put_contents($f, json_encode($c, JSON_UNESCAPED_UNICODE), LOCK_EX); }
    return $found;
}

// ---------------- Order Allocation (MySales -> a house) ----------------
// A MySales / MySales 4P order can be moved to TM Perfume House
// or TM4U from the Order Allocation page. The panel's own
// database is never written; the choice lives here and every page that
// counts orders applies it: the order stops counting as MySales and counts
// under the chosen house, with the same employee, customer and amount.
function ensure_order_allocations_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_order_alloc_ok_v4';
    if (is_file($flag)) return $done = true;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS order_allocations (
                alloc_id INT AUTO_INCREMENT PRIMARY KEY,
                source VARCHAR(20) NOT NULL,
                order_id VARCHAR(40) NOT NULL,
                house VARCHAR(10) NOT NULL,
                order_type VARCHAR(10) NOT NULL DEFAULT '',
                employee_id INT NOT NULL DEFAULT 0,
                is_direct TINYINT NOT NULL DEFAULT 0,
                allocated_by VARCHAR(100) NULL,
                allocated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (source, order_id)
            )"
        );
        // Table created by the first version: add the Query / Campaign column.
        try {
            $col = $pdo->query("SHOW COLUMNS FROM order_allocations LIKE 'order_type'")->fetch();
            if (!$col) $pdo->exec("ALTER TABLE order_allocations ADD COLUMN order_type VARCHAR(10) NOT NULL DEFAULT ''");
            $col = $pdo->query("SHOW COLUMNS FROM order_allocations LIKE 'employee_id'")->fetch();
            if (!$col) $pdo->exec("ALTER TABLE order_allocations ADD COLUMN employee_id INT NOT NULL DEFAULT 0");
            // Direct order: allocated to a panel with no employee (nobody is credited).
            $col = $pdo->query("SHOW COLUMNS FROM order_allocations LIKE 'is_direct'")->fetch();
            if (!$col) $pdo->exec("ALTER TABLE order_allocations ADD COLUMN is_direct TINYINT NOT NULL DEFAULT 0");
        } catch (PDOException $e) {}
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

/** "source|order_id" => ['house' => 'tm4u', 'by' => ..., 'at' => ...] */
function order_allocations(PDO $pdo): array
{
    static $map = null;
    if ($map !== null) return $map;
    $map = [];
    if (!ensure_order_allocations_table($pdo)) return $map;
    try {
        try { $rows = $pdo->query("SELECT source, order_id, house, order_type, employee_id, is_direct, allocated_by, allocated_at FROM order_allocations")->fetchAll(); }
        catch (PDOException $e) { $rows = $pdo->query("SELECT source, order_id, house, order_type, employee_id, allocated_by, allocated_at FROM order_allocations")->fetchAll(); }
        foreach ($rows as $r) {
            $map[$r['source'] . '|' . $r['order_id']] = ['house' => $r['house'], 'type' => (string)($r['order_type'] ?? ''), 'emp' => (int)($r['employee_id'] ?? 0), 'direct' => (int)($r['is_direct'] ?? 0), 'by' => $r['allocated_by'], 'at' => $r['allocated_at']];
        }
    } catch (PDOException $e) {}
    return $map;
}

/** salesperson tag (lower case) => employee id, ONLY for tags that belong to exactly one person. A tag two people share is ambiguous: an order carrying it
 *  must not be credited to "the last one in the list" — it waits for a real allocation instead. $dups gets tag => [names]. */
function sales_tag_unique(array $emps, array &$dups = []): array
{
    $by = []; $dups = [];
    foreach ($emps as $id => $e) { $t = mb_strtolower(trim((string)($e['sales_tag'] ?? ''))); if ($t !== '') $by[$t][] = (int)$id; }
    $out = [];
    foreach ($by as $t => $ids) {
        if (count($ids) === 1) $out[$t] = $ids[0];
        else $dups[$t] = array_map(fn($i) => (string)($emps[$i]['full_name'] ?? ('#' . $i)), $ids);
    }
    return $out;
}

function house_labels(): array
{
    return store_group_options();
}

/**
 * Stamp one custom-store order with its allocation (if any): house, store
 * label, and a house tag so every existing house rule sees it.
 */
function apply_allocation(array &$o, string $csKey, array $map): void
{
    $a = $map[$csKey . '|' . (string)$o['id']] ?? null;
    $o['allocated'] = $a ? 1 : 0;
    $o['allocated_house'] = $a ? $a['house'] : '';
    $o['allocated_emp'] = $a ? (int)($a['emp'] ?? 0) : 0;
    $o['allocated_direct'] = $a ? (int)($a['direct'] ?? 0) : 0;   // Direct order: panel only, no employee
    $o['allocated_by'] = $a ? (string)$a['by'] : '';
    $o['allocated_at'] = $a ? (string)$a['at'] : '';
    $lk = code_lock_state();      // Employee-role logins: the code is locked N hours after allocation
    $ts = $a ? (int)strtotime((string)$a['at']) : 0;
    $dl = ($a && $lk['applies']) ? code_lock_deadline($lk['cfg'], $ts) : 0;
    $o['code_locked'] = ($dl && time() > $dl) ? 1 : 0;
    $o['order_type'] = $a ? (string)($a['type'] ?? '') : '';
    if ($a) {
        $o['house'] = $a['house'];
        $o['house_tags'] = [$a['house']];
        // The house rule reads tags; Query / Campaign counting reads the same
        // tags (query / campaign). Keep the order's other tags (salesman
        // tag etc.), drop any old house / type tags, then add the chosen ones.
        $keep = [];
        $hm = house_tag_map();
        foreach (explode(',', (string)($o['tags'] ?? '')) as $t) {
            $k = strtolower(trim($t));
            if ($k === '' || isset($hm[$k]) || in_array($k, ['query', 'campaign', 's', 'c'], true)) continue;
            $keep[] = trim($t);
        }
        $keep[] = $a['house'];
        if ($o['order_type'] !== '') $keep[] = $o['order_type'];
        $o['tags'] = implode(', ', $keep);
        $o['store_src'] = $o['store'] ?? '';
        $o['store'] = house_labels()[$a['house']] ?? $a['house'];
        if ($o['allocated_emp']) {
            // the person chosen on Order Allocation ALWAYS wins, by name too (also when that employee is no longer in the active list); never keep the old tag salesman's name next to the new person's id
            $o['salesman'] = employee_names_by_id($GLOBALS['pdo'])[$o['allocated_emp']] ?? employee_name_any($GLOBALS['pdo'], (int)$o['allocated_emp']);
        }
        if ($o['allocated_direct']) $o['salesman'] = '';
    }
}

/** Orders cancelled on the Orders page (HRMS only — nothing is changed in Shopify). */
function ensure_order_cancels_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_order_cancels_ok_v1';
    if (is_file($flag)) return $done = true;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS order_cancels (
                source VARCHAR(20) NOT NULL,
                order_id VARCHAR(40) NOT NULL,
                order_name VARCHAR(40) NOT NULL DEFAULT '',
                cancelled_by VARCHAR(100) NULL,
                cancelled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (source, order_id)
            )"
        );
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

/** "source|order_id" => ['by' => name, 'at' => datetime] for every cancelled order. */
function order_cancels_map(PDO $pdo): array
{
    static $map = null;
    if ($map !== null) return $map;
    $map = [];
    if (!ensure_order_cancels_table($pdo)) return $map;
    try {
        foreach ($pdo->query("SELECT source, order_id, cancelled_by, cancelled_at FROM order_cancels")->fetchAll() as $r) {
            $map[$r['source'] . '|' . $r['order_id']] = ['by' => (string)$r['cancelled_by'], 'at' => (string)$r['cancelled_at']];
        }
    } catch (PDOException $e) {}
    return $map;
}

/**
 * Allocation override for the Targets / Performance / My Sales loops:
 * replaces the house and the salesman worked out from tags with the ones
 * chosen on the Order Allocation page (when that order was allocated).
 */
function alloc_override(array $map, string $source, $orderId, string &$gk, ?array &$sm): void
{
    // A cancelled order counts for nobody.
    if (isset(order_cancels_map($GLOBALS['pdo'])[$source . '|' . (string)$orderId])) { $sm = null; return; }
    $a = $map[$source . '|' . (string)$orderId] ?? null;
    if (!$a) return;
    $gk = $a['house'];
    if (!empty($a['direct'])) { $sm = null; return; }   // Direct order: counts under the panel, credited to no employee
    if (!empty($a['emp'])) {
        $sm = ['id' => (int)$a['emp'], 'name' => employee_names_by_id($GLOBALS['pdo'])[(int)$a['emp']] ?? ''];
    }
}

/** one employee's full name by id, whatever their status (used when an order was allocated to someone who has since left the active list). */
function employee_name_any(PDO $pdo, int $id): string
{
    static $c = [];
    if (!isset($c[$id])) { try { $q = $pdo->prepare("SELECT full_name FROM employees WHERE employee_id = ?"); $q->execute([$id]); $c[$id] = (string)$q->fetchColumn(); } catch (Throwable $e) { $c[$id] = ''; } }
    return $c[$id];
}

/** employee_id => full name (active employees). */
function employee_names_by_id(PDO $pdo): array
{
    static $map = null;
    if ($map !== null) return $map;
    $map = [];
    try {
        foreach ($pdo->query("SELECT employee_id, full_name FROM employees WHERE status != 'ex'")->fetchAll() as $e) {
            $map[(int)$e['employee_id']] = (string)$e['full_name'];
        }
    } catch (PDOException $e) {}
    return $map;
}

/** Employee id by full name (case/space-insensitive), for MySales salesmen. */
function employee_ids_by_name(PDO $pdo): array
{
    static $map = null;
    if ($map !== null) return $map;
    $map = [];
    foreach ($pdo->query("SELECT employee_id, full_name FROM employees WHERE status != 'ex'")->fetchAll() as $e) {
        $map[mb_strtolower(trim((string)$e['full_name']))] = (int)$e['employee_id'];
    }
    return $map;
}

/**
 * MySales orders in the range that were allocated to a house, shaped like
 * the Shopify orders the Targets / Performance / My Sales code loops over:
 * id, order_name, created_at, total, financial_status, customer, tags,
 * plus house, emp_id (by the panel salesman's name) and source.
 */
function allocated_house_orders(PDO $pdo, string $dateFrom, string $dateTo, array &$errors): array
{
    $map = order_allocations($pdo);
    $byName = employee_ids_by_name($pdo);
    $out = [];
    foreach ($map ? custom_stores() : [] as $csKey => $cs) {
        $res = fetch_custom_store($cs, $dateFrom, $dateTo);
        if (isset($res['error'])) { $errors[] = $res['error']; continue; }
        foreach ($res['orders'] as $o) {
            $a = $map[$csKey . '|' . (string)$o['id']] ?? null;
            if (!$a) continue;
            if (isset(order_cancels_map($pdo)[$csKey . '|' . (string)$o['id']])) continue;   // cancelled on the Orders page
            $name = mb_strtolower(trim((string)($o['panel_salesman'] ?? '')));
            $out[] = [
                'id' => $o['id'],
                'source' => $csKey,
                'order_name' => $o['order_name'],
                'created_at' => $o['created_at'],
                'biz_date' => $o['biz_date'],
                'total' => $o['total'],
                'financial_status' => $o['financial_status'], 'outstanding' => $o['outstanding'] ?? null,
                'customer' => (string)($o['phone'] ?? ''),
                'tags' => $a['house'] . (!empty($a['type']) ? ', ' . $a['type'] : ''),
                'house' => $a['house'],
                'order_type' => (string)($a['type'] ?? ''),
                'emp_id' => !empty($a['direct']) ? 0 : (!empty($a['emp']) ? (int)$a['emp'] : ($byName[$name] ?? 0)),
                'salesman' => !empty($a['direct']) ? '' : (!empty($a['emp']) ? (employee_names_by_id($pdo)[(int)$a['emp']] ?? '') : (string)($o['panel_salesman'] ?? '')),
            ];
        }
    }
    // Store bills (Store → Billing) join here, so they count like every other order for sales, targets and commission.
    require_once __DIR__ . '/store_lib.php';
    foreach (st_house_orders($pdo, $dateFrom, $dateTo) as $o) $out[] = $o;
    return $out;
}

/**
 * Fetch orders from ALL given stores in parallel (curl_multi), following each
 * store's pagination, up to ~2000 orders per store. Much faster than fetching
 * stores one after another.
 * Returns [key => ['orders' => [...], 'error' => null|string]].
 */
/**
 * Product colour counts for one order, from its line-item titles:
 * DG = Dark Green, LG = Light Green, WH = White, anything else = Other.
 * Counted by quantity (2 x a DG product = 2 Dark Green). 10 ml perfumes and chains are left out of all four.
 */
/**
 * The payment gateway transaction ids (GoKwik / PayU "txnid", they start with KWIK) written on a Shopify order.
 * Looked for in the order note, the note attributes, the checkout token and the tags. Returns "KWIK..., KWIK..." or '' (max 200 chars).
 * Finance uses it to match a PayU file row (its txnid) to the order.
 */
function order_pay_refs(array $o): string
{
    $hay = [(string)($o['note'] ?? ''), (string)($o['tags'] ?? ''), (string)($o['checkout_token'] ?? ''), (string)($o['reference'] ?? '')];
    foreach ((array)($o['note_attributes'] ?? []) as $a) { if (is_array($a)) { $hay[] = (string)($a['name'] ?? $a['key'] ?? '') . '=' . (string)($a['value'] ?? ''); } }
    $found = [];
    foreach ($hay as $h) { if ($h !== '' && preg_match_all('/KWIK[A-Za-z0-9]{3,}/i', $h, $m)) foreach ($m[0] as $x) $found[strtoupper($x)] = 1; }
    return mb_substr(implode(', ', array_keys($found)), 0, 200);
}

function order_product_colors(array $lineItems): array
{
    $c = ['dg' => 0, 'lg' => 0, 'wh' => 0, 'other' => 0, 'ml10' => 0];
    foreach ($lineItems as $li) {
        // 10 ml perfumes ("10 ml", "10ml", "10-ML") and chains (jewelry: "chain" / "chains") are not counted in DG / LG / WH / Other.
        // The 10 ml ones are counted on their own as ml10 ("Extra ml" on the Platform summary), × quantity.
        $nm = (string)($li['title'] ?? '') . ' ' . (string)($li['variant_title'] ?? '') . ' ' . (string)($li['name'] ?? '');
        if (preg_match('/(?<![0-9.])10\s*-?\s*ml(?![a-z])/i', $nm)) { $c['ml10'] += max(1, (int)($li['quantity'] ?? 1)); continue; }
        if (preg_match('/(?<![a-z0-9])chains?(?![a-z0-9])/i', $nm)) continue;
        $qty = max(1, (int)($li['quantity'] ?? 1));
        $k = 'other';
        if (preg_match('/(?<![A-Za-z0-9])(DG|LG|WH)(?![A-Za-z0-9])/i', (string)($li['title'] ?? ''), $m)) $k = strtolower($m[1]);
        $c[$k] += $qty;
    }
    return $c;
}

/**
 * ---------------- ML price slab commission ----------------
 * One chart: rows = order size in ML (100, 110 … 600), columns = the commission % (7, 6.5, 6 … 0.1) and, in each cell, the lowest
 * order price that still earns that %. An allocated order's commission = its total ML (free ML included) → that row → the price paid
 * → the % (mode 'step': a price between two columns earns the lower column's %; 'between': a % in between). Then: daily target incomplete → at most `cap`%;
 * no order code → `nocode`% of it (50 = half); below the last column → `floor`% (2.8%; no code → half of it); more than `maxdisc`% off the chart price → 0% (0 = off). A size between two rows (e.g. 165 ml)
 * uses prices in between. Prepaid orders are looked up at their price before the 2% prepaid discount (the company bears it).
 * Stored as JSON in hrms_settings (ml_slab_chart). Off until switched on (Commission Rules page → ML price slab).
 */
function ml_slab_default(): array
{
    // Price & Commission Slab Chart (v2, 22 Oct 2026): 7 / 6.5 / 6 (campaign) / 4 / 3.5 / 3 %, below the 3% price = 2.8% (never less).
    $rows = [
        [100,1810,1760,1700,1670,1640,1590],
        [110,1990,1940,1870,1840,1810,1750],
        [120,2170,2110,2040,2010,1970,1900],
