// ---------------------------------------------------------------------------------------------------------------------------
// Alerts
// ---------------------------------------------------------------------------------------------------------------------------
/** Creates the alert, or refreshes it while it is open. A resolved alert of the same key is left alone (no re-opening the same day). Returns true when it is new. */
function ct_alert(PDO $pdo, string $key, array $a): bool
{
    $q = $pdo->prepare("SELECT id, status, resolved_at FROM ct_alerts WHERE akey = ?"); $q->execute([$key]);
    $ex = $q->fetch();
    $f = ['kind' => (string)$a['kind'], 'sev' => (string)($a['sev'] ?? 'info'), 'emp' => (int)($a['emp'] ?? 0), 'day' => $a['day'] ?? null, 'title' => mb_substr((string)$a['title'], 0, 220),
        'body' => (string)($a['body'] ?? ''), 'gu' => (string)($a['gu'] ?? ''), 'meet' => !empty($a['meet']) ? 1 : 0];
    if ($ex) {
        if ($ex['status'] === 'open') $pdo->prepare("UPDATE ct_alerts SET severity = ?, title = ?, body = ?, gu = ?, updated_at = NOW() WHERE id = ?")->execute([$f['sev'], $f['title'], $f['body'], $f['gu'], $ex['id']]);
        // Handled (✅ Resolved, or a remark was written) but the same problem is STILL / AGAIN happening after the cool-down → it comes back as a new open alert.
        elseif ($ex['status'] === 'resolved' && !empty($ex['resolved_at']) && strtotime((string)$ex['resolved_at']) <= time() - max(5, (int)setting_get($pdo, 'ct_realert_min', '60')) * 60) {
            $pdo->prepare("UPDATE ct_alerts SET status = 'open', severity = ?, title = ?, body = ?, gu = ?, created_at = NOW(), updated_at = NOW(), resolved_at = NULL, resolved_by = '', note = '', pushed_at = NULL WHERE id = ?")->execute([$f['sev'], $f['title'], $f['body'], $f['gu'], $ex['id']]);
            return true;
        }
        return false;
    }
    $pdo->prepare("INSERT INTO ct_alerts (akey, kind, severity, employee_id, day, title, body, gu, meet_admin, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'open', NOW(), NOW())")
        ->execute([$key, $f['kind'], $f['sev'], $f['emp'], $f['day'], $f['title'], $f['body'], $f['gu'], $f['meet']]);
    return true;
}
/**
 * A remark was written to a person (Live, ratings, Orders sheet): every open alert about that person counts as handled and leaves "Needs attention".
 * If the same problem is still / again there after the cool-down (setting ct_realert_min, default 60 minutes), ct_alert() opens it again. Returns how many were cleared.
 */
function ct_alerts_handled(PDO $pdo, int $emp, string $by, string $text): int
{
    if ($emp <= 0) return 0;
    try {
        $st = $pdo->prepare("UPDATE ct_alerts SET status = 'resolved', resolved_at = NOW(), resolved_by = ?, note = ? WHERE employee_id = ? AND status = 'open' AND kind NOT IN ('digest', 'md_ignored', 'idea_rigid')");
        $st->execute([mb_substr($by, 0, 95), mb_substr('Remark: ' . trim($text), 0, 300), $emp]);
        return (int)$st->rowCount();
    } catch (Throwable $e) { return 0; }
}
function ct_money($v): string { return '₹' . number_format((float)$v, 0, '.', ','); }
/** Evaluates every goal for the day and writes / refreshes the alerts. Alerts whose problem is gone close themselves ('auto'); "meet admin" ones wait for a human. */
function ct_eval(PDO $pdo, string $day): array
{
    $S = ct_snapshot($pdo, $day); $cfg = $S['cfg']; $T = $S['team']; $want = []; $newRed = [];
    $add = function (string $key, array $a) use (&$want, &$newRed, $pdo, $day) {
        $a['day'] = $day; $want[$key] = 1;
        if (ct_alert($pdo, $key, $a) && ($a['sev'] ?? '') === 'red') $newRed[] = $a;
    };
    // ---- team goals ----
    if ($T['q_state'] === 'warn' || $T['q_state'] === 'red') {
        $add("q_pace|0|$day", ['kind' => 'q_pace', 'sev' => $T['q_state'] === 'red' ? 'red' : 'warn',
            'title' => 'Query orders below goal: ' . $T['query_orders'] . ' of ' . $T['q_expected_now'] . ' (goal ' . $T['q_goal_pct'] . '% of ' . $T['queries'] . ' queries, now ' . ($T['q_conv'] ?? '–') . '%)',
            'body' => 'Goal: ' . $T['q_goal_pct'] . '% of the queries given become query orders. Check who converts slowly below and push the queries that are still open.']);
    }
    foreach ($T['comm_checks'] as $ck) {
        if ($ck['state'] === 'miss') $add("comm|0|$day|" . $ck['at'], ['kind' => 'comm_check', 'sev' => 'red',
            'title' => 'Community orders: ' . $ck['have'] . ' by ' . $ck['at'] . ' — ' . $ck['need'] . ' needed',
            'body' => 'The ' . $T['comm_target'] . ' community-order target for the day is slipping. Tag the allocated community orders and ask the team for more community leads now.']);
    }
    if ($T['pieces'] >= (int)$cfg['mix_min_pieces'] && $T['mix_pct'] !== null && $T['mix_pct'] < (float)$cfg['mix_amber']) {
        $red = $T['mix_pct'] < (float)$cfg['mix_red'];
        $add("mix|0|$day", ['kind' => 'mix_team', 'sev' => $red ? 'red' : 'warn', 'title' => 'Dark green / light green / white mix is ' . $T['mix_pct'] . '% (goal ' . $cfg['mix_goal'] . '%)',
            'body' => 'DG ' . $T['dg'] . ' · LG ' . $T['lg'] . ' · WH ' . $T['wh'] . ' · other ' . $T['oth'] . '. Push the three signature colours in every chat.']);
    }
    // ---- per salesperson ----
    $meet = []; foreach ($cfg['meet'] as $m) $meet[$m['id']] = $m;
    $on = fn($id) => !empty($meet[$id]['on']);
    $hourNow = (int)date('G', strtotime((string)$S['now'])); $dsH = (int)substr(day_start_for($pdo, $day), 0, 2); $clockH = $hourNow < $dsH ? $hourNow + 24 : $hourNow;
    foreach ($S['emps'] as $id => $e) {
        $nm = trim(preg_replace('/\s+/', ' ', (string)$e['name']));      // FULL name in alerts (2-3 people can share a first name)
        // Selling or taking queries = working = must have a target. Tell the Admin at once.
        if (!($e['target'] > 0) && ($e['mark'] ?? '') !== 'leave' && ($e['orders'] > 0 || $e['sales'] > 0 || $e['queries'] > 0)) $add("no_target|$id|$day", ['kind' => 'no_target', 'sev' => 'red', 'emp' => $id, 'meet' => 1,
            'title' => "$nm is working but has no target — assign a target now", 'body' => $e['orders'] . ' order(s), ' . $e['queries'] . ' queries today and no target is set, so he is not measured. Set the target (Targets page) or switch him to "not working" if this was a mistake.']);
        // On leave but a sale came in: is he live (give a target) or not (move his orders to someone else)? Admin confirms; "live" = the Live switch ON.
        if (($e['mark'] ?? '') === 'leave' && ($e['wm'] ?? '') !== 'on' && ($e['orders'] > 0 || $e['sales'] > 0)) $add("leave_sale|$id|$day", ['kind' => 'leave_sale', 'sev' => 'red', 'emp' => $id, 'meet' => 1,
            'title' => "$nm is on leave but has a sale — " . ct_money($e['sales']) . ' (' . $e['orders'] . ' order' . ($e['orders'] === 1 ? '' : 's') . ')',
            'body' => 'Is he live today? If yes, switch him on and give him a target. If not, move his orders to another person (Order Allocation).']);
        // Selling but never punched in: tell the Admin now (also when the target is already reached — "why is he not punched in?").
        if ($day === biz_today($pdo) && ($e['orders'] > 0 || $e['sales'] > 0) && ($e['arrive'] ?? null) === null && !in_array(($e['mark'] ?? ''), ['wfh', 'leave'], true)) {
            $pc = ($e['target'] ?? 0) > 0 ? (int)round((float)($e['pct'] ?? 0)) : null;
            $add("no_punch_sales|$id|$day", ['kind' => 'no_punch_sales', 'sev' => 'red', 'emp' => $id, 'meet' => 1,
                'title' => "$nm has " . ct_money($e['sales']) . ' sales (' . $e['orders'] . ' order' . ($e['orders'] === 1 ? '' : 's') . ') but has not punched in' . ($pc !== null && $pc >= 100 ? ' — target already achieved' : ($pc !== null ? " — $pc% of target" : '')),
                'body' => 'Selling without a punch-in. Ask why he did not punch in, and ask him to punch in now (or fix his attendance) so the day is counted properly.']);
        }
        if (!empty($e['camp_weak'])) $add("camp_weak|$id|$day", ['kind' => 'camp_weak', 'sev' => 'warn', 'emp' => $id, 'meet' => 0,
            'title' => "$nm: query ratio " . round((float)$e['conv']) . '% (strong) but campaign ratio ' . round((float)$e['cq_conv']) . '% (team ' . round((float)($T['cq_conv'] ?? 0)) . '%) over ' . $e['cq'] . ' campaign queries',
            'body' => 'Good with fresh queries, weak with campaign customers. Check how he follows up campaign replies (already-assigned and newly assigned chats).']);
        if (!($e['target'] > 0) && $e['orders'] === 0) continue;          // on leave / not working today
        $tv = $e['tv'];
        if ($tv['state'] === 'near' && $tv['next']) $add("ticket_push|$id|$day", ['kind' => 'ticket_push', 'sev' => 'info', 'emp' => $id,
            'title' => "$nm: ticket " . ct_money($e['ticket']) . ' — ' . ct_money($tv['next'] - $e['ticket']) . ' from ' . ct_money($tv['next']),
            'body' => 'Next order of about ' . ct_money($tv['need_next']) . ' lifts the average to ' . ct_money($tv['next']) . '.',
            'gu' => 'Ticket ' . ct_money($e['ticket']) . ' છે — આગલો order લગભગ ' . ct_money($tv['need_next']) . ' નો કરો તો average ' . ct_money($tv['next']) . ' થઈ જશે! 🚀']);
        if (!empty($tv['carried'])) $add("ticket_big|$id|$day", ['kind' => 'ticket_big', 'sev' => 'info', 'emp' => $id,
            'title' => "$nm: ticket " . ct_money($e['ticket']) . ' is carried by ' . $e['big_orders'] . ' big order' . ($e['big_orders'] == 1 ? '' : 's'),
            'body' => 'Without orders above ' . ct_money($cfg['big_order']) . ' the clean ticket is ' . ct_money($e['clean_ticket']) . '. The normal orders are still below the step.']);
        if ($tv['state'] === 'raise') $add("ticket_raise|$id|$day", ['kind' => 'ticket_raise', 'sev' => 'info', 'emp' => $id,
            'title' => "$nm already reached " . ct_money($tv['reached']) . ' this early', 'body' => 'You can raise the ticket goal for this person today.',
            'gu' => 'વાહ! સવારે જ ticket ' . ct_money($tv['reached']) . ' પર — હવે થોડું ઊંચું goal રાખીએ? 💎']);
        if ($tv['state'] === 'low') $add("ticket_low|$id|$day", ['kind' => 'ticket_low', 'sev' => 'warn', 'emp' => $id,
            'title' => "$nm: ticket only " . ct_money($e['ticket']) . ' (step ' . ct_money($cfg['ticket_steps'][0]) . ')', 'body' => 'Suggest 200 ml / combos and the 10 ml add-on on the next orders.',
            'gu' => 'Ting ting! ⏰ Ticket ' . ct_money($e['ticket']) . ' — 200 ml / combo અને 10 ml add-on offer કરો, ticket તરત ઉપર જશે 💪']);
        if ($e['code_left'] > 0 && $e['orders'] >= 4 && $e['code_rate'] !== null && $e['code_rate'] < 50) $add("code_gap|$id|$day", ['kind' => 'code_gap', 'sev' => 'warn', 'emp' => $id,
            'title' => "$nm: " . $e['code'] . '/' . $e['orders'] . ' orders have a code', 'body' => 'Goal ' . $e['code_need'] . ' (65%) — ' . $e['code_left'] . ' more code(s) unlock full commission on every order.',
            'gu' => 'બસ ' . $e['code_left'] . ' code બાકી — પછી બધા orders પર FULL commission! 🔑']);
        if ($e['mix']['pieces'] >= (int)$cfg['mix_min_pieces'] && $e['mix']['pct'] !== null && $e['mix']['pct'] < (float)$cfg['mix_amber']) $add("mix|$id|$day", ['kind' => 'mix_emp', 'sev' => $e['mix']['pct'] < (float)$cfg['mix_red'] ? 'red' : 'warn', 'emp' => $id,
            'title' => "$nm: colour mix " . $e['mix']['pct'] . '%', 'body' => 'DG ' . $e['mix']['dg'] . ' · LG ' . $e['mix']['lg'] . ' · WH ' . $e['mix']['wh'] . ' · other ' . $e['mix']['oth'] . '.',
            'gu' => 'Dark green / light green / white perfume પર વધુ ભાર આપો — એ best sellers છે! 💚']);
        // ---- meet-admin triggers (all editable on the Control Tower → Settings) ----
        $hit = function (string $id2, string $title, string $body) use ($add, $id, $day) {
            $add("meet_$id2|$id|$day", ['kind' => 'meet_' . $id2, 'sev' => 'red', 'emp' => $id, 'meet' => 1, 'title' => $title, 'body' => $body,
                'gu' => 'Admin ને હમણાં મળો 🙋 — ' . $body]);
        };
        if ($on('no_order') && $e['orders'] === 0 && $e['elapsed_h'] >= (float)$meet['no_order']['v1'] && $e['target'] > 0) $hit('no_order', "$nm has no order yet", $e['elapsed_h'] . ' hours into the day with zero orders.');
        if ($on('order_pace') && $e['target'] > 0 && $e['should_pct'] > 0 && $e['elapsed_h'] >= (float)$meet['order_pace']['v2'] && $e['orders'] > 0 && ($e['pct'] ?? 0) < $e['should_pct'] * (float)$meet['order_pace']['v1'] / 100)
            $hit('order_pace', "$nm is far behind the pace", ($e['pct'] ?? 0) . '% of target when ' . $e['should_pct'] . '% is expected.');
        if ($on('ticket') && $e['orders'] >= (int)$meet['ticket']['v2'] && $e['ticket'] < (float)$meet['ticket']['v1']) $hit('ticket', "$nm: ticket size very low", 'Average ' . ct_money($e['ticket']) . ' over ' . $e['orders'] . ' orders.');
        if ($on('community') && $e['co'] === 0 && $clockH >= (int)$meet['community']['v1'] && $e['orders'] > 0) $hit('community', "$nm: no community order", 'Zero community orders at ' . date('g A', strtotime((string)$S['now'])) . '.');
        if ($on('code') && $e['orders'] >= (int)$meet['code']['v2'] && $e['code_rate'] !== null && $e['code_rate'] < (float)$meet['code']['v1'] && !$e['code_ok']) $hit('code', "$nm: not giving order codes", $e['code'] . '/' . $e['orders'] . ' orders have a code.');
        if ($on('mix') && $e['mix']['pieces'] >= (int)$meet['mix']['v2'] && $e['mix']['pct'] !== null && $e['mix']['pct'] < (float)$meet['mix']['v1']) $hit('mix', "$nm: colour mix far below goal", 'Only ' . $e['mix']['pct'] . '% DG / LG / WH.');
    }
    // problems that are gone close themselves (meet-admin, digest, Message Doctor and idea alerts wait for a human / their own rules)
    $q = $pdo->prepare("SELECT id, akey FROM ct_alerts WHERE day = ? AND status = 'open' AND meet_admin = 0 AND kind NOT IN ('digest', 'md_ignored', 'idea_rigid')"); $q->execute([$day]);
    foreach ($q->fetchAll() as $r) if (empty($want[$r['akey']])) $pdo->prepare("UPDATE ct_alerts SET status = 'auto', resolved_at = NOW(), resolved_by = 'auto' WHERE id = ?")->execute([$r['id']]);
    // a "meet admin" alert stays until a human presses Resolved — but when the problem has gone it says so (✅ Improving) and drops to info, and after 2 days it closes itself
    $q = $pdo->prepare("SELECT id, akey, title, created_at FROM ct_alerts WHERE day = ? AND status = 'open' AND meet_admin = 1"); $q->execute([$day]);
    foreach ($q->fetchAll() as $r) {
        if (!empty($want[$r['akey']]) || strpos((string)$r['title'], '✅') === 0) continue;
        $pdo->prepare("UPDATE ct_alerts SET severity = 'info', title = ?, updated_at = NOW() WHERE id = ?")->execute(['✅ Improving now — ' . mb_substr((string)$r['title'], 0, 190), $r['id']]);
    }
    $pdo->prepare("UPDATE ct_alerts SET status = 'auto', resolved_at = NOW(), resolved_by = 'auto (2 days)' WHERE status = 'open' AND meet_admin = 1 AND created_at < ?")->execute([date('Y-m-d H:i:s', time() - 2 * 86400)]);
    return ['red_new' => $newRed];
}
function ct_digest(PDO $pdo, string $day): void
{
    $cfg = ct_cfg($pdo); $S = ct_snapshot($pdo, $day); $T = $S['team'];
    $nowTs = strtotime((string)$S['now']); $h = (int)date('G', $nowTs);
    foreach ((array)$cfg['digest_hours'] as $dh) {
        $dh = (int)$dh; if ($h < $dh || $h > $dh + 2) continue;
        $lines = ['Query orders ' . $T['query_orders'] . ' / ' . $T['q_expected_now'] . ' (goal ' . $T['q_goal_pct'] . '% of ' . $T['queries'] . ' queries, now ' . ($T['q_conv'] ?? '–') . '%)',
            'Community orders ' . $T['community_orders'] . ' / ' . $T['comm_target'],
            'Ticket ' . ct_money($T['ticket']) . ' (steps ' . implode(' → ', array_map('ct_money', (array)$cfg['ticket_steps'])) . ')',
            'Codes ' . ($T['code_rate'] ?? '–') . '% · Colour mix ' . ($T['mix_pct'] ?? '–') . '% (goal ' . $cfg['mix_goal'] . '%)'];
        $behind = array_filter($S['emps'], fn($e) => $e['target'] > 0 && ($e['pct'] ?? 0) < ($e['should_pct'] ?? 0) * 0.7 && $e['elapsed_h'] >= 3);
        if ($behind) $lines[] = 'Needs a push: ' . implode(', ', array_slice(array_map(fn($e) => trim(preg_replace('/\s+/', ' ', (string)$e['name'])), array_values($behind)), 0, 6));
        $sev = $T['q_state'] === 'red' ? 'red' : ($T['q_state'] === 'warn' ? 'warn' : 'info');
        ct_alert($pdo, "digest|$day|$dh", ['kind' => 'digest', 'sev' => $sev, 'title' => date('g A', strtotime(sprintf('%02d:00', $dh))) . ' sales check', 'body' => implode("\n", $lines), 'day' => $day]);
    }
}
/** One pass: alerts + digest + Message Doctor + ideas, at most every 5 minutes; red alerts are pushed to the admin phones (and meet-admin ones to the salesperson). */
function ct_run(PDO $pdo, bool $force = false): array
{
    if (!ensure_ct_tables($pdo)) return ['ok' => false];
    $lock = sys_get_temp_dir() . '/hrms_ct_tick';
    if (!$force && is_file($lock) && time() - (int)filemtime($lock) < 300) return ['ok' => true, 'skipped' => 1];
    @touch($lock);
    @set_time_limit(90);
    $day = biz_today($pdo); $out = ['ok' => true];
    try {
        $r = ct_eval($pdo, $day); ct_digest($pdo, $day);
        $out['red_new'] = count($r['red_new']);
        // push: new red alerts to the admin phones; "meet admin" ones also to that salesperson
        $q = $pdo->query("SELECT id, employee_id, title, meet_admin FROM ct_alerts WHERE status = 'open' AND pushed_at IS NULL AND (severity = 'red' OR meet_admin = 1) ORDER BY id LIMIT 12");
        foreach ($q->fetchAll() as $a) {
            ct_push($pdo, ct_admin_emp_ids($pdo), '🚨 ' . $a['title'], 'Open the Control Tower', 'control_tower.html', 'hrms-ct');
            if ((int)$a['meet_admin'] === 1 && (int)$a['employee_id'] > 0) ct_push($pdo, [(int)$a['employee_id']], 'Meet admin 🙋', 'Please meet the admin now — ' . $a['title'], 'my_sales.html', 'hrms-ct-me');
            $pdo->prepare("UPDATE ct_alerts SET pushed_at = NOW() WHERE id = ?")->execute([$a['id']]);
        }
    } catch (Throwable $e) { error_log('ct_run eval: ' . $e->getMessage()); $out['err'] = $e->getMessage(); }
    try { $out['md'] = md_run($pdo, false); } catch (Throwable $e) { error_log('ct_run md: ' . $e->getMessage()); }
    try { ct_ideas_build($pdo, false); ct_ideas_track($pdo); } catch (Throwable $e) { error_log('ct_run ideas: ' . $e->getMessage()); }
    return $out;
}

// ---------------------------------------------------------------------------------------------------------------------------
// (The proof gate — chat screenshots and call recordings before an order is allocated — ended on 1 Nov 2026.)
// ---------------------------------------------------------------------------------------------------------------------------

// ---------------------------------------------------------------------------------------------------------------------------
// Message Doctor: which messages / offers / funnel sections work, which do not, and whether anyone fixed them
// ---------------------------------------------------------------------------------------------------------------------------
function md_norm(string $s): string { return mb_substr(premsg_norm($s), 0, 70); }
/** Reviewed chats of the last $days days: [emp, ts, won (ordered), amt, chat]. */
function md_chats(PDO $pdo, int $days): array
{
    static $memo = [];
    if (isset($memo[$days])) return $memo[$days];
    $out = [];
    if (!ensure_convo_tables($pdo)) return $memo[$days] = $out;
    try {
        $q = $pdo->prepare("SELECT employee_id, kind, order_total, score, created_at, result FROM convo_uploads WHERE status = 'done' AND flag_wrong = 0 AND kind IN ('order', 'lost') AND created_at >= ?");
        $q->execute([date('Y-m-d H:i:s', time() - $days * 86400)]);
        foreach ($q->fetchAll() as $r) {
            $c = convo_result($r)['chat'] ?? null; if (!is_array($c) || empty($c['is_chat'])) continue;
            $out[] = ['emp' => (int)$r['employee_id'], 'ts' => strtotime((string)$r['created_at']), 'won' => $r['kind'] !== 'lost', 'amt' => (float)$r['order_total'], 'chat' => $c];
        }
    } catch (PDOException $e) {}
    return $memo[$days] = $out;
}
function md_rate(int $a, int $n): ?float { return $n > 0 ? round($a / $n * 100, 1) : null; }
/** Everything that is weak or strong right now. Each: ikey, itype (msg|offer|flash|section), label, state (weak|good), m (numbers), finger (changes when someone edits it), advice. */
function md_findings(PDO $pdo): array
{
    $cfg = ct_cfg($pdo); $mu = (int)$cfg['md']['min_uses']; $weakRep = (float)$cfg['md']['weak_reply'];
    $rows = md_chats($pdo, 30); $F = [];
    // ---- 1. pre-messages (the ready-made texts the team copies) ----
    foreach (premsg_stats($pdo, 30)['rows'] as $m) {
        if (!$m['active'] || $m['uses'] < $mu || $m['rating'] === null) continue;
        $rep = $m['reply_rate'] !== null ? round($m['reply_rate'] * 100) : null; $ord = $m['order_rate'] !== null ? round($m['order_rate'] * 100) : null;
        $state = $m['rating'] >= 7.5 ? 'good' : ($m['rating'] < 5.5 || ($rep !== null && $rep <= $weakRep) ? 'weak' : null); if (!$state) continue;
        $F[] = ['ikey' => 'pm|' . $m['id'], 'itype' => 'msg', 'label' => 'Pre-message “' . $m['title'] . '”', 'state' => $state, 'pm_id' => $m['id'], 'text' => $m['body'],
            'm' => ['uses' => $m['uses'], 'reply' => $rep, 'orders' => $ord, 'rating' => $m['rating']], 'finger' => md5($m['title'] . '|' . $m['body'] . '|' . (int)$m['active']),
            'advice' => $state === 'weak' ? 'Customers rarely answer this one (' . ($rep ?? '?') . '% reply). Rewrite it shorter, start with a question, or stop using it.' : 'Customers answer it (' . ($rep ?? '?') . '% reply) and orders follow — copy this style into the weaker messages.'];
    }
    // ---- 2. messages the salespeople write themselves (from the AI's chat reading), grouped by funnel stage + wording ----
    $pat = []; $bn = 0; $bw = 0;
    foreach ($rows as $r) {
        foreach ((array)($r['chat']['msg_patterns'] ?? []) as $p) {
            $t = trim((string)($p['text'] ?? '')); if (mb_strlen($t) < 12) continue;
            $k = (string)($p['stage'] ?? 'other') . '|' . md_norm($t); if (mb_strlen($k) < 20) continue;
            $x = &$pat[$k]; if (!$x) $x = ['stage' => (string)$p['stage'], 'text' => mb_substr($t, 0, 140), 'n' => 0, 'rep' => 0, 'won' => 0, 'emps' => []];
            $x['n']++; if (!empty($p['customer_replied'])) $x['rep']++; if ($r['won']) $x['won']++; $x['emps'][$r['emp']] = 1; unset($x);
        }
    }
    foreach ($pat as $k => $x) {
        if ($x['n'] < $mu) continue;
        $rep = md_rate($x['rep'], $x['n']); $ord = md_rate($x['won'], $x['n']);
        $state = $rep <= $weakRep ? 'weak' : ($rep >= 75 && $ord >= 60 ? 'good' : null); if (!$state) continue;
        $F[] = ['ikey' => 'pat|' . substr(md5($k), 0, 16), 'itype' => 'msg', 'label' => ucfirst($x['stage']) . ' message: “' . $x['text'] . '”', 'state' => $state, 'text' => $x['text'], 'stage' => $x['stage'],
            'm' => ['uses' => $x['n'], 'reply' => round($rep), 'orders' => round($ord), 'people' => count($x['emps'])], 'finger' => '',
            'advice' => $state === 'weak' ? 'Used ' . $x['n'] . ' times by ' . count($x['emps']) . ' people, customers answer only ' . round($rep) . '% of the time. Replace it with a better ' . $x['stage'] . ' line.' : 'Works: ' . round($rep) . '% of customers reply to it.'];
    }
    // ---- 3. offers the salespeople pitched in chats ----
    $of = [];
    foreach ($rows as $r) foreach ((array)($r['chat']['offers_used'] ?? []) as $o) {
        $k = (string)($o['offer'] ?? 'other'); $x = &$of[$k]; if (!$x) $x = ['n' => 0, 'acc' => 0, 'amt' => 0.0, 'wn' => 0];
        $x['n']++; if (!empty($o['accepted'])) { $x['acc']++; if ($r['amt'] > 0) { $x['amt'] += $r['amt']; $x['wn']++; } } unset($x);
    }
    $names = ['flash' => 'Limited-time (flash) offer', 'combo' => 'Combo offer', 'ml10' => '10 ml add-on', 'discount' => 'Discount', 'prepaid_discount' => 'Prepaid discount', 'free_gift' => 'Free gift', 'other' => 'Other offers'];
    foreach ($of as $k => $x) {
        if ($x['n'] < $mu + 3) continue;
        $acc = md_rate($x['acc'], $x['n']); $state = $acc <= 15 ? 'weak' : ($acc >= 45 ? 'good' : null); if (!$state) continue;
        $F[] = ['ikey' => 'offer|' . $k, 'itype' => 'offer', 'label' => ($names[$k] ?? $k) . ' (as pitched in chats)', 'state' => $state, 'm' => ['pitched' => $x['n'], 'accepted' => round($acc)], 'finger' => '',
            'advice' => $state === 'weak' ? 'Pitched ' . $x['n'] . ' times, customers take it only ' . round($acc) . '% of the time. Change the wording or the price.' : 'Customers take it ' . round($acc) . '% of the time — pitch it more.'];
    }
    // ---- 4. flash offers: orders that used them ----
    try {
        $today = biz_today($pdo); coach_day($pdo, $today, true);
        $sale = $GLOBALS['coach_sale_memo'][$today . '1'] ?? [];
        $all = []; foreach ($sale as $l) foreach ($l as $o) $all[] = $o;
        foreach (flash_offer_list_get($pdo) as $x) {
            $s = strtotime((string)($x['started_at'] ?? '')); $e = min(time(), strtotime((string)($x['ends_at'] ?? '')) ?: time()); if (!$s || $s < time() - 14 * 86400) continue;
            $hours = ($e - $s) / 3600; if ($hours < 3) continue;
            $mls = array_map(fn($i) => (int)$i['ml'], (array)($x['items'] ?? []));
            $tot = 0; $hit = 0;
            foreach ($all as $o) { if ($o['ts'] < $s || $o['ts'] > $e) continue; $tot++; if ($o['ml'] && in_array((int)round((float)$o['ml']), $mls, true)) $hit++; }
            $share = $tot ? $hit / $tot * 100 : 0;
            $state = $hit === 0 ? 'weak' : ($share < 5 && $hours >= 6 ? 'weak' : ($share >= 25 ? 'good' : null)); if (!$state) continue;
            $lbl = implode(' + ', array_map(fn($i) => $i['ml'] . ' ml ₹' . round($i['price']), (array)$x['items']));
            $F[] = ['ikey' => 'flash|' . ($x['id'] ?? md5($lbl . $x['started_at'])), 'itype' => 'flash', 'label' => 'Flash offer ' . $lbl, 'state' => $state, 'm' => ['orders' => $hit, 'of_orders' => $tot, 'share' => round($share), 'hours' => round($hours, 1)],
                'finger' => md5(json_encode([$x['items'] ?? [], $x['pct'] ?? 0, $x['status'] ?? '', $x['ends_at'] ?? ''])),
                'advice' => $state === 'weak' ? ($hit === 0 ? 'Nobody sold this size in ' . round($hours, 1) . ' hours. Change the price / size, or announce it to the team.' : 'Only ' . round($share) . '% of orders used it. Make the offer easier to say in the chat.') : 'This offer converts: ' . round($share) . '% of orders use it.'];
        }
    } catch (Throwable $e) { error_log('md flash: ' . $e->getMessage()); }
    // ---- 5. funnel sections (the AI's nine skill scores, team average, last 7 days vs the 7 before) ----
    $sk = ['reply_speed' => 'Reply speed', 'greeting' => 'Greeting / opening', 'need_discovery' => 'Asking what the customer needs', 'suggestion' => 'Suggesting perfumes', 'upsell' => 'Add-on offer',
        'objection' => 'Handling price doubts', 'prepaid' => 'Asking for prepaid', 'closing' => 'Closing the sale', 'tone' => 'Tone'];
    $cut = time() - 7 * 86400; $A = []; $B = [];
    foreach ($rows as $r) foreach ($sk as $k => $_) { $v = $r['chat']['scores'][$k] ?? -1; if ($v < 0) continue; if ($r['ts'] >= $cut) $A[$k][] = $v; elseif ($r['ts'] >= $cut - 7 * 86400) $B[$k][] = $v; }
    foreach ($sk as $k => $lab) {
        $a = $A[$k] ?? []; if (count($a) < (int)$cfg['md']['min_chats_section']) continue;
        $avg = array_sum($a) / count($a); $b = $B[$k] ?? []; $prev = count($b) >= 5 ? array_sum($b) / count($b) : null;
        $state = $avg <= 5.5 ? 'weak' : ($avg >= 7.5 ? 'good' : null); if (!$state) continue;
        $F[] = ['ikey' => 'sec|' . $k, 'itype' => 'section', 'label' => 'Section: ' . $lab, 'state' => $state, 'm' => ['score' => round($avg, 1), 'prev' => $prev !== null ? round($prev, 1) : null, 'chats' => count($a)], 'finger' => '',
            'advice' => $state === 'weak' ? 'Team average ' . round($avg, 1) . '/10 on “' . $lab . '”' . ($prev !== null ? ' (was ' . round($prev, 1) . ')' : '') . '. Fix this section: a short training note + a ready message for it.' : 'Team is strong here (' . round($avg, 1) . '/10).'];
    }
    return $F;
}
function md_run(PDO $pdo, bool $force): array
{
    if (!ensure_ct_tables($pdo)) return [];
    $last = (int)setting_get($pdo, 'md_last_run', 0);
    if (!$force && time() - $last < 3 * 3600) return ['skipped' => 1];
    setting_set($pdo, 'md_last_run', (string)time());
    $cfg = ct_cfg($pdo); $today = biz_today($pdo); $ign = (int)$cfg['md']['ignore_days']; $mu = (int)$cfg['md']['min_uses'];
    $F = md_findings($pdo); $weak = []; foreach ($F as $f) if ($f['state'] === 'weak') $weak[$f['ikey']] = $f;
    $items = []; foreach ($pdo->query("SELECT * FROM md_items")->fetchAll() as $r) $items[$r['ikey']] = $r;
    foreach ($weak as $k => $f) {
        $base = json_encode($f['m'], JSON_UNESCAPED_UNICODE);
        if (empty($items[$k])) {
            $pdo->prepare("INSERT INTO md_items (ikey, itype, label, first_flagged, last_flagged, flagged_days, status, finger, baseline, updated_at) VALUES (?, ?, ?, ?, ?, 1, 'open', ?, ?, NOW())")
                ->execute([$k, $f['itype'], mb_substr($f['label'], 0, 300), $today, $today, $f['finger'], $base]);
            continue;
        }
        $it = $items[$k];
        if (in_array($it['status'], ['cleared', 'improved', 'removed'], true)) { $pdo->prepare("UPDATE md_items SET status = 'open', first_flagged = ?, last_flagged = ?, flagged_days = 1, finger = ?, baseline = ?, verdict = '', fixed_at = NULL, after_txt = NULL, label = ?, updated_at = NOW() WHERE id = ?")->execute([$today, $today, $f['finger'], $base, mb_substr($f['label'], 0, 300), $it['id']]); continue; }
        if ($it['status'] === 'open') {
            $days = (int)$it['flagged_days'] + ($it['last_flagged'] !== $today ? 1 : 0);
            if ($f['finger'] !== '' && $f['finger'] !== (string)$it['finger']) {        // somebody edited the message / offer
                $pdo->prepare("UPDATE md_items SET status = 'changed', fixed_at = NOW(), fixed_by = 'edited', finger = ?, flagged_days = ?, last_flagged = ?, label = ?, updated_at = NOW() WHERE id = ?")->execute([$f['finger'], $days, $today, mb_substr($f['label'], 0, 300), $it['id']]);
            } else $pdo->prepare("UPDATE md_items SET flagged_days = ?, last_flagged = ?, label = ?, updated_at = NOW() WHERE id = ?")->execute([$days, $today, mb_substr($f['label'], 0, 300), $it['id']]);
        } elseif ($it['status'] === 'changed') {
            // changed, but still weak — has it had enough chats since the change to judge?
            $uses = md_uses_since($pdo, $k, (string)$it['fixed_at'], $f);
            if ($uses >= max(3, (int)floor($mu / 2))) $pdo->prepare("UPDATE md_items SET status = 'open', verdict = 'same', flagged_days = 1, first_flagged = ?, last_flagged = ?, after_txt = ?, updated_at = NOW() WHERE id = ?")->execute([$today, $today, json_encode($f['m'], JSON_UNESCAPED_UNICODE), $it['id']]);
        }
    }
    $goodNow = []; foreach ($F as $f) if ($f['state'] === 'good') $goodNow[$f['ikey']] = $f;
    foreach ($items as $k => $it) {
        if (isset($weak[$k])) continue;
        if ($it['status'] === 'open') $pdo->prepare("UPDATE md_items SET status = 'cleared', updated_at = NOW() WHERE id = ?")->execute([$it['id']]);
        elseif ($it['status'] === 'changed') {
            // no longer weak after the change → learn: it worked (compare with the numbers at the time it was flagged)
            if (isset($goodNow[$k])) { $pdo->prepare("UPDATE md_items SET status = 'improved', verdict = 'improved', after_txt = ?, updated_at = NOW() WHERE id = ?")->execute([json_encode($goodNow[$k]['m'], JSON_UNESCAPED_UNICODE), $it['id']]); }
            elseif ((strtotime((string)$it['fixed_at']) ?: 0) < time() - 3 * 86400) $pdo->prepare("UPDATE md_items SET status = 'improved', verdict = 'ok', updated_at = NOW() WHERE id = ?")->execute([$it['id']]);
        }
    }
    // pre-messages that were deleted count as fixed ("removed")
    foreach ($items as $k => $it) if (strpos($k, 'pm|') === 0 && $it['status'] === 'open' && !isset($weak[$k])) {
        $q = $pdo->prepare("SELECT 1 FROM pre_messages WHERE id = ?"); $q->execute([(int)substr($k, 3)]);
        if (!$q->fetchColumn()) $pdo->prepare("UPDATE md_items SET status = 'removed', fixed_at = NOW(), fixed_by = 'deleted', verdict = 'removed', updated_at = NOW() WHERE id = ?")->execute([$it['id']]);
    }
    // "nobody is changing it" → admin alert
    $wk = date('oW');
    $q = $pdo->query("SELECT * FROM md_items WHERE status = 'open' AND flagged_days >= " . $ign);
    $n = 0;
    foreach ($q->fetchAll() as $it) {
        $d = (int)$it['flagged_days'];
        ct_alert($pdo, 'md_ignored|' . $it['ikey'] . '|' . $wk, ['kind' => 'md_ignored', 'sev' => $d >= 2 * $ign ? 'red' : 'warn', 'day' => $today,
            'title' => 'Nobody has changed this for ' . $d . ' days: ' . mb_substr((string)$it['label'], 0, 120),
            'body' => ($it['verdict'] === 'same' ? 'It was edited but still does not work. ' : ($it['verdict'] === 'rigid' ? 'It is still being used after the fix. ' : '')) . 'Open the Message Doctor and fix this section — the HRMS will learn from the result.']);
        $n++;
    }
    return ['weak' => count($weak), 'ignored' => $n];
}
/** How many times the flagged thing was used since the change (messages: chats that contain it; offers / sections: use the current sample as a proxy). */
function md_uses_since(PDO $pdo, string $ikey, string $since, array $f): int
{
    $ts = strtotime($since) ?: 0; $n = 0;
    foreach (md_chats($pdo, 30) as $r) {
        if ($r['ts'] < $ts) continue;
        if (strpos($ikey, 'pat|') === 0) { foreach ((array)($r['chat']['msg_patterns'] ?? []) as $p) if (substr(md5(((string)$p['stage']) . '|' . md_norm((string)$p['text'])), 0, 16) === substr($ikey, 4)) $n++; }
        elseif (strpos($ikey, 'pm|') === 0) { foreach ((array)($r['chat']['pre_used'] ?? []) as $u) if ((int)($u['id'] ?? 0) === (int)substr($ikey, 3)) $n++; }
        else $n++;
    }
    return $n;
}
function md_report(PDO $pdo): array
{
    ensure_ct_tables($pdo);
    $F = md_findings($pdo); $items = [];
    foreach ($pdo->query("SELECT * FROM md_items ORDER BY FIELD(status, 'open', 'changed', 'improved', 'removed', 'cleared'), flagged_days DESC, id DESC LIMIT 80")->fetchAll() as $r) $items[$r['ikey']] = $r;
    $weak = []; $good = [];
    foreach ($F as $f) {
        $it = $items[$f['ikey']] ?? null;
        $f['status'] = $it['status'] ?? 'open'; $f['flagged_days'] = (int)($it['flagged_days'] ?? 1); $f['first_flagged'] = $it['first_flagged'] ?? null; $f['verdict'] = $it['verdict'] ?? ''; $f['fixed_by'] = $it['fixed_by'] ?? ''; $f['fixed_at'] = $it['fixed_at'] ?? null;
        unset($f['finger']);
        if ($f['state'] === 'weak') $weak[] = $f; else $good[] = $f;
    }
    $order = ['section' => 0, 'msg' => 1, 'offer' => 2, 'flash' => 3];
    usort($weak, fn($a, $b) => $b['flagged_days'] <=> $a['flagged_days'] ?: ($order[$a['itype']] ?? 9) <=> ($order[$b['itype']] ?? 9));
    $log = [];
    foreach ($items as $r) if (in_array($r['status'], ['changed', 'improved', 'removed'], true) || $r['verdict'] !== '')
        $log[] = ['key' => $r['ikey'], 'label' => $r['label'], 'status' => $r['status'], 'verdict' => $r['verdict'], 'fixed_at' => $r['fixed_at'], 'fixed_by' => $r['fixed_by'],
            'before' => json_decode((string)$r['baseline'], true), 'after' => json_decode((string)$r['after_txt'], true)];
    $chats = count(md_chats($pdo, 30));
    return ['weak' => $weak, 'good' => array_slice($good, 0, 12), 'log' => array_slice($log, 0, 20), 'chats_read' => $chats, 'cfg' => ct_cfg($pdo)['md']];
}

// ---------------------------------------------------------------------------------------------------------------------------
// Learning ideas: what the best chats do differently, shown to the salesperson who is not doing it yet
// ---------------------------------------------------------------------------------------------------------------------------
function ct_idea_defs(): array
{
    // key => [good-side test, label shown, gujarati title, gujarati body (with {a} {b} {n}), english why, 'win' = order rate | 'ticket' = average order value]
    return [
        'fast_reply' => ['mode' => 'win', 'gu' => '⚡ પહેલો reply 2 મિનિટમાં આપો', 'body' => 'જે chats માં પહેલો reply 2 મિનિટમાં ગયો ત્યાં {a}% orders મળ્યા — બાકીમાં ફક્ત {b}%. આજે દરેક નવા query ને પહેલા 2 મિનિટમાં reply / call કરો.', 'en' => 'Chats answered within 2 minutes turn into orders far more often.'],
        'questions' => ['mode' => 'win', 'gu' => '❓ પહેલા 3 સવાલ પૂછો', 'body' => 'જ્યાં સવાલ (occasion, પસંદગી, budget) પૂછ્યા ત્યાં {a}% orders — ન પૂછ્યા ત્યાં {b}%. Perfume suggest કરતાં પહેલા 3 સવાલ પૂછો.', 'en' => 'Asking 3 questions before suggesting a perfume lifts the order rate.'],
        'ml10' => ['mode' => 'ticket', 'gu' => '🧴 10 ml add-on offer કરો', 'body' => '10 ml offer કર્યો ત્યાં સરેરાશ order ₹{a} — ન કર્યો ત્યાં ₹{b}. દરેક order માં "બીજી smell 10 ml માં try કરશો?" પૂછો.', 'en' => 'Offering a 10 ml add-on raises the order value.'],
        'combo' => ['mode' => 'ticket', 'gu' => '🎁 Combo offer કરો', 'body' => 'Combo offer કર્યો ત્યાં સરેરાશ order ₹{a} — ન કર્યો ત્યાં ₹{b}. 100 ml સાથે બીજું size / combo જરૂર બતાવો.', 'en' => 'Showing a combo lifts the order value.'],
        'prepaid' => ['mode' => 'win', 'gu' => '💳 Prepaid માટે પૂછો', 'body' => 'Prepaid માટે પૂછ્યું ત્યાં {a}% orders — ન પૂછ્યું ત્યાં {b}%. Order confirm કરતાં "UPI થી prepaid કરશો તો extra benefit" કહો.', 'en' => 'Asking for prepaid closes more orders.'],
        'objection' => ['mode' => 'win', 'gu' => '💬 Price ના doubt માં value સમજાવો', 'body' => 'Price doubt ને value થી handle કર્યો ત્યાં {a}% orders — બાકીમાં {b}%. Discount પહેલાં long-lasting, oil % અને combo value કહો.', 'en' => 'Handling price doubts with value, not discount, wins the order.'],
    ];
}
function ct_idea_good(string $key, array $c): ?bool
{
    switch ($key) {
        case 'fast_reply': $m = (float)($c['first_reply_min'] ?? -1); return $m < 0 ? null : $m <= 2;
        case 'questions': return (int)($c['questions_asked'] ?? 0) >= 3;
        case 'ml10': return !empty($c['offered_10ml']);
        case 'combo': return !empty($c['offered_combo']);
        case 'prepaid': return !empty($c['asked_prepaid']);
        case 'objection': return empty($c['price_objection']) ? null : !empty($c['objection_handled']);
    }
    return null;
}
function ct_ideas_build(PDO $pdo, bool $force): void
{
    if (!ensure_ct_tables($pdo)) return;
    if (!$force && time() - (int)setting_get($pdo, 'ct_ideas_run', 0) < 6 * 3600) return;
    setting_set($pdo, 'ct_ideas_run', (string)time());
    $rows = md_chats($pdo, 30); if (count($rows) < 12) return;
    foreach (ct_idea_defs() as $key => $d) {
        $A = ['n' => 0, 'w' => 0, 'amt' => 0.0, 'wn' => 0]; $B = $A;
        foreach ($rows as $r) {
            $g = ct_idea_good($key, $r['chat']); if ($g === null) continue;
            $x = &$A; if (!$g) { unset($x); $x = &$B; }
            $x['n']++; if ($r['won']) { $x['w']++; if ($r['amt'] > 0) { $x['amt'] += $r['amt']; $x['wn']++; } } unset($x);
        }
        if ($A['n'] < 6 || $B['n'] < 6) continue;
        if ($d['mode'] === 'win') { $a = $A['w'] / $A['n'] * 100; $b = $B['w'] / $B['n'] * 100; $lift = $a - $b; $ok = $lift >= 8; }
        else { if ($A['wn'] < 5 || $B['wn'] < 5) continue; $a = $A['amt'] / $A['wn']; $b = $B['amt'] / $B['wn']; $lift = $b > 0 ? ($a - $b) / $b * 100 : 0; $ok = $lift >= 6; }
        if (!$ok) continue;
        $body = str_replace(['{a}', '{b}'], [round($a), round($b)], $d['body']);
        $ev = json_encode(['a_n' => $A['n'], 'b_n' => $B['n'], 'a' => round($a, 1), 'b' => round($b, 1), 'mode' => $d['mode']]);
        $pdo->prepare("INSERT INTO ct_ideas (ikey, title, body, why, evidence, lift, active, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, 1, NOW(), NOW())
            ON DUPLICATE KEY UPDATE title = VALUES(title), body = VALUES(body), why = VALUES(why), evidence = VALUES(evidence), lift = VALUES(lift), updated_at = NOW()")
            ->execute([$key, $d['gu'], $body, $d['en'] . ' (' . $A['n'] . ' chats vs ' . $B['n'] . ')', $ev, round($lift, 1)]);
    }
}
/** The share (%) of the person's chats in a window that do the good thing; null = fewer than 3 chats. */
function ct_idea_rate(PDO $pdo, string $key, int $emp, int $from, int $to): ?array
{
    $n = 0; $g = 0;
    foreach (md_chats($pdo, 30) as $r) {
        if ($r['emp'] !== $emp || $r['ts'] < $from || $r['ts'] > $to) continue;
        $v = ct_idea_good($key, $r['chat']); if ($v === null) continue; $n++; if ($v) $g++;
    }
    return $n >= 3 ? [round($g / $n * 100), $n] : null;
}
/** After rigid_days: did the salesperson start doing it (adopted) or not (rigid → alert for Admin, gentle nudge for the salesperson)? */
function ct_ideas_track(PDO $pdo): void
{
    if (!ensure_ct_tables($pdo)) return;
    $cfg = ct_cfg($pdo); $rd = max(1, (int)$cfg['ideas']['rigid_days']);
    $q = $pdo->query("SELECT s.*, i.ikey, i.title FROM ct_idea_state s JOIN ct_ideas i ON i.id = s.idea_id WHERE s.shown_at IS NOT NULL AND s.adopted_at IS NULL AND s.rigid_at IS NULL");
    foreach ($q->fetchAll() as $s) {
        $since = strtotime((string)$s['shown_at']); if ($since > time() - $rd * 86400) continue;
        $now = ct_idea_rate($pdo, (string)$s['ikey'], (int)$s['employee_id'], $since, time()); if (!$now) continue;
        $before = $s['before_val'] !== null ? (float)$s['before_val'] : 0;
        if ($now[0] >= max(60, $before + 15)) { $pdo->prepare("UPDATE ct_idea_state SET adopted_at = NOW() WHERE idea_id = ? AND employee_id = ?")->execute([$s['idea_id'], $s['employee_id']]); continue; }
        $pdo->prepare("UPDATE ct_idea_state SET rigid_at = NOW() WHERE idea_id = ? AND employee_id = ?")->execute([$s['idea_id'], $s['employee_id']]);
        $nm = (string)$pdo->query("SELECT full_name FROM employees WHERE employee_id = " . (int)$s['employee_id'])->fetchColumn();
        ct_alert($pdo, 'idea_rigid|' . $s['employee_id'] . '|' . $s['ikey'], ['kind' => 'idea_rigid', 'sev' => 'warn', 'emp' => (int)$s['employee_id'], 'day' => biz_today($pdo),
            'title' => trim($nm) . ' has not tried “' . $s['title'] . '” after ' . $rd . ' days', 'body' => 'Doing it in ' . $now[0] . '% of ' . $now[1] . ' recent chats (was ' . round($before) . '%). Talk to them.',
            'gu' => 'આ idea ' . $rd . ' દિવસથી try નથી થયો — એક વાર try કરી જુઓ, orders વધશે! 💡']);
    }
}
function ct_idea_for(PDO $pdo, int $emp): ?array
{
    if (!ensure_ct_tables($pdo) || !ensure_convo_tables($pdo)) return null;
    $cfg = ct_cfg($pdo);
    try {
        $first = (string)$pdo->query("SELECT MIN(created_at) FROM convo_uploads WHERE status = 'done'")->fetchColumn();
        if (!$first || strtotime($first) > time() - (int)$cfg['ideas']['after_days'] * 86400) return null;        // the HRMS needs 2–3 days of chats to learn first
        $dn = $pdo->prepare("SELECT COUNT(*) FROM ct_idea_state WHERE employee_id = ? AND opened_at >= ?"); $dn->execute([$emp, date('Y-m-d 00:00:00')]);
        if ((int)$dn->fetchColumn() > 0) return null;                  // one new idea a day: today's was already opened
        $best = null;
        foreach ($pdo->query("SELECT * FROM ct_ideas WHERE active = 1 ORDER BY lift DESC")->fetchAll() as $i) {
            $st = $pdo->prepare("SELECT * FROM ct_idea_state WHERE idea_id = ? AND employee_id = ?"); $st->execute([$i['id'], $emp]); $s = $st->fetch();
            if ($s && ($s['adopted_at'] || $s['rigid_at'])) continue;
            $mine = ct_idea_rate($pdo, (string)$i['ikey'], $emp, time() - 21 * 86400, time());
            if ($mine && $mine[0] >= 60) continue;                       // already does it
            if ($s && $s['shown_at'] && strtotime((string)$s['shown_at']) < time() - 20 * 3600 && $s['opened_at'] && !$s['tried_at']) { /* shown before, opened: wait for the tracker */ continue; }
            $best = [$i, $s, $mine]; break;
        }
        if (!$best) return null;
        [$i, $s, $mine] = $best;
        if (!$s) $pdo->prepare("INSERT INTO ct_idea_state (idea_id, employee_id, shown_at, before_val, shows) VALUES (?, ?, NOW(), ?, 1)")->execute([$i['id'], $emp, $mine ? $mine[0] : null]);
        elseif (!$s['shown_at']) $pdo->prepare("UPDATE ct_idea_state SET shown_at = NOW(), before_val = ?, shows = shows + 1 WHERE idea_id = ? AND employee_id = ?")->execute([$mine ? $mine[0] : null, $i['id'], $emp]);
        $ev = json_decode((string)$i['evidence'], true) ?: [];
        return ['id' => (int)$i['id'], 'title' => $i['title'], 'body' => $i['body'], 'why' => $i['why'], 'evidence' => $ev, 'opened' => $s && $s['opened_at'] ? true : false, 'my_rate' => $mine ? $mine[0] : null];
    } catch (Throwable $e) { error_log('ct_idea_for: ' . $e->getMessage()); return null; }
}

// ---------------------------------------------------------------------------------------------------------------------------
// Benchmarks: the top 3 people per measure set the bar; everybody is rated by outcome against it
// ---------------------------------------------------------------------------------------------------------------------------
function ct_benchmarks(PDO $pdo): array
{
    static $memo = null;
    if ($memo !== null) return $memo;
    $cfg = ct_cfg($pdo); $today = biz_today($pdo); $big = (float)$cfg['big_order'];
    $c = coach_day($pdo, $today, true);
    $sale = $GLOBALS['coach_sale_memo'][$today . '1'] ?? [];
    $from = date('Y-m-d', strtotime($today . ' -30 day'));
    $qs = [];
    try { $qs = qa_day_emp($pdo, $from, $today); } catch (Throwable $e) {}          // old typed counts before the cut-over date, WhatsApp Sales from it (never both)
    $per = [];
    foreach ($c['emps'] as $id => $m) {
        $ord = 0; $qn = 0; $days = 0; $cleanS = 0.0; $cleanN = 0; $firstSum = 0.0; $firstN = 0;
        for ($i = 0; $i <= 30; $i++) {
            $d = date('Y-m-d', strtotime($today . " -$i day")); $l = $sale[$d . '|' . $id] ?? []; $q = $qs[$d . '|' . $id] ?? 0;
            if (!$l && !$q) continue;
            $qn += $q;
            if ($l) {
                $days++; $ord += count($l); $ds = strtotime($d . ' ' . day_start_for($pdo, $d) . ':00'); $f = min(array_column($l, 'ts'));
                $firstSum += max(0, ($f - $ds) / 60); $firstN++;
                foreach ($l as $o) if ($o['amt'] <= $big) { $cleanS += $o['amt']; $cleanN++; }
            }
        }
        $per[$id] = ['id' => $id, 'name' => $m['name'], 'days' => $days, 'orders' => $ord, 'queries' => $qn, 'conv' => $qn >= 30 ? round($ord / $qn * 100, 1) : null,
            'ticket' => $cleanN ? round($cleanS / $cleanN) : null, 'speed' => $firstN ? round($firstSum / $firstN) : null, 'volume' => $days ? round($ord / $days, 1) : null];
    }
    $elig = array_filter($per, fn($p) => $p['days'] >= 5);
    $bench = []; $top = [];
    foreach (['conv' => 1, 'ticket' => 1, 'volume' => 1, 'speed' => 0] as $k => $high) {
        $l = array_filter($elig, fn($p) => $p[$k] !== null);
        usort($l, fn($a, $b) => $high ? $b[$k] <=> $a[$k] : $a[$k] <=> $b[$k]);
        $t3 = array_slice($l, 0, 3);
        $bench[$k] = $t3 ? round(array_sum(array_column($t3, $k)) / count($t3), 1) : null;
        $top[$k] = array_map(fn($p) => ['id' => $p['id'], 'name' => trim(preg_replace('/\s+/', ' ', (string)$p['name'])), 'v' => $p[$k]], $t3);
    }
    $w = $cfg['outcome_weights']; $rows = [];
    foreach ($elig as $id => $p) {
        $sc = []; $ws = 0; $sum = 0;
        foreach (['conv', 'ticket', 'volume', 'speed'] as $k) {
            if ($p[$k] === null || !$bench[$k]) continue;
            $s = $k === 'speed' ? ($p[$k] > 0 ? min(10, 10 * $bench[$k] / $p[$k]) : 10) : min(10, 10 * $p[$k] / $bench[$k]);
            $sc[$k] = round($s, 1); $sum += (float)$w[$k] * $s; $ws += (float)$w[$k];
        }
        $rows[] = $p + ['scores' => $sc, 'outcome' => $ws ? round($sum / $ws, 1) : null];
    }
    usort($rows, fn($a, $b) => ($b['outcome'] ?? -1) <=> ($a['outcome'] ?? -1));
    return $memo = ['days' => 30, 'bench' => $bench, 'top3' => $top, 'rows' => $rows, 'weights' => $w];
}

// ---------------------------------------------------------------------------------------------------------------------------
// Salesperson side + theme
// ---------------------------------------------------------------------------------------------------------------------------
function ct_theme(PDO $pdo): array
{
    $c = ct_cfg($pdo); $mode = (string)$c['theme']; $today = date('Y-m-d');
    $on = $mode === 'on' || ($mode === 'auto' && $today >= (string)$c['theme_from'] && $today <= (string)$c['theme_to']);
    return ['on' => $on, 'name' => 'diwali', 'mode' => $mode, 'from' => $c['theme_from'], 'to' => $c['theme_to']];
}
/**
 * Query → order ranking for the Sales Control Tower (visible to everyone in Sales): orders ÷ queries given, today and the last 7 business days,
 * who placed the first order of the day, and suggestions for the admin (who to give more queries to, whose chats to coach first).
 * People with fewer than 5 queries are listed but not ranked (too little to judge). Suggestions only — nothing is assigned automatically.
 */
function ct_leaders(PDO $pdo, array $S, string $day): array
{
    $emps = rating_emps($pdo); if (!$emps) return ['today' => [], 'week' => [], 'tips' => []];
    $from = date('Y-m-d', strtotime($day . ' -6 day'));
    $wq = []; $wo = []; $wc = [];
    try {
        $wq = qa_emp_total($pdo, $from, $day);          // old typed counts before the cut-over date, WhatsApp Sales from it (never both)
        $sale = coach_sales_load($pdo, $emps, $from, $day);
        $commSet = [];          // community / campaign orders are NOT query orders — left out of the query → order ratio
        if (ensure_order_community_table($pdo)) { try { foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $r) $commSet[$r['source'] . '|' . $r['order_id']] = 1; } catch (Throwable $e2) {} }
        foreach ($sale as $k => $l) {
            $id = (int)substr($k, strpos($k, '|') + 1);
            foreach ($l as $x) { if (isset($commSet[$x['key']]) || ($x['type'] ?? '') === 'campaign') $wc[$id] = ($wc[$id] ?? 0) + 1; else $wo[$id] = ($wo[$id] ?? 0) + 1; }
        }
    } catch (Throwable $e) {}
    $MIN = 5;
    $mk = function (array $rows) use ($MIN): array {
        $tq = array_sum(array_column($rows, 'queries')); $to = array_sum(array_column($rows, 'orders'));
        usort($rows, function ($a, $b) use ($MIN) {
            $ra = $a['queries'] >= $MIN; $rb = $b['queries'] >= $MIN;
            if ($ra !== $rb) return $ra ? -1 : 1;
            return (($b['conv'] ?? -1) <=> ($a['conv'] ?? -1)) ?: ($b['orders'] <=> $a['orders']);
        });
        $rank = 0;
        foreach ($rows as &$r) { $r['rank'] = ($r['queries'] >= $MIN) ? ++$rank : null; }
        unset($r);
        return ['rows' => $rows, 'team_conv' => $tq > 0 ? round($to / $tq * 100, 1) : null, 'queries' => $tq, 'orders' => $to];
    };
    $today = []; $week = [];
    foreach ($S['emps'] as $id => $e) $today[] = ['id' => (int)$id, 'name' => $e['name'], 'queries' => (int)$e['queries'], 'orders' => (int)$e['qo'], 'comm' => (int)$e['co'], 'conv' => $e['queries'] > 0 ? round((int)$e['qo'] / $e['queries'] * 100, 1) : null, 'first_order' => $e['first_order'], 'elapsed_h' => (float)$e['elapsed_h']];
    foreach ($emps as $id => $e) {
        $q = (int)($wq[$id] ?? 0); $o = (int)($wo[$id] ?? 0);
        $cm = (int)($wc[$id] ?? 0);
        if ($q === 0 && $o === 0 && $cm === 0) continue;
        $week[] = ['id' => (int)$id, 'name' => trim((string)$e['full_name']), 'queries' => $q, 'orders' => $o, 'comm' => $cm, 'conv' => $q > 0 ? round($o / $q * 100, 1) : null];
    }
    $T = $mk($today); $W = $mk($week);
    // the first order of the day = earliest first_order time
    $firstId = null; $firstT = null;
    foreach ($T['rows'] as $r) if ($r['first_order'] && ($firstT === null || $r['first_order'] < $firstT)) { $firstT = $r['first_order']; $firstId = $r['id']; }
    foreach ($T['rows'] as &$r) $r['first'] = $firstId !== null && $r['id'] === $firstId;
    unset($r);
    // suggestions (week ratio = steadier; today's queries per hour = how many more to give)
    $tips = []; $tc = $W['team_conv'];
    $perHr = []; foreach ($T['rows'] as $r) $perHr[$r['id']] = $r['elapsed_h'] > 0 ? $r['queries'] / $r['elapsed_h'] : 0;
    if ($tc !== null && $tc > 0) foreach ($W['rows'] as $r) {
        if ($r['queries'] < 20 || $r['conv'] === null) continue;
        $extra = max(2, (int)round(($perHr[$r['id']] ?? 0) * 0.3));
        if ($r['conv'] >= $tc * 1.25) $tips[] = ['kind' => 'more', 'id' => $r['id'], 'name' => $r['name'], 'conv' => $r['conv'], 'team' => $tc, 'extra' => $extra,
            'text' => $r['name'] . ' turns ' . $r['conv'] . '% of queries into orders (team ' . $tc . '%) → give about ' . $extra . ' more queries per hour.'];
        elseif ($r['conv'] <= $tc * 0.55) $tips[] = ['kind' => 'coach', 'id' => $r['id'], 'name' => $r['name'], 'conv' => $r['conv'], 'team' => $tc, 'extra' => 0,
            'text' => $r['name'] . ' converts only ' . $r['conv'] . '% (team ' . $tc . '%) → coach before giving more queries.'];
    }
    usort($tips, fn($a, $b) => ($a['kind'] === $b['kind'] ? 0 : ($a['kind'] === 'more' ? -1 : 1)) ?: ($b['conv'] <=> $a['conv']));
    return ['day' => $day, 'from' => $from, 'min' => $MIN, 'today' => $T, 'week' => $W, 'tips' => array_slice($tips, 0, 8)];
}
// ===================== ☀️ Morning Focus: who to talk to today, and about what =====================
// Built ONCE each business day from the day that just closed (rating by section + query → order ratio) and saved, so the "Talked ✅ + comment" stays.
// Groups: talk (rating under 5.5), check (5.5 – 7 with a weak section), praise (7+). The next morning each person also shows how last focus moved.
function ct_focus_do(string $k): string
{
    $m = ['code' => 'Ask for the code on every order — full commission needs the code goal.', 'community' => 'Push at least 1 community / campaign order today.',
        'target' => 'Call back every query and keep pace with the target through the day.', 'ticket' => 'Suggest a bigger size or one more bottle as an add-on to lift the ticket.', 'price' => 'Hold the price — avoid low-price slabs and big discounts.',
        'orders' => 'Follow up the pending queries to add more orders.', 'discipline' => 'Punch in on time every day.',
        'addon' => 'Add one more on every order — an extra bottle, a bigger size or a 10 ml piece.', 'prepaid' => 'Push prepaid — explain the prepaid benefit.',
        'consistency' => 'Hit the target every day, not once in a while.', 'conv' => 'Listen to how the chats are handled and coach before giving more queries.'];
    return $m[$k] ?? 'Talk about this and agree one small step for today.';
}
function ct_focus_build(PDO $pdo, string $day): void
{
    if (!ensure_ct_tables($pdo)) return;
    $q = $pdo->prepare("SELECT COUNT(*) FROM ct_focus WHERE day = ?"); $q->execute([$day]);
    if ((int)$q->fetchColumn() > 0) return;
    @set_time_limit(180);
    $y = date('Y-m-d', strtotime($day . ' -1 day')); $y2 = date('Y-m-d', strtotime($day . ' -2 day'));
    $days = rating_days($pdo, $y2, $y); $emps = rating_emps($pdo); $P = rating_parts();
    if (empty($days[$y])) return;
    // query → order ratio of yesterday (community / campaign orders are not query orders)
    $qs = []; $qo = [];
    try {
        $qs = qa_emp_total($pdo, $y, $y);          // old typed counts before the cut-over date, WhatsApp Sales from it (never both)
        $commSet = [];
        if (ensure_order_community_table($pdo)) foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $x) $commSet[$x['source'] . '|' . $x['order_id']] = 1;
        foreach (coach_sales_load($pdo, $emps, $y, $y) as $k => $l) {
            $id = (int)substr($k, strpos($k, '|') + 1);
            foreach ($l as $o) if (!isset($commSet[$o['key']]) && ($o['type'] ?? '') !== 'campaign') $qo[$id] = ($qo[$id] ?? 0) + 1;
        }
    } catch (Throwable $e) {}
    $tq = array_sum($qs); $to = array_sum($qo); $teamConv = $tq > 0 ? $to / $tq * 100 : null;
    // team average per part (for "best in the team")
    $avg = []; $cnt = []; $best = [];
    foreach ($days[$y] as $id => $x) foreach ($x['parts'] as $k => $v) if ($v !== null) { $avg[$k] = ($avg[$k] ?? 0) + $v; $cnt[$k] = ($cnt[$k] ?? 0) + 1; if (!isset($best[$k]) || $v > $best[$k]) $best[$k] = $v; }
    // last focus day's items (to show what moved)
    $pf = []; $pd = $pdo->prepare("SELECT MAX(day) FROM ct_focus WHERE day < ?"); $pd->execute([$day]); $pday = (string)$pd->fetchColumn();
    if ($pday !== '') { $r = $pdo->prepare("SELECT employee_id, items, status FROM ct_focus WHERE day = ?"); $r->execute([$pday]); foreach ($r->fetchAll() as $x) $pf[(int)$x['employee_id']] = ['items' => json_decode((string)$x['items'], true) ?: [], 'done' => $x['status'] === 'done']; }
    $ins = $pdo->prepare("INSERT INTO ct_focus (day, employee_id, grp, score, prev_score, items, progress, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'open', NOW())");
    foreach ($days[$y] as $id => $x) {
        if (!isset($emps[$id]) || $x['score'] === null) continue;
        $score = (float)$x['score']; $prev = isset($days[$y2][$id]['score']) && $days[$y2][$id]['score'] !== null ? (float)$days[$y2][$id]['score'] : null;
        $weak = [];
        foreach ($x['parts'] as $k => $v) if ($v !== null && $v < 6 && isset($P[$k])) $weak[$k] = $P[$k]['w'] * (8 - $v);
        arsort($weak);
        $items = [];
        foreach (array_slice(array_keys($weak), 0, 2) as $k) {
            $v = (float)$x['parts'][$k];
            $items[] = ['k' => $k, 'icon' => $P[$k]['icon'], 'label' => $P[$k]['label'], 'val' => $v, 'why' => (string)($x['notes'][$k] ?? ($P[$k]['label'] . ' ' . $v . ' / 10')), 'do' => ct_focus_do($k)];
        }
        $qn = $qs[$id] ?? 0; $on = $qo[$id] ?? 0; $conv = $qn > 0 ? $on / $qn * 100 : null;
        if ($teamConv !== null && $conv !== null && $qn >= 15 && $teamConv > 0 && $conv <= $teamConv * 0.55 && count($items) < 3)
            $items[] = ['k' => 'conv', 'icon' => '🏁', 'label' => 'Query → order', 'val' => round($conv, 1), 'why' => 'Only ' . round($conv, 1) . '% of queries became orders (team ' . round($teamConv, 1) . '%).', 'do' => ct_focus_do('conv')];
        $grp = $score < 5.5 ? 'talk' : ($score >= 7 ? 'praise' : 'check');
        if ($grp === 'praise' || ($teamConv !== null && $conv !== null && $qn >= 15 && $conv >= $teamConv * 1.25 && $score >= 6.5)) {
            // praise: the strongest part (9+), best in the team when it is
            arsort($x['parts']); $bk = null; foreach ($x['parts'] as $k => $v) if ($v !== null && $v >= 9 && isset($P[$k])) { $bk = $k; break; }
            $praise = [];
            if ($bk) $praise[] = ['k' => 'praise', 'icon' => '🌟', 'label' => $P[$bk]['label'], 'val' => (float)$x['parts'][$bk], 'why' => $P[$bk]['label'] . ' ' . $x['parts'][$bk] . ' / 10' . (abs(($best[$bk] ?? 0) - $x['parts'][$bk]) < 0.05 ? ' — best in the team' : ' — excellent'), 'do' => 'Appreciate them in the team group today.'];
            elseif ($prev !== null && $score - $prev >= 0.8) $praise[] = ['k' => 'praise', 'icon' => '📈', 'label' => 'Rating up', 'val' => $score, 'why' => 'Rating ' . $prev . ' → ' . $score . ' since the day before.', 'do' => 'Appreciate the improvement today.'];
            else $praise[] = ['k' => 'praise', 'icon' => '💪', 'label' => 'Strong day', 'val' => $score, 'why' => 'Rating ' . $score . ' / 10 yesterday.', 'do' => 'Appreciate them in the team group today.'];
            if ($grp !== 'praise') { $grp = 'praise'; }
            $items = array_merge($praise, $grp === 'praise' ? array_slice($items, 0, 1) : []);
        }
        if (!$items) continue;
        // what moved since last focus (value on the closed day vs the value when it was set)
        $prog = [];
        foreach ($pf[$id]['items'] ?? [] as $it) {
            if (!isset($it['k']) || in_array($it['k'], ['praise', 'conv'], true) || !isset($x['parts'][$it['k']]) || $x['parts'][$it['k']] === null) continue;
            $to2 = (float)$x['parts'][$it['k']]; $d2 = $to2 - (float)$it['val'];
            $prog[] = ['k' => $it['k'], 'label' => $it['label'], 'from' => (float)$it['val'], 'to' => $to2, 'state' => $d2 >= 1 ? 'up' : ($d2 <= -1 ? 'down' : 'same'), 'talked' => !empty($pf[$id]['done'])];
        }
        $ins->execute([$day, $id, $grp, $score, $prev, json_encode($items, JSON_UNESCAPED_UNICODE), json_encode($prog, JSON_UNESCAPED_UNICODE)]);
    }
}
/** Remarks the sales head sent to this salesperson that they have not pressed "Got it" on yet. */
function ct_remarks_unseen(PDO $pdo, int $emp): array
{
    if ($emp <= 0 || !ensure_ct_tables($pdo)) return [];
    try {
        $q = $pdo->prepare("SELECT id, from_name, src, body, created_at FROM ct_remarks WHERE employee_id = ? AND seen_at IS NULL ORDER BY id DESC LIMIT 5"); $q->execute([$emp]);
        return array_map(fn($r) => ['id' => (int)$r['id'], 'from' => (string)$r['from_name'], 'src' => (string)$r['src'], 'body' => (string)$r['body'], 'at' => substr((string)$r['created_at'], 11, 5)], $q->fetchAll());
    } catch (Throwable $e) { return []; }
}
/** Full name of the logged-in person (who sent a remark / who changed a count). */
function ct_who(PDO $pdo, array $auth): array
{
    $who = (string)($auth['username'] ?? 'admin'); $eid = (int)($auth['employee_id'] ?? 0);
    if ($eid > 0) { try { $fq = $pdo->prepare("SELECT full_name FROM employees WHERE employee_id = ?"); $fq->execute([$eid]); $fn = trim((string)$fq->fetchColumn()); if ($fn !== '') $who = mb_substr($fn, 0, 95); } catch (Throwable $e) {} }
    return [$eid, $who];
}
/** Who may use Query Boost / Rudra: Admin, HR, Control Tower tick, named resolver, or anyone with the Orders page controls. */
function qb_ok(PDO $pdo, array $auth): bool
{
    return ct_admin_ok($pdo, $auth) || orders_page_controls($auth) || in_array(($auth['role'] ?? ''), ['Admin', 'HR'], true);
}
/** Sales people (active) as [id => name]. */
/** Campaign queries (AiSensy campaign replies), counted per person per business day, in two kinds: 'in' = already in his chat, 'new' = a new customer assigned to him. Never part of the fresh-query ratio. */
function ensure_cq_table(PDO $pdo): bool
{
    static $ok = null; if ($ok !== null) return $ok; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) { $ok = true; return $ok; }
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS campaign_queries (employee_id INT NOT NULL, cq_date DATE NOT NULL, kind VARCHAR(4) NOT NULL, n INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, PRIMARY KEY (employee_id, cq_date, kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        // which kind of campaign / community query each community order came from: 'in' = already in her chat, 'new' = new query assigned, 'comm' = community query
        $pdo->exec("CREATE TABLE IF NOT EXISTS order_qsrc (source VARCHAR(20) NOT NULL, order_id VARCHAR(40) NOT NULL, qsrc VARCHAR(4) NOT NULL, updated_by VARCHAR(100) NOT NULL DEFAULT '', updated_at DATETIME NOT NULL, PRIMARY KEY (source, order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['campaign_queries', 'order_qsrc']); return $ok = true;
    } catch (PDOException $e) { return $ok = false; }
}
/** "source|order_id" => 'in' | 'new' | 'comm' for every community order that was tagged with its query kind. */
function cq_qsrc_map(PDO $pdo): array
{
    $o = [];
    try { if (ensure_cq_table($pdo)) foreach ($pdo->query("SELECT source, order_id, qsrc FROM order_qsrc")->fetchAll() as $r) $o[$r['source'] . '|' . $r['order_id']] = (string)$r['qsrc']; } catch (Throwable $e) {}
    return $o;
}
/** Active Sales people with the columns coach_sales_load() needs: id => row. */
function cq_sales_emps(PDO $pdo): array
{
    $se = [];
    foreach ($pdo->query("SELECT e.employee_id, e.full_name, e.sales_tag, e.basic_salary, e.joining_date, e.designation, d.department_name FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex'")->fetchAll() as $x) {
        if (stripos((string)$x['department_name'], 'sales') === false) continue; $se[(int)$x['employee_id']] = $x;
    }
    return $se;
}
/** Community / campaign orders of a range (campaign type or ticked Community = Yes): [ ['key','day','emp','name','amt','ts','qs'] ... ], qs = '' when not tagged yet. */
function cq_comm_orders(PDO $pdo, string $from, string $to): array
{
    $se = cq_sales_emps($pdo); $cm = []; $out = [];
    if (ensure_order_community_table($pdo)) { try { foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $x) $cm[$x['source'] . '|' . $x['order_id']] = 1; } catch (Throwable $e) {} }
    $qm = cq_qsrc_map($pdo);
    foreach (coach_sales_load($pdo, $se, $from, $to) as $k => $lst) {
        $day = substr($k, 0, 10); $eid = (int)substr($k, strpos($k, '|') + 1);
        foreach ($lst as $x) if (isset($cm[$x['key']]) || (string)($x['type'] ?? '') === 'campaign')
            $out[] = ['key' => $x['key'], 'day' => $day, 'emp' => $eid, 'name' => (string)$x['name'], 'amt' => (float)$x['amt'], 'ts' => (int)$x['ts'], 'qs' => $qm[$x['key']] ?? ''];
    }
    return $out;
}
/** ⇄ Move queries. A query given to Y can be moved to Z. Y keeps it in his count ("not performed") unless the move is waived ("not Y's fault"); Z is never blamed for received queries — they count for Z only when they turn into an order (orders tagged ↪). */
function ensure_qm_tables(PDO $pdo): bool
{
    static $ok = null; if ($ok !== null) return $ok; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) { $ok = true; return $ok; }
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS query_moves (id INT AUTO_INCREMENT PRIMARY KEY, mv_day DATE NOT NULL, kind VARCHAR(5) NOT NULL, from_emp INT NOT NULL, to_emp INT NOT NULL, n INT NOT NULL DEFAULT 1, reason VARCHAR(12) NOT NULL DEFAULT '', waive TINYINT NOT NULL DEFAULT 0, by_name VARCHAR(100) NOT NULL DEFAULT '', created_at DATETIME NOT NULL, KEY k_day (mv_day), KEY k_from (from_emp, mv_day), KEY k_to (to_emp, mv_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        try { $pdo->exec("ALTER TABLE query_moves ADD COLUMN applied TINYINT NOT NULL DEFAULT 0"); } catch (PDOException $e) { /* already there */ }   // 1 = the queries were really moved from one person's count to the other's
        $pdo->exec("CREATE TABLE IF NOT EXISTS order_moved (source VARCHAR(20) NOT NULL, order_id VARCHAR(40) NOT NULL, updated_by VARCHAR(100) NOT NULL DEFAULT '', updated_at DATETIME NOT NULL, PRIMARY KEY (source, order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['query_moves', 'order_moved']); return $ok = true;
    } catch (PDOException $e) { return $ok = false; }
}
/** Moves of a date range per person: [emp => ['out' => [kind => n], 'out_w' => [kind => n] (waived), 'in' => [kind => n]]]. Kinds: fresh | in | new | comm. */
function qm_range(PDO $pdo, string $from, string $to): array
{
    $o = [];
    $cut = qa_cut($pdo); if ($cut !== '' && $cut <= $to) $to = date('Y-m-d', strtotime($cut . ' -1 day'));          // old typed moves count only for days before the cut-over date
    if ($from > $to) return [];
    try {
        if (!ensure_qm_tables($pdo)) return [];
        // A move with applied = 1 REALLY moved the queries (the sender's count went down, the receiver's went up in the database), so nothing has to be
        // adjusted on top: it is only listed as "moved out" for information. Older moves (applied = 0) keep the old rules (sender keeps them unless waived).
        $q = $pdo->prepare("SELECT from_emp, to_emp, kind, SUM(n) AS n, SUM(CASE WHEN applied = 0 THEN n ELSE 0 END) AS n_open, SUM(CASE WHEN waive = 1 AND applied = 0 THEN n ELSE 0 END) AS w FROM query_moves WHERE mv_day BETWEEN ? AND ? GROUP BY from_emp, to_emp, kind"); $q->execute([$from, $to]);
        foreach ($q->fetchAll() as $r) {
            $k = (string)$r['kind']; $f = (int)$r['from_emp']; $t = (int)$r['to_emp'];
            $o[$f]['out'][$k] = ($o[$f]['out'][$k] ?? 0) + (int)$r['n']; $o[$f]['out_w'][$k] = ($o[$f]['out_w'][$k] ?? 0) + (int)$r['w']; $o[$t]['in'][$k] = ($o[$t]['in'][$k] ?? 0) + (int)$r['n_open'];
        }
    } catch (Throwable $e) {}
    return $o;
}
/** "source|order_id" => 1 for every order tagged ↪ (it came from a moved query). */
function qm_orders_set(PDO $pdo): array
{
    $o = [];
    try { if (ensure_qm_tables($pdo)) foreach ($pdo->query("SELECT source, order_id FROM order_moved")->fetchAll() as $r) $o[$r['source'] . '|' . $r['order_id']] = 1; } catch (Throwable $e) {}
    return $o;
}
/** Which kind of query a ↪ order belongs to: fresh (a normal query order), or the tagged campaign kind (untagged community order = community). */
function qm_order_kind(string $key, bool $isComm, array $qsMap): string
{
    if (!$isComm) return 'fresh';
    $k = (string)($qsMap[$key] ?? '');
    return in_array($k, ['in', 'new', 'comm'], true) ? $k : 'comm';
}
/** Orders from moved queries per person and kind over a range (campaign kinds only; fresh ones are counted in ct_snapshot): [emp => [kind => n]]. */
function qm_rescued_comm(PDO $pdo, string $from, string $to): array
{
    $o = []; $set = qm_orders_set($pdo); if (!$set) return [];
    try { foreach (cq_comm_orders($pdo, $from, $to) as $x) if (isset($set[$x['key']])) { $k = in_array($x['qs'], ['in', 'new', 'comm'], true) ? $x['qs'] : 'comm'; $o[$x['emp']][$k] = ($o[$x['emp']][$k] ?? 0) + 1; } } catch (Throwable $e) {}
    return $o;
}
/**
 * Really moves $n queries of one kind from one person to another on a day (or takes the move back when $undo): the sender's number goes down and the
 * receiver's goes up in the database, so a query is never shown under both people. fresh = the Give queries counts (employee_queries, with the by-hour log);
 * in / new / comm = the campaign counts (campaign_queries). Call inside a transaction; ensure_* tables must already exist.
 */
function qm_transfer(PDO $pdo, string $date, string $kind, int $from, int $to, int $n, bool $undo = false): void
{
    if ($n < 1) return;
    if ($undo) { $t = $from; $from = $to; $to = $t; }     // taking a move back = moving the same number the other way
    if ($kind === 'fresh') {
        qb_apply($pdo, $from, $date, -$n, null);
        qb_apply($pdo, $to, $date, $n, null);
        return;
    }
    $pdo->prepare("UPDATE campaign_queries SET n = GREATEST(0, n - ?), updated_at = NOW() WHERE employee_id = ? AND cq_date = ? AND kind = ?")->execute([$n, $from, $date, $kind]);
    $pdo->prepare("INSERT INTO campaign_queries (employee_id, cq_date, kind, n, updated_at) VALUES (?, ?, ?, ?, NOW()) ON DUPLICATE KEY UPDATE n = n + ?, updated_at = NOW()")->execute([$to, $date, $kind, $n, $n]);
}
/** How many queries of a kind a person has today that have not been moved away yet. */
function qm_avail(PDO $pdo, string $day, string $kind, int $emp): int
{
    if (!qa_old_day($pdo, $day)) return 0;          // old typed moves ended on the cut-over date
    $raw = 0;
    try {
        if ($kind === 'fresh') { $q = $pdo->prepare("SELECT COALESCE(SUM(GREATEST(0, query_count - champion_count)), 0) FROM employee_queries WHERE employee_id = ? AND query_date = ?"); $q->execute([$emp, $day]); $raw = (int)$q->fetchColumn(); }
        elseif (ensure_cq_table($pdo)) { $q = $pdo->prepare("SELECT COALESCE(SUM(n), 0) FROM campaign_queries WHERE employee_id = ? AND cq_date = ? AND kind = ?"); $q->execute([$emp, $day, $kind]); $raw = (int)$q->fetchColumn(); }
        $m = $pdo->prepare("SELECT COALESCE(SUM(n), 0) FROM query_moves WHERE from_emp = ? AND mv_day = ? AND kind = ? AND applied = 0"); $m->execute([$emp, $day, $kind]); $raw -= (int)$m->fetchColumn();
    } catch (Throwable $e) {}
    return max(0, $raw);
}
/** Best people to receive moved queries of a kind: working people, best ratio first. */
function qm_suggest(PDO $pdo, string $day, string $kind, int $from): array
{
    $S = ct_snapshot($pdo, $day); $out = [];
    foreach ($S['emps'] as $id => $e) {
        if ((int)$id === $from || empty($e['working'])) continue;
        if ($kind === 'fresh') { $q = (int)$e['queries']; $o = (int)$e['orders']; }
        else { $q = (int)$e['cq_' . $kind]; $o = (int)$e['co_' . $kind]; }
        $out[] = ['id' => (int)$id, 'name' => (string)$e['name'], 'q' => $q, 'o' => $o, 'ratio' => $q >= 3 ? round($o / $q * 100, 1) : null];
    }
    usort($out, fn($a, $b) => (($b['ratio'] ?? -1) <=> ($a['ratio'] ?? -1)) ?: strcmp($a['name'], $b['name']));
    foreach ($out as $i => &$r) $r['best'] = $i === 0; unset($r);
    return array_slice($out, 0, 5);
}
function qb_people(PDO $pdo): array
{
    $o = [];
    foreach ($pdo->query("SELECT e.employee_id, e.full_name FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex' AND d.department_name LIKE '%sales%' ORDER BY e.full_name")->fetchAll() as $r) $o[(int)$r['employee_id']] = trim((string)$r['full_name']);
    return $o;
}
/**
 * Query Boost: ONE query count per person (shower gel + normal queries are the same thing — campaign kind is not a query).
 * delta > 0 goes to the person's biggest row of the day, delta < 0 is taken away from the rows that have queries. Every change is logged
 * in the hour it belongs to (By-hour list). Returns the new day total.
 */
function qb_apply(PDO $pdo, int $emp, string $date, int $delta, ?int $hour): int
{
    ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
    ensure_query_log_table($pdo);
    $rows = $pdo->prepare("SELECT group_key, scout_count FROM employee_queries WHERE employee_id = ? AND query_date = ? ORDER BY scout_count DESC");
    $rows->execute([$emp, $date]); $rows = $rows->fetchAll();
    $stamp = $hour === null ? date('Y-m-d H:i:s') : query_hour_stamp($pdo, $date, $hour);
    $log = function (string $gk, int $d) use ($pdo, $date, $emp, $stamp) {
        while ($d !== 0) {                       // delta column is TINYINT: log in chunks
            $c = max(-100, min(100, $d)); $d -= $c;
            try { $pdo->prepare("INSERT INTO employee_query_log (query_date, group_key, employee_id, kind, delta, created_at) VALUES (?, ?, ?, 'scout', ?, ?)")->execute([$date, $gk, $emp, $c, $stamp]); } catch (PDOException $e) {}
        }
    };
    if ($delta > 0) {
        $gk = $rows ? (string)$rows[0]['group_key'] : '';
        $pdo->prepare("INSERT INTO employee_queries (employee_id, query_date, group_key, query_count, scout_count) VALUES (?, ?, ?, ?, ?)
                       ON DUPLICATE KEY UPDATE scout_count = scout_count + ?, query_count = scout_count + champion_count")->execute([$emp, $date, $gk, $delta, $delta, $delta]);
        $pdo->prepare("UPDATE employee_queries SET query_count = scout_count + champion_count WHERE employee_id = ? AND query_date = ? AND group_key = ?")->execute([$emp, $date, $gk]);
        $log($gk, $delta);
    } elseif ($delta < 0) {
        $left = -$delta;
        foreach ($rows as $r) {
            if ($left <= 0) break;
            $take = min($left, (int)$r['scout_count']); if ($take <= 0) continue;
            $pdo->prepare("UPDATE employee_queries SET scout_count = GREATEST(0, scout_count - ?) WHERE employee_id = ? AND query_date = ? AND group_key = ?")->execute([$take, $emp, $date, (string)$r['group_key']]);
            $pdo->prepare("UPDATE employee_queries SET query_count = scout_count + champion_count WHERE employee_id = ? AND query_date = ? AND group_key = ?")->execute([$emp, $date, (string)$r['group_key']]);
            $log((string)$r['group_key'], -$take); $left -= $take;
        }
    }
    $t = $pdo->prepare("SELECT COALESCE(SUM(GREATEST(0, query_count - champion_count)), 0) FROM employee_queries WHERE employee_id = ? AND query_date = ?");
    $t->execute([$emp, $date]);
    return (int)$t->fetchColumn();
}
function qb_total(PDO $pdo, int $emp, string $date): int
{
    $t = $pdo->prepare("SELECT COALESCE(SUM(GREATEST(0, query_count - champion_count)), 0) FROM employee_queries WHERE employee_id = ? AND query_date = ?");
    $t->execute([$emp, $date]);
    return (int)$t->fetchColumn();
}
function qb_hour_n(PDO $pdo, string $date, int $emp, int $hour): int
{
    try {
        $st = $pdo->prepare("SELECT COALESCE(SUM(delta), 0) FROM employee_query_log WHERE query_date = ? AND employee_id = ? AND kind = 'scout' AND HOUR(created_at) = " . (int)$hour);
        $st->execute([$date, $emp]); return max(0, (int)$st->fetchColumn());
    } catch (PDOException $e) { return 0; }
}

/**
 * 🧭 Query planner — how many queries each person should get in the hour running now (shown on the same line as − / number / + in "Give queries").
 *  - Past 14 days + today decide each person's query → order ratio (pulled towards the team ratio while the sample is small).
 *  - Base = the person's usual queries per hour (never below the "basic" count, setting qb_base_per_hour, default 3).
 *  - Top converters get more, weak ones less; ordering in the last 2 hours = "hot" (+); no order yet but good history = "due" (keep giving);
 *    weak history and still no order = "hold" (coach first); fewer than 10 past queries = "new" (basic count).
 *  - What was suggested for the hour before and not given is carried into this hour.
 *  - After 2+ hours the team's real ratio is compared with the past: more than 15% off = every suggestion is moved by half of that (max −20% / +25%).
 * The latest suggestion of each hour is saved (qb_plan) so the next hour can carry the rest forward.
 */
function ensure_qb_plan_table(PDO $pdo): bool
{
    static $ok = null; if ($ok !== null) return $ok; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) { $ok = true; return $ok; }
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS qb_plan (plan_date DATE NOT NULL, hr TINYINT NOT NULL, employee_id INT NOT NULL, suggested INT NOT NULL DEFAULT 0, tag VARCHAR(10) NOT NULL DEFAULT '', saved_at DATETIME NOT NULL, PRIMARY KEY (plan_date, hr, employee_id))");
        if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['qb_plan']); return $ok = true;
    } catch (PDOException $e) { return $ok = false; }
}
function qb_plan(PDO $pdo, string $date, array $people, array $snapEmps): ?array
{
    if (!qa_old_day($pdo, $date)) return null;          // the planner belongs to the old typed counts (ended on the cut-over date)
    if ($date !== biz_today($pdo) || !$people) return null;
    $nowH = (int)date('G'); $base = max(1, (int)setting_get($pdo, 'qb_base_per_hour', '3'));
    $hFrom = date('Y-m-d', strtotime($date . ' -14 day')); $hTo = date('Y-m-d', strtotime($date . ' -1 day'));
    $emps = rating_emps($pdo);
    // --- history: queries, orders, queries per active hour, order hours
    $hq = []; $hd = []; $ho = []; $hOrdHour = array_fill(0, 24, 0); $hOrdTot = 0; $hOrdDays = [];
    try {
        $q = $pdo->prepare("SELECT employee_id, SUM(GREATEST(0, query_count - champion_count)) AS n, COUNT(DISTINCT CASE WHEN query_count - champion_count > 0 THEN query_date END) AS d FROM employee_queries WHERE query_date BETWEEN ? AND ? GROUP BY employee_id"); $q->execute([$hFrom, $hTo]);
        foreach ($q->fetchAll() as $r) { $hq[(int)$r['employee_id']] = (int)$r['n']; $hd[(int)$r['employee_id']] = (int)$r['d']; }
    } catch (Throwable $e) {}
    $ph = []; $pa = [];          // queries per active hour: [emp => [sum, hours]]
    try {
        ensure_query_log_table($pdo);
        $q = $pdo->prepare("SELECT employee_id, SUM(n) AS s, COUNT(*) AS h FROM (SELECT employee_id, query_date, HOUR(created_at) AS hr, SUM(delta) AS n FROM employee_query_log WHERE kind = 'scout' AND query_date BETWEEN ? AND ? GROUP BY employee_id, query_date, HOUR(created_at)) t WHERE n > 0 GROUP BY employee_id");
        $q->execute([$hFrom, $hTo]);
        foreach ($q->fetchAll() as $r) $ph[(int)$r['employee_id']] = (float)$r['s'] / max(1, (int)$r['h']);
    } catch (Throwable $e) {}
    $commSet = [];
    if (ensure_order_community_table($pdo)) { try { foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $r) $commSet[$r['source'] . '|' . $r['order_id']] = 1; } catch (Throwable $e2) {} }
    $isComm = fn($x) => isset($commSet[$x['key']]) || ($x['type'] ?? '') === 'campaign';
    if ($emps) {
        try {
            foreach (coach_sales_load($pdo, $emps, $hFrom, $hTo) as $k => $l) {
                $id = (int)substr($k, strpos($k, '|') + 1);
                foreach ($l as $x) if (!$isComm($x)) { $ho[$id] = ($ho[$id] ?? 0) + 1; $hOrdHour[(int)date('G', $x['ts'])]++; $hOrdTot++; $hOrdDays[substr($k, 0, strpos($k, '|'))] = 1; }
            }
        } catch (Throwable $e) {}
    }
    $tq = array_sum($hq); $to = array_sum($ho); $teamC = $tq >= 30 && $to > 0 ? $to / $tq : null;
    // --- today: last order time and orders in the last 2 hours
    $last2 = []; $now = time();
    if ($emps) {
        try {
            foreach (coach_sales_load($pdo, $emps, $date, $date) as $k => $l) {
                $id = (int)substr($k, strpos($k, '|') + 1);
                foreach ($l as $x) if (!$isComm($x) && $x['ts'] >= $now - 7200) $last2[$id] = ($last2[$id] ?? 0) + 1;
            }
        } catch (Throwable $e) {}
    }
    // --- given this hour / last hour, and last hour's saved suggestion
    $seq = biz_hour_sequence($pdo, $date); $ix = array_search($nowH, $seq, true); $prevH = ($ix !== false && $ix > 0) ? $seq[$ix - 1] : null;
    $given = []; $prevGiven = [];
    try {
        $q = $pdo->prepare("SELECT employee_id, HOUR(created_at) AS h, SUM(delta) AS n FROM employee_query_log WHERE query_date = ? AND kind = 'scout' GROUP BY employee_id, HOUR(created_at)"); $q->execute([$date]);
        foreach ($q->fetchAll() as $r) { if ((int)$r['h'] === $nowH) $given[(int)$r['employee_id']] = max(0, (int)$r['n']); elseif ($prevH !== null && (int)$r['h'] === $prevH) $prevGiven[(int)$r['employee_id']] = max(0, (int)$r['n']); }
    } catch (Throwable $e) {}
    $prevPlan = []; $savedNow = [];
    if (ensure_qb_plan_table($pdo)) {
        try {
            if ($prevH !== null) { $q = $pdo->prepare("SELECT employee_id, suggested FROM qb_plan WHERE plan_date = ? AND hr = ?"); $q->execute([$date, $prevH]); foreach ($q->fetchAll() as $r) $prevPlan[(int)$r['employee_id']] = (int)$r['suggested']; }
        } catch (Throwable $e) {}
    }
    // --- flow: today's real ratio against the past one, once 2+ hours are gone
    $ds = ct_clock_ts($pdo, $date, substr(day_start_for($pdo, $date), 0, 5)); $elapsed = max(0.0, ($now - $ds) / 3600);
    $dq = 0; $dord = 0; foreach ($snapEmps as $e) { $dq += (int)($e['queries'] ?? 0); $dord += (int)($e['qo'] ?? 0); }
    $flow = null; $factor = 1.0;
    if ($teamC !== null && $elapsed >= 2 && $dq >= 15) {
        $flow = round((($dord / $dq) / $teamC - 1) * 100);
        if (abs($flow) >= 15) $factor = max(0.8, min(1.25, 1 + $flow / 100 * 0.5));
    }
    // --- per person
    $rows = [];
    foreach ($people as $id => $nm) {
        $e = $snapEmps[$id] ?? []; $tqn = (int)($e['queries'] ?? 0); $tor = (int)($e['qo'] ?? 0);
        $pq = (int)($hq[$id] ?? 0) + $tqn; $po = (int)($ho[$id] ?? 0) + $tor;          // history + today in one pool
        $k = 20; $tc = $teamC ?? 0.15;
        $conv = ($po + $k * $tc) / ($pq + $k);                                          // pulled towards the team ratio while the sample is small
        $r = $tc > 0 ? $conv / $tc : 1.0;
        $usual = isset($ph[$id]) ? (int)round($ph[$id]) : $base; $hb = max($base, min(12, $usual));
        $tag = 'ok'; $mult = 1.0; $why = '';
        $histConv = (int)($hq[$id] ?? 0) > 0 ? round(($ho[$id] ?? 0) / $hq[$id] * 100) : null;
        if ($pq < 10) { $tag = 'new'; $sug = $base; $why = 'new — basic ' . $base . ' per hour'; }
        else {
            if ($r >= 1.25) { $tag = 'top'; $mult = 1.3; } elseif ($r >= 0.9) { $mult = 1.0; } elseif ($r >= 0.55) { $mult = 0.8; } else { $tag = 'weak'; $mult = 0.5; }
            if (($last2[$id] ?? 0) > 0) { $mult *= 1.2; if ($tag === 'ok') $tag = 'hot'; $why = ($last2[$id]) . ' order' . ($last2[$id] === 1 ? '' : 's') . ' in 2 h'; }
            elseif ($tqn >= 5 && $tor === 0) {
                if ($r >= 0.8) { $tag = 'due'; $mult = 1.0; $why = '0 / ' . $tqn . ' today · past ' . ($histConv !== null ? $histConv . '%' : 'ok'); }
                elseif (($hq[$id] ?? 0) >= 20) { $tag = 'hold'; $why = '0 / ' . $tqn . ' today · past ' . ($histConv !== null ? $histConv . '%' : 'weak') . ' — coach first'; }
            }
            if ($why === '') $why = round($conv * 100) . '% conv' . ($tqn > 0 ? ' · ' . $tor . ' / ' . $tqn . ' today' : '');
            $sug = $tag === 'hold' ? 0 : max(1, (int)round($hb * $mult * $factor));
        }
        $carry = 0;
        if ($tag !== 'hold' && isset($prevPlan[$id])) { $carry = min(max(3, (int)ceil($sug / 2)), max(0, $prevPlan[$id] - ($prevGiven[$id] ?? 0))); }
        $tot = $tag === 'hold' ? 0 : $sug + $carry;
        $rows[] = ['id' => (int)$id, 'name' => $nm, 'sug' => $tot, 'carry' => $carry, 'tag' => $tag, 'why' => $why, 'conv' => round($conv * 100, 1), 'given' => (int)($given[$id] ?? 0), 'exp' => $tot * $conv];
    }
    usort($rows, function ($a, $b) {
        $w = ['top' => 0, 'hot' => 1, 'ok' => 2, 'due' => 3, 'new' => 4, 'weak' => 5, 'hold' => 6];
        return ($w[$a['tag']] <=> $w[$b['tag']]) ?: ($b['conv'] <=> $a['conv']) ?: strcmp($a['name'], $b['name']);
    });
    foreach ($rows as $i => &$r) $r['rank'] = $i + 1; unset($r);
    if (ensure_qb_plan_table($pdo)) {
        try { $st = $pdo->prepare("REPLACE INTO qb_plan (plan_date, hr, employee_id, suggested, tag, saved_at) VALUES (?, ?, ?, ?, ?, NOW())"); foreach ($rows as $r) $st->execute([$date, $nowH, $r['id'], $r['sug'], $r['tag']]); } catch (Throwable $e) {}
    }
    // --- prediction: orders this hour, and for the whole day from the usual hour-by-hour shape
    $predHour = round(array_sum(array_column($rows, 'exp')), 1); $dayPred = null;
    if ($hOrdTot >= 20 && $dord >= 0) {
        $cum = 0.0; foreach ($seq as $h) { $cum += $hOrdHour[$h] / $hOrdTot; if ($h === $nowH) break; }
        $dayPred = ($cum >= 0.2 && $elapsed >= 1.5) ? (int)round($dord / $cum) : (int)round($hOrdTot / max(1, count($hOrdDays)));      // early in the day: the usual day
    }
    $sum = array_sum(array_column($rows, 'sug')); $giv = array_sum(array_column($rows, 'given')); $car = array_sum(array_column($rows, 'carry'));
    return ['hour' => $nowH, 'base' => $base, 'total' => $sum, 'given' => $giv, 'carried' => $car, 'pred_hour' => $predHour, 'pred_day' => $dayPred, 'day_orders' => $dord,
        'flow' => $flow, 'adjusted' => $factor !== 1.0 ? round(($factor - 1) * 100) : 0, 'team_conv' => $teamC !== null ? round($teamC * 100, 1) : null, 'rows' => $rows];
}

function ct_my(PDO $pdo, array $auth): array
{
    $me = (int)($auth['employee_id'] ?? 0); $day = biz_today($pdo); $cfg = ct_cfg($pdo);
    $out = ['day' => $day, 'theme' => ct_theme($pdo), 'cfg' => ['steps' => $cfg['ticket_steps'], 'mix_goal' => $cfg['mix_goal']]];
    if (!$me || !ensure_ct_tables($pdo)) return $out + ['me' => null];
    // (ct_run is NOT started here any more: a salesperson's phone never waits for the team-wide alert job — the cron / tick runs it)
    $S = ct_snapshot($pdo, $day); $e = $S['emps'][$me] ?? null;
    if (!$e) return $out + ['me' => null];
    $out['me'] = ['ticket' => $e['ticket'], 'clean_ticket' => $e['clean_ticket'], 'tv' => $e['tv'], 'mix' => $e['mix'], 'queries' => $e['queries'], 'conv' => $e['conv'], 'orders' => $e['orders'],
        'qo' => $e['qo'], 'co' => $e['co'], 'code' => ['have' => $e['code'], 'need' => $e['code_need'], 'left' => $e['code_left'], 'ok' => $e['code_ok']]];
    $out['team'] = ['q_state' => $S['team']['q_state'], 'query_orders' => $S['team']['query_orders'], 'q_expected_now' => $S['team']['q_expected_now'], 'community_orders' => $S['team']['community_orders'], 'comm_target' => $S['team']['comm_target'],
        'comm_checks' => $S['team']['comm_checks'], 'mix_pct' => $S['team']['mix_pct']];
    $q = $pdo->prepare("SELECT id, kind, severity, title, gu, body, meet_admin FROM ct_alerts WHERE employee_id = ? AND day = ? AND status = 'open' ORDER BY meet_admin DESC, id DESC LIMIT 12"); $q->execute([$me, $day]);
    $out['alerts'] = array_map(fn($r) => ['id' => (int)$r['id'], 'kind' => $r['kind'], 'sev' => $r['severity'], 'title' => $r['title'], 'gu' => $r['gu'], 'body' => $r['body'], 'meet' => (int)$r['meet_admin'] === 1], $q->fetchAll());
    $out['popup'] = null;          // (the missing-proof pop-up ended on 1 Nov 2026)
    try {   // the Top 5 + the person themself only (it used to send everyone's row to every phone and hide it on screen)
        $L = ct_leaders($pdo, $S, $day); unset($L['tips']); $L['me'] = $me;
        foreach (['today', 'week'] as $pk) if (isset($L[$pk]['rows']) && is_array($L[$pk]['rows'])) { $rows = $L[$pk]['rows']; $L[$pk]['rows'] = array_values(array_filter($rows, fn($r, $i) => $i < 5 || (int)$r['id'] === $me, ARRAY_FILTER_USE_BOTH)); $L[$pk]['people'] = count($rows); }
        $out['leaders'] = $L;
    } catch (Throwable $e3) {}
    $out['remarks'] = ct_remarks_unseen($pdo, $me);
    $out['idea'] = ct_idea_for($pdo, $me);
    $q = $pdo->prepare("SELECT title, gu FROM ct_alerts WHERE employee_id = ? AND kind = 'idea_rigid' AND status = 'open' ORDER BY id DESC LIMIT 1"); $q->execute([$me]); $nd = $q->fetch();
    $out['nudge'] = $nd ? ['title' => $nd['title'], 'gu' => $nd['gu']] : null;
    try { $b = ct_benchmarks($pdo); foreach ($b['rows'] as $r) if ($r['id'] === $me) { $out['outcome'] = ['score' => $r['outcome'], 'scores' => $r['scores'], 'bench' => $b['bench']]; break; } } catch (Throwable $e2) {}
    return $out;
}

/** Segment of an order line by its title: attar / gel (shower gel, body wash) / other (wax …) / perfume. Same words as the WhatsApp cart. */
function order_line_seg(string $t): string
{
    $t = mb_strtolower($t);
    if (preg_match('/\battar|\bittar|\boud oil|\broll[- ]?on\b/u', $t)) return 'attar';
    if (preg_match('/shower ?gel|body ?wash|\bgel\b/u', $t)) return 'gel';
    if (preg_match('/\bwax\b/u', $t)) return 'other';
    return 'perfume';
}
/** The non-perfume part of an order (from order_ml_total's parts): its money and its commission, each segment on its own price chart (pieces). */
function order_x_com(?PDO $pdo, $parts, int $perfMl = 0, float $total = 0): array
{
    $o = ['x_amt' => 0.0, 'x_com' => 0.0, 'x_note' => '', 'x_all' => false, 'x_pct' => null]; if (!is_array($parts) || !$parts) return $o; $n = [];
    if (!$pdo && isset($GLOBALS['pdo']) && $GLOBALS['pdo'] instanceof PDO) $pdo = $GLOBALS['pdo'];
    // Combo: 2 or more kinds in the order (perfume ml counts as one kind) = ONE row with exactly these amounts; its % applies to the WHOLE order total.
    // No row yet = no commission for this order, with a note; it is counted by itself as soon as the owner adds the row (worked out when the orders are read).
    $g = (int)($parts['gel']['pcs'] ?? 0); $a0 = (int)($parts['attar']['pcs'] ?? 0); $x0 = (int)($parts['other']['pcs'] ?? 0);
    if (function_exists('pc_mix_kinds') && pc_mix_kinds($perfMl, $g, $a0, $x0) >= 2) {
        $lab = pc_mix_label($perfMl, $g, $a0, $x0); $pc = ($pdo && $total > 0) ? pc_mix_pct($pdo, $perfMl, $g, $a0, $x0, $total) : null;
        return ['x_amt' => round($total, 2), 'x_com' => $pc === null ? 0.0 : round($total * $pc / 100, 2), 'x_all' => true, 'x_pct' => $pc === null ? null : round($pc, 2),
            'x_note' => $pc === null ? 'Combo price missing: ' . $lab . ' (add it in Learn & Setup → Pricing → Combos; the commission is counted then)' : 'Combo ' . $lab . ' ₹' . round($total) . ' at ' . round($pc, 2) . '%'];
    }
    foreach ($parts as $sg => $p) {
        $amt = round((float)($p['amt'] ?? 0), 2); $pcs = (int)($p['pcs'] ?? 0); if ($amt <= 0) continue; $o['x_amt'] += $amt;
        $pc = ($pdo && function_exists('pc_pct')) ? pc_pct($pdo, (string)$sg, (float)$pcs, $amt) : null; if ($pc !== null) $o['x_com'] += $amt * $pc / 100;
        $n[] = (function_exists('pc_segs') ? (pc_segs()[$sg] ?? $sg) : $sg) . ' ×' . $pcs . ' ₹' . round($amt) . ($pc === null ? ' (no price chart)' : ' at ' . round($pc, 2) . '%');
    }
    $o['x_com'] = round($o['x_com'], 2); $o['x_note'] = implode(' · ', $n); return $o;
}
function order_ml_total(array $lineItems): array
{
    $ml = 0; $ml10 = 0; $parts = [];
    $re = '/(?<![0-9.])(\d{1,4}(?:\.\d+)?)\s*-?\s*ml(?![a-z])/i';
    foreach ($lineItems as $li) {
        $qty = max(1, (int)($li['quantity'] ?? 1));
        $seg = order_line_seg((string)($li['title'] ?? '') . ' ' . (string)($li['name'] ?? '') . ' ' . (string)($li['variant_title'] ?? ''));
        if ($seg !== 'perfume') {   // attar / shower gel / others: not in the perfume ml; their pieces and money are priced on their own chart
            $amt = max(0.0, (float)($li['price'] ?? 0) * $qty - (float)($li['total_discount'] ?? 0));
            $parts[$seg] = ['pcs' => (int)(($parts[$seg]['pcs'] ?? 0) + $qty), 'amt' => round((float)($parts[$seg]['amt'] ?? 0) + $amt, 2)];
            continue;
        }
        $size = 0.0;
        foreach ([(string)($li['variant_title'] ?? ''), (string)($li['title'] ?? ''), (string)($li['name'] ?? '')] as $t) {
            if ($t !== '' && preg_match($re, $t, $m)) { $size = (float)$m[1]; break; }
        }
        if ($size <= 0 || $size > 2000) continue;
        $ml += $size * $qty;
        if (abs($size - 10) < 0.01) $ml10 += $qty;
    }
    return ['ml' => (int)round($ml), 'ml10' => $ml10, 'parts' => $parts];
}

/**
 * Adds ml_extra (the free 10 ml pieces, in ML) to each order and, for the orders whose "Extra ml" was switched off on the
 * Orders page (order_ml_skip), takes those pieces out of the order's total ML. Orders without ML (MySales) are left alone.
 */
function orders_ml_extra(PDO $pdo, array &$orders): void
{
    $skip = [];
    if ($orders) {
        if (ensure_order_ml_skip_table($pdo)) {
            try { foreach ($pdo->query("SELECT source, order_id FROM order_ml_skip")->fetchAll() as $r) $skip[$r['source'] . '|' . $r['order_id']] = true; } catch (PDOException $e) {}
        }
    }
    foreach ($orders as &$o) {
        if (!isset($o['ml']) || $o['ml'] === null) { $o['ml_extra'] = null; continue; }
        $x = 10 * (int)($o['ml10'] ?? 0);
        if (isset($skip[(string)($o['store_key'] ?? '') . '|' . (string)($o['id'] ?? '')])) { $o['ml'] = max(0, (int)$o['ml'] - $x); $x = 0; }
        $o['ml_extra'] = $x;
    }
    unset($o);
}

function shopify_fetch_all(array $targets, array $tokens, string $dateFrom, string $dateTo, int $maxRounds = 8, bool $slim = false, bool $manual = true): array
{
    $state = [];
    $win = biz_window($GLOBALS['pdo'], $dateFrom, $dateTo);
    foreach ($targets as $key => $store) {
        $state[$key] = [
            'store' => $store,
            'token' => $tokens[$key],
            'url' => "https://{$store['domain']}/admin/api/2024-10/orders.json?" . http_build_query([
                'status' => 'any',
                'limit' => 250,
                // Business-day window (Day timing setting; default 10:00 ->
                // next day 09:59 IST), so a selected date means that day's
                // start time to the next day's start time.
                'created_at_min' => str_replace(' ', 'T', $win[0]) . '+05:30',
                'created_at_max' => str_replace(' ', 'T', $win[1]) . '+05:30',
                'fields' => $slim
                    ? 'id,name,created_at,total_price,currency,tags'
                    : 'id,name,created_at,total_price,total_outstanding,currency,financial_status,fulfillment_status,customer,line_items,phone,shipping_address,tags,note,note_attributes,checkout_token',
            ]),
            'orders' => [],
            'error' => null,
        ];
    }

    for ($round = 0; $round < $maxRounds; $round++) {
        $mh = curl_multi_init();
        $handles = [];
        foreach ($state as $key => $st) {
            if (!$st['url'] || $st['error']) continue;
            $ch = curl_init($st['url']);
            curl_setopt_array($ch, [
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_HEADER => true,
                CURLOPT_HTTPHEADER => [
                    'X-Shopify-Access-Token: ' . $st['token'],
                    'Content-Type: application/json',
                ],
                CURLOPT_TIMEOUT => 25,
            ]);
            curl_multi_add_handle($mh, $ch);
            $handles[$key] = $ch;
        }
        if (!$handles) { curl_multi_close($mh); break; }

        do {
            $mrc = curl_multi_exec($mh, $running);
            if ($running) curl_multi_select($mh, 0.1);
        } while ($running && $mrc === CURLM_OK);

        foreach ($handles as $key => $ch) {
            $st = &$state[$key];
            $st['url'] = null; // cleared unless a next page is found below
            $resp = curl_multi_getcontent($ch);
            $status = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $headerSize = curl_getinfo($ch, CURLINFO_HEADER_SIZE);
            curl_multi_remove_handle($mh, $ch);
            curl_close($ch);

            if ($resp === false || $resp === '') {
                $st['error'] = $st['store']['label'] . ': could not reach Shopify.';
                continue;
            }
            if ($status === 401 || $status === 403) {
                $st['error'] = $st['store']['label'] . ': invalid token or missing read_orders permission.';
                continue;
            }
            if ($status !== 200) {
                $st['error'] = $st['store']['label'] . ': Shopify returned HTTP ' . $status . '.';
                continue;
            }

            $rawHeaders = substr($resp, 0, $headerSize);
            $body = substr($resp, $headerSize);
            $data = json_decode($body, true);
            foreach (($data['orders'] ?? []) as $o) {
                $customer = trim(($o['customer']['first_name'] ?? '') . ' ' . ($o['customer']['last_name'] ?? ''));
                $phone = $o['phone']
                    ?? ($o['customer']['phone'] ?? null)
                    ?? ($o['shipping_address']['phone'] ?? null);
                $st['orders'][] = [
                    'id' => $o['id'],
                    'order_name' => $o['name'],
                    'created_at' => $o['created_at'],
                    'customer' => $customer !== '' ? $customer : 'Guest',
                    'phone' => $phone ?: '',
                    'items' => count($o['line_items'] ?? []),
                    'colors' => order_product_colors($o['line_items'] ?? []),
                    'ml' => ($mlt = isset($o['line_items']) ? order_ml_total($o['line_items']) : null) ? $mlt['ml'] : null,       // total ML of the order (ML price slab commission)
                    'ml10' => $mlt ? $mlt['ml10'] : null,
                    'xparts' => $mlt ? ($mlt['parts'] ?: (object)[]) : null,      // attar / shower gel / others in the order (pieces + money), priced on their own price charts
                ] + ($mlt ? order_x_com(null, $mlt['parts'], (int)$mlt['ml'], (float)($o['total_price'] ?? 0)) : []) + [
                    'dti' => isset($o['line_items']) ? (order_dti($o['line_items']) ?: 0) : null,     // Dress to Impress bottles (0 = none)
                    'total' => $o['total_price'],
                    'currency' => $o['currency'] ?? 'INR',
                    'financial_status' => $o['financial_status'] ?? '',
                    'outstanding' => isset($o['total_outstanding']) ? (float)$o['total_outstanding'] : null,   // still to be paid (COD balance)
                    'paid' => (($o['financial_status'] ?? '') === 'partially_paid' && isset($o['total_outstanding'])) ? round(max(0, (float)$o['total_price'] - (float)$o['total_outstanding']), 2) : null,   // already paid (partially_paid only)
                    'fulfillment_status' => $o['fulfillment_status'] ?? 'unfulfilled',
                    'tags' => $o['tags'] ?? '',
                    'pay_ref' => $slim ? null : order_pay_refs($o),      // GoKwik / PayU transaction id (KWIK...), '' = none found
                ];
            }
            if (preg_match('/<([^>]+)>;\s*rel="next"/', $rawHeaders, $m)) {
                $st['url'] = $m[1];
            }
            unset($st);
        }
        curl_multi_close($mh);
    }
    if ($manual) orders_add_manual($GLOBALS['pdo'], $state, $win[0], $win[1]);   // 🧾 + the manual (WM-) orders of the same days (not when copying Shopify into shop_orders)

    return $state;
}

/**
 * Salary engine: day-wise pay for one employee & month, driven by punches,
 * day marks (wfh/leave/half_leave/holiday/week_off) and the salary_rules table.
 */
function salary_rules_load(PDO $pdo): array
{
    $freeLeave = 0.0;
    $wfh = []; // occurrence => percent
    try {
        foreach ($pdo->query("SELECT * FROM salary_rules")->fetchAll() as $r) {
            if ($r['rule_type'] === 'free_leave') $freeLeave = (float)$r['value'];
            if ($r['rule_type'] === 'wfh') $wfh[(int)$r['occurrence']] = (float)$r['value'];
        }
    } catch (PDOException $e) { /* table missing — defaults apply */ }
    ksort($wfh);
    return ['free_leave' => $freeLeave, 'wfh' => $wfh];
}

function wfh_percent(array $wfhRules, int $n): float
{
    if (!$wfhRules) return 100.0;
    $pct = null;
    foreach ($wfhRules as $occ => $p) {
        if ($n >= $occ) $pct = $p; // last defined occurrence <= n wins
    }
    return $pct === null ? 100.0 : $pct;
}

function salary_calc(PDO $pdo, array $emp, string $month, array $rules): array
{
    $monthStart = $month . '-01';
    $daysInMonth = (int)date('t', strtotime($monthStart));
    $monthEnd = date('Y-m-t', strtotime($monthStart));
    $today = date('Y-m-d');
    $lastDay = min($monthEnd, $today);
    $empId = (int)$emp['employee_id'];
    $monthly = (float)$emp['monthly_salary'];
    // Every month is paid as a 30-day month: daily rate = monthly salary / 30. Day 31 is not counted, and a short
    // month (February) gets its missing days up to 30 as paid days — so full attendance always pays the full salary.
    $payDays = 30;
    $dailyRate = $monthly / $payDays;

    $present = [];
    $aStmt = $pdo->prepare("SELECT punch_date, punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date BETWEEN ? AND ? AND punch_in IS NOT NULL");
    $aStmt->execute([$empId, $monthStart, $monthEnd]);
    foreach ($aStmt->fetchAll() as $a) $present[$a['punch_date']] = ['in' => substr((string)$a['punch_in'], 11, 5), 'out' => $a['punch_out'] ? substr((string)$a['punch_out'], 11, 5) : ''];

    $marks = [];
    try {
        $mStmt = $pdo->prepare("SELECT mark_date, mark FROM day_marks WHERE employee_id = ? AND mark_date BETWEEN ? AND ?");
        $mStmt->execute([$empId, $monthStart, $monthEnd]);
        foreach ($mStmt->fetchAll() as $m) $marks[$m['mark_date']] = $m['mark'];
    } catch (PDOException $e) { /* table missing */ }

    $pool = (float)$rules['free_leave'];
    $wfhCount = 0;
    $days = [];
    $earned = 0.0;
    $counts = ['present' => 0, 'wfh' => 0, 'leave_units' => 0.0, 'absent' => 0, 'holiday' => 0, 'sunday_off' => 0];

    for ($d = $monthStart; $d <= $lastDay; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
        if ((int)substr($d, 8, 2) > $payDays) break;   // 30-day pay month: the 31st is not counted
        $mark = $marks[$d] ?? null;
        $status = ''; $pct = 0.0; $note = '';

        if (isset($present[$d])) {
            $status = 'Present'; $pct = 100; $counts['present']++;
        } elseif ($mark === null && date('N', strtotime($d)) === '7') {
            // Sunday is the weekly off: no punch on a Sunday is never cut. (A mark set by Admin / HR still wins.)
            $status = 'Sunday off'; $pct = 100; $note = 'weekly off — not cut'; $counts['sunday_off']++;
        } elseif ($mark === 'holiday' || $mark === 'week_off') {
            $status = $mark === 'holiday' ? 'Holiday' : 'Week off'; $pct = 100; $counts['holiday']++;
        } elseif ($mark === 'wfh') {
            $wfhCount++;
            $pct = wfh_percent($rules['wfh'], $wfhCount);
            $status = 'WFH'; $note = "day $wfhCount → $pct%";
            $counts['wfh']++;
        } elseif ($mark === 'leave') {
            $counts['leave_units'] += 1;
            if ($pool >= 1) { $pool -= 1; $pct = 100; $note = 'free pool'; }
            else { $pct = 0; $note = 'pool over'; }
            $status = 'Leave';
        } elseif ($mark === 'half_leave') {
            $counts['leave_units'] += 0.5;
            if ($pool >= 0.5) { $pool -= 0.5; $pct = 100; $note = 'free pool'; }
            else { $pct = 50; $note = 'pool over → half'; }
            $status = 'Half leave';
        } else {
            $status = 'Absent'; $pct = 0; $counts['absent']++;
        }

        $amount = round($dailyRate * $pct / 100, 2);
        $earned += $amount;
        $days[] = ['date' => $d, 'status' => $status, 'mark' => $mark, 'pct' => $pct, 'note' => $note, 'amount' => $amount,
            'punch_in' => $present[$d]['in'] ?? '', 'punch_out' => $present[$d]['out'] ?? ''];
    }

    // February (28 / 29 days): once the month is over, the days missing up to 30 are paid days.
    $extraDays = ($lastDay === $monthEnd && $daysInMonth < $payDays) ? $payDays - $daysInMonth : 0;
    $extraAmount = round($dailyRate * $extraDays, 2);
    $earned += $extraAmount;

    // Penalties taken off this month's salary: original (earned) → penalties → final.
    $penItems = [];
    $penTotal = 0.0;
    try {
        $penItems = penalty_month_items($pdo, (int)$empId, (string)$month, 'salary');
        $penTotal = round(array_sum(array_column($penItems, 'amount')), 2);
    } catch (Throwable $e) { $penItems = []; $penTotal = 0.0; }   // penalties can never take Salary down
    $netPay = max(0, round($earned - $penTotal, 2));

    return [
        'employee_id' => $empId,
        'full_name' => $emp['full_name'],
        'employee_code' => $emp['employee_code'],
        'monthly_salary' => $monthly,
        'daily_rate' => round($dailyRate, 2),
        'days_in_month' => $daysInMonth,
        'pay_days' => $payDays,
        'extra_days' => $extraDays,
        'extra_amount' => $extraAmount,
        'days' => $days,
        'earned' => round($earned, 2),
        'penalties' => $penItems,
        'penalty_total' => $penTotal,
        'net_pay' => $netPay,
        'counts' => $counts,
        'pool_left' => $pool,
    ];
}

/**
 * Verify a generated .docx is actually openable: the zip must be readable,
 * every XML part must parse, and every r:embed / r:id referenced in a part
 * must exist in that part's .rels file. Returns null when fine, otherwise a
 * short reason string.
 */
function docx_validate(string $path): ?string
{
    if (!class_exists('ZipArchive')) return 'ZipArchive missing';
    $zip = new ZipArchive();
    if ($zip->open($path) !== true) return 'not a readable zip';

    $names = [];
    for ($i = 0; $i < $zip->numFiles; $i++) $names[] = $zip->getNameIndex($i);

    if (!in_array('[Content_Types].xml', $names, true)) { $zip->close(); return 'missing [Content_Types].xml'; }

    $prev = libxml_use_internal_errors(true);
    foreach ($names as $n) {
        if (!function_exists('simplexml_load_string')) break; // SimpleXML absent — skip parse check
        if (substr($n, -4) !== '.xml' && substr($n, -5) !== '.rels') continue;
        $data = $zip->getFromName($n);
        if ($data === false) { libxml_use_internal_errors($prev); $zip->close(); return "unreadable part $n"; }
        libxml_clear_errors();
        $doc = simplexml_load_string($data);
        if ($doc === false) {
            $e = libxml_get_errors();
            $msg = $e ? trim($e[0]->message) : 'parse error';
            libxml_use_internal_errors($prev);
            $zip->close();
            return "invalid XML in $n: $msg";
        }
    }
    libxml_use_internal_errors($prev);

    // Relationship ids used by each part must exist in its .rels
    foreach ($names as $n) {
        if (!preg_match('#^word/(document|header\d*|footer\d*)\.xml$#', $n)) continue;
        $xml = $zip->getFromName($n);
        if ($xml === false) continue;
        if (!preg_match_all('/r:(?:embed|id|link)="([^"]+)"/', $xml, $m)) continue;
        $relsName = 'word/_rels/' . basename($n) . '.rels';
        $rels = $zip->getFromName($relsName);
        if ($rels === false) { $zip->close(); return "missing $relsName"; }
        foreach (array_unique($m[1]) as $id) {
            if (strpos($rels, 'Id="' . $id . '"') === false) {
                $zip->close();
                return "relationship $id used in $n is not declared";
            }
        }
    }

    // Any image target referenced must exist inside the package
    foreach ($names as $n) {
        if (substr($n, -5) !== '.rels') continue;
        $rels = $zip->getFromName($n);
        if ($rels === false) continue;
        if (!preg_match_all('/Target="([^"]+)"[^>]*?\/>/', $rels, $m)) continue;
        foreach ($m[1] as $t) {
            if (strpos($t, 'media/') !== 0) continue;
            if (!in_array('word/' . $t, $names, true)) {
                $zip->close();
                return "image $t referenced but not present";
            }
        }
    }

    $zip->close();
    return null;
}

/**
 * Fill {{placeholders}} in a .docx and (optionally) stamp a signature image.
 *
 * A .docx is a zip; word/document.xml holds the body, and headers/footers are
 * separate parts — all are processed, so a {{signature}} in the footer behaves
 * exactly like one in the body. Word often splits a placeholder across runs,
 * so tags are re-joined before replacing.
 *
 * The result is validated before being accepted. If embedding the image
 * produces anything Word would refuse to open, the document is rebuilt with a
 * plain-text signature line instead — a readable document always wins over a
 * prettier one that won't open. $failReason receives the diagnosis in that case.
 */
function docx_fill(string $srcPath, string $destPath, array $vars, ?string $signaturePng = null, ?string &$failReason = null): bool
{
    $failReason = null;

    if (docx_build($srcPath, $destPath, $vars, $signaturePng)) {
        $why = docx_validate($destPath);
        if ($why === null) return true;
        $failReason = $why;
    } else {
        $failReason = 'could not write the document';
    }

    // Fallback: no image, plain text in its place. Must open anywhere.
    @unlink($destPath);
    $textVars = $vars;
    $textVars['signature'] = '(signed digitally — ref ' . ($vars['ref'] ?? '') . ')';
    if (!docx_build($srcPath, $destPath, $textVars, null)) return false;
    return docx_validate($destPath) === null;
}

/**
 * The actual writer used by docx_fill. Pass $signaturePng = null to render the
 * signature placeholder as whatever text is in $vars['signature'] instead.
 */
function docx_build(string $srcPath, string $destPath, array $vars, ?string $signaturePng = null): bool
{
    if (!class_exists('ZipArchive')) return false;
    if (!is_file($srcPath)) return false;
    if (!copy($srcPath, $destPath)) return false;

    $zip = new ZipArchive();
    if ($zip->open($destPath) !== true) return false;

    $parts = [];
    for ($i = 0; $i < $zip->numFiles; $i++) {
        $n = $zip->getNameIndex($i);
        if ($n === 'word/document.xml' || preg_match('#^word/(header|footer)\d*\.xml$#', $n)) {
            $parts[] = $n;
        }
    }
    if (!$parts) { $zip->close(); return false; }

    // Signature image: added once, sized from its real aspect ratio.
    $imgName = 'media/hrms_signature.png';
    $imgAdded = false;
    $cx = 1710000; $cy = 570000; // ~4.5cm x 1.5cm fallback
    if ($signaturePng && is_file($signaturePng)) {
        $size = @getimagesize($signaturePng);
        // Only real PNGs are embedded — anything else is what breaks Word.
        if ($size && $size[0] > 0 && $size[1] > 0 && ($size[2] ?? 0) === IMAGETYPE_PNG) {
            $cx = 1710000;
            $cy = (int)round($cx * ($size[1] / $size[0]));
            $maxH = 900000;
            if ($cy > $maxH) { $cy = $maxH; $cx = (int)round($cy * ($size[0] / $size[1])); }
            if ($zip->addFile($signaturePng, 'word/' . $imgName)) {
                $imgAdded = true;
                $ct = $zip->getFromName('[Content_Types].xml');
                if ($ct !== false && strpos($ct, 'Extension="png"') === false) {
                    $ct = str_replace('</Types>', '<Default Extension="png" ContentType="image/png"/></Types>', $ct);
                    $zip->addFromString('[Content_Types].xml', $ct);
                }
            }
        }
    }

    $rid = 'rIdHrmsSign';
    $nsNeeded = [
        'wp'  => 'http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing',
        'r'   => 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
        'a'   => 'http://schemas.openxmlformats.org/drawingml/2006/main',
        'pic' => 'http://schemas.openxmlformats.org/drawingml/2006/picture',
    ];
    $drawingId = 9901;

    foreach ($parts as $part) {
        $xml = $zip->getFromName($part);
        if ($xml === false) continue;

        // Re-join placeholders Word split across runs.
        $xml = preg_replace_callback('/\{\{(.*?)\}\}/su', function ($m) {
            return '{{' . strip_tags($m[1]) . '}}';
        }, $xml);
        $xml = preg_replace_callback('/\{(?:<[^>]+>)*\{(.*?)\}(?:<[^>]+>)*\}/su', function ($m) {
            return '{{' . strip_tags($m[1]) . '}}';
        }, $xml);

        foreach ($vars as $key => $value) {
            if ($key === 'signature' && $imgAdded) continue; // handled below
            $xml = str_replace('{{' . $key . '}}', htmlspecialchars((string)$value, ENT_XML1 | ENT_QUOTES, 'UTF-8'), $xml);
        }

        if (strpos($xml, '{{signature}}') !== false) {
            if (!$imgAdded) {
                $xml = str_replace('{{signature}}',
                    htmlspecialchars((string)($vars['signature'] ?? ''), ENT_XML1 | ENT_QUOTES, 'UTF-8'), $xml);
            } else {
                // The image markup needs the wp/r/a/pic prefixes on the root.
                if (preg_match('/<w:(document|hdr|ftr)\b[^>]*>/', $xml, $m)) {
                    $openTag = $m[0];
                    $newTag = $openTag;
                    foreach ($nsNeeded as $prefix => $uri) {
                        if (strpos($newTag, 'xmlns:' . $prefix . '=') === false) {
                            $newTag = preg_replace('/>$/', ' xmlns:' . $prefix . '="' . $uri . '">', $newTag, 1);
                        }
                    }
                    if ($newTag !== $openTag) $xml = str_replace($openTag, $newTag, $xml);
                }

                // Relationship entry in THIS part's own .rels file.
                $relsName = 'word/_rels/' . basename($part) . '.rels';
                $rels = $zip->getFromName($relsName);
                if ($rels === false) {
                    $rels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                          . '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>';
                }
                if (strpos($rels, 'Id="' . $rid . '"') === false) {
                    $rels = str_replace('</Relationships>',
                        '<Relationship Id="' . $rid . '" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="' . $imgName . '"/></Relationships>',
                        $rels);
                }
                $zip->addFromString($relsName, $rels);

                // Each occurrence gets a unique docPr id — duplicates make
                // Word refuse the file.
                $xml = preg_replace_callback('/\{\{signature\}\}/', function () use (&$drawingId, $cx, $cy, $rid) {
                    $id = $drawingId++;
                    return '</w:t></w:r><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0">'
                        . '<wp:extent cx="' . $cx . '" cy="' . $cy . '"/>'
                        . '<wp:effectExtent l="0" t="0" r="0" b="0"/>'
                        . '<wp:docPr id="' . $id . '" name="Signature' . $id . '"/>'
                        . '<wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr>'
                        . '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'
                        . '<pic:pic><pic:nvPicPr><pic:cNvPr id="' . $id . '" name="Signature' . $id . '"/><pic:cNvPicPr/></pic:nvPicPr>'
                        . '<pic:blipFill><a:blip r:embed="' . $rid . '"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
                        . '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="' . $cx . '" cy="' . $cy . '"/></a:xfrm>'
                        . '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic>'
                        . '</wp:inline></w:drawing></w:r><w:r><w:t>';
                }, $xml);
            }
        }

        $zip->addFromString($part, $xml);
    }

    return $zip->close();
}

/**
 * ---------------- Agreement PDF rendering (v2) ----------------
 * Renders a .docx template to PDF in pure PHP, preserving as much of the Word
 * formatting as a core-font PDF can carry: page size & margins, headers and
 * footers on every page, run-level bold/italic/underline/size/colour,
 * paragraph alignment (incl. justify), spacing and indents, bullets, headings,
 * tables with borders and cell shading, paragraph shading, and embedded
 * images (logos). Fonts are mapped to Helvetica; layout is re-flowed.
 */

// ---------- font metrics ----------
function pdf_helv_widths(): array
{
    return [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,
            556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,
            1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,
            667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,
            333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,
            556,556,333,500,278,556,500,722,500,500,500,334,260,334,584];
}
function pdf_text_width(string $s, float $size, bool $bold = false): float
{
    static $w = null; if ($w === null) $w = pdf_helv_widths();
    $total = 0; $len = strlen($s);
    for ($i = 0; $i < $len; $i++) {
        $c = ord($s[$i]);
        $cw = ($c >= 32 && $c <= 126) ? $w[$c - 32] : 556;
        $total += $bold ? $cw * 1.08 : $cw;
    }
    return $total * $size / 1000;
}
function pdf_esc(string $s): string
{
    return str_replace(['\\', '(', ')', "\r", "\n"], ['\\\\', '\\(', '\\)', '', ' '], $s);
}
function pdf_win(string $s): string
{
    $map = ["\xe2\x82\xb9"=>'Rs.', "\xe2\x80\x94"=>'-', "\xe2\x80\x93"=>'-', "\xe2\x80\x9c"=>'"', "\xe2\x80\x9d"=>'"',
            "\xe2\x80\x98"=>"'", "\xe2\x80\x99"=>"'", "\xe2\x80\xa6"=>'...', "\xe2\x80\xa2"=>'-', "\xe2\x9c\x93"=>'v', "\xc2\xa0"=>' '];
    $s = strtr($s, $map);
    $out = ''; $len = strlen($s); $i = 0;
    while ($i < $len) {
        $c = ord($s[$i]);
        if ($c < 0x80) { $cp = $c; $step = 1; }
        elseif (($c & 0xE0) === 0xC0) { $cp = (($c & 0x1F) << 6) | (ord($s[$i+1] ?? "\0") & 0x3F); $step = 2; }
        elseif (($c & 0xF0) === 0xE0) { $cp = (($c & 0x0F) << 12) | ((ord($s[$i+1] ?? "\0") & 0x3F) << 6) | (ord($s[$i+2] ?? "\0") & 0x3F); $step = 3; }
        else { $cp = 0x20; $step = (($c & 0xF8) === 0xF0) ? 4 : 1; }
        $i += $step;
        if ($cp === 9) $out .= ' ';
        elseif (($cp >= 32 && $cp <= 126) || ($cp >= 160 && $cp <= 255)) $out .= chr($cp);
        else $out .= ' ';
    }
    return $out;
}

// ---------- docx parsing ----------
function dx_close(string $xml, string $tag, int $openPos): int
{
    // index just after the matching </tag> for the element opened at $openPos
    $depth = 0; $p = $openPos; $len = strlen($xml);
    $o = '<' . $tag; $c = '</' . $tag . '>';
    while ($p < $len) {
        $no = strpos($xml, $o, $p); $nc = strpos($xml, $c, $p);
        if ($nc === false) return $len;
        if ($no !== false && $no < $nc) {
            $after = $xml[$no + strlen($o)] ?? '';
            if ($after === '>' || $after === ' ') {
                $gt = strpos($xml, '>', $no);
                if ($gt !== false && $xml[$gt - 1] === '/') { $p = $gt + 1; continue; } // self-closing
                $depth++; $p = $no + strlen($o); continue;
            }
            $p = $no + strlen($o); continue;
        }
        $depth--; $p = $nc + strlen($c);
        if ($depth <= 0) return $p;
    }
    return $len;
}
function dx_attr(string $xml, string $tag, string $attr, ?string $default = null): ?string
{
    if (preg_match('/<' . preg_quote($tag, '/') . '\b[^>]*?\b' . preg_quote($attr, '/') . '="([^"]*)"/', $xml, $m)) return $m[1];
    return $default;
}
function dx_first(string $xml, string $tag): ?string
{
    $p = strpos($xml, '<' . $tag);
    if ($p === false) return null;
    $after = $xml[$p + strlen($tag) + 1] ?? '';
    if ($after !== '>' && $after !== ' ' && $after !== '/') return null;
    $gt = strpos($xml, '>', $p);
    if ($gt !== false && $xml[$gt - 1] === '/') return substr($xml, $p, $gt - $p + 1);
    $e = dx_close($xml, $tag, $p);
    return substr($xml, $p, $e - $p);
}
function dx_has(string $xml, string $tag): bool
{
    return preg_match('/<' . preg_quote($tag, '/') . '(?:\s[^>]*)?\/?>/', $xml) === 1
        && !preg_match('/<' . preg_quote($tag, '/') . '\b[^>]*w:val="(?:0|false|none)"/', $xml);
}

function dx_rels(ZipArchive $z, string $part): array
{
    $rp = 'word/_rels/' . basename($part) . '.rels';
    $x = $z->getFromName($rp);
    $out = [];
    if ($x === false) return $out;
    if (preg_match_all('/<Relationship\b[^>]*Id="([^"]+)"[^>]*Target="([^"]+)"/', $x, $m, PREG_SET_ORDER)) {
        foreach ($m as $r) $out[$r[1]] = $r[2];
    }
    if (preg_match_all('/<Relationship\b[^>]*Target="([^"]+)"[^>]*Id="([^"]+)"/', $x, $m, PREG_SET_ORDER)) {
        foreach ($m as $r) $out[$r[2]] = $r[1];
    }
    return $out;
}

/** Load an image from the package as JPEG bytes (flattened on white). */
function dx_image(ZipArchive $z, string $target, array &$cache): ?array
{
    $path = (strpos($target, '/') === 0) ? ltrim($target, '/') : 'word/' . $target;
    if (isset($cache[$path])) return $cache[$path];
    $raw = $z->getFromName($path);
    if ($raw === false || !function_exists('imagecreatefromstring')) return $cache[$path] = null;
    $im = @imagecreatefromstring($raw);
    if (!$im) return $cache[$path] = null;
    $w = imagesx($im); $h = imagesy($im);
    $canvas = imagecreatetruecolor($w, $h);
    imagefilledrectangle($canvas, 0, 0, $w, $h, imagecolorallocate($canvas, 255, 255, 255));
    imagecopy($canvas, $im, 0, 0, 0, 0, $w, $h);
    ob_start(); imagejpeg($canvas, null, 88); $jpg = ob_get_clean();
    imagedestroy($im); imagedestroy($canvas);
    return $cache[$path] = ['data' => $jpg, 'w' => $w, 'h' => $h];
}

/** Run-level style inherited from paragraph style. */
function dx_para_style(string $pPr): array
{
    $style = dx_attr($pPr, 'w:pStyle', 'w:val', '') ?? '';
    $st = ['size' => 11.0, 'bold' => false, 'before' => 0.0, 'after' => 4.0];
    $s = strtolower($style);
    if ($s === 'title')                 $st = ['size' => 24.0, 'bold' => true,  'before' => 0,  'after' => 10];
    elseif ($s === 'heading1')          $st = ['size' => 16.0, 'bold' => true,  'before' => 12, 'after' => 4];
    elseif ($s === 'heading2')          $st = ['size' => 13.5, 'bold' => true,  'before' => 10, 'after' => 3];
    elseif ($s === 'heading3')          $st = ['size' => 12.0, 'bold' => true,  'before' => 8,  'after' => 3];
    elseif ($s === 'subtitle')          $st = ['size' => 13.0, 'bold' => false, 'before' => 0,  'after' => 8];
    return $st;
}

/**
 * Parse one <w:p> chunk into a paragraph model.
 */
function dx_parse_paragraph(string $p, array $rels, ZipArchive $z, array &$imgCache, array $vars, float $defaultSize): array
{
    // Re-join placeholders split across runs, then substitute values.
    $p = preg_replace_callback('/\{(?:<[^>]+>)*\{(.*?)\}(?:<[^>]+>)*\}/su', function ($m) {
        return '{{' . strip_tags($m[1]) . '}}';
    }, $p);
    foreach ($vars as $k => $v) {
        if ($k === 'signature') continue;
        $p = str_replace('{{' . $k . '}}', htmlspecialchars((string)$v, ENT_XML1 | ENT_QUOTES, 'UTF-8'), $p);
    }
    $p = str_replace('{{signature}}', "\x01SIG\x01", $p);

    $pPr = dx_first($p, 'w:pPr') ?? '';
    $ps  = dx_para_style($pPr);
    $align = dx_attr($pPr, 'w:jc', 'w:val', 'left') ?? 'left';
    if ($align === 'both') $align = 'justify';
    if ($align === 'start') $align = 'left';
    if ($align === 'end') $align = 'right';
    $before = dx_attr($pPr, 'w:spacing', 'w:before'); $after = dx_attr($pPr, 'w:spacing', 'w:after');
    $before = $before !== null ? (float)$before / 20 : $ps['before'];
    $after  = $after  !== null ? (float)$after / 20 : $ps['after'];
    $line   = dx_attr($pPr, 'w:spacing', 'w:line');
    $lineRule = dx_attr($pPr, 'w:spacing', 'w:lineRule', 'auto');
    $lineMul = 1.2;
    if ($line !== null && $lineRule === 'auto') $lineMul = max(1.0, (float)$line / 240 * 1.15);
    $indLeft = (float)(dx_attr($pPr, 'w:ind', 'w:left') ?? dx_attr($pPr, 'w:ind', 'w:start') ?? 0) / 20;
    $indHang = (float)(dx_attr($pPr, 'w:ind', 'w:hanging') ?? 0) / 20;
    $indFirst = (float)(dx_attr($pPr, 'w:ind', 'w:firstLine') ?? 0) / 20;
    $styleName = strtolower(dx_attr($pPr, 'w:pStyle', 'w:val', '') ?? '');
    $bullet = strpos($pPr, '<w:numPr>') !== false || strpos($styleName, 'list') === 0;
    if ($bullet && $indLeft < 14) $indLeft = 18;
    $shade = dx_attr($pPr, 'w:shd', 'w:fill');
    if ($shade === 'auto' || $shade === 'FFFFFF' || $shade === 'ffffff') $shade = null;
    $pageBreak = strpos($p, 'w:type="page"') !== false || strpos($p, '<w:pageBreakBefore') !== false;

    $pRun = dx_first($pPr, 'w:rPr') ?? '';
    $pBold = $ps['bold'] || dx_has($pRun, 'w:b');
    $pSize = $ps['size'] !== 11.0 ? $ps['size'] : $defaultSize;
    if (($sz = dx_attr($pRun, 'w:sz', 'w:val')) !== null) $pSize = (float)$sz / 2;
    $pColor = dx_attr($pRun, 'w:color', 'w:val');

    $runs = [];
    $pos = 0;
    while (($r = strpos($p, '<w:r', $pos)) !== false) {
        $after_ = $p[$r + 4] ?? '';
        if ($after_ !== '>' && $after_ !== ' ') { $pos = $r + 4; continue; }
        $e = dx_close($p, 'w:r', $r);
        $chunk = substr($p, $r, $e - $r);
        $pos = $e;

        $rPr = dx_first($chunk, 'w:rPr') ?? '';
        $bold = $pBold || dx_has($rPr, 'w:b');
        $ital = dx_has($rPr, 'w:i');
        $under = strpos($rPr, '<w:u ') !== false && strpos($rPr, 'w:val="none"') === false;
        $size = $pSize;
        if (($sz = dx_attr($rPr, 'w:sz', 'w:val')) !== null) $size = (float)$sz / 2;
        $color = dx_attr($rPr, 'w:color', 'w:val') ?? $pColor;
        if ($color === 'auto') $color = null;
        $style = ['bold' => $bold, 'italic' => $ital, 'underline' => $under, 'size' => $size, 'color' => $color];

        // Images inside this run
        if (strpos($chunk, '<a:blip') !== false || strpos($chunk, '<v:imagedata') !== false) {
            $rid = dx_attr($chunk, 'a:blip', 'r:embed') ?? dx_attr($chunk, 'a:blip', 'r:link') ?? dx_attr($chunk, 'v:imagedata', 'r:id');
            $cx = dx_attr($chunk, 'wp:extent', 'cx'); $cy = dx_attr($chunk, 'wp:extent', 'cy');
            $wpt = $cx ? (float)$cx / 12700 : 0; $hpt = $cy ? (float)$cy / 12700 : 0;
            if (!$wpt && preg_match('/width:\s*([\d.]+)pt/', $chunk, $mm)) $wpt = (float)$mm[1];
            if (!$hpt && preg_match('/height:\s*([\d.]+)pt/', $chunk, $mm)) $hpt = (float)$mm[1];
            if ($rid && isset($rels[$rid])) {
                $img = dx_image($z, $rels[$rid], $imgCache);
                if ($img) {
                    if (!$wpt || !$hpt) { $wpt = min(200, $img['w'] * 0.75); $hpt = $wpt * $img['h'] / $img['w']; }
                    $runs[] = ['image' => $img, 'w' => $wpt, 'h' => $hpt] + $style;
                }
            }
        }

        // Text pieces in order
        $text = '';
        $c = 0;
        while (($t = strpos($chunk, '<w:', $c)) !== false) {
            $tag = substr($chunk, $t + 3, 3);
            if (substr($chunk, $t, 5) === '<w:t>' || substr($chunk, $t, 5) === '<w:t ') {
                $gt = strpos($chunk, '>', $t);
                if ($chunk[$gt - 1] === '/') { $c = $gt + 1; continue; }
                $close = strpos($chunk, '</w:t>', $gt);
                if ($close === false) break;
                $text .= substr($chunk, $gt + 1, $close - $gt - 1);
                $c = $close + 6;
            } elseif (substr($chunk, $t, 7) === '<w:tab/' || substr($chunk, $t, 6) === '<w:tab') {
                $text .= "\t"; $c = $t + 6;
            } elseif (substr($chunk, $t, 6) === '<w:br/' || substr($chunk, $t, 5) === '<w:br' || substr($chunk, $t, 5) === '<w:cr') {
                $text .= "\n"; $c = $t + 5;
            } else { $c = $t + 3; }
        }
        if ($text !== '') {
            $text = html_entity_decode($text, ENT_QUOTES | ENT_XML1, 'UTF-8');
            // split on signature marker
            $parts = explode("\x01SIG\x01", $text);
            foreach ($parts as $i => $part) {
                if ($i > 0) $runs[] = ['signature' => true] + $style;
                if ($part !== '') $runs[] = ['text' => $part] + $style;
            }
        }
    }

    return [
        'type' => 'p', 'runs' => $runs, 'align' => $align, 'before' => $before, 'after' => $after,
        'lineMul' => $lineMul, 'indent' => $indLeft, 'hanging' => $indHang, 'firstLine' => $indFirst,
        'bullet' => $bullet, 'shade' => $shade, 'size' => $pSize, 'pageBreak' => $pageBreak,
    ];
}

/** Parse a <w:tbl> chunk. */
function dx_parse_table(string $t, array $rels, ZipArchive $z, array &$imgCache, array $vars, float $defaultSize): array
{
    $grid = [];
    if (preg_match_all('/<w:gridCol\b[^>]*w:w="(\d+)"/', $t, $m)) foreach ($m[1] as $g) $grid[] = (float)$g / 20;
    $tblPr = dx_first($t, 'w:tblPr') ?? '';
    $borders = strpos($tblPr, '<w:tblBorders') !== false && strpos($tblPr, 'w:val="nil"') === false && strpos($tblPr, 'w:val="none"') === false;
    if (strpos($tblPr, '<w:tblBorders') === false) $borders = strpos($tblPr, 'TableGrid') !== false || stripos($t, 'w:tblStyle w:val="TableGrid"') !== false;

    $rows = [];
    $pos = 0;
    while (($r = strpos($t, '<w:tr', $pos)) !== false) {
        $a = $t[$r + 5] ?? '';
        if ($a !== '>' && $a !== ' ') { $pos = $r + 5; continue; }
        $e = dx_close($t, 'w:tr', $r);
        $rowXml = substr($t, $r, $e - $r);
        $pos = $e;
        $cells = [];
        $cp = 0;
        while (($c = strpos($rowXml, '<w:tc', $cp)) !== false) {
            $a2 = $rowXml[$c + 5] ?? '';
            if ($a2 !== '>' && $a2 !== ' ') { $cp = $c + 5; continue; }
            $ce = dx_close($rowXml, 'w:tc', $c);
            $cellXml = substr($rowXml, $c, $ce - $c);
            $cp = $ce;
            $tcPr = dx_first($cellXml, 'w:tcPr') ?? '';
            $span = (int)(dx_attr($tcPr, 'w:gridSpan', 'w:val') ?? 1);
            $shade = dx_attr($tcPr, 'w:shd', 'w:fill');
            if ($shade === 'auto' || strtoupper((string)$shade) === 'FFFFFF') $shade = null;
            $cellBorders = null;
            if (strpos($tcPr, '<w:tcBorders') !== false) {
                $cellBorders = !(strpos($tcPr, 'w:val="nil"') !== false || strpos($tcPr, 'w:val="none"') !== false);
            }
            $inner = substr($cellXml, strlen($tcPr));
            $blocks = dx_parse_blocks($inner, $rels, $z, $imgCache, $vars, $defaultSize, true);
            $cells[] = ['span' => max(1, $span), 'shade' => $shade, 'blocks' => $blocks, 'borders' => $cellBorders];
        }
        if ($cells) $rows[] = $cells;
    }
    return ['type' => 'table', 'grid' => $grid, 'rows' => $rows, 'borders' => $borders];
}

/** Top-level walk: paragraphs and tables in document order. */
function dx_parse_blocks(string $xml, array $rels, ZipArchive $z, array &$imgCache, array $vars, float $defaultSize, bool $inCell = false): array
{
    $blocks = [];
    $pos = 0; $len = strlen($xml);
    while ($pos < $len) {
        $np = strpos($xml, '<w:p', $pos);
        while ($np !== false) {
            $a = $xml[$np + 4] ?? '';
            if ($a === '>' || $a === ' ' || $a === '/') break;
            $np = strpos($xml, '<w:p', $np + 4);
        }
        $nt = $inCell ? false : strpos($xml, '<w:tbl', $pos);
        while ($nt !== false) {
            $a = $xml[$nt + 6] ?? '';
            if ($a === '>' || $a === ' ') break;
            $nt = strpos($xml, '<w:tbl', $nt + 6);
        }
        if ($np === false && $nt === false) break;
        if ($nt !== false && ($np === false || $nt < $np)) {
            $e = dx_close($xml, 'w:tbl', $nt);
            $blocks[] = dx_parse_table(substr($xml, $nt, $e - $nt), $rels, $z, $imgCache, $vars, $defaultSize);
            $pos = $e;
        } else {
            $a = $xml[$np + 4];
            if ($a === '/') { $blocks[] = ['type' => 'p', 'runs' => [], 'align' => 'left', 'before' => 0, 'after' => 4, 'lineMul' => 1.2, 'indent' => 0, 'hanging' => 0, 'firstLine' => 0, 'bullet' => false, 'shade' => null, 'size' => $defaultSize, 'pageBreak' => false]; $pos = $np + 5; continue; }
            $e = dx_close($xml, 'w:p', $np);
            // Nested table inside a paragraph (text boxes) — parse paragraph only.
            $blocks[] = dx_parse_paragraph(substr($xml, $np, $e - $np), $rels, $z, $imgCache, $vars, $defaultSize);
            $pos = $e;
        }
    }
    return $blocks;
}

/** Whole-document model: page geometry, body, header, footer. */
function dx_load(string $path, array $vars, ?string &$err = null): ?array
{
    $err = null;
    if (!class_exists('ZipArchive')) { $err = 'ZipArchive extension not available'; return null; }
    if (!is_file($path)) { $err = 'template file missing: ' . basename($path); return null; }
    $z = new ZipArchive();
    $code = $z->open($path);
    if ($code !== true) { $err = 'template is not a valid .docx (zip code ' . $code . ')'; return null; }
    $doc = $z->getFromName('word/document.xml');
    if ($doc === false) { $z->close(); $err = 'word/document.xml missing'; return null; }

    // Default font size from styles.xml docDefaults
    $defaultSize = 11.0;
    $styles = $z->getFromName('word/styles.xml');
    if ($styles !== false && preg_match('/<w:docDefaults>.*?<w:sz w:val="(\d+)"/s', $styles, $m)) $defaultSize = (float)$m[1] / 2;

    // Page geometry
    $sect = dx_first($doc, 'w:sectPr') ?? '';
    $pgW = (float)(dx_attr($sect, 'w:pgSz', 'w:w') ?? 11906) / 20;
    $pgH = (float)(dx_attr($sect, 'w:pgSz', 'w:h') ?? 16838) / 20;
    $mT = (float)(dx_attr($sect, 'w:pgMar', 'w:top') ?? 1440) / 20;
    $mB = (float)(dx_attr($sect, 'w:pgMar', 'w:bottom') ?? 1440) / 20;
    $mL = (float)(dx_attr($sect, 'w:pgMar', 'w:left') ?? 1440) / 20;
    $mR = (float)(dx_attr($sect, 'w:pgMar', 'w:right') ?? 1440) / 20;
    $mH = (float)(dx_attr($sect, 'w:pgMar', 'w:header') ?? 708) / 20;
    $mF = (float)(dx_attr($sect, 'w:pgMar', 'w:footer') ?? 708) / 20;

    $imgCache = [];
    $docRels = dx_rels($z, 'word/document.xml');
    $bodyStart = strpos($doc, '<w:body');
    $body = $bodyStart !== false ? substr($doc, $bodyStart) : $doc;
    if (($sp = strrpos($body, '<w:sectPr')) !== false) $body = substr($body, 0, $sp);
    $blocks = dx_parse_blocks($body, $docRels, $z, $imgCache, $vars, $defaultSize);

    // Header / footer: the "default" ones referenced from sectPr
    $header = []; $footer = [];
    if (preg_match_all('/<w:(header|footer)Reference\b[^>]*w:type="default"[^>]*r:id="([^"]+)"/', $sect, $m, PREG_SET_ORDER)
        || preg_match_all('/<w:(header|footer)Reference\b[^>]*r:id="([^"]+)"[^>]*w:type="default"/', $sect, $m, PREG_SET_ORDER)) {
        foreach ($m as $ref) {
            $target = $docRels[$ref[2]] ?? null;
            if (!$target) continue;
            $part = 'word/' . ltrim($target, '/');
            $x = $z->getFromName($part);
            if ($x === false) continue;
            $rels = dx_rels($z, $part);
            $b = dx_parse_blocks($x, $rels, $z, $imgCache, $vars, $defaultSize);
            if ($ref[1] === 'header') $header = $b; else $footer = $b;
        }
    }
    // Fallback: first header1/footer1 if no reference matched
    if (!$header && ($x = $z->getFromName('word/header1.xml')) !== false) $header = dx_parse_blocks($x, dx_rels($z, 'word/header1.xml'), $z, $imgCache, $vars, $defaultSize);
    if (!$footer && ($x = $z->getFromName('word/footer1.xml')) !== false) $footer = dx_parse_blocks($x, dx_rels($z, 'word/footer1.xml'), $z, $imgCache, $vars, $defaultSize);
    $z->close();

    $hasText = false;
    foreach ($blocks as $b) { if ($b['type'] === 'table') { $hasText = true; break; } foreach ($b['runs'] as $r) if (!empty($r['text']) && trim($r['text']) !== '') { $hasText = true; break 2; } }
    if (!$hasText && !$header && !$footer) { $err = 'no readable text found in template'; return null; }

    return ['page' => [$pgW, $pgH, $mT, $mB, $mL, $mR, $mH, $mF], 'body' => $blocks, 'header' => $header, 'footer' => $footer, 'images' => $imgCache];
}

// ---------- layout + drawing ----------
class PdfDoc {
    public array $objs = [];
    public array $imgObj = [];   // key => obj id
    public array $imgData = [];  // key => [data,w,h]
    public array $pages = [];
    public string $ops = '';
    public float $W, $H, $mT, $mB, $mL, $mR, $mH, $mF;
    public float $y = 0;
    public float $bodyTop, $bodyBottom;
    public $sig = null;          // ['key','w','h']
    public array $hdr = [], $ftr = [];
    public string $hdrOps = ''; public string $ftrOps = ''; public float $hdrH = 0, $ftrH = 0;

    function font(array $s): string
    {
        if (!empty($s['bold']) && !empty($s['italic'])) return '/F4';
        if (!empty($s['bold'])) return '/F2';
        if (!empty($s['italic'])) return '/F3';
        return '/F1';
    }
    function color(?string $hex): string
    {
        if (!$hex || !preg_match('/^[0-9a-fA-F]{6}$/', $hex)) return '0 0 0 rg';
        return sprintf('%.3f %.3f %.3f rg', hexdec(substr($hex,0,2))/255, hexdec(substr($hex,2,2))/255, hexdec(substr($hex,4,2))/255);
    }
    function imgKey(array $img): string
    {
        $k = md5($img['data']);
        if (!isset($this->imgData[$k])) $this->imgData[$k] = $img;
        return $k;
    }

    /** Break a paragraph into lines for a given width. Returns [lines, totalHeight]. */
    function layout(array $p, float $width): array
    {
        $lines = []; $cur = []; $curW = 0.0; $curH = 0.0;
        $firstIndent = $p['firstLine'] - $p['hanging'];
        $avail = $width - ($firstIndent > 0 ? $firstIndent : 0);
        $flush = function () use (&$lines, &$cur, &$curW, &$curH, &$avail, $width, $p) {
            $lines[] = ['segs' => $cur, 'w' => $curW, 'h' => max($curH, $p['size'] * $p['lineMul'])];
            $cur = []; $curW = 0.0; $curH = 0.0; $avail = $width;
        };
        $baseSize = $p['size'];
        foreach ($p['runs'] as $r) {
            $lh = ($r['size'] ?? $baseSize) * $p['lineMul'];
            if (isset($r['image'])) {
                $w = min($r['w'], $width); $h = $r['h'] * ($w / max($r['w'], 0.01));
                if ($curW > 0 && $curW + $w > $avail) $flush();
                $cur[] = ['img' => $this->imgKey($r['image']), 'w' => $w, 'h' => $h];
                $curW += $w; $curH = max($curH, $h + 2);
                continue;
            }
            if (isset($r['signature'])) {
                if ($this->sig) {
                    $w = $this->sig['w']; $h = $this->sig['h'];
                    if ($curW > 0 && $curW + $w > $avail) $flush();
                    $cur[] = ['img' => $this->sig['key'], 'w' => $w, 'h' => $h];
                    $curW += $w; $curH = max($curH, $h + 2);
                } else {
                    $txt = pdf_win('(signed digitally)');
                    $w = pdf_text_width($txt, $r['size'], !empty($r['bold']));
                    if ($curW > 0 && $curW + $w > $avail) $flush();
                    $cur[] = ['t' => $txt, 'w' => $w, 's' => $r];
                    $curW += $w; $curH = max($curH, $lh);
                }
                continue;
            }
            $text = pdf_win($r['text']);
            $paras = explode("\n", $text);
            foreach ($paras as $pi => $seg) {
                if ($pi > 0) $flush();
                $seg = str_replace("\t", '    ', $seg);
                $words = preg_split('/( )/', $seg, -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_NO_EMPTY);
                foreach ($words as $wd) {
                    $w = pdf_text_width($wd, $r['size'], !empty($r['bold']));
                    if ($wd === ' ' && $curW === 0.0) continue; // no leading space
                    if ($curW + $w > $avail && $curW > 0) {
                        // drop trailing space on the line
                        if ($cur && isset($cur[count($cur)-1]['t']) && $cur[count($cur)-1]['t'] === ' ') { $curW -= $cur[count($cur)-1]['w']; array_pop($cur); }
                        $flush();
                        if ($wd === ' ') continue;
                    }
                    // hard-break very long words
                    while ($w > $avail && strlen($wd) > 1) {
                        $cut = max(1, (int)floor(strlen($wd) * $avail / $w));
                        $head = substr($wd, 0, $cut); $wd = substr($wd, $cut);
                        $cur[] = ['t' => $head, 'w' => pdf_text_width($head, $r['size'], !empty($r['bold'])), 's' => $r];
                        $curW += $cur[count($cur)-1]['w']; $curH = max($curH, $lh);
                        $flush();
                        $w = pdf_text_width($wd, $r['size'], !empty($r['bold']));
                    }
                    $cur[] = ['t' => $wd, 'w' => $w, 's' => $r];
                    $curW += $w; $curH = max($curH, $lh);
                }
            }
        }
        if ($cur || !$lines) {
            if ($cur && isset($cur[count($cur)-1]['t']) && $cur[count($cur)-1]['t'] === ' ') { $curW -= $cur[count($cur)-1]['w']; array_pop($cur); }
            $flush();
        }
        $total = $p['before'] + $p['after'];
        foreach ($lines as $l) $total += $l['h'];
        return [$lines, $total];
    }

    /** Draw already-laid-out lines at x/y (y = top). Returns ops, and new y. */
    function drawLines(array $p, array $lines, float $x, float $y, float $width, bool $lastLineJustify = false): array
    {
        $ops = '';
        $y -= $p['before'];
        if ($p['shade']) {
            $h = 0; foreach ($lines as $l) $h += $l['h'];
            $ops .= "q " . $this->fillColor($p['shade']) . " " . ($x - 2) . " " . ($y - $h - 1) . " " . ($width + 4) . " " . ($h + 2 + $p['after']) . " re f Q\n";
        }
        $n = count($lines);
        foreach ($lines as $i => $l) {
            $isFirst = $i === 0;
            $lineX = $x + $p['indent'] + ($isFirst ? ($p['firstLine'] - $p['hanging']) : 0);
            if ($p['bullet'] && $isFirst) {
                $bx = $lineX - 12;
                $ops .= "BT /F1 " . $p['size'] . " Tf 1 0 0 1 " . round($bx, 2) . " " . round($y - $l['h'] * 0.78, 2) . " Tm 0 0 0 rg (" . pdf_esc(chr(149)) . ") Tj ET\n";
            }
            $lineW = $width - $p['indent'] - ($isFirst ? max(0, $p['firstLine'] - $p['hanging']) : 0);
            $free = max(0, $lineW - $l['w']);
            $align = $p['align'];
            $off = 0; $tw = 0;
            if ($align === 'center') $off = $free / 2;
            elseif ($align === 'right') $off = $free;
            elseif ($align === 'justify' && $i < $n - 1) {
                $spaces = 0; foreach ($l['segs'] as $sg) if (isset($sg['t']) && $sg['t'] === ' ') $spaces++;
                if ($spaces > 0) $tw = $free / $spaces;
            }
            $baseline = $y - $l['h'] * 0.78;
            $cx = $lineX + $off;
            foreach ($l['segs'] as $sg) {
                if (isset($sg['img'])) {
                    $iy = $y - $l['h'] + ($l['h'] - $sg['h']) / 2;
                    $ops .= "q " . round($sg['w'], 2) . " 0 0 " . round($sg['h'], 2) . " " . round($cx, 2) . " " . round($iy, 2) . " cm /Im" . $sg['img'] . " Do Q\n";
                    $cx += $sg['w'];
                    continue;
                }
                $s = $sg['s'];
                $w = $sg['w'] + ($sg['t'] === ' ' ? $tw : 0);
                $ops .= "BT " . $this->font($s) . " " . $s['size'] . " Tf " . $this->color($s['color'] ?? null)
                      . " 1 0 0 1 " . round($cx, 2) . " " . round($baseline, 2) . " Tm (" . pdf_esc($sg['t']) . ") Tj ET\n";
                if (!empty($s['underline']) && $sg['t'] !== ' ') {
                    $ops .= "q " . str_replace(' rg', ' RG', $this->color($s['color'] ?? null)) . " 0.6 w " . round($cx, 2) . " " . round($baseline - 1.5, 2) . " m " . round($cx + $sg['w'], 2) . " " . round($baseline - 1.5, 2) . " l S Q\n";
                }
                $cx += $w;
            }
            $y -= $l['h'];
        }
        $y -= $p['after'];
        return [$ops, $y];
    }
    function fillColor(string $hex): string { return str_replace(' rg', ' rg', $this->color($hex)); }

    /** Render a list of blocks into $this->ops with page breaking. */
    function renderBlocks(array $blocks, float $x, float $width): void
    {
        foreach ($blocks as $b) {
            if ($b['type'] === 'table') { $this->renderTable($b, $x, $width); continue; }
            if (!empty($b['pageBreak']) && $this->ops !== '') { $this->newPage(); }
            [$lines, $h] = $this->layout($b, $width);
            $empty = count($lines) === 1 && !$lines[0]['segs'];
            if ($empty) { $this->y -= $b['before'] + $lines[0]['h'] * 0.6 + $b['after'] * 0.5; if ($this->y < $this->bodyBottom) $this->newPage(); continue; }
            // Keep short paragraphs whole; split long ones by line.
            if ($this->y - $h < $this->bodyBottom) {
                if ($h < ($this->bodyTop - $this->bodyBottom) * 0.5 || $this->y - $b['before'] - $lines[0]['h'] < $this->bodyBottom) {
                    $this->newPage();
                } else {
                    // split
                    $fit = []; $rem = []; $yy = $this->y - $b['before'];
                    foreach ($lines as $l) { if ($yy - $l['h'] >= $this->bodyBottom && !$rem) { $fit[] = $l; $yy -= $l['h']; } else $rem[] = $l; }
                    if ($fit) {
                        $pa = $b; $pa['after'] = 0;
                        [$ops, $ny] = $this->drawLines($pa, $fit, $x, $this->y, $width);
                        $this->ops .= $ops;
                    }
                    $this->newPage();
                    $pb = $b; $pb['before'] = 0; $pb['bullet'] = false; $pb['firstLine'] = 0; $pb['hanging'] = 0;
                    [$ops, $ny] = $this->drawLines($pb, $rem, $x, $this->y, $width);
                    $this->ops .= $ops; $this->y = $ny;
                    continue;
                }
            }
            [$ops, $ny] = $this->drawLines($b, $lines, $x, $this->y, $width);
            $this->ops .= $ops; $this->y = $ny;
        }
    }

    function cellHeight(array $cell, float $w): float
    {
        $h = 0;
        foreach ($cell['blocks'] as $b) {
            if ($b['type'] === 'table') continue;
            [$lines, $bh] = $this->layout($b, $w - 8);
            $h += $bh;
        }
        return $h + 6;
    }

    function renderTable(array $t, float $x, float $width): void
    {
        $grid = $t['grid'];
        $ncols = 0; foreach ($t['rows'] as $r) { $c = 0; foreach ($r as $cell) $c += $cell['span']; $ncols = max($ncols, $c); }
        if (!$grid || count($grid) < $ncols) { $grid = array_fill(0, max(1, $ncols), $width / max(1, $ncols)); }
        $sum = array_sum($grid); if ($sum <= 0) $sum = $width;
        $scale = $width / $sum;
        foreach ($grid as $i => $g) $grid[$i] = $g * $scale;

        $this->y -= 2;
        foreach ($t['rows'] as $row) {
            // widths per cell
            $widths = []; $ci = 0;
            foreach ($row as $cell) { $w = 0; for ($k = 0; $k < $cell['span']; $k++) $w += $grid[$ci + $k] ?? 0; $widths[] = $w; $ci += $cell['span']; }
            $rowH = 0;
            foreach ($row as $i => $cell) $rowH = max($rowH, $this->cellHeight($cell, $widths[$i]));
            if ($this->y - $rowH < $this->bodyBottom) $this->newPage();
            $cx = $x;
            foreach ($row as $i => $cell) {
                $w = $widths[$i];
                if ($cell['shade']) $this->ops .= "q " . $this->fillColor($cell['shade']) . " " . round($cx,2) . " " . round($this->y - $rowH,2) . " " . round($w,2) . " " . round($rowH,2) . " re f Q\n";
                $drawB = $cell['borders'] ?? $t['borders'];
                if ($drawB) $this->ops .= "q 0.55 0.55 0.55 RG 0.5 w " . round($cx,2) . " " . round($this->y - $rowH,2) . " " . round($w,2) . " " . round($rowH,2) . " re S Q\n";
                $yy = $this->y - 3;
                foreach ($cell['blocks'] as $b) {
                    if ($b['type'] === 'table') continue;
                    [$lines, $bh] = $this->layout($b, $w - 8);
                    [$ops, $yy] = $this->drawLines($b, $lines, $cx + 4, $yy, $w - 8);
                    $this->ops .= $ops;
                }
                $cx += $w;
            }
            $this->y -= $rowH;
        }
        $this->y -= 6;
    }

    function newPage(): void
    {
        $this->pages[] = $this->hdrOps . $this->ops . $this->ftrOps;
        $this->ops = '';
        $this->y = $this->bodyTop;
    }

    /** Lay out header/footer once into ops strings and measure their heights. */
    function prepareHeaderFooter(array $hdr, array $ftr, float $x, float $width): void
    {
        $measure = function (array $blocks, float $startY) use ($x, $width): array {
            $save = [$this->ops, $this->y, $this->pages, $this->bodyBottom, $this->bodyTop];
            $this->ops = ''; $this->y = $startY; $this->pages = []; $this->bodyBottom = -1e9; $this->bodyTop = $startY;
            $this->renderBlocks($blocks, $x, $width);
            $ops = $this->ops; $h = $startY - $this->y;
            [$this->ops, $this->y, $this->pages, $this->bodyBottom, $this->bodyTop] = $save;
            return [$ops, $h];
        };
        if ($hdr) { [$this->hdrOps, $this->hdrH] = $measure($hdr, $this->H - $this->mH); }
        if ($ftr) {
            [$tmp, $fh] = $measure($ftr, 1000.0); // measure at arbitrary y
            $this->ftrH = $fh;
            [$this->ftrOps, $fh2] = $measure($ftr, $this->mF + $fh); // bottom aligned
        }
        $this->bodyTop = $this->H - max($this->mT, $this->mH + $this->hdrH + 6);
        $this->bodyBottom = max($this->mB, $this->mF + $this->ftrH + 6);
    }

    function build(array $vars): string
    {
        if ($this->ops !== '' || !$this->pages) $this->pages[] = $this->hdrOps . $this->ops . $this->ftrOps;
        $objs = [];
        $add = function (string $b) use (&$objs) { $objs[] = $b; return count($objs); };
        $f1 = $add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
        $f2 = $add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
        $f3 = $add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>");
        $f4 = $add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-BoldOblique /Encoding /WinAnsiEncoding >>");
        $xo = '';
        foreach ($this->imgData as $k => $img) {
            $id = $add("<< /Type /XObject /Subtype /Image /Width {$img['w']} /Height {$img['h']} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length " . strlen($img['data']) . " >>\nstream\n" . $img['data'] . "\nendstream");
            $xo .= " /Im$k $id 0 R";
        }
        $pageIds = [];
        foreach ($this->pages as $ops) {
            $stream = $ops === '' ? ' ' : $ops;
            $cid = $add("<< /Length " . strlen($stream) . " >>\nstream\n" . $stream . "\nendstream");
            $res = "/Font << /F1 $f1 0 R /F2 $f2 0 R /F3 $f3 0 R /F4 $f4 0 R >>" . ($xo ? " /XObject <<$xo >>" : '');
            $pageIds[] = $add("<< /Type /Page /Parent PARENT 0 R /MediaBox [0 0 {$this->W} {$this->H}] /Resources << $res >> /Contents $cid 0 R >>");
        }
        $kids = implode(' ', array_map(fn($i) => "$i 0 R", $pageIds));
        $pagesId = $add("<< /Type /Pages /Count " . count($pageIds) . " /Kids [$kids] >>");
        $catalog = $add("<< /Type /Catalog /Pages $pagesId 0 R >>");
        $info = $add("<< /Title (" . pdf_esc(pdf_win(($vars['name'] ?? '') . ' agreement')) . ") /Producer (HRMS) /CreationDate (D:" . date('YmdHis') . "+05'30') >>");
        foreach ($objs as $i => $o) if (strpos($o, 'PARENT') !== false) $objs[$i] = str_replace('PARENT', (string)$pagesId, $o);
        $pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n"; $off = [];
        foreach ($objs as $i => $b) { $off[$i+1] = strlen($pdf); $pdf .= ($i+1) . " 0 obj\n" . $b . "\nendobj\n"; }
        $xref = strlen($pdf); $n = count($objs) + 1;
        $pdf .= "xref\n0 $n\n0000000000 65535 f \n";
        for ($i = 1; $i < $n; $i++) $pdf .= sprintf("%010d 00000 n \n", $off[$i]);
        $pdf .= "trailer\n<< /Size $n /Root $catalog 0 R /Info $info 0 R >>\nstartxref\n$xref\n%%EOF\n";
        return $pdf;
    }
}

/** Compatibility shim used by the diagnose endpoint. */
function docx_paragraphs(string $docxPath, ?string &$err = null): array
{
    $m = dx_load($docxPath, [], $err);
    if (!$m) return [];
    $out = [];
    $walk = function (array $blocks) use (&$walk, &$out) {
        foreach ($blocks as $b) {
            if ($b['type'] === 'table') { foreach ($b['rows'] as $r) foreach ($r as $c) $walk($c['blocks']); continue; }
            $t = ''; foreach ($b['runs'] as $r) { $t .= $r['text'] ?? (isset($r['signature']) ? '{{signature}}' : ''); }
            $out[] = ['text' => trim($t), 'bold' => false, 'bullet' => $b['bullet']];
        }
    };
    $walk($m['body']); $walk($m['header']); $walk($m['footer']);
    return $out;
}

function agreement_pdf(string $templateDocx, string $destPdf, array $vars, ?string $signaturePng = null, ?string &$err = null): bool
{
    $err = null;
    try {
        return agreement_pdf_inner($templateDocx, $destPdf, $vars, $signaturePng, $err);
    } catch (\Throwable $t) {
        $err = get_class($t) . ': ' . $t->getMessage() . ' @' . basename($t->getFile()) . ':' . $t->getLine();
        return false;
    }
}

function agreement_pdf_inner(string $templateDocx, string $destPdf, array $vars, ?string $signaturePng, ?string &$err): bool
{
    $m = dx_load($templateDocx, $vars, $err);
    if (!$m) return false;

    $d = new PdfDoc();
    [$d->W, $d->H, $d->mT, $d->mB, $d->mL, $d->mR, $d->mH, $d->mF] = $m['page'];
    $width = $d->W - $d->mL - $d->mR;

    if ($signaturePng && is_file($signaturePng) && function_exists('imagecreatefromstring')) {
        $raw = @file_get_contents($signaturePng);
        $im = $raw !== false ? @imagecreatefromstring($raw) : false;
        if ($im) {
            $iw = imagesx($im); $ih = imagesy($im);
            $canvas = imagecreatetruecolor($iw, $ih);
            imagefilledrectangle($canvas, 0, 0, $iw, $ih, imagecolorallocate($canvas, 255, 255, 255));
            imagecopy($canvas, $im, 0, 0, 0, 0, $iw, $ih);
            ob_start(); imagejpeg($canvas, null, 92); $jpg = ob_get_clean();
            imagedestroy($im); imagedestroy($canvas);
            $dw = 120.0; $dh = $dw * $ih / $iw; if ($dh > 50) { $dh = 50.0; $dw = $dh * $iw / $ih; }
            $d->sig = ['key' => $d->imgKey(['data' => $jpg, 'w' => $iw, 'h' => $ih]), 'w' => $dw, 'h' => $dh];
        }
    }

    $d->bodyTop = $d->H - $d->mT; $d->bodyBottom = $d->mB;
    $d->prepareHeaderFooter($m['header'], $m['footer'], $d->mL, $width);
    $d->y = $d->bodyTop;
    $d->renderBlocks($m['body'], $d->mL, $width);
    $pdf = $d->build($vars);

    if (@file_put_contents($destPdf, $pdf) === false) { $err = 'cannot write ' . basename($destPdf) . ' (is uploads/agreements/ writable?)'; return false; }
    return true;
}

/**
 * Agreement templates can be .docx (rendered to PDF on the server) or .html
 * (rendered by the browser with the template's own CSS, then the PDF the
 * browser produces is uploaded back and archived — pixel-perfect styling).
 */
function agreement_template_kind(string $filePath): string
{
    $ext = strtolower(pathinfo($filePath, PATHINFO_EXTENSION));
    if ($ext === 'html' || $ext === 'htm') return 'html';
    if ($ext === 'pdf') return 'pdf';   // your designed PDF, values overlaid in the browser
    return 'docx';
}

/** Templates rendered in the browser (PDF materialised on first view). */
function agreement_kind_is_browser(string $kind): bool
{
    return $kind === 'html' || $kind === 'pdf';
}

/**
 * Fill an HTML template: every {{key}} becomes its escaped value and
 * {{signature}} becomes an inline <img> with the signature embedded as a
 * data URL (so the page has no external dependencies when it is rendered).
 */
function agreement_fill_html(string $htmlPath, array $vars, ?string $signaturePng, ?string &$err = null): ?string
{
    $err = null;
    if (!is_file($htmlPath)) { $err = 'template file missing: ' . basename($htmlPath); return null; }
    $html = @file_get_contents($htmlPath);
    if ($html === false || $html === '') { $err = 'template is empty or unreadable'; return null; }

    foreach ($vars as $k => $v) {
        if ($k === 'signature') continue;
        $html = str_replace('{{' . $k . '}}', htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'), $html);
    }

    $sigTag = '<span class="hrms-sig-missing">(signed digitally — ' . htmlspecialchars((string)($vars['ref'] ?? ''), ENT_QUOTES, 'UTF-8') . ')</span>';
    if ($signaturePng && is_file($signaturePng)) {
        $raw = @file_get_contents($signaturePng);
        $info = $raw !== false ? @getimagesize($signaturePng) : false;
        if ($raw !== false && $info) {
            $mime = $info['mime'] ?? 'image/png';
            $sigTag = '<img class="hrms-signature" alt="Signature" src="data:' . $mime . ';base64,' . base64_encode($raw) . '">';
        }
    }
    $html = str_replace('{{signature}}', $sigTag, $html);
    return $html;
}

/**
 * Mark an agreement signed for an HTML template. No file is produced here —
 * the browser generates the PDF on first view and uploads it back.
 */
function agreement_mark_signed_html(PDO $pdo, int $agreementId, string $ref, bool $auto): void
{
    $pdo->prepare(
        "UPDATE agreements SET status = 'signed', signed_at = NOW(), reference = ?, signed_ip = ?, auto_signed = ?
         WHERE agreement_id = ?"
    )->execute([$ref, $_SERVER['REMOTE_ADDR'] ?? '', $auto ? 1 : 0, $agreementId]);
}

/**
 * Per-agreement render error journal (uploads/agreements/render_errors.json)
 * so a failure can be shown on screen instead of silently staying "pending".
 */
function agreement_error_set(int $agreementId, ?string $msg): void
{
    $f = __DIR__ . '/uploads/agreements/render_errors.json';
    $all = is_file($f) ? (json_decode((string)@file_get_contents($f), true) ?: []) : [];
    if ($msg === null) unset($all[(string)$agreementId]);
    else $all[(string)$agreementId] = ['error' => $msg, 'at' => date('Y-m-d H:i:s')];
    @file_put_contents($f, json_encode($all));
}
function agreement_errors_all(): array
{
    $f = __DIR__ . '/uploads/agreements/render_errors.json';
    return is_file($f) ? (json_decode((string)@file_get_contents($f), true) ?: []) : [];
}

/**
 * Build the {{placeholder}} values for one employee's agreement.
 * Shared by agreements.send (auto-sign) and agreements.sign (manual).
 */
function agreement_vars(array $emp, string $ref): array
{
    return [
        'name' => $emp['full_name'],
        'code' => $emp['employee_code'],
        'department' => $emp['department_name'] ?? '',
        'designation' => $emp['designation'] ?? '',
        'joining_date' => $emp['joining_date'] ? date('d F Y', strtotime($emp['joining_date'])) : '',
        'date' => date('d F Y'),
        'salary' => (float)$emp['monthly_salary'] > 0 ? '₹' . number_format((float)$emp['monthly_salary'], 0) : '',
        'mobile' => $emp['mobile'] ?? '',
        'email' => $emp['email'] ?? '',
        'address' => $emp['address'] ?? '',
        'signed_at' => date('d M Y, h:i A'),
        'ref' => $ref,
    ];
}

/**
 * Find a usable signature image for one employee and return an absolute path
 * to a PNG that can be embedded.
 *
 * Primary source: the employee's uploaded document whose type name contains
 * "signature" (the "Digital Signature" document), approved ones first.
 * Fallback: a signature drawn on the My Agreements pad.
 *
 * File type is detected from the CONTENTS, not the extension. PNG/JPG/GIF/
 * WEBP/BMP are all accepted and normalised to PNG. A PDF is rejected.
 * The converted PNG is cached in employees.signature_file when that column
 * exists; nothing here breaks when it doesn't.
 */
function employee_signature_png(PDO $pdo, array $emp, ?string &$why = null): ?string
{
    global $HAS_SIG_COL;
    $employeeId = (int)$emp['employee_id'];
    $why = null;

    $dir = __DIR__ . '/uploads/agreements/';
    if (!is_dir($dir)) @mkdir($dir, 0755, true);
    $outRel = 'uploads/agreements/sig_' . $employeeId . '.png';
    $out = __DIR__ . '/' . $outRel;

    // Turns an image or PDF signature into a PNG. Sets $reason on failure.
    $toPng = function (string $src, string $dest, ?string &$reason) : bool {
        $reason = null;
        $ext = strtolower(pathinfo($src, PATHINFO_EXTENSION));
        $head = (string)@file_get_contents($src, false, null, 0, 5);

        // PDF signature document: render its first page.
        if ($ext === 'pdf' || $head === '%PDF-') {
            if (!class_exists('Imagick')) { $reason = 'the signature is a PDF and this server cannot convert PDFs — upload it as a PNG or JPG photo'; return false; }
            try {
                $im = new Imagick();
                $im->setResolution(200, 200);
                $im->readImage($src . '[0]');
                $im->setImageBackgroundColor('white');
                $im = $im->mergeImageLayers(Imagick::LAYERMETHOD_FLATTEN);
                $im->trimImage(20000);           // crop the empty page around the signature
                $im->setImageFormat('png');
                $ok = $im->writeImage($dest);
                $im->clear();
                if (!$ok) $reason = 'could not convert the PDF signature';
                return (bool)$ok;
            } catch (Throwable $e) {
                $reason = 'could not read the PDF signature (' . $e->getMessage() . ')';
                return false;
            }
        }

        $info = @getimagesize($src);
        if (!$info || empty($info[0])) { $reason = 'the signature file is not a readable image (use PNG or JPG)'; return false; }
        if (($info[2] ?? 0) === IMAGETYPE_PNG) return @copy($src, $dest);
        if (!function_exists('imagecreatefromstring')) { $reason = 'this server has no image library to convert the signature'; return false; }
        $raw = @file_get_contents($src);
        $im = $raw === false ? false : @imagecreatefromstring($raw);
        if (!$im) { $reason = 'this image type is not supported (use PNG or JPG — HEIC/WEBP photos from phones often fail)'; return false; }
        if (function_exists('imagepalettetotruecolor')) @imagepalettetotruecolor($im);
        $ok = @imagepng($im, $dest);
        imagedestroy($im);
        if (!$ok) $reason = 'could not save the converted signature';
        return (bool)$ok;
    };

    $cache = function (string $rel) use ($pdo, $employeeId, $HAS_SIG_COL) {
        if (!$HAS_SIG_COL) return;
        try {
            $pdo->prepare("UPDATE employees SET signature_file = ? WHERE employee_id = ?")->execute([$rel, $employeeId]);
        } catch (PDOException $e) { /* cache only */ }
    };

    // 1. Uploaded Digital Signature document (primary).
    try {
        $stmt = $pdo->prepare(
            "SELECT ed.document_file
             FROM employee_documents ed
             JOIN document_types dt ON dt.document_type_id = ed.document_type_id
             WHERE ed.employee_id = ?
               AND LOWER(dt.document_name) LIKE '%signature%'
               AND ed.document_file IS NOT NULL
               AND ed.document_file <> ''
             ORDER BY (ed.status = 'approved') DESC, ed.uploaded_at DESC
             LIMIT 5"
        );
        $stmt->execute([$employeeId]);
        $candidates = $stmt->fetchAll(PDO::FETCH_COLUMN);
    } catch (PDOException $e) {
        $candidates = [];
    }
    foreach ($candidates as $rel) {
        $src = find_upload_on_account((string)$rel);
        if (!$src) { $why = 'the signature file is missing on the server (uploaded before the domain move) — re-upload the Digital Signature document'; continue; }
        // Already converted and unchanged since? Reuse it — keeps the
        // Send list's status check fast.
        if (is_file($out) && filemtime($out) >= filemtime($src) && @getimagesize($out)) { $why = null; return $out; }
        $reason = null;
        if ($toPng($src, $out, $reason)) {
            $cache($outRel);
            $why = null;
            return $out;
        }
        $why = $reason;
    }

    // 2. Drawn signature (fallback).
    $pad = $emp['signature_file'] ?? null;
    if (!empty($pad)) {
        $padPath = find_upload_on_account((string)$pad);
        if ($padPath && @getimagesize($padPath)) { $why = null; return $padPath; }
    }
    if (is_file($out) && @getimagesize($out)) { $why = null; return $out; } // earlier cached copy

    if ($why === null) $why = 'no Digital Signature document uploaded';
    return null;
}

/**
 * Sign every pending agreement for one employee using their saved signature.
 * Used when an agreement is sent (agreements.send) and the moment the employee
 * saves a signature (signature.save) — employees never get a sign request.
 * Returns how many documents were generated.
 */
function agreements_autosign_pending(PDO $pdo, int $employeeId): int
{
    $eStmt = $pdo->prepare(
        "SELECT e.*, d.department_name FROM employees e
         LEFT JOIN departments d ON d.department_id = e.department_id
         WHERE e.employee_id = ?"
    );
    $eStmt->execute([$employeeId]);
    $emp = $eStmt->fetch();
    if (!$emp) return 0;

    $sigWhy = null;
    $sigPath = employee_signature_png($pdo, $emp, $sigWhy);

    $dir = __DIR__ . '/uploads/agreements/';
    if (!is_dir($dir)) mkdir($dir, 0755, true);

    $pend = $pdo->prepare(
        "SELECT a.agreement_id, t.file_path
         FROM agreements a
         JOIN agreement_templates t ON t.template_id = a.template_id
         WHERE a.employee_id = ? AND a.status <> 'signed'"
    );
    $pend->execute([$employeeId]);

    $upd = $pdo->prepare(
        "UPDATE agreements SET status = 'signed', signed_at = NOW(), signed_file = ?, reference = ?,
                signed_ip = ?, auto_signed = 1
         WHERE agreement_id = ?"
    );

    $rows = $pend->fetchAll();
    if (!$sigPath) {
        foreach ($rows as $a) agreement_error_set((int)$a['agreement_id'], 'Not auto-signed: ' . ($sigWhy ?: 'no usable signature image'));
        return 0;
    }

    $done = 0;
    foreach ($rows as $a) {
        $agreementId = (int)$a['agreement_id'];
        $ref = 'HRMS-' . date('Y') . '-' . str_pad((string)$employeeId, 4, '0', STR_PAD_LEFT) . '-' . $agreementId;

        if (agreement_kind_is_browser(agreement_template_kind($a['file_path']))) {
            try { agreement_mark_signed_html($pdo, $agreementId, $ref, true); agreement_error_set($agreementId, null); agreement_email_queue($pdo, $agreementId, 'signed'); $done++; }
            catch (PDOException $e) { agreement_error_set($agreementId, 'database update failed: ' . $e->getMessage()); }
            continue;
        }

        $outName = 'signed_' . $agreementId . '_' . time() . '_' . bin2hex(random_bytes(3)) . '.pdf';
        $why = null;
        $ok = agreement_pdf(
            upload_abs($a['file_path']),
            $dir . $outName,
            agreement_vars($emp, $ref),
            $sigPath,
            $why
        );
        if (!$ok) { agreement_error_set($agreementId, $why ?: 'unknown render failure'); continue; }
        try {
            $upd->execute(['uploads/agreements/' . $outName, $ref, $_SERVER['REMOTE_ADDR'] ?? '', $agreementId]);
            agreement_email_queue($pdo, $agreementId, 'signed');
        } catch (PDOException $e) {
            agreement_error_set($agreementId, 'database update failed: ' . $e->getMessage());
            continue;
        }
        agreement_error_set($agreementId, null);
        $done++;
    }
    return $done;
}


/**
 * Older agreements were generated as .docx, which several Word/WPS/mobile
 * viewers refuse to open. Any signed agreement still pointing at a .docx is
 * re-rendered as PDF here, so the View button always serves a PDF.
 * Runs in small batches and never throws — purely opportunistic.
 */
function agreements_upgrade_docx_to_pdf(PDO $pdo): int
{
    try {
        $rows = $pdo->query(
            "SELECT a.agreement_id, a.employee_id, a.reference, a.signed_file, t.file_path
             FROM agreements a
             JOIN agreement_templates t ON t.template_id = a.template_id
             WHERE a.status = 'signed'
               AND a.signed_file IS NOT NULL
               AND a.signed_file <> ''
               AND a.signed_file NOT LIKE '%.pdf'
             LIMIT 25"
        )->fetchAll();
    } catch (PDOException $e) {
        return 0;
    }
    if (!$rows) return 0;

    $dir = __DIR__ . '/uploads/agreements/';
    if (!is_dir($dir)) mkdir($dir, 0755, true);

    $eStmt = $pdo->prepare(
        "SELECT e.*, d.department_name FROM employees e
         LEFT JOIN departments d ON d.department_id = e.department_id
         WHERE e.employee_id = ?"
    );
    $upd = $pdo->prepare("UPDATE agreements SET signed_file = ?, reference = ? WHERE agreement_id = ?");

    $done = 0;
    foreach ($rows as $a) {
        $eStmt->execute([(int)$a['employee_id']]);
        $emp = $eStmt->fetch();
        if (!$emp) continue;

        $ref = $a['reference'] ?: ('HRMS-' . date('Y') . '-'
            . str_pad((string)(int)$a['employee_id'], 4, '0', STR_PAD_LEFT) . '-' . (int)$a['agreement_id']);

        if (agreement_kind_is_browser(agreement_template_kind($a['file_path']))) {
            // Browser-rendered template: drop the stale docx, PDF arrives on first view.
            $pdo->prepare("UPDATE agreements SET signed_file = NULL, reference = ? WHERE agreement_id = ?")->execute([$ref, (int)$a['agreement_id']]);
            if ($a['signed_file'] && file_exists(__DIR__ . '/' . $a['signed_file'])) @unlink(__DIR__ . '/' . $a['signed_file']);
            $done++;
            continue;
        }

        $sigPath = employee_signature_png($pdo, $emp);
        $outName = 'signed_' . (int)$a['agreement_id'] . '_' . time() . '_' . bin2hex(random_bytes(3)) . '.pdf';

        $why = null;
        if (!agreement_pdf(upload_abs($a['file_path']), $dir . $outName, agreement_vars($emp, $ref), $sigPath, $why)) {
            agreement_error_set((int)$a['agreement_id'], 'PDF upgrade failed: ' . ($why ?: 'unknown'));
            continue;
        }

        $old = $a['signed_file'];
        $upd->execute(['uploads/agreements/' . $outName, $ref, (int)$a['agreement_id']]);
        if ($old && file_exists(__DIR__ . '/' . $old)) @unlink(__DIR__ . '/' . $old);
        $done++;
    }
    return $done;
}

/**
 * targets.prepaid_amount and targets.avg_ticket cache commission inputs
 * gathered during targets.sync_orders. Created once if missing, same
 * self-healing pattern as ensure_signature_column().
 */
/**
 * House-wise (store group) tracking: adds a `group_key` column to a table
 * that previously had one row per (employee, date/month) and rebuilds its
 * unique key to include group_key, so an employee can have a separate row
 * per house (TM Perfume House / TM4U) instead of one shared
 * total. Reads the table's real unique/primary key from MySQL's own catalog
 * (information_schema) rather than guessing an index name, so the rebuild
 * targets whatever actually exists. Runs once per table (cached via a temp
 * flag file, same pattern as the other self-healing tables in this file);
 * any failure is caught and simply leaves the column/key as they were, so a
 * problem here degrades to "house split doesn't work yet" rather than
 * breaking the table.
 */
function ensure_group_key_column(PDO $pdo, string $table, array $oldKeyCols): bool
{
    static $done = [];
    if (isset($done[$table])) return $done[$table];
    $flag = sys_get_temp_dir() . '/hrms_groupkey_' . preg_replace('/[^a-z_]/', '', $table) . '_ok';
    if (is_file($flag)) return $done[$table] = true;

    try {
        $cols = $pdo->query("SHOW COLUMNS FROM `$table`")->fetchAll(PDO::FETCH_COLUMN);
        if (!in_array('group_key', $cols, true)) {
            $pdo->exec("ALTER TABLE `$table` ADD COLUMN group_key VARCHAR(10) NOT NULL DEFAULT ''");
        }

        $rows = $pdo->query(
            "SELECT INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols
             FROM information_schema.STATISTICS
             WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = " . $pdo->quote($table) . " AND NON_UNIQUE = 0
             GROUP BY INDEX_NAME"
        )->fetchAll();

        $oldSet = $oldKeyCols; sort($oldSet);
        $newSet = array_merge($oldKeyCols, ['group_key']); sort($newSet);
        $already = false; $oldIndexName = null;
        foreach ($rows as $r) {
            $set = explode(',', $r['cols']); sort($set);
            if ($set === $newSet) $already = true;
            if ($set === $oldSet) $oldIndexName = $r['INDEX_NAME'];
        }

        if (!$already) {
            $newKeyCols = implode(', ', array_map(fn($c) => "`$c`", array_merge($oldKeyCols, ['group_key'])));
            if ($oldIndexName === 'PRIMARY') {
                $pdo->exec("ALTER TABLE `$table` DROP PRIMARY KEY, ADD PRIMARY KEY ($newKeyCols)");
            } elseif ($oldIndexName) {
                $pdo->exec("ALTER TABLE `$table` DROP INDEX `$oldIndexName`, ADD UNIQUE KEY `uk_{$table}_grp` ($newKeyCols)");
            } else {
                $pdo->exec("ALTER TABLE `$table` ADD UNIQUE KEY `uk_{$table}_grp` ($newKeyCols)");
            }
        }

        @file_put_contents($flag, '1');
        return $done[$table] = true;
    } catch (PDOException $e) {
        return $done[$table] = false;
    }
}

/** Normalises a store-group filter/value: '' means "no house" / "all houses" depending on context. */
function normalize_group_key(?string $g): string
{
    $valid = array_keys(store_group_options());
    return ($g && in_array($g, $valid, true)) ? $g : '';
}

/**
 * Convincing and Customer ratings accept one decimal place (1.0 - 10.0),
 * so their columns must be DECIMAL rather than INT — an INT column silently
 * truncates 5.6 to 5 at the database level, no matter what the API accepts.
 * Behavior stays a whole number: it is set by the Good/Average/Bad chips,
 * which only ever send 5, 3 or 1.
 */
/**
 * Add-ons: extra products an employee upsold onto an existing order.
 * One row per product added, so a single add-on event with three products
 * stores three rows sharing the same order_name and date — that keeps
 * "which products get upsold most" answerable later.
 *
 * Kept separate from targets.achieved on purpose: the customer pays the
 * combined total, so the add-on value already arrives inside the Shopify
 * order. Counting it again here would double-count the same rupees.
 */
/**
 * Finds a punch photo anywhere on this hosting account.
 *
 * Both the old server (empmanagment.tmbodywash.com) and the new one
 * (fourpirates.space) share one database. A phone still running an old
 * cached config.js sends its punch to the OLD api.php, which saves the photo
 * in the old domain's folder — while the DB row it writes is shared. So the
 * row exists but the file is "missing" from the new server's folder.
 * This searches every domain folder on the account for the same file.
 * Only files named like a punch photo, inside an uploads/attendance folder,
 * are ever returned.
 */
/**
 * Finds an uploaded file by its stored relative path ("uploads/…/name.ext"),
 * first next to this api.php, then in every other site folder on the
 * hosting account. Files uploaded before the move to the new domain were
 * never copied over, so the database row exists but the file sits in the
 * OLD domain's folder. Only paths under uploads/ are accepted.
 */
function find_upload_on_account(string $rel): ?string
{
    $rel = ltrim(str_replace('\\', '/', $rel), '/');
    if (strpos($rel, 'uploads/') !== 0 || strpos($rel, '..') !== false) return null;

    $here = __DIR__ . '/' . $rel;
    if (is_file($here)) return $here;

    $home = dirname(__DIR__, 4);
    foreach (['', '/*', '/*/*'] as $depth) {
        foreach ([$home . '/domains/*/public_html' . $depth . '/' . $rel, $home . '/public_html' . $depth . '/' . $rel] as $pat) {
            foreach (@glob($pat) ?: [] as $hit) {
                if (is_file($hit)) return $hit;
            }
        }
    }
    return null;
}

/**
 * Absolute path for a stored upload path, wherever it lives on the account
 * (this domain first, then the old one). Falls back to the local path so
 * callers get the same "file missing" error they always did.
 */
function upload_abs(string $rel): string
{
    return find_upload_on_account($rel) ?: (__DIR__ . '/' . ltrim($rel, '/'));
}

function find_attendance_photo_on_account(string $rel): ?string
{
    $name = basename($rel);
    if (!preg_match('/^punch_\d+_(in|out)_\d+_[a-f0-9]+\.jpg$/', $name)) return null;

    $here = __DIR__ . '/' . $rel;
    if (is_file($here)) return $here;

    // /home/<user>/domains/<site>/public_html/<app> -> /home/<user>
    $home = dirname(__DIR__, 4);
    $patterns = [];
    foreach (['', '/*', '/*/*'] as $depth) {
        $patterns[] = $home . '/domains/*/public_html' . $depth . '/uploads/attendance/' . $name;
        $patterns[] = $home . '/public_html' . $depth . '/uploads/attendance/' . $name;
    }
    foreach ($patterns as $pat) {
        $hits = @glob($pat) ?: [];
        foreach ($hits as $h) {
            if (is_file($h)) return $h;
        }
    }
    return null;
}

/** Every copy of the HRMS api.php on this hosting account. */
function find_hrms_api_copies(): array
{
    $home = dirname(__DIR__, 4);
    $found = [];
    foreach (['', '/*', '/*/*'] as $depth) {
        foreach ([$home . '/domains/*/public_html' . $depth . '/api.php', $home . '/public_html' . $depth . '/api.php'] as $pat) {
            foreach (@glob($pat) ?: [] as $f) {
                $head = (string)@file_get_contents($f, false, null, 0, 20000);
                if (strpos($head, 'attendance') === false || strpos($head, 'employees') === false) continue;
                $found[$f] = [
                    'file' => $f,
                    'modified' => date('Y-m-d H:i:s', filemtime($f)),
                    'bytes' => filesize($f),
                    'is_this_one' => realpath($f) === realpath(__FILE__),
                    'photos_in_its_attendance_folder' => count(@glob(dirname($f) . '/uploads/attendance/*.jpg') ?: []),
                ];
            }
        }
    }
    return array_values($found);
}

/**
 * Per-order ratings: each order a salesperson handled gets its own
 * Ticket size convincing (1–10, half-star steps), Call rating (1–10) and
 * Customer behaviour (5 Good / 3 Average / 1 Bad). order_key is
 * "<storeKey>:<shopify order id>" so the same order is never rated twice.
 */
function ensure_order_ratings_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_order_ratings_ok_v1';
    if (is_file($flag)) return $done = true;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS order_ratings (
                rating_id INT AUTO_INCREMENT PRIMARY KEY,
                order_key VARCHAR(80) NOT NULL,
                order_name VARCHAR(60) NOT NULL DEFAULT '',
                employee_id INT NOT NULL,
                rating_date DATE NOT NULL,
                group_key VARCHAR(10) NOT NULL DEFAULT '',
                ticket_rating DECIMAL(4,1) NULL,
                call_rating DECIMAL(4,1) NULL,
                behaviour_rating TINYINT NULL,
                updated_by VARCHAR(100) NULL,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY uq_order (order_key),
                KEY idx_emp_date (employee_id, rating_date)
            )"
        );
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

/** Who gave the Ticket-size stars and when (ticket_by / ticket_at) — checked on the table itself, added when missing. */
function ensure_order_ratings_ticket_columns(PDO $pdo): void
{
    static $done = false;
    if ($done) return;
    $done = true;
    try {
        $have = [];
        foreach ($pdo->query("SHOW COLUMNS FROM order_ratings")->fetchAll() as $c) $have[strtolower((string)$c['Field'])] = true;
        if (!isset($have['ticket_by'])) $pdo->exec("ALTER TABLE order_ratings ADD COLUMN ticket_by VARCHAR(100) NULL");
        if (!isset($have['ticket_at'])) $pdo->exec("ALTER TABLE order_ratings ADD COLUMN ticket_at DATETIME NULL");
    } catch (PDOException $e) { /* reads fall back to updated_by / updated_at */ }
}

/**
 * Automatic daily targets — a SET of rules plus two shared settings.
 *
 * Settings (target_rule, one row, rule_id = 1):
 *   enabled     — automatic targets on/off
 *   groups_csv  — which houses' employees get automatic targets. A house
 *                 added later is NOT included until someone ticks it.
 *
 * Rules (target_rules, one row each). A rule covers some weekdays; the
 * rule covering the selected day's weekday sets that day's target:
 *   basis 'days'    — average of the previous `lookback` days
 *   basis 'weekday' — average of the same weekday over the previous
 *                     `lookback` weeks (e.g. last 3 Sundays for a Sunday)
 *   target = average × (1 + pct/100), to the rupee, never below min_target.
 *   skip_zero leaves days with no sales out of the average.
 * A weekday belongs to at most one rule; days in no rule fall back to the
 * profile / monthly target.
 */
/**
 * Houses shown on the Targets page: only those with their own Shopify store,
 * so they have sales to count. TM4U has no store, so it isn't a Targets house
 * (it stays a normal house everywhere else in the app).
 */
/**
 * Employee label colour (hex like #3d7bf3), picked on Assign Queries —
 * one per employee PER HOUSE, so someone in TM Perfume House and TM4U can
 * be yellow in one and red in the other.
 */
function ensure_employee_color_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS employee_label_colors (
                employee_id INT NOT NULL,
                group_key VARCHAR(40) NOT NULL DEFAULT '',
                color VARCHAR(7) NOT NULL,
                PRIMARY KEY (employee_id, group_key)
            )"
        );
    } catch (PDOException $e) {}
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['employee_label_colors']);
}
/** "employee|house" => '#rrggbb' */
function employee_colors(PDO $pdo): array
{
    static $cache = null;
    if ($cache !== null) return $cache;
    $cache = [];
    ensure_employee_color_table($pdo);
    try {
        foreach ($pdo->query("SELECT employee_id, group_key, color FROM employee_label_colors")->fetchAll() as $r) {
            $cache[(int)$r['employee_id'] . '|' . $r['group_key']] = (string)$r['color'];
        }
    } catch (PDOException $e) {}
    return $cache;
}

/** Click log behind the Assign Queries "By hour" grid. */
/** Sum of one employee's logged clicks of a kind in one clock hour of a day. */
function query_hour_sum(PDO $pdo, string $date, string $groupKey, int $empId, string $kind, int $hour): int
{
    try {
        $st = $pdo->prepare("SELECT COALESCE(SUM(delta),0) FROM employee_query_log WHERE query_date = ? AND group_key = ? AND employee_id = ? AND kind = ? AND HOUR(created_at) = ?");
        $st->execute([$date, $groupKey, $empId, $kind, $hour]);
        return max(0, (int)$st->fetchColumn());
    } catch (PDOException $e) { return 0; }
}
/**
 * Timestamp for a click filed under a given hour: the real time when that
 * is the hour running now, else half past that hour (only the hour part is
 * ever read back).
 */
function query_hour_stamp(PDO $pdo, string $date, int $hour): string
{
    if ($date === biz_today($pdo) && (int)date('G') === $hour) return date('Y-m-d H:i:s');
    // The business day runs past midnight, so an hour before the day start
    // belongs to the NEXT calendar date (10 PM = same day, 1 AM = next day).
    $startHour = (int)substr(day_start_for($pdo, $date), 0, 2);
    $cal = $hour < $startHour ? date('Y-m-d', strtotime($date . ' +1 day')) : $date;
    return $cal . ' ' . sprintf('%02d', $hour) . ':30:00';
}

/** The 24 hours of a business day in order: day start … 23, 0 … day start − 1. */
function biz_hour_sequence(PDO $pdo, string $date): array
{
    $start = (int)substr(day_start_for($pdo, $date), 0, 2);
    $out = [];
    for ($i = 0; $i < 24; $i++) $out[] = ($start + $i) % 24;
    return $out;
}

function ensure_query_log_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS employee_query_log (
                id INT AUTO_INCREMENT PRIMARY KEY,
                query_date DATE NOT NULL,
                group_key VARCHAR(40) NOT NULL DEFAULT '',
                employee_id INT NOT NULL,
                kind VARCHAR(12) NOT NULL,
                delta TINYINT NOT NULL,
                created_at DATETIME NOT NULL,
                INDEX (query_date, group_key)
            )"
        );
    } catch (PDOException $e) {}
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['employee_query_log']);
}

/**
 * Email (agreements). Sends through the HR mailbox by SMTP over SSL — no
 * library needed. Settings come from config.php:
 *   MAIL_HOST, MAIL_PORT, MAIL_USER, MAIL_PASS, MAIL_FROM_NAME, APP_URL
 * With MAIL_USER/MAIL_PASS missing, sending is simply skipped (recorded
 * as "not configured") so nothing else is affected.
 */
function mail_config(): ?array
{
    if (!defined('MAIL_USER') || !defined('MAIL_PASS') || MAIL_USER === '' || MAIL_PASS === '') return null;
    return [
        'host' => defined('MAIL_HOST') ? MAIL_HOST : 'smtp.hostinger.com',
        'port' => defined('MAIL_PORT') ? (int)MAIL_PORT : 465,
        'user' => MAIL_USER,
        'pass' => MAIL_PASS,
        'from_name' => defined('MAIL_FROM_NAME') ? MAIL_FROM_NAME : 'HR',
    ];
}
function app_url(): string
{
    return rtrim(defined('APP_URL') ? APP_URL : '', '/');
}
/** Sends one email. Returns null on success, else the error text. */
function send_mail(string $toEmail, string $toName, string $subject, string $html, array $attachments = []): ?string
{
    $cfg = mail_config();
    if (!$cfg) return 'Email is not configured (MAIL_USER / MAIL_PASS missing in config.php).';
    if (!filter_var($toEmail, FILTER_VALIDATE_EMAIL)) return 'Invalid email address.';

    $boundary = 'b' . bin2hex(random_bytes(12));
    $enc = fn(string $t) => '=?UTF-8?B?' . base64_encode($t) . '?=';
    $headers = [
        'Date: ' . date('r'),
        'From: ' . $enc($cfg['from_name']) . ' <' . $cfg['user'] . '>',
        'To: ' . $enc($toName) . ' <' . $toEmail . '>',
        'Subject: ' . $enc($subject),
        'Message-ID: <' . bin2hex(random_bytes(8)) . '@' . (explode('@', $cfg['user'])[1] ?? 'hrms') . '>',
        'MIME-Version: 1.0',
        'Content-Type: multipart/mixed; boundary="' . $boundary . '"',
    ];
    $text = trim(strip_tags(preg_replace('/<br\s*\/?>|<\/p>/i', "\n", $html)));
    $body = "--$boundary\r\nContent-Type: multipart/alternative; boundary=\"alt$boundary\"\r\n\r\n"
        . "--alt$boundary\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" . chunk_split(base64_encode($text))
        . "--alt$boundary\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" . chunk_split(base64_encode($html))
        . "--alt$boundary--\r\n";
    foreach ($attachments as $att) {           // ['path' => ..., 'name' => ...]
        if (empty($att['path']) || !is_file($att['path'])) continue;
        $body .= "--$boundary\r\nContent-Type: application/pdf; name=\"{$att['name']}\"\r\nContent-Transfer-Encoding: base64\r\n"
            . "Content-Disposition: attachment; filename=\"{$att['name']}\"\r\n\r\n" . chunk_split(base64_encode((string)file_get_contents($att['path'])));
    }
    $body .= "--$boundary--\r\n";
    $message = implode("\r\n", $headers) . "\r\n\r\n" . $body;

    $transport = $cfg['port'] === 465 ? 'ssl://' : '';
    $sock = @stream_socket_client($transport . $cfg['host'] . ':' . $cfg['port'], $errno, $errstr, 20);
    if (!$sock) return "Could not reach the mail server ({$cfg['host']}:{$cfg['port']}): $errstr";
    stream_set_timeout($sock, 20);
    $read = function () use ($sock): string {
        $out = '';
        while (($line = fgets($sock, 2048)) !== false) { $out .= $line; if (strlen($line) < 4 || $line[3] !== '-') break; }
        return $out;
    };
    $cmd = function (string $c, array $okCodes) use ($sock, $read): ?string {
        fwrite($sock, $c . "\r\n");
        $r = $read();
        return in_array((int)substr($r, 0, 3), $okCodes, true) ? null : trim($r);
    };
    $ehlo = preg_replace('/[^A-Za-z0-9.\-]/', '', (string)(explode('@', $cfg['user'])[1] ?? '')) ?: 'localhost';   // a real domain, not a bare word: some mail servers refuse a bare "hrms"
    try {
        $r = $read(); if ((int)substr($r, 0, 3) !== 220) return 'Mail server refused the connection: ' . trim($r);
        if ($e = $cmd('EHLO ' . $ehlo, [250])) return "EHLO failed: $e";
        if ($cfg['port'] !== 465) {                       // STARTTLS on 587
            if ($e = $cmd('STARTTLS', [220])) return "STARTTLS failed: $e";
            if (!stream_socket_enable_crypto($sock, true, STREAM_CRYPTO_METHOD_TLS_CLIENT)) return 'TLS could not be started.';
            if ($e = $cmd('EHLO ' . $ehlo, [250])) return "EHLO failed: $e";
        }
        if ($e = $cmd('AUTH LOGIN', [334])) return "Login not accepted: $e";
        if ($e = $cmd(base64_encode($cfg['user']), [334])) return "Login not accepted: $e";
        if ($e = $cmd(base64_encode($cfg['pass']), [235])) return "Mailbox password rejected: $e";
        if ($e = $cmd('MAIL FROM:<' . $cfg['user'] . '>', [250])) return "Sender rejected: $e";
        if ($e = $cmd('RCPT TO:<' . $toEmail . '>', [250, 251])) return "Recipient rejected: $e";
        if ($e = $cmd('DATA', [354])) return "DATA rejected: $e";
        // dot-stuffing per RFC 5321
        fwrite($sock, preg_replace('/^\./m', '..', $message) . "\r\n.\r\n");
        stream_set_timeout($sock, 90);   // the server may take a while to accept a PDF attachment
        $r = $read(); if ((int)substr($r, 0, 3) !== 250) return 'Message rejected: ' . trim($r);
        $cmd('QUIT', [221]);
        return null;
    } finally {
        fclose($sock);
    }
}

/** One row per agreement email attempt: what was sent, when, or why not. */
function ensure_agreement_emails_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS agreement_emails (
                agreement_id INT NOT NULL,
                kind VARCHAR(12) NOT NULL,
                to_email VARCHAR(190) NOT NULL DEFAULT '',
                sent_at DATETIME NULL,
                error TEXT NULL,
                attempts TINYINT NOT NULL DEFAULT 0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (agreement_id, kind)
            )"
        );
        $col = $pdo->query("SHOW COLUMNS FROM agreement_emails LIKE 'attempts'")->fetch();
        if (!$col) $pdo->exec("ALTER TABLE agreement_emails ADD COLUMN attempts TINYINT NOT NULL DEFAULT 0");
    } catch (PDOException $e) {}
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['agreement_emails']);
}

/**
 * Queue an agreement email (instant — no sending here). The outbox is
 * worked by mail_process(): from the pages in the background right after
 * an action and every half minute while open, and by a cron job if set.
 */
function agreement_email_queue(PDO $pdo, int $agreementId, string $kind, bool $force = false): void
{
    ensure_agreement_emails_table($pdo);
    if (!$force) {
        $q = $pdo->prepare("SELECT sent_at FROM agreement_emails WHERE agreement_id = ? AND kind = ?");
        $q->execute([$agreementId, $kind]);
        if ($q->fetchColumn()) return;          // already delivered
    }
    $pdo->prepare(
        "INSERT INTO agreement_emails (agreement_id, kind, to_email, sent_at, error, attempts) VALUES (?, ?, '', NULL, 'Queued', 0)
         ON DUPLICATE KEY UPDATE sent_at = NULL, error = 'Queued', attempts = 0"
    )->execute([$agreementId, $kind]);
}

/**
 * Send what's waiting in the outbox: up to $max emails per call, oldest
 * first, each retried up to 6 times. Guarded by a lock so two pages don't
 * send the same email at once. Returns [sent, failed, waiting].
 */
function mail_process(PDO $pdo, int $max = 5): array
{
    ensure_agreement_emails_table($pdo);
    $lock = @fopen(sys_get_temp_dir() . '/hrms_mail.lock', 'c') ?: @fopen(__DIR__ . '/uploads/.hrms_mail.lock', 'c');   // temp folder not writable: use ours, never stall silently
    if ($lock && !flock($lock, LOCK_EX | LOCK_NB)) { fclose($lock); return [0, 0, 0]; }   // another page is already sending
    $sent = 0; $failed = 0;
    try {
        $rows = $pdo->query(
            "SELECT agreement_id, kind FROM agreement_emails
             WHERE sent_at IS NULL AND attempts < 6 AND (error IS NULL OR error NOT LIKE 'No email%')
             ORDER BY updated_at ASC LIMIT " . (int)$max
        )->fetchAll();
        foreach ($rows as $r) {
            $pdo->prepare("UPDATE agreement_emails SET attempts = attempts + 1 WHERE agreement_id = ? AND kind = ?")->execute([$r['agreement_id'], $r['kind']]);
            [$ok] = agreement_email($pdo, (int)$r['agreement_id'], (string)$r['kind'], true);
            if ($ok) $sent++; else $failed++;
        }
        $waiting = (int)$pdo->query("SELECT COUNT(*) FROM agreement_emails WHERE sent_at IS NULL AND attempts < 6 AND (error IS NULL OR error NOT LIKE 'No email%')")->fetchColumn();
    } finally {
        if ($lock) { flock($lock, LOCK_UN); fclose($lock); }
    }
    return [$sent, $failed, $waiting];
}

/**
 * Emails the employee about an agreement.
 *   kind 'request' — please sign (link to My Agreements)
 *   kind 'signed'  — signed copy: PDF attached when the file exists on the
 *                    server, otherwise a link to view/download it
 * One successful email per agreement per kind unless $force. Never throws:
 * the result is recorded in agreement_emails and returned as [ok, message].
 */
function agreement_email(PDO $pdo, int $agreementId, string $kind, bool $force = false): array
{
    ensure_agreement_emails_table($pdo);
    $st = $pdo->prepare(
        "SELECT a.*, e.full_name, e.email, e.employee_code, t.template_name
         FROM agreements a JOIN employees e ON e.employee_id = a.employee_id
         JOIN agreement_templates t ON t.template_id = a.template_id WHERE a.agreement_id = ?"
    );
    $st->execute([$agreementId]);
    $a = $st->fetch();
    if (!$a) return [false, 'Agreement not found.'];

    $rec = $pdo->prepare(
        "INSERT INTO agreement_emails (agreement_id, kind, to_email, sent_at, error) VALUES (?, ?, ?, ?, ?)
         ON DUPLICATE KEY UPDATE to_email = VALUES(to_email), sent_at = VALUES(sent_at), error = VALUES(error)"
    );
    $to = trim((string)($a['email'] ?? ''));
    if ($to === '') { $rec->execute([$agreementId, $kind, '', null, 'No email address on the employee profile.']); return [false, 'No email on profile.']; }

    if (!$force) {
        $q = $pdo->prepare("SELECT sent_at FROM agreement_emails WHERE agreement_id = ? AND kind = ?");
        $q->execute([$agreementId, $kind]);
        if ($q->fetchColumn()) return [true, 'Already sent.'];
    }

    $app = app_url();
    $name = (string)$a['full_name'];
    $tpl = (string)$a['template_name'];
    $from = defined('MAIL_FROM_NAME') ? MAIL_FROM_NAME : 'HR';
    $subjName = $name; $subjTpl = $tpl;   // plain text for the subject / file name
    $name = htmlspecialchars($name, ENT_QUOTES, 'UTF-8'); $tpl = htmlspecialchars($tpl, ENT_QUOTES, 'UTF-8'); $from = htmlspecialchars($from, ENT_QUOTES, 'UTF-8');
    $attachments = [];
    if ($kind === 'signed') {
        // The signed copy always goes INSIDE the email as a PDF. If the PDF
        // doesn't exist on the server yet (templates uploaded as PDF/HTML are
        // rendered in the browser and saved on first view), the email waits:
        // the Agreements page creates the PDF in the background and the
        // upload_pdf action then sends this email.
        $subject = "Your signed agreement — $subjTpl";
        $file = $a['signed_file'] ? upload_abs((string)$a['signed_file']) : '';
        if (!$file || !is_file($file)) {
            $rec->execute([$agreementId, $kind, $to, null, 'Waiting for the PDF to be created.']);
            $pdo->prepare("UPDATE agreement_emails SET attempts = 0 WHERE agreement_id = ? AND kind = ?")->execute([$agreementId, $kind]);   // not a send failure
            return [false, 'Waiting for the PDF.'];
        }
        if (filesize($file) > 20 * 1024 * 1024) {
            $rec->execute([$agreementId, $kind, $to, null, 'PDF is too large to email (over 20 MB).']);
            return [false, 'PDF too large to email.'];
        }
        $attachments[] = ['path' => $file, 'name' => preg_replace('/[^A-Za-z0-9_-]+/', '_', $subjTpl) . '_' . $a['employee_code'] . '.pdf'];
        $html = "<p>Dear $name,</p><p>Your <b>$tpl</b> has been signed" . ($a['reference'] ? " (reference <b>{$a['reference']}</b>)" : '') . '.</p>'
            . '<p>The signed copy is attached to this email as a PDF. Please keep it for your records.</p>'
            . "<p>Regards,<br>$from</p>";
    } else {
        $subject = "Please sign your agreement — $subjTpl";
        $html = "<p>Dear $name,</p><p>Your <b>$tpl</b> is ready for your signature.</p>"
            . ($app ? "<p>Please log in and sign it here: <a href=\"$app/my_agreements.html\">$app/my_agreements.html</a></p>" : '<p>Please log in to the HRMS and sign it on the My Agreements page.</p>')
            . "<p>Once signed, a copy will be emailed to you.</p><p>Regards,<br>$from</p>";
    }
    $err = send_mail($to, $subjName, $subject, $html, $attachments);
    $rec->execute([$agreementId, $kind, $to, $err === null ? date('Y-m-d H:i:s') : null, $err]);
    return [$err === null, $err === null ? "Emailed $to." : $err];
}

function target_houses(): array
{
    return array_intersect_key(store_group_options(), array_flip(['tmph', 'tm4u']));
}

/**
 * Which house an order counts under. ONE rule for every page:
 *   - a HOUSE TAG on the order wins over the store that took it:
 *       tm4u                          -> TM4U (no store of its own)
 *       tmph / "tm perfume house"     -> TM Perfume House
 *     (any case, as a whole tag)
 *   - otherwise the store's house (tmperfumehouse -> tmph).
 * An order counts under exactly one house. If an order carries TWO house
 * tags (a tagging mistake), the store's house applies and the Orders page
 * flags it (see order_house_tags()).
 */
function house_tag_map(): array
{
    return [
        'tmph' => 'tmph', 'tm perfume house' => 'tmph',
        'tmsg' => 'tmsg', 'tm shower gel' => 'tmsg',
    ];
}
/** Distinct houses named by the order's tags, in tag order. */
function order_house_tags(string $tags): array
{
    $map = house_tag_map(); $out = [];
    foreach (explode(',', $tags) as $t) {
        $k = strtolower(trim($t));
        if (isset($map[$k]) && !in_array($map[$k], $out, true)) $out[] = $map[$k];
    }
    return $out;
}
function order_house(string $storeKey, string $tags): string
{
    $ht = order_house_tags($tags);
    if (count($ht) === 1) return $ht[0];
    return ['tmperfumehouse' => 'tmph'][$storeKey] ?? '';
}
function order_is_tm4u(string $tags): bool
{
    return order_house_tags($tags) === ['tm4u'];
}

function ensure_target_rule_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_target_rules_ok_v2';
    if (is_file($flag)) return $done = true;
    try {
        // Shared settings. Installs created by the first version of this
        // table also have days/pct/round_to/min_target/skip_zero columns;
        // they're only read once below to carry the old rule over.
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS target_rule (
                rule_id TINYINT PRIMARY KEY,
                enabled TINYINT(1) NOT NULL DEFAULT 1,
                groups_csv VARCHAR(255) NOT NULL DEFAULT 'tmph',
                updated_by VARCHAR(100) NULL,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            )"
        );
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS target_rules (
                rule_id INT AUTO_INCREMENT PRIMARY KEY,
                sort_order INT NOT NULL DEFAULT 0,
                name VARCHAR(60) NOT NULL DEFAULT '',
                weekdays VARCHAR(20) NOT NULL,
                basis ENUM('days','weekday') NOT NULL DEFAULT 'days',
                lookback TINYINT NOT NULL DEFAULT 3,
                pct DECIMAL(5,1) NOT NULL DEFAULT 10,
                min_target DECIMAL(12,2) NOT NULL DEFAULT 0,
                skip_zero TINYINT(1) NOT NULL DEFAULT 1
            )"
        );
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

/** One rule row → the shape the page uses. */
function target_rule_row(array $r): array
{
    return [
        'name' => (string)$r['name'],
        'weekdays' => array_values(array_map('intval', array_filter(explode(',', (string)$r['weekdays']), 'strlen'))),
        'basis' => $r['basis'] === 'weekday' ? 'weekday' : 'days',
        'lookback' => (int)$r['lookback'],
        'pct' => (float)$r['pct'],
        'min_target' => (float)$r['min_target'],
        'skip_zero' => (int)$r['skip_zero'],
    ];
}

/** Settings + rules, with defaults when nothing has been saved yet. */
function target_rule_get(PDO $pdo): array
{
    $out = [
        'enabled' => 1,
        'groups' => array_keys(target_houses()),
        'rules' => [[
            'name' => 'Every day', 'weekdays' => [0, 1, 2, 3, 4, 5, 6], 'basis' => 'days',
            'lookback' => 3, 'pct' => 10.0, 'min_target' => 0.0, 'skip_zero' => 1,
        ]],
        'updated_by' => null, 'updated_at' => null,
    ];
    if (!ensure_target_rule_table($pdo)) return $out;

    $row = $pdo->query("SELECT * FROM target_rule WHERE rule_id = 1")->fetch();
    if ($row) {
        $valid = array_keys(target_houses());   // older values (Ungrouped, TM4U) drop out
        $out['enabled'] = (int)$row['enabled'];
        $out['groups'] = array_values(array_intersect(array_map('trim', explode(',', (string)$row['groups_csv'])), $valid));
        $out['updated_by'] = $row['updated_by'];
        $out['updated_at'] = $row['updated_at'];
    }

    $rules = $pdo->query("SELECT * FROM target_rules ORDER BY sort_order, rule_id")->fetchAll();
    if ($rules) {
        $out['rules'] = array_map('target_rule_row', $rules);
    } elseif ($row && isset($row['days'], $row['pct'])) {
        // Carry the single rule from the first version over as "Every day".
        $out['rules'][0]['lookback'] = max(1, (int)$row['days']);
        $out['rules'][0]['pct'] = (float)$row['pct'];
        $out['rules'][0]['min_target'] = (float)($row['min_target'] ?? 0);
        $out['rules'][0]['skip_zero'] = (int)($row['skip_zero'] ?? 1);
    }
    return $out;
}

/**
 * Orders page panels: the businesses, each on its own — TM Perfume House, TM4U,
 * TM Shower Gel. Returns '' for a key that belongs to no panel (the old "no house" rows).
 */
function sheet_panels(): array
{
    return ['tmph', 'tmsg'];
}
function sheet_panel(string $gk): string
{
    return in_array($gk, sheet_panels(), true) ? $gk : '';
}

/**
 * A person's sales role from the Department: Sales Executive, Sales Head, Sales Helper or Sales Retailer
 * ('executive' | 'head' | 'helper' | 'retailer'), '' for anyone else. Case, spaces, "-" and "_" do not matter, and a
 * plural ("Sales Executives") is the same. A general "Sales" department falls back to the Designation.
 */
function sales_role_kind(?string $department, ?string $designation = ''): string
{
    $norm = fn($s) => trim(preg_replace('/\s+/', ' ', str_replace(['_', '-'], ' ', mb_strtolower((string)$s))));
    $pick = function (string $n): string { return preg_match('/^sales (executive|head|helper|retailer)s?$/', $n, $m) ? $m[1] : ''; };
    $dep = $norm($department);
    $k = $pick($dep);
    if ($k !== '') return $k;
    if (strpos($dep, 'sales') === false) return '';
    $des = $norm($designation); $k = $pick($des); if ($k !== '') return $k;
    // a sales department with any other designation is still a seller: leader / head / manager = head, helper = helper, retail = retailer, everything else = executive
    if (preg_match('/\b(lead|leader|head|manager)\b/', $des)) return 'head';
    if (strpos($des, 'helper') !== false) return 'helper';
    if (strpos($des, 'retail') !== false) return 'retailer';
    return 'executive';
}
/** Commission for everyone who creates orders: a sales role, or anybody (not a retailer) who has an order tag on their profile. */
function sales_commission_ok(array $e): bool
{
    if (sales_sheet_role_ok($e['department_name'] ?? '', $e['designation'] ?? '')) return true;
    return trim((string)($e['sales_tag'] ?? '')) !== '' && sales_role_kind($e['department_name'] ?? '', $e['designation'] ?? '') !== 'retailer';
}

/** The Orders page Employee sheet lists Sales Executive, Sales Head and Sales Helper — not Sales Retailer. */
function sales_sheet_role_ok(?string $department, ?string $designation = ''): bool
{
    return in_array(sales_role_kind($department, $designation), ['executive', 'head', 'helper'], true);
}

/**
 * New Sales Executive daily-target ladder (₹ per day): week 1 = 10,000, week 2 = 15,000, week 3 = 20,000,
 * week 4 = 25,000, counted from the joining date. A target set by hand can go above it, never below it.
 * After week 4 the usual order applies again (set by hand -> automatic rule -> profile / monthly target).
 */
function sales_ladder_amounts(): array
{
    return [10000, 15000, 20000, 25000];
}

/** ['amount', 'week', 'day'] of the ladder for this employee on this day (Y-m-d), or null. $emp needs department_name, designation, joining_date. */
function sales_ladder_for(array $emp, string $day): ?array
{
    if (sales_role_kind($emp['department_name'] ?? '', $emp['designation'] ?? '') !== 'executive') return null;
    $j = substr((string)($emp['joining_date'] ?? ''), 0, 10);
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $j) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $day)) return null;
    $off = (int)floor((strtotime($day . ' 12:00:00') - strtotime($j . ' 12:00:00')) / 86400);
    $steps = sales_ladder_amounts();
    if ($off < 0 || $off >= 7 * count($steps)) return null;
    $w = intdiv($off, 7);
    return ['amount' => $steps[$w], 'week' => $w + 1, 'day' => $off + 1];
}

/**
 * The month's target for one person: the manual monthly target (else daily target x days), with every day of
 * the ladder lifted up to the ladder amount. Same as before for anyone with no ladder day in the month.
 */
function sales_month_target(array $emp, string $month, float $dailyBase, ?float $manualMonthly): float
{
    $dim = (int)date('t', strtotime($month . '-01'));
    if ($manualMonthly !== null) return $manualMonthly;          // a monthly target set by hand always wins (also for a new Sales Executive)
    $plain = $manualMonthly ?? ($dailyBase * $dim);
    $total = 0.0; $used = false;
    for ($i = 1; $i <= $dim; $i++) {
        $base = $manualMonthly !== null ? $manualMonthly / $dim : $dailyBase;
        $lad = sales_ladder_for($emp, sprintf('%s-%02d', $month, $i));
        if ($lad !== null) { $used = true; $base = max($base, (float)$lad['amount']); }
        $total += $base;
    }
    return $used ? round($total, 2) : $plain;
}

/** Panel targets set by hand on the Orders page, one per panel and day. */
function ensure_panel_targets_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS panel_targets (target_date DATE NOT NULL, panel VARCHAR(10) NOT NULL, amount DECIMAL(12,2) NOT NULL DEFAULT 0, updated_by VARCHAR(100) NULL, PRIMARY KEY (target_date, panel))");
    } catch (PDOException $e) { /* reads fall back to the employee sum */ }
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['panel_targets']);
}

/**
 * The Target of each panel over a date range, for the Orders page stat boxes: for every day, the amount set by hand
 * for the panel when there is one, else the sum of that panel's employee targets ($panels = team_range_targets()['panels'],
 * each entry carrying 'by_day'). Returns panel => ['target', 'auto' (employee sum), 'emp' (the sales employees' targets added up, never set by hand), 'src' => 'auto'|'manual', 'manual_days', 'days'].
 * The extra key 'all' is the target of the "All Orders & Revenue" box: set by hand for the day, else the sum of the five
 * panel targets of that day ('auto' = that sum).
 */
function panel_target_totals(PDO $pdo, array $panels, string $from, string $to): array
{
    $days = [];
    for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) $days[] = $d;
    $emp = [];      // panel => date => sum of the employees' targets
    foreach ($panels as $perPanel) foreach ($perPanel as $gk => $x) foreach (($x['by_day'] ?? []) as $d => $v) $emp[$gk][$d] = ($emp[$gk][$d] ?? 0) + (float)$v;
    $man = [];      // panel => date => amount set by hand
    ensure_panel_targets_table($pdo);
    try {
        $st = $pdo->prepare("SELECT target_date, panel, amount FROM panel_targets WHERE target_date BETWEEN ? AND ?");
        $st->execute([$from, $to]);
        foreach ($st->fetchAll() as $r) $man[(string)$r['panel']][substr((string)$r['target_date'], 0, 10)] = (float)$r['amount'];
    } catch (PDOException $e) {}
    $out = [];
    foreach (sheet_panels() as $bp) {
        $auto = 0.0; $total = 0.0; $n = 0;
        foreach ($days as $d) {
            $a = (float)($emp[$bp][$d] ?? 0);
            $auto += $a;
            if (isset($man[$bp][$d])) { $total += $man[$bp][$d]; $n++; } else $total += $a;
        }
        $out[$bp] = ['target' => round($total), 'auto' => round($auto), 'emp' => round($auto), 'src' => $n > 0 ? 'manual' : 'auto', 'manual_days' => $n, 'days' => count($days)];
    }
    $aAuto = 0.0; $aTotal = 0.0; $aN = 0; $aEmp = 0.0;
    foreach ($days as $d) {
        $sum = 0.0;
        foreach (sheet_panels() as $bp) { $sum += isset($man[$bp][$d]) ? $man[$bp][$d] : (float)($emp[$bp][$d] ?? 0); $aEmp += (float)($emp[$bp][$d] ?? 0); }
        $aAuto += $sum;
        if (isset($man['all'][$d])) { $aTotal += $man['all'][$d]; $aN++; } else $aTotal += $sum;
    }
    $out['all'] = ['target' => round($aTotal), 'auto' => round($aAuto), 'emp' => round($aEmp), 'src' => $aN > 0 ? 'manual' : 'auto', 'manual_days' => $aN, 'days' => count($days)];
    return $out;
}

/** The three ROAS goals shown in "Revenue needed for ROAS" (editable on the Orders page). */
function roas_goals_get(PDO $pdo): array
{
    $def = [2.95, 3.0, 3.1];
    $raw = setting_get($pdo, 'roas_goals', null);
    $g = $raw ? json_decode((string)$raw, true) : null;
    if (!is_array($g) || count($g) !== 3) return $def;
    $out = [];
    foreach ($g as $i => $v) {
        if (!is_numeric($v) || (float)$v < 0.1 || (float)$v > 50) return $def;
        $out[] = round((float)$v, 2);
    }
    return $out;
}

/** Ad spend typed by hand on the Orders page (for ROAS), one amount per panel and day. */
function ensure_panel_spend_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS panel_ad_spend (spend_date DATE NOT NULL, panel VARCHAR(10) NOT NULL, amount DECIMAL(12,2) NOT NULL DEFAULT 0, updated_by VARCHAR(100) NULL, PRIMARY KEY (spend_date, panel))");
    } catch (PDOException $e) { /* reads fall back to "no spend" */ }
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['panel_ad_spend']);
}

/**
 * The ad spend of each panel over a date range, for the ROAS line in the Orders page stat boxes.
 * panel => ['spend' (sum of the days typed), 'n' (days with a spend typed), 'days' (days in the range)].
 * The extra key 'all' is the "All Orders & Revenue" box: for every day the amount typed for 'all' when there is one,
 * else the sum of that day's panel spends. It adds 'auto' (that sum of the panel spends only), 'src' => 'manual'|'auto'
 * ('manual' = at least one day typed for the box itself) and 'n' = days with any spend.
 */
function panel_spend_totals(PDO $pdo, string $from, string $to): array
{
    $days = [];
    for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) $days[] = $d;
    $man = [];      // panel => date => amount typed
    ensure_panel_spend_table($pdo);
    try {
        $st = $pdo->prepare("SELECT spend_date, panel, amount FROM panel_ad_spend WHERE spend_date BETWEEN ? AND ?");
        $st->execute([$from, $to]);
        foreach ($st->fetchAll() as $r) $man[(string)$r['panel']][substr((string)$r['spend_date'], 0, 10)] = (float)$r['amount'];
    } catch (PDOException $e) {}
    $out = [];
    foreach (sheet_panels() as $bp) {
        $sum = 0.0; $n = 0;
        foreach ($days as $d) if (isset($man[$bp][$d])) { $sum += $man[$bp][$d]; $n++; }
        $out[$bp] = ['spend' => round($sum, 2), 'n' => $n, 'days' => count($days)];
    }
    $auto = 0.0; $total = 0.0; $nAll = 0; $nAny = 0;
    foreach ($days as $d) {
        $sum = 0.0; $any = false;
        foreach (sheet_panels() as $bp) if (isset($man[$bp][$d])) { $sum += $man[$bp][$d]; $any = true; }
        $auto += $sum;
        if (isset($man['all'][$d])) { $total += $man['all'][$d]; $nAll++; $nAny++; }
        else { $total += $sum; if ($any) $nAny++; }
    }
    $out['all'] = ['spend' => round($total, 2), 'auto' => round($auto, 2), 'src' => $nAll > 0 ? 'manual' : 'auto', 'n' => $nAny, 'days' => count($days)];
    return $out;
}

/** A remark written on one order (Orders page → order details); the salesman of that order gets a small notification. */
function ensure_order_remarks_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS order_remarks (id INT AUTO_INCREMENT PRIMARY KEY, store_key VARCHAR(40) NOT NULL, order_id VARCHAR(40) NOT NULL, order_name VARCHAR(60) NOT NULL DEFAULT '',
            note VARCHAR(400) NOT NULL, author VARCHAR(120) NOT NULL DEFAULT '', to_emp INT NOT NULL DEFAULT 0, to_name VARCHAR(120) NOT NULL DEFAULT '', notified TINYINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, KEY k_order (store_key, order_id))");
        try { $pdo->exec("ALTER TABLE order_remarks ADD COLUMN ct_id INT NULL"); } catch (PDOException $e) { /* already there */ }     // the matching row in ct_remarks (the pop-up / My remarks list on My Sales); NULL = none
    } catch (PDOException $e) { /* reads fall back to "no remarks" */ }
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['order_remarks']);
}
/** The employee a salesman name on an order belongs to: [employee_id, full_name] or [0, ''] when no employee has that name. */
function order_salesman_employee(PDO $pdo, string $name): array
{
    $name = trim($name);
    if ($name === '') return [0, ''];
    try {
        $st = $pdo->prepare("SELECT employee_id, full_name FROM employees WHERE LOWER(TRIM(full_name)) = LOWER(?) ORDER BY (status != 'ex') DESC, employee_id DESC LIMIT 1");
        $st->execute([$name]);
        $r = $st->fetch();
        if ($r) return [(int)$r['employee_id'], (string)$r['full_name']];
        // The name on an order is often the sales TAG of the person (the same tag the orders are attributed with): match that too.
        $st = $pdo->prepare("SELECT employee_id, full_name FROM employees WHERE sales_tag IS NOT NULL AND sales_tag <> '' AND LOWER(TRIM(sales_tag)) = LOWER(?) ORDER BY (status != 'ex') DESC, employee_id DESC LIMIT 1");
        $st->execute([$name]);
        $r = $st->fetch();
        if ($r) return [(int)$r['employee_id'], (string)$r['full_name']];
    } catch (PDOException $e) {}
    return [0, ''];
}

/** Notes typed by hand under an employee on the Orders page Employee sheet: one note per day, employee and panel. */
function ensure_panel_remarks_table(PDO $pdo): void
{
    static $done = false;
    if ($done) return; if (function_exists('schema_ok') && schema_ok($pdo, __FUNCTION__)) return;
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS panel_remarks (remark_date DATE NOT NULL, employee_id INT NOT NULL, panel VARCHAR(10) NOT NULL, note VARCHAR(500) NOT NULL, author VARCHAR(120) NULL, updated_at DATETIME NULL, PRIMARY KEY (remark_date, employee_id, panel))");
    } catch (PDOException $e) { /* reads fall back to "no notes" */ }
    $done = true;
    if (function_exists('schema_set')) schema_set($pdo, __FUNCTION__, ['panel_remarks']);
}

/** The notes of one day as "employee_id|panel" => ['note', 'by', 'at'] (empty when nothing was written). */
function panel_remarks_for_day(PDO $pdo, string $date): array
