/** Typed Community numbers of a date range as "employee_id|panel" => [day => ['yes', 'no', 'by', 'at']] (empty when nothing was typed). */
function panel_community_for_range(PDO $pdo, string $from, string $to): array
{
    $out = [];
    ensure_panel_community_table($pdo);
    try {
        $st = $pdo->prepare("SELECT cm_date, employee_id, panel, yes_n, no_n, author, updated_at FROM panel_community_manual WHERE cm_date BETWEEN ? AND ?");
        $st->execute([$from, $to]);
        foreach ($st->fetchAll() as $r) {
            $k = (int)$r['employee_id'] . '|' . $r['panel'];
            if (!isset($out[$k])) $out[$k] = [];
            $out[$k][(string)$r['cm_date']] = ['yes' => (int)$r['yes_n'], 'no' => (int)$r['no_n'], 'by' => (string)$r['author'], 'at' => (string)$r['updated_at']];
        }
    } catch (PDOException $e) {}
    foreach ($out as $k => $days) $out[$k] = (object)$days;
    return $out;
}

/** Name shown after a note: the logged-in person's employee name, else their username. */
function remark_author_name(PDO $pdo, array $auth): string
{
    $name = '';
    try {
        $st = $pdo->prepare("SELECT e.full_name FROM users u JOIN employees e ON e.employee_id = u.employee_id WHERE u.user_id = ? LIMIT 1");
        $st->execute([(int)($auth['user_id'] ?? 0)]);
        $name = trim((string)$st->fetchColumn());
    } catch (PDOException $e) {}
    return $name !== '' ? $name : (string)($auth['username'] ?? '');
}

/** employee_id => the first panel (in panel order) the person belongs to — the one panel their ladder / profile target counts on. */
function first_panels(PDO $pdo, array $ids): array
{
    $out = [];
    $ids = array_values(array_unique(array_map('intval', $ids)));
    if (!$ids || !ensure_store_groups_table($pdo)) return $out;
    $st = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN (" . implode(',', array_fill(0, count($ids), '?')) . ")");
    $st->execute($ids);
    $have = [];
    foreach ($st->fetchAll() as $r) $have[(int)$r['employee_id']][(string)$r['group_key']] = true;
    foreach ($have as $id => $gs) foreach (sheet_panels() as $bp) if (!empty($gs[$bp])) { $out[$id] = $bp; break; }
    return $out;
}

/** employee_id => [business day => true] for every day of the range on which the person punched in (same day rule as the Employee sheet). */
function attendance_present_map(PDO $pdo, string $from, string $to): array
{
    $out = [];
    try {
        $as = $pdo->prepare("SELECT employee_id, punch_date, punch_in FROM attendance WHERE punch_in IS NOT NULL AND punch_in >= ? AND punch_in < ?");
        $as->execute([date('Y-m-d', strtotime($from . ' -1 day')) . ' 00:00:00', date('Y-m-d', strtotime($to . ' +2 day')) . ' 00:00:00']);
        foreach ($as->fetchAll() as $r) {
            $pd = (string)$r['punch_date'];
            $day = substr((string)$r['punch_in'], 0, 10) === $pd ? $pd : punch_in_day($pdo, strtotime((string)$r['punch_in']));
            if ($day >= $from && $day <= $to) $out[(int)$r['employee_id']][$day] = true;
        }
    } catch (PDOException $e) {}
    return $out;
}

/**
 * Orders page "Employee sheet": the Target of each employee on each panel over
 * a date range = the sum of that panel's daily targets, resolved the way the
 * Targets page does for one day:
 *   set by hand for the day -> automatic rule (average of earlier days/weeks
 *   +% , with a minimum) -> monthly manual target / days in the month ->
 *   profile Daily Target.
 * Two panels have a target: House ('' = TM Perfume House ) and TM4U.
 * The profile Daily Target is ONE number for the person, so it counts on their
 * first panel only (House when they are in it) — never once per panel.
 * $withRule = false skips the automatic rule (no Shopify history needed), so
 * the sheet can show something instantly and fill the exact figure afterwards.
 * A new Sales Executive's first four weeks use the ladder instead (sales_ladder_for): the automatic rule is skipped
 * and a target set by hand always wins over it (higher or lower).
 * $emps rows carry department_name, designation and joining_date for that.
 * A day on which the person is Absent (no punch-in and no WFH / leave / week-off mark, on a day that has already started)
 * counts no target: that day is 0 for the person and for the panel totals. 'absent' = true when every day of the range is such a day.
 * A day marked Leave (full day, past or coming) counts no target either: 'leave' = true when every day of the range is on Leave,
 * 'off' = true when every day is Absent or on Leave. Half leave, WFH, Holiday and Week off keep the target.
 * Returns ['panels' => [employee_id => ['tmph'|'tm4u' => ['target','src','how','shared','absent','absent_days','leave','leave_days','off','by_day']]], 'rule_used' => bool, 'note' => string].
 */
/**
 * The days an automatic-target rule averages for $day, oldest first. 'weekday' basis = the same weekday in the previous N weeks.
 * 'days' basis = the previous N days THAT THE RULE COVERS: a day outside the rule's weekdays (e.g. a Sunday when the rule is
 * Mon–Sat) is skipped, so a quiet off-day does not pull the average down.
 */
function target_rule_hist_days(array $r, string $day): array
{
    $n = max(1, (int)$r['lookback']); $o = [];
    if (($r['basis'] ?? '') === 'weekday') {
        for ($i = 0; $i < $n; $i++) $o[] = date('Y-m-d', strtotime($day . ' -' . (7 * ($n - $i)) . ' day'));
        return $o;
    }
    $wds = array_map('intval', (array)($r['weekdays'] ?? []));
    $d = $day;
    for ($back = 0; $back < 60 && count($o) < $n; $back++) {
        $d = date('Y-m-d', strtotime($d . ' -1 day'));
        if ($wds && !in_array((int)date('w', strtotime($d)), $wds, true)) continue;
        array_unshift($o, $d);
    }
    return $o;
}

function team_range_targets(PDO $pdo, array $emps, string $from, string $to, bool $withRule, bool $combine = false): array
{
    // $combine = true (Commission page): TM Perfume House  are ONE row, like the Targets page — the automatic rule is
    // worked out once on their sales together and counted on the person's first one of the two; the other one keeps only a target
    // typed for it by hand (no second automatic / minimum target on top). TM4U and TM Shower Gel stay their own rows.
    // Each panel's 'by_day_src' says where every day's amount came from (manual | shared | ladder | rule | profile | away).
    $out = ['panels' => [], 'rule_used' => false, 'note' => ''];
    if (!$emps) return $out;
    $inrTxt = function (float $v): string {      // Indian digit grouping, like the Targets page
        $n = (string)(int)round($v); $neg = $n[0] === '-'; $n = ltrim($n, '-');
        if (strlen($n) > 3) { $last = substr($n, -3); $rest = substr($n, 0, -3); $rest = preg_replace('/\B(?=(\d{2})+(?!\d))/', ',', $rest); $n = $rest . ',' . $last; }
        return ($neg ? '-' : '') . '₹' . $n;
    };
    $ids = array_map('intval', array_column($emps, 'employee_id'));
    $in = implode(',', array_fill(0, count($ids), '?'));
    $panelList = sheet_panels();

    // Which panels each person has a target in: every panel they belong to (tmph, tm4u, tmsg).
    $rowsOf = [];
    $hh = [];
    if (ensure_store_groups_table($pdo)) {
        $g = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN ($in)");
        $g->execute($ids);
        foreach ($g->fetchAll() as $r) if (in_array($r['group_key'], $panelList, true)) $hh[(int)$r['employee_id']][] = $r['group_key'];
    }
    foreach ($ids as $id) $rowsOf[$id] = array_values(array_filter($panelList, fn($k) => in_array($k, $hh[$id] ?? [], true)));

    // Monthly manual targets per person, split the same way (combined vs tm4u).
    ensure_group_key_column($pdo, 'targets', ['month', 'employee_id']);
    $m1 = substr($from, 0, 7); $m2 = substr($to, 0, 7);
    $manual = [];   // "$id|$month|$gk" => amount
    try {
        $t = $pdo->prepare("SELECT month, employee_id, group_key, manual_target FROM targets WHERE month BETWEEN ? AND ? AND employee_id > 0 AND manual_target IS NOT NULL");
        $t->execute([$m1, $m2]);
        foreach ($t->fetchAll() as $r) {
            $gk = ($r['group_key'] ?? '') === 'tm4u' ? 'tm4u' : '';
            $k = (int)$r['employee_id'] . '|' . $r['month'] . '|' . $gk;
            $manual[$k] = ($manual[$k] ?? 0) + (float)$r['manual_target'];
        }
    } catch (PDOException $e) {}

    // Amounts set by hand for one day.
    ensure_group_key_column($pdo, 'daily_targets', ['target_date', 'employee_id']);
    $over = [];     // "$date|$id|$gk" => amount
    try {
        $o = $pdo->prepare("SELECT target_date, employee_id, group_key, amount FROM daily_targets WHERE target_date BETWEEN ? AND ?");
        $o->execute([$from, $to]);
        foreach ($o->fetchAll() as $r) $over[$r['target_date'] . '|' . (int)$r['employee_id'] . '|' . $r['group_key']] = (float)$r['amount'];
    } catch (PDOException $e) {}
    // The panel the profile Daily Target belongs to: the person's first panel (TM Perfume House, TM4U ...).
    $profileRow = [];
    foreach ($ids as $id) $profileRow[$id] = $rowsOf[$id][0] ?? null;
    // A panel the person is not listed in still gets the target typed for them by hand on that panel.
    foreach ($over as $ok => $_) {
        $pp = explode('|', $ok); $oid = (int)$pp[1]; $ogk = (string)($pp[2] ?? '');
        if (isset($rowsOf[$oid]) && in_array($ogk, $panelList, true) && !in_array($ogk, $rowsOf[$oid], true)) $rowsOf[$oid][] = $ogk;
    }
    foreach ($ids as $id) {
        usort($rowsOf[$id], fn($a, $b) => array_search($a, $panelList, true) <=> array_search($b, $panelList, true));
        if ($profileRow[$id] === null) $profileRow[$id] = $rowsOf[$id][0] ?? null;
    }
    // The Targets page keeps ONE combined target for TM Perfume House  (key ''): it stands in for the
    // person's first one of the two until that panel gets a target of its own here.
    $houseFirst = [];
    foreach ($ids as $id) { $houseFirst[$id] = null; foreach ($rowsOf[$id] as $k) if ($k === 'tmph') { $houseFirst[$id] = $k; break; } }
    // The Targets page's combined row (key '') covers TM Perfume House AND TM Shower Gel. A target typed there shows on the person's first
    // such panel — TM Perfume House if they are in it, otherwise TM Shower Gel. (It used to look for TM Perfume House only, so a person who sells
    // only Shower Gel never showed their hand-set target.)
    $sharedAnchor = [];
    foreach ($ids as $id) { $sharedAnchor[$id] = null; foreach ($rowsOf[$id] as $k) if ($k !== 'tm4u') { $sharedAnchor[$id] = $k; break; } if ($sharedAnchor[$id] === null && $rowsOf[$id]) $sharedAnchor[$id] = $rowsOf[$id][0]; }      // a person only in TM4U: the Targets page's combined row shows on TM4U

    // Automatic rule + the sales history it averages.
    $rule = null; $ruleHouses = [];
    $hist = [];     // "$id|$gk" => [date => collection]
    $days = [];
    for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) $days[] = $d;
    // Absent on a day that has started = no target that day.
    $present = attendance_present_map($pdo, $from, $to);
    $dayMarks = day_marks_between($pdo, $from, $to);
    $bizNow = biz_today($pdo);
    // Sales → Live "working today" switch: 'off' (holiday / not-working mode) = no target that day; 'on' = counts as working even without a punch-in.
    $wmDay = [];
    if (count($days) <= 62) foreach ($days as $d0) { $x = json_decode((string)setting_get($pdo, 'ct_wm_' . $d0, ''), true); if (is_array($x) && $x) $wmDay[$d0] = $x; }
    $absentOn = fn(int $eid, string $d) => ($wmDay[$d][$eid] ?? '') !== 'on' && $d <= $bizNow && empty($present[$eid][$d]) && !in_array($dayMarks[$d . '|' . $eid] ?? '', ['wfh', 'leave', 'half_leave', 'holiday', 'week_off'], true);
    if ($withRule) {
        $rs = target_rule_get($pdo);
        if (!empty($rs['enabled'])) {
            if (count($days) > 31) {
                $out['note'] = 'Automatic targets are not summed for more than 31 days.';
            } else {
                $rule = $rs; $ruleHouses = $rs['groups'] ?? [];
                $ruleFor = function (string $day) use ($rs) {
                    $wd = (int)date('w', strtotime($day));
                    foreach ($rs['rules'] as $r) if (in_array($wd, array_map('intval', (array)$r['weekdays']), true)) return $r;
                    return null;
                };
                $histDaysOf = fn(array $r, string $day): array => target_rule_hist_days($r, $day);
                $minDay = $from;
                foreach ($days as $d) { $r = $ruleFor($d); if ($r) foreach ($histDaysOf($r, $d) as $h) if ($h < $minDay) $minDay = $h; }
                $errors = [];
                $stores = shopify_stores(); $tokens = [];
                foreach ($stores as $key => $store) {
                    if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
                    $token = shopify_get_token($key, $store);
                    if (is_array($token)) { $errors[] = $token['error']; unset($stores[$key]); continue; }
                    $tokens[$key] = $token;
                }
                if ($stores) {
                    $tagMap = sales_tag_map($pdo); $allocMap = order_allocations($pdo);
                    $res = orders_by_store_cached($pdo, $stores, $minDay, $to) ?? shopify_fetch_all($stores, $tokens, $minDay, $to, 40, true);      // local order cache first (fast), live Shopify only when it cannot be used
                    foreach ($res as $storeKey => $st) {
                        if ($st['error']) { $errors[] = $st['error']; continue; }
                        foreach ($st['orders'] as $od) {
                            $gk = order_house($storeKey, (string)($od['tags'] ?? ''));
                            $sm = match_salesman($tagMap, (string)($od['tags'] ?? ''));
                            alloc_override($allocMap, $storeKey, $od['id'], $gk, $sm);
                            if (!$sm) continue;
                            $day = biz_day_of($pdo, strtotime((string)$od['created_at']));
                            $k = (int)$sm['id'] . '|' . $gk;
                            $hist[$k][$day] = ($hist[$k][$day] ?? 0) + (float)$od['total'];
                            if ($combine && ($gk === 'tmph')) { $kc = (int)$sm['id'] . '|*'; $hist[$kc][$day] = ($hist[$kc][$day] ?? 0) + (float)$od['total']; }
                        }
                    }
                    foreach (allocated_house_orders($pdo, $minDay, $to, $errors) as $od) {
                        if (empty($od['emp_id'])) continue;
                        $k = (int)$od['emp_id'] . '|' . (string)$od['house'];
                        $day = (string)($od['biz_date'] ?? biz_day_of($pdo, strtotime((string)$od['created_at'])));
                        $hist[$k][$day] = ($hist[$k][$day] ?? 0) + (float)$od['total'];
                        if ($combine && in_array((string)$od['house'], ['tmph'], true)) { $kc = (int)$od['emp_id'] . '|*'; $hist[$kc][$day] = ($hist[$kc][$day] ?? 0) + (float)$od['total']; }
                    }
                    $out['rule_used'] = true;
                } else {
                    $rule = null;
                    $out['note'] = 'Automatic targets could not be worked out (Shopify not reachable).';
                }
            }
        }
    }

    foreach ($emps as $e) {
        $id = (int)$e['employee_id'];
        $out['panels'][$id] = [];
        // Commission page: TM Perfume House  share one automatic target, counted on the first of the two (see $combine above).
        $anchor = $houseFirst[$id];
        $ruleOk = !empty(array_intersect($rowsOf[$id], ['tmph'], $ruleHouses));      // the person is in a ticked TM Perfume House
        foreach ($rowsOf[$id] as $gk) {
            $total = 0.0; $srcs = []; $how = ''; $shared = false; $ladHow = '';
            $byDay = []; $prevDay = null; $prevTotal = 0.0;     // each day's amount, for the panel totals on the Orders page
            $bySrc = []; $dSrc = 'none';                         // where each day's amount came from
            $absentDays = 0; $leaveDays = 0;
            foreach ($days as $d) {
                if ($prevDay !== null) { $byDay[$prevDay] = $total - $prevTotal; $bySrc[$prevDay] = $dSrc; }
                $prevDay = $d; $prevTotal = $total; $dSrc = 'none';
                $month = substr($d, 0, 7);
                $dim = (int)date('t', strtotime($d));
                $ovk = $d . '|' . $id . '|' . $gk;
                if (($wmDay[$d][$id] ?? '') === 'off') { $leaveDays++; $dSrc = 'away'; continue; }      // switched to holiday / not-working mode: no target
                // A target typed by hand for this day wins over "not punched in yet": Admin gave it, so the person is working (a Leave mark still wins, below).
                $manualHere = isset($over[$ovk]) || ($gk === $sharedAnchor[$id] && isset($over[$d . '|' . $id . '|']));
                if ($absentOn($id, $d) && !$manualHere) { $absentDays++; $dSrc = 'away'; continue; }
                if (($dayMarks[$d . '|' . $id] ?? '') === 'leave' && ($wmDay[$d][$id] ?? '') !== 'on' && !$manualHere) { $leaveDays++; $dSrc = 'away'; continue; }      // a target typed by hand wins even on a Leave-marked day      // a full-day Leave mark (even a coming day): no target
                // New Sales Executive ladder: counted on the person's first panel only (like the profile Daily Target).
                // It replaces the automatic rule. A target set by hand ALWAYS wins — higher or lower than the ladder.
                $lad = $gk === $profileRow[$id] ? sales_ladder_for($e, $d) : null;
                if ($lad !== null && count($days) === 1) {
                    $ladHow = 'New Sales Executive · week ' . $lad['week'] . ' of 4 · set by hand to change it';
                }
                if (isset($over[$ovk])) {
                    $a = (float)$over[$ovk];
                    $srcs[] = 'manual'; $dSrc = 'manual';
                    $total += $a; continue;
                }
                if ($gk === $sharedAnchor[$id] && isset($over[$d . '|' . $id . '|'])) {
                    $a = (float)$over[$d . '|' . $id . '|'];
                    $srcs[] = 'manual'; $shared = true; $dSrc = 'shared';
                    $total += $a; continue;
                }
                $comb = $combine && ($gk === 'tmph');   // Commission page: one automatic target for TM Perfume House only
                if ($rule && $lad === null && (!$comb || $gk === $anchor)) {
                    $r = null; $wd = (int)date('w', strtotime($d));
                    foreach ($rule['rules'] as $rr) if (in_array($wd, array_map('intval', (array)$rr['weekdays']), true)) { $r = $rr; break; }
                    if ($r && ($comb ? $ruleOk : in_array($gk, $ruleHouses, true))) {
                        $hk = $comb ? $id . '|*' : $id . '|' . $gk;
                        $vals = [];
                        foreach (target_rule_hist_days($r, $d) as $hd) $vals[] = $hist[$hk][$hd] ?? 0;
                        $counted = !empty($r['skip_zero']) ? array_values(array_filter($vals, fn($v) => $v > 0)) : $vals;
                        $min = (float)($r['min_target'] ?? 0);
                        if ($counted) {
                            $avg = array_sum($counted) / count($counted);
                            $exact = round($avg * (1 + (float)$r['pct'] / 100));
                            $amt = max($min, $exact);
                            $total += $amt; $srcs[] = 'rule'; $dSrc = 'rule';
                            if (count($days) === 1 && $how === '') {
                                $basis = ($r['basis'] ?? '') === 'weekday' ? ('last ' . count($counted) . ' ' . date('D', strtotime($d)) . (count($counted) === 1 ? '' : 's')) : ('last ' . count($counted) . ' day' . (count($counted) === 1 ? '' : 's'));
                                $pc = (float)$r['pct'];
                                $how = (!empty($r['name']) ? $r['name'] . ': ' : '') . 'avg of ' . $basis . ' ' . $inrTxt($avg) . ' ' . ($pc >= 0 ? '+' : '−') . ' ' . rtrim(rtrim(number_format(abs($pc), 2, '.', ''), '0'), '.') . '%' . ($amt > $exact ? ' → minimum ' . $inrTxt($min) : ' = ' . $inrTxt($amt));
                            }
                            continue;
                        }
                        if ($min > 0) { $total += $min; $srcs[] = 'rule'; $dSrc = 'rule'; if (count($days) === 1 && $how === '') $how = 'No sales in the look-back — minimum target'; continue; }
                    }
                }
                $mk = $id . '|' . $month . '|' . ($gk === 'tm4u' ? 'tm4u' : '');
                if ($gk === 'tm4u' && $gk === $sharedAnchor[$id] && !isset($manual[$mk]) && isset($manual[$id . '|' . $month . '|'])) $mk = $id . '|' . $month . '|';      // TM4U-only person: monthly target typed in the combined row
                $byHand = ($gk === 'tm4u' || $gk === $sharedAnchor[$id]) && isset($manual[$mk]);      // a monthly target set by hand wins over the ladder too
                if ($byHand && count($days) === 1 && $how === '') $how = 'Monthly target set by hand on the Targets page ÷ ' . $dim . ' days';
                $pv = $byHand ? round($manual[$mk] / $dim) : ($gk === $profileRow[$id] ? (float)($e['basic_salary'] ?? 0) : 0.0);
                if ($lad !== null && !$byHand && $pv <= $lad['amount']) { $pv = (float)$lad['amount']; $srcs[] = 'ladder'; $dSrc = 'ladder'; }
                elseif ($pv > 0) { $srcs[] = 'profile'; $dSrc = 'profile'; }
                $total += $pv;
            }
            if ($prevDay !== null) { $byDay[$prevDay] = $total - $prevTotal; $bySrc[$prevDay] = $dSrc; }
            $src = in_array('manual', $srcs, true) ? 'manual' : (in_array('ladder', $srcs, true) ? 'ladder' : (in_array('rule', $srcs, true) ? 'rule' : (in_array('profile', $srcs, true) ? 'profile' : 'none')));
            $allAbsent = $absentDays > 0 && $absentDays === count($days);
            $allLeave = $leaveDays > 0 && $leaveDays === count($days);
            $allOff = ($absentDays + $leaveDays) === count($days) && ($absentDays + $leaveDays) > 0;     // every day is Absent or on Leave
            $howTxt = $allAbsent ? 'Absent — target not counted' : ($allLeave ? 'On leave — target not counted' : ($allOff ? 'Absent / on leave — target not counted' : ($src === 'manual' ? ($shared ? 'Set on the Targets page (TM Perfume House )' : 'Set by hand for this day') : ($src === 'ladder' ? $ladHow : ($src === 'rule' ? $how : ($src === 'profile' ? ($how !== '' ? $how : 'From profile / monthly target') : ''))))));
            $out['panels'][$id][$gk] = [
                'target' => round($total), 'src' => $src,
                'absent' => $allAbsent, 'absent_days' => $absentDays, 'leave' => $allLeave, 'leave_days' => $leaveDays, 'off' => $allOff,
                'how' => $howTxt,
                'shared' => $shared,
                'by_day' => $byDay,
                'by_day_src' => $bySrc,
            ];
        }
    }
    return $out;
}

/** Username of an existing login already linked to this employee, or null. */
function existing_login_for_employee(PDO $pdo, ?int $employeeId, int $exceptUserId = 0): ?string
{
    if (!$employeeId) return null;
    $st = $pdo->prepare("SELECT username FROM users WHERE employee_id = ? AND user_id <> ? LIMIT 1");
    $st->execute([$employeeId, $exceptUserId]);
    $u = $st->fetchColumn();
    return $u === false ? null : (string)$u;
}

function ensure_addons_table(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    // Version the flag filename: bumping it forces the migration below to
    // re-run on servers where an older version already created the table
    // (and so already wrote the previous flag), which is what otherwise
    // leaves the addon_group column missing and every insert failing.
    $flag = sys_get_temp_dir() . '/hrms_addons_ok_v2';
    if (is_file($flag)) return $done = true;
    try {
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS employee_addons (
                addon_id INT AUTO_INCREMENT PRIMARY KEY,
                employee_id INT NOT NULL,
                addon_date DATE NOT NULL,
                group_key VARCHAR(10) NOT NULL DEFAULT '',
                order_name VARCHAR(60) NOT NULL DEFAULT '',
                product_name VARCHAR(190) NOT NULL,
                size_ml VARCHAR(30) NULL,
                qty INT NOT NULL DEFAULT 1,
                price DECIMAL(12,2) NOT NULL DEFAULT 0,
                addon_group CHAR(16) NULL,
                created_by VARCHAR(100) NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                KEY idx_emp_date (employee_id, addon_date),
                KEY idx_date (addon_date)
            )"
        );
        // Installs created before the single-price change won't have this
        // column, so add it rather than relying on CREATE TABLE alone.
        $cols = $pdo->query("SHOW COLUMNS FROM employee_addons")->fetchAll(PDO::FETCH_COLUMN);
        if (!in_array('addon_group', $cols, true)) {
            $pdo->exec("ALTER TABLE employee_addons ADD COLUMN addon_group CHAR(16) NULL");
        }

        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

function ensure_rating_decimal_columns(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_ratingdec_ok_v4';
    if (is_file($flag)) return $done = true;
    try {
        $cols = $pdo->query("SHOW COLUMNS FROM employee_daily_ratings")->fetchAll(PDO::FETCH_ASSOC);
        $names = [];
        foreach ($cols as $c) {
            $names[] = $c['Field'];
            if (in_array($c['Field'], ['convincing_rating', 'customer_rating'], true)
                && stripos($c['Type'], 'decimal') === false) {
                $pdo->exec("ALTER TABLE employee_daily_ratings MODIFY `{$c['Field']}` DECIMAL(4,1) NULL");
            }
        }
        // One Overall rating per employee per HOUSE per day (1-10 = half
        // stars). Kept in its own table because employee_daily_ratings is
        // keyed by employee only, and someone in two houses gets two ratings.
        $pdo->exec(
            "CREATE TABLE IF NOT EXISTS employee_daily_overall (
                rating_date DATE NOT NULL,
                employee_id INT NOT NULL,
                group_key VARCHAR(40) NOT NULL DEFAULT '',
                rating DECIMAL(4,1) NULL,
                call_rating DECIMAL(4,1) NULL,
                PRIMARY KEY (rating_date, employee_id, group_key)
            )"
        );
        // Per employee PER HOUSE per day: `rating` = Customer behaviour (was
        // shown as "Overall rating"), `call_rating` = Call rating.
        $c = $pdo->query("SHOW COLUMNS FROM employee_daily_overall LIKE 'call_rating'")->fetch();
        if (!$c) { $pdo->exec("ALTER TABLE employee_daily_overall ADD COLUMN call_rating DECIMAL(4,1) NULL"); $pdo->exec("ALTER TABLE employee_daily_overall MODIFY rating DECIMAL(4,1) NULL"); }
        @file_put_contents($flag, '1');
        return $done = true;
    } catch (PDOException $e) {
        return $done = false;
    }
}

function ensure_targets_commission_columns(PDO $pdo): bool
{
    static $done = null;
    if ($done !== null) return $done;
    $flag = sys_get_temp_dir() . '/hrms_targetscol_ok';
    if (is_file($flag)) return $done = true;
    try {
        $cols = $pdo->query("SHOW COLUMNS FROM targets")->fetchAll(PDO::FETCH_COLUMN);
