        $out = [];
        foreach ($tables as $t) {
            try {
                $cols = $pdo->query("SHOW COLUMNS FROM `$t`")->fetchAll(PDO::FETCH_COLUMN);
                $keys = $pdo->query(
                    "SELECT INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) cols
                     FROM information_schema.STATISTICS
                     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = " . $pdo->quote($t) . " AND NON_UNIQUE = 0
                     GROUP BY INDEX_NAME"
                )->fetchAll();
                $out[$t] = [
                    'has_group_key_column' => in_array('group_key', $cols, true),
                    'unique_keys' => array_map(fn($k) => $k['INDEX_NAME'] . ' (' . $k['cols'] . ')', $keys),
                ];
            } catch (PDOException $e) {
                $out[$t] = ['error' => $e->getMessage()];
            }
        }
        json_response($out);
        break;
    }

    case 'ping': {
        // No auth needed on purpose — lets you confirm which api.php is
        // actually deployed just by opening this URL in a browser.
        json_response([
            'ok' => true,
            'build' => HRMS_BUILD,
            'modules' => array_keys(all_permissions()),
            'has_agreements_file_action' => true,
            'php_version' => PHP_VERSION,
            'server_time' => date('Y-m-d H:i:s'),
        ]);
        break;
    }

    // ============== AUTH ==============
    case 'login': {
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $username = trim($input['username'] ?? '');
        $password = $input['password'] ?? '';
        if ($username === '' || $password === '') {
            json_response(['error' => 'Username and password are required.'], 422);
        }
        $stmt = $pdo->prepare("SELECT user_id, employee_id, username, password_hash, role FROM users WHERE username = ? LIMIT 1");
        $stmt->execute([$username]);
        $user = $stmt->fetch();
        $stored = $user ? (string)$user['password_hash'] : '';
        // A password typed straight into the database (phpMyAdmin: UPDATE users SET password_hash = 'MyPass' ...) is plain text, not an
        // encrypted hash. It is accepted once — when it matches exactly — and encrypted (bcrypt) on the spot, so it never stays readable.
        $isHash = (bool)preg_match('/^\$(2[aby]|argon2i|argon2id)\$/', $stored);
        $ok = $user && ($isHash ? password_verify($password, $stored) : ($stored !== '' && hash_equals($stored, (string)$password)));
        if (!$ok) {
            json_response(['error' => 'Invalid username or password.'], 401);
        }
        if (!$isHash) {
            try { $pdo->prepare("UPDATE users SET password_hash = ? WHERE user_id = ?")->execute([password_hash((string)$password, PASSWORD_BCRYPT), $user['user_id']]); } catch (PDOException $e) {}
        }
        $token = generate_token([
            'user_id' => $user['user_id'], 'employee_id' => $user['employee_id'],
            'username' => $user['username'], 'role' => $user['role'],
        ]);
        json_response(['token' => $token, 'user' => [
            'user_id' => $user['user_id'], 'employee_id' => $user['employee_id'],
            'username' => $user['username'], 'role' => $user['role'],
        ]]);
        break;
    }

    case 'me': {
        $auth = require_auth();
        json_response(['user' => $auth]);
        break;
    }

    case 'setup_admin': {
        $existing = $pdo->prepare("SELECT user_id FROM users WHERE username = 'admin'");
        $existing->execute();
        if ($existing->fetch()) {
            json_response(['error' => "User 'admin' already exists. Nothing to do."], 409);
        }
        $hash = password_hash('Admin@123', PASSWORD_BCRYPT);
        $stmt = $pdo->prepare("INSERT INTO users (username, password_hash, role) VALUES ('admin', ?, 'Admin')");
        $stmt->execute([$hash]);
        json_response(['message' => 'Admin created. Username: admin / Password: Admin@123 — change it after first login.']);
        break;
    }

