        json_response(['users' => $rows]);
        break;
    }

    case 'users.create': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $username = trim($input['username'] ?? '');
        $password = $input['password'] ?? '';
        $role = $input['role'] ?? '';
        $employeeId = $input['employee_id'] ?: null;

        if ($username === '' || $password === '') {
            json_response(['error' => 'Username and password are required.'], 422);
        }
        if (strlen($password) < 6) {
            json_response(['error' => 'Password must be at least 6 characters.'], 422);
        }
        $validRole = in_array($role, ['Admin', 'HR', 'Employee'], true);
        if (!$validRole) {
            try {
                $rc = $pdo->prepare("SELECT role_id FROM roles WHERE role_name = ?");
                $rc->execute([$role]);
                $validRole = (bool)$rc->fetchColumn();
            } catch (PDOException $e) { $validRole = false; }
        }
        if (!$validRole) json_response(['error' => 'Unknown role.'], 422);
        if ($role === 'Employee' && !$employeeId) {
            json_response(['error' => 'An Employee login must be linked to an employee.'], 422);
        }

        if ($taken = existing_login_for_employee($pdo, $employeeId ? (int)$employeeId : null)) {
            json_response(['error' => "This employee already has a login (username \"$taken\")."], 409);
        }
        $dupe = $pdo->prepare("SELECT 1 FROM users WHERE username = ? LIMIT 1");
        $dupe->execute([$username]);
        if ($dupe->fetchColumn()) json_response(['error' => 'That username is already taken.'], 409);

        $hash = password_hash($password, PASSWORD_BCRYPT);
        try {
            $stmt = $pdo->prepare("INSERT INTO users (username, password_hash, role, employee_id) VALUES (?, ?, ?, ?)");
            $stmt->execute([$username, $hash, $role, $employeeId]);
            json_response(['message' => 'User created.', 'user_id' => $pdo->lastInsertId()], 201);
        } catch (PDOException $e) {
            // Username clashes are caught above, so anything here is a
            // genuine database problem — say so instead of blaming the name.
            json_response(['error' => 'Could not create the login: ' . $e->getMessage()], 500);
        }
        break;
    }

    case 'roles.list': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        $rows = [];
        try {
            ensure_roles_known_column($pdo);
            $rows = $pdo->query("SELECT role_id, role_name, is_system, permissions FROM roles ORDER BY is_system DESC, role_name")->fetchAll();
            // Effective ticks (HR also gets modules added after its last save).
            foreach ($rows as &$r) $r['permissions'] = role_permissions($pdo, (string)$r['role_name']);
            unset($r);
        } catch (PDOException $e) {
            json_response(['error' => 'Roles table missing — run the roles SQL first.'], 500);
        }
        // Count users per role
        $counts = [];
        foreach ($pdo->query("SELECT role, COUNT(*) c FROM users GROUP BY role")->fetchAll() as $c) $counts[$c['role']] = (int)$c['c'];
        foreach ($rows as &$r) $r['user_count'] = $counts[$r['role_name']] ?? 0;
        unset($r);
        json_response(['roles' => $rows, 'all_permissions' => all_permissions()]);
        break;
    }

    case 'roles.save': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $roleId = (int)($input['role_id'] ?? 0);
        $name = trim($input['role_name'] ?? '');
        $perms = $input['permissions'] ?? [];
        if ($name === '') json_response(['error' => 'Role name is required.'], 422);
        if (in_array($name, ['Admin', 'Employee'], true) && !$roleId) json_response(['error' => 'That name is reserved.'], 422);
        if (!is_array($perms)) $perms = [];
        $valid = array_keys(all_permissions());
        $perms = array_values(array_intersect($perms, $valid));

        if ($roleId) {
            $cur = $pdo->prepare("SELECT role_name, is_system FROM roles WHERE role_id = ?");
            $cur->execute([$roleId]);
            $row = $cur->fetch();
            if (!$row) json_response(['error' => 'Role not found.'], 404);
            if ((int)$row['is_system'] === 1 && $row['role_name'] !== $name) {
                json_response(['error' => 'System role names cannot be changed.'], 409);
            }
            ensure_roles_known_column($pdo);
            $pdo->prepare("UPDATE roles SET role_name = ?, permissions = ?, known_modules = ? WHERE role_id = ?")
                ->execute([$name, json_encode($perms), json_encode($valid), $roleId]);
            // Keep users pointing at the (possibly renamed) role
            if ($row['role_name'] !== $name) {
                $pdo->prepare("UPDATE users SET role = ? WHERE role = ?")->execute([$name, $row['role_name']]);
            }
        } else {
            $dup = $pdo->prepare("SELECT role_id FROM roles WHERE role_name = ?");
            $dup->execute([$name]);
            if ($dup->fetchColumn()) json_response(['error' => 'A role with that name already exists.'], 409);
            ensure_roles_known_column($pdo);
            $pdo->prepare("INSERT INTO roles (role_name, is_system, permissions, known_modules) VALUES (?, 0, ?, ?)")
                ->execute([$name, json_encode($perms), json_encode($valid)]);
        }
        json_response(['message' => 'Role saved.']);
        break;
    }

    case 'roles.delete': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $roleId = (int)($input['role_id'] ?? 0);
        if (!$roleId) json_response(['error' => 'role_id required.'], 422);
        $cur = $pdo->prepare("SELECT role_name, is_system FROM roles WHERE role_id = ?");
        $cur->execute([$roleId]);
        $row = $cur->fetch();
        if (!$row) json_response(['error' => 'Role not found.'], 404);
        if ((int)$row['is_system'] === 1 && $row['role_name'] !== 'HR') json_response(['error' => 'Admin and Employee roles cannot be deleted.'], 409);
        $used = $pdo->prepare("SELECT COUNT(*) FROM users WHERE role = ?");
        $used->execute([$row['role_name']]);
        if ((int)$used->fetchColumn() > 0) json_response(['error' => 'Cannot delete — users still have this role. Change their role first.'], 409);
        $pdo->prepare("DELETE FROM roles WHERE role_id = ?")->execute([$roleId]);
        json_response(['message' => 'Role deleted.']);
        break;
    }

    case 'users.update': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $userId = (int)($input['user_id'] ?? 0);
        $username = trim($input['username'] ?? '');
        $role = $input['role'] ?? '';
        $employeeId = !empty($input['employee_id']) ? (int)$input['employee_id'] : null;

        if (!$userId || $username === '') json_response(['error' => 'user_id and username are required.'], 422);
        $validRole = in_array($role, ['Admin', 'HR', 'Employee'], true);
        if (!$validRole) {
            try {
                $rc = $pdo->prepare("SELECT role_id FROM roles WHERE role_name = ?");
                $rc->execute([$role]);
                $validRole = (bool)$rc->fetchColumn();
            } catch (PDOException $e) { $validRole = false; }
        }
        if (!$validRole) json_response(['error' => 'Unknown role.'], 422);
        if ($role === 'Employee' && !$employeeId) json_response(['error' => 'An Employee login must be linked to an employee.'], 422);

        $cur = $pdo->prepare("SELECT role FROM users WHERE user_id = ?");
        $cur->execute([$userId]);
        $curRole = $cur->fetchColumn();
        if (!$curRole) json_response(['error' => 'User not found.'], 404);
        if ($taken = existing_login_for_employee($pdo, $employeeId, $userId)) {
            json_response(['error' => "That employee already has a login (username \"$taken\")."], 409);
        }

        // Never let the last Admin be demoted.
        if ($curRole === 'Admin' && $role !== 'Admin') {
            $admins = (int)$pdo->query("SELECT COUNT(*) FROM users WHERE role = 'Admin'")->fetchColumn();
            if ($admins <= 1) json_response(['error' => 'Cannot change role — this is the only Admin login.'], 409);
        }

        $dup = $pdo->prepare("SELECT user_id FROM users WHERE username = ? AND user_id != ?");
        $dup->execute([$username, $userId]);
        if ($dup->fetchColumn()) json_response(['error' => 'That username is already taken.'], 409);

        // Optional password change — only when a new one is actually sent,
        // so saving a user without touching the password field leaves their
        // existing login working.
        $newPassword = (string)($input['password'] ?? '');
        if ($newPassword !== '') {
            if (mb_strlen($newPassword) < 6) json_response(['error' => 'Password must be at least 6 characters.'], 422);
            $hash = password_hash($newPassword, PASSWORD_BCRYPT);
            $pdo->prepare("UPDATE users SET username = ?, role = ?, employee_id = ?, password_hash = ? WHERE user_id = ?")
                ->execute([$username, $role, $employeeId, $hash, $userId]);
            json_response(['message' => 'User updated and password changed. They must use the new password next time.']);
        }

        $pdo->prepare("UPDATE users SET username = ?, role = ?, employee_id = ? WHERE user_id = ?")
            ->execute([$username, $role, $employeeId, $userId]);
        json_response(['message' => 'User updated. Changes apply on their next login.']);
        break;
    }

    case 'users.delete': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
