    // ============== EMPLOYEES ==============
    case 'employees.list': {
        require_auth();
        $search = trim($_GET['search'] ?? '');
        $departmentId = $_GET['department_id'] ?? '';
        $status = $_GET['status'] ?? '';
        $storeGroup = $_GET['store_group'] ?? '';
        ensure_gender_column($pdo);
        // Computed ONCE for everybody (grouped), not once per employee: one pass over the documents instead of
        // employees x document types sub-queries. Same numbers as before.
        $sigDocExpr = "(sg.employee_id IS NOT NULL)";
        $sigExpr = $HAS_SIG_COL ? "((e.signature_file IS NOT NULL AND e.signature_file <> '') OR $sigDocExpr)" : $sigDocExpr;
        $sql = "SELECT e.*, d.department_name,
                    ($sigExpr) AS has_signature,
                    GREATEST(0, (SELECT COUNT(*) FROM document_types) - COALESCE(pc.c, 0)) AS pending_count
                FROM employees e
                LEFT JOIN departments d ON d.department_id = e.department_id
                LEFT JOIN (SELECT ed.employee_id, COUNT(DISTINCT ed.document_type_id) AS c
                           FROM employee_documents ed JOIN document_types dt ON dt.document_type_id = ed.document_type_id
                           GROUP BY ed.employee_id) pc ON pc.employee_id = e.employee_id
                LEFT JOIN (SELECT DISTINCT ed2.employee_id
                           FROM employee_documents ed2 JOIN document_types dt2 ON dt2.document_type_id = ed2.document_type_id
                           WHERE LOWER(dt2.document_name) LIKE '%signature%' AND ed2.document_file IS NOT NULL AND ed2.document_file <> '') sg
                       ON sg.employee_id = e.employee_id
                WHERE 1=1";
        $params = [];
        if ($search !== '') {
            $sql .= " AND (e.full_name LIKE ? OR e.employee_code LIKE ? OR e.email LIKE ? OR e.mobile LIKE ? OR e.designation LIKE ?)";
            $like = "%$search%";
            array_push($params, $like, $like, $like, $like, $like);
        }
        if ($departmentId !== '') {
            $sql .= " AND e.department_id = ?";
            $params[] = $departmentId;
        }
        if ($status !== '') {
            $sql .= " AND e.status = ?";
            $params[] = $status;
        } else {
            // Ex-employees are hidden everywhere by default — only shown when
            // explicitly requested with ?status=ex (the Ex-Employees page).
            $sql .= " AND e.status != 'ex'";
        }
        [$sgSql, $sgParams] = store_group_filter_sql($pdo, $storeGroup);
        $sql .= $sgSql;
        array_push($params, ...$sgParams);
        $sql .= " ORDER BY e.employee_code ASC"; // EMP0001, EMP0002, ... number-wise
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll();

        // Attach each employee's store group keys for the picker/badges.
        if (ensure_store_groups_table($pdo) && $rows) {
            $ids = array_column($rows, 'employee_id');
            $in = implode(',', array_fill(0, count($ids), '?'));
            $gStmt = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN ($in)");
            $gStmt->execute($ids);
            $byEmp = [];
            foreach ($gStmt->fetchAll() as $g) $byEmp[(int)$g['employee_id']][] = $g['group_key'];
            foreach ($rows as &$r) $r['store_groups'] = $byEmp[(int)$r['employee_id']] ?? [];
            unset($r);
        }

        json_response(['employees' => $rows, 'count' => count($rows)]);
        break;
    }

    case 'employees.get': {
        require_auth();
        $id = $_GET['id'] ?? null;
        if (!$id) json_response(['error' => 'id is required.'], 422);
        $stmt = $pdo->prepare(
            "SELECT e.*, d.department_name, m.full_name AS manager_name
             FROM employees e
             LEFT JOIN departments d ON d.department_id = e.department_id
             LEFT JOIN employees m ON m.employee_id = e.reporting_manager_id
             WHERE e.employee_id = ?"
        );
        $stmt->execute([$id]);
        $employee = $stmt->fetch();
        if (!$employee) json_response(['error' => 'Employee not found.'], 404);

        $pendingStmt = $pdo->prepare(
            "SELECT dt.document_type_id, dt.document_name
             FROM document_types dt
             WHERE dt.is_required = 1
               AND NOT EXISTS (
                   SELECT 1 FROM employee_documents ed
                   WHERE ed.employee_id = ? AND ed.document_type_id = dt.document_type_id
               )
             ORDER BY dt.document_name"
        );
        $pendingStmt->execute([$id]);
        $employee['pending_documents'] = $pendingStmt->fetchAll();

        $groupsStmt = $pdo->prepare(
            "SELECT wg.group_id, wg.group_name
             FROM employee_whatsapp_groups ewg
             JOIN whatsapp_groups wg ON wg.group_id = ewg.group_id
             WHERE ewg.employee_id = ?
             ORDER BY wg.group_name"
        );
        $groupsStmt->execute([$id]);
        $employee['whatsapp_groups'] = $groupsStmt->fetchAll();

        $filesStmt = $pdo->prepare(
            "SELECT ef.file_id, ef.file_name, ef.file_url
             FROM employee_excel_files eef
             JOIN excel_files ef ON ef.file_id = eef.file_id
             WHERE eef.employee_id = ?
             ORDER BY ef.file_name"
        );
        $filesStmt->execute([$id]);
        $employee['excel_files'] = $filesStmt->fetchAll();

        $employee['store_groups'] = employee_store_groups($pdo, (int)$id);

        json_response(['employee' => $employee]);
        break;
    }

    case 'employees.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);

        // Two shapes accepted: plain JSON (no photo change), or multipart/form-data
        // when a new photo file is attached — same dual pattern used elsewhere
        // (employee_documents.update, hero slides) for optional file uploads.
        $hasPhoto = isset($_FILES['photo']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK;
        $input = $hasPhoto ? $_POST : json_input();

        $id = $input['employee_id'] ?? null;

        $fullName       = trim($input['full_name'] ?? '');
        $mobile         = trim($input['mobile'] ?? '');
        $email          = trim($input['email'] ?? '');
        $address        = trim($input['address'] ?? '');
        $dob            = $input['date_of_birth'] ?: null;
        $joiningDate    = $input['joining_date'] ?? '';
        $departmentId   = $input['department_id'] ?: null;
        $managerId      = $input['reporting_manager_id'] ?: null;
        $basicSalary    = $input['basic_salary'] ?? 0;
        $monthlySalary  = $input['monthly_salary'] ?? 0;
        $employmentType = trim($input['employment_type'] ?? '');
        $designation    = trim($input['designation'] ?? '');
        $emName         = trim($input['emergency_contact_name'] ?? '');
        $emMobile       = trim($input['emergency_contact_mobile'] ?? '');
        $emRelation     = trim($input['emergency_contact_relation'] ?? '');
        $salesTag       = trim($input['sales_tag'] ?? '');
        $whatsappGroupIds = $input['whatsapp_group_ids'] ?? null;
        $excelFileIds     = $input['excel_file_ids'] ?? null;
        $storeGroupKeys   = $input['store_group_keys'] ?? null;
        $hasGender        = array_key_exists('gender', $input) && ensure_gender_column($pdo);
        $gender           = $hasGender ? clean_gender($input['gender']) : null;

        if ($fullName === '' || $joiningDate === '') {
            json_response(['error' => 'Full name and joining date are required.'], 422);
        }
        if ($id && $managerId && (int)$managerId === (int)$id) {
            json_response(['error' => 'An employee cannot be their own reporting manager.'], 422);
        }

        $newPhotoPath = null;
        if ($hasPhoto) {
            $file = $_FILES['photo'];
            $allowedExt = ['jpg', 'jpeg', 'png', 'webp'];
            $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
            if (!in_array($ext, $allowedExt, true)) {
                json_response(['error' => 'Only JPG, PNG, and WEBP photos are allowed.'], 422);
            }
            if ($file['size'] > 3 * 1024 * 1024) {
                json_response(['error' => 'Photo must be under 3MB.'], 422);
            }

            $uploadDir = __DIR__ . '/uploads/';
            if (!is_dir($uploadDir)) {
                mkdir($uploadDir, 0755, true);
            }

            $safeName = 'photo_' . uniqid() . '.' . $ext;
            $destPath = $uploadDir . $safeName;

            if (!move_uploaded_file($file['tmp_name'], $destPath)) {
                json_response(['error' => 'Failed to save the photo.'], 500);
            }

            $newPhotoPath = 'uploads/' . $safeName;
        }

        try {
            if ($id) {
                if ($newPhotoPath) {
                    $oldStmt = $pdo->prepare("SELECT photo FROM employees WHERE employee_id = ?");
                    $oldStmt->execute([$id]);
                    $oldPhoto = $oldStmt->fetchColumn();

                    $stmt = $pdo->prepare(
                        "UPDATE employees SET
                            full_name = ?, mobile = ?, email = ?, address = ?, date_of_birth = ?,
                            joining_date = ?, department_id = ?, reporting_manager_id = ?,
                            basic_salary = ?, monthly_salary = ?, employment_type = ?, designation = ?, emergency_contact_name = ?,
                            emergency_contact_mobile = ?, emergency_contact_relation = ?, sales_tag = ?, photo = ?
                         WHERE employee_id = ?"
                    );
                    $stmt->execute([
                        $fullName, $mobile, $email, $address, $dob,
                        $joiningDate, $departmentId, $managerId,
                        $basicSalary, $monthlySalary, $employmentType, $designation, $emName,
                        $emMobile, $emRelation, $salesTag ?: null, $newPhotoPath, $id,
                    ]);

                    if ($oldPhoto && file_exists(__DIR__ . '/' . $oldPhoto)) {
                        @unlink(__DIR__ . '/' . $oldPhoto);
                    }
                } else {
                    // No new photo — leave the photo column untouched entirely.
                    $stmt = $pdo->prepare(
                        "UPDATE employees SET
                            full_name = ?, mobile = ?, email = ?, address = ?, date_of_birth = ?,
                            joining_date = ?, department_id = ?, reporting_manager_id = ?,
                            basic_salary = ?, monthly_salary = ?, employment_type = ?, designation = ?, emergency_contact_name = ?,
                            emergency_contact_mobile = ?, emergency_contact_relation = ?, sales_tag = ?
                         WHERE employee_id = ?"
                    );
                    $stmt->execute([
                        $fullName, $mobile, $email, $address, $dob,
                        $joiningDate, $departmentId, $managerId,
                        $basicSalary, $monthlySalary, $employmentType, $designation, $emName,
                        $emMobile, $emRelation, $salesTag ?: null, $id,
                    ]);
                }
                sync_employee_groups($pdo, (int)$id, $whatsappGroupIds);
                sync_employee_excel_files($pdo, (int)$id, $excelFileIds);
                sync_employee_store_groups($pdo, (int)$id, $storeGroupKeys);
                if ($hasGender) $pdo->prepare("UPDATE employees SET gender = ? WHERE employee_id = ?")->execute([$gender, (int)$id]);
                json_response(['message' => 'Employee updated.', 'employee_id' => (int)$id]);
            } else {
                $code = generate_employee_code($pdo);
                $status = 'approved'; // employees no longer need approval — only documents do
                $stmt = $pdo->prepare(
                    "INSERT INTO employees
                        (employee_code, full_name, mobile, email, address, date_of_birth,
                         joining_date, department_id, reporting_manager_id, basic_salary, monthly_salary,
                         employment_type, designation, emergency_contact_name, emergency_contact_mobile,
                         emergency_contact_relation, sales_tag, photo, status, created_by)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
                );
                $stmt->execute([
                    $code, $fullName, $mobile, $email, $address, $dob,
                    $joiningDate, $departmentId, $managerId, $basicSalary, $monthlySalary,
                    $employmentType, $designation, $emName, $emMobile, $emRelation, $salesTag ?: null, $newPhotoPath, $status, $auth['username'],
                ]);
                $newEmployeeId = (int)$pdo->lastInsertId();
                sync_employee_groups($pdo, $newEmployeeId, $whatsappGroupIds);
                sync_employee_excel_files($pdo, $newEmployeeId, $excelFileIds);
                sync_employee_store_groups($pdo, $newEmployeeId, $storeGroupKeys);
                if ($hasGender) $pdo->prepare("UPDATE employees SET gender = ? WHERE employee_id = ?")->execute([$gender, $newEmployeeId]);
                json_response([
                    'message' => $status === 'pending' ? 'Employee added — pending Admin approval.' : 'Employee added.',
                    'employee_id' => $newEmployeeId,
                    'employee_code' => $code,
                    'status' => $status,
                ], 201);
            }
        } catch (PDOException $e) {
            if ($e->getCode() === '23000') {
                json_response(['error' => 'That email is already used by another employee.'], 409);
            }
            json_response(['error' => 'Could not save employee.'], 500);
        }
        break;
    }

    case 'employees.set_gender': {
        // Employees list: change one person's gender right in the list (M / F / '' = not set).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = (int)($input['employee_id'] ?? 0);
        if (!$id) json_response(['error' => 'employee_id is required.'], 422);
        if (!ensure_gender_column($pdo)) json_response(['error' => 'Could not add the gender column.'], 500);
        $g = clean_gender($input['gender'] ?? '');
        $pdo->prepare("UPDATE employees SET gender = ? WHERE employee_id = ?")->execute([$g, $id]);
        json_response(['message' => 'Saved.', 'employee_id' => $id, 'gender' => $g]);
        break;
    }

    case 'employees.bulk_add': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $list = $input['employees'] ?? [];
        if (!is_array($list) || count($list) === 0) json_response(['error' => 'No employees to add.'], 422);
        if (count($list) > 200) json_response(['error' => 'Maximum 200 employees per import.'], 422);

        // Department name -> id map (case-insensitive)
        $deptMap = [];
        foreach ($pdo->query("SELECT department_id, department_name FROM departments")->fetchAll() as $d) {
            $deptMap[mb_strtolower(trim($d['department_name']))] = (int)$d['department_id'];
        }

        $status = 'approved'; // employees no longer need approval — only documents do
        $created = 0;
        $errors = [];

        // Manager lookup by exact name or EMP code (case-insensitive),
        // including employees created earlier in this same import.
        $managerMap = [];
        foreach ($pdo->query("SELECT employee_id, full_name, employee_code FROM employees WHERE status != 'ex'")->fetchAll() as $m) {
            $managerMap[mb_strtolower(trim($m['full_name']))] = (int)$m['employee_id'];
            $managerMap[mb_strtolower(trim($m['employee_code']))] = (int)$m['employee_id'];
        }

        $parseDate = function ($v, $fallback = null) {
            $v = trim((string)$v);
            if ($v === '') return $fallback;
            if (preg_match('/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/', $v, $m)) {
                return $m[3] . '-' . str_pad($m[2], 2, '0', STR_PAD_LEFT) . '-' . str_pad($m[1], 2, '0', STR_PAD_LEFT);
            }
            if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $v)) return $v;
            return false; // not understood
        };

        $ins = $pdo->prepare(
            "INSERT INTO employees
                (employee_code, full_name, mobile, email, address, date_of_birth, joining_date,
                 department_id, reporting_manager_id, basic_salary, employment_type, designation,
                 emergency_contact_name, emergency_contact_mobile, emergency_contact_relation,
                 sales_tag, status, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        );

        foreach ($list as $i => $row) {
            $line = $i + 1;
            $name = trim($row['full_name'] ?? '');
            if ($name === '') { $errors[] = "Row $line: name is empty — skipped."; continue; }

            $deptId = null;
            $deptName = trim($row['department'] ?? '');
            if ($deptName !== '') {
                $key = mb_strtolower($deptName);
                if (isset($deptMap[$key])) {
                    $deptId = $deptMap[$key];
                } else {
                    $errors[] = "Row $line ($name): department \"$deptName\" not found — added without department.";
                }
            }

            $jd = $parseDate($row['joining_date'] ?? '', date('Y-m-d'));
            if ($jd === false) {
                $errors[] = "Row $line ($name): joining date not understood — used today.";
                $jd = date('Y-m-d');
            }
            $dob = $parseDate($row['date_of_birth'] ?? '', null);
            if ($dob === false) {
                $errors[] = "Row $line ($name): date of birth not understood — left blank.";
                $dob = null;
            }

            $managerId = null;
            $mgrRef = trim($row['reporting_manager'] ?? '');
            if ($mgrRef !== '') {
                $key = mb_strtolower($mgrRef);
                if (isset($managerMap[$key])) {
                    $managerId = $managerMap[$key];
                } else {
                    $errors[] = "Row $line ($name): manager \"$mgrRef\" not found — left blank.";
                }
            }

            try {
                $newCode = generate_employee_code($pdo);
                $ins->execute([
                    $newCode,
                    $name,
                    trim($row['mobile'] ?? ''),
                    trim($row['email'] ?? ''),
                    trim($row['address'] ?? ''),
                    $dob,
                    $jd,
                    $deptId,
                    $managerId,
                    (float)($row['basic_salary'] ?? 0),
                    trim($row['employment_type'] ?? ''),
                    trim($row['designation'] ?? ''),
                    trim($row['emergency_contact_name'] ?? ''),
                    trim($row['emergency_contact_mobile'] ?? ''),
                    trim($row['emergency_contact_relation'] ?? ''),
                    trim($row['sales_tag'] ?? '') ?: null,
                    $status,
                    $auth['username'],
                ]);
                $newId = (int)$pdo->lastInsertId();
                $managerMap[mb_strtolower($name)] = $newId;
                $managerMap[mb_strtolower($newCode)] = $newId;
                $created++;
            } catch (PDOException $e) {
                if ($e->getCode() === '23000') {
                    $errors[] = "Row $line ($name): email already used by another employee — skipped.";
                } else {
                    $errors[] = "Row $line ($name): could not save — skipped.";
                }
            }
        }

        json_response([
            'message' => "$created employee" . ($created === 1 ? '' : 's') . " added" . ($status === 'pending' ? ' (pending Admin approval)' : '') . ".",
            'created' => $created,
            'errors' => $errors,
        ]);
        break;
    }

    case 'employees.delete': {
        // Soft delete — the employee is moved to Ex-Employees, nothing is
        // removed from the database. Rejoin/permanent-delete happen from the
        // Ex-Employees page (employees.rejoin / employees.destroy).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['employee_id'] ?? null;
        if (!$id) json_response(['error' => 'employee_id is required.'], 422);
        $stmt = $pdo->prepare("UPDATE employees SET status = 'ex', left_at = NOW() WHERE employee_id = ?");
        $stmt->execute([$id]);
        json_response(['message' => 'Employee moved to Ex-Employees.']);
        break;
    }

    case 'employees.rejoin': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['employee_id'] ?? null;
        if (!$id) json_response(['error' => 'employee_id is required.'], 422);
        $stmt = $pdo->prepare("UPDATE employees SET status = 'approved', left_at = NULL WHERE employee_id = ? AND status = 'ex'");
        $stmt->execute([$id]);
        if ($stmt->rowCount() === 0) {
            json_response(['error' => 'Employee not found in Ex-Employees.'], 404);
        }
        json_response(['message' => 'Employee rejoined.']);
        break;
    }

    case 'employees.destroy': {
        // Permanent delete — removes the employee, their documents and files.
        // Only reachable from the Ex-Employees page.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['employee_id'] ?? null;
        if (!$id) json_response(['error' => 'employee_id is required.'], 422);

        $stmt = $pdo->prepare("SELECT * FROM employees WHERE employee_id = ? AND status = 'ex'");
        $stmt->execute([$id]);
        $emp = $stmt->fetch();
        if (!$emp) json_response(['error' => 'Employee not found in Ex-Employees.'], 404);

        try {
            // Clear references to this employee first:
            // - anyone who has them as reporting manager loses that link
            // - any login account tied to them is unlinked
            $pdo->prepare("UPDATE employees SET reporting_manager_id = NULL WHERE reporting_manager_id = ?")->execute([$id]);
            $pdo->prepare("UPDATE users SET employee_id = NULL WHERE employee_id = ?")->execute([$id]);

            // Clean up documents (files on disk) and photo.
            $docStmt = $pdo->prepare("SELECT document_file FROM employee_documents WHERE employee_id = ?");
            $docStmt->execute([$id]);
            foreach ($docStmt->fetchAll() as $doc) {
                if ($doc['document_file'] && file_exists(__DIR__ . '/' . $doc['document_file'])) {
                    @unlink(__DIR__ . '/' . $doc['document_file']);
                }
            }
            $pdo->prepare("DELETE FROM employee_documents WHERE employee_id = ?")->execute([$id]);

            if ($emp['photo'] && file_exists(__DIR__ . '/' . $emp['photo'])) {
                @unlink(__DIR__ . '/' . $emp['photo']);
            }

            $pdo->prepare("DELETE FROM employees WHERE employee_id = ?")->execute([$id]);
            json_response(['message' => 'Employee permanently deleted.']);
        } catch (PDOException $e) {
            json_response(['error' => 'Cannot delete — this employee is referenced elsewhere (e.g. as a reporting manager).'], 409);
        }
        break;
    }

    case 'employees.approve': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['employee_id'] ?? null;
        if (!$id) json_response(['error' => 'employee_id is required.'], 422);
        $stmt = $pdo->prepare("UPDATE employees SET status = 'approved' WHERE employee_id = ?");
        $stmt->execute([$id]);
        json_response(['message' => 'Employee approved.']);
        break;
    }

    case 'employees.decline': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['employee_id'] ?? null;
        $reason = trim($input['reason'] ?? '');
        if (!$id) json_response(['error' => 'employee_id is required.'], 422);

        $stmt = $pdo->prepare("SELECT * FROM employees WHERE employee_id = ?");
        $stmt->execute([$id]);
        $emp = $stmt->fetch();
        if (!$emp) json_response(['error' => 'Employee not found.'], 404);

        $payload = json_encode([
            'full_name' => $emp['full_name'],
            'mobile' => $emp['mobile'],
            'email' => $emp['email'],
            'address' => $emp['address'],
            'date_of_birth' => $emp['date_of_birth'],
            'joining_date' => $emp['joining_date'],
            'department_id' => $emp['department_id'],
            'reporting_manager_id' => $emp['reporting_manager_id'],
            'basic_salary' => $emp['basic_salary'],
            'employment_type' => $emp['employment_type'],
            'emergency_contact_name' => $emp['emergency_contact_name'],
            'emergency_contact_mobile' => $emp['emergency_contact_mobile'],
            'emergency_contact_relation' => $emp['emergency_contact_relation'],
        ]);

        $histStmt = $pdo->prepare(
            "INSERT INTO approval_history (entity_type, employee_name, employee_code, submitted_by, declined_by, reason, payload)
             VALUES ('employee', ?, ?, ?, ?, ?, ?)"
        );
        $histStmt->execute([$emp['full_name'], $emp['employee_code'], $emp['created_by'], $auth['username'], $reason, $payload]);

        // Clean up anything attached to this employee before removing them —
        // their documents (and files on disk) and photo.
        $docStmt = $pdo->prepare("SELECT document_file FROM employee_documents WHERE employee_id = ?");
        $docStmt->execute([$id]);
        foreach ($docStmt->fetchAll() as $doc) {
            if ($doc['document_file'] && file_exists(__DIR__ . '/' . $doc['document_file'])) {
                @unlink(__DIR__ . '/' . $doc['document_file']);
            }
        }
        $pdo->prepare("DELETE FROM employee_documents WHERE employee_id = ?")->execute([$id]);

        if ($emp['photo'] && file_exists(__DIR__ . '/' . $emp['photo'])) {
            @unlink(__DIR__ . '/' . $emp['photo']);
        }

        $pdo->prepare("DELETE FROM employees WHERE employee_id = ?")->execute([$id]);

        json_response(['message' => 'Employee declined and removed.']);
        break;
    }

    // ============== DOCUMENT TYPES ==============
    case 'document_types.list': {
        require_auth();
        $rows = $pdo->query("SELECT * FROM document_types ORDER BY document_name ASC")->fetchAll();
        json_response(['document_types' => $rows]);
        break;
    }

    case 'document_types.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['document_type_id'] ?? null;
        $name = trim($input['document_name'] ?? '');
        $isRequired = !empty($input['is_required']) ? 1 : 0;
        $hasExpiry = array_key_exists('has_expiry', $input) ? (!empty($input['has_expiry']) ? 1 : 0) : 1;
        if ($name === '') json_response(['error' => 'Document type name is required.'], 422);
        try {
            if ($id) {
                $stmt = $pdo->prepare("UPDATE document_types SET document_name = ?, is_required = ?, has_expiry = ? WHERE document_type_id = ?");
                $stmt->execute([$name, $isRequired, $hasExpiry, $id]);
                json_response(['message' => 'Document type updated.']);
            } else {
                $stmt = $pdo->prepare("INSERT INTO document_types (document_name, is_required, has_expiry) VALUES (?, ?, ?)");
                $stmt->execute([$name, $isRequired, $hasExpiry]);
                json_response(['message' => 'Document type added.', 'document_type_id' => $pdo->lastInsertId()], 201);
            }
        } catch (PDOException $e) {
            json_response(['error' => 'A document type with that name already exists.'], 409);
        }
        break;
    }

    case 'document_types.update': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['document_type_id'] ?? null;
        $name = trim($input['document_name'] ?? '');
        if (!$id || $name === '') json_response(['error' => 'document_type_id and document_name are required.'], 422);
        $hasExpiry = !empty($input['has_expiry']) ? 1 : 0;
        $isRequired = !empty($input['is_required']) ? 1 : 0;
        $pdo->prepare("UPDATE document_types SET document_name = ?, has_expiry = ?, is_required = ? WHERE document_type_id = ?")
            ->execute([$name, $hasExpiry, $isRequired, $id]);
        json_response(['message' => 'Document type updated.']);
        break;
    }

    case 'document_types.delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['document_type_id'] ?? null;
        if (!$id) json_response(['error' => 'document_type_id is required.'], 422);

        $cnt = $pdo->prepare("SELECT COUNT(*) FROM employee_documents WHERE document_type_id = ?");
        $cnt->execute([$id]);
        $docCount = (int)$cnt->fetchColumn();

        if ($docCount > 0 && empty($input['force'])) {
            // Frontend asks the user, then retries with force=1.
            json_response(['needs_force' => true, 'doc_count' => $docCount], 409);
        }

        if ($docCount > 0) {
            // Delete the uploaded files from disk, then the rows.
            $files = $pdo->prepare("SELECT document_file FROM employee_documents WHERE document_type_id = ?");
            $files->execute([$id]);
            foreach ($files->fetchAll() as $f) {
                if ($f['document_file'] && file_exists(__DIR__ . '/' . $f['document_file'])) {
                    @unlink(__DIR__ . '/' . $f['document_file']);
                }
            }
            $pdo->prepare("DELETE FROM employee_documents WHERE document_type_id = ?")->execute([$id]);
        }

        $pdo->prepare("DELETE FROM document_types WHERE document_type_id = ?")->execute([$id]);
        json_response(['message' => 'Document type deleted' . ($docCount > 0 ? " along with $docCount uploaded document(s)." : '.')]);
        break;
    }

    // ============== EMPLOYEE DOCUMENTS ==============
    case 'employee_documents.list': {
        require_auth();
        $employeeId = $_GET['employee_id'] ?? '';
        $status = $_GET['status'] ?? '';

        $sql = "SELECT ed.*, dt.document_name, e.full_name, e.employee_code
                FROM employee_documents ed
                JOIN document_types dt ON dt.document_type_id = ed.document_type_id
                JOIN employees e ON e.employee_id = ed.employee_id
                WHERE 1=1";
        $params = [];

        if ($employeeId !== '') {
            $sql .= " AND ed.employee_id = ?";
            $params[] = $employeeId;
        }
        if ($status !== '') {
            $stList = array_values(array_filter(array_map('trim', explode(',', (string)$status)), 'strlen'));   // status=pending,approved = both in ONE call
            if (count($stList) > 1) {
                $sql .= " AND ed.status IN (" . implode(',', array_fill(0, count($stList), '?')) . ")";
                array_push($params, ...$stList);
            } else {
                $sql .= " AND ed.status = ?";
                $params[] = $status;
            }
        }

        $sql .= " ORDER BY ed.uploaded_at DESC";
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        json_response(['documents' => $stmt->fetchAll()]);
        break;
    }

    case 'employee_documents.upload': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);

        $employeeId = $_POST['employee_id'] ?? null;
        $documentTypeId = $_POST['document_type_id'] ?? null;
        $documentNumber = trim($_POST['document_number'] ?? '');
        $issueDate = $_POST['issue_date'] ?: null;
        $expiryDate = $_POST['expiry_date'] ?: null;
        $remarks = trim($_POST['remarks'] ?? '');

        if (!$employeeId || !$documentTypeId) {
            json_response(['error' => 'employee_id and document_type_id are required.'], 422);
        }
        if (!isset($_FILES['document_file']) || $_FILES['document_file']['error'] !== UPLOAD_ERR_OK) {
            json_response(['error' => 'A valid file is required.'], 422);
        }

        $file = $_FILES['document_file'];
        $allowedExt = ['pdf', 'jpg', 'jpeg', 'png'];
        $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
        if (!in_array($ext, $allowedExt, true)) {
            json_response(['error' => 'Only PDF, JPG, and PNG files are allowed.'], 422);
        }

        $uploadDir = __DIR__ . '/uploads/';
        if (!is_dir($uploadDir)) {
            mkdir($uploadDir, 0755, true);
        }

        $safeName = 'doc_' . $employeeId . '_' . time() . '_' . bin2hex(random_bytes(4)) . '.' . $ext;
        $destPath = $uploadDir . $safeName;

        if (!move_uploaded_file($file['tmp_name'], $destPath)) {
            json_response(['error' => 'Failed to save the uploaded file.'], 500);
        }

        $stmt = $pdo->prepare(
            "INSERT INTO employee_documents
                (employee_id, document_type_id, document_number, document_file, issue_date, expiry_date, remarks, status, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)"
        );
        $docStatus = ($auth['role'] === 'Admin') ? 'approved' : 'pending';
        $stmt->execute([$employeeId, $documentTypeId, $documentNumber, 'uploads/' . $safeName, $issueDate, $expiryDate, $remarks, $docStatus, $auth['username']]);

        json_response([
            'message' => $docStatus === 'pending' ? 'Document uploaded — pending Admin approval.' : 'Document uploaded.',
            'employee_document_id' => $pdo->lastInsertId(),
            'status' => $docStatus,
        ], 201);
        break;
    }

    case 'employee_documents.update': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);

        // Two shapes accepted: a plain JSON body (edit only, keep existing
        // file), or multipart/form-data (edit + optionally replace the file) —
        // same dual pattern used by employee_documents.upload for the file case.
        $hasFile = isset($_FILES['document_file']) && $_FILES['document_file']['error'] === UPLOAD_ERR_OK;

        if ($hasFile) {
            $id = $_POST['employee_document_id'] ?? null;
            $documentTypeId = $_POST['document_type_id'] ?? null;
            $documentNumber = trim($_POST['document_number'] ?? '');
            $issueDate = $_POST['issue_date'] ?: null;
            $expiryDate = $_POST['expiry_date'] ?: null;
            $remarks = trim($_POST['remarks'] ?? '');
        } else {
            $input = json_input();
            $id = $input['employee_document_id'] ?? null;
            $documentTypeId = $input['document_type_id'] ?? null;
            $documentNumber = trim($input['document_number'] ?? '');
            $issueDate = $input['issue_date'] ?: null;
            $expiryDate = $input['expiry_date'] ?: null;
            $remarks = trim($input['remarks'] ?? '');
        }

        if (!$id) json_response(['error' => 'employee_document_id is required.'], 422);
        if (!$documentTypeId) json_response(['error' => 'document_type_id is required.'], 422);

        $existingStmt = $pdo->prepare("SELECT document_file FROM employee_documents WHERE employee_document_id = ?");
        $existingStmt->execute([$id]);
        $existing = $existingStmt->fetch();
        if (!$existing) json_response(['error' => 'Document not found.'], 404);

        $newFilePath = null;
        if ($hasFile) {
            $file = $_FILES['document_file'];
            $allowedExt = ['pdf', 'jpg', 'jpeg', 'png'];
            $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
            if (!in_array($ext, $allowedExt, true)) {
                json_response(['error' => 'Only PDF, JPG, and PNG files are allowed.'], 422);
            }

            $uploadDir = __DIR__ . '/uploads/';
            if (!is_dir($uploadDir)) {
                mkdir($uploadDir, 0755, true);
            }

            $safeName = 'doc_' . $id . '_' . time() . '_' . bin2hex(random_bytes(4)) . '.' . $ext;
            $destPath = $uploadDir . $safeName;

            if (!move_uploaded_file($file['tmp_name'], $destPath)) {
                json_response(['error' => 'Failed to save the uploaded file.'], 500);
            }

            $newFilePath = 'uploads/' . $safeName;
        }

        if ($newFilePath) {
            $stmt = $pdo->prepare(
                "UPDATE employee_documents SET
                    document_type_id = ?, document_number = ?, document_file = ?,
                    issue_date = ?, expiry_date = ?, remarks = ?
                 WHERE employee_document_id = ?"
            );
            $stmt->execute([$documentTypeId, $documentNumber, $newFilePath, $issueDate, $expiryDate, $remarks, $id]);

            if ($existing['document_file'] && file_exists(__DIR__ . '/' . $existing['document_file'])) {
                @unlink(__DIR__ . '/' . $existing['document_file']);
            }
        } else {
            $stmt = $pdo->prepare(
                "UPDATE employee_documents SET
                    document_type_id = ?, document_number = ?,
                    issue_date = ?, expiry_date = ?, remarks = ?
                 WHERE employee_document_id = ?"
            );
            $stmt->execute([$documentTypeId, $documentNumber, $issueDate, $expiryDate, $remarks, $id]);
        }

        json_response(['message' => 'Document updated.']);
        break;
    }

