        $reason = trim($input['reason'] ?? '');
        if (!$id) json_response(['error' => 'employee_document_id is required.'], 422);

        $stmt = $pdo->prepare(
            "SELECT ed.*, dt.document_name, dt.document_type_id, e.full_name, e.employee_code
             FROM employee_documents ed
             JOIN document_types dt ON dt.document_type_id = ed.document_type_id
             JOIN employees e ON e.employee_id = ed.employee_id
             WHERE ed.employee_document_id = ?"
        );
        $stmt->execute([$id]);
        $doc = $stmt->fetch();
        if (!$doc) json_response(['error' => 'Document not found.'], 404);

        $payload = json_encode([
            'employee_id' => $doc['employee_id'],
            'document_type_id' => $doc['document_type_id'],
            'document_number' => $doc['document_number'],
            'issue_date' => $doc['issue_date'],
            'expiry_date' => $doc['expiry_date'],
            'remarks' => $doc['remarks'],
        ]);

        $histStmt = $pdo->prepare(
            "INSERT INTO approval_history (entity_type, employee_name, employee_code, document_name, submitted_by, declined_by, reason, payload)
             VALUES ('document', ?, ?, ?, ?, ?, ?, ?)"
        );
        $histStmt->execute([$doc['full_name'], $doc['employee_code'], $doc['document_name'], $doc['created_by'], $auth['username'], $reason, $payload]);

        if ($doc['document_file'] && file_exists(__DIR__ . '/' . $doc['document_file'])) {
            @unlink(__DIR__ . '/' . $doc['document_file']);
        }
        $pdo->prepare("DELETE FROM employee_documents WHERE employee_document_id = ?")->execute([$id]);

