    // ============== APPROVAL HISTORY ==============
    case 'approval_history.list': {
        $auth = require_auth();
        $sql = "SELECT * FROM approval_history";
        $params = [];
        if ($auth['role'] !== 'Admin') {
            // HR only sees history for things they personally submitted.
            $sql .= " WHERE submitted_by = ?";
            $params[] = $auth['username'];
        }
        // `limit` (1-200) and `offset` give one page of rows plus `total`; without `limit` every row is returned (old behaviour)
        $lim = (int)($_GET['limit'] ?? 0); $off = max(0, (int)($_GET['offset'] ?? 0));
        $total = null;
        if ($lim > 0) {
            $lim = min(200, $lim);
            $cq = $pdo->prepare(str_replace('SELECT *', 'SELECT COUNT(*)', $sql)); $cq->execute($params); $total = (int)$cq->fetchColumn();
        }
        $sql .= " ORDER BY declined_at DESC" . ($lim > 0 ? " LIMIT $lim OFFSET $off" : '');
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll();
        json_response(['history' => $rows, 'total' => $total === null ? count($rows) : $total]);
        break;
    }

