    // ============== EMPLOYEE SOURCES (Google Sheets / WhatsApp mapping) ==============
    case 'employee_sources.sync': {
        // Called by n8n with the full mapping for ONE spreadsheet. Old rows for
        // that spreadsheet are wiped and replaced, so deletions in the sheet
        // also disappear here. n8n authenticates with the X-API-Key header.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();

        $sourceType = trim($input['source_type'] ?? 'sheet');
        $sourceName = trim($input['source_name'] ?? '');
        $sourceUrl  = trim($input['source_url'] ?? '');
        $entries    = $input['entries'] ?? [];

        if ($sourceName === '') json_response(['error' => 'source_name is required.'], 422);
        if (!is_array($entries)) json_response(['error' => 'entries must be an array.'], 422);

        $pdo->beginTransaction();
        try {
            $del = $pdo->prepare("DELETE FROM employee_sources WHERE source_type = ? AND source_name = ?");
            $del->execute([$sourceType, $sourceName]);

            $ins = $pdo->prepare(
                "INSERT INTO employee_sources (employee_id, source_type, source_name, sheet_name, row_no, matched_on, source_url)
                 VALUES (?, ?, ?, ?, ?, ?, ?)"
            );
            $count = 0;
            foreach ($entries as $en) {
                if (empty($en['employee_id'])) continue;
                $ins->execute([
                    (int)$en['employee_id'],
                    $sourceType,
                    $sourceName,
                    $en['sheet_name'] ?? null,
                    isset($en['row_number']) ? (int)$en['row_number'] : null,
                    $en['matched_on'] ?? null,
                    $sourceUrl ?: null,
                ]);
                $count++;
            }
            $pdo->commit();
            json_response(['message' => "Synced $count entries for \"$sourceName\".", 'count' => $count]);
        } catch (PDOException $e) {
            $pdo->rollBack();
            json_response(['error' => 'Sync failed: ' . $e->getMessage()], 500);
        }
        break;
    }

    case 'employee_sources.get': {
        require_auth();
        $employeeId = $_GET['employee_id'] ?? null;
        if (!$employeeId) json_response(['error' => 'employee_id is required.'], 422);
        // Sheet mappings (from Apps Script) + manual Excel-file memberships +
        // WhatsApp group memberships, unified so the Found In card shows all.
        $stmt = $pdo->prepare(
            "SELECT source_id, employee_id, source_type, source_name, sheet_name, row_no, matched_on, source_url, last_synced
             FROM employee_sources WHERE employee_id = ?
             UNION ALL
             SELECT NULL, eef.employee_id, 'sheet', ef.file_name, NULL, NULL, 'manual', ef.file_url, eef.added_at
             FROM employee_excel_files eef
             JOIN excel_files ef ON ef.file_id = eef.file_id
             WHERE eef.employee_id = ?
             UNION ALL
             SELECT NULL, ewg.employee_id, 'whatsapp', wg.group_name, NULL, NULL, 'manual', NULL, ewg.added_at
             FROM employee_whatsapp_groups ewg
             JOIN whatsapp_groups wg ON wg.group_id = ewg.group_id
             WHERE ewg.employee_id = ?
             ORDER BY source_type, source_name, sheet_name, row_no"
        );
        $stmt->execute([$employeeId, $employeeId, $employeeId]);
        json_response(['sources' => $stmt->fetchAll()]);
        break;
    }

    // ============== ATTENDANCE (face punch in/out) ==============
    case 'face.get': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $stmt = $pdo->prepare("SELECT face_descriptor FROM employees WHERE employee_id = ?");
        $stmt->execute([$auth['employee_id']]);
        // A few OTHER employees' fingerprints (no names) let the phone check
        // that the live face matches this person and NOT the others — an
        // independent guard against look-alikes and imprecise phone maths.
        $o = $pdo->prepare("SELECT face_descriptor FROM employees WHERE employee_id <> ? AND face_descriptor IS NOT NULL AND face_descriptor <> '' ORDER BY RAND() LIMIT 6");
        $o->execute([$auth['employee_id']]);
        json_response(['descriptor' => $stmt->fetchColumn() ?: null, 'others' => $o->fetchAll(PDO::FETCH_COLUMN)]);
        break;
    }

    case 'face.enroll': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $descriptor = $input['descriptor'] ?? null;
        if (!is_array($descriptor) || count($descriptor) !== 128) {
            json_response(['error' => 'Invalid face data.'], 422);
        }
        $stmt = $pdo->prepare("SELECT face_descriptor FROM employees WHERE employee_id = ?");
        $stmt->execute([$auth['employee_id']]);
        if ($stmt->fetchColumn()) {
            json_response(['error' => 'Face already enrolled. Ask Admin to reset it if needed.'], 409);
        }
        // Proofs the admin asked for at the Enroll step (once): all of them must be uploaded before the face is saved.
        $epf = proof_stage_state($pdo, (int)$auth['employee_id'], 'enroll', '');
        if ($epf['total'] && !$epf['complete']) {
            json_response(['error' => 'Upload your proof first — ' . implode(', ', $epf['missing']) . '.', 'proofs' => $epf], 409);
        }
        $pdo->prepare("UPDATE employees SET face_descriptor = ? WHERE employee_id = ?")
            ->execute([json_encode($descriptor), $auth['employee_id']]);
        json_response(['message' => 'Face enrolled.']);
        break;
    }

