    case 'diag.access': {
        // Open in a browser while logged in (the page adds the token):
        //   api.php?action=diag.access&token=...
        // Explains, for THIS login, why a page shows or not.
        $auth = !empty($_GET['token']) ? verify_token((string)$_GET['token']) : require_auth();
        if (!$auth) json_response(['error' => 'Unauthorized. Please log in again.'], 401);
        $auth = refresh_auth($auth);
        $role = $auth['role'] ?? '';
        $out = ['api_build' => HRMS_BUILD, 'login' => $auth['username'] ?? '', 'role_in_users_table' => $role, 'employee_id' => $auth['employee_id'] ?? null];
        $out['modules_in_this_api'] = array_keys(all_permissions());
        $out['your_effective_modules'] = $role === 'Admin' ? array_keys(all_permissions()) : role_permissions($pdo, $role);
        $out['order_allocation_visible'] = $role === 'Admin' || in_array('allocation', $out['your_effective_modules'], true);
        try {
            ensure_roles_known_column($pdo);
            $out['roles_table'] = $pdo->query("SELECT role_id, role_name, is_system, permissions, known_modules FROM roles")->fetchAll();
        } catch (PDOException $e) { $out['roles_table'] = 'ERROR: ' . $e->getMessage(); }
        try { $out['users_by_role'] = $pdo->query("SELECT role, COUNT(*) AS users FROM users GROUP BY role")->fetchAll(); } catch (PDOException $e) {}
        try { ensure_order_allocations_table($pdo); $out['order_allocations_rows'] = (int)$pdo->query("SELECT COUNT(*) FROM order_allocations")->fetchColumn(); } catch (PDOException $e) { $out['order_allocations_rows'] = 'ERROR: ' . $e->getMessage(); }
        $out['hint'] = $out['order_allocation_visible']
            ? 'This login CAN see Order Allocation. If the menu still lacks it, the browser is running an old layout.js — check the build shown under your name in the sidebar (must be ' . HRMS_BUILD . ').'
            : 'This login CANNOT see Order Allocation: tick "Order Allocation" for role "' . $role . '" on the Roles page.';
        json_response($out);
        break;
    }

    case 'me.flags': {
        // Lightweight flags for the employee portal sidebar.
        $auth = require_auth();
        json_response(me_flags_data($pdo, $auth));
        break;
    }

    case 'my.stats': {
        // The logged-in employee's own sales numbers for their portal.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);

        $stmt = $pdo->prepare("SELECT e.full_name, e.sales_tag, e.basic_salary, e.joining_date, e.designation, d.department_name FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.employee_id = ?");
        $stmt->execute([$auth['employee_id']]);
        $emp = $stmt->fetch();
        if (!$emp) json_response(['error' => 'Employee not found.'], 404);

        $month = date('Y-m');
        $daysInMonth = (int)date('t');
        // Business day per the Day timing setting (default: before 10 AM it is still yesterday).
        $bizDay = biz_today($pdo);

        // The month's figures are stored per house (one targets row per
        // group_key); the employee has ONE target, so add every row up.
        // fetch() used to read a single row, showing one house's sales only.
        ensure_group_key_column($pdo, 'targets', ['month', 'employee_id']);
        $tStmt = $pdo->prepare(
            "SELECT SUM(manual_target) AS manual_target, MAX(manual_target IS NOT NULL) AS has_manual,
                    SUM(achieved) AS achieved, SUM(orders_count) AS orders_count
             FROM targets WHERE month = ? AND employee_id = ?"
        );
        $tStmt->execute([$month, $auth['employee_id']]);
        $tRow = $tStmt->fetch();

        // Today's target: the one set by hand on the Targets page for today
        // wins (same daily_targets row the admin page reads); with none there,
        // the targets set per panel on the Orders page add up; else the
        // profile Daily Target.
        // ONE rule with the Control Tower and the ratings (sales_target_fn): leave = none → set for today → monthly target set by hand ÷ days → profile target lifted by the ladder.
        $dailyTarget = sales_target_fn($pdo, [(int)$auth['employee_id'] => $emp], $bizDay, $bizDay, day_marks_between($pdo, $bizDay, $bizDay, (int)$auth['employee_id']))((int)$auth['employee_id'], $bizDay);
        // A new Sales Executive's first four weeks: the ladder (10,000 / 15,000 / 20,000 / 25,000 a day) is the lowest target. Shown only while it is what applies.
        $lad = sales_ladder_for($emp, $bizDay);
        if ($lad !== null && abs($dailyTarget - (float)$lad['amount']) > 0.01) $lad = null;
        $monthlyTarget = sales_month_target($emp, $month, (float)$emp['basic_salary'], ($tRow && (int)$tRow['has_manual']) ? (float)$tRow['manual_target'] : null);

        $todaySales = 0; $todayOrders = 0; $todayError = null;
        $tag = mb_strtolower(trim((string)$emp['sales_tag']));
        $allocMap = order_allocations($pdo);
        $myId = (int)$auth['employee_id'];
        // Today's orders split by the type chosen on the Order Allocation page (Query / Campaign; the order tag when none was chosen).
        $byType = ['query' => ['orders' => 0, 'sales' => 0.0], 'campaign' => ['orders' => 0, 'sales' => 0.0]];
        $bumpType = function (string $type, float $amt) use (&$byType) { if (isset($byType[$type])) { $byType[$type]['orders']++; $byType[$type]['sales'] += $amt; } };
        $tagType = function (string $tags): string {
            foreach (explode(',', $tags) as $t) {
                $t = mb_strtolower(trim($t));
                if ($t === 'query' || $t === 's') return 'query';
                if ($t === 'campaign' || $t === 'c') return 'campaign';
            }
            return '';
        };
        if ($tag !== '' || $allocMap) {
            $stores = shopify_stores();
            $tokens = [];
            foreach ($stores as $key => $store) {
                if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
                $token = shopify_get_token($key, $store);
                if (is_array($token)) { unset($stores[$key]); continue; }
                $tokens[$key] = $token;
            }
            if ($stores) {
                $results = orders_by_store_cached($pdo, $stores, $bizDay, $bizDay) ?? shopify_fetch_all($stores, $tokens, $bizDay, $bizDay, 8, true);      // local order cache (synced every 3 min) — much faster than paging Shopify
                foreach ($results as $storeKey => $st) {
                    if ($st['error']) { $todayError = $st['error']; continue; }
                    foreach ($st['orders'] as $o) {
                        // Allocated on the Order Allocation page: that employee, no one else.
                        $a = $allocMap[$storeKey . '|' . (string)$o['id']] ?? null;
                        if ($a && !empty($a['direct'])) continue;   // Direct order: nobody's sale
                        if ($a && !empty($a['emp'])) {
                            if ((int)$a['emp'] === $myId) { $todaySales += (float)$o['total']; $todayOrders++; $bumpType((string)($a['type'] ?? ''), (float)$o['total']); }
                            continue;
                        }
                        if ($tag === '') continue;
                        foreach (explode(',', (string)($o['tags'] ?? '')) as $t) {
                            if (mb_strtolower(trim($t)) === $tag) {
                                $todaySales += (float)$o['total'];
                                $todayOrders++;
                                $bumpType($tagType((string)($o['tags'] ?? '')), (float)$o['total']);
                                break;
                            }
                        }
                    }
                }
            }
        }

        // MySales orders moved to a house on the Order Allocation page.
        $allocErrs = [];
        foreach (allocated_house_orders($pdo, $bizDay, $bizDay, $allocErrs) as $o) {
            if ($o['emp_id'] === (int)$auth['employee_id']) { $todaySales += (float)$o['total']; $todayOrders++; $bumpType((string)($o['order_type'] ?? ''), (float)$o['total']); }
        }

        // Query / Campaign counts set for him on the Assign Queries page: today, this month, and today per panel.
        $qc = ['query' => ['today' => 0, 'month' => 0], 'campaign' => ['today' => 0, 'month' => 0]];
        $qcPanels = [];
        try {
            $gl = house_labels();
            // old typed counts before the cut-over date, WhatsApp Sales (by holder) from it; a day is never both
            foreach (array_filter(qa_rows($pdo, $month . '-01', date('Y-m-t', strtotime($month . '-01'))), fn($r) => (int)$r['employee_id'] === $myId) as $r) {
                $q = (int)$r['q']; $c = (int)$r['c'];
                $qc['query']['month'] += $q; $qc['campaign']['month'] += $c;
                if (substr((string)$r['query_date'], 0, 10) === $bizDay) {
                    $qc['query']['today'] += $q; $qc['campaign']['today'] += $c;
                    $gk = (string)$r['group_key'];
                    if ($q || $c) $qcPanels[] = ['panel' => $gk, 'label' => $gl[$gk] ?? ($gk !== '' ? $gk : 'No panel'), 'query' => $q, 'campaign' => $c];
                }
            }
        } catch (PDOException $e) { /* table missing — shows zeros */ }
        foreach (['query', 'campaign'] as $k) { $qc[$k]['orders'] = $byType[$k]['orders']; $qc[$k]['sales'] = round($byType[$k]['sales'], 2); }

        json_response([
            'qc' => $qc,
            'qc_panels' => $qcPanels,
            'name' => $emp['full_name'],
            'tag' => $emp['sales_tag'],
            'business_day' => $bizDay,
            'today' => ['sales' => round($todaySales, 2), 'orders' => $todayOrders, 'error' => $todayError],
            'month' => [
                'sales' => $tRow ? (float)$tRow['achieved'] : 0,
                'orders' => $tRow ? (int)($tRow['orders_count'] ?? 0) : 0,
                'target' => round($monthlyTarget, 2),
            ],
            'daily_target' => $dailyTarget,
            'ladder' => $lad !== null ? ['week' => $lad['week'], 'amount' => $lad['amount']] : null,
        ]);
        break;
    }

    case 'convo.analyze': {
