        if ($r['status'] === 'analyzing' && strtotime((string)$r['updated_at']) > time() - 600) json_response(['upload' => convo_public($r, true), 'busy' => true]);
        if ($r['status'] === 'done' && empty($in['force'])) json_response(['upload' => convo_public($r, true)]);
