        ensure_convo_tables($pdo);
        $days = in_array((int)($_GET['days'] ?? 7), [7, 30], true) ? (int)($_GET['days'] ?? 7) : 7;
        $from = date('Y-m-d H:i:s', time() - $days * 86400); $pfrom = date('Y-m-d H:i:s', time() - 2 * $days * 86400);
        $now = convo_stats($pdo, $from); $prev = convo_stats($pdo, $pfrom, $from);
        $c = coach_day($pdo, biz_today($pdo));
        $top = convo_top_ids($c['emps']); $names = employee_names_by_id($pdo); $sk = convo_skill_names();
        $ids = array_unique(array_merge(array_keys($c['emps']), array_keys($now)));
        $rows = [];
        foreach ($ids as $id) {
            $p = $now[$id] ?? null; $best = null; $weak = null;
            if ($p) foreach ($p['avg'] as $k => $v) {
                if (!isset($sk[$k]) || ($p['cnt'][$k] ?? 0) < 2) continue;
                if ($best === null || $v > $p['avg'][$best]) $best = $k;
                if ($weak === null || $v < $p['avg'][$weak]) $weak = $k;
            }
            $q = $pdo->prepare("SELECT COUNT(*) FROM convo_uploads WHERE employee_id = ? AND created_at >= ? AND status IN ('need_more', 'saved', 'analyzing', 'incomplete', 'error', 'waiting')"); $q->execute([$id, $from]);
            $rows[] = ['id' => (int)$id, 'name' => $names[$id] ?? ('#' . $id), 'top' => in_array((int)$id, $top, true), 'n' => $p['n'] ?? 0, 'lost' => $p['lost'] ?? 0, 'calls' => $p['calls'] ?? 0,
                'avg' => $p['avg']['overall'] ?? null, 'prev' => $prev[$id]['avg']['overall'] ?? null, 'call_avg' => $p['avg']['call_overall'] ?? null,
                'best' => $best ? $sk[$best] : null, 'weak' => $weak && $weak !== $best ? $sk[$weak] : null,
                'habits' => $p ? array_intersect_key($p['avg'], array_flip(['offered_10ml', 'offered_combo', 'asked_prepaid', 'questions', 'reply_min', 'obj_handled', 'talk', 'interrupt'])) : [],
                'open' => (int)$q->fetchColumn(), 'orders' => $c['emps'][$id]['orders'] ?? 0];
        }
        usort($rows, fn($a, $b) => ($b['avg'] ?? -1) <=> ($a['avg'] ?? -1) ?: $b['n'] <=> $a['n']);
        $q = $pdo->prepare("SELECT * FROM convo_uploads WHERE status = 'done' AND flag_wrong = 0 AND created_at >= ? AND score IS NOT NULL ORDER BY score DESC, analyzed_at DESC LIMIT 6"); $q->execute([$from]);
        $best = array_map(function ($r) use ($names) { $ch = convo_result($r)['chat'] ?? []; return convo_public($r) + ['employee' => $names[(int)$r['employee_id']] ?? '', 'summary' => $ch['summary'] ?? '', 'best_line' => $ch['best_line'] ?? '']; }, $q->fetchAll());
        $q = $pdo->prepare("SELECT result FROM convo_uploads WHERE kind = 'lost' AND status = 'done' AND flag_wrong = 0 AND created_at >= ?"); $q->execute([$from]);
        $reasons = [];
        foreach ($q->fetchAll() as $r) { $rr = convo_result($r); $x = strtolower(trim((string)($rr['chat']['lost_reason'] ?? ($rr['call']['lost_reason'] ?? '')))); if ($x !== '') $reasons[$x] = ($reasons[$x] ?? 0) + 1; }
        arsort($reasons);
        $all = convo_group($now, array_keys($now)); $T = convo_group($now, $top); $R = convo_group($now, array_values(array_diff(array_keys($now), $top)));
        $pb = convo_playbook($pdo);
        $stale = !$pb || strtotime((string)($pb['built_at'] ?? '2000-01-01')) < time() - 7 * 86400;
        json_response(['days' => $days, 'cfg' => convo_cfg(), 'rows' => $rows, 'best' => $best, 'lost_reasons' => array_slice($reasons, 0, 8, true),
            'totals' => ['chats' => $all['n'], 'calls' => $all['calls'], 'lost' => array_sum(array_column($rows, 'lost')), 'avg' => $all['avg']['overall'] ?? null],
            'top_avg' => $T['avg'], 'rest_avg' => $R['avg'], 'skill_names' => $sk, 'playbook' => $pb ?: null, 'playbook_stale' => $stale]);
        break;
