    case 'rating.team': {
        // Orders page "Team rating" box (Admin / HR / Orders page access). ?view=today|month|last
        $auth = require_auth();
        if (!orders_page_controls($auth) && !ct_admin_ok($pdo, $auth)) require_role(['Admin', 'HR'], $auth);       // Control Tower people (Admin / HR / named resolvers) see the ratings too
        $view = in_array($_GET['view'] ?? 'today', ['today', 'month', 'last'], true) ? (string)($_GET['view'] ?? 'today') : 'today';
        $today = biz_today($pdo); $m1 = substr($today, 0, 8) . '01';
        $lm1 = date('Y-m-01', strtotime($m1 . ' -1 day')); $lmTo = date('Y-m-t', strtotime($lm1));
        $emps = rating_emps($pdo);
        $rows = [];
        if ($view === 'today') {
            $days = rating_days($pdo, date('Y-m-d', strtotime($today . ' -7 day')), $today);
            foreach ($emps as $id => $e) {
                $x = $days[$today][$id] ?? null;
                $prev = null; for ($i = 1; $i <= 7 && $prev === null; $i++) { $d = date('Y-m-d', strtotime($today . " -$i day")); if (isset($days[$d][$id]) && $days[$d][$id]['score'] !== null) $prev = $days[$d][$id]['score']; }
                if (!$x || $x['score'] === null) { if ($prev !== null) $rows[] = ['id' => $id, 'name' => trim((string)$e['full_name']), 'score' => null, 'parts' => [], 'notes' => [], 'prev' => $prev, 'insight' => null]; continue; }
                $rows[] = ['id' => $id, 'name' => trim((string)$e['full_name']), 'score' => $x['score'], 'parts' => $x['parts'], 'notes' => $x['notes'], 'prev' => $prev, 'insight' => rating_insight($x['parts'])];
            }
        } else {
            [$f, $t] = $view === 'month' ? [$m1, $today] : [$lm1, $lmTo];
            $days = rating_days($pdo, $f, $t);
            $prevDays = $view === 'month' ? rating_days($pdo, $lm1, $lmTo) : rating_days($pdo, date('Y-m-01', strtotime($lm1 . ' -1 day')), date('Y-m-t', strtotime($lm1 . ' -1 day')));
            foreach ($emps as $id => $e) {
                $x = rating_period($days, $id); if (!$x || $x['score'] === null) continue;
                $pv = rating_period($prevDays, $id);
                $rows[] = ['id' => $id, 'name' => trim((string)$e['full_name']), 'score' => $x['score'], 'parts' => $x['parts'], 'notes' => $x['notes'], 'prev' => $pv ? $pv['score'] : null,
                    'days' => $x['days'], 'insight' => rating_insight($x['parts'])];
            }
        }
        // Total sales + total target of each person for the same period (the allocated sales the Today tab uses; target = the sum of the daily targets).
        @set_time_limit(90);
        [$sf, $st] = $view === 'today' ? [$today, $today] : ($view === 'month' ? [$m1, $today] : [$lm1, $lmTo]);
        $tot = [];
        for ($d = $sf, $guard = 0; $d <= $st && $guard < 32; $d = date('Y-m-d', strtotime($d . ' +1 day')), $guard++) {
            try { $cd = coach_day($pdo, $d, false); } catch (Throwable $e) { continue; }
            foreach ($cd['emps'] as $id => $x) {
                $t = &$tot[$id]; if (!$t) $t = ['sales' => 0.0, 'orders' => 0, 'target' => 0.0];
                $t['sales'] += (float)$x['sales']; $t['orders'] += (int)$x['orders']; $t['target'] += (float)$x['target']; unset($t);
            }
        }
        foreach ($rows as &$rw) { $t = $tot[$rw['id']] ?? ['sales' => 0, 'orders' => 0, 'target' => 0]; $rw['sales'] = round($t['sales']); $rw['orders'] = (int)$t['orders']; $rw['target'] = round($t['target']); $rw['pct'] = $t['target'] > 0 ? round($t['sales'] / $t['target'] * 100) : null; }
        unset($rw);
        usort($rows, fn($a, $b) => ($b['score'] ?? -1) <=> ($a['score'] ?? -1));
        // team weak spot: the part with the lowest average (people who have it), and how many are below 6
        $avg = []; $low = []; $cnt = [];
        foreach ($rows as $r) foreach ($r['parts'] as $k => $v) if ($v !== null) { $avg[$k] = ($avg[$k] ?? 0) + $v; $cnt[$k] = ($cnt[$k] ?? 0) + 1; if ($v < 6) $low[$k] = ($low[$k] ?? 0) + 1; }
        foreach ($avg as $k => $s) $avg[$k] = round($s / $cnt[$k], 1);
        $weak = null; foreach ($avg as $k => $v) if (($cnt[$k] ?? 0) >= 2 && ($weak === null || $v < $avg[$weak])) $weak = $k;
        $scored = array_values(array_filter(array_column($rows, 'score'), fn($v) => $v !== null));
        json_response(['view' => $view, 'today' => $today, 'parts' => rating_parts(), 'rows' => $rows, 'part_avg' => $avg,
            'team' => ['avg' => $scored ? round(array_sum($scored) / count($scored), 1) : null, 'people' => count($scored),
                'strong' => count(array_filter($scored, fn($v) => $v >= 7)), 'focus' => count(array_filter($scored, fn($v) => $v < 5.5)),
                'weak' => $weak ? ['k' => $weak, 'avg' => $avg[$weak], 'below6' => $low[$weak] ?? 0, 'of' => $cnt[$weak]] : null],
            'period' => $view === 'today' ? $today : ($view === 'month' ? substr($today, 0, 7) : substr($lm1, 0, 7))]);
        break;
    }

