    case 'convo.backfill_status': {
        // Admin: how many old uploads are already read into the database (convo_messages), how many are left, how many can no longer be read (files deleted after the keep-days).
        $auth = require_auth(); ensure_convo_tables($pdo);
        if (!convo_is_admin($auth)) json_response(['error' => 'Only Admin / HR can use this.'], 403);
        $row = $pdo->query("SELECT COUNT(*) AS total, COALESCE(SUM(msgs_at IS NOT NULL), 0) AS rd, COALESCE(SUM(msgs_at IS NULL AND files_gone = 1), 0) AS gone,
            COALESCE(SUM((msgs_at IS NULL OR msgs_sig = '') AND files_gone = 0 AND msgs_tries < 3), 0) AS pending, COALESCE(SUM((msgs_at IS NULL OR msgs_sig = '') AND files_gone = 0 AND msgs_tries >= 3), 0) AS failed
            FROM convo_uploads WHERE status IN ('done', 'incomplete') AND (shots > 0 OR has_video = 1 OR has_call = 1)")->fetch();
        $msgs = (int)$pdo->query("SELECT COUNT(*) FROM convo_messages")->fetchColumn();
        json_response(['total' => (int)$row['total'], 'read' => (int)$row['rd'], 'gone' => (int)$row['gone'], 'pending' => (int)$row['pending'], 'failed' => (int)$row['failed'], 'messages' => $msgs, 'keep_days' => convo_cfg()['keep_days'], 'ai' => convo_gemini_key() !== '' || convo_cfg()['ai']]);
