    case 'convo.backfill_run': {
        // Admin: reads the next old uploads (newest first) into the database. Body {n: 1..3}. The page calls it again and again until "pending" is 0.
        $auth = require_auth(); ensure_convo_tables($pdo);
        if (!convo_is_admin($auth)) json_response(['error' => 'Only Admin / HR can use this.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input(); $n = max(1, min(3, (int)($in['n'] ?? 1)));
        ignore_user_abort(true); @set_time_limit(200);
        $lock = sys_get_temp_dir() . '/hrms_convo_backfill.lock';
        if (is_file($lock) && filemtime($lock) > time() - 240) json_response(['busy' => true, 'done' => 0, 'saved' => 0, 'errors' => []]);
        @touch($lock); $t0 = time(); $done = 0; $saved = 0; $errs = [];
        try {
            lib_requeue_calls($pdo);
            $q = $pdo->query("SELECT id FROM convo_uploads WHERE status IN ('done', 'incomplete') AND (shots > 0 OR has_video = 1 OR has_call = 1) AND (msgs_at IS NULL OR msgs_sig = '') AND files_gone = 0 AND msgs_tries < 3 ORDER BY has_call DESC, id DESC LIMIT " . $n);
            foreach ($q->fetchAll(PDO::FETCH_COLUMN) as $uid) {
                if (time() - $t0 > 110) break;
                [$ok, $note] = convo_transcribe($pdo, (int)$uid); $done++;
                if ($ok) { $c = $pdo->prepare("SELECT msgs_n FROM convo_uploads WHERE id = ?"); $c->execute([$uid]); $saved += (int)$c->fetchColumn(); } else $errs[] = '#' . $uid . ': ' . mb_substr($note, 0, 140);
                @touch($lock);
            }
        } finally { @unlink($lock); }
        json_response(['done' => $done, 'saved' => $saved, 'errors' => $errs]);
        break;
    }

    // ===================== 📚 Chat library / Practice bot / Replay / Ready scorecard (Sales page) =====================
