        $lim = max(1, min(50, (int)($_GET['limit'] ?? 30))); $off = max(0, (int)($_GET['offset'] ?? 0));
        $cw = "u.status IN ('done', 'incomplete') AND u.flag_wrong = 0 AND u.msgs_n > 0"; $par = [];
        if ($emp > 0) { $cw .= " AND u.employee_id = ?"; $par[] = $emp; }
        if ($from !== '') { $cw .= " AND DATE(u.created_at) >= ?"; $par[] = $from; }
        if ($to !== '') { $cw .= " AND DATE(u.created_at) <= ?"; $par[] = $to; }
        if ($qs !== '') { $l = lib_like($qs); $cw .= " AND (u.order_name LIKE ? OR u.note LIKE ? OR EXISTS (SELECT 1 FROM convo_messages m WHERE m.upload_id = u.id AND m.msg_text LIKE ?))"; array_push($par, $l, $l, $l); }
        $hasCall = "EXISTS (SELECT 1 FROM convo_messages k WHERE k.upload_id = u.id AND k.src = 'call')";
        $cq = $pdo->prepare("SELECT COUNT(*) AS a, COALESCE(SUM(u.kind = 'order'), 0) AS o, COALESCE(SUM(u.kind = 'lost'), 0) AS l, COALESCE(SUM($hasCall), 0) AS c FROM convo_uploads u WHERE $cw"); $cq->execute($par); $cnt = $cq->fetch();
        $w = $cw . ($kind === 'ordered' ? " AND u.kind = 'order'" : ($kind === 'lost' ? " AND u.kind = 'lost'" : ($kind === 'calls' ? " AND $hasCall" : '')));
        $q = $pdo->prepare("SELECT u.*, (SELECT COUNT(*) FROM convo_messages m WHERE m.upload_id = u.id AND m.src = 'chat') AS chat_n, (SELECT COUNT(*) FROM convo_messages m WHERE m.upload_id = u.id AND m.src = 'call') AS call_n,
                (SELECT COUNT(*) FROM lib_best b WHERE b.upload_id = u.id) AS starred FROM convo_uploads u WHERE $w ORDER BY u.id DESC LIMIT $lim OFFSET $off");
        $q->execute($par); $rows = $q->fetchAll(); $ids = array_map(fn($r) => (int)$r['id'], $rows); $fu = [];
        if ($ids) { foreach ($pdo->query("SELECT DISTINCT upload_id FROM convo_messages WHERE src = 'chat' AND who = 'sales' AND stage = 'followup' AND upload_id IN (" . implode(',', $ids) . ")")->fetchAll(PDO::FETCH_COLUMN) as $i) $fu[(int)$i] = 1; }
