            foreach ($pq->fetchAll() as $p) if (isset($names[(int)$p['employee_id']])) $people[] = ['id' => (int)$p['employee_id'], 'name' => $names[(int)$p['employee_id']], 'n' => (int)$p['n']]; }
        json_response(['list' => $list, 'counts' => ['all' => (int)$cnt['a'], 'ordered' => (int)$cnt['o'], 'lost' => (int)$cnt['l'], 'calls' => (int)$cnt['c']], 'people' => $people, 'more' => count($rows) === $lim]);
