    case 'lib.tick': {
        // The hourly study pass: reads old chats into the library, and writes a new draft guidebook when one is due. GET = the page's quiet hourly call (answers first, works after); POST = "Study now".
        $auth = require_auth(); lib_guard($pdo, $auth);
