            $every = $backlog > 0 ? max(300, (int)tmph_cfg('LIB_TICK_EVERY', 600)) : 3000;       // while old chats are waiting: a pass every 10 minutes (config LIB_TICK_EVERY, seconds); otherwise hourly
            if (time() - (int)($lt['at'] ?? 0) < $every) json_response(['skipped' => true]);
            register_shutdown_function(function () {
                global $pdo; ignore_user_abort(true); @set_time_limit(280);
                if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request(); elseif (function_exists('litespeed_finish_request')) @litespeed_finish_request();
                try { lib_tick_run($pdo, max(1, min(60, (int)tmph_cfg('LIB_TICK_BATCH', 24))), 240); } catch (Throwable $e) { error_log('lib.tick: ' . $e->getMessage()); }
            });
            json_response(['started' => true]);
        }
        $r = lib_tick_run($pdo, 8, 200);
