        $grp = (string)($_GET['grp'] ?? 'ad'); if (!in_array($grp, ['ad', 'lost', 'price', 'gift', 'cod', 'all', 'own', 'weak', 'facts'], true)) $grp = 'ad';
        $n = max(1, min(30, (int)($_GET['n'] ?? 12)));
        $ex = array_flip(array_filter(array_map(fn($x) => preg_replace('/[^a-f0-9]/', '', $x), explode(',', (string)($_GET['ex'] ?? '')))));
        $done = []; $st = ['taught' => 0, 'fine' => 0, 'lessons' => 0]; $ownN = 0;
