        if (!lib_guide_row($pdo, 'live')) json_response(['error' => 'Approve a guidebook first.'], 422);
        $n = max(1, min(20, (int)($_GET['n'] ?? 10))); $nl = (int)ceil($n * 0.4); $got = ['lost' => [], 'order' => []];
        foreach (['lost' => $nl, 'order' => $n] as $kind => $want) {
            foreach (lib_sample_ids($pdo, $kind, 60, 0, 4) as $i) {
                if (lib_replay_points(lib_turns($pdo, $i), $kind === 'lost')) $got[$kind][] = $i;
                if (count($got[$kind]) >= $want) break;
            }
        }
        $lostIds = array_slice($got['lost'], 0, $nl); $ids = array_merge($lostIds, array_slice($got['order'], 0, $n - count($lostIds))); shuffle($ids);
        if (!$ids) json_response(['error' => 'No saved chats with a transcript yet — press “Study now” first.'], 422);
        json_response(['run_id' => date('ymdHis') . substr(md5(uniqid('', true)), 0, 6), 'ids' => $ids]);
        break;
    }

    case 'lib.replay_case': {
        // One replay: the customer's real message (or a quiet customer to follow up) → the bot's reply → a judge compares it with what our salesperson really wrote.
        // In a LOST chat the question is: would the bot have done better than our salesperson, who did not win?
        $auth = require_auth(); lib_guard($pdo, $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input(); $cid = (int)($in['chat_id'] ?? 0); $run = preg_replace('/[^a-z0-9]/i', '', (string)($in['run_id'] ?? ''));
        $liveR = lib_guide_row($pdo, 'live'); if (!$liveR) json_response(['error' => 'Approve a guidebook first.'], 422);
        $live = lib_guide_public($liveR);
        $up = convo_get($pdo, $cid); if (!$up || !in_array($up['kind'], ['order', 'lost'], true)) json_response(['error' => 'Chat not found.'], 404);
        $isLost = $up['kind'] === 'lost';
        $t = lib_turns($pdo, $cid); $pts = lib_replay_points($t, $isLost);
        if (!$pts) json_response(['error' => 'This chat has no moment that can be replayed.'], 422);
        [$k, $type] = $pts[array_rand($pts)]; $msgs = [];
        foreach (array_slice($t, max(0, $k - 12), min(12, $k)) as $x) $msgs[] = ['who' => $x['who'] === 'customer' ? 'customer' : 'bot', 'text' => $x['text']];
        $cust = ''; for ($j = $k - 1; $j >= 0; $j--) if ($t[$j]['who'] === 'customer') { $cust = $t[$j]['text']; break; }
        $real = $t[$k]['text'];
        ignore_user_abort(true); @set_time_limit(150);
        [$ok, $b, $why] = lib_bot_reply($pdo, $live['body'], $msgs, $cid, $type === 'followup');      // this chat is hidden from the bot
        if (!$ok) json_response(['error' => $why], 502);
        $sys = "You judge a perfume-sales chatbot for TM Perfume House (India). The same moment of a real chat was handled by our real salesperson and by the bot. Judge only the reply, in context. "
            . ($isLost ? "IMPORTANT: this chat was LOST — the customer did not order — so our salesperson's reply is NOT proof of a good reply. better = the bot's reply is more likely to keep or win this customer than our salesperson's reply was. "
                       : "This chat was WON (became an order). better = the bot's reply is more likely to win the order than our salesperson's (helpful, right language and tone, right next step, no invented price / offer / fact). ")
            . ($type === 'followup' ? "This moment is a FOLLOW-UP: the customer had not answered our last message. A good follow-up gives a reason to reply and is not a copy of the last message. " : "")
            . "same = about equally good. worse = less likely to win, OR it invents prices / offers / facts, uses the wrong language, or ignores that a person should take over. why = one short English sentence.";
        $sch = ['type' => 'OBJECT', 'properties' => ['verdict' => ['type' => 'STRING', 'enum' => ['better', 'same', 'worse']], 'why' => ['type' => 'STRING']], 'required' => ['verdict', 'why']];
        $ctx = ''; foreach ($msgs as $m) $ctx .= ($m['who'] === 'customer' ? 'Customer: ' : 'Salesperson: ') . $m['text'] . "\n";
        [$ok2, $j, $why2] = convo_ai($sys, [['text' => "CONVERSATION BEFORE:\n$ctx\n" . ($type === 'followup' ? "THE CUSTOMER HAS NOT ANSWERED.\n" : "CUSTOMER'S MESSAGE:\n$cust\n") . "\nOUR SALESPERSON'S REAL " . ($type === 'followup' ? 'FOLLOW-UP' : 'REPLY') . ":\n$real\n\nBOT'S " . ($type === 'followup' ? 'FOLLOW-UP' : 'REPLY') . ":\n" . $b['reply']]], $sch, false, 800, 'claude');
        if (!$ok2) json_response(['error' => $why2], 502);
        $verdict = in_array($j['verdict'] ?? '', ['better', 'same', 'worse'], true) ? $j['verdict'] : 'same';
        $jw = ($isLost ? 'LOST chat · ' : '') . ($type === 'followup' ? 'follow-up · ' : '') . mb_substr(trim((string)($j['why'] ?? '')), 0, 280);
        $shown = ($type === 'followup' ? '(no answer yet — follow-up) ' : '') . lib_clip($cust, 560);
        $pdo->prepare("INSERT INTO lib_replay (run_id, chat_id, guide_version, customer, real_reply, bot_reply, verdict, why, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW())")
            ->execute([mb_substr($run, 0, 30), $cid, (int)$live['version'], $shown, lib_clip($real, 900), $b['reply'], $verdict, $jw]);
        json_response(['chat_id' => $cid, 'guide_version' => (int)$live['version'], 'customer' => $shown, 'real' => lib_clip($real, 900), 'bot' => $b['reply'], 'verdict' => $verdict, 'why' => $jw]);
        break;
    }

    case 'lib.replay_list': {
        // The last replay test of the live guidebook
        $auth = require_auth(); lib_guard($pdo, $auth);
        $live = lib_guide_row($pdo, 'live'); if (!$live) json_response(['rows' => []]);
        $q = $pdo->prepare("SELECT run_id FROM lib_replay WHERE guide_version = ? ORDER BY id DESC LIMIT 1"); $q->execute([(int)$live['version']]); $run = (string)$q->fetchColumn();
        if ($run === '') json_response(['rows' => []]);
        $q = $pdo->prepare("SELECT * FROM lib_replay WHERE run_id = ? ORDER BY id"); $q->execute([$run]);
        json_response(['rows' => array_map(fn($r) => ['chat_id' => (int)$r['chat_id'], 'version' => (int)$r['guide_version'], 'customer' => $r['customer'], 'real' => $r['real_reply'], 'bot' => $r['bot_reply'], 'verdict' => $r['verdict'], 'why' => $r['why']], $q->fetchAll())]);
        break;
    }

    case 'addon.ai': {
        // ➕ Add-on coach inside the ratings. Without ?run=1 it only returns what is saved; with run=1 it works it out again when older than 90 min (or ?force=1).
        $auth = require_auth();
        if (!orders_page_controls($auth) && !ct_admin_ok($pdo, $auth)) require_role(['Admin', 'HR'], $auth);
        $c = json_decode((string)setting_get($pdo, 'addon_ai', ''), true); $age = is_array($c) && !empty($c['at']) ? time() - strtotime((string)$c['at']) : PHP_INT_MAX;
        if (is_array($c)) $c['people'] = (object)($c['people'] ?? []);
        if (empty($_GET['run'])) { if (!is_array($c)) json_response(['ready' => false, 'stale' => true]); $c['ready'] = true; $c['stale'] = $age > 5400; json_response($c); }
        if (is_array($c) && $age < 5400 && empty($_GET['force'])) { $c['ready'] = true; $c['stale'] = false; json_response($c); }
        ignore_user_abort(true); @set_time_limit(150);
        $x = addon_build($pdo);
