    // ============================ Control Tower · Message Doctor · learning ideas · theme ============================
    case 'ct.pulse': {
        // Small badge feed for Admin pages (open red / warn / meet-admin counts). Also runs the 5-minute pass.
        $auth = require_auth();
        if (!ensure_ct_tables($pdo)) json_response(['error' => 'Could not prepare the Control Tower tables.'], 500);
        $theme = ct_theme($pdo);
        if (!ct_admin_ok($pdo, $auth)) json_response(['admin' => false, 'theme' => $theme]);
        $run = ct_run($pdo, false);
        $r = $pdo->query("SELECT SUM(severity = 'red') AS red, SUM(severity = 'warn') AS warn, SUM(meet_admin = 1) AS meet, COUNT(*) AS n FROM ct_alerts WHERE status = 'open' AND kind <> 'digest'")->fetch();
        json_response(['admin' => true, 'red' => (int)$r['red'], 'warn' => (int)$r['warn'], 'meet' => (int)$r['meet'], 'open' => (int)$r['n'], 'theme' => $theme, 'run' => $run]);
        break;
    }

    case 'ct.tower': {
        // The Control Tower page: goals vs reality for a business day (?date=), the open alerts, benchmarks.
        $auth = require_auth();
        if (!ct_admin_ok($pdo, $auth)) json_response(['error' => 'The Control Tower is for Admin / HR.'], 403);
        if (!ensure_ct_tables($pdo)) json_response(['error' => 'Could not prepare the Control Tower tables.'], 500);
        @set_time_limit(120);
        $today = biz_today($pdo); $day = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['date'] ?? '')) ? (string)$_GET['date'] : $today;
        if ($day === $today) ct_run($pdo, isset($_GET['refresh']));
        $S = ct_snapshot($pdo, $day);
        $q = $pdo->prepare("SELECT * FROM ct_alerts WHERE (day = ? OR status = 'open') AND status IN ('open', 'resolved') ORDER BY (status = 'open') DESC, meet_admin DESC, FIELD(severity, 'red', 'warn', 'info'), id DESC LIMIT 120"); $q->execute([$day]);
        $unm = [];          // older resolves stored the login name — show the person's full name for those too
        try { foreach ($pdo->query("SELECT u.username, e.full_name FROM users u JOIN employees e ON e.employee_id = u.employee_id")->fetchAll() as $ur) $unm[strtolower((string)$ur['username'])] = trim((string)$ur['full_name']); } catch (Throwable $e) {}
        $alerts = array_map(fn($r) => ['id' => (int)$r['id'], 'kind' => $r['kind'], 'sev' => $r['severity'], 'emp' => (int)$r['employee_id'], 'day' => $r['day'], 'title' => $r['title'], 'body' => $r['body'],
            'meet' => (int)$r['meet_admin'] === 1, 'status' => $r['status'], 'created_at' => $r['created_at'], 'resolved_by' => ($unm[strtolower((string)$r['resolved_by'])] ?? '') !== '' ? $unm[strtolower((string)$r['resolved_by'])] : $r['resolved_by'], 'resolved_at' => $r['resolved_at'], 'note' => $r['note']], $q->fetchAll());
        $emps = array_values($S['emps']);
        usort($emps, fn($a, $b) => ($b['orders'] <=> $a['orders']) ?: strcmp((string)$a['name'], (string)$b['name']));
        $S['team'] = array_merge($S['team'], ct_roas_block($pdo, $day, $day === $today, get_bearer_token(), (float)$S['team']['sales'], (float)($S['cfg']['roas_goal'] ?? 3)));
        json_response(['day' => $day, 'today' => $today, 'now' => $S['now'], 'team' => $S['team'], 'emps' => $emps, 'alerts' => $alerts, 'cfg' => $S['cfg'], 'theme' => ct_theme($pdo),
            'leaders' => ct_leaders($pdo, $S, $day), 'can_settings' => convo_is_admin($auth), 'names' => array_map(fn($e) => ['id' => $e['id'], 'name' => $e['name']], $emps)]);
        break;
    }

    case 'ct.benchmarks': {
        $auth = require_auth();
