        @set_time_limit(120);
        json_response(ct_benchmarks($pdo));
        break;
    }

    case 'ct.resolve': {
        // "Resolved" for an alert — Admin / HR, or one of the named resolvers (Control Tower → Settings). Body: {id, note?}
        $auth = require_auth();
        if (!ct_admin_ok($pdo, $auth)) json_response(['error' => 'Only Admin / HR or a named resolver can mark this resolved.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_ct_tables($pdo);
        $in = json_input(); $id = (int)($in['id'] ?? 0);
        if (mb_strlen(trim((string)($in['note'] ?? ''))) < 3) json_response(['error' => 'Please write a comment (what you did) to mark this resolved.'], 422);
        $who = (string)($auth['username'] ?? 'admin');
        if (!empty($auth['employee_id'])) {          // show the person's FULL NAME on the alert ("Dipti Patel"), not the login name
            try { $fq = $pdo->prepare("SELECT full_name FROM employees WHERE employee_id = ?"); $fq->execute([(int)$auth['employee_id']]); $fn = trim((string)$fq->fetchColumn()); if ($fn !== '') $who = mb_substr($fn, 0, 95); } catch (Throwable $e) {}
        }
        $pdo->prepare("UPDATE ct_alerts SET status = 'resolved', resolved_at = NOW(), resolved_by = ?, note = ? WHERE id = ? AND status = 'open'")->execute([$who, mb_substr(trim((string)($in['note'] ?? '')), 0, 300), $id]);
        // a resolved "meet admin" also clears that person's behaviour counters, so they start fresh
        $r = $pdo->prepare("SELECT kind, employee_id FROM ct_alerts WHERE id = ?"); $r->execute([$id]); $a = $r->fetch();
        if ($a && (int)$a['employee_id'] > 0) {
            if ($a['kind'] === 'meet_dup') ct_behavior_set($pdo, (int)$a['employee_id'], 'dup', 0);
        }
        json_response(['ok' => true]);
        break;
    }

    case 'ct.focus': {
        // ☀️ Morning Focus: each salesperson's 1–2 things to work on today (built from yesterday), who already talked and what moved. Admin / HR / resolvers.
        $auth = require_auth();
        if (!ct_admin_ok($pdo, $auth)) json_response(['error' => 'The Control Tower is for Admin / HR.'], 403);
        if (!ensure_ct_tables($pdo)) json_response(['error' => 'Could not prepare the Control Tower tables.'], 500);
        $day = biz_today($pdo);
        try { ct_focus_build($pdo, $day); } catch (Throwable $e) { error_log('ct_focus_build: ' . $e->getMessage()); }
        $emps = rating_emps($pdo);
        $q = $pdo->prepare("SELECT * FROM ct_focus WHERE day = ?"); $q->execute([$day]);
        $rows = []; $order = ['talk' => 0, 'check' => 1, 'praise' => 2];
        foreach ($q->fetchAll() as $r) {
            $id = (int)$r['employee_id'];
            $rows[] = ['id' => $id, 'name' => isset($emps[$id]) ? trim((string)$emps[$id]['full_name']) : ('#' . $id), 'grp' => $r['grp'], 'score' => $r['score'] !== null ? (float)$r['score'] : null, 'prev' => $r['prev_score'] !== null ? (float)$r['prev_score'] : null,
                'items' => json_decode((string)$r['items'], true) ?: [], 'progress' => json_decode((string)$r['progress'], true) ?: [], 'done' => $r['status'] === 'done', 'done_by' => $r['done_by'], 'done_at' => $r['done_at'], 'note' => $r['note']];
        }
        usort($rows, fn($a, $b) => (($order[$a['grp']] ?? 9) <=> ($order[$b['grp']] ?? 9)) ?: (($a['score'] ?? 0) <=> ($b['score'] ?? 0)));
        $sc = array_values(array_filter(array_column($rows, 'score'), fn($v) => $v !== null));
        $pa = []; $pn = [];
        foreach ($rows as $r) foreach ($r['items'] as $it) if (isset($it['k']) && !in_array($it['k'], ['praise', 'conv'], true)) { $pa[$it['k']] = ($pa[$it['k']] ?? 0) + $it['val']; $pn[$it['k']] = ($pn[$it['k']] ?? 0) + 1; }
        $weak = null; foreach ($pa as $k => $v) { $a = $v / $pn[$k]; if ($pn[$k] >= 2 && ($weak === null || $a < $weak['avg'])) $weak = ['k' => $k, 'label' => rating_parts()[$k]['label'] ?? $k, 'avg' => round($a, 1), 'n' => $pn[$k]]; }
        json_response(['day' => $day, 'for' => date('Y-m-d', strtotime($day . ' -1 day')), 'rows' => $rows,
            'team' => ['avg' => $sc ? round(array_sum($sc) / count($sc), 1) : null, 'weak' => $weak, 'total' => count($rows), 'done' => count(array_filter($rows, fn($r) => $r['done'])),
                'talk' => count(array_filter($rows, fn($r) => $r['grp'] === 'talk')), 'praise' => count(array_filter($rows, fn($r) => $r['grp'] === 'praise'))]]);
        break;
    }

