        $num = fn($v, $lo, $hi) => max($lo, min($hi, (float)$v));
        foreach (['q_conv_goal' => [5, 80], 'roas_goal' => [0.5, 20], 'comm_target' => [1, 2000], 'big_order' => [500, 100000], 'ticket_min_orders' => [1, 50], 'q_warn_pct' => [10, 100], 'q_red_pct' => [5, 100],
            'mix_goal' => [10, 100], 'mix_amber' => [10, 100], 'mix_red' => [5, 100], 'mix_min_pieces' => [1, 200]] as $k => [$lo, $hi]) if (array_key_exists($k, $in)) $cur[$k] = $num($in[$k], $lo, $hi);
        if (isset($in['ticket_steps']) && is_array($in['ticket_steps'])) { $st = array_values(array_filter(array_map('floatval', $in['ticket_steps']), fn($x) => $x > 0)); sort($st); if ($st) $cur['ticket_steps'] = array_slice($st, 0, 6); }
