            $cc = []; foreach ($in['comm_checks'] as $x) if (is_array($x) && preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', (string)($x[0] ?? '')) && (int)($x[1] ?? 0) > 0) $cc[] = [(string)$x[0], (int)$x[1]];
            if ($cc) $cur['comm_checks'] = array_slice($cc, 0, 8);
        }
