        if (isset($in['resolvers']) && is_array($in['resolvers'])) $cur['resolvers'] = array_values(array_unique(array_filter(array_map('intval', $in['resolvers']))));
        if (isset($in['meet']) && is_array($in['meet'])) $cur['meet'] = array_values(array_map(fn($m) => ['id' => (string)($m['id'] ?? ''), 'on' => !empty($m['on']) ? 1 : 0, 'v1' => (float)($m['v1'] ?? 0), 'v2' => (float)($m['v2'] ?? 0)], array_filter($in['meet'], fn($m) => is_array($m) && !empty($m['id']))));
        if (isset($in['md']) && is_array($in['md'])) foreach (['min_uses' => [2, 100], 'ignore_days' => [1, 30], 'weak_reply' => [5, 60], 'min_chats_section' => [3, 200]] as $k => [$lo, $hi]) if (isset($in['md'][$k])) $cur['md'][$k] = $num($in['md'][$k], $lo, $hi);
        if (isset($in['ideas']) && is_array($in['ideas'])) foreach (['after_days' => [0, 14], 'rigid_days' => [1, 14]] as $k => [$lo, $hi]) if (isset($in['ideas'][$k])) $cur['ideas'][$k] = $num($in['ideas'][$k], $lo, $hi);
        if (isset($in['outcome_weights']) && is_array($in['outcome_weights'])) foreach (['conv', 'ticket', 'speed', 'volume'] as $k) if (isset($in['outcome_weights'][$k])) $cur['outcome_weights'][$k] = $num($in['outcome_weights'][$k], 0, 100);
        if (isset($in['theme']) && in_array($in['theme'], ['on', 'off', 'auto'], true)) $cur['theme'] = $in['theme'];
        foreach (['theme_from', 'theme_to'] as $k) if (isset($in[$k]) && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$in[$k])) $cur[$k] = (string)$in[$k];
        setting_set($pdo, 'ct_cfg', json_encode($cur, JSON_UNESCAPED_UNICODE));
        json_response(['ok' => true, 'theme' => (function () use ($pdo, $cur) { $c = ct_cfg_default(); foreach ($cur as $k => $v) $c[$k] = $v; $on = $c['theme'] === 'on' || ($c['theme'] === 'auto' && date('Y-m-d') >= $c['theme_from'] && date('Y-m-d') <= $c['theme_to']); return ['on' => $on, 'mode' => $c['theme']]; })()]);
