    case 'ct.remark_send': {
        // The sales head's remark to a salesperson (from the Focus card, the Ratings person or the Rudra sheet). It pops up on My Sales until "Got it". Body: {employee_id, text, src}
        $auth = require_auth();
        if (!qb_ok($pdo, $auth)) json_response(['error' => 'Only Admin / HR or a named resolver can send a remark.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_ct_tables($pdo);
        $in = json_input(); $emp = (int)($in['employee_id'] ?? 0); $text = mb_substr(trim((string)($in['text'] ?? '')), 0, 400);
        $src = in_array(($in['src'] ?? ''), ['focus', 'rating', 'rudra', 'remind', 'today', 'orders'], true) ? $in['src'] : 'focus';
        if ($emp <= 0) json_response(['error' => 'Pick a person.'], 422);
        if (mb_strlen($text) < 3) json_response(['error' => 'Write the remark first.'], 422);
        [$fromEmp, $who] = ct_who($pdo, $auth);
        $pdo->prepare("INSERT INTO ct_remarks (employee_id, from_emp, from_name, src, body, created_at) VALUES (?, ?, ?, ?, ?, NOW())")->execute([$emp, $fromEmp, $who, $src, $text]);
