                foreach ($orq->fetchAll() as $r) $rows[] = ['id' => 'o' . (int)$r['id'], 'from' => (string)$r['author'], 'body' => 'Order ' . ((string)$r['order_name'] !== '' ? $r['order_name'] : '#' . $r['order_id']) . ': ' . (string)$r['note'], 'at' => substr((string)$r['created_at'], 0, 16), 'seen' => true];
