    case 'cq.list': {
        // Give queries → 📣 Campaign: per person, three kinds of campaign / community queries — 'in' (already in her chat), 'new' (new query assigned), 'comm' (community query) —
        // and the community / campaign orders of each kind (orders are tagged with their kind on the Campaign tab). ?date=&days=1|7
        $auth = require_auth();
        if (!qb_ok($pdo, $auth)) json_response(['error' => 'Not allowed.'], 403);
        $date = trim((string)($_GET['date'] ?? '')); if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) $date = biz_today($pdo);
        if (!ensure_cq_table($pdo)) json_response(['error' => 'Could not prepare the campaign table.'], 500);
        @set_time_limit(90);
        $people = qb_people($pdo); $m = [];
        $days = max(1, min(7, (int)($_GET['days'] ?? 1))); $dFrom = date('Y-m-d', strtotime($date . ' -' . ($days - 1) . ' day'));
        $m = qa_cq_range($pdo, $dFrom, $date);          // old typed counts before the cut-over date, WhatsApp Sales (by kind) from it
        $oc = []; $untag = 0;
