        $pc = fn($o, $q) => $q > 0 ? round($o / $q * 100, 1) : null;
        $mvR = qm_range($pdo, $dFrom, $date); $rsc = qm_rescued_comm($pdo, $dFrom, $date); $TA = ['in' => 0, 'new' => 0, 'comm' => 0];
        $list = []; $T = ['in' => 0, 'new' => 0, 'comm' => 0, 'o_in' => 0, 'o_new' => 0, 'o_comm' => 0, 'o_un' => 0];
        foreach ($people as $id => $nm) {
            $in = (int)($m[$id]['in'] ?? 0); $nw = (int)($m[$id]['new'] ?? 0); $cm = (int)($m[$id]['comm'] ?? 0); $t = $in + $nw + $cm;
            $adj = ['in' => $in, 'new' => $nw, 'comm' => $cm]; $mvx = [];      // ⇄ moved queries: waived ones leave the giver's count, a received one counts for the receiver only when it ordered (↪)
            foreach (['in', 'new', 'comm'] as $kk) {
                $ou = (int)($mvR[$id]['out'][$kk] ?? 0); $w = (int)($mvR[$id]['out_w'][$kk] ?? 0); $inn = (int)($mvR[$id]['in'][$kk] ?? 0); $rs = min((int)($rsc[$id][$kk] ?? 0), $inn);
                $adj[$kk] = max(0, $adj[$kk] - $w + $rs); if ($ou || $inn) $mvx[$kk] = ['out' => $ou, 'w' => $w, 'in' => $inn, 'res' => $rs];
            }
            $oi = (int)($oc[$id]['in'] ?? 0); $on = (int)($oc[$id]['new'] ?? 0); $ocm = (int)($oc[$id]['comm'] ?? 0); $ou = (int)($oc[$id]['un'] ?? 0); $o = $oi + $on + $ocm + $ou;
            $list[] = ['id' => $id, 'name' => $nm, 'in' => $in, 'new' => $nw, 'comm' => $cm, 'total' => $t, 'orders' => $o, 'conv' => $pc($o, $adj['in'] + $adj['new'] + $adj['comm']), 'mv' => (object)$mvx,
                'o_in' => $oi, 'o_new' => $on, 'o_comm' => $ocm, 'o_un' => $ou, 'c_in' => $pc($oi, $adj['in']), 'c_new' => $pc($on, $adj['new']), 'c_comm' => $pc($ocm, $adj['comm'])];
            $TA['in'] += $adj['in']; $TA['new'] += $adj['new']; $TA['comm'] += $adj['comm'];
