        else $pdo->prepare("INSERT INTO order_qsrc (source, order_id, qsrc, updated_by, updated_at) VALUES (?, ?, ?, ?, NOW()) ON DUPLICATE KEY UPDATE qsrc = VALUES(qsrc), updated_by = VALUES(updated_by), updated_at = NOW()")->execute([$source, $oid, $qs, mb_substr((string)($auth['username'] ?? ''), 0, 95)]);
