    case 'qm.move': {
        // ⇄ Move queries. Body {kind: fresh|in|new|comm, from, to, n, reason: slow|nofollow|suspect|workload|asked, waive: 0|1, date?}. Y keeps the queries unless waive = 1; Z is never blamed for them.
        $auth = require_auth();
