            $worst = ''; $worstQ = 0;
            if ($cTeam !== null && (int)$e['cq'] >= 10 && $e['cq_conv'] !== null && (float)$e['cq_conv'] < $cTeam * 0.6) {
                foreach (['new', 'comm', 'in'] as $kk) { $qq = (int)$e['cq_' . $kk]; if ($qq >= 5 && $qq > $worstQ && (int)$e['co_' . $kk] * 3 < $qq) { $worst = $kk; $worstQ = $qq; } }
                $why[] = ['k' => 'camp', 'txt' => 'campaign ' . round((float)$e['cq_conv']) . '% vs team ' . round((float)$cTeam) . '% over ' . $e['cq'] . ' campaign queries' . (!empty($e['camp_weak']) ? ' · query ratio strong' : '')];
