    case 'ct.history': {
        // Today tab → "Last days": orders + collection of the last 7 business days (10 AM → 10 AM), split Query / Campaign, per hour, and "same time" totals.
        // The numbers come from the same allocated sales the Today tab uses, so the collections match. Cheap: ONE load for all 7 days.
        $auth = require_auth();
        if (!qb_ok($pdo, $auth)) json_response(['error' => 'Not allowed.'], 403);
        @set_time_limit(90);
        $today = biz_today($pdo); $end = trim((string)($_GET['date'] ?? '')); if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $end) || $end > $today) $end = $today;
        $isToday = $end === $today; $from = date('Y-m-d', strtotime($end . ' -6 day'));
        // Seven days of orders are rebuilt from scratch for this box, and the page asks every minute: keep the answer for a short while
        // (45 s for today, 10 min for an older day). "Refresh" on the page sends fresh=1 to rebuild at once.
        $cf = sys_get_temp_dir() . '/hrms_cthist_' . md5(__FILE__) . '_' . $end . '.json'; $ttl = $isToday ? 45 : 600;
        if (empty($_GET['fresh']) && is_file($cf) && time() - (int)@filemtime($cf) < $ttl) {
            $hit = json_decode((string)@file_get_contents($cf), true);
            if (is_array($hit) && isset($hit['days'])) { $hit['cached'] = true; json_response($hit); }
        }
        $emps = rating_emps($pdo);
        $sale = coach_sales_load($pdo, $emps, $from, $end);
        $comm = [];
        if (ensure_order_community_table($pdo)) { try { foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $r) $comm[$r['source'] . '|' . $r['order_id']] = 1; } catch (Throwable $e) {} }
        $startOf = fn(string $d) => ct_clock_ts($pdo, $d, substr(day_start_for($pdo, $d), 0, 5));
        $nowTs = $isToday ? time() : $startOf($end) + 86400;
        $elapsed = max(0, $nowTs - $startOf($end));
        $out = [];
        for ($k = 0; $k < 7; $k++) {
            $d = date('Y-m-d', strtotime($end . " -$k day"));
            $seq = biz_hour_sequence($pdo, $d); $pos = array_flip($seq);
            $hrs = array_fill(0, 24, [0, 0.0]);
            $T = ['orders' => 0, 'sales' => 0.0, 'qo' => 0, 'co' => 0, 'qs' => 0.0, 'cs' => 0.0, 'same_n' => 0, 'same_s' => 0.0];
            $cut = $startOf($d) + $elapsed;
            foreach ($sale as $key => $list) {
                if (substr($key, 0, 10) !== $d) continue;
                foreach ($list as $x) {
                    $amt = (float)$x['amt']; $isComm = isset($comm[$x['key']]) || ($x['type'] ?? '') === 'campaign';
                    $T['orders']++; $T['sales'] += $amt;
                    if ($isComm) { $T['co']++; $T['cs'] += $amt; } else { $T['qo']++; $T['qs'] += $amt; }
                    $i = $pos[(int)date('G', (int)$x['ts'])] ?? null; if ($i !== null) { $hrs[$i][0]++; $hrs[$i][1] += $amt; }
                    if ((int)$x['ts'] <= $cut) { $T['same_n']++; $T['same_s'] += $amt; }
                }
