            $out[] = ['day' => $d, 'dow' => date('D j M', strtotime($d)), 'orders' => $T['orders'], 'sales' => round($T['sales']), 'ticket' => $T['orders'] ? round($T['sales'] / $T['orders']) : 0,
                'qo' => $T['qo'], 'co' => $T['co'], 'qs' => round($T['qs']), 'cs' => round($T['cs']), 'same_n' => $T['same_n'], 'same_s' => round($T['same_s']),
                'h' => array_map(fn($v) => [$v[0], round($v[1])], $hrs)];
        }
        $seqNow = biz_hour_sequence($pdo, $end); $nowIdx = $isToday ? array_search((int)date('G'), $seqNow, true) : 23;
        $payload = ['today' => $today, 'date' => $end, 'is_today' => $isToday, 'now' => date('H:i', $nowTs), 'now_idx' => $nowIdx === false ? 23 : (int)$nowIdx, 'hours' => $seqNow, 'days' => $out, 'at' => date('H:i')];
        @file_put_contents($cf, json_encode($payload));
