        if (!convo_is_admin($auth)) { $st['rows'] = array_values(array_filter($st['rows'], fn($r) => $r['active'])); unset($st['found']); }
        json_response($st + ['admin' => convo_is_admin($auth)]);
        break;
    }

    case 'premsg.save': {
        // Admin: add / edit a pre-message. Body: {id?, kind: reply|broadcast, title, body, active}
        $auth = require_auth();
        if (!convo_is_admin($auth)) require_role(['Admin', 'HR'], $auth);
        ensure_premsg_table($pdo);
        $in = json_decode(file_get_contents('php://input'), true) ?: [];
        $title = mb_substr(trim((string)($in['title'] ?? '')), 0, 80); $body = mb_substr(trim((string)($in['body'] ?? '')), 0, 2000);
        if ($body === '') json_response(['error' => 'Write the message text.'], 422);
        if ($title === '') $title = mb_substr(preg_replace('/\s+/', ' ', $body), 0, 40);
        $kind = ($in['kind'] ?? 'reply') === 'broadcast' ? 'broadcast' : 'reply'; $active = !isset($in['active']) || !empty($in['active']) ? 1 : 0;
        $id = (int)($in['id'] ?? 0);
        if ($id) $pdo->prepare("UPDATE pre_messages SET kind = ?, title = ?, body = ?, active = ?, updated_at = NOW() WHERE id = ?")->execute([$kind, $title, $body, $active, $id]);
        else { $pdo->prepare("INSERT INTO pre_messages (kind, title, body, active, source, created_at, updated_at) VALUES (?, ?, ?, ?, ?, NOW(), NOW())")->execute([$kind, $title, $body, $active, !empty($in['from_ai']) ? 'ai' : 'admin']); $id = (int)$pdo->lastInsertId(); }
        json_response(['id' => $id]);
        break;
    }

    case 'premsg.delete': {
        $auth = require_auth();
        if (!convo_is_admin($auth)) require_role(['Admin', 'HR'], $auth);
        ensure_premsg_table($pdo);
        $in = json_decode(file_get_contents('php://input'), true) ?: [];
        $pdo->prepare("DELETE FROM pre_messages WHERE id = ?")->execute([(int)($in['id'] ?? 0)]);
        json_response(['ok' => true]);
        break;
    }

    case 'coach.team': {
        // Orders page "Team coach" box (Admin / HR / Orders page access): every Sales employee's pace, ranks, coaching flags and how
        // often each tip was already shown to them today (from coach_log). ?date=YYYY-MM-DD (a past day = final figures).
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        $day = (string)($_GET['date'] ?? '');
        $today = biz_today($pdo);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $day) || $day > $today) $day = $today;
        $c = coach_day($pdo, $day);
        $shown = [];
        try { $q = $pdo->prepare("SELECT employee_id, tip, shown FROM coach_log WHERE log_day = ?"); $q->execute([$day]); foreach ($q->fetchAll() as $r) $shown[(int)$r['employee_id']][$r['tip']] = (int)$r['shown']; } catch (PDOException $e) {}
        $rows = [];
        $chatNow = convo_stats($pdo, date('Y-m-d H:i:s', time() - 7 * 86400));      // chat score of the last 7 days
        foreach ($c['emps'] as $id => $m) {
            $tips = array_merge(coach_tips($m, $c['team'], (float)($m['bonus'] ?? $c['bonus']), $c['floor']), $day === $today ? convo_tips($pdo, (int)$id, $c['emps']) : []);
            foreach ($tips as &$t) $t['shown'] = $shown[$id][$t['k']] ?? 0; unset($t);
            $idle = ($day === $today && $m['target'] > 0 && $m['sales'] < $m['target'])
                ? ($m['last_order'] ? (time() - strtotime($m['last_order'])) / 3600 : (time() - strtotime($day . ' ' . day_start_for($pdo, $day) . ':00')) / 3600) : 0;
            unset($m['order_com']);
            $cs = $chatNow[$id] ?? null;
            $rows[] = $m + ['tips' => $tips, 'idle_h' => round(max(0, $idle), 1), 'goal' => coach_goal($m), 'chat' => $cs ? ['n' => $cs['n'], 'avg' => $cs['avg']['overall'] ?? null, 'calls' => $cs['calls'], 'call_avg' => $cs['avg']['call_overall'] ?? null] : null];
        }
        json_response(['date' => $day, 'today' => $day === $today, 'bonus' => $c['bonus'], 'floor' => $c['floor'], 'team' => $c['team'], 'rows' => $rows]);
        break;
    }

    case 'my.coach': {
        // My Sales page, top: today's pace (ahead / behind of time), ranks and EVERY coaching tip that applies. See coach_day().
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $myId = (int)$auth['employee_id'];
        $bizDay = biz_today($pdo);
        $c = coach_day($pdo, $bizDay);
        $m = $c['emps'][$myId] ?? null;
        if (!$m) json_response(['business_day' => $bizDay, 'me' => null]);
        $tips = array_merge(coach_tips($m, $c['team'], (float)($m['bonus'] ?? $c['bonus']), $c['floor']), convo_tips($pdo, $myId, $c['emps']));   // + what the chat / call reviews say
        // Today's small wins so far (badges) + the next step.
        $won = [];
        if ($m['orders'] >= 1) $won[] = ['🌅', 'First order'];
        if ($m['orders'] >= 3) $won[] = ['🎩', 'Hat-trick'];
        if ($m['orders'] >= 5) $won[] = ['✋', 'High five'];
        for ($k = 10; $k <= $m['orders']; $k += 5) $won[] = ['🔥', $k . ' orders club'];
        if ($m['target'] > 0 && $m['sales'] >= $m['target'] / 2) $won[] = ['🌓', 'Half target'];
        if ($m['target'] > 0 && $m['sales'] >= $m['target']) $won[] = ['🏆', 'Target done'];
        if ($m['yest_same'] > 0 && $m['sales'] > $m['yest_same']) $won[] = ['📈', 'Beat yesterday'];
        if ($m['best_day'] > 0 && $m['sales'] > $m['best_day']) $won[] = ['🏅', 'Personal best day'];
        if ($m['streak'] >= 2) $won[] = ['🔥', $m['streak'] . '-day streak'];
        $nx = coach_badges($m, 0)['next'];
        unset($m['nocode_orders'], $m['order_com']);
        $r = $c['team']['ranked'];
        // My queries (green panel): assigned, query orders, community orders, query→order %, and how many more query orders reach the goal.
        $qinfo = null;
        try {
            $S = ct_snapshot($pdo, $bizDay); $x = $S['emps'][$myId] ?? null;
            if ($x) {
                $gp = max(1.0, (float)ct_cfg($pdo)['q_conv_goal']); $gq = (int)ceil($x['queries'] * $gp / 100);
                $qinfo = ['queries' => (int)$x['queries'], 'query_orders' => (int)$x['qo'], 'community_orders' => (int)$x['co'], 'conv' => $x['queries'] > 0 ? round($x['qo'] / $x['queries'] * 100) : null,
                    'goal_pct' => $gp, 'goal_orders' => $gq, 'need_more' => max(0, $gq - (int)$x['qo']), 'exp_arr' => $x['exp_arr'] ?? null, 'arrive' => $x['arrive'] ?? null];
                $rsp = ms_wa_reply_today($pdo, $myId, $bizDay); if ($rsp) $qinfo += $rsp;   // ⚡ Reply speed from today's WhatsApp chats (no upload needed)
                if (isset($x['exp_arr']) && $x['exp_arr'] !== null) $m['should_pct'] = (int)round((float)$x['exp_arr']);
                if (isset($x['clean_ticket'])) $m['clean_ticket'] = (int)round((float)$x['clean_ticket']);   // the same ticket rule as the ticket tile   // ONE "where you should be now" on every card: counted from YOUR punch-in (same as the Pace box)
            }
        } catch (Throwable $e) {}
        json_response(['business_day' => $bizDay, 'qinfo' => $qinfo, 'me' => $m, 'tips' => $tips, 'bonus' => (float)($m['bonus'] ?? $c['bonus']), 'goal' => coach_goal($m), 'won' => $won, 'next' => $nx,
            'team' => ['people' => $c['team']['people'], 'ahead' => $c['team']['ahead'], 'avg_ticket' => $c['team']['avg_ticket'], 'ranked' => $r]]);
        break;
