    case 'my.alloc_pulse': {
        // Order Allocation page, after a sales employee allocates an order to themselves: today's target, sales, orders (one arrow each),
        // pace (ahead / behind of time), the team rank (names + % only, never amounts) and two coaching tips. See coach_day().
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $myId = (int)$auth['employee_id'];
        $bizDay = biz_today($pdo);
        $c = coach_day($pdo, $bizDay);
        $m = $c['emps'][$myId] ?? null;
        if (!$m) json_response(['business_day' => $bizDay, 'target' => 0, 'sales' => 0, 'orders' => 0, 'pct' => null, 'rank' => [], 'team' => 0, 'bonus' => $c['bonus'], 'coach' => null]);
        // Rank by % of today's target: the top 3 by name; "You" is shown only when in the top 10 (lower = "₹X to reach the top 10").
        $l = array_values(array_filter($c['emps'], fn($x) => $x['pct'] !== null && $x['orders'] > 0));
        usort($l, fn($a, $b) => $b['pct'] <=> $a['pct'] ?: $b['sales'] <=> $a['sales']);
        $rank = []; $myPos = null;
        foreach ($l as $i => $x) {
            $me = $x['id'] === $myId;
            if ($me) $myPos = $i + 1;
            if ($i < 3 || ($me && $i < 10)) $rank[] = ['pos' => $i + 1, 'name' => $me ? 'You' : trim(explode(' ', $x['name'])[0]), 'pct' => $x['pct'], 'me' => $me];
        }
        $toTop10 = null;
        if ($myPos !== null && $myPos > 10 && isset($l[9]) && $m['target'] > 0) $toTop10 = round(max(0, ($l[9]['pct'] - $m['pct']) / 100 * $m['target']));
        $tips = array_merge(coach_tips($m, $c['team'], (float)($m['bonus'] ?? $c['bonus']), $c['floor']), convo_tips($pdo, $myId, $c['emps']));   // + what the chat / call reviews say
        $pick = coach_pick($tips, (int)$m['orders']);
        coach_log($pdo, $bizDay, $myId, array_column($pick, 'k'));
        // This order (?source=&order_id=): its commission, and the small wins it unlocked (badges) + the next step.
        $ok = (string)($_GET['source'] ?? '') . '|' . (string)($_GET['order_id'] ?? '');
        $oCom = $m['order_com'][$ok] ?? null;
        $amt = (float)($_GET['amount'] ?? 0);
        $bg = coach_badges($m, $amt);
        // today's rating (out of 10) with this order in it, next to the last worked day
        $rt = null;
        try {
            $rd = rating_days($pdo, date('Y-m-d', strtotime($bizDay . ' -7 day')), $bizDay);
            $rx = $rd[$bizDay][$myId] ?? null; $rp = null;
            for ($i = 1; $i <= 7 && $rp === null; $i++) { $d = date('Y-m-d', strtotime($bizDay . " -$i day")); if (isset($rd[$d][$myId]) && $rd[$d][$myId]['score'] !== null) $rp = $rd[$d][$myId]['score']; }
            if ($rx && $rx['score'] !== null) $rt = ['today' => $rx['score'], 'prev' => $rp, 'label' => rating_label($rx['score'])];
        } catch (Throwable $e) {}
        json_response(['rating' => $rt,'business_day' => $bizDay, 'target' => $m['target'], 'sales' => $m['sales'], 'orders' => $m['orders'], 'pct' => $m['pct'],
            'rank' => $rank, 'my_pos' => $myPos, 'to_top10' => $toTop10, 'team' => count($l), 'bonus' => (float)($m['bonus'] ?? $c['bonus']),
            'coach' => ['should_pct' => $m['should_pct'], 'gap' => $m['gap'], 'ahead' => $c['team']['ahead'], 'people' => $c['team']['people'], 'tips' => $pick,
                'goal' => coach_goal($m), 'order_com' => $oCom !== null ? round($oCom) : null, 'com_today' => $m['com_today'], 'yest_same' => $m['yest_same'],
                'code' => ['have' => $m['code'], 'need' => $m['code_need'], 'left' => $m['code_left'], 'ok' => $m['code_ok'], 'orders' => $m['orders'], 'lost' => $m['code_lost'], 'pct' => $m['code_pct']],
                'badges' => $bg['badges'], 'next' => $bg['next'], 'improved' => $m['improved_rank'] ?? null]]);
        break;
    }

    case 'my.commission': {
        // The logged-in sales employee's own commission ingredients for this month: the commission rules, the order-code rules,
        // the manual order shares, and THEIR OWN daily targets / attendance. The My Sales page works today's and the month's commission
        // out in the browser from these and its own orders (shopify.orders, already limited to them) — the same way the Commission page does.
        $auth = require_auth();
        $myId = (int)($auth['employee_id'] ?? 0);
        if (!$myId) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $es = $pdo->prepare(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.basic_salary, e.designation, e.joining_date, e.sales_tag, d.department_name
             FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.employee_id = ? AND e.status != 'ex'"
        );
        $es->execute([$myId]);
        $e = $es->fetch();
        if (!$e || !sales_commission_ok($e)) json_response(['applicable' => false]);   // everyone who creates orders (sales role or an order tag) gets commission automatically

        $to = biz_today($pdo);
        $from = substr($to, 0, 7) . '-01';
        // Archive: an earlier month (last 12) can be asked for with ?month=YYYY-MM — its days, targets and attendance.
        $mq = trim((string)($_GET['month'] ?? ''));
        if (preg_match('/^\d{4}-\d{2}$/', $mq) && $mq < substr($to, 0, 7) && $mq >= date('Y-m', strtotime($from . ' -12 months'))) {
            $from = $mq . '-01'; $to = date('Y-m-t', strtotime($from));
        }
        ensure_commission_rules_table($pdo);
        $rules = $pdo->query("SELECT * FROM commission_rules ORDER BY sort_order ASC, rule_id ASC")->fetchAll();
        $code = ['on' => false, 'rules' => []];
        $shares = [];
        if (ensure_commission_code_tables($pdo)) {
            $code['on'] = setting_get($pdo, 'commission_code_rules_on', '0') === '1';
            $code['rules'] = array_map('commission_code_rule_out', $pdo->query("SELECT * FROM commission_code_rules ORDER BY sort_order ASC, rule_id ASC")->fetchAll());
            $sq = $pdo->prepare("SELECT order_key, share_pct, pay_mode FROM commission_order_share WHERE order_day BETWEEN ? AND ?");
            $sq->execute([$from, $to]);
            foreach ($sq->fetchAll() as $r) $shares[$r['order_key']] = ['share_pct' => (float)$r['share_pct'], 'mode' => (string)$r['pay_mode']];   // the reason notes stay with Admin
        }

        // Same day-wise target / attendance as the Commission page, for this one employee.
        $tg = team_range_targets($pdo, [$e], $from, $to, true);
        $present = attendance_present_map($pdo, $from, $to);
        $marks = day_marks_between($pdo, $from, $to, $myId);
        $t = ['' => [], 'tm4u' => []];
        foreach (($tg['panels'][$myId] ?? []) as $gk => $x) {
            $rk = $gk === 'tm4u' ? 'tm4u' : '';
            foreach (($x['by_day'] ?? []) as $d => $v) $t[$rk][$d] = ($t[$rk][$d] ?? 0) + (float)$v;
        }
        $st = [];
        for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
            $m = $marks[$d . '|' . $myId] ?? '';
            if ($m !== '') $st[$d] = $m;
            elseif (!empty($present[$myId][$d])) $st[$d] = 'present';
            elseif ($d <= biz_today($pdo)) $st[$d] = 'absent';
        }
        // Commission set by hand for him this month (Commission page): the My Sales page shows it instead of the worked-out figure.
        $manual = [];
        if (ensure_commission_manual_table($pdo)) {
            $ms = $pdo->prepare("SELECT row_key, rate, amount FROM commission_manual WHERE month = ? AND employee_id = ?");
            $ms->execute([substr($from, 0, 7), $myId]);
            foreach ($ms->fetchAll() as $r) $manual[$r['row_key']] = ['rate' => (float)$r['rate'], 'amount' => (float)$r['amount']];
        }
        json_response([
            'manual' => (object)$manual,
            'applicable' => true, 'from' => $from, 'to' => $to, 'today' => $to,
            'rules' => $rules, 'code' => $code, 'shares' => (object)$shares,
            'target' => ['' => (object)$t[''], 'tm4u' => (object)$t['tm4u']], 'status' => (object)$st,
            // Each panel's own day-wise target (a person on 2 panels gets a separate target per panel); the page shows them as tabs.
            'target_panels' => (object)array_map(fn($x) => (object)($x['by_day'] ?? []), $tg['panels'][$myId] ?? []),
            'panel_labels' => house_labels(),
            'ml_slab' => (function () use ($pdo, $myId) {       // 📅 special days: only "everyone" and this person's own
                $c = ml_slab_get($pdo); $c['me'] = (int)$myId;
                $c['special'] = array_values(array_filter($c['special'] ?? [], fn($x) => empty($x['emps']) || in_array((int)$myId, array_map('intval', (array)$x['emps']), true)));
                return $c;
            })(),
        ]);
        break;
    }

    // ============== LEAVE ==============
    case 'leave.my': {
        // The logged-in employee's own requests plus the free-leave figures the apply form needs.
        $auth = require_auth();
        require_leave_access($auth);
        $empId = (int)($auth['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if (!ensure_leave_table($pdo)) json_response(['error' => 'Could not create the leave_requests table.'], 500);
        ensure_day_marks_table($pdo);
        $today = biz_today($pdo);
        $st = $pdo->prepare("SELECT leave_id, leave_type, date_from, date_to, days, reason, status, decided_by, admin_note, created_at FROM leave_requests WHERE employee_id = ? ORDER BY date_from DESC, leave_id DESC LIMIT 80");
        $st->execute([$empId]);
        $rows = $st->fetchAll();
        foreach ($rows as &$r) { $r['leave_id'] = (int)$r['leave_id']; $r['days'] = (float)$r['days']; }
        unset($r);
        $rules = salary_rules_load($pdo);
        $month = substr($today, 0, 7);
        $used = leave_used_by_month($pdo, $empId, $month . '-01');
        // This month's approved leave days (day marks only), for the "taken" tile.
        $taken = 0.0;
        try {
            $mk = $pdo->prepare("SELECT mark FROM day_marks WHERE employee_id = ? AND mark_date BETWEEN ? AND ? AND mark IN ('leave','half_leave')");
            $mk->execute([$empId, $month . '-01', date('Y-m-t', strtotime($month . '-01'))]);
            foreach ($mk->fetchAll() as $m) $taken += $m['mark'] === 'half_leave' ? 0.5 : 1;
        } catch (PDOException $e) {}
        json_response([
            'requests' => $rows, 'today' => $today, 'month' => $month,
            'free_total' => (float)$rules['free_leave'], 'used' => $used, 'taken' => $taken,
            'pending' => count(array_filter($rows, fn($r) => $r['status'] === 'pending')),
        ]);
        break;
    }

    case 'leave.apply': {
        $auth = require_auth();
        require_leave_access($auth);
        $empId = (int)($auth['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_leave_table($pdo)) json_response(['error' => 'Could not create the leave_requests table.'], 500);
        $in = json_input();
        $type = (string)($in['type'] ?? '');
        $from = (string)($in['from'] ?? '');
        $to = (string)($in['to'] ?? '');
        $reason = trim((string)($in['reason'] ?? ''));
        if (!isset(LEAVE_TYPES[$type])) json_response(['error' => 'Choose Full day, Half day or Work from home.'], 422);
        if ($type === 'half_leave') $to = $from;
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Pick the dates.'], 422);
        if ($to < $from) json_response(['error' => 'The end date is before the start date.'], 422);
        if ($from < biz_today($pdo)) json_response(['error' => 'You can only apply from today onward. For an earlier day, ask Admin / HR to mark it.'], 422);
        $days = leave_days($type, $from, $to);
        if ($days > 31) json_response(['error' => 'One request can cover up to 31 days.'], 422);
        if ($reason === '') json_response(['error' => 'Please write a reason.'], 422);
        $reason = mb_substr($reason, 0, 400);
        // No second request over the same days (pending or approved).
        $ov = $pdo->prepare("SELECT leave_id FROM leave_requests WHERE employee_id = ? AND status IN ('pending','approved') AND date_from <= ? AND date_to >= ? LIMIT 1");
        $ov->execute([$empId, $to, $from]);
        if ($ov->fetch()) json_response(['error' => 'You already have a request that covers some of these days.'], 409);
        $pdo->prepare("INSERT INTO leave_requests (employee_id, leave_type, date_from, date_to, days, reason) VALUES (?, ?, ?, ?, ?, ?)")
            ->execute([$empId, $type, $from, $to, $days, $reason]);
        json_response(['message' => 'Request sent to Admin.', 'leave_id' => (int)$pdo->lastInsertId()]);
        break;
    }

    case 'leave.cancel': {
        // The employee withdraws a request that is still pending.
        $auth = require_auth();
        require_leave_access($auth);
        $empId = (int)($auth['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_leave_table($pdo)) json_response(['error' => 'Could not create the leave_requests table.'], 500);
        $id = (int)(json_input()['leave_id'] ?? 0);
        $st = $pdo->prepare("DELETE FROM leave_requests WHERE leave_id = ? AND employee_id = ? AND status = 'pending'");
        $st->execute([$id, $empId]);
        if (!$st->rowCount()) json_response(['error' => 'This request was already decided, so it cannot be cancelled.'], 409);
        json_response(['message' => 'Request cancelled.']);
        break;
    }

    case 'leave_admin.count': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_leave_table($pdo)) json_response(['count' => 0]);
        json_response(['count' => (int)$pdo->query("SELECT COUNT(*) FROM leave_requests WHERE status = 'pending'")->fetchColumn()]);
        break;
    }

    case 'leave_admin.list': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_leave_table($pdo)) json_response(['error' => 'Could not create the leave_requests table.'], 500);
        ensure_day_marks_table($pdo);
        $status = (string)($_GET['status'] ?? 'pending');
        if (!in_array($status, ['pending', 'approved', 'rejected'], true)) $status = 'pending';
        // Search: one employee (employee_id) or any text in the name / code / department (q). The tab counts follow the search.
        $fSql = ''; $fArgs = [];
        if (!empty($_GET['employee_id'])) { $fSql .= " AND l.employee_id = ?"; $fArgs[] = (int)$_GET['employee_id']; }
        $lq = trim((string)($_GET['q'] ?? ''));
        if ($lq !== '') { $fSql .= " AND (e.full_name LIKE ? OR e.employee_code LIKE ? OR d.department_name LIKE ?)"; $lk = '%' . $lq . '%'; array_push($fArgs, $lk, $lk, $lk); }
        $counts = ['pending' => 0, 'approved' => 0, 'rejected' => 0];
        $cs = $pdo->prepare("SELECT l.status, COUNT(*) c FROM leave_requests l JOIN employees e ON e.employee_id = l.employee_id LEFT JOIN departments d ON d.department_id = e.department_id WHERE 1 = 1$fSql GROUP BY l.status");
        $cs->execute($fArgs);
        foreach ($cs->fetchAll() as $r) if (isset($counts[$r['status']])) $counts[$r['status']] = (int)$r['c'];
        $st = $pdo->prepare(
            "SELECT l.leave_id, l.employee_id, l.leave_type, l.date_from, l.date_to, l.days, l.reason, l.status, l.decided_by, l.decided_at, l.admin_note, l.created_at,
                    e.full_name, e.employee_code, d.department_name
               FROM leave_requests l
               JOIN employees e ON e.employee_id = l.employee_id
               LEFT JOIN departments d ON d.department_id = e.department_id
              WHERE l.status = ?$fSql
              ORDER BY " . ($status === 'pending' ? "l.date_from ASC, l.leave_id ASC" : "l.decided_at DESC, l.leave_id DESC") . " LIMIT " . ($fSql !== '' ? 500 : 150)
        );
        $st->execute(array_merge([$status], $fArgs));
        $rows = $st->fetchAll();
        $rules = salary_rules_load($pdo);
        $usedCache = [];
        $today = biz_today($pdo);
        foreach ($rows as &$r) {
            $r['leave_id'] = (int)$r['leave_id']; $r['employee_id'] = (int)$r['employee_id']; $r['days'] = (float)$r['days'];
            if ($status !== 'pending') continue;
            // Free leave left in the month the leave starts (marks + this employee's other pending requests), and who else is off.
            $eid = $r['employee_id'];
            if (!isset($usedCache[$eid])) $usedCache[$eid] = leave_used_by_month($pdo, $eid, substr($today, 0, 7) . '-01');
            $m = substr((string)$r['date_from'], 0, 7);
            $own = 0.0;                  // this request's own pending days in that month (they sit inside the used total)
            if ($r['leave_type'] === 'half_leave') $own = 0.5;
            elseif ($r['leave_type'] === 'leave') { for ($dd = (string)$r['date_from']; $dd <= (string)$r['date_to']; $dd = date('Y-m-d', strtotime($dd . ' +1 day'))) if (substr($dd, 0, 7) === $m) $own++; }
            $r['free_left'] = max(0.0, (float)$rules['free_leave'] - max(0.0, ($usedCache[$eid][$m] ?? 0) - $own));
            $cl = $pdo->prepare(
                "SELECT DISTINCT e.full_name, l2.date_from, l2.date_to FROM leave_requests l2 JOIN employees e ON e.employee_id = l2.employee_id
                  WHERE l2.status = 'approved' AND l2.leave_type <> 'wfh' AND l2.employee_id <> ? AND l2.date_from <= ? AND l2.date_to >= ? LIMIT 5"
            );
            $cl->execute([$eid, $r['date_to'], $r['date_from']]);
            $r['clash'] = array_map(fn($c) => $c['full_name'], $cl->fetchAll());
        }
        unset($r);
        json_response(['requests' => $rows, 'counts' => $counts, 'status' => $status, 'free_total' => (float)$rules['free_leave']]);
        break;
    }

    case 'leave_admin.decide': {
        // approved | rejected on a pending request; 'rejected' on an approved one revokes it and clears the marks it set.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_leave_table($pdo)) json_response(['error' => 'Could not create the leave_requests table.'], 500);
        ensure_day_marks_table($pdo);
        $in = json_input();
        $id = (int)($in['leave_id'] ?? 0);
        $decision = (string)($in['decision'] ?? '');
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 300);
        if (!in_array($decision, ['approved', 'rejected'], true)) json_response(['error' => 'decision must be approved or rejected.'], 422);
        $st = $pdo->prepare("SELECT * FROM leave_requests WHERE leave_id = ?");
        $st->execute([$id]);
        $r = $st->fetch();
        if (!$r) json_response(['error' => 'Request not found.'], 404);
        $who = (string)($auth['username'] ?? 'admin');
        $mark = (string)$r['leave_type'];
        $empId = (int)$r['employee_id'];

        if ($r['status'] === 'approved' && $decision === 'rejected') {
            // Revoke: take back the marks this request set (only where the mark is still the one it wrote).
            $pdo->prepare("DELETE FROM day_marks WHERE employee_id = ? AND mark_date BETWEEN ? AND ? AND mark = ?")->execute([$empId, $r['date_from'], $r['date_to'], $mark]);
            $pdo->prepare("UPDATE leave_requests SET status = 'rejected', decided_by = ?, decided_at = NOW(), admin_note = ?, marks_set = 0 WHERE leave_id = ?")->execute([$who, $note !== '' ? $note : 'Approval withdrawn', $id]);
            json_response(['message' => 'Approval withdrawn — the days are unmarked.']);
        }
        if ($r['status'] !== 'pending') json_response(['error' => 'This request was already decided.'], 409);

        if ($decision === 'rejected') {
            $pdo->prepare("UPDATE leave_requests SET status = 'rejected', decided_by = ?, decided_at = NOW(), admin_note = ? WHERE leave_id = ?")->execute([$who, $note, $id]);
            json_response(['message' => 'Rejected.']);
        }

        // Approve: mark each day, except days that already carry a punch record or a Holiday / Week off mark.
        $set = 0; $skipped = 0;
        $hasPunch = $pdo->prepare("SELECT 1 FROM attendance WHERE employee_id = ? AND punch_date = ? AND punch_in IS NOT NULL LIMIT 1");
        $curMark = $pdo->prepare("SELECT mark FROM day_marks WHERE employee_id = ? AND mark_date = ?");
        $ins = $pdo->prepare("INSERT INTO day_marks (mark_date, employee_id, mark) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE mark = VALUES(mark)");
        for ($d = (string)$r['date_from']; $d <= (string)$r['date_to']; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
            $hasPunch->execute([$empId, $d]);
            $curMark->execute([$empId, $d]);
            $cm = $curMark->fetchColumn();
            if ($hasPunch->fetchColumn() || in_array($cm, ['holiday', 'week_off'], true)) { $skipped++; continue; }
            $ins->execute([$d, $empId, $mark]);
            $set++;
        }
        $pdo->prepare("UPDATE leave_requests SET status = 'approved', decided_by = ?, decided_at = NOW(), admin_note = ?, marks_set = ? WHERE leave_id = ?")->execute([$who, $note, $set, $id]);
        $msg = 'Approved — ' . $set . ' day' . ($set === 1 ? '' : 's') . ' marked on attendance.';
        if ($skipped) $msg .= ' ' . $skipped . ' day' . ($skipped === 1 ? '' : 's') . ' skipped (already punched in, or a holiday / week off).';
        json_response(['message' => $msg, 'marked' => $set, 'skipped' => $skipped]);
        break;
    }

    case 'approvals.count': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        $docs = (int)$pdo->query(
            "SELECT COUNT(*) FROM employee_documents ed
             JOIN employees e ON e.employee_id = ed.employee_id
             WHERE ed.status = 'pending' AND e.status != 'ex'"
        )->fetchColumn();
        $emps = (int)$pdo->query("SELECT COUNT(*) FROM employees WHERE status = 'pending'")->fetchColumn();
        json_response(['count' => $docs + $emps]);
        break;
    }

    // ============== AGREEMENTS ==============
    case 'agreement_templates.list': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        try {
            $rows = $pdo->query("SELECT * FROM agreement_templates ORDER BY template_name")->fetchAll();
        } catch (PDOException $e) {
            json_response(['error' => 'Agreement tables missing — run the agreement SQL first.'], 500);
        }
        json_response(['templates' => $rows]);
        break;
    }

    case 'agreement_templates.upload': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $name = trim($_POST['template_name'] ?? '');
        if ($name === '') json_response(['error' => 'Template name is required.'], 422);
        if (!isset($_FILES['template_file']) || $_FILES['template_file']['error'] !== UPLOAD_ERR_OK) {
            json_response(['error' => 'Upload the .docx template file.'], 422);
        }
        $ext = strtolower(pathinfo($_FILES['template_file']['name'], PATHINFO_EXTENSION));
        if ($ext === 'htm') $ext = 'html';
        if (!in_array($ext, ['pdf', 'html', 'docx'], true)) json_response(['error' => 'Upload a .pdf (recommended), .html or .docx template.'], 422);

        $dir = __DIR__ . '/uploads/agreements/';
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $safe = 'tpl_' . time() . '_' . bin2hex(random_bytes(3)) . '.' . $ext;
        if (!move_uploaded_file($_FILES['template_file']['tmp_name'], $dir . $safe)) {
            json_response(['error' => 'Could not save the template.'], 500);
        }

        // Optional: replace the file of an existing template (keeps its
        // agreements). Signed agreements are reset to "PDF on first view" so
        // they regenerate from the new file.
        $replaceId = (int)($_POST['template_id'] ?? 0);
        if ($replaceId > 0) {
            $cur = $pdo->prepare("SELECT file_path FROM agreement_templates WHERE template_id = ?");
            $cur->execute([$replaceId]);
            $oldPath = $cur->fetchColumn();
            if ($oldPath === false) json_response(['error' => 'Template not found.'], 404);
            $pdo->prepare("UPDATE agreement_templates SET template_name = ?, file_path = ? WHERE template_id = ?")
                ->execute([$name, 'uploads/agreements/' . $safe, $replaceId]);
            if ($oldPath && file_exists(__DIR__ . '/' . $oldPath)) @unlink(__DIR__ . '/' . $oldPath);
            if (agreement_kind_is_browser(agreement_template_kind($safe))) {
                $files = $pdo->prepare("SELECT agreement_id, signed_file FROM agreements WHERE template_id = ? AND status = 'signed'");
                $files->execute([$replaceId]);
                foreach ($files->fetchAll() as $f) {
                    if ($f['signed_file'] && file_exists(__DIR__ . '/' . $f['signed_file'])) @unlink(__DIR__ . '/' . $f['signed_file']);
                }
                $pdo->prepare("UPDATE agreements SET signed_file = NULL WHERE template_id = ? AND status = 'signed'")->execute([$replaceId]);
            }
            json_response(['message' => 'Template file replaced. Signed agreements will regenerate from the new file on next view.']);
        }

        $pdo->prepare("INSERT INTO agreement_templates (template_name, file_path, created_by) VALUES (?, ?, ?)")
            ->execute([$name, 'uploads/agreements/' . $safe, $auth['username']]);
        json_response(['message' => 'Template uploaded.'], 201);
        break;
    }

    case 'agreement_templates.delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = (int)($input['template_id'] ?? 0);
        if (!$id) json_response(['error' => 'template_id required.'], 422);
        $st = $pdo->prepare("SELECT file_path FROM agreement_templates WHERE template_id = ?");
        $st->execute([$id]);
        $fp = $st->fetchColumn();
        $pdo->prepare("DELETE FROM agreement_templates WHERE template_id = ?")->execute([$id]);
        if ($fp && file_exists(__DIR__ . '/' . $fp)) @unlink(__DIR__ . '/' . $fp);
        json_response(['message' => 'Template deleted.']);
        break;
    }

    case 'agreements.list': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        agreements_upgrade_docx_to_pdf($pdo);   // convert any leftover .docx
        $employeeId = (int)($_GET['employee_id'] ?? 0);
        $docSig = "(SELECT ed2.document_file FROM employee_documents ed2
                    JOIN document_types dt2 ON dt2.document_type_id = ed2.document_type_id
                    WHERE ed2.employee_id = e.employee_id
                      AND LOWER(dt2.document_name) LIKE '%signature%'
                      AND ed2.document_file IS NOT NULL AND ed2.document_file <> ''
                    ORDER BY (ed2.status = 'approved') DESC, ed2.uploaded_at DESC LIMIT 1)";
        $sigCol = $HAS_SIG_COL ? "COALESCE(NULLIF(e.signature_file, ''), $docSig)" : $docSig;
        $sql =
            "SELECT a.*, t.template_name, t.file_path AS template_file, e.full_name, e.employee_code, $sigCol AS signature_file
             FROM agreements a
             JOIN agreement_templates t ON t.template_id = a.template_id
             JOIN employees e ON e.employee_id = a.employee_id";
        $params = [];
        if ($employeeId > 0) {
            $sql .= " WHERE a.employee_id = ?";
            $params[] = $employeeId;
        }
        $sql .= " ORDER BY a.created_at DESC LIMIT 300";
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll();
        $errs = agreement_errors_all();
        ensure_agreement_emails_table($pdo);
        $emails = [];
        foreach ($pdo->query("SELECT agreement_id, kind, to_email, sent_at, error FROM agreement_emails")->fetchAll() as $em) $emails[(int)$em['agreement_id']][$em['kind']] = $em;
        foreach ($rows as &$r) {
            $r['render_error'] = ($r['status'] !== 'signed' && isset($errs[(string)$r['agreement_id']])) ? $errs[(string)$r['agreement_id']]['error'] : null;
            $r['template_kind'] = agreement_template_kind((string)$r['template_file']);
            unset($r['template_file']);
            // Email status for the row's current stage: the signed copy once
            // signed, otherwise the please-sign request.
            $ek = $r['status'] === 'signed' ? 'signed' : 'request';
            $em = $emails[(int)$r['agreement_id']][$ek] ?? null;
            $r['email'] = $em ? ['kind' => $ek, 'to' => $em['to_email'], 'sent_at' => $em['sent_at'], 'error' => $em['error']] : null;
        }
        unset($r);
        json_response(['agreements' => $rows, 'mail_configured' => mail_config() !== null]);
        break;
    }

    case 'agreements.delete': {
        // Admin/HR removes an agreement entirely, signed or not, and deletes
        // the generated file from disk.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = (int)($input['agreement_id'] ?? 0);
        if (!$id) json_response(['error' => 'agreement_id required.'], 422);

        $st = $pdo->prepare("SELECT signed_file FROM agreements WHERE agreement_id = ?");
        $st->execute([$id]);
        $row = $st->fetch();
        if (!$row) json_response(['error' => 'Agreement not found.'], 404);

        $pdo->prepare("DELETE FROM agreements WHERE agreement_id = ?")->execute([$id]);
        if (!empty($row['signed_file']) && file_exists(__DIR__ . '/' . $row['signed_file'])) {
            @unlink(__DIR__ . '/' . $row['signed_file']);
        }
        json_response(['message' => 'Agreement deleted.']);
        break;
    }

    case 'agreements.send': {
        // Sending no longer always creates a "please sign" request:
        // any employee who has already saved a signature gets the document
        // generated and signed immediately (auto_signed = 1). Only employees
        // with no signature on file are left pending for them to sign.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $templateId = (int)($input['template_id'] ?? 0);
        $empIds = $input['employee_ids'] ?? [];
        if (!$templateId || !is_array($empIds) || !$empIds) json_response(['error' => 'Pick a template and at least one employee.'], 422);

        $tStmt = $pdo->prepare("SELECT file_path, template_name FROM agreement_templates WHERE template_id = ?");
        $tStmt->execute([$templateId]);
        $tpl = $tStmt->fetch();
        if (!$tpl) json_response(['error' => 'Template not found.'], 404);

        $dir = __DIR__ . '/uploads/agreements/';
        if (!is_dir($dir)) mkdir($dir, 0755, true);

        $ins = $pdo->prepare(
            "INSERT INTO agreements (template_id, employee_id, status, created_by) VALUES (?, ?, 'pending', ?)
             ON DUPLICATE KEY UPDATE status = IF(status = 'signed', status, 'pending')"
        );
        $find = $pdo->prepare("SELECT agreement_id, status FROM agreements WHERE template_id = ? AND employee_id = ?");
        $empStmt = $pdo->prepare(
            "SELECT e.*, d.department_name FROM employees e
             LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.employee_id = ?"
        );
        $signUpd = $pdo->prepare(
            "UPDATE agreements SET status = 'signed', signed_at = NOW(), signed_file = ?, reference = ?,
                    signed_ip = ?, auto_signed = 1
             WHERE agreement_id = ?"
        );

        $auto = 0; $pending = 0; $failed = []; $notes = [];

        foreach ($empIds as $eid) {
            $eid = (int)$eid;
            if ($eid <= 0) continue;

            $ins->execute([$templateId, $eid, $auth['username']]);
            $find->execute([$templateId, $eid]);
            $row = $find->fetch();
            if (!$row) continue;
            if ($row['status'] === 'signed') { $auto++; continue; }

            $agreementId = (int)$row['agreement_id'];

            $empStmt->execute([$eid]);
            $emp = $empStmt->fetch();
            if (!$emp) { $pending++; continue; }

            // Signature pad first, then the uploaded "Digital Signature"
            // document. Nothing usable -> stays pending.
            $sigWhy = null;
            $sigPath = employee_signature_png($pdo, $emp, $sigWhy);
            if (!$sigPath) {
                agreement_error_set($agreementId, 'Not auto-signed: ' . ($sigWhy ?: 'no usable signature image'));
                $pending++;
                agreement_email_queue($pdo, $agreementId, 'request');
                continue;
            }

            $ref = 'HRMS-' . date('Y') . '-' . str_pad((string)$eid, 4, '0', STR_PAD_LEFT) . '-' . $agreementId;
            $vars = agreement_vars($emp, $ref);

            if (agreement_kind_is_browser(agreement_template_kind($tpl['file_path']))) {
                agreement_mark_signed_html($pdo, $agreementId, $ref, true);
                agreement_error_set($agreementId, null);
                $auto++;
                agreement_email_queue($pdo, $agreementId, 'signed');
                continue;
            }

            $outName = 'signed_' . $agreementId . '_' . time() . '_' . bin2hex(random_bytes(3)) . '.pdf';
            $why = null;
            $ok = agreement_pdf(upload_abs($tpl['file_path']), $dir . $outName, $vars, $sigPath, $why);
            if (!$ok) {
                agreement_error_set($agreementId, $why ?: 'unknown render failure');
                $failed[] = $emp['full_name'] . ($why ? " ($why)" : '');
                $pending++;
                agreement_email_queue($pdo, $agreementId, 'request');
                continue;
            }
            agreement_error_set($agreementId, null);

            $signUpd->execute([
                'uploads/agreements/' . $outName,
                $ref,
                $_SERVER['REMOTE_ADDR'] ?? '',
                $agreementId,
            ]);
            $auto++;
            agreement_email_queue($pdo, $agreementId, 'signed');
        }

        $msg = "Sent to " . ($auto + $pending) . " employee(s).";
        if ($auto) $msg = "$auto signed automatically" . ($pending ? ", $pending waiting for signature." : ".");
        if ($failed) $msg .= ' Could not auto-generate for: ' . implode(', ', $failed) . '.';
        if ($notes) $msg .= ' ' . implode(' ', $notes);

        json_response(['message' => $msg, 'auto_signed' => $auto, 'pending' => $pending, 'notes' => $notes]);
        break;
    }

    case 'agreements.signature_status': {
        // Real, file-level answer to "can this person be auto-signed?" for
        // everyone who has a signature on record. The Send list used to show
        // "auto-sign" whenever a signature document ROW existed, even when
        // the file behind it was missing or unreadable.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $ids = $pdo->query(
            "SELECT DISTINCT ed.employee_id FROM employee_documents ed
             JOIN document_types dt ON dt.document_type_id = ed.document_type_id
             WHERE LOWER(dt.document_name) LIKE '%signature%' AND ed.document_file IS NOT NULL AND ed.document_file <> ''"
        )->fetchAll(PDO::FETCH_COLUMN);
        global $HAS_SIG_COL;
        if ($HAS_SIG_COL) {
            $ids = array_unique(array_merge($ids, $pdo->query(
                "SELECT employee_id FROM employees WHERE signature_file IS NOT NULL AND signature_file <> ''"
            )->fetchAll(PDO::FETCH_COLUMN)));
        }
        $eStmt = $pdo->prepare("SELECT * FROM employees WHERE employee_id = ?");
        $status = [];
        foreach ($ids as $id) {
            $eStmt->execute([(int)$id]);
            $emp = $eStmt->fetch();
            if (!$emp) continue;
            $why = null;
            $ok = (bool)employee_signature_png($pdo, $emp, $why);
            $status[(int)$id] = ['ok' => $ok, 'reason' => $ok ? null : $why];
        }
        json_response(['status' => $status]);
        break;
    }

    case 'mail.process': {
        // Sends whatever is waiting in the outbox. Pages call this in the
        // background; it's safe to call often (locked, small batches).
        require_auth();
        [$sent, $failed, $waiting] = mail_process($pdo, 5);
        json_response(['sent' => $sent, 'failed' => $failed, 'waiting' => $waiting]);
        break;
    }

    case 'mail.cron': {
        // For a Hostinger cron job (every 5 minutes), no login:
        //   https://fourpirates.space/empmanagment/api.php?action=mail.cron&key=API_KEY
        if (!defined('API_KEY') || ($_GET['key'] ?? '') !== API_KEY) json_response(['error' => 'Forbidden.'], 403);
        [$sent, $failed, $waiting] = mail_process($pdo, 20);
        json_response(['sent' => $sent, 'failed' => $failed, 'waiting' => $waiting]);
        break;
    }

    case 'orders.cron': {
        // Keeps the local copy of the Shopify orders (shop_orders) fresh when nobody has an Orders page open. No login; needs the API_KEY. Hostinger cron job, every 5 minutes:
        //   curl -s "https://fourpirates.space/empmanagment/api.php?action=orders.cron&key=API_KEY" > /dev/null
        if (!defined('API_KEY') || !hash_equals((string)API_KEY, (string)($_GET['key'] ?? ''))) json_response(['error' => 'Forbidden.'], 403);
        ignore_user_abort(true); @set_time_limit(120);
        $lk = @fopen(sys_get_temp_dir() . '/hrms_orders_cron.lock', 'c');
        if (!$lk || !flock($lk, LOCK_EX | LOCK_NB)) json_response(['ok' => true, 'busy' => true]);       // the last run is still going
        $errs = []; $bizToday = biz_today($pdo); $n = 0;
        try { $n = orders_sync_range($pdo, date('Y-m-d', strtotime($bizToday . ' -1 day')), $bizToday, 12, $errs); @file_put_contents(sys_get_temp_dir() . '/hrms_orders_last_sync.txt', (string)time()); }
        catch (Throwable $e) { $errs[] = $e->getMessage(); }
        flock($lk, LOCK_UN); fclose($lk);
        json_response(['ok' => !$errs, 'synced' => $n, 'day' => $bizToday, 'errors' => array_slice(array_map(fn($x) => mb_substr((string)$x, 0, 160), $errs), 0, 3)]);
        break;
    }

    case 'lib.cron': {
        // Reads the old chats / calls into the Chat library by itself, no login. Hostinger cron job, every 5 minutes:
        //   https://fourpirates.space/empmanagment/api.php?action=lib.cron&key=API_KEY
        if (!defined('API_KEY') || !hash_equals((string)API_KEY, (string)($_GET['key'] ?? ''))) json_response(['error' => 'Forbidden.'], 403);
        ignore_user_abort(true); @set_time_limit(280);
        $r = lib_tick_run($pdo, max(1, min(60, (int)tmph_cfg('LIB_TICK_BATCH', 24))), 240);
        json_response(['busy' => !empty($r['busy']), 'read' => (int)($r['transcribed'] ?? 0), 'guide' => $r['guide'] ?? null, 'errors' => array_slice((array)($r['errors'] ?? []), 0, 3), 'left' => (int)$pdo->query("SELECT COUNT(*) " . lib_pending_sql() . " AND msgs_tries < 3")->fetchColumn()]);
        break;
    }

    case 'agreements.email_me': {
        // Employee asks for their own signed copy again.
        $auth = require_auth();
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $in = json_input();
        $id = (int)($in['agreement_id'] ?? 0);
        $st = $pdo->prepare("SELECT status FROM agreements WHERE agreement_id = ? AND employee_id = ?");
        $st->execute([$id, (int)$auth['employee_id']]);
        $status = $st->fetchColumn();
        if ($status === false) json_response(['error' => 'Agreement not found.'], 404);
        if ($status !== 'signed') json_response(['error' => 'This agreement is not signed yet.'], 409);
        $pdo->prepare("UPDATE agreement_emails SET attempts = 0 WHERE agreement_id = ? AND kind = 'signed'")->execute([$id]);
        [$ok, $msg] = agreement_email($pdo, $id, 'signed', true);
        json_response($ok ? ['message' => 'Sent — check your inbox (and spam).'] : ['error' => $msg], $ok ? 200 : 422);
        break;
    }

    case 'mail.test': {
        // Sends a test email to the given address and returns the exact
        // outcome, so mail settings can be checked without an agreement.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $to = trim((string)($in['to'] ?? ''));
        if (!filter_var($to, FILTER_VALIDATE_EMAIL)) json_response(['error' => 'Enter a valid email address.'], 422);
        $cfg = mail_config();
        if (!$cfg) json_response(['error' => 'Email is not configured: MAIL_USER / MAIL_PASS are missing in config.php.'], 422);
        $err = send_mail($to, $to, 'HRMS test email', '<p>This is a test email from the HRMS. If you can read this, agreement emails will work.</p><p>Sent from ' . htmlspecialchars($cfg['user']) . ' via ' . htmlspecialchars($cfg['host']) . ':' . $cfg['port'] . '.</p>');
        if ($err !== null) json_response(['error' => $err], 422);
        json_response(['message' => "Test email sent to $to from {$cfg['user']}. Check the inbox (and spam)."]);
        break;
    }

    case 'agreements.resend_email': {
        // Re-sends the email for the agreement's current stage (signed copy
        // or please-sign request), whatever the previous attempt did.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $id = (int)($in['agreement_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'agreement_id required.'], 422);
        $st = $pdo->prepare("SELECT status FROM agreements WHERE agreement_id = ?");
        $st->execute([$id]);
        $status = $st->fetchColumn();
        if ($status === false) json_response(['error' => 'Agreement not found.'], 404);
        $kind = $status === 'signed' ? 'signed' : 'request';
        $pdo->prepare("UPDATE agreement_emails SET attempts = 0 WHERE agreement_id = ? AND kind = ?")->execute([$id, $kind]);
        [$ok, $msg] = agreement_email($pdo, $id, $kind, true);
        json_response($ok ? ['message' => $msg] : ['error' => $msg], $ok ? 200 : 422);
        break;
    }

    case 'agreements.retry_autosign': {
        // Re-runs auto-signing for every employee who still has a pending
        // agreement — use after re-uploading signatures or fixing files.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $ids = $pdo->query("SELECT DISTINCT employee_id FROM agreements WHERE status <> 'signed'")->fetchAll(PDO::FETCH_COLUMN);
        $signed = 0;
        foreach ($ids as $id) $signed += agreements_autosign_pending($pdo, (int)$id);
        $left = (int)$pdo->query("SELECT COUNT(*) FROM agreements WHERE status <> 'signed'")->fetchColumn();
        json_response([
            'message' => $signed
                ? "Signed {$signed} agreement" . ($signed === 1 ? '' : 's') . ". {$left} still pending."
                : "Nothing could be signed. {$left} still pending — see the reason under each one.",
            'signed' => $signed,
            'still_pending' => $left,
        ]);
        break;
    }

    case 'agreements.diagnose': {
        // Troubleshooting endpoint: reports exactly why auto-signing is or
        // isn't working for one employee. Open in a browser with an admin
        // token, e.g. api.php?action=agreements.diagnose&employee_id=18
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        global $HAS_SIG_COL;
        $empId = (int)($_GET['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'employee_id required.'], 422);

        $out = [
            'php_version'      => PHP_VERSION,
            'has_zip'          => class_exists('ZipArchive'),
            'has_gd'           => function_exists('imagecreatefromstring'),
            'has_jpeg'         => function_exists('imagejpeg'),
            'has_simplexml'    => function_exists('simplexml_load_string'),
            'uploads_writable' => is_writable(__DIR__ . '/uploads/agreements/'),
        ];

        $eStmt = $pdo->prepare(
            "SELECT e.*, d.department_name FROM employees e
             LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.employee_id = ?"
        );
        $eStmt->execute([$empId]);
        $emp = $eStmt->fetch();
        if (!$emp) json_response(['error' => 'Employee not found.'], 404);
        $out['employee'] = $emp['full_name'] . ' (' . $emp['employee_code'] . ')';
        $out['signature_column_present'] = (bool)$HAS_SIG_COL;
        $out['signature_file_column'] = $emp['signature_file'] ?? null;
        $out['signature_file_exists'] = !empty($emp['signature_file'])
            ? file_exists(__DIR__ . '/' . $emp['signature_file']) : false;

        $sigPath = employee_signature_png($pdo, $emp);
        $out['resolved_signature'] = $sigPath ? str_replace(__DIR__ . '/', '', $sigPath) : null;
        if ($sigPath) {
            $info = @getimagesize($sigPath);
            $out['signature_image'] = $info ? ($info[0] . 'x' . $info[1] . ' type ' . $info[2]) : 'NOT A READABLE IMAGE';
        }

        $aStmt = $pdo->prepare(
            "SELECT a.agreement_id, a.status, a.signed_file, t.template_name, t.file_path
             FROM agreements a JOIN agreement_templates t ON t.template_id = a.template_id
             WHERE a.employee_id = ? ORDER BY a.agreement_id DESC LIMIT 5"
        );
        $aStmt->execute([$empId]);
        $ags = $aStmt->fetchAll();
        $out['agreements'] = [];

        foreach ($ags as $a) {
            $tpl = upload_abs($a['file_path']);
            $row = [
                'agreement_id'    => (int)$a['agreement_id'],
                'template'        => $a['template_name'],
                'status'          => $a['status'],
                'signed_file'     => $a['signed_file'],
                'template_path'   => $a['file_path'],
                'template_exists' => file_exists($tpl),
                'template_size'   => file_exists($tpl) ? filesize($tpl) : 0,
            ];

            if ($row['template_exists'] && class_exists('ZipArchive')) {
                $z = new ZipArchive();
                $openCode = $z->open($tpl);
                $row['zip_open'] = ($openCode === true) ? 'ok' : ('failed code ' . $openCode);
                if ($openCode === true) {
                    $row['zip_files'] = $z->numFiles;
                    $doc = $z->getFromName('word/document.xml');
                    $row['document_xml'] = ($doc === false) ? 'MISSING' : (strlen($doc) . ' bytes');
                    $z->close();
                }
                $paras = docx_paragraphs($tpl);
                $row['paragraphs_found'] = count($paras);
                $texts = [];
                foreach ($paras as $p) {
                    if ($p['text'] !== '') $texts[] = mb_substr($p['text'], 0, 60);
                    if (count($texts) >= 3) break;
                }
                $row['first_paragraphs'] = $texts;
                $row['has_signature_marker'] = false;
                foreach ($paras as $p) {
                    if (strpos($p['text'], '{{signature}}') !== false) { $row['has_signature_marker'] = true; break; }
                }

                // Dry run into a temp file.
                $tmp = $dirTmp = __DIR__ . '/uploads/agreements/_diag_' . (int)$a['agreement_id'] . '.pdf';
                $ok = agreement_pdf($tpl, $tmp, agreement_vars($emp, 'DIAG-TEST'), $sigPath);
                $row['render_ok'] = $ok;
                $row['render_size'] = ($ok && file_exists($tmp)) ? filesize($tmp) : 0;
                if (file_exists($tmp)) @unlink($tmp);
            }

            $out['agreements'][] = $row;
        }

        json_response($out);
        break;
    }

    case 'agreements.render': {
        // Returns the filled HTML for one agreement so the browser can render
        // it with the template's own CSS and produce the PDF. Allowed for
        // Admin/HR, and for the employee the agreement belongs to.
        $auth = require_auth();
        $id = (int)($_GET['agreement_id'] ?? 0);
        if (!$id) json_response(['error' => 'agreement_id required.'], 422);

        $st = $pdo->prepare(
            "SELECT a.*, t.template_name, t.file_path FROM agreements a
             JOIN agreement_templates t ON t.template_id = a.template_id
             WHERE a.agreement_id = ?"
        );
        $st->execute([$id]);
        $ag = $st->fetch();
        if (!$ag) json_response(['error' => 'Agreement not found.'], 404);

        $isOwner = !empty($auth['employee_id']) && (int)$auth['employee_id'] === (int)$ag['employee_id'];
        if (!$isOwner) require_role(['Admin', 'HR'], $auth);

        $eStmt = $pdo->prepare(
            "SELECT e.*, d.department_name FROM employees e
             LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.employee_id = ?"
        );
        $eStmt->execute([(int)$ag['employee_id']]);
        $emp = $eStmt->fetch();
        if (!$emp) json_response(['error' => 'Employee not found.'], 404);

        $ref = $ag['reference'] ?: ('HRMS-' . date('Y') . '-' . str_pad((string)(int)$ag['employee_id'], 4, '0', STR_PAD_LEFT) . '-' . $id);
        $vars = agreement_vars($emp, $ref);
        if (!empty($ag['signed_at'])) {
            $vars['date'] = date('d F Y', strtotime($ag['signed_at']));
            $vars['signed_at'] = date('d M Y, h:i A', strtotime($ag['signed_at']));
        }
        $sigPath = $ag['status'] === 'signed' ? employee_signature_png($pdo, $emp) : null;

        $kind = agreement_template_kind($ag['file_path']);
        $html = null; $err = null; $sigData = null;
        if ($kind === 'html') {
            $html = agreement_fill_html(upload_abs($ag['file_path']), $vars, $sigPath, $err);
            if ($html === null) json_response(['error' => 'Cannot render: ' . $err], 500);
        }
        if ($kind === 'pdf' && $sigPath && is_file($sigPath)) {
            $raw = @file_get_contents($sigPath);
            $info = $raw !== false ? @getimagesize($sigPath) : false;
            if ($raw !== false && $info) $sigData = 'data:' . ($info['mime'] ?? 'image/png') . ';base64,' . base64_encode($raw);
        }

        json_response([
            'agreement' => [
                'agreement_id' => $id, 'status' => $ag['status'], 'reference' => $ref,
                'signed_at' => $ag['signed_at'], 'signed_file' => $ag['signed_file'],
                'template_name' => $ag['template_name'], 'template_kind' => $kind,
                'template_file' => $ag['file_path'],
                'employee_name' => $emp['full_name'], 'employee_code' => $emp['employee_code'],
            ],
            'html' => $html,
            'vars' => $kind === 'pdf' ? $vars : null,
            'signature' => $sigData,
        ]);
        break;
    }

    case 'agreements.file': {
        // Streams the template PDF or the archived signed PDF for one
        // agreement with CORS headers, so the browser can read the bytes.
        // ?which=template|signed   Auth: Admin/HR, or the owning employee.
        $auth = require_auth();
        $id = (int)($_GET['agreement_id'] ?? 0);
        $which = ($_GET['which'] ?? 'template') === 'signed' ? 'signed' : 'template';
        if (!$id) json_response(['error' => 'agreement_id required.'], 422);

        $st = $pdo->prepare(
            "SELECT a.employee_id, a.signed_file, t.file_path FROM agreements a
             JOIN agreement_templates t ON t.template_id = a.template_id
             WHERE a.agreement_id = ?"
        );
        $st->execute([$id]);
        $ag = $st->fetch();
        if (!$ag) json_response(['error' => 'Agreement not found.'], 404);
        $isOwner = !empty($auth['employee_id']) && (int)$auth['employee_id'] === (int)$ag['employee_id'];
        if (!$isOwner) require_role(['Admin', 'HR'], $auth);

        $rel = $which === 'signed' ? $ag['signed_file'] : $ag['file_path'];
        // Files made before the domain move sit in the old domain's folder;
        // look there too, the same way the PDF link (files.view) does.
        $abs = $rel ? upload_abs($rel) : '';
        if (!$rel || !is_file($abs)) {
            json_response(['error' => ($which === 'signed' ? 'The signed PDF' : 'The template file') . ' is recorded but missing on the server.'
                . ($which === 'signed' ? ' Use "Regenerate & save" to create it again.' : ' Replace the template file on the Agreements page.')], 404);
        }

        $ext = strtolower(pathinfo($abs, PATHINFO_EXTENSION));
        $mime = $ext === 'pdf' ? 'application/pdf' : ($ext === 'html' || $ext === 'htm' ? 'text/html; charset=UTF-8' : 'application/octet-stream');
        header('Content-Type: ' . $mime);
        header('Content-Length: ' . filesize($abs));
        header('Content-Disposition: inline; filename="' . basename($abs) . '"');
        header('Cache-Control: private, max-age=0, no-cache');
        readfile($abs);
        exit;
    }

    case 'agreements.upload_pdf': {
        // The browser posts back the PDF it generated from the HTML template.
        // Stored once; later views/downloads serve this archived file.
        $auth = require_auth();
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $id = (int)($_POST['agreement_id'] ?? 0);
        if (!$id) json_response(['error' => 'agreement_id required.'], 422);
        if (!isset($_FILES['pdf']) || $_FILES['pdf']['error'] !== UPLOAD_ERR_OK) json_response(['error' => 'PDF file missing.'], 422);

        $st = $pdo->prepare("SELECT employee_id, status, signed_file FROM agreements WHERE agreement_id = ?");
        $st->execute([$id]);
        $ag = $st->fetch();
        if (!$ag) json_response(['error' => 'Agreement not found.'], 404);
        if ($ag['status'] !== 'signed') json_response(['error' => 'Agreement is not signed yet.'], 409);

        $isOwner = !empty($auth['employee_id']) && (int)$auth['employee_id'] === (int)$ag['employee_id'];
        if (!$isOwner) require_role(['Admin', 'HR'], $auth);

        $head = (string)@file_get_contents($_FILES['pdf']['tmp_name'], false, null, 0, 5);
        if (strpos($head, '%PDF') !== 0) json_response(['error' => 'Uploaded file is not a PDF.'], 422);
        if ($_FILES['pdf']['size'] > 15 * 1024 * 1024) json_response(['error' => 'PDF too large (max 15MB).'], 422);

        $dir = __DIR__ . '/uploads/agreements/';
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $name = 'signed_' . $id . '_' . time() . '_' . bin2hex(random_bytes(3)) . '.pdf';
        if (!move_uploaded_file($_FILES['pdf']['tmp_name'], $dir . $name)) json_response(['error' => 'Could not save the PDF.'], 500);

        $pdo->prepare("UPDATE agreements SET signed_file = ? WHERE agreement_id = ?")->execute(['uploads/agreements/' . $name, $id]);
        if (!empty($ag['signed_file']) && file_exists(__DIR__ . '/' . $ag['signed_file'])) @unlink(__DIR__ . '/' . $ag['signed_file']);

        // The signed copy can now be emailed with the PDF inside.
        agreement_email_queue($pdo, $id, 'signed');
        [$mailed] = mail_process($pdo, 3);
        json_response(['message' => 'PDF saved.', 'signed_file' => 'uploads/agreements/' . $name, 'emailed' => $mailed > 0]);
        break;
    }

    case 'agreements.cancel': {
        // Admin/HR withdraws a pending signature request. Signed agreements
        // are never removed this way.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = (int)($input['agreement_id'] ?? 0);
        if (!$id) json_response(['error' => 'agreement_id required.'], 422);

        $st = $pdo->prepare("SELECT status FROM agreements WHERE agreement_id = ?");
        $st->execute([$id]);
        $row = $st->fetch();
        if (!$row) json_response(['error' => 'Agreement not found.'], 404);
        if ($row['status'] === 'signed') json_response(['error' => 'Already signed — it cannot be cancelled.'], 409);

        $pdo->prepare("DELETE FROM agreements WHERE agreement_id = ? AND status <> 'signed'")->execute([$id]);
        ensure_agreement_emails_table($pdo);
        $pdo->prepare("DELETE FROM agreement_emails WHERE agreement_id = ?")->execute([$id]);
        json_response(['message' => 'Request cancelled.']);
        break;
    }

    case 'agreements.mine': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);

        // Self-healing: pick up a signature uploaded as a document (or drawn
        // earlier) and clear anything still pending, so the employee never
        // sees a sign request.
        agreements_autosign_pending($pdo, (int)$auth['employee_id']);
        agreements_upgrade_docx_to_pdf($pdo);

        $stmt = $pdo->prepare(
            "SELECT a.agreement_id, a.status, a.signed_at, a.signed_file, a.reference, t.template_name, t.file_path AS template_file
             FROM agreements a JOIN agreement_templates t ON t.template_id = a.template_id
             WHERE a.employee_id = ? ORDER BY a.created_at DESC"
        );
        $stmt->execute([$auth['employee_id']]);
        $eRow = $pdo->prepare("SELECT * FROM employees WHERE employee_id = ?");
        $eRow->execute([$auth['employee_id']]);
        $empRow = $eRow->fetch() ?: ['employee_id' => $auth['employee_id']];
        $sigAbs = employee_signature_png($pdo, $empRow);
        $sigFile = $sigAbs ? str_replace(__DIR__ . '/', '', $sigAbs) : null;
        $rows = $stmt->fetchAll();
        $errs = agreement_errors_all();
        foreach ($rows as &$r) {
            $r['render_error'] = ($r['status'] !== 'signed' && isset($errs[(string)$r['agreement_id']])) ? $errs[(string)$r['agreement_id']]['error'] : null;
            $r['template_kind'] = agreement_template_kind((string)$r['template_file']);
            unset($r['template_file']);
        }
        unset($r);
        json_response(['agreements' => $rows, 'signature_file' => $sigFile]);
        break;
    }

    case 'signature.get': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $eRow = $pdo->prepare("SELECT * FROM employees WHERE employee_id = ?");
        $eRow->execute([$auth['employee_id']]);
        $empRow = $eRow->fetch() ?: ['employee_id' => $auth['employee_id']];
        $sigAbs = employee_signature_png($pdo, $empRow);
        json_response(['signature_file' => $sigAbs ? str_replace(__DIR__ . '/', '', $sigAbs) : null]);
        break;
    }

    case 'signature.save': {
        // Employee saves/updates their signature once; reused everywhere after.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $dataUrl = $input['signature'] ?? '';
        if (strpos($dataUrl, 'data:image/png;base64,') !== 0) json_response(['error' => 'Please draw your signature first.'], 422);
        $png = base64_decode(substr($dataUrl, strlen('data:image/png;base64,')));
        if ($png === false || strlen($png) > 2 * 1024 * 1024) json_response(['error' => 'Signature image invalid.'], 422);
        $dir = __DIR__ . '/uploads/agreements/';
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $rel = 'uploads/agreements/sig_' . (int)$auth['employee_id'] . '.png';
        file_put_contents(__DIR__ . '/' . $rel, $png);
        if ($HAS_SIG_COL) {
            try {
                $pdo->prepare("UPDATE employees SET signature_file = ? WHERE employee_id = ?")
                    ->execute([$rel, $auth['employee_id']]);
            } catch (PDOException $e) { /* cache only */ }
        }

        // Anything already waiting for this employee is signed right now with
        // the signature they just saved — they never see a "sign" request.
        $signed = agreements_autosign_pending($pdo, (int)$auth['employee_id']);

        json_response([
            'message' => $signed
                ? 'Signature saved. ' . $signed . ' document(s) signed automatically.'
                : 'Signature saved. It will be used automatically on your documents.',
            'signature_file' => $rel,
            'auto_signed' => $signed,
        ]);
        break;
    }

    case 'signature.reset': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $empId = (int)($input['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'employee_id required.'], 422);
        $cached = __DIR__ . '/uploads/agreements/sig_' . $empId . '.png';
        if (file_exists($cached)) @unlink($cached);
        if ($HAS_SIG_COL) {
            try {
                $st = $pdo->prepare("SELECT signature_file FROM employees WHERE employee_id = ?");
                $st->execute([$empId]);
                $f = $st->fetchColumn();
                if ($f && file_exists(__DIR__ . '/' . $f)) @unlink(__DIR__ . '/' . $f);
                $pdo->prepare("UPDATE employees SET signature_file = NULL WHERE employee_id = ?")->execute([$empId]);
            } catch (PDOException $e) { /* column absent */ }
        }
        json_response(['message' => 'Signature reset — the employee can draw a new one.']);
        break;
    }

    case 'agreements.sign': {
        // Employee submits their drawn signature (PNG data URL) for one agreement.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $agreementId = (int)($input['agreement_id'] ?? 0);
        $dataUrl = $input['signature'] ?? '';
        if (!$agreementId) json_response(['error' => 'agreement_id required.'], 422);

        $stmt = $pdo->prepare(
            "SELECT a.*, t.file_path, t.template_name FROM agreements a
             JOIN agreement_templates t ON t.template_id = a.template_id
             WHERE a.agreement_id = ? AND a.employee_id = ?"
        );
        $stmt->execute([$agreementId, $auth['employee_id']]);
        $ag = $stmt->fetch();
        if (!$ag) json_response(['error' => 'Agreement not found.'], 404);
        if ($ag['status'] === 'signed') json_response(['error' => 'This agreement is already signed.'], 409);

        $eStmt = $pdo->prepare(
            "SELECT e.*, d.department_name FROM employees e
             LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.employee_id = ?"
        );
        $eStmt->execute([$auth['employee_id']]);
        $emp = $eStmt->fetch();

        $dir = __DIR__ . '/uploads/agreements/';
        if (!is_dir($dir)) mkdir($dir, 0755, true);

        // Signature: a freshly drawn one wins; otherwise the Digital Signature
        // document / previously saved pad image via the resolver.
        $sigPath = $dir . 'sig_' . $auth['employee_id'] . '.png';
        if (strpos($dataUrl, 'data:image/png;base64,') === 0) {
            $png = base64_decode(substr($dataUrl, strlen('data:image/png;base64,')));
            if ($png === false || strlen($png) > 2 * 1024 * 1024) json_response(['error' => 'Signature image invalid.'], 422);
            file_put_contents($sigPath, $png);
            if ($HAS_SIG_COL) {
                try {
                    $pdo->prepare("UPDATE employees SET signature_file = ? WHERE employee_id = ?")
                        ->execute(['uploads/agreements/sig_' . $auth['employee_id'] . '.png', $auth['employee_id']]);
                } catch (PDOException $e) { /* cache only */ }
            }
        } else {
            $sigPath = employee_signature_png($pdo, $emp);
            if (!$sigPath) json_response(['error' => 'No signature on file — upload a Digital Signature document or draw one.'], 422);
        }

        $ref = 'HRMS-' . date('Y') . '-' . str_pad((string)$auth['employee_id'], 4, '0', STR_PAD_LEFT) . '-' . $agreementId;
        $vars = agreement_vars($emp, $ref);

        if (agreement_kind_is_browser(agreement_template_kind($ag['file_path']))) {
            agreement_mark_signed_html($pdo, $agreementId, $ref, false);
            agreement_email_queue($pdo, $agreementId, 'signed');
            json_response(['message' => 'Signed. Reference ' . $ref, 'file' => null]);
        }

        $outName = 'signed_' . $agreementId . '_' . time() . '.pdf';
        $why = null;
        $ok = agreement_pdf(upload_abs($ag['file_path']), $dir . $outName, $vars, $sigPath, $why);
        if (!$ok) json_response(['error' => 'Could not generate the signed document' . ($why ? ': ' . $why : '.')], 500);

        $pdo->prepare(
            "UPDATE agreements SET status = 'signed', signed_at = NOW(), signed_file = ?, reference = ?, signed_ip = ?, auto_signed = 0
             WHERE agreement_id = ?"
        )->execute(['uploads/agreements/' . $outName, $ref, $_SERVER['REMOTE_ADDR'] ?? '', $agreementId]);
        agreement_email_queue($pdo, $agreementId, 'signed');

        json_response([
            'message' => 'Signed. Reference ' . $ref,
            'file' => 'uploads/agreements/' . $outName,
        ]);
        break;
    }

    // ============== COMMISSION ==============
    case 'commission_rules.list': {
        // Read-only. The Targets, Performance and Salary pages need the rules
        // to show the commission estimate, so any role that can open those
        // pages may read them; changing them still needs the Commission
        // Rules module (checked on save/delete below).
        $auth = require_auth();
        $role = $auth['role'] ?? '';
        if (!in_array($role, ['Admin', 'HR'], true)
            && !user_can($auth, 'commission_rules') && !user_can($auth, 'targets')
            && !user_can($auth, 'performance') && !user_can($auth, 'salary') && !user_can($auth, 'commission')) {
            json_response(['error' => 'Forbidden.'], 403);
        }
        ensure_commission_rules_table($pdo);
        $rows = $pdo->query("SELECT * FROM commission_rules ORDER BY sort_order ASC, rule_id ASC")->fetchAll();
        json_response(['rules' => $rows]);
        break;
    }

    case 'commission_rules.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_commission_rules_table($pdo);
        $input = json_input();
        $id = (int)($input['rule_id'] ?? 0);
        $type = $input['rule_type'] ?? '';
        if (!in_array($type, ['base', 'prepaid', 'over_target'], true)) json_response(['error' => 'rule_type must be base, prepaid, or over_target.'], 422);
        $rate = isset($input['rate']) ? (float)$input['rate'] : null;
        if ($rate === null) json_response(['error' => 'rate is required.'], 422);

        $ticketMin = (float)($input['ticket_min'] ?? 0);
        $sortOrder = (int)($input['sort_order'] ?? 0);
        $label = trim((string)($input['label'] ?? '')) ?: null;
        $achievedTarget = null; $prepaidMin = null; $overPct = null;

        if ($type === 'base') {
            if (!isset($input['achieved_target'])) json_response(['error' => 'achieved_target (true/false) is required for a base rule.'], 422);
            $achievedTarget = !empty($input['achieved_target']) ? 1 : 0;
        } elseif ($type === 'prepaid') {
            if (!isset($input['prepaid_min'])) json_response(['error' => 'prepaid_min is required for a prepaid rule.'], 422);
            $prepaidMin = (float)$input['prepaid_min'];
        } else { // over_target
            if (!isset($input['over_pct'])) json_response(['error' => 'over_pct is required for an over-target rule.'], 422);
            $overPct = (float)$input['over_pct'];
        }

        if ($id) {
            $pdo->prepare(
                "UPDATE commission_rules SET rule_type=?, achieved_target=?, ticket_min=?, prepaid_min=?, over_pct=?, rate=?, sort_order=?, label=?
                 WHERE rule_id = ?"
            )->execute([$type, $achievedTarget, $ticketMin, $prepaidMin, $overPct, $rate, $sortOrder, $label, $id]);
        } else {
            $pdo->prepare(
                "INSERT INTO commission_rules (rule_type, achieved_target, ticket_min, prepaid_min, over_pct, rate, sort_order, label)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
            )->execute([$type, $achievedTarget, $ticketMin, $prepaidMin, $overPct, $rate, $sortOrder, $label]);
        }
        json_response(['message' => 'Rule saved.']);
        break;
    }

    case 'commission_rules.delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = (int)($input['rule_id'] ?? 0);
        if (!$id) json_response(['error' => 'rule_id required.'], 422);
        $pdo->prepare("DELETE FROM commission_rules WHERE rule_id = ?")->execute([$id]);
        json_response(['message' => 'Rule deleted.']);
        break;
    }

    // ---- Order-code commission rules (Commission Rules page) ----
    case 'commission_rules.code_list': {
        // Read-only, same audience as commission_rules.list (the Commission page needs it to price orders).
        $auth = require_auth();
        $role = $auth['role'] ?? '';
        if (!in_array($role, ['Admin', 'HR'], true)
            && !user_can($auth, 'commission_rules') && !user_can($auth, 'targets')
            && !user_can($auth, 'performance') && !user_can($auth, 'salary') && !user_can($auth, 'commission')) {
            json_response(['error' => 'Forbidden.'], 403);
        }
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'The order-code rules table could not be created — check the database user has CREATE rights.'], 500);
        $rows = $pdo->query("SELECT * FROM commission_code_rules ORDER BY sort_order ASC, rule_id ASC")->fetchAll();
        json_response([
            'on' => setting_get($pdo, 'commission_code_rules_on', '0') === '1',
            'rules' => array_map('commission_code_rule_out', $rows),
            'houses' => store_group_options(),
        ]);
        break;
    }

    case 'commission_rules.code_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code rules table.'], 500);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        $match = (string)($in['match_type'] ?? '');
        if (!in_array($match, ['no_code', 'has_code', 'prefix'], true)) json_response(['error' => 'Choose when the rule applies: no code, has a code, or code starts with.'], 422);
        $prefix = '';
        if ($match === 'prefix') {
            $prefix = strtoupper(trim((string)($in['prefix'] ?? '')));
            if (!preg_match('/^[A-Z0-9_-]{1,20}$/', $prefix)) json_response(['error' => 'Enter the start of the code (letters / numbers, up to 20), e.g. AG.'], 422);
        }
        $mode = (string)($in['pay_mode'] ?? 'pct');
        if (!in_array($mode, ['pct', 'flat', 'rate'], true)) json_response(['error' => 'Pay must be a % of the normal commission, a fixed rate %, or a flat ₹ per order.'], 422);
        if (!isset($in['pay_value']) || !is_numeric($in['pay_value'])) json_response(['error' => 'Enter how much the rule pays.'], 422);
        $val = round((float)$in['pay_value'], 2);
        if ($val < 0 || ($mode === 'pct' && $val > 500) || ($mode === 'rate' && $val > 100) || ($mode === 'flat' && $val > 100000)) json_response(['error' => $mode === 'pct' ? 'The share must be between 0% and 500%.' : ($mode === 'rate' ? 'The rate must be between 0% and 100%.' : 'The flat amount must be between ₹0 and ₹1,00,000.')], 422);
        $wTarget = (string)($in['when_target'] ?? 'any');
        if (!in_array($wTarget, ['any', 'hit', 'miss'], true)) json_response(['error' => 'Target condition must be any, achieved or not achieved.'], 422);
        $wTicket = (string)($in['when_ticket'] ?? 'any');
        if (!in_array($wTicket, ['any', 'lt', 'gte'], true)) json_response(['error' => 'Ticket condition must be any, below, or at least.'], 422);
        $wVal = 0.0;
        if ($wTicket !== 'any') {
            if (!isset($in['when_ticket_val']) || !is_numeric($in['when_ticket_val']) || (float)$in['when_ticket_val'] <= 0 || (float)$in['when_ticket_val'] > 1000000) json_response(['error' => 'Enter the ticket size amount for the condition (₹).'], 422);
            $wVal = round((float)$in['when_ticket_val'], 2);
        }
        $okHouses = array_keys(store_group_options());
        $houses = array_values(array_unique(array_filter((array)($in['houses'] ?? []), fn($h) => in_array($h, $okHouses, true))));
        $housesStr = implode(',', $houses);
        if (strlen($housesStr) > 80) json_response(['error' => 'Too many stores selected.'], 422);
        $label = mb_substr(trim((string)($in['label'] ?? '')), 0, 120);
        $enabled = !empty($in['enabled']) ? 1 : 0;
        if ($id) {
            $pdo->prepare("UPDATE commission_code_rules SET label=?, match_type=?, prefix=?, pay_mode=?, pay_value=?, houses=?, enabled=?, when_target=?, when_ticket=?, when_ticket_val=? WHERE rule_id=?")
                ->execute([$label, $match, $prefix, $mode, $val, $housesStr, $enabled, $wTarget, $wTicket, $wVal, $id]);
        } else {
            $max = (int)$pdo->query("SELECT COALESCE(MAX(sort_order), 0) FROM commission_code_rules")->fetchColumn();
            $pdo->prepare("INSERT INTO commission_code_rules (label, match_type, prefix, pay_mode, pay_value, houses, enabled, sort_order, when_target, when_ticket, when_ticket_val) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                ->execute([$label, $match, $prefix, $mode, $val, $housesStr, $enabled, $max + 10, $wTarget, $wTicket, $wVal]);
        }
        json_response(['message' => 'Rule saved.']);
        break;
    }

    case 'commission_rules.code_toggle': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code rules table.'], 500);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        if (!$id) json_response(['error' => 'rule_id required.'], 422);
        $pdo->prepare("UPDATE commission_code_rules SET enabled = ? WHERE rule_id = ?")->execute([!empty($in['enabled']) ? 1 : 0, $id]);
        json_response(['message' => !empty($in['enabled']) ? 'Rule is on.' : 'Rule is off.']);
        break;
    }

    case 'commission_rules.code_master': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        setting_set($pdo, 'commission_code_rules_on', !empty($in['on']) ? '1' : '0');
        json_response(['message' => !empty($in['on']) ? 'Order-code rules are ON.' : 'Order-code rules are OFF — every order earns the normal commission.']);
        break;
    }

    case 'commission_rules.code_move': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code rules table.'], 500);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        $dir = (string)($in['dir'] ?? '');
        if (!$id || !in_array($dir, ['up', 'down'], true)) json_response(['error' => 'rule_id and dir (up/down) required.'], 422);
        $ids = array_map('intval', $pdo->query("SELECT rule_id FROM commission_code_rules ORDER BY sort_order ASC, rule_id ASC")->fetchAll(PDO::FETCH_COLUMN));
        $i = array_search($id, $ids, true);
        if ($i === false) json_response(['error' => 'Rule not found.'], 404);
        $j = $dir === 'up' ? $i - 1 : $i + 1;
        if ($j >= 0 && $j < count($ids)) { [$ids[$i], $ids[$j]] = [$ids[$j], $ids[$i]]; }
        $up = $pdo->prepare("UPDATE commission_code_rules SET sort_order = ? WHERE rule_id = ?");
        foreach ($ids as $n => $rid) $up->execute([($n + 1) * 10, $rid]);
        json_response(['message' => 'Order changed.']);
        break;
    }

    case 'commission_rules.code_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code rules table.'], 500);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        if (!$id) json_response(['error' => 'rule_id required.'], 422);
        $pdo->prepare("DELETE FROM commission_code_rules WHERE rule_id = ?")->execute([$id]);
        json_response(['message' => 'Rule deleted.']);
        break;
