    }
    case 'combo_price.save': {
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR'], true) && !user_can($auth, 'commission_rules')) json_response(['error' => 'Only Admin / HR can change the combo prices.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $chart = $in['chart'] ?? null;
        if (!is_array($chart)) json_response(['error' => 'Nothing to save.'], 422);
        [$clean, $err] = combo_price_clean($chart);
        if ($err) json_response(['error' => $err], 422);
        $clean['updated_at'] = date('Y-m-d H:i:s');
        $clean['updated_by'] = (string)($auth['full_name'] ?? $auth['username'] ?? '');
        setting_set($pdo, 'combo_price_chart', json_encode($clean, JSON_UNESCAPED_UNICODE));
        json_response(['message' => 'Combo prices saved.', 'chart' => array_merge(combo_price_default(), $clean)]);
        break;
