        $in = json_input();
        $probe = ['base' => (array)($in['base'] ?? []), 'rows' => [['gel' => 1, 'perf' => 1, 'p' => [1, 1, 1, 1, 1]]]];
        [$c, $err] = combo_price_clean($probe);
        if ($err) json_response(['error' => $err], 422);
        json_response(['base' => $c['base'], 'rows' => combo_price_build($c['base'])]);
        break;
