        break;
    }
    case 'ml_slab.save': {
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR'], true) && !user_can($auth, 'commission_rules')) json_response(['error' => 'Only Admin / HR can change the ML price slab.'], 403);
        $input = json_input();
