        setting_set($pdo, 'ml_slab_chart', json_encode($chart, JSON_UNESCAPED_UNICODE));
        json_response(['message' => $chart['on'] ? 'Saved — the ML price slab is ON.' : 'Saved — the ML price slab is OFF.', 'chart' => ml_slab_cap(array_merge(ml_slab_default(), $chart, ['special' => ml_slab_special_get($pdo)]))]);
        break;
    }
    case 'ml_slab.special_save':
    case 'ml_slab.special_delete': {
        // "📅 Specific date / person": add / change / delete one special day. Same permission as saving the chart.
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR'], true) && !user_can($auth, 'commission_rules')) json_response(['error' => 'Only Admin / HR can change special days.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $list = ml_slab_special_get($pdo);
        $id = (string)($in['id'] ?? '');
        if ($action === 'ml_slab.special_delete') {
            $list = array_values(array_filter($list, fn($x) => (string)($x['id'] ?? '') !== $id));
            $msg = 'Special day deleted.';
        } else {
            [$x, $err] = ml_slab_special_clean((array)($in['special'] ?? []));
            if ($err) json_response(['error' => $err], 422);
            $x['by'] = (string)($auth['full_name'] ?? $auth['username'] ?? ''); $x['at'] = date('Y-m-d H:i:s');
            $found = false;
            if ($id !== '') foreach ($list as $i => $y) if ((string)($y['id'] ?? '') === $id) { $list[$i] = ['id' => $id] + $x; $found = true; }
            if (!$found) $list[] = ['id' => substr(bin2hex(random_bytes(6)), 0, 10)] + $x;
            if (count($list) > 300) json_response(['error' => 'Too many special days — delete some old ones first.'], 422);
            $msg = $found ? 'Special day updated.' : 'Special day saved.';
        }
        setting_set($pdo, 'ml_slab_special', json_encode(array_values($list), JSON_UNESCAPED_UNICODE));
        json_response(['message' => $msg, 'special' => array_values($list)]);
        break;
