    case 'ml_slab.people': {
        // Sales employees for the special-day picker.
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR'], true) && !user_can($auth, 'commission_rules')) json_response(['error' => 'Forbidden.'], 403);
        $rows = [];
        foreach ($pdo->query("SELECT e.employee_id, e.full_name, d.department_name FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex' ORDER BY e.full_name")->fetchAll() as $e) {
            if (stripos((string)$e['department_name'], 'sales') === false) continue;
            $rows[] = ['id' => (int)$e['employee_id'], 'name' => trim((string)$e['full_name'])];
        }
        json_response(['people' => $rows]);
        break;
    }
    case 'flash_offer.get': {
        // ⚡ Flash Offer banner (My Sales, Order Allocation) + the admin card on the Commission Rules page. Every logged-in user may read it.
        require_auth();
        $list = flash_offer_list_get($pdo);
        usort($list, fn($a, $b) => strtotime((string)($b['started_at'] ?? '')) <=> strtotime((string)($a['started_at'] ?? '')));
        json_response(['running' => flash_offer_running($list), 'history' => array_slice($list, 0, 10), 'all' => $list, 'now' => date('Y-m-d H:i:s')]);      // 'all' = every offer's window, so the Commission / My Sales pages can price past orders too
        break;
    }
    case 'flash_offer.start': {
        // Admin/HR: start a new flash offer right now. Several can run at the same time — each only matches its own
        // sizes (flash_offer_pct_for() matches by ML only), so two running offers may not share a size (checked below).
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR'], true) && !user_can($auth, 'commission_rules')) json_response(['error' => 'Only Admin / HR can start a flash offer.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        [$clean, $err] = flash_offer_clean(json_input());
        if ($err) json_response(['error' => $err], 422);
        $list = flash_offer_list_get($pdo);
        $now = time();
        foreach (flash_offer_running($list) as $ro) {
            foreach ((array)($ro['items'] ?? []) as $ri) {
                foreach ($clean['items'] as $ni) {
                    if ((int)($ri['ml'] ?? 0) === (int)$ni['ml']) {
                        json_response(['error' => $ni['ml'] . ' ml is already in a running offer' . (($ro['note'] ?? '') !== '' ? ' ("' . $ro['note'] . '")' : '') . ' — an order is matched by its size, so stop that offer first, or remove this size.'], 422);
                    }
                }
            }
        }
        $clean['id'] = substr(bin2hex(random_bytes(6)), 0, 10);
        $clean['started_at'] = date('Y-m-d H:i:s', $now);
        $clean['ends_at'] = date('Y-m-d H:i:s', $now + (int)round($clean['hours'] * 3600));
        $clean['status'] = 'running';
        $clean['by'] = (string)($auth['full_name'] ?? $auth['username'] ?? '');
        $list[] = $clean;
        flash_offer_list_set($pdo, $list);
        json_response(['message' => 'Flash offer started — ' . $clean['hours'] . ' h at ' . $clean['pct'] . '% (with a code), ' . round($clean['pct'] * $clean['nocode'] / 100, 2) . '% (no code).', 'running' => $clean]);
        break;
    }
    case 'flash_offer.stop': {
        // Admin/HR: end the running offer early (orders already sold inside it keep their flat %, for good).
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR'], true) && !user_can($auth, 'commission_rules')) json_response(['error' => 'Only Admin / HR can stop a flash offer.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $id = (string)(json_input()['id'] ?? '');
        $list = flash_offer_list_get($pdo);
        $now = date('Y-m-d H:i:s'); $found = false;
        foreach ($list as &$x) if ((string)($x['id'] ?? '') === $id && ($x['status'] ?? '') !== 'stopped') { $x['status'] = 'stopped'; $x['ends_at'] = $now; $found = true; }
        unset($x);
        if (!$found) json_response(['error' => 'That offer is not running.'], 404);
        flash_offer_list_set($pdo, $list);
        json_response(['message' => 'Flash offer stopped.']);
        break;
    }
    case 'commission_rules.manual_list': {
        $auth = require_auth();
        $role = $auth['role'] ?? '';
        if (!in_array($role, ['Admin', 'HR'], true)
            && !user_can($auth, 'commission_rules') && !user_can($auth, 'targets')
            && !user_can($auth, 'performance') && !user_can($auth, 'salary') && !user_can($auth, 'commission')) {
            json_response(['error' => 'Forbidden.'], 403);
        }
        if (!ensure_commission_manual_tables($pdo)) json_response(['error' => 'The manual commission rules tables could not be created — check the database user has CREATE rights.'], 500);
        $mix = $pdo->query("SELECT rule_id, label, op, thr_pct, pay_mode, pay_value, who, enabled, grp, date_from, date_to FROM commission_mix_rules ORDER BY rule_id ASC")->fetchAll();
        $fx = $pdo->query("SELECT plan_id, employee_id, pay_mode, per_order, min_type, min_value, enabled, grp, date_from, date_to FROM commission_fixed_plans ORDER BY plan_id ASC")->fetchAll();
        $star = $pdo->query("SELECT rule_id, label, max_star, pay_pct, nocode_pct, who, enabled, grp, date_from, date_to FROM commission_star_rules ORDER BY max_star ASC, rule_id ASC")->fetchAll();
        $panelRows = $pdo->query("SELECT rule_id, label, panels, date_from, date_to, pct, who, enabled, grp FROM commission_panel_rules ORDER BY date_from DESC, rule_id DESC")->fetchAll();
        // sales people, for the "Applies to" / "Add person" lists on the Commission Rules page
        $empList = [];
        try {
            foreach ($pdo->query("SELECT e.employee_id, e.full_name, e.designation, e.sales_tag, d.department_name FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex' ORDER BY e.full_name")->fetchAll() as $er) {
                if (sales_commission_ok($er)) $empList[] = ['employee_id' => (int)$er['employee_id'], 'full_name' => (string)$er['full_name']];
            }
        } catch (PDOException $e) {}
        $bonus = [];
        if (ensure_commission_bonus_table($pdo)) {
            try { foreach ($pdo->query("SELECT rule_id, label, who, tiers, enabled, date_from, date_to, all_sales FROM commission_bonus_rules ORDER BY rule_id ASC")->fetchAll() as $br) {
