        $mode = (string)($in['pay_mode'] ?? 'full');
        if (!in_array($mode, ['full', 'rate', 'pct', 'flat'], true)) json_response(['error' => 'Choose how the rule pays: full commission, a fixed % of sales, a % of the normal commission, or ₹ per order.'], 422);
        $val = 0.0;
        if ($mode !== 'full') {
            if (!isset($in['pay_value']) || !is_numeric($in['pay_value'])) json_response(['error' => 'Enter how much the rule pays.'], 422);
            $val = round((float)$in['pay_value'], 2);
            if ($val < 0 || ($mode === 'rate' && $val > 100) || ($mode === 'pct' && $val > 500) || ($mode === 'flat' && $val > 100000)) {
                json_response(['error' => $mode === 'rate' ? 'A fixed commission % must be between 0 and 100.' : ($mode === 'pct' ? 'The share of the normal commission must be between 0% and 500%.' : 'The amount per order must be between ₹0 and ₹1,00,000.')], 422);
            }
        }
        $who = implode(',', array_values(array_unique(array_filter(array_map('intval', (array)($in['who'] ?? []))))));
        if (strlen($who) > 1000) json_response(['error' => 'Too many people selected — choose Everyone instead.'], 422);
        $label = mb_substr(trim((string)($in['label'] ?? '')), 0, 120);
        $en = !empty($in['enabled']) ? 1 : 0;
        $grp = commission_rule_grp($in);
        [$dFrom, $dTo, $dErr] = commission_rule_dates($in);
        if ($dErr !== '') json_response(['error' => $dErr], 422);
        if ($id) {
            $pdo->prepare("UPDATE commission_mix_rules SET label = ?, op = ?, thr_pct = ?, pay_mode = ?, pay_value = ?, who = ?, enabled = ?, grp = ?, date_from = ?, date_to = ? WHERE rule_id = ?")->execute([$label, $op, $thr, $mode, $val, $who, $en, $grp, $dFrom, $dTo, $id]);
        } else {
            if ((int)$pdo->query("SELECT COUNT(*) FROM commission_mix_rules")->fetchColumn() >= 20) json_response(['error' => 'Up to 20 rules.'], 422);
            $pdo->prepare("INSERT INTO commission_mix_rules (label, op, thr_pct, pay_mode, pay_value, who, enabled, grp, date_from, date_to) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")->execute([$label, $op, $thr, $mode, $val, $who, $en, $grp, $dFrom, $dTo]);
