        if (!$all && !$who) json_response(['error' => 'Choose at least one person, or choose Everyone.'], 422);
        [$tiers, $terr] = commission_bonus_tiers($in['tiers'] ?? []); if ($terr !== '') json_response(['error' => $terr], 422);
        [$dFrom, $dTo, $dErr] = commission_rule_dates($in); if ($dErr !== '') json_response(['error' => $dErr], 422);
        if ($dFrom === null) json_response(['error' => 'Choose the starting date. A target bonus needs a period.'], 422);
        $en = array_key_exists('enabled', $in) ? (!empty($in['enabled']) ? 1 : 0) : 1; $by = (string)($auth['username'] ?? '');
        if ($id) $pdo->prepare("UPDATE commission_bonus_rules SET label = ?, who = ?, tiers = ?, enabled = ?, date_from = ?, date_to = ?, set_by = ?, all_sales = ? WHERE rule_id = ?")->execute([$label, implode(',', $who), json_encode($tiers), $en, $dFrom, $dTo, $by, $all, $id]);
        else $pdo->prepare("INSERT INTO commission_bonus_rules (label, who, tiers, enabled, date_from, date_to, set_by, all_sales) VALUES (?,?,?,?,?,?,?,?)")->execute([$label, implode(',', $who), json_encode($tiers), $en, $dFrom, $dTo, $by, $all]);
