    case 'commission_rules.fixed_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_manual_tables($pdo)) json_response(['error' => 'Could not create the manual rules table.'], 500);
        $in = json_input();
        $emp = (int)($in['employee_id'] ?? 0);
        if (!$emp) json_response(['error' => 'Choose the employee.'], 422);
        $chk = $pdo->prepare("SELECT 1 FROM employees WHERE employee_id = ?");
        $chk->execute([$emp]);
        if (!$chk->fetchColumn()) json_response(['error' => 'Employee not found.'], 404);
        $pmode = ($in['pay_mode'] ?? 'rate') === 'flat' ? 'flat' : 'rate';
        if (!isset($in['per']) || !is_numeric($in['per']) || (float)$in['per'] < 0 || (float)$in['per'] > ($pmode === 'rate' ? 100 : 100000)) json_response(['error' => $pmode === 'rate' ? 'Fixed commission must be between 0% and 100% of sales.' : 'Fixed commission per order must be between ₹0 and ₹1,00,000.'], 422);
        $minType = (string)($in['min_type'] ?? 'count');
        if (!in_array($minType, ['count', 'amount'], true)) json_response(['error' => 'The minimum must be a number of orders or an achieved amount.'], 422);
        $minRaw = $in['min'] ?? '';   // the minimum is optional: blank / 0 = no minimum, the option is never locked
        if ($minRaw !== '' && $minRaw !== null && (!is_numeric($minRaw) || (float)$minRaw < 0 || (float)$minRaw > 100000000)) json_response(['error' => 'The minimum must be a number (or leave it blank for no minimum).'], 422);
        $per = round((float)$in['per'], 2);
        $min = ($minRaw === '' || $minRaw === null) ? 0.0 : round((float)$minRaw, 2);
        $en = !empty($in['enabled']) ? 1 : 0;
        $grp = commission_rule_grp($in);
        [$dFrom, $dTo, $dErr] = commission_rule_dates($in);
        if ($dErr !== '') json_response(['error' => $dErr], 422);
        // one plan per person: saving again for the same employee updates it
        $pdo->prepare(
            "INSERT INTO commission_fixed_plans (employee_id, per_order, pay_mode, min_type, min_value, enabled, grp, date_from, date_to) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE per_order = VALUES(per_order), pay_mode = VALUES(pay_mode), min_type = VALUES(min_type), min_value = VALUES(min_value), enabled = VALUES(enabled), grp = VALUES(grp), date_from = VALUES(date_from), date_to = VALUES(date_to)"
        )->execute([$emp, $per, $pmode, $minType, $min, $en, $grp, $dFrom, $dTo]);
        json_response(['message' => 'Saved.']);
        break;
    }

