    // ---- One order's share set by hand (Commission page, Order-wise view) ----
    case 'commission_page.order_shares': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code tables.'], 500);
        $from = (string)($_GET['date_from'] ?? ''); $to = (string)($_GET['date_to'] ?? '');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        $st = $pdo->prepare("SELECT order_key, share_pct, pay_mode, reason, set_by, set_at FROM commission_order_share WHERE order_day BETWEEN ? AND ?");
        $st->execute([$from, $to]);
        $out = [];
        foreach ($st->fetchAll() as $r) $out[$r['order_key']] = ['share_pct' => (float)$r['share_pct'], 'mode' => (string)$r['pay_mode'], 'reason' => (string)$r['reason'], 'set_by' => (string)$r['set_by'], 'set_at' => (string)$r['set_at']];
        json_response(['shares' => (object)$out]);
        break;
    }

    case 'commission_page.order_share_set': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code tables.'], 500);
        $in = json_input();
        $key = trim((string)($in['order_key'] ?? ''));
        if (!preg_match('/^[A-Za-z0-9_]{1,30}:[A-Za-z0-9_.-]{1,40}$/', $key)) json_response(['error' => 'Unknown order.'], 422);
        $day = (string)($in['order_day'] ?? '');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $day)) json_response(['error' => 'order_day must be YYYY-MM-DD.'], 422);
        $mode = (string)($in['pay_mode'] ?? 'pct');
        if (!in_array($mode, ['pct', 'rate', 'flat'], true)) json_response(['error' => 'Unknown commission type.'], 422);
        if (!isset($in['share_pct']) || !is_numeric($in['share_pct'])) json_response(['error' => $mode === 'flat' ? 'Enter the commission amount (₹).' : ($mode === 'rate' ? 'Enter the rate (0–100 %).' : 'Enter the share (0–500 %).')], 422);
        $pct = round((float)$in['share_pct'], 2);
        if ($mode === 'pct' && ($pct < 0 || $pct > 500)) json_response(['error' => 'The share must be between 0% and 500%.'], 422);
        if ($mode === 'rate' && ($pct < 0 || $pct > 100)) json_response(['error' => 'The rate must be between 0% and 100% of the order.'], 422);
        if ($mode === 'flat' && ($pct < 0 || $pct > 99999)) json_response(['error' => 'The amount must be between ₹0 and ₹99,999.'], 422);
        $reason = mb_substr(trim((string)($in['reason'] ?? '')), 0, 255);
        $pdo->prepare(
            "INSERT INTO commission_order_share (order_key, order_day, share_pct, pay_mode, reason, set_by) VALUES (?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE order_day = VALUES(order_day), share_pct = VALUES(share_pct), pay_mode = VALUES(pay_mode), reason = VALUES(reason), set_by = VALUES(set_by), set_at = CURRENT_TIMESTAMP"
        )->execute([$key, $day, $pct, $mode, $reason, (string)($auth['username'] ?? 'admin')]);
        json_response(['message' => 'Order commission saved.']);
        break;
    }

    case 'commission_page.order_share_clear': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_code_tables($pdo)) json_response(['error' => 'Could not create the order-code tables.'], 500);
        $in = json_input();
        $key = trim((string)($in['order_key'] ?? ''));
        if ($key === '') json_response(['error' => 'order_key required.'], 422);
        $pdo->prepare("DELETE FROM commission_order_share WHERE order_key = ?")->execute([$key]);
        json_response(['message' => 'Manual share removed — the rules apply again.']);
        break;
    }

    case 'commission_page.manual_list': {
        // Commission page: the commissions set by hand for one month, keyed "employee_id|row_key".
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $month = (string)($_GET['month'] ?? ($_GET['day'] ?? ''));   // YYYY-MM = the month's commission, YYYY-MM-DD = that day's (Today table)
        if (!preg_match('/^\d{4}-\d{2}(-\d{2}(_\d{4}-\d{2}-\d{2})?)?$/', $month)) json_response(['error' => 'month must be YYYY-MM (or day YYYY-MM-DD).'], 422);
        if (!ensure_commission_manual_table($pdo)) json_response(['error' => 'Could not create the manual commission table.'], 500);
        $st = $pdo->prepare("SELECT employee_id, row_key, rate, amount, reason, set_by, set_at FROM commission_manual WHERE month = ?");
        $st->execute([$month]);
        $out = [];
        foreach ($st->fetchAll() as $r) $out[(int)$r['employee_id'] . '|' . $r['row_key']] = ['rate' => (float)$r['rate'], 'amount' => (float)$r['amount'], 'reason' => (string)$r['reason'], 'set_by' => (string)$r['set_by'], 'set_at' => (string)$r['set_at']];
        json_response(['manual' => (object)$out]);
        break;
    }

    case 'commission_page.manual_set': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_commission_manual_table($pdo)) json_response(['error' => 'Could not create the manual commission table.'], 500);
        $in = json_input();
        $month = (string)($in['month'] ?? ($in['day'] ?? '')); $empId = (int)($in['employee_id'] ?? 0); $rk = (string)($in['row_key'] ?? '');
        if (!preg_match('/^\d{4}-\d{2}(-\d{2}(_\d{4}-\d{2}-\d{2})?)?$/', $month) || !$empId) json_response(['error' => 'month (or day) and employee_id required.'], 422);
        if (!in_array($rk, ['', 'tmsg'], true)) json_response(['error' => 'Unknown panel row.'], 422);
        if (!isset($in['amount']) || !is_numeric($in['amount']) || !isset($in['rate']) || !is_numeric($in['rate'])) json_response(['error' => 'Enter the rate or the amount.'], 422);
        $amount = round((float)$in['amount'], 2); $rate = round((float)$in['rate'], 2);
        if ($amount < 0 || $amount > 99999999) json_response(['error' => 'The amount must be between ₹0 and ₹9,99,99,999.'], 422);
        if ($rate < 0 || $rate > 999.99) json_response(['error' => 'The rate must be between 0% and 999.99%.'], 422);
        $reason = mb_substr(trim((string)($in['reason'] ?? '')), 0, 255);
        $pdo->prepare(
            "INSERT INTO commission_manual (month, employee_id, row_key, rate, amount, reason, set_by) VALUES (?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE rate = VALUES(rate), amount = VALUES(amount), reason = VALUES(reason), set_by = VALUES(set_by), set_at = CURRENT_TIMESTAMP"
        )->execute([$month, $empId, $rk, $rate, $amount, $reason, (string)($auth['username'] ?? 'admin')]);
        json_response(['message' => 'Manual commission saved.']);
        break;
    }

