        if (!ensure_commission_manual_table($pdo)) json_response(['error' => 'Could not create the manual commission table.'], 500);
        $in = json_input();
        $month = (string)($in['month'] ?? ($in['day'] ?? '')); $empId = (int)($in['employee_id'] ?? 0); $rk = (string)($in['row_key'] ?? '');
        if (!preg_match('/^\d{4}-\d{2}(-\d{2}(_\d{4}-\d{2}-\d{2})?)?$/', $month) || !$empId) json_response(['error' => 'month (or day) and employee_id required.'], 422);
        $pdo->prepare("DELETE FROM commission_manual WHERE month = ? AND employee_id = ? AND row_key = ?")->execute([$month, $empId, $rk]);
