    case 'commission.get': {
        // Computed commission for every sales employee, one row per house
        // they belong to, using whatever commission_rules currently say.
        // Nothing is stored unless commission.override is called — reopening
        // this page always reflects the latest rules and synced order data.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $month = $_GET['month'] ?? date('Y-m');
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $groupFilter = normalize_group_key($_GET['store_group'] ?? '');
        $rows = commission_rows_compute($pdo, $month, $groupFilter);
        $pen = [];
        try { $pen = penalty_commission_map($pdo, $month); } catch (Throwable $e) { $pen = []; }
        foreach ($rows as &$r) { $r['penalty_total'] = $pen[(int)$r['employee_id']]['total'] ?? 0; }
        unset($r);
        json_response(['month' => $month, 'rows' => $rows, 'penalties' => $pen]);
        break;
    }

    case 'commission_page.days': {
        // Commission page: for every sales employee and business day of the range, the TARGET of that day (the figure the
        // Orders page Employee sheet shows: set by hand -> new-executive ladder -> automatic rule -> monthly / profile target,
        // nothing on an Absent day) and the attendance state (present / absent / leave / half_leave / wfh / holiday / week_off).
        // Orders, tickets, prepaid share and the commission itself are worked out in the browser from the orders it loads
        // (shopify.orders), the same way the Targets page does it. rule=1 also applies the automatic target rule (slower).
        // Target rows: '' = TM Perfume House only; 'tm4u' and 'tmsg' (TM Shower Gel) are each their own row.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $today = biz_today($pdo);
        $to = trim((string)($_GET['date_to'] ?? $today));
        $from = trim((string)($_GET['date_from'] ?? (substr($to, 0, 7) . '-01')));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        if ($from > $to) json_response(['error' => 'From date must be before To date.'], 422);
        if ((int)round((strtotime($to) - strtotime($from)) / 86400) + 1 > 93) json_response(['error' => 'Pick at most 93 days.'], 422);
        $emps = array_values(array_filter($pdo->query(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.basic_salary, e.designation, e.joining_date, e.sales_tag, d.department_name
             FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex' ORDER BY e.full_name"
        )->fetchAll(), fn($r) => sales_commission_ok($r)));
        $tg = team_range_targets($pdo, $emps, $from, $to, !empty($_GET['rule']), true);      // combine: ONE automatic target per person, like the Targets page
        $present = attendance_present_map($pdo, $from, $to);
        $marks = day_marks_between($pdo, $from, $to);
        $days = [];
        for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) $days[] = $d;
        $roleLabel = ['executive' => 'Sales Executive', 'head' => 'Sales Head', 'helper' => 'Sales Helper'];
        $out = [];
        foreach ($emps as $e) {
            $id = (int)$e['employee_id'];
            $t = ['' => [], 'tm4u' => [], 'tmsg' => []];
            $parts = ['' => [], 'tm4u' => [], 'tmsg' => []];      // what each panel adds to the target, and where it came from (the Target breakdown on the page)
            foreach (($tg['panels'][$id] ?? []) as $gk => $x) {
                $rk = in_array($gk, ['tm4u', 'tmsg'], true) ? $gk : '';      // '' = TM Perfume House only; the other panels are their own rows
                foreach (($x['by_day'] ?? []) as $d => $v) $t[$rk][$d] = ($t[$rk][$d] ?? 0) + (float)$v;
                $pd = []; $ps = [];
                foreach (($x['by_day'] ?? []) as $d => $v) if ((float)$v > 0) { $pd[$d] = round((float)$v); $ps[$d] = ($x['by_day_src'][$d] ?? 'none'); }
                if ($pd) $parts[$rk][] = ['panel' => $gk, 'by_day' => (object)$pd, 'src' => (object)$ps];
            }
            $st = [];
            foreach ($days as $d) {
                $m = $marks[$d . '|' . $id] ?? '';
                if ($m !== '') $st[$d] = $m;
                elseif (!empty($present[$id][$d])) $st[$d] = 'present';
                elseif ($d <= $today) $st[$d] = 'absent';
            }
            $out[] = [
                'employee_id' => $id, 'full_name' => $e['full_name'], 'employee_code' => $e['employee_code'],
                'role' => $roleLabel[sales_role_kind($e['department_name'] ?? '', $e['designation'] ?? '')] ?? 'Sales',
                'target' => ['' => (object)$t[''], 'tm4u' => (object)$t['tm4u'], 'tmsg' => (object)$t['tmsg']], 'parts' => $parts, 'status' => (object)$st,
            ];
        }
        json_response(['from' => $from, 'to' => $to, 'today' => $today, 'rule_used' => !empty($tg['rule_used']), 'note' => $tg['note'], 'employees' => $out]);
        break;
    }

    case 'commission.override': {
        // Admin/HR sets (or clears, with rate="") a manual commission number
        // for one employee+house+month that wins over the automatic calc.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $month = $input['month'] ?? '';
        $empId = (int)($input['employee_id'] ?? 0);
        $groupKey = normalize_group_key($input['group_key'] ?? ($input['store_group'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}$/', $month) || !$empId) json_response(['error' => 'month and employee_id required.'], 422);

        try {
            $pdo->exec(
                "CREATE TABLE IF NOT EXISTS commission_overrides (
                    month CHAR(7) NOT NULL, employee_id INT NOT NULL, group_key VARCHAR(10) NOT NULL DEFAULT '',
                    rate DECIMAL(5,2) NOT NULL, commission_amount DECIMAL(12,2) NOT NULL,
                    manual_override TINYINT(1) NOT NULL DEFAULT 1, set_by VARCHAR(100) NULL,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    PRIMARY KEY (month, employee_id, group_key)
                )"
            );
            ensure_group_key_column($pdo, 'commission_overrides', ['month', 'employee_id']);
        } catch (PDOException $e) {
            json_response(['error' => 'Could not prepare override storage.'], 500);
        }

        if (($input['rate'] ?? '') === '' && !isset($input['commission_amount'])) {
            $pdo->prepare("DELETE FROM commission_overrides WHERE month = ? AND employee_id = ? AND group_key = ?")->execute([$month, $empId, $groupKey]);
            json_response(['message' => 'Override cleared — using the automatic calculation again.']);
        }

        $rate = (float)($input['rate'] ?? 0);
        $amount = (float)($input['commission_amount'] ?? 0);
        $pdo->prepare(
            "INSERT INTO commission_overrides (month, employee_id, group_key, rate, commission_amount, set_by)
             VALUES (?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE rate = VALUES(rate), commission_amount = VALUES(commission_amount), set_by = VALUES(set_by)"
        )->execute([$month, $empId, $groupKey, $rate, $amount, $auth['username']]);
        json_response(['message' => 'Manual commission saved.']);
        break;
    }

