    case 'salary_rules.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = (int)($input['rule_id'] ?? 0);
        $type = $input['rule_type'] ?? '';
        $value = (float)($input['value'] ?? -1);
        $occurrence = isset($input['occurrence']) && $input['occurrence'] !== '' ? (int)$input['occurrence'] : null;
        if (!in_array($type, ['free_leave', 'wfh'], true)) json_response(['error' => 'rule_type must be free_leave or wfh.'], 422);
        if ($value < 0) json_response(['error' => 'Enter a valid value.'], 422);
        if ($type === 'wfh') {
            if (!$occurrence || $occurrence < 1) json_response(['error' => 'WFH rules need a day number (1, 2, 3...).'], 422);
            if ($value > 100) json_response(['error' => 'WFH percent cannot exceed 100.'], 422);
        } else {
            $occurrence = null;
        }
        if ($id) {
            $pdo->prepare("UPDATE salary_rules SET rule_type = ?, occurrence = ?, value = ? WHERE rule_id = ?")
                ->execute([$type, $occurrence, $value, $id]);
        } else {
            $dup = $pdo->prepare("SELECT rule_id FROM salary_rules WHERE rule_type = ? AND (occurrence <=> ?)");
            $dup->execute([$type, $occurrence]);
            if ($dup->fetchColumn()) json_response(['error' => 'That rule already exists — edit it instead.'], 409);
            $pdo->prepare("INSERT INTO salary_rules (rule_type, occurrence, value) VALUES (?, ?, ?)")
                ->execute([$type, $occurrence, $value]);
        }
        json_response(['message' => 'Rule saved.']);
        break;
    }

