        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $empId = (int)($in['employee_id'] ?? 0);
        $gk = normalize_group_key((string)($in['group_key'] ?? ''));
        $color = trim((string)($in['color'] ?? ''));
