        }
        json_response(['message' => $color === '' ? 'Colour cleared.' : 'Colour saved.']);
        break;
    }

    case 'queries.assign_list': {
        // House-wise: each employee gets one entry per store group they
        // belong to (TM Perfume House / TM4U), each with its
        // own independent query/scout/champion counts for the day. An
        // employee with no house assigned yet falls back to a single
        // "ungrouped" bucket so old data keeps working. Selecting one house
        // via store_group narrows both which employees appear AND which
        // single house's numbers are shown for them.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        $groupFilter = normalize_group_key($_GET['store_group'] ?? '');
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);

        [$sgSql, $sgParams] = store_group_filter_sql($pdo, $groupFilter);
        $stmt = $pdo->prepare(
            "SELECT e.employee_id, e.full_name, e.employee_code
             FROM employees e
             JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex' AND d.department_name LIKE '%sales%'$sgSql
             ORDER BY e.employee_code"
        );
        $stmt->execute($sgParams);
        $emps = $stmt->fetchAll();
        if (!$emps) json_response(['date' => $date, 'employees' => []]);

        $ids = array_column($emps, 'employee_id');
        $in = implode(',', array_fill(0, count($ids), '?'));

        // Each employee's assigned houses (empty = no house tagged yet).
        $memberships = [];
        if (ensure_store_groups_table($pdo)) {
            $gStmt = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN ($in)");
            $gStmt->execute($ids);
            foreach ($gStmt->fetchAll() as $g) $memberships[(int)$g['employee_id']][] = $g['group_key'];
        }

        // All of that day's counts, any house, for these employees.
        $countsByEmpGroup = [];          // old typed counts before the cut-over date, WhatsApp Sales from it (read-only: the +/- boxes are refused after it)
        foreach (qa_rows($pdo, $date, $date) as $r) if (in_array($r['employee_id'], array_map('intval', $ids), true)) {
            $x = &$countsByEmpGroup[$r['employee_id']][$r['group_key']];
            if (!$x) $x = ['query_count' => 0, 'scout_count' => 0, 'champion_count' => 0];
            $x['query_count'] += $r['qc']; $x['scout_count'] += $r['q']; $x['champion_count'] += $r['c']; unset($x);
        }

        // Per-hour view: what each employee got in ONE hour of the day (from
        // the click log). hour = 0–23 of the clock, as the By-hour grid shows.
        $hour = isset($_GET['hour']) && $_GET['hour'] !== '' ? (int)$_GET['hour'] : null;
        $hourCounts = [];
        if ($hour !== null) {
            ensure_query_log_table($pdo);
            try {
                $hs = $pdo->prepare("SELECT employee_id, group_key, kind, SUM(delta) AS n FROM employee_query_log WHERE query_date = ? AND HOUR(created_at) = ? AND employee_id IN ($in) GROUP BY employee_id, group_key, kind");
                $hs->execute(array_merge([$date, $hour], $ids));
                foreach ($hs->fetchAll() as $r) $hourCounts[(int)$r['employee_id']][(string)$r['group_key']][$r['kind']] = (int)$r['n'];
            } catch (PDOException $e) {}
        }

        $groupLabels = store_group_options();
        $colors = employee_colors($pdo);
        foreach ($emps as &$e) {
            $eid = (int)$e['employee_id'];
            if ($groupFilter !== '') {
                $showGroups = [$groupFilter];
            } else {
                $showGroups = $memberships[$eid] ?? [];
                if (!$showGroups) $showGroups = ['']; // never tagged into a house — legacy bucket
            }
            $e['groups'] = array_map(function ($gk) use ($countsByEmpGroup, $eid, $groupLabels, $colors, $hour, $hourCounts) {
                $c = $countsByEmpGroup[$eid][$gk] ?? null;
                $h = $hourCounts[$eid][$gk] ?? [];
                return [
                    'group_key' => $gk,
                    'color' => $colors[$eid . '|' . $gk] ?? '',
                    'group_label' => $gk === '' ? 'Ungrouped' : ($groupLabels[$gk] ?? $gk),
                    'query_count' => $c ? (int)$c['query_count'] : 0,
                    'scout_count' => $c ? (int)$c['scout_count'] : 0,
                    'champion_count' => $c ? (int)$c['champion_count'] : 0,
                    'hour_scout' => $hour === null ? null : max(0, (int)($h['scout'] ?? 0)),
                    'hour_champion' => $hour === null ? null : max(0, (int)($h['champion'] ?? 0)),
                ];
            }, $showGroups);
            // Back-compat top-level totals (sum across the shown houses) for
            // anything still reading the old flat shape.
            $e['query_count'] = array_sum(array_column($e['groups'], 'query_count'));
            $e['scout_count'] = array_sum(array_column($e['groups'], 'scout_count'));
            $e['champion_count'] = array_sum(array_column($e['groups'], 'champion_count'));
        }
        unset($e);
        // Hints for an empty day: the latest earlier date this house has counts on,
        // and whether other houses have counts on this date (wrong house picked).
        $hint = ['prev_date' => null, 'prev_total' => 0, 'other_houses' => 0];
        try {
            $gcol = $groupFilter !== '' ? ' AND group_key = ?' : '';
            $gp = $groupFilter !== '' ? [$groupFilter] : [];
            $ps = $pdo->prepare("SELECT query_date, SUM(scout_count + champion_count) AS n FROM employee_queries WHERE query_date < ?" . (qa_cut($pdo) !== '' ? " AND query_date < '" . qa_cut($pdo) . "'" : '') . "$gcol GROUP BY query_date HAVING n > 0 ORDER BY query_date DESC LIMIT 1");
            $ps->execute(array_merge([$date], $gp));
            if ($pr = $ps->fetch()) { $hint['prev_date'] = $pr['query_date']; $hint['prev_total'] = (int)$pr['n']; }
            if ($groupFilter !== '') {
                $os = $pdo->prepare("SELECT COALESCE(SUM(scout_count + champion_count),0) FROM employee_queries WHERE query_date = ? AND group_key <> ?");
                $os->execute([$date, $groupFilter]);
                $hint['other_houses'] = (int)$os->fetchColumn();
            }
        } catch (PDOException $e) {}
        json_response(['date' => $date, 'hour' => $hour, 'now_hour' => (int)date('G'), 'biz_today' => biz_today($pdo), 'hint' => $hint, 'employees' => $emps]);
        break;
    }

    case 'queries.platform_totals': {
        // Queries assigned per platform (house) over a date range — the
        // Orders page's Platform summary pairs these with the orders.
        require_auth();
        $from = trim($_GET['date_from'] ?? date('Y-m-d'));
        $to = trim($_GET['date_to'] ?? $from);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Bad date.'], 422);
        $qaAgg = [];          // old typed counts before the cut-over date, WhatsApp Sales from it (never both for one day)
        foreach (qa_rows($pdo, $from, $to) as $r) { $k = $r['employee_id'] . '|' . $r['group_key']; $qaAgg[$k] = ['employee_id' => $r['employee_id'], 'group_key' => $r['group_key'], 'q' => ($qaAgg[$k]['q'] ?? 0) + $r['q'], 'c' => ($qaAgg[$k]['c'] ?? 0) + $r['c']]; }
        // Sales → Give queries saves one count per person with NO house (group_key ''). File those under the person's own
        // house when they work in exactly one, so each house card on the Orders page gets its Query ratio. People in several
        // houses (or in none) stay under '' — the all-houses total still counts them.
        $homes = [];
        if (ensure_store_groups_table($pdo)) {
            try { foreach ($pdo->query("SELECT employee_id, group_key FROM employee_store_groups")->fetchAll() as $g) if ((string)$g['group_key'] !== '') $homes[(int)$g['employee_id']][(string)$g['group_key']] = true; } catch (PDOException $e) {}
        }
        $out = [];
        foreach ($qaAgg as $r) {
            $gk = (string)$r['group_key'];
            $eid = (int)$r['employee_id'];
            if ($gk === '' && isset($homes[$eid]) && count($homes[$eid]) === 1) $gk = (string)array_key_first($homes[$eid]);
            if (!isset($out[$gk])) $out[$gk] = ['query' => 0, 'campaign' => 0];
            $out[$gk]['query'] += (int)$r['q'];
            $out[$gk]['campaign'] += (int)$r['c'];
        }
        json_response(['from' => $from, 'to' => $to, 'queries' => $out]);
        break;
    }

    case 'team.sheet': {
        // Orders page "Employee sheet" tab: one row per sales employee for a
        // date range — attendance, plus a `panels` entry for every panel the
        // person works in (TM Perfume House, TM4U, TM Shower Gel):
        // target, queries / campaigns and ratings of that panel.
        // The page shows one block per panel.
        // The order-based columns (collection, orders, COD / prepaid, colours)
        // are worked out in the browser from the orders the page already
        // loaded, so they always match the Platform summary above.
        // rule=1 returns only the Target column with the automatic daily-target
        // rule applied (needs Shopify history, so it is a separate, slower call).
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        $from = trim($_GET['date_from'] ?? biz_today($pdo));
        $to = trim($_GET['date_to'] ?? $from);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        if ($from > $to) json_response(['error' => 'From date must be before To date.'], 422);
        $dayCount = (int)round((strtotime($to) - strtotime($from)) / 86400) + 1;
        if ($dayCount > 93) json_response(['error' => 'Pick at most 93 days for the Employee sheet.'], 422);
        // The Orders page shows Sales Executives only (Employee sheet, Employee target sums, Sales team present / absent) —
        // not Sales Head, Sales Helper, Sales Retailer or anyone else.
        $emps = array_values(array_filter($pdo->query(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.basic_salary, e.designation, e.joining_date, d.department_name
             FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex'
             ORDER BY e.full_name"
        )->fetchAll(), fn($r) => sales_role_kind($r['department_name'] ?? '', $r['designation'] ?? '') === 'executive'));

        if (!empty($_GET['rule'])) {
            $t = team_range_targets($pdo, $emps, $from, $to, true);
            $ptot = panel_target_totals($pdo, $t['panels'], $from, $to);
            foreach ($t['panels'] as $pid => $pp) foreach ($pp as $gk => $x) unset($t['panels'][$pid][$gk]['by_day']);
            json_response(['from' => $from, 'to' => $to, 'panels' => $t['panels'], 'panel_targets' => $ptot, 'rule_used' => $t['rule_used'], 'note' => $t['note']]);
        }

        // ---- attendance: the business day each punch belongs to
        $today = biz_today($pdo);
        $last = $to < $today ? $to : $today;
        $elapsed = $last >= $from ? (int)round((strtotime($last) - strtotime($from)) / 86400) + 1 : 0;
        $att = [];   // employee_id => [date => first punch_in]
        $attMan = [];   // employee_id => [date => punch time was typed in by Admin / HR]
        $hasEdited = ensure_attendance_edited_column($pdo);
        $attOut = [];
        $attOutTs = [];   // employee_id => [date => latest punch_out as a timestamp] — the page works out which orders came after punch-out
        $as = $pdo->prepare("SELECT employee_id, punch_date, punch_in, punch_out, " . ($hasEdited ? "edited_by" : "NULL AS edited_by") . " FROM attendance WHERE punch_in IS NOT NULL AND punch_in >= ? AND punch_in < ?");
        $as->execute([date('Y-m-d', strtotime($from . ' -1 day')) . ' 00:00:00', date('Y-m-d', strtotime($to . ' +2 day')) . ' 00:00:00']);
        foreach ($as->fetchAll() as $r) {
            $pd = (string)$r['punch_date'];
            $day = substr((string)$r['punch_in'], 0, 10) === $pd ? $pd : punch_in_day($pdo, strtotime((string)$r['punch_in']));
            if ($day < $from || $day > $to) continue;
            $eid = (int)$r['employee_id'];
            if (!empty($r['punch_out'])) { $oTs = strtotime((string)$r['punch_out']); if ($oTs && $oTs > ($attOutTs[$eid][$day] ?? 0)) $attOutTs[$eid][$day] = $oTs; }
            if (!isset($att[$eid][$day]) || $r['punch_in'] < $att[$eid][$day]) { $att[$eid][$day] = (string)$r['punch_in']; $attMan[$eid][$day] = !empty($r['edited_by']); $attOut[$eid][$day] = $r['punch_out'] ? substr((string)$r['punch_out'], 11, 5) : ''; }
        }
        $shifts = $from === $to ? emp_shift_map($pdo, $from) : [];
        $defStart = day_start_for($pdo, $from);
        $tsMarks = $from === $to ? day_marks_between($pdo, $from, $from) : [];
        // Sales team present / absent in the Orders page boxes: the last day of the range that has started (today for a range into the future).
        $dsDay = $last >= $from ? $last : null;
        $dsMarks = $dsDay ? ($dsDay === $from && $from === $to ? $tsMarks : day_marks_between($pdo, $dsDay, $dsDay)) : [];

        // ---- the panels each person belongs to (the five businesses, each on its own)
        $empIds = array_map('intval', array_column($emps, 'employee_id'));
        $memb = [];     // employee_id => [panel => true]
        if ($empIds && ensure_store_groups_table($pdo)) {
            $mg = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN (" . implode(',', array_fill(0, count($empIds), '?')) . ")");
            $mg->execute($empIds);
            foreach ($mg->fetchAll() as $r) { $bp = sheet_panel((string)$r['group_key']); if ($bp !== '') $memb[(int)$r['employee_id']][$bp] = true; }
        }
        // A count saved with no house goes to the person's first panel (TM Perfume House, TM4U ...), else to "no panel".
        $firstPanel = [];
        foreach ($empIds as $id) {
            $firstPanel[$id] = 'none';
            foreach (sheet_panels() as $bp) if (!empty($memb[$id][$bp])) { $firstPanel[$id] = $bp; break; }
        }

        // ---- queries / campaigns per panel (same figures as Platform summary: scout = query, champion = campaign)
        $qn = [];       // employee_id => panel => ['q', 'c']
        try {
            foreach (qa_rows($pdo, $from, $to) as $r) {          // old typed counts before the cut-over date, WhatsApp Sales from it
                $id = (int)$r['employee_id'];
                $bp = sheet_panel((string)$r['group_key']) ?: ($firstPanel[$id] ?? 'none');
                $qn[$id][$bp]['q'] = ($qn[$id][$bp]['q'] ?? 0) + (int)$r['q'];
                $qn[$id][$bp]['c'] = ($qn[$id][$bp]['c'] ?? 0) + (int)$r['c'];
            }
        } catch (PDOException $e) {}

        // ---- order ratings per panel (stored 1-10; the page shows them as stars out of 5)
        $ordR = [];     // employee_id => panel => ['s' => sum, 'n' => count]
        try {
            ensure_order_ratings_table($pdo);
            $rs = $pdo->prepare("SELECT employee_id, group_key, SUM(ticket_rating) AS s, COUNT(ticket_rating) AS n FROM order_ratings WHERE rating_date BETWEEN ? AND ? AND ticket_rating IS NOT NULL GROUP BY employee_id, group_key");
            $rs->execute([$from, $to]);
            foreach ($rs->fetchAll() as $r) {
                $id = (int)$r['employee_id'];
                $bp = sheet_panel((string)$r['group_key']) ?: ($firstPanel[$id] ?? 'none');
                $ordR[$id][$bp]['s'] = ($ordR[$id][$bp]['s'] ?? 0) + (float)$r['s'];
                $ordR[$id][$bp]['n'] = ($ordR[$id][$bp]['n'] ?? 0) + (int)$r['n'];
            }
        } catch (PDOException $e) {}

        // ---- target without the automatic rule (instant); the page asks again with rule=1
        $tg = team_range_targets($pdo, $emps, $from, $to, false);
        $ruleOn = false;
        try { $ruleOn = !empty(target_rule_get($pdo)['enabled']); } catch (Throwable $e) {}

        $rows = [];
        foreach ($emps as $e) {
            $id = (int)$e['employee_id'];
            $dates = array_keys($att[$id] ?? []);
            sort($dates);
            $punch = null; $late = null;
            if ($from === $to && $dates) {
                $punch = substr($att[$id][$dates[0]], 11, 5);
                $s = $shifts[$id] ?? ['shift_start' => $defStart, 'late_after' => 15];
                $due = strtotime($from . ' ' . $s['shift_start'] . ':00') + (int)$s['late_after'] * 60;
                $late = strtotime($att[$id][$dates[0]]) > $due;
            }
            // One entry per panel the person has something in: member of it, queries, ratings or a target there.
            $panels = [];
            foreach (array_merge(sheet_panels(), ['none']) as $bp) {
                $m = !empty($memb[$id][$bp]); $qc = $qn[$id][$bp] ?? ['q' => 0, 'c' => 0]; $ra = $ordR[$id][$bp] ?? null; $tp = $tg['panels'][$id][$bp] ?? null;
                if (!$m && !$qc['q'] && !$qc['c'] && !$ra && !$tp) continue;
                $panels[$bp] = [
                    'member' => $m, 'q' => (int)$qc['q'], 'c' => (int)$qc['c'],
                    'order_rating' => $ra && $ra['n'] ? ['avg' => round($ra['s'] / $ra['n'], 1), 'n' => (int)$ra['n']] : null,
                    'target' => $tp['target'] ?? null, 'src' => $tp['src'] ?? 'none', 'how' => $tp['how'] ?? '', 'shared' => !empty($tp['shared']), 'absent' => !empty($tp['absent']), 'absent_days' => (int)($tp['absent_days'] ?? 0), 'off' => !empty($tp['off']), 'leave_days' => (int)($tp['leave_days'] ?? 0),
                    'floor' => $tp['floor'] ?? null,
                ];
            }
            $rows[] = [
                'employee_id' => $id, 'full_name' => $e['full_name'], 'employee_code' => $e['employee_code'],
                'present_days' => count($dates), 'punch_in' => $punch, 'late' => $late,
                'manual' => $from === $to && $dates ? !empty($attMan[$id][$dates[0]]) : false,
                'punch_out' => $from === $to && $dates ? ($attOut[$id][$dates[0]] ?? '') : '',
                'outs' => (object)($attOutTs[$id] ?? []),
                'mark' => $tsMarks[$from . '|' . $id] ?? null,
                'day_status' => $dsDay ? ['date' => $dsDay, 'present' => isset($att[$id][$dsDay]), 'punch' => isset($att[$id][$dsDay]) ? substr($att[$id][$dsDay], 11, 5) : '', 'mark' => $dsMarks[$dsDay . '|' . $id] ?? null] : null,
                'panels' => $panels,
            ];
        }
        // The order the sheet is shown in when "Manual order" is picked: panel => [employee ids] (saved by drag and drop).
        $sheetOrder = [];
        try { $so = json_decode((string)setting_get($pdo, 'orders_sheet_order', ''), true); if (is_array($so)) $sheetOrder = $so; } catch (Throwable $e) {}
        json_response(['from' => $from, 'to' => $to, 'days' => $dayCount, 'elapsed' => $elapsed, 'single' => $from === $to, 'auto_rule' => $ruleOn, 'rows' => $rows, 'order' => (object)$sheetOrder, 'panel_targets' => panel_target_totals($pdo, $tg['panels'], $from, $to), 'panel_spend' => panel_spend_totals($pdo, $from, $to), 'roas_goals' => roas_goals_get($pdo), 'roas_manual' => $from === $to ? roas_manual_get($pdo, $from) : null, 'remarks' => $from === $to ? (object)panel_remarks_for_day($pdo, $from) : (object)[], 'community_manual' => (object)panel_community_for_range($pdo, $from, $to)]);
        break;
    }

    case 'order_remark.list': {
        // Orders page → order details: the remarks written on this order (newest first) and who would be notified (the order's salesman).
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        $store = trim((string)($_GET['store'] ?? '')); $oid = trim((string)($_GET['id'] ?? ''));
        if ($store === '' || $oid === '') json_response(['error' => 'Unknown order.'], 422);
        ensure_order_remarks_table($pdo);
        $rows = [];
        try {
            $q = $pdo->prepare("SELECT id, note, author, to_name, notified, created_at FROM order_remarks WHERE store_key = ? AND order_id = ? ORDER BY id DESC LIMIT 30");
            $q->execute([$store, $oid]);
            $rows = array_map(fn($r) => ['id' => (int)$r['id'], 'note' => (string)$r['note'], 'by' => (string)$r['author'], 'to' => (string)$r['to_name'], 'notified' => (int)$r['notified'] === 1, 'at' => (string)$r['created_at']], $q->fetchAll());
        } catch (PDOException $e) {}
        [$toId, $toName] = order_salesman_employee($pdo, (string)($_GET['salesman'] ?? ''));
        json_response(['remarks' => $rows, 'to' => ['id' => $toId, 'name' => $toName]]);
        break;
    }

    case 'order_remark.save': {
        // Orders page → order details: write a remark on one order. The salesman of that order (matched by name to an employee)
        // gets a small notification (phone push + the "Remark" pop-up on My Sales). Remarks are never edited — a new one is added.
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $store = trim((string)($in['store'] ?? '')); $oid = trim((string)($in['id'] ?? ''));
        $oname = mb_substr(trim((string)($in['order_name'] ?? '')), 0, 60);
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 300);
        if ($store === '' || $oid === '') json_response(['error' => 'Unknown order.'], 422);
        if (mb_strlen($note) < 2) json_response(['error' => 'Write the remark first.'], 422);
        ensure_order_remarks_table($pdo);
        [$fromEmp, $who] = ct_who($pdo, $auth);
        [$toId, $toName] = order_salesman_employee($pdo, (string)($in['salesman'] ?? ''));
        // The same remark sent twice within two minutes (double tap / slow network) is one remark, not two.
        try {
            $dq = $pdo->prepare("SELECT id, created_at FROM order_remarks WHERE store_key = ? AND order_id = ? AND note = ? AND author = ? AND created_at >= ? ORDER BY id DESC LIMIT 1");
            $dq->execute([$store, $oid, $note, $who, date('Y-m-d H:i:s', time() - 120)]); $dup = $dq->fetch();
            if ($dup) json_response(['message' => 'This remark was already sent.', 'remark' => ['id' => (int)$dup['id'], 'note' => $note, 'by' => $who, 'to' => $toName, 'notified' => $toId > 0, 'at' => (string)$dup['created_at']], 'pushed' => 0, 'duplicate' => true]);
        } catch (PDOException $e) {}
        $pushed = 0; $ctId = null;
        if ($toId > 0 && ensure_ct_tables($pdo)) {
            $label = $oname !== '' ? $oname : ('#' . $oid);
            $pdo->prepare("INSERT INTO ct_remarks (employee_id, from_emp, from_name, src, body, created_at) VALUES (?, ?, ?, 'order', ?, NOW())")->execute([$toId, $fromEmp, $who, mb_substr('Order ' . $label . ': ' . $note, 0, 400)]);
            $ctId = (int)$pdo->lastInsertId();
            try { $pushed = ct_push($pdo, [$toId], 'Remark on order ' . $label . ' from ' . $who, mb_substr($note, 0, 120), 'my_sales.html', 'remark'); } catch (Throwable $e) {}
        }
        $at = date('Y-m-d H:i:s');
        $pdo->prepare("INSERT INTO order_remarks (store_key, order_id, order_name, note, author, to_emp, to_name, notified, created_at, ct_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
            ->execute([$store, $oid, $oname, $note, $who, $toId, $toName, $toId > 0 ? 1 : 0, $at, $ctId]);
        json_response(['message' => $toId > 0 ? 'Remark sent to ' . $toName . '.' : 'Remark saved — no employee found for this salesman, so nobody was notified.',
            'remark' => ['id' => (int)$pdo->lastInsertId(), 'note' => $note, 'by' => $who, 'to' => $toName, 'notified' => $toId > 0, 'at' => $at], 'pushed' => $pushed]);
        break;
    }

    case 'panel_remark.save': {
        // Employee sheet: write (or clear, when blank) the note under one employee of one panel for one day.
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $date = trim((string)($in['date'] ?? ''));
        $panel = (string)($in['panel'] ?? '');
        $empId = (int)($in['employee_id'] ?? 0);
        $note = trim((string)($in['note'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Pick a single day first.'], 422);
        if (!in_array($panel, array_merge(sheet_panels(), ['none']), true)) json_response(['error' => 'Unknown panel.'], 422);
        if ($empId <= 0) json_response(['error' => 'Unknown employee.'], 422);
        if (mb_strlen($note) > 500) json_response(['error' => 'Keep the note under 500 characters.'], 422);
        ensure_panel_remarks_table($pdo);
        if ($note === '') {
            $pdo->prepare("DELETE FROM panel_remarks WHERE remark_date = ? AND employee_id = ? AND panel = ?")->execute([$date, $empId, $panel]);
            json_response(['message' => 'Remark removed.', 'remark' => null]);
        }
        $by = remark_author_name($pdo, $auth); $at = date('Y-m-d H:i:s');
        $pdo->prepare(
            "INSERT INTO panel_remarks (remark_date, employee_id, panel, note, author, updated_at) VALUES (?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE note = VALUES(note), author = VALUES(author), updated_at = VALUES(updated_at)"
        )->execute([$date, $empId, $panel, $note, $by, $at]);
        $cleared = 0; if ($date === biz_today($pdo) && ensure_ct_tables($pdo)) $cleared = ct_alerts_handled($pdo, $empId, $by, $note);
        json_response(['message' => 'Remark saved.' . ($cleared ? ' ' . $cleared . ' alert' . ($cleared === 1 ? '' : 's') . ' cleared from Live.' : ''), 'remark' => ['note' => $note, 'by' => $by, 'at' => $at], 'cleared' => $cleared]);
        break;
    }

    case 'panel_community.save': {
        // Employee sheet: Community Yes / No typed by hand for one employee of one panel for one day (both blank = back to the order count).
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $date = trim((string)($in['date'] ?? ''));
        $panel = (string)($in['panel'] ?? '');
        $empId = (int)($in['employee_id'] ?? 0);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Pick a single day first.'], 422);
        if (!in_array($panel, array_merge(sheet_panels(), ['none']), true)) json_response(['error' => 'Unknown panel.'], 422);
        if ($empId <= 0) json_response(['error' => 'Unknown employee.'], 422);
        $yRaw = trim((string)($in['yes'] ?? '')); $nRaw = trim((string)($in['no'] ?? ''));
        ensure_panel_community_table($pdo);
        if ($yRaw === '' && $nRaw === '') {
            $pdo->prepare("DELETE FROM panel_community_manual WHERE cm_date = ? AND employee_id = ? AND panel = ?")->execute([$date, $empId, $panel]);
            json_response(['message' => 'Back to the order count.', 'entry' => null]);
        }
        if (($yRaw !== '' && !preg_match('/^\d{1,4}$/', $yRaw)) || ($nRaw !== '' && !preg_match('/^\d{1,4}$/', $nRaw))) json_response(['error' => 'Type whole numbers (0 – 9999).'], 422);
        $yes = (int)$yRaw; $no = (int)$nRaw;
        $by = remark_author_name($pdo, $auth); $at = date('Y-m-d H:i:s');
        $pdo->prepare(
            "INSERT INTO panel_community_manual (cm_date, employee_id, panel, yes_n, no_n, author, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE yes_n = VALUES(yes_n), no_n = VALUES(no_n), author = VALUES(author), updated_at = VALUES(updated_at)"
        )->execute([$date, $empId, $panel, $yes, $no, $by, $at]);
        json_response(['message' => 'Community saved.', 'entry' => ['yes' => $yes, 'no' => $no, 'by' => $by, 'at' => $at]]);
        break;
    }

    case 'panel_spend.get': {
        // Orders page ROAS: the typed ad spend of every panel for a date range (small call, no Shopify).
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        $from = trim($_GET['date_from'] ?? biz_today($pdo));
        $to = trim($_GET['date_to'] ?? $from);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to) || $from > $to) json_response(['error' => 'Bad dates.'], 422);
        if ((int)round((strtotime($to) - strtotime($from)) / 86400) + 1 > 93) json_response(['error' => 'Pick at most 93 days.'], 422);
        json_response(['from' => $from, 'to' => $to, 'panel_spend' => panel_spend_totals($pdo, $from, $to), 'roas_goals' => roas_goals_get($pdo), 'roas_manual' => $from === $to ? roas_manual_get($pdo, $from) : null]);
        break;
    }

    case 'roas_goals.save': {
        // Orders page: change the three ROAS goals of "Revenue needed for ROAS" (goals = null -> back to 2.95 / 3.0 / 3.1). Same for everyone.
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
