        $g = $in['goals'] ?? null;
        if ($g === null) {
            setting_set($pdo, 'roas_goals', null);
        } else {
            if (!is_array($g) || count($g) !== 3) json_response(['error' => 'Type all three ROAS goals.'], 422);
            $clean = [];
            foreach ($g as $v) {
                if (!is_numeric($v) || (float)$v < 0.1 || (float)$v > 50) json_response(['error' => 'Each ROAS goal must be between 0.1 and 50.'], 422);
                $clean[] = round((float)$v, 2);
            }
            setting_set($pdo, 'roas_goals', json_encode($clean));
        }
        json_response(['message' => 'ROAS goals saved.', 'roas_goals' => roas_goals_get($pdo)]);
        break;
    }

    case 'roas_manual.save': {
        // Live Blocks + Orders page: type the day's ROAS by hand (blank = back to collection ÷ ad spend). Same people as the ad spend box.
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
