        $v = $in['roas'] ?? null;
        if ($v === null || trim((string)$v) === '') {
            $pdo->prepare("DELETE FROM roas_manual WHERE roas_date = ?")->execute([$date]);
            json_response(['message' => 'ROAS is automatic again (collection ÷ ad spend).', 'roas' => null]);
        }
        if (!is_numeric($v) || (float)$v <= 0 || (float)$v > 99.99) json_response(['error' => 'Type the ROAS as a number above 0 (for example 3.2).'], 422);
        $pdo->prepare("INSERT INTO roas_manual (roas_date, roas, updated_by, updated_at) VALUES (?, ?, ?, NOW()) ON DUPLICATE KEY UPDATE roas = VALUES(roas), updated_by = VALUES(updated_by), updated_at = NOW()")
            ->execute([$date, round((float)$v, 2), mb_substr((string)($auth['username'] ?? ''), 0, 100)]);
        json_response(['message' => 'ROAS saved.', 'roas' => round((float)$v, 2)]);
        break;
