        ensure_panel_spend_table($pdo);
        $amount = $in['amount'] ?? null;
        if ($amount === null || $amount === '') {
            $pdo->prepare("DELETE FROM panel_ad_spend WHERE spend_date = ? AND panel = ?")->execute([$date, $panel]);
            json_response(['message' => $panel === 'all' ? 'Ad spend cleared — using the sum of the panel spends.' : 'Ad spend cleared.']);
        }
