        $ids = [];
        foreach ((array)($in['ids'] ?? []) as $v) { $n = (int)$v; if ($n > 0 && !in_array($n, $ids, true)) $ids[] = $n; }
        if (count($ids) > 500) json_response(['error' => 'Too many employees.'], 422);
        $cur = json_decode((string)setting_get($pdo, 'orders_sheet_order', ''), true);
        if (!is_array($cur)) $cur = [];
        if ($ids) $cur[$panel] = $ids; else unset($cur[$panel]);
        setting_set($pdo, 'orders_sheet_order', json_encode($cur));
        json_response(['message' => 'Order saved.', 'panel' => $panel, 'ids' => $ids]);
        break;
    }

    case 'panel_target.save': {
