    case 'queries.hourly': {
        // The team's Query / Campaign counts for a day grouped by the hour
        // each +1 / − was clicked (from the click log). Counts that were
        // entered before the log existed have no time and come back as
        // "earlier" (day totals minus everything logged).
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);   // the Orders page's own controls: any role that has the Orders page (e.g. Sales Head)
        $date = trim($_GET['date'] ?? date('Y-m-d'));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        $groupFilter = normalize_group_key($_GET['store_group'] ?? '');
        ensure_query_log_table($pdo);
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
        $gSql = $groupFilter !== '' ? ' AND group_key = ?' : '';
        $gPar = $groupFilter !== '' ? [$groupFilter] : [];

        $h = $pdo->prepare("SELECT HOUR(created_at) AS h, kind, SUM(delta) AS n FROM employee_query_log WHERE query_date = ?$gSql GROUP BY HOUR(created_at), kind");
        $h->execute(array_merge([$date], $gPar));
        $hours = []; $loggedScout = 0; $loggedChamp = 0;
        foreach ($h->fetchAll() as $r) {
            $hr = (int)$r['h']; $n = (int)$r['n'];
            $hours[$hr] = $hours[$hr] ?? ['hour' => $hr, 'scout' => 0, 'champion' => 0];
            $hours[$hr][$r['kind']] += $n;
            if ($r['kind'] === 'scout') $loggedScout += $n; else $loggedChamp += $n;
        }

        // All 24 hours of the business day, in order (10 AM … 11 PM, 12 AM …
        // 9 AM) — including the ones where nobody added anything. On the day
        // that is still running, the hours that have not started yet are
        // marked "future" so the page can show them greyed instead of 0.
        $seq = biz_hour_sequence($pdo, $date);
        $isToday = $date === biz_today($pdo);
        $nowIdx = $isToday ? array_search((int)date('G'), $seq, true) : false;
        $ordered = [];
        foreach ($seq as $i => $hr) {
            $row = $hours[$hr] ?? ['hour' => $hr, 'scout' => 0, 'champion' => 0];
            $row['future'] = ($nowIdx !== false && $i > $nowIdx) ? 1 : 0;
            $row['now'] = ($nowIdx !== false && $i === $nowIdx) ? 1 : 0;
            $ordered[] = $row;
        }

        // Who the queries of each hour went to (Orders page: tap an hour / its number → the employees).
        $byEmp = [];
        try {
            $be = $pdo->prepare("SELECT HOUR(l.created_at) AS h, l.employee_id, COALESCE(e.full_name, '') AS name, l.kind, SUM(l.delta) AS n
                                 FROM employee_query_log l LEFT JOIN employees e ON e.employee_id = l.employee_id
                                 WHERE l.query_date = ?" . ($groupFilter !== '' ? ' AND l.group_key = ?' : '') . " GROUP BY HOUR(l.created_at), l.employee_id, l.kind");
            $be->execute(array_merge([$date], $gPar));
            foreach ($be->fetchAll() as $r) {
                $hr = (string)(int)$r['h']; $eid = (int)$r['employee_id'];
                $x = &$byEmp[$hr][$eid];
                if (!$x) $x = ['employee_id' => $eid, 'name' => (string)$r['name'] ?: ('#' . $eid), 'scout' => 0, 'champion' => 0];
                $x[$r['kind'] === 'scout' ? 'scout' : 'champion'] += (int)$r['n'];
                unset($x);
            }
            foreach ($byEmp as $hr => $list) $byEmp[$hr] = array_values(array_filter($list, fn($x) => $x['scout'] != 0 || $x['champion'] != 0));
        } catch (PDOException $e) {}

        $tot = ['s' => 0, 'c' => 0];          // old typed counts before the cut-over date, WhatsApp Sales from it (the hour log above is old-only)
        foreach (qa_rows($pdo, $date, $date) as $r) { if ($groupFilter !== '' && $r['group_key'] !== $groupFilter) continue; $tot['s'] += $r['q']; $tot['c'] += $r['c']; }
        json_response([
            'date' => $date,
            'hours' => $ordered,
            'day_start_hour' => (int)substr(day_start_for($pdo, $date), 0, 2),
            'now_hour' => (int)date('G'),
            'biz_today' => biz_today($pdo),
            'earlier' => ['scout' => max(0, (int)$tot['s'] - $loggedScout), 'champion' => max(0, (int)$tot['c'] - $loggedChamp)],
            'total' => ['scout' => (int)$tot['s'], 'champion' => (int)$tot['c']],
            'by_emp' => (object)$byEmp,     // hour => [{employee_id, name, scout, champion}]
        ]);
        break;
    }

    case 'queries.assign_set': {
        // With hour=H the typed number is that HOUR's count (the By-hour
        // view): the difference is logged in that hour and the day total
        // moves by the same amount. Without hour it is the day count.
        // Type a number instead of clicking +1: sets the count exactly. The
        // difference from the old value is logged so the By-hour grid stays
        // right (e.g. typing 12 over 9 logs +3 in this hour).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $empId = (int)($input['employee_id'] ?? 0);
        $value = (int)($input['value'] ?? -1);
        $kind = $input['kind'] ?? 'scout';
        $date = trim($input['date'] ?? date('Y-m-d'));
        $groupKey = normalize_group_key($input['group_key'] ?? '');
        if (!$empId || $value < 0 || $value > 9999) json_response(['error' => 'employee_id and a value from 0 to 9999 required.'], 422);
        if (!in_array($kind, ['scout', 'champion'], true)) json_response(['error' => 'kind must be scout or champion.'], 422);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
        $col = $kind . '_count';
        $hour = isset($input['hour']) && $input['hour'] !== '' && $input['hour'] !== null ? (int)$input['hour'] : null;
        if ($hour !== null) {
            if ($hour < 0 || $hour > 23) json_response(['error' => 'Bad hour.'], 422);
            ensure_query_log_table($pdo);
            $oldHour = query_hour_sum($pdo, $date, $groupKey, $empId, $kind, $hour);
            $diff = $value - $oldHour;
            if ($diff !== 0) {
                $pdo->prepare(
                    "INSERT INTO employee_queries (employee_id, query_date, group_key, query_count, $col) VALUES (?, ?, ?, GREATEST(0, ?), GREATEST(0, ?))
                     ON DUPLICATE KEY UPDATE $col = GREATEST(0, $col + ?), query_count = scout_count + champion_count"
                )->execute([$empId, $date, $groupKey, max(0, $diff), max(0, $diff), $diff]);
                $pdo->prepare("UPDATE employee_queries SET query_count = scout_count + champion_count WHERE employee_id = ? AND query_date = ? AND group_key = ?")->execute([$empId, $date, $groupKey]);
                try {
                    $pdo->prepare("INSERT INTO employee_query_log (query_date, group_key, employee_id, kind, delta, created_at) VALUES (?, ?, ?, ?, ?, ?)")
                        ->execute([$date, $groupKey, $empId, $kind, $diff, query_hour_stamp($pdo, $date, $hour)]);
                } catch (PDOException $e) {}
            }
            $row = $pdo->prepare("SELECT query_count, scout_count, champion_count FROM employee_queries WHERE employee_id = ? AND query_date = ? AND group_key = ?");
            $row->execute([$empId, $date, $groupKey]);
            $r = $row->fetch() ?: ['query_count' => 0, 'scout_count' => 0, 'champion_count' => 0];
            json_response(['group_key' => $groupKey, 'query_count' => (int)$r['query_count'], 'scout_count' => (int)$r['scout_count'], 'champion_count' => (int)$r['champion_count'],
                'hour' => $hour, 'hour_scout' => query_hour_sum($pdo, $date, $groupKey, $empId, 'scout', $hour), 'hour_champion' => query_hour_sum($pdo, $date, $groupKey, $empId, 'champion', $hour)]);
        }
        $cur = $pdo->prepare("SELECT $col FROM employee_queries WHERE employee_id = ? AND query_date = ? AND group_key = ?");
        $cur->execute([$empId, $date, $groupKey]);
        $old = (int)($cur->fetchColumn() ?: 0);
        $pdo->prepare(
            "INSERT INTO employee_queries (employee_id, query_date, group_key, query_count, $col) VALUES (?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE $col = ?, query_count = scout_count + champion_count"
        )->execute([$empId, $date, $groupKey, $value, $value, $value]);
        // second statement so query_count also reflects the new value on insert
        $pdo->prepare("UPDATE employee_queries SET query_count = scout_count + champion_count WHERE employee_id = ? AND query_date = ? AND group_key = ?")->execute([$empId, $date, $groupKey]);
        if ($value !== $old) {
            ensure_query_log_table($pdo);
            try {
                $pdo->prepare("INSERT INTO employee_query_log (query_date, group_key, employee_id, kind, delta, created_at) VALUES (?, ?, ?, ?, ?, ?)")
                    ->execute([$date, $groupKey, $empId, $kind, $value - $old, date('Y-m-d H:i:s')]);
            } catch (PDOException $e) {}
        }
        $row = $pdo->prepare("SELECT query_count, scout_count, champion_count FROM employee_queries WHERE employee_id = ? AND query_date = ? AND group_key = ?");
        $row->execute([$empId, $date, $groupKey]);
        $r = $row->fetch();
        json_response(['group_key' => $groupKey, 'query_count' => (int)$r['query_count'], 'scout_count' => (int)$r['scout_count'], 'champion_count' => (int)$r['champion_count']]);
        break;
    }

    case 'queries.panel_hour_set': {
        // Orders page, "Queries by hour" list in a panel box: type the panel's Query / Campaign number for ONE hour of a day.
        // The panel's counts are kept per employee, so the difference is filed on real employees of that panel (the sheet,
        // Assign Queries and the ratios all stay in step): more → added to the employee with the most clicks that hour
        // (else the first member of the panel); fewer → taken from the employees who have clicks in that hour.
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);   // the Orders page's own controls: any role that has the Orders page (e.g. Sales Head)
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $groupKey = normalize_group_key($in['group_key'] ?? '');
        $kind = $in['kind'] ?? 'scout';
        $date = trim($in['date'] ?? '');
        $hour = isset($in['hour']) && $in['hour'] !== '' ? (int)$in['hour'] : -1;
        $value = isset($in['value']) && is_numeric($in['value']) ? (int)$in['value'] : -1;
        if ($groupKey === '') json_response(['error' => 'Choose a panel.'], 422);
        if (!in_array($kind, ['scout', 'champion'], true)) json_response(['error' => 'kind must be scout or champion.'], 422);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        if ($hour < 0 || $hour > 23) json_response(['error' => 'Bad hour.'], 422);
        if ($value < 0 || $value > 9999) json_response(['error' => 'Enter a number from 0 to 9999.'], 422);
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
        ensure_query_log_table($pdo);
        $col = $kind . '_count';
        // who has clicks in this hour of this panel (per employee, never below 0)
        $st = $pdo->prepare("SELECT employee_id, SUM(delta) AS n FROM employee_query_log WHERE query_date = ? AND group_key = ? AND kind = ? AND HOUR(created_at) = ? GROUP BY employee_id");
        $st->execute([$date, $groupKey, $kind, $hour]);
        $have = [];
        foreach ($st->fetchAll() as $r) { $n = (int)$r['n']; if ($n > 0) $have[(int)$r['employee_id']] = $n; }
        $cur = array_sum($have);
        $diff = $value - $cur;
        if ($diff !== 0) {
            $apply = function (int $empId, int $delta) use ($pdo, $date, $groupKey, $col, $kind, $hour) {
                $pdo->prepare(
                    "INSERT INTO employee_queries (employee_id, query_date, group_key, query_count, $col) VALUES (?, ?, ?, GREATEST(0, ?), GREATEST(0, ?))
                     ON DUPLICATE KEY UPDATE $col = GREATEST(0, $col + ?), query_count = scout_count + champion_count"
                )->execute([$empId, $date, $groupKey, max(0, $delta), max(0, $delta), $delta]);
                $pdo->prepare("UPDATE employee_queries SET query_count = scout_count + champion_count WHERE employee_id = ? AND query_date = ? AND group_key = ?")->execute([$empId, $date, $groupKey]);
                $stamp = query_hour_stamp($pdo, $date, $hour);
                for ($left = abs($delta); $left > 0; $left -= 100) {          // the log column is a small int: file big changes in steps
                    $step = min(100, $left) * ($delta < 0 ? -1 : 1);
                    try { $pdo->prepare("INSERT INTO employee_query_log (query_date, group_key, employee_id, kind, delta, created_at) VALUES (?, ?, ?, ?, ?, ?)")->execute([$date, $groupKey, $empId, $kind, $step, $stamp]); } catch (PDOException $e) {}
                }
            };
            if ($diff > 0) {
                $target = 0;
                if ($have) { arsort($have); $target = (int)array_key_first($have); }
                if (!$target) {
                    [$sgSql, $sgParams] = store_group_filter_sql($pdo, $groupKey);
                    $m = $pdo->prepare("SELECT e.employee_id FROM employees e JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex' AND d.department_name LIKE '%sales%'$sgSql ORDER BY e.employee_code LIMIT 1");
                    $m->execute($sgParams);
                    $target = (int)$m->fetchColumn();
                }
                if (!$target) json_response(['error' => 'No sales employee is in this panel yet — tick the panel on an employee first.'], 422);
                $apply($target, $diff);
            } else {
                $need = -$diff;
                arsort($have);
                foreach ($have as $empId => $n) {
                    if ($need <= 0) break;
                    $take = min($n, $need);
                    $apply((int)$empId, -$take);
                    $need -= $take;
                }
            }
        }
        json_response(['group_key' => $groupKey, 'date' => $date, 'hour' => $hour, 'kind' => $kind, 'value' => $value, 'changed' => $diff]);
        break;
    }

    case 'queries.assign_bump': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $empId = (int)($input['employee_id'] ?? 0);
        $delta = (int)($input['delta'] ?? 0);
        $kind = $input['kind'] ?? 'scout';
        $date = trim($input['date'] ?? date('Y-m-d'));
        $groupKey = normalize_group_key($input['group_key'] ?? ($input['store_group'] ?? ''));
        if (!$empId || !in_array($delta, [1, -1], true)) json_response(['error' => 'employee_id and delta (+1/-1) required.'], 422);
        if (!in_array($kind, ['scout', 'champion'], true)) json_response(['error' => 'kind must be scout or champion.'], 422);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
        $col = $kind . '_count';
        // hour=H: the click belongs to that hour of the day (By-hour view).
        // Taking one away from an hour that has nothing is refused so an
        // hour can never go negative.
        $hour = isset($input['hour']) && $input['hour'] !== '' && $input['hour'] !== null ? (int)$input['hour'] : null;
        if ($hour !== null) {
            if ($hour < 0 || $hour > 23) json_response(['error' => 'Bad hour.'], 422);
            ensure_query_log_table($pdo);
            if ($delta < 0 && query_hour_sum($pdo, $date, $groupKey, $empId, $kind, $hour) <= 0) json_response(['error' => 'Nothing to take away in this hour.'], 422);
        }
        // Bump the type column, never below 0; total = scout + champion.
        // group_key separates this house's row from the same employee's
        // rows for any other house on the same day.
        $pdo->prepare(
            "INSERT INTO employee_queries (employee_id, query_date, group_key, query_count, $col) VALUES (?, ?, ?, GREATEST(0, ?), GREATEST(0, ?))
             ON DUPLICATE KEY UPDATE $col = GREATEST(0, $col + ?), query_count = scout_count + champion_count"
        )->execute([$empId, $date, $groupKey, max(0, $delta), max(0, $delta), $delta]);
        // Log the click with its time, for the By-hour grid.
        ensure_query_log_table($pdo);
        try {
            $pdo->prepare("INSERT INTO employee_query_log (query_date, group_key, employee_id, kind, delta, created_at) VALUES (?, ?, ?, ?, ?, ?)")
                ->execute([$date, $groupKey, $empId, $kind, $delta, $hour === null ? date('Y-m-d H:i:s') : query_hour_stamp($pdo, $date, $hour)]);
        } catch (PDOException $e) { /* the count itself is saved; the grid just misses this click */ }
        $cur = $pdo->prepare("SELECT query_count, scout_count, champion_count FROM employee_queries WHERE employee_id = ? AND query_date = ? AND group_key = ?");
        $cur->execute([$empId, $date, $groupKey]);
        $row = $cur->fetch();
        $out = [
            'group_key' => $groupKey,
            'query_count' => (int)$row['query_count'],
            'scout_count' => (int)$row['scout_count'],
            'champion_count' => (int)$row['champion_count'],
        ];
        if ($hour !== null) {
            $out['hour'] = $hour;
            $out['hour_scout'] = query_hour_sum($pdo, $date, $groupKey, $empId, 'scout', $hour);
            $out['hour_champion'] = query_hour_sum($pdo, $date, $groupKey, $empId, 'champion', $hour);
        }
        json_response($out);
        break;
    }

    case 'queries.save': {
        $auth = require_auth();
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $count = (int)($input['query_count'] ?? -1);
        if ($count < 0 || $count > 5000) json_response(['error' => 'Enter a valid query count.'], 422);

        $date = trim($input['date'] ?? date('Y-m-d'));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        $groupKey = normalize_group_key($input['group_key'] ?? ($input['store_group'] ?? ''));
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);

        // Employees save their own; Admin/HR may pass employee_id.
        $empId = (int)($auth['employee_id'] ?? 0);
        if (in_array($auth['role'], ['Admin', 'HR'], true) && !empty($input['employee_id'])) {
            $empId = (int)$input['employee_id'];
        }
        if (!$empId) json_response(['error' => 'Your login is not linked to an employee.'], 422);

        $pdo->prepare(
            "INSERT INTO employee_queries (employee_id, query_date, group_key, query_count) VALUES (?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE query_count = VALUES(query_count)"
        )->execute([$empId, $date, $groupKey, $count]);
        json_response(['message' => 'Saved: ' . $count . ' queries for ' . $date . '.']);
        break;
    }

    case 'queries.today': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
        // Summed across houses — this is just the employee's own "have I
        // logged anything today" total, not a house breakdown.
        $v = null;
        foreach (qa_rows($pdo, date('Y-m-d'), date('Y-m-d')) as $r) if ((int)$r['employee_id'] === (int)$auth['employee_id']) $v = ($v ?? 0) + $r['qc'];          // old typed count, or WhatsApp Sales from the cut-over date
        json_response(['query_count' => $v === null ? null : (int)$v]);
        break;
    }

    case 'performance.get': {
        // House-wise: one row per employee per store group they belong to.
        // Ratings (convincing/customer/behavior) are about the person, not
        // the house, so they stay shared across that employee's rows.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $month = $_GET['month'] ?? date('Y-m');
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $monthStart = $month . '-01';
        $monthEnd = date('Y-m-t', strtotime($monthStart));
        $groupFilter = normalize_group_key($_GET['store_group'] ?? '');
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);
        ensure_group_key_column($pdo, 'targets', ['month', 'employee_id']);

        [$sgSql, $sgParams] = store_group_filter_sql($pdo, $groupFilter);
        $stmt = $pdo->prepare(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.sales_tag
             FROM employees e
             JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex' AND d.department_name LIKE '%sales%'$sgSql
             ORDER BY e.full_name"
        );
        $stmt->execute($sgParams);
        $emps = $stmt->fetchAll();

        $memberships = [];
        if ($emps && ensure_store_groups_table($pdo)) {
            $ids = array_column($emps, 'employee_id');
            $in = implode(',', array_fill(0, count($ids), '?'));
            $gStmt = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN ($in)");
            $gStmt->execute($ids);
            foreach ($gStmt->fetchAll() as $g) $memberships[(int)$g['employee_id']][] = $g['group_key'];
        }
        $groupLabels = store_group_options();

        $queries = [];          // old typed counts before the cut-over date, WhatsApp Sales from it (never both for one day)
        foreach (qa_rows($pdo, $monthStart, $monthEnd) as $r) {
            $x = &$queries[$r['employee_id']][$r['group_key']];
            if (!$x) $x = ['employee_id' => $r['employee_id'], 'group_key' => $r['group_key'], 'total' => 0, 'days' => 0];
            $x['total'] += $r['qc']; $x['days'] += $r['nrows']; unset($x);
        }

        $tStmt = $pdo->prepare("SELECT employee_id, group_key, achieved, orders_count FROM targets WHERE month = ? AND employee_id > 0");
        $tStmt->execute([$month]);
        $orders = [];
        foreach ($tStmt->fetchAll() as $t) $orders[(int)$t['employee_id']][$t['group_key']] = $t;

        // Monthly ratings — averaged across the month, per employee (shared
        // across their houses since a rating is about the person).
        ensure_rating_decimal_columns($pdo);
        $rStmt = $pdo->prepare(
            "SELECT employee_id,
                    AVG(convincing_rating) AS conv,
                    AVG(customer_rating) AS cust,
                    AVG(behavior_rating) AS beh
             FROM employee_daily_ratings
             WHERE rating_date BETWEEN ? AND ?
             GROUP BY employee_id"
        );
        $rStmt->execute([$monthStart, $monthEnd]);
        $ratings = [];
        foreach ($rStmt->fetchAll() as $r) $ratings[(int)$r['employee_id']] = $r;
        // Month average of the day-level Overall rating, per employee AND house.
        $overallAvg = [];
        $callAvg = [];
        $oStmt = $pdo->prepare("SELECT employee_id, group_key, AVG(rating) AS ov, AVG(call_rating) AS cv FROM employee_daily_overall WHERE rating_date BETWEEN ? AND ? GROUP BY employee_id, group_key");
        $oStmt->execute([$monthStart, $monthEnd]);
        foreach ($oStmt->fetchAll() as $o) {
            $k = (int)$o['employee_id'] . '|' . $o['group_key'];
            if ($o['ov'] !== null) $overallAvg[$k] = (float)$o['ov'];
            if ($o['cv'] !== null) $callAvg[$k] = (float)$o['cv'];
        }

        // Per-order ratings replace the older once-a-day ratings from now on.
        // Each day counts once: a day with order ratings uses the average of
        // its orders; a day with only an old daily rating uses that. Mixing
        // them this way keeps earlier months' scores unchanged.
        if (ensure_order_ratings_table($pdo)) {
            $days = []; // [eid][date] => [conv, cust, beh]
            $d1 = $pdo->prepare("SELECT employee_id, rating_date, convincing_rating, customer_rating, behavior_rating FROM employee_daily_ratings WHERE rating_date BETWEEN ? AND ?");
            $d1->execute([$monthStart, $monthEnd]);
            foreach ($d1->fetchAll() as $x) $days[(int)$x['employee_id']][$x['rating_date']] = [$x['convincing_rating'], $x['customer_rating'], $x['behavior_rating']];
            $d2 = $pdo->prepare(
                "SELECT employee_id, rating_date, AVG(ticket_rating) t, AVG(call_rating) c, AVG(behaviour_rating) b
                 FROM order_ratings WHERE rating_date BETWEEN ? AND ? GROUP BY employee_id, rating_date"
            );
            $d2->execute([$monthStart, $monthEnd]);
            foreach ($d2->fetchAll() as $x) $days[(int)$x['employee_id']][$x['rating_date']] = [$x['t'], $x['c'], $x['b']];
            foreach ($days as $eid => $byDay) {
                $sum = [0, 0, 0]; $n = [0, 0, 0];
                foreach ($byDay as $vals) foreach ($vals as $k => $v) if ($v !== null) { $sum[$k] += (float)$v; $n[$k]++; }
                $ratings[$eid] = [
                    'conv' => $n[0] ? $sum[0] / $n[0] : null,
                    'cust' => $n[1] ? $sum[1] / $n[1] : null,
                    'beh'  => $n[2] ? $sum[2] / $n[2] : null,
                ];
            }
        }

        $rows = [];
        foreach ($emps as $e) {
            $eid = (int)$e['employee_id'];
            $r = $ratings[$eid] ?? null;
            $cust = $r && $r['cust'] !== null ? round((float)$r['cust'], 1) : null;
            $beh  = $r && $r['beh'] !== null ? round((float)$r['beh'], 1) : null;
            $convincing = $r && $r['conv'] !== null ? round((float)$r['conv'], 1) : null;
            // Overall is on the 1-10 scale. Convincing and Customer are
            // already 1-10; Behavior is a 1-5 chip value, so it is scaled up
            // before averaging — mixing the two scales raw would understate
            // anyone whose behavior is rated Good.
            $parts = [];
            if ($convincing !== null) $parts[] = $convincing;
            if ($cust !== null) $parts[] = $cust;
            if ($beh !== null) $parts[] = $beh * 2;
            $overall = $parts ? round(array_sum($parts) / count($parts), 1) : null;

            $showGroups = $groupFilter !== '' ? [$groupFilter] : ($memberships[$eid] ?? ['']);
            foreach ($showGroups as $gk) {
                $q = $queries[$eid][$gk] ?? null;
                $t = $orders[$eid][$gk] ?? null;
                $qTotal = $q ? (int)$q['total'] : 0;
                $qDays = $q ? (int)$q['days'] : 0;
                $ordCount = $t ? (int)$t['orders_count'] : 0;
                $achieved = $t ? (float)$t['achieved'] : 0;
                $ratio = $qTotal > 0 ? round($ordCount / $qTotal * 100, 1) : null;

                $rows[] = [
                    'employee_id' => $eid,
                    'full_name' => $e['full_name'],
                    'employee_code' => $e['employee_code'],
                    'sales_tag' => $e['sales_tag'],
                    'group_key' => $gk,
                    'group_label' => $gk === '' ? 'Ungrouped' : ($groupLabels[$gk] ?? $gk),
                    'queries' => $qTotal,
                    'query_days' => $qDays,
                    'avg_per_day' => $qDays > 0 ? round($qTotal / $qDays) : 0,
                    'orders' => $ordCount,
                    'achieved' => $achieved,
                    'ratio' => $ratio,
                    'convincing' => $convincing,
                    'customer_rating' => $cust,
                    'behavior_rating' => $beh,
                    'overall' => $overall,
                    'overall_rating' => isset($overallAvg[$eid . '|' . $gk]) ? round($overallAvg[$eid . '|' . $gk], 1) : null,   // Customer behaviour
                    'call_day_rating' => isset($callAvg[$eid . '|' . $gk]) ? round($callAvg[$eid . '|' . $gk], 1) : null,      // Call rating
                ];
            }
        }
        json_response(['month' => $month, 'rows' => $rows]);
        break;
    }

    // sales_db.find_phone — Admin: GET phone. Where does this mobile number appear in the MySales database, and is there a name next to it?
    // Shows every table / column holding the number with the row, plus what the HRMS already knows for it — to see why a name is missing.
    case 'sales_db.find_phone': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        @set_time_limit(120);
        $t = phone_tail10((string)($_GET['phone'] ?? ''));
        if ($t === '') json_response(['error' => 'Give phone= with at least 10 digits.'], 422);
        $out = ['phone10' => $t, 'mysales' => [], 'hrms' => []];
        $db = sales_db();
        if ($db) {
            try {
                foreach ($db->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN) as $tb) {
                    $cols = $db->query("SHOW COLUMNS FROM `$tb`")->fetchAll();
                    $txt = array_values(array_filter(array_map(fn($c) => (string)$c['Field'], array_filter($cols, fn($c) => preg_match('/char|text|int|bigint/i', (string)$c['Type'])))));
                    if (!$txt) continue;
                    $w = implode(' OR ', array_map(fn($c) => "CAST(`$c` AS CHAR) LIKE ?", $txt));
                    try {
                        $q = $db->prepare("SELECT * FROM `$tb` WHERE $w LIMIT 3"); $q->execute(array_fill(0, count($txt), '%' . $t . '%'));
                        $rows = $q->fetchAll();
                        foreach ($rows as &$r) foreach ($r as $k => $v) if (is_string($v) && mb_strlen($v) > 80) $r[$k] = mb_substr($v, 0, 80) . '…';
                        unset($r);
                        if ($rows) $out['mysales'][$tb] = ['columns' => array_map(fn($c) => (string)$c['Field'], $cols), 'rows' => $rows];
                    } catch (PDOException $e) {}
                }
            } catch (PDOException $e) { $out['mysales_error'] = $e->getMessage(); }
        } else $out['mysales_error'] = 'Cannot open the sales database.';
        @unlink(sys_get_temp_dir() . '/hrms_phone_names_v4.json'); @unlink(sys_get_temp_dir() . '/hrms_sales_namesrc_v1.json');
        foreach (glob(sys_get_temp_dir() . '/hrms_sales_ordername_*') ?: [] as $f) @unlink($f);
        $map = customer_names_by_phone($db, 'order', [$t]);
        $out['hrms']['name_found'] = $map[$t] ?? '';
        $out['hrms']['name_sources_by_phone'] = $GLOBALS['sales_name_sources'] ?? [];
        if ($db) { $out['hrms']['order_name_column'] = sales_order_name_sql($db, 'order')['how']; $out['hrms']['order4p_name_column'] = sales_order_name_sql($db, 'order4p')['how']; }
        try { $q = $pdo->prepare("SELECT customer, created_at, store_key FROM shop_orders WHERE REPLACE(REPLACE(phone,' ',''),'+','') LIKE ? ORDER BY created_at DESC LIMIT 3"); $q->execute(['%' . $t]); $out['hrms']['shopify_orders'] = $q->fetchAll(); } catch (PDOException $e) {}
        try { $q = $pdo->prepare("SELECT * FROM phone_name_lookup WHERE phone10 = ?"); $q->execute([$t]); $out['hrms']['shopify_customer_lookup'] = $q->fetch() ?: null; } catch (PDOException $e) {}
        $out['hrms']['customer_api_blocked'] = is_file(sys_get_temp_dir() . '/hrms_no_customer_scope');
        json_response($out);
    }

    case 'sales_db.inspect': {
        // Lists the columns and a sample row of the MySales panel tables, so
        // the broadcast field can be identified by name before any matching
        // logic is written against it.
        $auth = require_auth();
        require_role(['Admin'], $auth);
        $db = sales_db();
        if (!$db) json_response(['error' => 'Cannot open the sales database.'], 500);

        $out = [];

        // Every table in the sales DB, so the broadcast lookup table (and any
        // user/employee table it joins to) can be located by name.
        try {
            $out['_all_tables'] = $db->query("SHOW TABLES")->fetchAll(PDO::FETCH_COLUMN);
        } catch (PDOException $e) {
            $out['_all_tables_error'] = $e->getMessage();
        }

        // Scan EVERY table for columns that reference a broadcast or a
        // salesman. The join between the two has to live somewhere, and
        // guessing table names one at a time is slower than looking at all
        // of them once.
        $out['_tables_linking_broadcast_to_salesman'] = [];
        $out['_tables_with_broadcast_column'] = [];
        $out['_tables_with_salesman_column'] = [];
        foreach (($out['_all_tables'] ?? []) as $t) {
            try {
                $cols = $db->query("SHOW COLUMNS FROM `$t`")->fetchAll(PDO::FETCH_COLUMN);
            } catch (PDOException $e) { continue; }
            $hasB = (bool)preg_grep('/broadcast/i', $cols);
            $hasS = (bool)preg_grep('/salesman|agent|user_id|staff|employee/i', $cols);
            if ($hasB) $out['_tables_with_broadcast_column'][$t] = $cols;
            if ($hasS) $out['_tables_with_salesman_column'][$t] = $cols;
            if ($hasB && $hasS) {
                $info = ['columns' => $cols];
                try {
                    $rows = $db->query("SELECT * FROM `$t` LIMIT 3")->fetchAll();
                    foreach ($rows as &$r) foreach ($r as $k => $v) {
                        $r[$k] = is_string($v) && mb_strlen($v) > 60 ? mb_substr($v, 0, 60) . '…' : $v;
                    }
                    unset($r);
                    $info['sample_rows'] = $rows;
                } catch (PDOException $e) { $info['error'] = $e->getMessage(); }
                $out['_tables_linking_broadcast_to_salesman'][$t] = $info;
            }
        }

        // Anything that looks like it maps broadcastId -> a person.
        foreach (($out['_all_tables'] ?? []) as $t) {
            if (!preg_match('/^contactnumber$/i', $t)) continue;
            $info = [];
            try {
                $info['columns'] = $db->query("SHOW COLUMNS FROM `$t`")->fetchAll(PDO::FETCH_COLUMN);
                $rows = $db->query("SELECT * FROM `$t` LIMIT 3")->fetchAll();
                foreach ($rows as &$r) {
                    foreach ($r as $k => $v) {
                        $r[$k] = is_string($v) && mb_strlen($v) > 60 ? mb_substr($v, 0, 60) . '…' : $v;
                    }
                }
                unset($r);
                $info['sample_rows'] = $rows;
            } catch (PDOException $e) {
                $info['error'] = $e->getMessage();
            }
            $out['_lookup_' . $t] = $info;
        }

        foreach (custom_stores() as $key => $cs) {
            $t = $cs['table'];
            $info = ['label' => $cs['label'], 'table' => $t];
            try {
                $info['columns'] = $db->query("SHOW COLUMNS FROM `$t`")->fetchAll(PDO::FETCH_COLUMN);
                // Anything that looks like it could hold the broadcast value.
                $info['likely_broadcast_columns'] = array_values(array_filter(
                    $info['columns'],
                    fn($c) => preg_match('/broadcast|agent|user|staff|sales|created_by|owner|employee/i', $c)
                ));
                $row = $db->query("SELECT * FROM `$t` ORDER BY id DESC LIMIT 1")->fetch();
                // Trim long values so the response stays readable.
                if ($row) {
                    foreach ($row as $k => $v) {
                        $row[$k] = is_string($v) && mb_strlen($v) > 80 ? mb_substr($v, 0, 80) . '…' : $v;
                    }
                }
                $info['latest_row'] = $row ?: null;
            } catch (PDOException $e) {
                $info['error'] = $e->getMessage();
            }
            $out[$key] = $info;
        }
        json_response($out);
        break;
    }

    case 'sales_db.broadcast_check': {
        // Settles whether broadcast -> salesman is a safe attribution:
        //  - is any broadcast shared by more than one user?
        //  - does contactnumber.userId actually resolve to a salesman?
        //  - do real recent orders resolve end to end?
        $auth = require_auth();
        require_role(['Admin'], $auth);
        $db = sales_db();
        if (!$db) json_response(['error' => 'Cannot open the sales database.'], 500);
        $out = [];

        try {
            $out['contactnumber_rows'] = (int)$db->query("SELECT COUNT(*) FROM contactnumber")->fetchColumn();
            $out['distinct_broadcasts'] = (int)$db->query("SELECT COUNT(DISTINCT broadcastId) FROM contactnumber")->fetchColumn();
            // A broadcast owned by 2+ users would make attribution ambiguous.
            $dupes = $db->query(
                "SELECT broadcastId, COUNT(DISTINCT userId) n FROM contactnumber
                 GROUP BY broadcastId HAVING n > 1 ORDER BY n DESC LIMIT 10"
            )->fetchAll();
            $out['broadcasts_with_multiple_users'] = $dupes;
            $out['attribution_is_unambiguous'] = empty($dupes);
        } catch (PDOException $e) {
            $out['error_counts'] = $e->getMessage();
        }

        try {
            $out['userId_resolves_to_salesman'] = (int)$db->query(
                "SELECT COUNT(*) FROM contactnumber c JOIN salesman s ON s.id = c.userId"
            )->fetchColumn();
        } catch (PDOException $e) {
            $out['error_salesman_join'] = $e->getMessage();
        }

        // End-to-end on real recent orders from both stores.
        foreach (['order' => 'mysales', 'order4p' => 'mysales4p'] as $tbl => $label) {
            try {
                $out['sample_' . $label] = $db->query(
                    "SELECT o.id, o.date, o.totalAmount, o.broadcastId,
                            b.name AS broadcast_name, s.name AS salesman_name
                     FROM `$tbl` o
                     LEFT JOIN contactnumber c ON c.broadcastId = o.broadcastId
                     LEFT JOIN broadcast b ON b.id = o.broadcastId
                     LEFT JOIN salesman s ON s.id = c.userId
                     ORDER BY o.date DESC, o.id DESC LIMIT 5"
                )->fetchAll();
            } catch (PDOException $e) {
                $out['error_' . $label] = $e->getMessage();
            }
        }

        json_response($out);
        break;
    }

    case 'addons.check': {
        // Reports the real state of the add-on table so a 500 can be
        // diagnosed without guessing.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $out = ['ensure_ran' => ensure_addons_table($pdo)];
        try {
            $out['columns'] = $pdo->query("SHOW COLUMNS FROM employee_addons")->fetchAll(PDO::FETCH_COLUMN);
            $out['has_addon_group'] = in_array('addon_group', $out['columns'], true);
            $out['row_count'] = (int)$pdo->query("SELECT COUNT(*) FROM employee_addons")->fetchColumn();
        } catch (PDOException $e) {
            $out['error'] = $e->getMessage();
        }
        json_response($out);
        break;
    }

    case 'addons.save': {
        // One add-on event = one order plus one or more products upsold onto
        // it. Each product is stored as its own row so per-product reporting
        // stays possible; they share order_name, date and employee.
        $auth = require_auth();
        require_addons_access($auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_addons_table($pdo);

        $input = json_input();
        $empId = (int)($input['employee_id'] ?? 0);
        $date = trim($input['date'] ?? '');
        $groupKey = normalize_group_key($input['group_key'] ?? '');
        $orderName = trim((string)($input['order_name'] ?? ''));
        $items = $input['items'] ?? [];

        if (!ensure_addons_table($pdo)) json_response(['error' => 'Add-on storage is not available — check database permissions.'], 500);
        if (!$empId || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'employee_id and a valid date are required.'], 422);
        if (!is_array($items) || !count($items)) json_response(['error' => 'Add at least one product.'], 422);
        if (count($items) > 20) json_response(['error' => 'Up to 20 products per add-on.'], 422);

        // One price covers the whole add-on. It is stored on the first
        // product row and left at 0 on the rest, so summing the price
        // column across rows still gives the correct total — no row holds a
        // made-up per-product figure the user never entered.
        $total = round((float)($input['total_price'] ?? 0), 2);
        if ($total <= 0) json_response(['error' => 'Enter the total add-on price.'], 422);

        $clean = [];
        foreach ($items as $it) {
            $name = trim((string)($it['product_name'] ?? ''));
            if ($name === '') continue; // skip blank rows the form may send
            $clean[] = [
                'name' => mb_substr($name, 0, 190),
                'size' => mb_substr(trim((string)($it['size_ml'] ?? '')), 0, 30),
                'qty' => max(1, (int)($it['qty'] ?? 1)),
            ];
        }
        if (!$clean) json_response(['error' => 'Enter a product name.'], 422);

        // Group id ties the rows of one add-on together, so the UI can show
        // and delete them as a single entry rather than loose products.
        $groupId = bin2hex(random_bytes(8));

        $ins = $pdo->prepare(
            "INSERT INTO employee_addons (employee_id, addon_date, group_key, order_name, product_name, size_ml, qty, price, addon_group, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        );
        $pdo->beginTransaction();
        try {
            foreach ($clean as $i => $c) {
                $ins->execute([
                    $empId, $date, $groupKey, $orderName, $c['name'], $c['size'] ?: null,
                    $c['qty'], $i === 0 ? $total : 0, $groupId, $auth['username'],
                ]);
            }
            $pdo->commit();
        } catch (PDOException $e) {
            $pdo->rollBack();
            // Surface the real reason — a generic 500 here gives no clue
            // whether it's a missing column, a bad value or a dead table.
            json_response(['error' => 'Could not save the add-on: ' . $e->getMessage()], 500);
        }

        json_response([
            'message' => count($clean) . ' product' . (count($clean) === 1 ? '' : 's') . ' added (' . number_format($total, 2) . ').',
            'count' => count($clean),
            'total' => $total,
        ]);
        break;
    }

    case 'addons.list': {
        // Add-ons for one day, grouped by employee. Optionally narrowed to a
        // single employee for the expanded per-row list.
        $auth = require_auth();
        require_addons_access($auth);
        ensure_addons_table($pdo);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        $empId = (int)($_GET['employee_id'] ?? 0);

        // Order Allocation asks for a whole date range at once (date_from / date_to); the Performance page keeps
        // sending a single date.
        $from = (string)($_GET['date_from'] ?? ''); $to = (string)($_GET['date_to'] ?? '');
        if ($from !== '' || $to !== '') {
            if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to) || $from > $to) json_response(['error' => 'Bad date range.'], 422);
            $sql = "SELECT * FROM employee_addons WHERE addon_date BETWEEN ? AND ?";
            $params = [$from, $to];
        } else {
            $sql = "SELECT * FROM employee_addons WHERE addon_date = ?";
            $params = [$date];
        }
        if ($empId) { $sql .= " AND employee_id = ?"; $params[] = $empId; }
        $sql .= " ORDER BY created_at DESC, addon_id DESC";
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll();

        // Per-employee totals, so the Performance row can show "n · total"
        // without the page having to add them up itself.
        $byEmp = [];
        foreach ($rows as $r) {
            $eid = (int)$r['employee_id'];
            if (!isset($byEmp[$eid])) $byEmp[$eid] = ['count' => 0, 'total' => 0.0];
            $byEmp[$eid]['count']++;
            $byEmp[$eid]['total'] += (float)$r['price'] * (int)$r['qty'];
        }
        foreach ($byEmp as &$b) $b['total'] = round($b['total'], 2);
        unset($b);

        json_response(['date' => $date, 'addons' => $rows, 'by_employee' => $byEmp]);
        break;
    }

    case 'addons.delete': {
        $auth = require_auth();
        require_addons_access($auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_addons_table($pdo);
        $input = json_input();
        $group = trim((string)($input['addon_group'] ?? ''));
        $id = (int)($input['addon_id'] ?? 0);
        if ($group !== '') {
            // Remove the whole add-on (every product recorded together).
            $pdo->prepare("DELETE FROM employee_addons WHERE addon_group = ?")->execute([$group]);
        } elseif ($id) {
            $pdo->prepare("DELETE FROM employee_addons WHERE addon_id = ?")->execute([$id]);
        } else {
            json_response(['error' => 'addon_group or addon_id required.'], 422);
        }
        json_response(['message' => 'Add-on removed.']);
        break;
    }

    case 'performance.daily': {
        // House-wise: one row per employee per store group they belong to.
        // Live Shopify orders are attributed to a house by which store they
        // came from (same mapping as targets.sync_orders); query counts come
        // from employee_queries's own group_key. Ratings stay employee-level.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        $groupFilter = normalize_group_key($_GET['store_group'] ?? '');
        ensure_group_key_column($pdo, 'employee_queries', ['employee_id', 'query_date']);

        [$sgSql, $sgParams] = store_group_filter_sql($pdo, $groupFilter);
        $stmt = $pdo->prepare(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.sales_tag
             FROM employees e
             JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex' AND d.department_name LIKE '%sales%'$sgSql
             ORDER BY e.full_name"
        );
        $stmt->execute($sgParams);
        $emps = $stmt->fetchAll();

        $memberships = [];
        if ($emps && ensure_store_groups_table($pdo)) {
            $ids = array_column($emps, 'employee_id');
            $in = implode(',', array_fill(0, count($ids), '?'));
            $gStmt = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN ($in)");
            $gStmt->execute($ids);
            foreach ($gStmt->fetchAll() as $g) $memberships[(int)$g['employee_id']][] = $g['group_key'];
        }
        $groupLabels = store_group_options();

        $queries = [];          // old typed counts before the cut-over date, WhatsApp Sales from it
        foreach (qa_rows($pdo, $date, $date) as $r) $queries[$r['employee_id']][$r['group_key']] = ($queries[$r['employee_id']][$r['group_key']] ?? 0) + $r['qc'];

        ensure_rating_decimal_columns($pdo);
        $rStmt = $pdo->prepare("SELECT * FROM employee_daily_ratings WHERE rating_date = ?");
        $rStmt->execute([$date]);
        $ratings = [];
        foreach ($rStmt->fetchAll() as $r) $ratings[(int)$r['employee_id']] = $r;
        $overallByKey = [];   // "employee|house" => Overall rating for the day
        $callByKey = [];
        $oStmt = $pdo->prepare("SELECT employee_id, group_key, rating, call_rating FROM employee_daily_overall WHERE rating_date = ?");
        $oStmt->execute([$date]);
        foreach ($oStmt->fetchAll() as $o) {
            $k = (int)$o['employee_id'] . '|' . $o['group_key'];
            if ($o['rating'] !== null) $overallByKey[$k] = (float)$o['rating'];
            if ($o['call_rating'] !== null) $callByKey[$k] = (float)$o['call_rating'];
        }

        // Live day orders per employee, split by which house's store they came from.
        $tagMap = sales_tag_map($pdo);
        $orderSums = [];   // "$empId|$gk" => amount
        $orderCounts = [];
        $orderLists = [];  // "$empId|$gk" => [order, ...] for per-order rating
        $errors = [];
        $storeToGroup = ['tmperfumehouse' => 'tmph'];
        $allocMap = order_allocations($pdo);
        if ($tagMap || $allocMap) {
            $stores = shopify_stores();
            $tokens = [];
            foreach ($stores as $key => $store) {
                if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
                $token = shopify_get_token($key, $store);
                if (is_array($token)) { $errors[] = $token['error']; unset($stores[$key]); continue; }
                $tokens[$key] = $token;
            }
            if ($stores) {
                $results = shopify_fetch_all($stores, $tokens, $date, $date, 8, true);
                foreach ($results as $storeKey => $st) {
                    if ($st['error']) { $errors[] = $st['error']; continue; }
                    foreach ($st['orders'] as $o) {
                        $gk = order_house($storeKey, (string)($o['tags'] ?? ''));   // house tag wins
                        $sm = match_salesman($tagMap, (string)($o['tags'] ?? ''));
                        alloc_override($allocMap, $storeKey, $o['id'], $gk, $sm);   // Order Allocation page wins over both
                        if ($sm) {
                            $key = $sm['id'] . '|' . $gk;
                            $orderSums[$key] = ($orderSums[$key] ?? 0) + (float)$o['total'];
                            $orderCounts[$key] = ($orderCounts[$key] ?? 0) + 1;
                            $orderLists[$key][] = [
                                'order_key' => $storeKey . ':' . $o['id'],
                                'order_name' => (string)$o['order_name'],
                                'customer' => (string)($o['customer'] ?? ''),
                                'total' => round((float)$o['total'], 2),
                                'created_at' => (string)$o['created_at'],
                                'code' => order_code_for($pdo, $storeKey, $o['id'], (string)($o['tags'] ?? '')),
                            ];
                        }
                    }
                }
            }
        }

        // MySales orders moved to a house on the Order Allocation page.
        foreach (allocated_house_orders($pdo, $date, $date, $errors) as $o) {
            if (!$o['emp_id']) continue;
            $key = $o['emp_id'] . '|' . $o['house'];
            $orderSums[$key] = ($orderSums[$key] ?? 0) + (float)$o['total'];
            $orderCounts[$key] = ($orderCounts[$key] ?? 0) + 1;
            $orderLists[$key][] = [
                'order_key' => $o['source'] . ':' . $o['id'],
                'order_name' => (string)$o['order_name'],
                'customer' => (string)$o['customer'],
                'total' => round((float)$o['total'], 2),
                'created_at' => (string)$o['created_at'],
                'code' => order_code_for($pdo, (string)$o['source'], $o['id']),
            ];
        }

        // Existing per-order ratings for every order listed above.
        $orderRatings = [];
        if ($orderLists && ensure_order_ratings_table($pdo)) {
            $keys = [];
            foreach ($orderLists as $list) foreach ($list as $ol) $keys[] = $ol['order_key'];
            foreach (array_chunk($keys, 500) as $chunk) {
                $in = implode(',', array_fill(0, count($chunk), '?'));
                $orStmt = $pdo->prepare("SELECT order_key, ticket_rating, call_rating, behaviour_rating FROM order_ratings WHERE order_key IN ($in)");
                $orStmt->execute($chunk);
                foreach ($orStmt->fetchAll() as $or) $orderRatings[$or['order_key']] = $or;
            }
        }

        $rows = [];
        foreach ($emps as $e) {
            $eid = (int)$e['employee_id'];
            $r = $ratings[$eid] ?? null;
            $showGroups = $groupFilter !== '' ? [$groupFilter] : ($memberships[$eid] ?? ['']);
            foreach ($showGroups as $gk) {
                $key = $eid . '|' . $gk;
                $q = $queries[$eid][$gk] ?? null;
                $oc = (int)($orderCounts[$key] ?? 0);
                $rows[] = [
                    'employee_id' => $eid,
                    'full_name' => $e['full_name'],
                    'employee_code' => $e['employee_code'],
                    'group_key' => $gk,
                    'group_label' => $gk === '' ? 'Ungrouped' : ($groupLabels[$gk] ?? $gk),
                    'queries' => $q,
                    'orders' => $oc,
                    'sales' => round($orderSums[$key] ?? 0, 2),
                    'ratio' => ($q !== null && $q > 0) ? round($oc / $q * 100, 1) : null,
                    'convincing' => $r && $r['convincing_rating'] !== null ? (float)$r['convincing_rating'] : null,
                    'customer_rating' => $r && $r['customer_rating'] !== null ? (float)$r['customer_rating'] : null,
                    'behavior_rating' => $r && $r['behavior_rating'] !== null ? (int)$r['behavior_rating'] : null,
                    'overall_rating' => $overallByKey[$key] ?? null,   // Customer behaviour (per employee per house)
                    'call_day_rating' => $callByKey[$key] ?? null,    // Call rating (per employee per house)
                    'order_list' => array_map(function ($ol) use ($orderRatings) {
                        $or = $orderRatings[$ol['order_key']] ?? null;
                        $ol['ticket'] = $or && $or['ticket_rating'] !== null ? (float)$or['ticket_rating'] : null;
                        $ol['call'] = $or && $or['call_rating'] !== null ? (float)$or['call_rating'] : null;
                        $ol['behaviour'] = $or && $or['behaviour_rating'] !== null ? (int)$or['behaviour_rating'] : null;
                        return $ol;
                    }, $orderLists[$key] ?? []),
                ];
            }
        }
        json_response(['date' => $date, 'rows' => $rows, 'errors' => $errors]);
        break;
    }

    case 'order_ratings.save': {
        // Saves ONE field of one order's rating; the other fields keep
        // whatever they already had.
        $auth = require_auth();
        // Rated from the Orders page or the Order Allocation page (any non-Employee role that has it), or Admin / HR.
        if (!orders_page_controls($auth) && !(strtolower(trim((string)($auth['role'] ?? ''))) !== 'employee' && user_can($auth, 'allocation'))) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_ratings_table($pdo)) json_response(['error' => 'Rating storage is not available.'], 500);
        $in = json_input();
        $orderKey = trim((string)($in['order_key'] ?? ''));
        $empId = (int)($in['employee_id'] ?? 0);
        $date = trim((string)($in['date'] ?? ''));
        $field = (string)($in['field'] ?? '');
        if ($orderKey === '' || strlen($orderKey) > 80 || !$empId || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            json_response(['error' => 'order_key, employee_id and date are required.'], 422);
        }
        $cols = ['ticket' => 'ticket_rating', 'call' => 'call_rating', 'behaviour' => 'behaviour_rating'];
        if (!isset($cols[$field])) json_response(['error' => 'Unknown rating field.'], 422);
        if ($field === 'behaviour') {
            $value = (int)($in['value'] ?? 0);
            if (!in_array($value, [1, 3, 5], true)) json_response(['error' => 'Customer behaviour must be Good, Average or Bad.'], 422);
        } else {
            $value = round((float)($in['value'] ?? 0), 1);
            // 0 = clear the rating (a mis-tap); otherwise 1–10 (half stars).
            if ($value != 0 && ($value < 1 || $value > 10)) json_response(['error' => 'Rating must be between 1 and 10, or 0 to clear.'], 422);
        }
        $col = $cols[$field];
        $stored = $value == 0 ? null : $value;
        $pdo->prepare(
            "INSERT INTO order_ratings (order_key, order_name, employee_id, rating_date, group_key, $col, updated_by)
             VALUES (?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE $col = VALUES($col), employee_id = VALUES(employee_id),
                 rating_date = VALUES(rating_date), updated_by = VALUES(updated_by)"
        )->execute([
            $orderKey, mb_substr((string)($in['order_name'] ?? ''), 0, 60), $empId, $date,
            normalize_group_key($in['group_key'] ?? ''), $stored, $auth['username'] ?? null,
        ]);
        // Ticket-size stars: remember who gave them and when (shown under the stars on the Order Allocation page).
        $by = (string)($auth['username'] ?? ''); $at = date('Y-m-d H:i:s');
        if ($field === 'ticket') {
            ensure_order_ratings_ticket_columns($pdo);
            try { $pdo->prepare("UPDATE order_ratings SET ticket_by = ?, ticket_at = ? WHERE order_key = ?")->execute([$stored === null ? null : $by, $stored === null ? null : $at, $orderKey]); } catch (PDOException $e) {}
        }
        json_response(['message' => $stored === null ? 'Rating cleared.' : 'Rating saved.', 'field' => $field, 'value' => $stored, 'by' => $stored === null ? '' : $by, 'at' => $stored === null ? '' : $at]);
        break;
    }

    case 'performance.rate_daily': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $date = trim($input['date'] ?? '');
        $empId = (int)($input['employee_id'] ?? 0);
        $field = $input['field'] ?? '';
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date) || !$empId) json_response(['error' => 'date and employee_id required.'], 422);
        if (!in_array($field, ['customer', 'behavior', 'convincing', 'overall', 'call'], true)) json_response(['error' => 'Bad field.'], 422);
        ensure_rating_decimal_columns($pdo);

        // Convincing and Customer take one decimal place on a 1-10 scale;
        // Behavior is set by the Good/Average/Bad chips and stays whole.
        if ($field === 'behavior') {
            $value = (int)($input['value'] ?? 0);
            if ($value < 1 || $value > 5) json_response(['error' => 'Behavior rating must be 1-5.'], 422);
        } else {
            $value = round((float)($input['value'] ?? 0), 1);
            // 0 = clear the rating (a mis-tap); otherwise 1–10 (half stars).
            if ($value != 0 && ($value < 1 || $value > 10)) json_response(['error' => 'Rating must be between 1 and 10, or 0 to clear.'], 422);
        }
        if ($field === 'overall' || $field === 'call') {
            // Per employee per house: 'overall' = Customer behaviour, 'call' = Call rating.
            $gk = (string)($input['group_key'] ?? '');
            $col = $field === 'call' ? 'call_rating' : 'rating';
            $stored = $value == 0 ? null : $value;
            $pdo->prepare(
                "INSERT INTO employee_daily_overall (rating_date, employee_id, group_key, $col) VALUES (?, ?, ?, ?)
                 ON DUPLICATE KEY UPDATE $col = VALUES($col)"
            )->execute([$date, $empId, $gk, $stored]);
            json_response(['message' => $stored === null ? 'Rating cleared.' : 'Rating saved.']);
        }
        $col = ['customer' => 'customer_rating', 'behavior' => 'behavior_rating', 'convincing' => 'convincing_rating'][$field];
        $pdo->prepare(
            "INSERT INTO employee_daily_ratings (rating_date, employee_id, $col) VALUES (?, ?, ?)
             ON DUPLICATE KEY UPDATE $col = VALUES($col)"
        )->execute([$date, $empId, $value]);
        json_response(['message' => 'Rating saved.']);
        break;
    }

    case 'performance.rate': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $month = $input['month'] ?? '';
        $empId = (int)($input['employee_id'] ?? 0);
        $field = $input['field'] ?? '';
        $value = (int)($input['value'] ?? 0);
        if (!preg_match('/^\d{4}-\d{2}$/', $month) || !$empId) json_response(['error' => 'month and employee_id required.'], 422);
        if (!in_array($field, ['customer', 'behavior', 'convincing'], true)) json_response(['error' => 'field must be customer, behavior, or convincing.'], 422);
        if ($value < 1 || $value > 5) json_response(['error' => 'Rating must be 1-5.'], 422);

        $col = $field === 'customer' ? 'customer_rating' : ($field === 'behavior' ? 'behavior_rating' : 'convincing_rating');
        $pdo->prepare(
            "INSERT INTO employee_ratings (month, employee_id, $col) VALUES (?, ?, ?)
             ON DUPLICATE KEY UPDATE $col = VALUES($col)"
        )->execute([$month, $empId, $value]);
        json_response(['message' => 'Rating saved.']);
        break;
    }

    // ---- Footwear check (AI vision) ----
    case 'attendance.footwear_check': {
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR', 'Employee'], true) && !user_can($auth, 'punch')) json_response(['error' => 'Your role does not have Punch In / Out access.'], 403);
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $empId = (int)$auth['employee_id'];
        [$fwCode, $fwOut] = footwear_check_run($pdo, $empId);
        json_response($fwOut, $fwCode);
        break;
    }

    // footwear.diag — Admin: why does the shoe check say "Could not check the photo right now"? Sends one tiny test picture to Gemini
    // and reports the exact answer, plus the last real failure of an employee's check.
    case 'footwear.diag': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        $out = ['feature_on' => footwear_enabled(), 'key_set' => tmph_key() !== '', 'models' => footwear_models(), 'enroll_on' => footwear_enroll_enabled()];
        $lf = @file_get_contents(sys_get_temp_dir() . '/hrms_footwear_lastfail.json');
        $last = $lf ? json_decode($lf, true) : null;
        if (is_array($last)) { $last['reason'] = footwear_fail_reason((int)$last['status'], (string)$last['detail'], (string)$last['curl']); $out['last_failure'] = $last; }
        if (!$out['key_set']) { $out['test'] = ['ok' => false, 'reason' => 'ANTHROPIC_API_KEY (or GEMINI_API_KEY) is not set in config.php.']; json_response($out); }
        // a 64x64 grey JPEG made on the spot (no file needed)
        $im = imagecreatetruecolor(64, 64); imagefill($im, 0, 0, imagecolorallocate($im, 120, 120, 120));
        ob_start(); imagejpeg($im, null, 70); $jpg = (string)ob_get_clean(); imagedestroy($im);
        @set_time_limit(90);
        $ai = footwear_ai($jpg, 'image/jpeg');
        $out['test'] = $ai['ok']
            ? ['ok' => true, 'model' => (string)($ai['model'] ?? ''), 'answer' => $ai['v']]
            : ['ok' => false, 'status' => (int)($ai['status'] ?? 0), 'detail' => mb_substr((string)($ai['detail'] ?? ''), 0, 400), 'tried' => (array)($ai['tried'] ?? []), 'reason' => footwear_fail_reason((int)($ai['status'] ?? 0), (string)($ai['detail'] ?? ''), (string)($ai['curl'] ?? ''))];
        json_response($out);
    }

    case 'footwear.log': {
        // Admin / HR: footwear checks of one day (newest first).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_footwear_enroll_tables($pdo)) json_response(['error' => 'Could not create the footwear table.'], 500);
        $date = (string)($_GET['date'] ?? date('Y-m-d'));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $st = $pdo->prepare("SELECT f.check_id, f.employee_id, e.full_name, e.employee_code, f.status, f.kind, f.category, f.shoe_type, f.confidence, f.quality, f.cleanliness, f.clean_note, f.message, f.model, f.used_at, f.created_at, (f.photo_path <> '') AS has_photo
                             FROM footwear_checks f JOIN employees e ON e.employee_id = f.employee_id WHERE f.check_date = ? ORDER BY f.check_id DESC LIMIT 500");
        $st->execute([$date]);
        json_response(['date' => $date, 'checks' => $st->fetchAll()]);
        break;
    }

    case 'footwear.summary': {
        // Admin / HR "Shoes" view: one day's shoe checks (latest per employee + every try), KPIs, and each person's month average.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_footwear_table($pdo) || !ensure_footwear_enroll_tables($pdo)) json_response(['error' => 'Could not create the footwear table.'], 500);
        $date = (string)($_GET['date'] ?? date('Y-m-d'));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $st = $pdo->prepare("SELECT f.check_id, f.employee_id, e.full_name, e.employee_code, f.status, f.category, f.shoe_type, f.cleanliness, f.clean_note, f.message, f.used_at, f.created_at, (f.photo_path <> '') AS has_photo
                             FROM footwear_checks f JOIN employees e ON e.employee_id = f.employee_id WHERE f.check_date = ? AND f.kind = 'check' ORDER BY f.check_id");
        try { $st->execute([$date]); $rows = $st->fetchAll(); }
        catch (PDOException $e) {      // older table without `kind`
            $st = $pdo->prepare(str_replace(" AND f.kind = 'check'", '', $st->queryString)); $st->execute([$date]); $rows = $st->fetchAll();
        }
        $people = [];
        foreach ($rows as $r) {
            $id = (int)$r['employee_id'];
            if (!isset($people[$id])) $people[$id] = ['employee_id' => $id, 'full_name' => $r['full_name'], 'employee_code' => $r['employee_code'], 'tries' => [], 'final' => null, 'blocked' => 0];
            $people[$id]['tries'][] = $r;
            if (in_array($r['status'], ['rejected', 'dirty'], true)) $people[$id]['blocked']++;
            if ($r['status'] === 'approved') $people[$id]['final'] = $r;
        }
        foreach ($people as &$p) if (!$p['final']) $p['final'] = end($p['tries']); unset($p);
        // month average and dirty days (approved checks, one per employee per day: the day's last approved rating)
        $m1 = substr($date, 0, 8) . '01';
        $ms = $pdo->prepare("SELECT employee_id, check_date, cleanliness FROM footwear_checks WHERE check_date BETWEEN ? AND ? AND status = 'approved' AND cleanliness IS NOT NULL ORDER BY check_id");
        $ms->execute([$m1, $date]);
        $day = [];
        foreach ($ms->fetchAll() as $r) $day[(int)$r['employee_id']][$r['check_date']] = (int)$r['cleanliness'];
        $month = [];
        foreach ($day as $id => $d) $month[$id] = ['avg' => round(array_sum($d) / count($d), 1), 'days' => count($d), 'dirty_days' => count(array_filter($d, fn($v) => $v <= 2))];
        $approved = array_filter($people, fn($p) => $p['final'] && $p['final']['status'] === 'approved');
        $rated = array_values(array_filter(array_map(fn($p) => $p['final']['cleanliness'], $approved), fn($v) => $v !== null));
        $staff = 0;
        try { $staff = (int)$pdo->query("SELECT COUNT(*) FROM employees WHERE status = 'approved'")->fetchColumn(); } catch (PDOException $e) {}
        $cost = 0.0;
        if (ensure_ai_usage_table($pdo)) { $c = $pdo->prepare("SELECT COALESCE(SUM(cost_usd),0) FROM ai_usage WHERE use_date = ? AND purpose = 'footwear'"); $c->execute([$date]); $cost = (float)$c->fetchColumn(); }
        json_response([
            'date' => $date, 'enabled' => footwear_enabled(), 'min_clean' => (int)tmph_cfg('FOOTWEAR_MIN_CLEAN', 0),
            'kpi' => ['checked' => count($people), 'staff' => $staff, 'approved' => count($approved),
                      'blocked' => count(array_filter($people, fn($p) => $p['blocked'] > 0)), 'still_blocked' => count($people) - count($approved),
                      'avg' => $rated ? round(array_sum($rated) / count($rated), 1) : null, 'dirty' => count(array_filter($rated, fn($v) => $v <= 2)),
                      'cost_inr' => round($cost * (float)tmph_cfg('USD_INR', 88), 2)],
            'people' => array_values($people), 'month' => (object)$month,
        ]);
        break;
    }

    case 'footwear.photo': {
        // Streams one stored footwear photo (Admin / HR, or the employee's own). ?token= works too, so it can sit in an <img>.
        $auth = !empty($_GET['token']) ? verify_token((string)$_GET['token']) : require_auth();
        if (!$auth) json_response(['error' => 'Please log in again.'], 401);
        if (!ensure_footwear_table($pdo)) json_response(['error' => 'No footwear photos.'], 404);
        $id = (int)($_GET['check_id'] ?? 0);
        $st = $pdo->prepare("SELECT employee_id, photo_path FROM footwear_checks WHERE check_id = ?");
        $st->execute([$id]);
        $r = $st->fetch();
        if (!$r) json_response(['error' => 'Not found.'], 404);
        if (empty($auth['employee_id']) || (int)$auth['employee_id'] !== (int)$r['employee_id']) require_role(['Admin', 'HR'], $auth);
        $f = __DIR__ . '/' . $r['photo_path'];
        if ($r['photo_path'] === '' || !is_file($f)) json_response(['error' => 'The photo has been removed (old photos are deleted automatically).'], 404);
        header('Content-Type: image/jpeg'); header('Content-Length: ' . filesize($f)); header('Cache-Control: private, max-age=300');
        readfile($f);
        exit;
    }

    case 'footwear.enroll_photo': {
        // One photo of the shoes being enrolled (side 0-4, in order): 5 sides = the pair is locked to this employee.
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR', 'Employee'], true) && !user_can($auth, 'punch')) json_response(['error' => 'Your role does not have Punch In / Out access.'], 403);
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        [$feCode, $feOut] = footwear_enroll_photo($pdo, (int)$auth['employee_id'], (int)($_POST['side'] ?? $_GET['side'] ?? -1));
        json_response($feOut, $feCode);
        break;
    }

    case 'footwear.enroll_status': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $empId = (int)$auth['employee_id'];
        $en = footwear_enroll_enabled() && !employee_is_female($pdo, $empId);   // female: no shoe enrollment
        $a = $en ? footwear_enroll_active($pdo, $empId) : null;
        json_response(['enabled' => $en, 'enrolled' => $en ? $a !== null : true, 'enrolled_at' => $a ? (string)$a['activated_at'] : null, 'shoe_type' => $a ? (string)$a['shoe_type'] : '',
            'cleanliness' => ($a && $a['cleanliness'] !== null) ? (int)$a['cleanliness'] : null, 'sides' => $a ? count($a['photos']) : 0]);
        break;
    }

    case 'footwear.enroll_list': {
        // Admin / HR: who has enrolled shoes (and when).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_footwear_enroll_tables($pdo)) json_response(['error' => 'Could not create the shoe tables.'], 500);
        $rows = $pdo->query("SELECT e.employee_id, e.full_name, e.employee_code, f.enroll_id, f.shoe_type, f.main_color, f.cleanliness, f.clean_note, f.activated_at,
                                    (SELECT COUNT(*) FROM footwear_enroll_photos p WHERE p.enroll_id = f.enroll_id) AS sides
                             FROM employees e LEFT JOIN footwear_enroll f ON f.employee_id = e.employee_id AND f.status = 'active'
                             ORDER BY (f.enroll_id IS NULL), e.full_name LIMIT 1000")->fetchAll();
        json_response(['enabled' => footwear_enroll_enabled(), 'employees' => $rows]);
        break;
    }

    case 'footwear.enroll_reset': {
        // Admin / HR: forget an employee's enrolled shoes (lost / wrong photos). He enrolls again at the next Punch In.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_footwear_enroll_tables($pdo)) json_response(['error' => 'Could not create the shoe tables.'], 500);
        $in = json_input();
        $eid = (int)($in['employee_id'] ?? 0);
        if ($eid <= 0) json_response(['error' => 'Employee is required.'], 422);
        footwear_enroll_drop_draft($pdo, $eid);
        $st = $pdo->prepare("SELECT enroll_id FROM footwear_enroll WHERE employee_id = ? AND status = 'active'");
        $st->execute([$eid]);
        $n = 0;
        foreach ($st->fetchAll() as $r) { footwear_enroll_drop_photos($pdo, (int)$r['enroll_id']); $pdo->prepare("UPDATE footwear_enroll SET status = 'replaced' WHERE enroll_id = ?")->execute([(int)$r['enroll_id']]); $n++; }
        json_response(['message' => $n ? 'Shoes reset. The employee must enroll again.' : 'Nothing to reset.', 'reset' => $n]);
        break;
    }

    case 'footwear.enroll_image': {
        // Streams one enrolled photo (Admin / HR, or the employee's own). <img> tags can't send a header, so ?token= works too.
        $auth = !empty($_GET['token']) ? verify_token((string)$_GET['token']) : require_auth();
        if (!$auth) json_response(['error' => 'Unauthorized.'], 401);
        if (!ensure_footwear_enroll_tables($pdo)) json_response(['error' => 'No photos.'], 404);
        $st = $pdo->prepare("SELECT e.employee_id, p.photo_path FROM footwear_enroll e JOIN footwear_enroll_photos p ON p.enroll_id = e.enroll_id WHERE e.enroll_id = ? AND p.side = ?");
        $st->execute([(int)($_GET['enroll_id'] ?? 0), (int)($_GET['side'] ?? 0)]);
        $r = $st->fetch();
        if (!$r) json_response(['error' => 'Not found.'], 404);
        if (empty($auth['employee_id']) || (int)$auth['employee_id'] !== (int)$r['employee_id']) require_role(['Admin', 'HR'], $auth);
        $f = __DIR__ . '/' . $r['photo_path'];
        if (!is_file($f)) json_response(['error' => 'The photo is missing.'], 404);
        header('Content-Type: image/jpeg'); header('Content-Length: ' . filesize($f)); header('Cache-Control: private, max-age=300');
        readfile($f);
        exit;
    }

    case 'attendance.punch': {
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin', 'HR', 'Employee'], true) && !user_can($auth, 'punch')) {
            json_response(['error' => 'Your role does not have Punch In / Out access.'], 403);
        }
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);

        attendance_cleanup_photos($pdo);

        $type = $_POST['type'] ?? '';
        if (!in_array($type, ['in', 'out'], true)) json_response(['error' => 'type must be in or out.'], 422);
        if (!isset($_FILES['photo']) || $_FILES['photo']['error'] !== UPLOAD_ERR_OK) {
            json_response(['error' => 'A camera photo is required.'], 422);
        }

        $empId = (int)$auth['employee_id'];

        // Location gate: the phone sends its GPS fix; the server measures the
        // distance to the employee's office itself, so the page can't be
        // edited around it. Every try is logged (see attendance.attempts).
        $gLat = isset($_POST['lat']) && $_POST['lat'] !== '' ? (float)$_POST['lat'] : null;
        $gLng = isset($_POST['lng']) && $_POST['lng'] !== '' ? (float)$_POST['lng'] : null;
        $gAcc = isset($_POST['accuracy']) && $_POST['accuracy'] !== '' ? (float)$_POST['accuracy'] : null;
        [$geoOk, $office, $dist, $geoWhy] = geo_check_punch($pdo, $empId, $gLat, $gLng, $gAcc);
        if (!$geoOk) {
            log_punch_attempt($pdo, $empId, $type, $office, $dist, $gLat, $gLng, $gAcc, false, $geoWhy);
            json_response(['error' => $geoWhy, 'distance_m' => $dist === null ? null : (int)round($dist), 'office' => $office ? $office['office_name'] : null], 403);
        }
        // The attendance day follows the Day timing rule (default 10 AM to
        // next day 10 AM), so a shift that runs past midnight stays one row:
        // a 1 AM punch-out closes the previous evening's punch-in.
        $today = $type === 'in' ? punch_in_day($pdo, time()) : biz_today($pdo);
        $open = attendance_open_row($pdo, $empId);

        if ($type === 'in') {
            if ($open) json_response(['error' => 'You are still punched in from ' . date('d M, h:i A', strtotime($open['punch_in'])) . ' — punch out first.'], 409);
            $stmt = $pdo->prepare("SELECT * FROM attendance WHERE employee_id = ? AND punch_date = ?");
            $stmt->execute([$empId, $today]);
            $row = $stmt->fetch();
            if ($row && $row['punch_in']) {
                // That business day is already done; before the day-start
                // time this is an early start of the new calendar day.
                if ($today !== date('Y-m-d')) {
                    $today = date('Y-m-d');
                    $stmt->execute([$empId, $today]);
                    $row = $stmt->fetch();
                    if ($row && $row['punch_in']) json_response(['error' => 'Already punched in today at ' . date('h:i A', strtotime($row['punch_in'])) . '.'], 409);
                } else {
                    json_response(['error' => 'Already punched in today at ' . date('h:i A', strtotime($row['punch_in'])) . '.'], 409);
                }
            }
        } else {
            if (!$open) json_response(['error' => 'Punch in first.'], 409);
            $row = $open;
            $today = $row['punch_date'];
            // Store staff: the opening checklist must be submitted first.
            $shift = emp_shift($pdo, $empId, $today);
            if ($shift['is_store']) {
                $why = store_punch_block($pdo, $empId, $today, 'out');
                if ($why !== '') json_response(['error' => $why, 'checklist' => store_day_state($pdo, $empId, $today)], 409);
            }
            // Photo categories: the "After Punch In" and "Before Punch Out" ones must be finished first.
            $why = photocat_punch_block($pdo, $empId, $today, 'out');
            if ($why !== '') json_response(['error' => $why, 'categories' => photocat_day_state($pdo, $empId, $today)], 409);
            // (The Sales call-recording gate at Punch Out ended on 1 Nov 2026.)
        }

        // Store staff: the "Before Punch In" tasks (photos) come first. Checked for the day the upload used, and for the day the punch lands on.
        if ($type === 'in' && emp_shift($pdo, $empId, $today)['is_store']) {
            $why = store_punch_block($pdo, $empId, $today, 'in');
            $d2 = attendance_day_now($pdo);
            if ($why !== '' && $d2 !== $today && store_punch_block($pdo, $empId, $d2, 'in') === '') $why = '';
            if ($why !== '') json_response(['error' => $why, 'checklist' => store_day_state($pdo, $empId, $today)], 409);
        }

        // Photo categories: the "Before Punch In" ones come first. Checked for the day the upload used, and for the day the punch lands on.
        if ($type === 'in') {
            $why = photocat_punch_block($pdo, $empId, $today, 'in');
            $d2 = attendance_day_now($pdo);
            if ($why !== '' && $d2 !== $today && photocat_punch_block($pdo, $empId, $d2, 'in') === '') $why = '';
            if ($why !== '') json_response(['error' => $why, 'categories' => photocat_day_state($pdo, $empId, $today)], 409);
        }

        // Punch-in proofs (Instagram / YouTube comment screenshots, plus any the admin added): every requirement that
        // applies to this employee must have its screenshot for today before Punch In is accepted.
        if ($type === 'in') {
            // A once-only proof (ID card …) that this already-enrolled person has not given yet: asked one time, before this Punch In.
            if ($once = proof_once_pending($pdo, $empId)) {
                json_response(['error' => 'One-time step first — ' . implode(', ', $once['missing']) . '.', 'proofs' => $once], 409);
            }
            $pf = proof_state($pdo, $empId, $today);
            if ($pf['total'] && !$pf['complete']) {
                json_response(['error' => 'Upload your punch-in proof first — ' . implode(', ', $pf['missing']) . '.', 'proofs' => $pf], 409);
            }
        }

        // Footwear check: Punch In is accepted only with the footwear photo that was approved by attendance.footwear_check a moment ago.
        $fwRow = null;
        if ($type === 'in' && footwear_step_needed($pdo, $empId)) {
            $fh = (isset($_FILES['footwear']) && $_FILES['footwear']['error'] === UPLOAD_ERR_OK) ? (string)hash_file('sha256', $_FILES['footwear']['tmp_name']) : '';
            $fwRow = $fh !== '' ? footwear_approved_row($pdo, $empId, $fh) : null;
            if (!$fwRow) json_response(['error' => 'Footwear check needed — take a photo of your shoes and get it approved first.', 'check' => 'footwear', 'footwear_required' => true], 409);
        }

        $uploadDir = __DIR__ . '/uploads/attendance/';
        if (!is_dir($uploadDir)) mkdir($uploadDir, 0755, true);
        $safeName = 'punch_' . $empId . '_' . $type . '_' . time() . '_' . bin2hex(random_bytes(3)) . '.jpg';
        if (!move_uploaded_file($_FILES['photo']['tmp_name'], $uploadDir . $safeName)) {
            json_response(['error' => 'Failed to save punch photo.'], 500);
        }
        $photoPath = 'uploads/attendance/' . $safeName;
        $now = date('Y-m-d H:i:s');

        $oid = (int)$office['office_id']; $dm = (int)round($dist);
        if (!$row) {
            $pdo->prepare("INSERT INTO attendance (employee_id, punch_date, punch_in, punch_in_photo, in_office_id, in_distance_m) VALUES (?, ?, ?, ?, ?, ?)")
                ->execute([$empId, $today, $now, $photoPath, $oid, $dm]);
        } elseif ($type === 'in') {
            $pdo->prepare("UPDATE attendance SET punch_in = ?, punch_in_photo = ?, in_office_id = ?, in_distance_m = ? WHERE attendance_id = ?")
                ->execute([$now, $photoPath, $oid, $dm, $row['attendance_id']]);
        } else {
            $pdo->prepare("UPDATE attendance SET punch_out = ?, punch_out_photo = ?, out_office_id = ?, out_distance_m = ? WHERE attendance_id = ?")
                ->execute([$now, $photoPath, $oid, $dm, $row['attendance_id']]);
        }
        log_punch_attempt($pdo, $empId, $type, $office, $dist, $gLat, $gLng, $gAcc, true, '');
        if ($fwRow) {
            $aid = (int)($row['attendance_id'] ?? 0) ?: (int)$pdo->lastInsertId();
            $pdo->prepare("UPDATE footwear_checks SET used_at = ?, attendance_id = ? WHERE check_id = ?")->execute([$now, $aid ?: null, $fwRow['check_id']]);
        }

        json_response(['message' => ($type === 'in' ? 'Punched in' : 'Punched out') . ' at ' . date('h:i A') . ' · ' . $office['office_name'] . ' (' . $dm . ' m).', 'time' => $now, 'office' => $office['office_name'], 'distance_m' => $dm]);
        break;
    }

    // ============== OFFICE LOCATIONS (geo-fenced punch) ==============
    case 'offices.options': {
        // For dropdowns (Employee form). Any login.
        require_auth();
        $out = [];
        if (ensure_offices_tables($pdo)) $out = $pdo->query("SELECT office_id, office_name, radius_m FROM offices WHERE is_active = 1 ORDER BY office_name")->fetchAll();
        json_response(['offices' => $out]);
        break;
    }

    case 'offices.list': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_offices_tables($pdo)) json_response(['error' => 'Could not create the offices tables.'], 500);
        $offices = $pdo->query("SELECT * FROM offices ORDER BY is_active DESC, office_name")->fetchAll();
        // Punches made at each office today (from the attendance rows).
        $todayCounts = [];
        try {
            $st = $pdo->prepare("SELECT in_office_id AS oid, COUNT(*) c FROM attendance WHERE punch_date = ? AND in_office_id IS NOT NULL GROUP BY in_office_id");
            $st->execute([biz_today($pdo)]);
            foreach ($st->fetchAll() as $r) $todayCounts[(int)$r['oid']] = (int)$r['c'];
        } catch (PDOException $e) {}
        foreach ($offices as &$o) $o['punches_today'] = $todayCounts[(int)$o['office_id']] ?? 0;
        unset($o);
        $refusedToday = 0;
        try {
            $st = $pdo->prepare("SELECT COUNT(*) FROM punch_attempts WHERE result = 'refused' AND created_at >= ?");
            $st->execute([date('Y-m-d') . ' 00:00:00']);
            $refusedToday = (int)$st->fetchColumn();
        } catch (PDOException $e) {}
        json_response(['offices' => $offices, 'refused_today' => $refusedToday]);
        break;
    }

    case 'offices.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_offices_tables($pdo)) json_response(['error' => 'Could not create the offices tables.'], 500);
        $in = json_input();
        $id = (int)($in['office_id'] ?? 0);
        $name = trim((string)($in['office_name'] ?? ''));
        $addr = trim((string)($in['address'] ?? ''));
        $lat = isset($in['lat']) && $in['lat'] !== '' ? (float)$in['lat'] : null;
        $lng = isset($in['lng']) && $in['lng'] !== '' ? (float)$in['lng'] : null;
        $radius = (int)($in['radius_m'] ?? 100);
        $active = isset($in['is_active']) ? ((int)$in['is_active'] ? 1 : 0) : 1;
        if ($name === '') json_response(['error' => 'Office name is required.'], 422);
        if ($lat === null || $lng === null || abs($lat) > 90 || abs($lng) > 180) json_response(['error' => 'Valid latitude and longitude are required (use "Use my current location" or paste a Google Maps link).'], 422);
        if ($radius < 10 || $radius > 5000) json_response(['error' => 'Radius must be between 10 and 5000 metres.'], 422);
        if ($id) {
            $pdo->prepare("UPDATE offices SET office_name = ?, address = ?, lat = ?, lng = ?, radius_m = ?, is_active = ? WHERE office_id = ?")
                ->execute([$name, $addr ?: null, $lat, $lng, $radius, $active, $id]);
        } else {
            $pdo->prepare("INSERT INTO offices (office_name, address, lat, lng, radius_m, is_active) VALUES (?, ?, ?, ?, ?, ?)")
                ->execute([$name, $addr ?: null, $lat, $lng, $radius, $active]);
            $id = (int)$pdo->lastInsertId();
        }
        json_response(['message' => 'Office saved.', 'office_id' => $id]);
        break;
    }

    case 'offices.delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_offices_tables($pdo);
        $id = (int)(json_input()['office_id'] ?? 0);
        if (!$id) json_response(['error' => 'office_id is required.'], 422);
        $pdo->prepare("DELETE FROM offices WHERE office_id = ?")->execute([$id]);
        json_response(['message' => 'Office location deleted.']);
        break;
    }

    case 'me.offices': {
        // Every allowed punch location (centre + radius) for the punch page.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $out = [];
        foreach (active_offices($pdo) as $o) {
            $out[] = ['office_id' => (int)$o['office_id'], 'office_name' => $o['office_name'], 'address' => $o['address'], 'lat' => (float)$o['lat'], 'lng' => (float)$o['lng'], 'radius_m' => (int)$o['radius_m']];
        }
        json_response(['offices' => $out]);
        break;
    }

    case 'attendance.face_fail': {
        // The phone tells us a face check failed and why (look-alike / too far / no match / not live) with the scores,
        // so Admin sees it in Refused punches and can tell a wrong refusal from a real one. Only a log: nothing is decided here.
        $auth = require_auth();
        if (empty($auth['employee_id']) || $_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['ok' => true]);
        $in = json_input();
        $kinds = ['lookalike' => 'looks like another employee', 'far' => 'face too far from the camera', 'nomatch' => 'face not recognized', 'notlive' => 'no blink / head turn seen'];
        $k = (string)($in['kind'] ?? ''); if (!isset($kinds[$k])) json_response(['ok' => true]);
        $best = isset($in['best']) && is_numeric($in['best']) ? round((float)$in['best'], 3) : null; $oth = isset($in['other']) && is_numeric($in['other']) ? round((float)$in['other'], 3) : null;
        $type = ($in['type'] ?? 'in') === 'out' ? 'out' : 'in';
        ensure_offices_tables($pdo);
        $why = 'Face check: ' . $kinds[$k] . ($best !== null ? ' (closest score ' . $best . ($oth !== null ? ', nearest other employee ' . $oth : '') . ')' : '');
        log_punch_attempt($pdo, (int)$auth['employee_id'], $type, null, null, null, null, null, false, $why);
        json_response(['ok' => true]);
        break;
    }

    case 'attendance.attempts': {
        // Refused (and ok) punch tries for a date — Attendance admin page.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_offices_tables($pdo);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $only = ($_GET['result'] ?? 'refused');
        $st = $pdo->prepare(
            "SELECT p.*, e.full_name, e.employee_code, o.office_name
             FROM punch_attempts p
             JOIN employees e ON e.employee_id = p.employee_id
             LEFT JOIN offices o ON o.office_id = p.office_id
             WHERE p.created_at >= ? AND p.created_at < ?" . ($only === 'all' ? '' : " AND p.result = 'refused'") . "
             ORDER BY p.created_at DESC LIMIT 500"
        );
        $st->execute([$date . ' 00:00:00', date('Y-m-d', strtotime($date . ' +1 day')) . ' 00:00:00']);
        json_response(['date' => $date, 'attempts' => $st->fetchAll()]);
        break;
    }

    case 'attendance.today': {
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        // An unfinished shift (even from yesterday's date, for shifts that
        // run past midnight) is what the page must show, so Punch Out stays
        // available; otherwise the current business day's row.
        // "Today" here follows the punch-in rule, so an employee whose shift starts
        // before the day-start time (9:00 against a 10:00 day start) sees a fresh,
        // empty day when they arrive — not yesterday's finished punch in / out.
        $open = attendance_open_row($pdo, (int)$auth['employee_id']);
        $myShift = emp_shift($pdo, (int)$auth['employee_id']);
        $myDay = attendance_day_now($pdo);
        $nm = $pdo->prepare("SELECT full_name FROM employees WHERE employee_id = ?");
        $nm->execute([(int)$auth['employee_id']]);
        $myName = (string)($nm->fetchColumn() ?: '');
        if ($open) json_response(['attendance' => $open, 'business_day' => $myDay, 'shift' => $myShift, 'employee_name' => $myName, 'footwear_required' => footwear_step_needed($pdo, (int)$auth['employee_id']), 'shoe_enrolled' => footwear_is_enrolled($pdo, (int)$auth['employee_id']), 'any_footwear' => employee_is_female($pdo, (int)$auth['employee_id'])]);
        $stmt = $pdo->prepare(
            "SELECT a.*, e.full_name, e.employee_code FROM attendance a
             JOIN employees e ON e.employee_id = a.employee_id
             WHERE a.employee_id = ? AND a.punch_date = ?"
        );
        $stmt->execute([$auth['employee_id'], $myDay]);
        json_response(['attendance' => $stmt->fetch() ?: null, 'business_day' => $myDay, 'shift' => $myShift, 'employee_name' => $myName, 'footwear_required' => footwear_step_needed($pdo, (int)$auth['employee_id']), 'shoe_enrolled' => footwear_is_enrolled($pdo, (int)$auth['employee_id']), 'any_footwear' => employee_is_female($pdo, (int)$auth['employee_id'])]);
        break;
    }

    case 'analytics.url': {
        // The Analytics page asks here for the report link. Admin, or a role Admin ticked "Analytics" for (the permission map enforces it).
        $auth = require_auth();
        if (!in_array($auth['role'] ?? '', ['Admin'], true) && !user_can($auth, 'analytics')) json_response(['error' => 'Your role does not have Analytics access.'], 403);
        // The link carries a secret key, so it is never written in GitHub or in a page file. The server reads it from where the report keeps it:
        // the 'viewkey' in the analytics folder's own config.php (next to report.php). Optional override: define('ANALYTICS_REPORT_URL', '…') in this folder's config.php.
        if (defined('ANALYTICS_REPORT_URL') && ANALYTICS_REPORT_URL !== '') json_response(['url' => ANALYTICS_REPORT_URL]);
        $acf = dirname(__DIR__) . '/analytics/config.php'; $vk = '';
        if (is_file($acf)) { try { $ac = require $acf; if (is_array($ac)) $vk = (string)($ac['viewkey'] ?? ''); } catch (Throwable $e) { $vk = ''; } }
        if ($vk === '') json_response(['error' => 'Analytics is not set up yet: the report needs a viewkey in analytics/config.php (the same one you use in its link).'], 422);
        $host = preg_replace('/[^A-Za-z0-9.\-:]/', '', (string)($_SERVER['HTTP_HOST'] ?? 'fourpirates.space'));
        json_response(['url' => 'https://' . $host . '/analytics/report.php?k=' . rawurlencode($vk)]);
        break;
    }

    case 'files.view': {
        // Opens any uploaded file (documents, photos, signatures, agreements)
        // through api.php instead of a direct /uploads/… link. Direct links
        // 404 on this hosting, and files uploaded before the domain move
        // live in the old domain's folder — find_upload_on_account() looks in
        // both. Admin/HR can open any file; an employee only their own.
        // A plain <a href> can't send the Authorization header, so the
        // login token may also come in the link (?token=…). Pages build such
        // links themselves, so this works even if a script is cached or
        // fails to run.
        if (empty($_GET['token'])) {
            $auth = require_auth();
        } else {
            $auth = verify_token((string)$_GET['token']);
            if (!$auth) json_response(['error' => 'Unauthorized. Please log in again.'], 401);
            $auth = refresh_auth($auth);
        }
        $rel = ltrim(str_replace('\\', '/', (string)($_GET['path'] ?? '')), '/');
        if ($rel === '' || strpos($rel, 'uploads/') !== 0 || strpos($rel, '..') !== false) {
            json_response(['error' => 'Invalid file path.'], 422);
        }

        // Any role granted a module that shows other people's files
        // (Documents, Attendance, Agreements, Employees, Approvals, Decline
        // History) may open them; otherwise only the employee's own files.
        $canAny = in_array($auth['role'] ?? '', ['Admin', 'HR'], true);
        foreach (['documents', 'attendance', 'agreements', 'employees', 'approvals', 'decline_history', 'retail'] as $m) {
            if ($canAny) break;
            if (user_can($auth, $m)) $canAny = true;
        }
        if (!$canAny) {
            $eid = (int)($auth['employee_id'] ?? 0);
            // Their own signature image is named by their id and isn't always
            // recorded in a table (older installs lack the column).
            $owns = $eid > 0 && $rel === 'uploads/agreements/sig_' . $eid . '.png';
            foreach ([
                "SELECT 1 FROM employee_documents WHERE employee_id = ? AND document_file = ? LIMIT 1",
                "SELECT 1 FROM agreements WHERE employee_id = ? AND signed_file = ? LIMIT 1",
                "SELECT 1 FROM attendance WHERE employee_id = ? AND (punch_in_photo = ? OR punch_out_photo = ?) LIMIT 1",
                "SELECT 1 FROM employees WHERE employee_id = ? AND (photo = ? OR signature_file = ?) LIMIT 1",
                "SELECT 1 FROM store_task_photos WHERE employee_id = ? AND photo = ? LIMIT 1",
                "SELECT 1 FROM punch_proofs WHERE employee_id = ? AND file = ? LIMIT 1",
                "SELECT 1 FROM photo_cat_photos WHERE employee_id = ? AND photo = ? LIMIT 1",
            ] as $sql) {
                try {
                    $st = $pdo->prepare($sql);
                    $n = substr_count($sql, '?');
                    $st->execute($n === 3 ? [$eid, $rel, $rel] : [$eid, $rel]);
                    if ($st->fetchColumn()) { $owns = true; break; }
                } catch (PDOException $e) { /* column may not exist on older schemas */ }
            }
            if (!$eid || !$owns) json_response(['error' => 'You do not have access to this file.'], 403);
        }

        $abs = find_upload_on_account($rel);
        if (!$abs) {
            json_response([
                'error' => 'This file is recorded but missing on the server. Ask for it to be uploaded again.',
                'expected_path' => __DIR__ . '/' . $rel,
            ], 404);
        }

        $mime = function_exists('mime_content_type') ? (mime_content_type($abs) ?: 'application/octet-stream') : 'application/octet-stream';
        // Small pictures (list avatars): ?w=96 sends a small cached JPEG instead of the full phone photo (a 3 MB photo became ~4 KB).
        $tw = (int)($_GET['w'] ?? 0);
        if ($tw >= 16 && $tw <= 512 && strpos($mime, 'image/') === 0 && in_array($mime, ['image/jpeg', 'image/png', 'image/webp', 'image/gif'], true)
            && function_exists('imagecreatefromstring') && function_exists('imagejpeg')) {
            try {
                $tdir = __DIR__ . '/uploads/.thumbs/';
                if (!is_dir($tdir)) { @mkdir($tdir, 0755, true); @file_put_contents($tdir . '.htaccess', "Require all denied\n<IfModule !mod_authz_core.c>\nDeny from all\n</IfModule>\n"); }
                $tf = $tdir . md5($abs . '|' . $tw . '|' . @filemtime($abs)) . '.jpg';
                if (!is_file($tf) && @filesize($abs) < 25 * 1024 * 1024) {
                    $im = @imagecreatefromstring((string)@file_get_contents($abs));
                    if ($im) {
                        $w0 = imagesx($im); $h0 = imagesy($im);
                        if ($w0 > $tw) { $im2 = imagescale($im, $tw, (int)max(1, round($h0 * $tw / $w0))); if ($im2) { imagedestroy($im); $im = $im2; } }
                        $bg = imagecreatetruecolor(imagesx($im), imagesy($im)); imagefill($bg, 0, 0, imagecolorallocate($bg, 255, 255, 255)); imagecopy($bg, $im, 0, 0, 0, 0, imagesx($im), imagesy($im));
                        @imagejpeg($bg, $tf, 78); imagedestroy($bg); imagedestroy($im);
                    }
                }
                if (is_file($tf) && filesize($tf) > 0) { $abs = $tf; $mime = 'image/jpeg'; }
            } catch (Throwable $thE) { /* any trouble: send the original */ }
        }
        header('Content-Type: ' . $mime);
        header('Content-Length: ' . filesize($abs));
        header('Content-Disposition: inline; filename="' . basename($abs) . '"');
        header('Cache-Control: private, max-age=' . ($tw ? 86400 : 300));
        header('X-Content-Type-Options: nosniff');
        readfile($abs);
        exit;
    }

    case 'attendance.photo': {
        // Streams a punch photo through api.php instead of linking straight
        // to /uploads/attendance/...jpg. Two reasons:
        //  1. It reads from __DIR__, the exact folder the punch was saved to,
        //     so it works even when the public URL for /uploads/ doesn't map
        //     to that folder on the server (the cause of the 404s).
        //  2. Punch photos are employees' faces — a direct URL let anyone who
        //     had the link view them without logging in. This requires a login.
        // Auth: Admin/HR, or the employee viewing their own photo.
        $auth = require_auth();
        $empId = (int)($_GET['employee_id'] ?? 0);
        $date = $_GET['date'] ?? '';
        $which = ($_GET['which'] ?? 'in') === 'out' ? 'out' : 'in';
        if (!$empId || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            json_response(['error' => 'employee_id and date are required.'], 422);
        }
        $isOwner = !empty($auth['employee_id']) && (int)$auth['employee_id'] === $empId;
        if (!$isOwner) require_role(['Admin', 'HR'], $auth);

        $col = $which === 'out' ? 'punch_out_photo' : 'punch_in_photo';
        $st = $pdo->prepare("SELECT $col FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $rel = (string)$st->fetchColumn();
        if ($rel === '') json_response(['error' => 'No photo recorded for this punch (photos are removed automatically after 48 hours).'], 404);

        // Look here first, then anywhere else on the hosting account (a punch
        // sent to the old server saves its photo in the old domain's folder).
        $abs = find_attendance_photo_on_account($rel);
        if (!$abs) {
            json_response([
                'error' => 'The photo is recorded but the file is missing on the server.',
                'expected_path' => __DIR__ . '/' . $rel,
            ], 404);
        }

        header('Content-Type: image/jpeg');
        header('Content-Length: ' . filesize($abs));
        header('Content-Disposition: inline; filename="' . basename($abs) . '"');
        header('Cache-Control: private, max-age=300');
        readfile($abs);
        exit;
    }

    case 'attendance.list': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        attendance_cleanup_photos($pdo);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $editedCol = ensure_attendance_edited_column($pdo) ? 'a.edited_by' : 'NULL AS edited_by';
        $geoCols = ensure_offices_tables($pdo)
            ? "a.in_distance_m, a.out_distance_m, oi.office_name AS in_office, oo.office_name AS out_office"
            : "NULL AS in_distance_m, NULL AS out_distance_m, NULL AS in_office, NULL AS out_office";
        $geoJoin = ensure_offices_tables($pdo)
            ? "LEFT JOIN offices oi ON oi.office_id = a.in_office_id LEFT JOIN offices oo ON oo.office_id = a.out_office_id"
            : "";
        $stmt = $pdo->prepare(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.department_id,
                    a.punch_in, a.punch_out, a.punch_in_photo, a.punch_out_photo, $editedCol,
                    (e.face_descriptor IS NOT NULL) AS face_enrolled, $geoCols
             FROM employees e
             LEFT JOIN attendance a ON a.employee_id = e.employee_id AND a.punch_date = ?
             $geoJoin
             WHERE e.status != 'ex'
             ORDER BY e.full_name"
        );
        $stmt->execute([$date]);
        $rows = $stmt->fetchAll();
        // Punches filed under another date (the old rule counted an early
        // arrival on the previous day, so the person showed Absent here).
        // Any punch that belongs to this day by the punch-in rule is shown on
        // this day, and an early-arrival one is moved onto it for good so the
        // month view and salary agree.
        $missing = [];
        foreach ($rows as $r0) if (!$r0['punch_in']) $missing[(int)$r0['employee_id']] = true;
        if ($missing) {
            $mf = $pdo->prepare(
                "SELECT attendance_id, employee_id, punch_date, punch_in, punch_out, punch_in_photo, punch_out_photo
                 FROM attendance
                 WHERE punch_in IS NOT NULL AND punch_date <> ?
                   AND punch_in >= ? AND punch_in < ?
                 ORDER BY punch_in"
            );
            $mf->execute([$date, date('Y-m-d', strtotime($date . ' -1 day')) . ' 00:00:00', date('Y-m-d', strtotime($date . ' +2 day')) . ' 00:00:00']);
            $found = [];
            foreach ($mf->fetchAll() as $m) {
                $eid = (int)$m['employee_id'];
                if (empty($missing[$eid]) || isset($found[$eid])) continue;
                $ts = strtotime((string)$m['punch_in']);
                if (punch_in_day($pdo, $ts) !== $date) continue;
                $found[$eid] = $m;
            }
            if ($found) {
                $fix = $pdo->prepare("UPDATE attendance SET punch_date = ? WHERE attendance_id = ?");
                foreach ($rows as &$r1) {
                    $eid = (int)$r1['employee_id'];
                    if (!isset($found[$eid])) continue;
                    $m = $found[$eid];
                    $r1['punch_in'] = $m['punch_in'];
                    $r1['punch_out'] = $m['punch_out'];
                    $r1['punch_in_photo'] = $m['punch_in_photo'];
                    $r1['punch_out_photo'] = $m['punch_out_photo'];
                    try { $fix->execute([$date, (int)$m['attendance_id']]); } catch (PDOException $e) { /* shown anyway */ }
                }
                unset($r1);
            }
        }
        // Each row carries that employee's own working time, whether they are
        // late against it, and (store staff only) the opening checklist.
        $shifts = emp_shift_map($pdo, $date);
        $defStart = day_start_for($pdo, $date);
        $dayMarks = day_marks_between($pdo, $date, $date);
        // Punch-in proofs: the requirements in force, each employee's department, and the screenshots sent on this day.
        $proofRules = proof_rules_all($pdo, true);
        $proofDept = []; $proofCnt = [];
        if ($proofRules) {
            try {
                foreach ($pdo->query("SELECT employee_id, department_id FROM employees")->fetchAll() as $pe) $proofDept[(int)$pe['employee_id']] = (int)$pe['department_id'];
                // the day's proofs, plus the ones asked once at the Enroll step (kept under a fixed day)
                $pc = $pdo->prepare("SELECT employee_id, rule_id, status, work_date, COUNT(*) AS c FROM punch_proofs WHERE work_date IN (?, ?) GROUP BY employee_id, rule_id, status, work_date");
                $pc->execute([$date, PROOF_ENROLL_DAY]);
                foreach ($pc->fetchAll() as $pe) {
                    $k = (int)$pe['employee_id'] . '|' . (int)$pe['rule_id'] . ((string)$pe['work_date'] === PROOF_ENROLL_DAY ? '|e' : '|d');
                    if (!isset($proofCnt[$k])) $proofCnt[$k] = ['ok' => 0, 'rej' => 0];
                    $proofCnt[$k][$pe['status'] === 'ok' ? 'ok' : 'rej'] += (int)$pe['c'];
                }
            } catch (PDOException $e) {}
        }
        foreach ($rows as &$r) {
            $id = (int)$r['employee_id'];
            $r['mark'] = $dayMarks[$date . '|' . $id] ?? null;
            $s = $shifts[$id] ?? ['shift_start' => $defStart, 'shift_end' => '', 'late_after' => 15, 'is_store' => 0, 'own' => 0];
            $r['shift_start'] = $s['shift_start'];
            $r['shift_end'] = $s['shift_end'];
            $r['late_after'] = $s['late_after'];
            $r['own_shift'] = $s['own'];
            $r['is_store'] = $s['is_store'];
            $r['mode'] = $s['mode'] ?? 'fixed';
            $r['hours_target'] = $s['hours_target'] ?? 0;
            $r['hours_full'] = $s['hours_full'] ?? 0;
            $r['win_from'] = $s['win_from'] ?? '';
            $r['win_to'] = $s['win_to'] ?? '';
            $r['late_minutes'] = null;
            $r['worked_min'] = null; $r['short_min'] = null; $r['left_min'] = null;
            if ($r['punch_in']) {
                $in = strtotime((string)$r['punch_in']);
                $due = strtotime($date . ' ' . $s['shift_start'] . ':00') + $s['late_after'] * 60;
                $r['late_minutes'] = $in > $due ? (int)round(($in - $due) / 60) : 0;
                if ($r['mode'] === 'hours') {
                    // hours-only people: how much of the day's hours is done / still to do / missed
                    $outT = $r['punch_out'] ? strtotime((string)$r['punch_out']) : 0;
                    $wk = (int)floor((($outT > $in ? $outT : time()) - $in) / 60);
                    $r['worked_min'] = max(0, $wk);
                    if ($outT > $in) $r['short_min'] = $wk < (int)round($s['hours_full'] * 60) ? max(0, (int)round($s['hours_target'] * 60) - $wk) : 0;
                    else $r['left_min'] = max(0, (int)round($s['hours_target'] * 60) - $wk);
                }
            }
            if ($s['is_store']) {
                $st2 = store_day_state($pdo, $id, $date);
                $r['checklist'] = [
                    'tasks_done' => $st2['tasks_done'], 'tasks_total' => $st2['tasks_total'],
                    'photos_have' => $st2['photos_have'], 'photos_need' => $st2['photos_need'],
                    'submitted_at' => $st2['submitted_at'], 'complete' => $st2['complete'],
                    'phases' => array_map(fn($p) => ['tasks_done' => $p['tasks_done'], 'tasks_total' => $p['tasks_total'], 'photos_have' => $p['photos_have'], 'photos_need' => $p['photos_need'], 'complete' => $p['complete']], $st2['phases']),
                ];
            } else {
                $r['checklist'] = null;
            }
            $r['proofs'] = [];
            if ($proofRules) {
                $dp = $proofDept[$id] ?? 0;
                foreach ($proofRules as $pr) {
                    if (!proof_rule_applies($pr, $id, $dp)) continue;
                    $c = $proofCnt[$id . '|' . $pr['rule_id'] . ($pr['stage'] === 'enroll' ? '|e' : '|d')] ?? ['ok' => 0, 'rej' => 0];
                    // A proof asked once at Enroll: shown only while the face is not enrolled yet, or once something was uploaded for it.
                    if ($pr['stage'] === 'enroll' && empty($pr['ask_enrolled']) && !$c['ok'] && !$c['rej'] && !empty($r['face_enrolled'])) continue;
                    $r['proofs'][] = [
                        'rule_id' => $pr['rule_id'], 'kind' => $pr['kind'], 'title' => $pr['title'], 'stage' => $pr['stage'],
                        'have' => $c['ok'], 'need' => $pr['shots_required'],
                        'done' => $c['ok'] >= $pr['shots_required'] ? 1 : 0,
                        'redo' => ($c['ok'] < $pr['shots_required'] && $c['rej'] > 0) ? 1 : 0,
                    ];
                    // Enrolled ID card checked every day: a second chip for today's card.
                    if ($pr['stage'] === 'enroll' && $pr['capture'] === 'idcard' && !empty($pr['daily_check']) && $c['ok'] > 0) {
                        $cd = $proofCnt[$id . '|' . $pr['rule_id'] . '|d'] ?? ['ok' => 0, 'rej' => 0];
                        $r['proofs'][] = ['rule_id' => $pr['rule_id'], 'kind' => $pr['kind'], 'title' => $pr['title'] . ' — today', 'stage' => 'punch', 'daily' => 1,
                            'have' => $cd['ok'], 'need' => 1, 'done' => $cd['ok'] >= 1 ? 1 : 0, 'redo' => (!$cd['ok'] && $cd['rej'] > 0) ? 1 : 0];
                    }
                }
            }
        }
        unset($r);
        // Same person listed twice (two employee records with one name): the punch may sit on the OTHER record,
        // which is why this one reads Absent. Say so on the row instead of leaving it a mystery.
        $byName = [];
        foreach ($rows as $i => $r2) $byName[mb_strtolower(preg_replace('/\s+/', ' ', trim((string)$r2['full_name'])))][] = $i;
        foreach ($byName as $idxs) {
            if (count($idxs) < 2) continue;
            foreach ($idxs as $i) {
                $others = [];
                foreach ($idxs as $j) {
                    if ($j === $i) continue;
                    $others[] = ['employee_code' => $rows[$j]['employee_code'], 'punch_in' => $rows[$j]['punch_in'], 'punch_out' => $rows[$j]['punch_out']];
                }
                $rows[$i]['same_name'] = $others;
            }
        }
        json_response(['date' => $date, 'rows' => $rows, 'day_start' => $defStart]);
        break;
    }

    case 'attendance.set_day': {
        // Admin / HR sets one employee's day: Present (with punch times) or WFH /
        // Leave / Half leave (a day mark — what the salary calculation reads), or
        // Absent (nothing). A day mark replaces the punch record and the other way
        // round, so the day never says two things. Removing an existing punch
        // record needs remove_punch = true (the page asks first).
        // Also used by the Salary page (which adds Holiday / Week off as day marks).
        $auth = require_auth();
        if (!orders_page_controls($auth) && !(strtolower(trim((string)($auth['role'] ?? ''))) !== 'employee' && user_can($auth, 'salary'))) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_attendance_edited_column($pdo);
        ensure_day_marks_table($pdo);
        $in = json_input();
        $empId = (int)($in['employee_id'] ?? 0);
        $date = (string)($in['date'] ?? '');
        $status = trim((string)($in['status'] ?? ''));
        $tIn = trim((string)($in['punch_in'] ?? ''));
        $tOut = trim((string)($in['punch_out'] ?? ''));
        $removePunch = !empty($in['remove_punch']);
        if (!$empId || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'employee_id and date are required.'], 422);
        if (!in_array($status, ['present', 'wfh', 'leave', 'half_leave', 'holiday', 'week_off', 'absent'], true)) json_response(['error' => 'Status must be present, wfh, leave, half_leave, holiday, week_off or absent.'], 422);
        $who = (string)($auth['username'] ?? 'admin');

        $stmt = $pdo->prepare("SELECT * FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $stmt->execute([$empId, $date]);
        $row = $stmt->fetch();

        if ($status === 'present') {
            foreach ([$tIn, $tOut] as $t) if ($t !== '' && !preg_match('/^\d{2}:\d{2}$/', $t)) json_response(['error' => 'Times must be HH:MM (24-hour).'], 422);
            if ($tIn === '') json_response(['error' => 'Type the punch in time.'], 422);
            $punchIn = $date . ' ' . $tIn . ':00';
            $punchOut = null;
            if ($tOut !== '') $punchOut = ($tOut < $tIn ? date('Y-m-d', strtotime($date . ' +1 day')) : $date) . ' ' . $tOut . ':00';
            if ($row) {
                $pdo->prepare("UPDATE attendance SET punch_in = ?, punch_out = ?, edited_by = ? WHERE attendance_id = ?")->execute([$punchIn, $punchOut, $who, $row['attendance_id']]);
            } else {
                $pdo->prepare("INSERT INTO attendance (employee_id, punch_date, punch_in, punch_out, edited_by) VALUES (?, ?, ?, ?, ?)")->execute([$empId, $date, $punchIn, $punchOut, $who]);
            }
            $pdo->prepare("DELETE FROM day_marks WHERE mark_date = ? AND employee_id = ?")->execute([$date, $empId]);
            json_response(['message' => 'Marked Present.', 'status' => 'present']);
        }

        // WFH / Leave / Half leave / Holiday / Week off / Absent: the day carries no punch record.
        if ($row && $row['punch_in']) {
            if (!$removePunch) json_response(['error' => 'This day has a punch record. Confirm to remove it.', 'has_punch' => true], 409);
        }
        if ($row) {
            foreach (['punch_in_photo', 'punch_out_photo'] as $c) {
                if (!empty($row[$c]) && is_file(__DIR__ . '/' . $row[$c])) @unlink(__DIR__ . '/' . $row[$c]);
            }
            $pdo->prepare("DELETE FROM attendance WHERE attendance_id = ?")->execute([$row['attendance_id']]);
        }
        if ($status === 'absent') {
            $pdo->prepare("DELETE FROM day_marks WHERE mark_date = ? AND employee_id = ?")->execute([$date, $empId]);
        } else {
            $pdo->prepare("INSERT INTO day_marks (mark_date, employee_id, mark) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE mark = VALUES(mark)")->execute([$date, $empId, $status]);
        }
        json_response(['message' => 'Saved.', 'status' => $status]);
        break;
    }

    case 'attendance.month': {
        // One employee's whole month, day by day (the popup that opens when
        // an employee name is clicked on the admin Attendance page).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $empId = (int)($_GET['employee_id'] ?? 0);
        $month = $_GET['month'] ?? date('Y-m');
        if (!$empId) json_response(['error' => 'employee_id required.'], 422);
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $eSt = $pdo->prepare("SELECT employee_id, full_name, employee_code FROM employees WHERE employee_id = ?");
        $eSt->execute([$empId]);
        $emp = $eSt->fetch();
        if (!$emp) json_response(['error' => 'Employee not found.'], 404);
        $first = $month . '-01';
        $last = date('Y-m-t', strtotime($first));
        $st = $pdo->prepare("SELECT punch_date, punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date BETWEEN ? AND ?");
        $st->execute([$empId, date('Y-m-d', strtotime($first . ' -1 day')), $last]);
        $byDate = [];
        foreach ($st->fetchAll() as $r) $byDate[(string)$r['punch_date']] = $r;
        // A punch filed under another date than the one it belongs to (early
        // arrival counted on the previous day) is shown on its own day.
        foreach ($byDate as $k => $r) {
            if (!$r['punch_in'] || substr((string)$r['punch_in'], 0, 10) === $k) continue;
            $real = punch_in_day($pdo, strtotime((string)$r['punch_in']));
            if ($real !== $k && $real >= $first && $real <= $last && empty($byDate[$real]['punch_in'])) {
                $byDate[$real] = $r;
                unset($byDate[$k]);
            }
        }
        $shift = emp_shift_map($pdo, $first)[$empId] ?? null;
        $today = attendance_day_now($pdo);
        $days = []; $present = 0; $late = 0; $lateMin = 0; $secs = 0; $absent = 0; $mc = ['wfh' => 0, 'leave' => 0, 'half_leave' => 0];
        $monthMarks = day_marks_between($pdo, $first, $last, $empId);
        for ($d = $first; $d <= $last; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
            $r = $byDate[$d] ?? null;
            $mk = $monthMarks[$d . '|' . $empId] ?? null;
            $row = ['date' => $d, 'weekday' => (int)date('w', strtotime($d)), 'punch_in' => null, 'punch_out' => null,
                    'hours' => null, 'late_minutes' => null, 'future' => $d > $today ? 1 : 0, 'mark' => $mk];
            if ($r && $r['punch_in']) {
                $present++;
                $row['punch_in'] = $r['punch_in'];
                $row['punch_out'] = $r['punch_out'];
                $start = ($shift && $shift['own']) ? $shift['shift_start'] : day_start_for($pdo, $d);
                $after = $shift ? (int)$shift['late_after'] : 15;
                $in = strtotime((string)$r['punch_in']);
                $due = strtotime($d . ' ' . $start . ':00') + $after * 60;
                $row['late_minutes'] = $in > $due ? (int)round(($in - $due) / 60) : 0;
                if ($row['late_minutes'] > 0) { $late++; $lateMin += $row['late_minutes']; }
                if ($r['punch_out']) {
                    $sec = strtotime((string)$r['punch_out']) - $in;
                    if ($sec > 0) { $secs += $sec; $row['hours'] = round($sec / 3600, 1); }
                }
            } elseif ($mk) {
                if (isset($mc[$mk])) $mc[$mk]++;
            } elseif ($d <= $today) {
                $absent++;
            }
            $days[] = $row;
        }
        json_response([
            'employee' => $emp, 'month' => $month, 'days' => $days,
            'summary' => ['present' => $present, 'absent' => $absent, 'late' => $late, 'late_minutes' => $lateMin, 'hours' => round($secs / 3600, 1), 'wfh' => $mc['wfh'], 'leave' => $mc['leave'], 'half_leave' => $mc['half_leave']],
        ]);
        break;
    }

    case 'attendance.range': {
        // Everyone's attendance between two dates (From -> To, at most 62 days): one summary row per employee plus
        // their day-by-day lines. Same rules as attendance.month (day marks, late minutes, early-arrival punches).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $from = (string)($_GET['from'] ?? date('Y-m-d'));
        $to = (string)($_GET['to'] ?? $from);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        if ($to < $from) json_response(['error' => 'The To date is before the From date.'], 422);
        $nDays = (int)round((strtotime($to) - strtotime($from)) / 86400) + 1;
        if ($nDays > 62) json_response(['error' => 'Pick at most 62 days at a time (' . $nDays . ' picked).'], 422);
        $emps = $pdo->query("SELECT employee_id, full_name, employee_code, department_id FROM employees WHERE status != 'ex' ORDER BY full_name")->fetchAll();
        $st = $pdo->prepare("SELECT employee_id, punch_date, punch_in, punch_out FROM attendance WHERE punch_date BETWEEN ? AND ?");
        $st->execute([date('Y-m-d', strtotime($from . ' -1 day')), $to]);
        $by = [];
        foreach ($st->fetchAll() as $r) $by[(int)$r['employee_id']][(string)$r['punch_date']] = $r;
        // A punch filed under another date than the one it belongs to (early arrival) is shown on its own day.
        foreach ($by as $eid => $dates) {
            foreach ($dates as $k => $r) {
                if (!$r['punch_in'] || substr((string)$r['punch_in'], 0, 10) === $k) continue;
                $real = punch_in_day($pdo, strtotime((string)$r['punch_in']));
                if ($real !== $k && $real >= $from && $real <= $to && empty($by[$eid][$real]['punch_in'])) {
                    $by[$eid][$real] = $r;
                    unset($by[$eid][$k]);
                }
            }
        }
        $shifts = emp_shift_map($pdo, $from);
        $today = attendance_day_now($pdo);
        $marks = day_marks_between($pdo, $from, $to);
        $dayStart = [];
        for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) $dayStart[$d] = day_start_for($pdo, $d);
        $out = []; $tot = ['present' => 0, 'wfh' => 0, 'leave' => 0, 'half_leave' => 0, 'off' => 0, 'absent' => 0, 'late' => 0, 'hours' => 0.0];
        foreach ($emps as $e) {
            $eid = (int)$e['employee_id'];
            $shift = $shifts[$eid] ?? null;
            $sum = ['present' => 0, 'wfh' => 0, 'leave' => 0, 'half_leave' => 0, 'off' => 0, 'absent' => 0, 'late' => 0, 'late_minutes' => 0, 'hours' => 0.0];
            $days = []; $secs = 0;
            for ($d = $from; $d <= $to; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
                $r = $by[$eid][$d] ?? null;
                $mk = $marks[$d . '|' . $eid] ?? null;
                $row = ['date' => $d, 'weekday' => (int)date('w', strtotime($d)), 'punch_in' => null, 'punch_out' => null,
                        'hours' => null, 'late_minutes' => null, 'future' => $d > $today ? 1 : 0, 'mark' => $mk];
                if ($r && $r['punch_in']) {
                    $sum['present']++;
                    $row['punch_in'] = $r['punch_in']; $row['punch_out'] = $r['punch_out'];
                    $start = ($shift && $shift['own']) ? $shift['shift_start'] : $dayStart[$d];
                    $after = $shift ? (int)$shift['late_after'] : 15;
                    $in = strtotime((string)$r['punch_in']);
                    $due = strtotime($d . ' ' . $start . ':00') + $after * 60;
                    $row['late_minutes'] = $in > $due ? (int)round(($in - $due) / 60) : 0;
                    if ($row['late_minutes'] > 0) { $sum['late']++; $sum['late_minutes'] += $row['late_minutes']; }
                    if ($r['punch_out']) {
                        $sec = strtotime((string)$r['punch_out']) - $in;
                        if ($sec > 0) { $secs += $sec; $row['hours'] = round($sec / 3600, 1); }
                    }
                } elseif ($mk) {
                    if ($mk === 'holiday' || $mk === 'week_off') $sum['off']++;
                    elseif (isset($sum[$mk])) $sum[$mk]++;
                } elseif ($d <= $today) {
                    $sum['absent']++;
                }
                $days[] = $row;
            }
            $sum['hours'] = round($secs / 3600, 1);
            foreach (['present', 'wfh', 'leave', 'half_leave', 'off', 'absent', 'late'] as $k) $tot[$k] += $sum[$k];
            $tot['hours'] += $sum['hours'];
            $out[] = ['employee_id' => $eid, 'full_name' => $e['full_name'], 'employee_code' => $e['employee_code'], 'department_id' => $e['department_id'] !== null ? (int)$e['department_id'] : null, 'summary' => $sum, 'days' => $days];
        }
        $tot['hours'] = round($tot['hours'], 1);
        json_response(['from' => $from, 'to' => $to, 'days' => $nDays, 'employees' => $out, 'totals' => $tot]);
        break;
    }

    case 'attendance.early_check': {
        // Punches that landed on the previous day because the employee
        // arrived before the day start time (old rule). Lists them, and with
        // POST moves each one onto the day it actually happened.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $apply = $_SERVER['REQUEST_METHOD'] === 'POST';
        $since = date('Y-m-d', strtotime('-120 day'));
        $st = $pdo->prepare(
            "SELECT a.attendance_id, a.employee_id, a.punch_date, a.punch_in, a.punch_out, e.full_name, e.employee_code
             FROM attendance a JOIN employees e ON e.employee_id = a.employee_id
             WHERE a.punch_in IS NOT NULL AND a.punch_date >= ? AND DATE(a.punch_in) <> a.punch_date
             ORDER BY a.punch_in DESC"
        );
        $st->execute([$since]);
        $rows = []; $moved = 0; $skipped = 0;
        $has = $pdo->prepare("SELECT attendance_id, punch_in FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $mv = $pdo->prepare("UPDATE attendance SET punch_date = ? WHERE attendance_id = ?");
        foreach ($st->fetchAll() as $r) {
            $ts = strtotime((string)$r['punch_in']);
            $realDay = date('Y-m-d', $ts);
            // Only the "came in early" case: the punch is on the day AFTER the
            // stored date and inside the early window. Night shifts are left alone.
            if ($realDay !== date('Y-m-d', strtotime($r['punch_date'] . ' +1 day'))) continue;
            $early = minutes_before_day_start($pdo, $ts);
            if ($early <= 0 || $early > PUNCH_EARLY_WINDOW_MINUTES) continue;
            $has->execute([(int)$r['employee_id'], $realDay]);
            $clash = $has->fetch();
            $canMove = !$clash || $clash['punch_in'] === null;
            $row = ['attendance_id' => (int)$r['attendance_id'], 'employee_id' => (int)$r['employee_id'], 'full_name' => $r['full_name'],
                    'employee_code' => $r['employee_code'], 'stored_on' => $r['punch_date'], 'belongs_to' => $realDay,
                    'punch_in' => $r['punch_in'], 'punch_out' => $r['punch_out'], 'minutes_early' => $early, 'can_move' => $canMove ? 1 : 0];
            if ($apply && $canMove) {
                if ($clash) $pdo->prepare("DELETE FROM attendance WHERE attendance_id = ?")->execute([(int)$clash['attendance_id']]);
                $mv->execute([$realDay, (int)$r['attendance_id']]);
                $moved++;
                $row['moved'] = 1;
            } elseif ($apply) { $skipped++; }
            $rows[] = $row;
        }
        json_response([
            'rows' => $rows, 'count' => count($rows), 'moved' => $moved, 'skipped' => $skipped,
            'window_minutes' => PUNCH_EARLY_WINDOW_MINUTES,
            'message' => $apply
                ? ($moved ? ($moved . ' punch' . ($moved === 1 ? '' : 'es') . ' moved to the day it happened.' . ($skipped ? ' ' . $skipped . ' skipped (that day already has a punch in).' : '')) : 'Nothing to move.')
                : (count($rows) . ' punch' . (count($rows) === 1 ? ' is' : 'es are') . ' filed on the previous day.'),
        ]);
        break;
    }

    case 'attendance.set_times': {
        // Admin/HR types the punch in / out times for one employee on one
        // date. Times are HH:MM on that date; an out time earlier than the
        // in time means the next morning (shift ran past midnight). Empty
        // punch_in with empty punch_out removes the day's record.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_attendance_edited_column($pdo);
        $in = json_input();
        $empId = (int)($in['employee_id'] ?? 0);
        $date = (string)($in['date'] ?? '');
        $tIn = trim((string)($in['punch_in'] ?? ''));
        $tOut = trim((string)($in['punch_out'] ?? ''));
        if (!$empId || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'employee_id and date are required.'], 422);
        foreach ([$tIn, $tOut] as $t) {
            if ($t !== '' && !preg_match('/^\d{2}:\d{2}$/', $t)) json_response(['error' => 'Times must be HH:MM (24-hour).'], 422);
        }
        if ($tIn === '' && $tOut !== '') json_response(['error' => 'Set the punch in time first.'], 422);

        $stmt = $pdo->prepare("SELECT * FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $stmt->execute([$empId, $date]);
        $row = $stmt->fetch();
        $who = (string)($auth['username'] ?? 'admin');

        if ($tIn === '') {
            if ($row) {
                foreach (['punch_in_photo', 'punch_out_photo'] as $c) {
                    if ($row[$c] && is_file(__DIR__ . '/' . $row[$c])) @unlink(__DIR__ . '/' . $row[$c]);
                }
                $pdo->prepare("DELETE FROM attendance WHERE attendance_id = ?")->execute([$row['attendance_id']]);
            }
            json_response(['message' => 'Attendance removed for that day.']);
        }

        $punchIn = $date . ' ' . $tIn . ':00';
        $punchOut = null;
        if ($tOut !== '') {
            $punchOut = $date . ' ' . $tOut . ':00';
            if ($tOut < $tIn) $punchOut = date('Y-m-d', strtotime($date . ' +1 day')) . ' ' . $tOut . ':00';   // past midnight
        }
        if ($row) {
            $pdo->prepare("UPDATE attendance SET punch_in = ?, punch_out = ?, edited_by = ? WHERE attendance_id = ?")
                ->execute([$punchIn, $punchOut, $who, $row['attendance_id']]);
        } else {
            $pdo->prepare("INSERT INTO attendance (employee_id, punch_date, punch_in, punch_out, edited_by) VALUES (?, ?, ?, ?, ?)")
                ->execute([$empId, $date, $punchIn, $punchOut, $who]);
        }
        json_response(['message' => 'Times saved.', 'punch_in' => $punchIn, 'punch_out' => $punchOut]);
        break;
    }

    // ============== WORKING TIME PER EMPLOYEE + STORE OPENING CHECKLIST ==============
    case 'shift.list': {
        // Every employee with their own working time and store flag.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_shift_tables($pdo);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) $date = date('Y-m-d');
        $shifts = emp_shift_map($pdo, $date);
        $raw = shift_raw_map($pdo);
        $def = day_start_for($pdo, $date);
        $rows = [];
        foreach ($pdo->query("SELECT employee_id, full_name, employee_code FROM employees WHERE status != 'ex' ORDER BY full_name")->fetchAll() as $e) {
            $id = (int)$e['employee_id'];
            $s = $shifts[$id] ?? ['shift_start' => $def, 'shift_end' => '', 'late_after' => 15, 'is_store' => 0, 'own' => 0];
            $rw = $raw[$id] ?? [];
            $rows[] = [
                'employee_id' => $id, 'full_name' => $e['full_name'], 'employee_code' => $e['employee_code'],
                'shift_start' => ($s['mode'] ?? 'fixed') === 'fixed' ? $s['shift_start'] : (string)($rw['shift_start'] ?? ''), 'shift_end' => ($s['mode'] ?? 'fixed') === 'fixed' ? $s['shift_end'] : (string)($rw['shift_end'] ?? ''), 'late_after' => ($s['mode'] ?? 'fixed') === 'fixed' ? $s['late_after'] : (isset($rw['late_after']) ? (int)$rw['late_after'] : 15),
                'is_store' => $s['is_store'], 'own' => $s['own'],
                'mode' => $s['mode'] ?? 'fixed', 'hours_target' => (float)($s['hours_target'] ?? 0) ?: 8.0, 'hours_full' => (float)($s['hours_full'] ?? 0) ?: 0.0,
                'win_from' => $s['win_from'] ?? '', 'win_to' => $s['win_to'] ?? '',
                'tasks' => $s['is_store'] ? count(store_tasks_for($pdo, $id)) : 0,
            ];
        }
        json_response(['rows' => $rows, 'day_start' => $def]);
        break;
    }

    case 'shift.save': {
        // One employee's working time, late grace, store flag and task list.
        // A store employee with no list yet is given the standard six tasks.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_shift_tables($pdo)) json_response(['error' => 'Could not create the working-time tables.'], 500);
        $empId = (int)($_POST['employee_id'] ?? 0);
        if ($empId <= 0) json_response(['error' => 'Employee is required.'], 422);
        $start = trim((string)($_POST['shift_start'] ?? ''));
        $end = trim((string)($_POST['shift_end'] ?? ''));
        if ($start !== '' && !preg_match('/^\d{2}:\d{2}$/', $start)) json_response(['error' => 'Start time must be HH:MM.'], 422);
        if ($end !== '' && !preg_match('/^\d{2}:\d{2}$/', $end)) json_response(['error' => 'End time must be HH:MM.'], 422);
        $late = max(0, min(240, (int)($_POST['late_after'] ?? 15)));
        $isStore = (int)($_POST['is_store'] ?? 0) === 1 ? 1 : 0;

        // Punch rule: fixed (the times above), hours (come any time, complete the hours) or free (no time rules).
        // For hours / free the typed start, end and late-after are left as they were; only the rule is changed.
        $pmode = isset($_POST['punch_mode']) ? (string)$_POST['punch_mode'] : 'fixed';
        if (!in_array($pmode, ['fixed', 'hours', 'free'], true)) json_response(['error' => 'Unknown punch rule.'], 422);
        $st = $pdo->prepare("SELECT employee_id FROM employee_shifts WHERE employee_id = ?");
        $st->execute([$empId]);
        $exists = (bool)$st->fetch();
        if ($pmode === 'fixed') {
            if ($exists) {
                $pdo->prepare("UPDATE employee_shifts SET shift_start = ?, shift_end = ?, late_after = ?, is_store = ?, updated_at = ? WHERE employee_id = ?")
                    ->execute([$start, $end, $late, $isStore, date('Y-m-d H:i:s'), $empId]);
            } else {
                $pdo->prepare("INSERT INTO employee_shifts (employee_id, shift_start, shift_end, late_after, is_store, updated_at) VALUES (?, ?, ?, ?, ?, ?)")
                    ->execute([$empId, $start, $end, $late, $isStore, date('Y-m-d H:i:s')]);
            }
            if (isset($_POST['punch_mode'])) { $err = shift_set_mode($pdo, $empId, 'fixed'); if ($err !== '') json_response(['error' => $err], 422); }
        } else {
            if ($exists) {
                $pdo->prepare("UPDATE employee_shifts SET is_store = ?, updated_at = ? WHERE employee_id = ?")->execute([$isStore, date('Y-m-d H:i:s'), $empId]);
            } else {
                $pdo->prepare("INSERT INTO employee_shifts (employee_id, shift_start, shift_end, late_after, is_store, updated_at) VALUES (?, '', '', 15, ?, ?)")->execute([$empId, $isStore, date('Y-m-d H:i:s')]);
            }
            $err = shift_set_mode($pdo, $empId, $pmode, $_POST['hours_target'] ?? 8, $_POST['hours_full'] ?? 0, trim((string)($_POST['win_from'] ?? '')), trim((string)($_POST['win_to'] ?? '')));
            if ($err !== '') json_response(['error' => $err], 422);
        }

        // Task list: sent as JSON [{task_id?, title, photos_required, phase}, …] (phase = pre_in | post_in | pre_out | post_out).
        // Anything missing from the list is switched off (kept, so old
        // photos still have a task name next to them).
        $tasksJson = (string)($_POST['tasks'] ?? '');
        if ($tasksJson !== '') {
            $list = json_decode($tasksJson, true);
            if (!is_array($list)) json_response(['error' => 'Task list could not be read.'], 422);
            $keep = [];
            $i = 0;
            foreach ($list as $t) {
                $title = trim((string)($t['title'] ?? ''));
                if ($title === '') continue;
                $need = max(1, min(10, (int)($t['photos_required'] ?? 1)));
                $tid = (int)($t['task_id'] ?? 0);
                $phase = store_phase_clean($t['phase'] ?? 'post_in');
                $i++;
                if ($tid > 0) {
                    $pdo->prepare("UPDATE store_tasks SET title = ?, photos_required = ?, sort_order = ?, phase = ?, active = 1 WHERE task_id = ? AND employee_id = ?")
                        ->execute([$title, $need, $i, $phase, $tid, $empId]);
                    $keep[] = $tid;
                } else {
                    $pdo->prepare("INSERT INTO store_tasks (employee_id, title, photos_required, sort_order, phase, active) VALUES (?, ?, ?, ?, ?, 1)")
                        ->execute([$empId, $title, $need, $i, $phase]);
                    $keep[] = (int)$pdo->lastInsertId();
                }
            }
            if ($keep) {
                $in = implode(',', array_fill(0, count($keep), '?'));
                $pdo->prepare("UPDATE store_tasks SET active = 0 WHERE employee_id = ? AND task_id NOT IN ($in)")->execute(array_merge([$empId], $keep));
            } else {
                $pdo->prepare("UPDATE store_tasks SET active = 0 WHERE employee_id = ?")->execute([$empId]);
            }
        } elseif ($isStore && !store_tasks_for($pdo, $empId)) {
            $ins = $pdo->prepare("INSERT INTO store_tasks (employee_id, title, photos_required, sort_order, phase, active) VALUES (?, ?, ?, ?, 'post_in', 1)");
            $i = 0;
            foreach (store_default_tasks() as $t) { $i++; $ins->execute([$empId, $t['title'], $t['photos_required'], $i]); }
        }

        // "Apply this list to every store employee" copies the saved list.
        $copied = 0;
        if ((int)($_POST['apply_all'] ?? 0) === 1) {
            $src = store_tasks_for($pdo, $empId);
            $others = $pdo->prepare("SELECT employee_id FROM employee_shifts WHERE is_store = 1 AND employee_id <> ?");
            $others->execute([$empId]);
            $del = $pdo->prepare("UPDATE store_tasks SET active = 0 WHERE employee_id = ?");
            $ins = $pdo->prepare("INSERT INTO store_tasks (employee_id, title, photos_required, sort_order, phase, example_photo, active) VALUES (?, ?, ?, ?, ?, ?, 1)");
            $exPath = $pdo->prepare("SELECT example_photo FROM store_tasks WHERE task_id = ?");
            foreach ($src as &$t) { $exPath->execute([$t['task_id']]); $t['example_path'] = (string)$exPath->fetchColumn(); }
            unset($t);
            foreach ($others->fetchAll() as $o) {
                $oid = (int)$o['employee_id'];
                $del->execute([$oid]);
                $i = 0;
                foreach ($src as $t) { $i++; $ins->execute([$oid, $t['title'], $t['photos_required'], $i, $t['phase'], $t['example_path']]); }
                $copied++;
            }
        }

        json_response([
            'message' => 'Saved.' . ($copied ? ' Task list copied to ' . $copied . ' other store employee' . ($copied === 1 ? '' : 's') . '.' : ''),
            'employee_id' => $empId, 'tasks' => store_tasks_for($pdo, $empId),
        ]);
        break;
    }

    case 'store_tasks.list': {
        // Admin: one employee's settings + task list (for the settings box).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $empId = (int)($_GET['employee_id'] ?? 0);
        if ($empId <= 0) json_response(['error' => 'Employee is required.'], 422);
        $s = emp_shift($pdo, $empId);
        // The times as typed (a punch rule folds its own values into 'shift'), so the box never saves folded numbers back.
        $rw = shift_raw_map($pdo)[$empId] ?? [];
        if (($s['mode'] ?? 'fixed') !== 'fixed') {
            $s['own'] = preg_match('/^\d{2}:\d{2}$/', (string)($rw['shift_start'] ?? '')) ? 1 : 0;
            $s['shift_start'] = (string)($rw['shift_start'] ?? ''); $s['shift_end'] = (string)($rw['shift_end'] ?? '');
            $s['late_after'] = isset($rw['late_after']) ? (int)$rw['late_after'] : 15;
            if ($s['hours_target'] <= 0) $s['hours_target'] = 8;
        }
        json_response([
            'employee_id' => $empId, 'shift' => $s,
            'tasks' => store_tasks_for($pdo, $empId),
            'defaults' => store_default_tasks(),
            'day_start' => day_start_for($pdo, date('Y-m-d')),
        ]);
        break;
    }

    case 'store_tasks.day': {
        // Admin: what one store employee did on one day, with the photos.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $empId = (int)($_GET['employee_id'] ?? 0);
        $date = $_GET['date'] ?? biz_today($pdo);
        if ($empId <= 0) json_response(['error' => 'Employee is required.'], 422);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $st = $pdo->prepare("SELECT full_name, employee_code FROM employees WHERE employee_id = ?");
        $st->execute([$empId]);
        $e = $st->fetch() ?: ['full_name' => '', 'employee_code' => ''];
        $state = store_day_state($pdo, $empId, $date);
        $state['employee_id'] = $empId;
        $state['full_name'] = $e['full_name'];
        $state['employee_code'] = $e['employee_code'];
        $state['date'] = $date;
        json_response($state);
        break;
    }

    case 'store_tasks.my': {
        // The employee's own checklist for the current attendance day.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $empId = (int)$auth['employee_id'];
        $date = attendance_day_now($pdo);
        $open = attendance_open_row($pdo, $empId);
        if ($open) $date = (string)$open['punch_date'];
        $s = emp_shift($pdo, $empId, $date);
        $out = ['is_store' => $s['is_store'], 'shift' => $s, 'date' => $date, 'punched_in' => $open ? 1 : 0];
        if (!$s['is_store']) { json_response($out + ['tasks' => [], 'tasks_total' => 0]); }
        $st = $pdo->prepare("SELECT punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $row = $st->fetch();
        $out['punched_in'] = $row && $row['punch_in'] ? 1 : 0;
        $out['punch_in'] = $row['punch_in'] ?? null;
        $out['punched_out'] = $row && $row['punch_out'] ? 1 : 0;
        $out['punch_out'] = $row['punch_out'] ?? null;
        $state = store_day_state($pdo, $empId, $date);
        $out['phase_status'] = store_phase_status($state, (bool)$out['punched_in'], (bool)$out['punched_out']);
        $out['phase_names'] = STORE_PHASE_NAMES;
        json_response($out + $state);
        break;
    }

    case 'store_tasks.upload': {
        // The employee sends one photo for one task (camera photo from the page).
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_shift_tables($pdo)) json_response(['error' => 'Checklist tables are missing.'], 500);
        $empId = (int)$auth['employee_id'];
        $s = emp_shift($pdo, $empId);
        if (!$s['is_store']) json_response(['error' => 'The opening checklist is not switched on for you.'], 403);
        $taskId = (int)($_POST['task_id'] ?? 0);
        $task = null;
        foreach (store_tasks_for($pdo, $empId) as $t) if ($t['task_id'] === $taskId) $task = $t;
        if (!$task) json_response(['error' => 'That task is not on your list.'], 404);

        $open = attendance_open_row($pdo, $empId);
        $date = $open ? (string)$open['punch_date'] : attendance_day_now($pdo);
        $st = $pdo->prepare("SELECT punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $arow = $st->fetch();
        $isIn = (bool)($arow && $arow['punch_in']); $isOut = (bool)($arow && $arow['punch_out']);
        $dayState = store_day_state($pdo, $empId, $date);
        $phase = $task['phase'];
        $pst = store_phase_status($dayState, $isIn, $isOut)[$phase];
        if ($pst !== 'open') {
            $why = [
                'pre_in' => 'Punch In is already done — this task was for before Punch In.',
                'post_in' => $isOut ? 'You have already punched out.' : 'Punch in first, then upload the task photos.',
                'pre_out' => $isOut ? 'You have already punched out.' : (!$isIn ? 'Punch in first.' : 'Finish and submit the opening checklist first.'),
                'post_out' => 'Punch out first, then upload these photos.',
            ][$phase];
            json_response(['error' => $why], 409);
        }
        if ($phase === 'post_in' && $dayState['submitted_at'] !== '') json_response(['error' => "Today's checklist is already submitted."], 409);

        $have = count(store_photos_for($pdo, $empId, $date)[$taskId] ?? []);
        if ($have >= $task['photos_required']) json_response(['error' => 'That task already has all ' . $task['photos_required'] . ' photo' . ($task['photos_required'] === 1 ? '' : 's') . '.'], 409);
        if (!isset($_FILES['photo'])) json_response(['error' => 'A photo is required.'], 422);
        [$path, $err] = store_save_photo($_FILES['photo'], $empId);
        if ($err !== '') json_response(['error' => $err], 422);

        $lat = isset($_POST['lat']) && $_POST['lat'] !== '' ? (float)$_POST['lat'] : null;
        $lng = isset($_POST['lng']) && $_POST['lng'] !== '' ? (float)$_POST['lng'] : null;
        $pdo->prepare("INSERT INTO store_task_photos (employee_id, work_date, task_id, photo, taken_at, lat, lng) VALUES (?, ?, ?, ?, ?, ?, ?)")
            ->execute([$empId, $date, $taskId, $path, date('Y-m-d H:i:s'), $lat, $lng]);
        json_response(['message' => 'Photo saved.'] + store_day_state($pdo, $empId, $date));
        break;
    }

    case 'store_tasks.remove_photo': {
        // Remove a photo taken by mistake — only before the checklist is submitted.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_shift_tables($pdo);
        $empId = (int)$auth['employee_id'];
        $photoId = (int)($_POST['photo_id'] ?? 0);
        $st = $pdo->prepare("SELECT photo_id, work_date, photo, task_id FROM store_task_photos WHERE photo_id = ? AND employee_id = ?");
        $st->execute([$photoId, $empId]);
        $row = $st->fetch();
        if (!$row) json_response(['error' => 'Photo not found.'], 404);
        $date = (string)$row['work_date'];
        $ph = 'post_in';
        foreach (store_tasks_for($pdo, $empId) as $t) if ($t['task_id'] === (int)$row['task_id']) $ph = $t['phase'];
        $ra = $pdo->prepare("SELECT punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $ra->execute([$empId, $date]);
        $arow = $ra->fetch() ?: [];
        if ($ph === 'post_in' && store_submitted_at($pdo, $empId, $date) !== '') json_response(['error' => 'The checklist is submitted — ask the admin to change it.'], 409);
        if ($ph === 'pre_in' && !empty($arow['punch_in'])) json_response(['error' => 'You have already punched in — ask the admin to change it.'], 409);
        if ($ph === 'pre_out' && !empty($arow['punch_out'])) json_response(['error' => 'You have already punched out — ask the admin to change it.'], 409);
        $pdo->prepare("DELETE FROM store_task_photos WHERE photo_id = ?")->execute([$photoId]);
        $file = __DIR__ . '/' . $row['photo'];
        if ($row['photo'] !== '' && is_file($file)) @unlink($file);
        json_response(['message' => 'Photo removed.'] + store_day_state($pdo, $empId, $date));
        break;
    }

    case 'store_tasks.submit': {
        // Locks the day's checklist once every task has its photos.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_shift_tables($pdo)) json_response(['error' => 'Checklist tables are missing.'], 500);
        $empId = (int)$auth['employee_id'];
        $open = attendance_open_row($pdo, $empId);
        $date = $open ? (string)$open['punch_date'] : attendance_day_now($pdo);
        $state = store_day_state($pdo, $empId, $date);
        if ($state['submitted_at'] !== '') json_response(['message' => 'Already submitted.'] + $state);
        if (!$state['tasks_total']) json_response(['error' => 'You have no tasks to submit.'], 409);
        if (!$state['complete']) {
            $left = $state['photos_need'] - $state['photos_have'];
            json_response(['error' => $left . ' photo' . ($left === 1 ? ' is' : 's are') . ' still missing.'], 409);
        }
        $now = date('Y-m-d H:i:s');
        $st = $pdo->prepare("SELECT employee_id FROM store_task_days WHERE employee_id = ? AND work_date = ?");
        $st->execute([$empId, $date]);
        if ($st->fetch()) {
            $pdo->prepare("UPDATE store_task_days SET submitted_at = ? WHERE employee_id = ? AND work_date = ?")->execute([$now, $empId, $date]);
        } else {
            $pdo->prepare("INSERT INTO store_task_days (employee_id, work_date, submitted_at) VALUES (?, ?, ?)")->execute([$empId, $date, $now]);
        }
        $state['submitted_at'] = $now;
        json_response(['message' => 'Checklist submitted at ' . date('h:i A') . '.'] + $state);
        break;
    }

    case 'store_tasks.reopen': {
        // Admin unlocks a submitted checklist so the employee can redo a photo.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_shift_tables($pdo);
        $empId = (int)($_POST['employee_id'] ?? 0);
        $date = (string)($_POST['date'] ?? '');
        if ($empId <= 0 || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Employee and date are required.'], 422);
        $pdo->prepare("DELETE FROM store_task_days WHERE employee_id = ? AND work_date = ?")->execute([$empId, $date]);
        json_response(['message' => 'Checklist reopened for ' . date('d M', strtotime($date)) . '.']);
        break;
    }

    // ============== PHOTO CATEGORIES (admin: Punch-in proofs › + Add category) ==============
    case 'photocat.admin_list': {
        // Admin: every category with its items, who it applies to, and the totals.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Could not create the category tables.'], 500);
        $cats = photocat_all($pdo);
        $emps = $pdo->query("SELECT employee_id, department_id FROM employees WHERE status != 'ex'")->fetchAll();
        foreach ($cats as &$c) {
            $n = 0;
            foreach ($emps as $e) if (proof_rule_applies(['active' => 1] + $c, (int)$e['employee_id'], (int)$e['department_id'])) $n++;
            $c['applies_count'] = $n;
            $c['photos_total'] = array_sum(array_column($c['items'], 'photos_required'));
        }
        unset($c);
        json_response(['categories' => $cats, 'phase_names' => STORE_PHASE_NAMES]);
        break;
    }

    case 'photocat.admin_save': {
        // Admin: create or edit one category and its items in one go. Items left out are switched off (old photos stay readable).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Could not create the category tables.'], 500);
        $in = json_input();
        $id = (int)($in['cat_id'] ?? 0);
        $name = trim(preg_replace('/\s+/u', ' ', (string)($in['name'] ?? '')));
        $phase = store_phase_clean($in['phase'] ?? 'post_in');
        $all = !empty($in['scope_all']) ? 1 : 0;
        $deps = $all ? [] : proof_ints($in['department_ids'] ?? []);
        $emps = $all ? [] : proof_ints($in['employee_ids'] ?? []);
        $active = array_key_exists('active', $in) ? (!empty($in['active']) ? 1 : 0) : 1;
        if ($name === '') json_response(['error' => 'Give the category a name.'], 422);
        if (mb_strlen($name) > 120) json_response(['error' => 'The name is too long (max 120 characters).'], 422);
        if (!$all && !$deps && !$emps) json_response(['error' => 'Choose Everyone, or pick at least one department or employee.'], 422);
        $items = [];
        foreach ((is_array($in['items'] ?? null) ? $in['items'] : []) as $it) {
            $t = trim(preg_replace('/\s+/u', ' ', (string)($it['title'] ?? '')));
            if ($t === '') continue;
            if (mb_strlen($t) > 160) json_response(['error' => 'An item name is too long (max 160 characters).'], 422);
            $items[] = ['item_id' => (int)($it['item_id'] ?? 0), 'title' => $t, 'photos_required' => max(1, min(10, (int)($it['photos_required'] ?? 1)))];
        }
        if (!$items) json_response(['error' => 'Add at least one item (for example "Floor").'], 422);
        $pdo->beginTransaction();
        try {
            if ($id) {
                $chk = $pdo->prepare("SELECT cat_id FROM photo_categories WHERE cat_id = ? AND deleted = 0");
                $chk->execute([$id]);
                if (!$chk->fetchColumn()) { $pdo->rollBack(); json_response(['error' => 'That category no longer exists.'], 404); }
                $pdo->prepare("UPDATE photo_categories SET name = ?, phase = ?, scope_all = ?, department_ids = ?, employee_ids = ?, active = ? WHERE cat_id = ?")
                    ->execute([$name, $phase, $all, implode(',', $deps), implode(',', $emps), $active, $id]);
            } else {
                $next = (int)$pdo->query("SELECT COALESCE(MAX(sort_order), 0) FROM photo_categories")->fetchColumn() + 1;
                $pdo->prepare("INSERT INTO photo_categories (name, phase, scope_all, department_ids, employee_ids, active, sort_order, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
                    ->execute([$name, $phase, $all, implode(',', $deps), implode(',', $emps), $active, $next, date('Y-m-d H:i:s')]);
                $id = (int)$pdo->lastInsertId();
            }
            $ex = $pdo->prepare("SELECT item_id FROM photo_cat_items WHERE cat_id = ? AND active = 1");
            $ex->execute([$id]);
            $existing = array_map('intval', $ex->fetchAll(PDO::FETCH_COLUMN));
            $keep = [];
            $outItems = [];
            foreach ($items as $i => $it) {
                if ($it['item_id'] && in_array($it['item_id'], $existing, true)) {
                    $pdo->prepare("UPDATE photo_cat_items SET title = ?, photos_required = ?, sort_order = ? WHERE item_id = ?")->execute([$it['title'], $it['photos_required'], $i + 1, $it['item_id']]);
                    $iid = $it['item_id'];
                } else {
                    $pdo->prepare("INSERT INTO photo_cat_items (cat_id, title, photos_required, sort_order) VALUES (?, ?, ?, ?)")->execute([$id, $it['title'], $it['photos_required'], $i + 1]);
                    $iid = (int)$pdo->lastInsertId();
                }
                $keep[] = $iid;
                $outItems[] = ['item_id' => $iid, 'title' => $it['title']];
            }
            foreach (array_diff($existing, $keep) as $gone) $pdo->prepare("UPDATE photo_cat_items SET active = 0 WHERE item_id = ?")->execute([$gone]);
            $pdo->commit();
        } catch (PDOException $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            json_response(['error' => 'Could not save the category.'], 500);
        }
        json_response(['message' => 'Saved.', 'cat_id' => $id, 'items' => $outItems]);
        break;
    }

    case 'photocat.admin_toggle': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Could not create the category tables.'], 500);
        $in = json_input();
        $id = (int)($in['cat_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'cat_id is required.'], 422);
        $pdo->prepare("UPDATE photo_categories SET active = ? WHERE cat_id = ? AND deleted = 0")->execute([!empty($in['active']) ? 1 : 0, $id]);
        json_response(['message' => !empty($in['active']) ? 'Category switched on.' : 'Category switched off.']);
        break;
    }

    case 'photocat.admin_delete': {
        // Removed from the list and from Punch In/Out; photos already taken stay readable in the viewer.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Could not create the category tables.'], 500);
        $id = (int)(json_input()['cat_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'cat_id is required.'], 422);
        $pdo->prepare("UPDATE photo_categories SET deleted = 1, active = 0 WHERE cat_id = ?")->execute([$id]);
        json_response(['message' => 'Category deleted.']);
        break;
    }

    case 'photocat.admin_day': {
        // Admin viewer: one employee's categories for one day, with the photos (pending ones marked).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Could not create the category tables.'], 500);
        $empId = (int)($_GET['employee_id'] ?? 0);
        $date = (string)($_GET['date'] ?? biz_today($pdo));
        if ($empId <= 0) json_response(['error' => 'Employee is required.'], 422);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $cats = photocat_for($pdo, $empId);
        // Categories switched off / deleted later, or items removed, still show when the employee already sent photos that day.
        $have = photocat_photos_for($pdo, $empId, $date);
        $seen = [];
        foreach ($cats as $c) foreach ($c['items'] as $it) $seen[$it['item_id']] = true;
        if (array_diff_key($have, $seen)) {
            $ids = implode(',', array_map('intval', array_keys($have)));
            $extra = $pdo->query("SELECT i.item_id, i.cat_id, i.title, i.photos_required, i.example_photo, c.name, c.phase FROM photo_cat_items i JOIN photo_categories c ON c.cat_id = i.cat_id WHERE i.item_id IN ($ids)")->fetchAll();
            $byCat = [];
            foreach ($cats as $k => $c) $byCat[$c['cat_id']] = $k;
            foreach ($extra as $x) {
                if (isset($seen[(int)$x['item_id']])) continue;
                $item = ['item_id' => (int)$x['item_id'], 'title' => (string)$x['title'], 'photos_required' => max(1, (int)$x['photos_required']), 'example' => basename((string)$x['example_photo'])];
                $cid = (int)$x['cat_id'];
                if (!isset($byCat[$cid])) { $cats[] = ['cat_id' => $cid, 'name' => (string)$x['name'], 'phase' => store_phase_clean($x['phase']), 'scope_all' => 1, 'department_ids' => [], 'employee_ids' => [], 'active' => 0, 'sort_order' => 0, 'items' => []]; $byCat[$cid] = count($cats) - 1; }
                $cats[$byCat[$cid]]['items'][] = $item;
            }
        }
        $state = photocat_day_state($pdo, $empId, $date, $cats);
        $st = $pdo->prepare("SELECT full_name, employee_code FROM employees WHERE employee_id = ?");
        $st->execute([$empId]);
        $e = $st->fetch() ?: ['full_name' => '', 'employee_code' => ''];
        $state['employee_id'] = $empId; $state['full_name'] = $e['full_name']; $state['employee_code'] = $e['employee_code']; $state['date'] = $date;
        $state['phase_names'] = STORE_PHASE_NAMES;
        json_response($state);
        break;
    }

    // ============== PHOTO CATEGORIES (employee) ==============
    case 'photocat.my': {
        // The employee's own categories for the current attendance day, by timing.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $empId = (int)$auth['employee_id'];
        $date = attendance_day_now($pdo);
        $open = attendance_open_row($pdo, $empId);
        if ($open) $date = (string)$open['punch_date'];
        $st = $pdo->prepare("SELECT punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $row = $st->fetch() ?: [];
        $in = !empty($row['punch_in']); $out = !empty($row['punch_out']);
        $state = photocat_day_state($pdo, $empId, $date);
        json_response($state + ['date' => $date, 'punched_in' => $in ? 1 : 0, 'punched_out' => $out ? 1 : 0, 'phase_status' => photocat_phase_status($in, $out), 'phase_names' => STORE_PHASE_NAMES]);
        break;
    }

    case 'photocat.upload': {
        // The employee sends one photo for one item (camera photo from the page).
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Category tables are missing.'], 500);
        $empId = (int)$auth['employee_id'];
        $itemId = (int)($_POST['item_id'] ?? 0);
        $cat = null; $item = null;
        foreach (photocat_for($pdo, $empId) as $c) foreach ($c['items'] as $it) if ($it['item_id'] === $itemId) { $cat = $c; $item = $it; }
        if (!$item) json_response(['error' => 'That item is not on your list.'], 404);
        $open = attendance_open_row($pdo, $empId);
        $date = $open ? (string)$open['punch_date'] : attendance_day_now($pdo);
        $st = $pdo->prepare("SELECT punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $arow = $st->fetch() ?: [];
        $isIn = !empty($arow['punch_in']); $isOut = !empty($arow['punch_out']);
        $ph = $cat['phase'];
        if (photocat_phase_status($isIn, $isOut)[$ph] !== 'open') {
            $why = [
                'pre_in' => 'Punch In is already done — this was for before Punch In.',
                'post_in' => $isOut ? 'You have already punched out.' : 'Punch in first, then take these photos.',
                'pre_out' => $isOut ? 'You have already punched out.' : 'Punch in first, then take these photos.',
                'post_out' => 'Punch out first, then take these photos.',
            ][$ph];
            json_response(['error' => $why], 409);
        }
        $haveN = count(photocat_photos_for($pdo, $empId, $date)[$itemId] ?? []);
        if ($haveN >= $item['photos_required']) json_response(['error' => 'That item already has all ' . $item['photos_required'] . ' photo' . ($item['photos_required'] === 1 ? '' : 's') . '.'], 409);
        if (!isset($_FILES['photo'])) json_response(['error' => 'A photo is required.'], 422);
        [$path, $err] = store_save_photo($_FILES['photo'], $empId, 'store', 'cat_');
        if ($err !== '') json_response(['error' => $err], 422);
        $lat = isset($_POST['lat']) && $_POST['lat'] !== '' ? (float)$_POST['lat'] : null;
        $lng = isset($_POST['lng']) && $_POST['lng'] !== '' ? (float)$_POST['lng'] : null;
        $pdo->prepare("INSERT INTO photo_cat_photos (employee_id, work_date, item_id, photo, taken_at, lat, lng) VALUES (?, ?, ?, ?, ?, ?, ?)")
            ->execute([$empId, $date, $itemId, $path, date('Y-m-d H:i:s'), $lat, $lng]);
        json_response(['message' => 'Photo saved.', 'date' => $date, 'punched_in' => $isIn ? 1 : 0, 'punched_out' => $isOut ? 1 : 0, 'phase_status' => photocat_phase_status($isIn, $isOut), 'phase_names' => STORE_PHASE_NAMES] + photocat_day_state($pdo, $empId, $date));
        break;
    }

    case 'photocat.remove_photo': {
        // Remove a photo taken by mistake — while that timing is still open.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_photocat_tables($pdo)) json_response(['error' => 'Category tables are missing.'], 500);
        $empId = (int)$auth['employee_id'];
        $photoId = (int)($_POST['photo_id'] ?? 0);
        $st = $pdo->prepare("SELECT p.photo_id, p.work_date, p.photo, c.phase FROM photo_cat_photos p JOIN photo_cat_items i ON i.item_id = p.item_id JOIN photo_categories c ON c.cat_id = i.cat_id WHERE p.photo_id = ? AND p.employee_id = ?");
        $st->execute([$photoId, $empId]);
        $row = $st->fetch();
        if (!$row) json_response(['error' => 'Photo not found.'], 404);
        $date = (string)$row['work_date'];
        $ra = $pdo->prepare("SELECT punch_in, punch_out FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $ra->execute([$empId, $date]);
        $arow = $ra->fetch() ?: [];
        $isIn = !empty($arow['punch_in']); $isOut = !empty($arow['punch_out']);
        if (photocat_phase_status($isIn, $isOut)[store_phase_clean($row['phase'])] !== 'open') json_response(['error' => 'This timing is over — ask the admin to change it.'], 409);
        $pdo->prepare("DELETE FROM photo_cat_photos WHERE photo_id = ?")->execute([$photoId]);
        $f = __DIR__ . '/' . $row['photo'];
        if ($row['photo'] !== '' && is_file($f)) @unlink($f);
        json_response(['message' => 'Photo removed.', 'date' => $date, 'punched_in' => $isIn ? 1 : 0, 'punched_out' => $isOut ? 1 : 0, 'phase_status' => photocat_phase_status($isIn, $isOut), 'phase_names' => STORE_PHASE_NAMES] + photocat_day_state($pdo, $empId, $date));
        break;
    }

    // ============== EXAMPLE PHOTOS (optional, on store tasks and punch-in proofs) ==============
    case 'example.upload': {
        // Admin / HR: attach (or replace) the example photo of one task or one proof. POST: kind = task | proof, id, photo.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $tg = example_target((string)($_POST['kind'] ?? ''));
        $id = (int)($_POST['id'] ?? 0);
        if (!$tg || $id <= 0) json_response(['error' => 'kind and id are required.'], 422);
        if (!isset($_FILES['photo'])) json_response(['error' => 'A photo is required.'], 422);
        ensure_shift_tables($pdo); ensure_proof_tables($pdo); ensure_photocat_tables($pdo);
        [$tbl, $key] = $tg;
        $st = $pdo->prepare("SELECT example_photo FROM $tbl WHERE $key = ?");
        $st->execute([$id]);
        $old = $st->fetchColumn();
        if ($old === false) json_response(['error' => 'That ' . ($tbl === 'store_tasks' ? 'task' : ($tbl === 'photo_cat_items' ? 'item' : 'requirement')) . ' no longer exists. Save it first.'], 404);
        [$path, $err] = store_save_photo($_FILES['photo'], $id, 'examples', 'ex_' . $tg[1] . '_');
        if ($err !== '') json_response(['error' => $err], 422);
        $pdo->prepare("UPDATE $tbl SET example_photo = ? WHERE $key = ?")->execute([$path, $id]);
        example_drop_file($pdo, (string)$old);
        json_response(['message' => 'Example photo saved.', 'example' => basename($path)]);
        break;
    }

    case 'example.remove': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $tg = example_target((string)($_POST['kind'] ?? ($_GET['kind'] ?? '')));
        $id = (int)($_POST['id'] ?? ($_GET['id'] ?? 0));
        if (!$tg || $id <= 0) json_response(['error' => 'kind and id are required.'], 422);
        ensure_shift_tables($pdo); ensure_proof_tables($pdo); ensure_photocat_tables($pdo);
        [$tbl, $key] = $tg;
        $st = $pdo->prepare("SELECT example_photo FROM $tbl WHERE $key = ?");
        $st->execute([$id]);
        $old = $st->fetchColumn();
        if ($old !== false && $old !== '') {
            $pdo->prepare("UPDATE $tbl SET example_photo = '' WHERE $key = ?")->execute([$id]);
            example_drop_file($pdo, (string)$old);
        }
        json_response(['message' => 'Example photo removed.']);
        break;
    }

    case 'example.image': {
        // Streams one example photo to any signed-in user (<img> tags can't send a header, so ?token= works too).
        $auth = !empty($_GET['token']) ? verify_token((string)$_GET['token']) : require_auth();
        if (!$auth) json_response(['error' => 'Unauthorized.'], 401);
        $tg = example_target((string)($_GET['kind'] ?? ''));
        $id = (int)($_GET['id'] ?? 0);
        if (!$tg || $id <= 0) json_response(['error' => 'Not found.'], 404);
        ensure_shift_tables($pdo); ensure_proof_tables($pdo); ensure_photocat_tables($pdo);
        [$tbl, $key] = $tg;
        $st = $pdo->prepare("SELECT example_photo FROM $tbl WHERE $key = ?");
        $st->execute([$id]);
        $path = (string)$st->fetchColumn();
        $f = __DIR__ . '/' . $path;
        if ($path === '' || strpos($path, 'uploads/examples/') !== 0 || !is_file($f)) json_response(['error' => 'No example photo.'], 404);
        header('Content-Type: image/jpeg'); header('Content-Length: ' . filesize($f)); header('Cache-Control: private, max-age=86400');
        readfile($f);
        exit;
    }

    // ============== PUNCH-IN PROOFS (Instagram / YouTube comment screenshots) ==============
    case 'proofs.my': {
        // The employee's own proofs for the day a Punch In would be filed under.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        $empId = (int)$auth['employee_id'];
        if (!ensure_proof_tables($pdo)) json_response(['date' => '', 'items' => [], 'total' => 0, 'done_count' => 0, 'redo' => 0, 'missing' => [], 'complete' => 1, 'punched_in' => 0]);
        // ?stage=enroll: the proofs asked once, at the face Enroll step.
        if ((string)($_GET['stage'] ?? '') === 'enroll') json_response(proof_stage_state($pdo, $empId, 'enroll', '') + ['punched_in' => 0, 'stage' => 'enroll']);
        // Already enrolled, but a once-only proof (ID card …) is missing: that comes first ("Enroll now — 1st time only").
        if ($once = proof_once_pending($pdo, $empId)) json_response($once + ['punched_in' => 0]);
        $open = attendance_open_row($pdo, $empId);
        $date = $open ? (string)$open['punch_date'] : proof_target_day($pdo, $empId);
        $st = $pdo->prepare("SELECT punch_in FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $punched = $st->fetchColumn() ? 1 : 0;
        json_response(proof_state($pdo, $empId, $date) + ['punched_in' => $punched]);
        break;
    }

    case 'proofs.upload': {
        // One screenshot (and the link, when the requirement asks for it) for one requirement.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Proof tables are missing.'], 500);
        $empId = (int)$auth['employee_id'];
        $ruleId = (int)($_POST['rule_id'] ?? 0);
        $enrollStage = (string)($_POST['stage'] ?? '') === 'enroll';
        if ($enrollStage) {
            // Asked once, at the face Enroll step: not tied to a day. After the face is enrolled only a once-proof that is still
            // missing (new, or sent back by the admin) can be given — never changed once it is done.
            $date = PROOF_ENROLL_DAY;
            $punched = false;
            $state = proof_stage_state($pdo, $empId, 'enroll', '');
            if (proof_face_enrolled($pdo, $empId)) {
                foreach ($state['items'] as $it0) if ($it0['rule_id'] === $ruleId && $it0['done']) json_response(['error' => 'This one-time proof is already saved.'], 409);
            }
        } else {
            $open = attendance_open_row($pdo, $empId);
            $date = $open ? (string)$open['punch_date'] : proof_target_day($pdo, $empId);
            $st = $pdo->prepare("SELECT punch_in FROM attendance WHERE employee_id = ? AND punch_date = ?");
            $st->execute([$empId, $date]);
            $punched = (bool)$st->fetchColumn();
            $state = proof_state($pdo, $empId, $date);
        }
        $item = null;
        foreach ($state['items'] as $it) if ($it['rule_id'] === $ruleId) $item = $it;
        if (!$item) json_response(['error' => 'That proof is not on your list.'], 404);
        // After punching in only a proof the admin sent back can be uploaded again.
        if ($punched && !$item['redo']) json_response(['error' => 'You have already punched in — this proof can no longer be changed.'], 409);
        if (!isset($_FILES['photo'])) json_response(['error' => 'A screenshot is required.'], 422);
        $faceDist = null;

        $link = '';
        if ($item['link_required']) {
            [$link, $lerr] = proof_clean_link($item['kind'], (string)($_POST['link'] ?? ''));
            if ($lerr !== '') json_response(['error' => $lerr], 422);
        }
        $replace = (int)($_POST['replace'] ?? 0) === 1;
        if ($item['have'] >= $item['shots_required'] && !$replace) {
            json_response(['error' => 'That proof already has all ' . $item['shots_required'] . ' screenshot' . ($item['shots_required'] === 1 ? '' : 's') . '.'], 409);
        }
        // A shoes requirement: the photo goes through the footwear AI first (Crocs / slippers / unclear = rejected, retake).
        $cleanRating = null; $cleanNote = '';
        if (!empty($item['footwear']) && proof_shoe_ai_on()) {
            [$fwCode, $fwOut] = footwear_check_run($pdo, $empId);
            if (empty($fwOut['is_valid'])) {
                json_response(['error' => (string)($fwOut['message'] ?? $fwOut['error'] ?? 'Footwear check failed.'), 'footwear' => $fwOut, 'retake' => !empty($fwOut['retake'])], $fwCode === 200 ? 422 : $fwCode);
            }
            $cleanRating = isset($fwOut['cleanliness']) ? (int)$fwOut['cleanliness'] : null;
            $cleanNote = (string)($fwOut['cleanliness_note'] ?? '');
        }
        [$path, $hash, $err] = proof_save_image($_FILES['photo'], $empId);
        if ($err !== '') json_response(['error' => $err], 422);
        // The same picture can't be used twice (another day, another proof or another person).
        if ($hash !== '') {
            $dup = $pdo->prepare("SELECT proof_id FROM punch_proofs WHERE file_hash = ? LIMIT 1");
            $dup->execute([$hash]);
            if ($dup->fetchColumn()) {
                proof_unlink($path);
                json_response(['error' => "This screenshot was already used. Take a new screenshot of today's comment."], 409);
            }
        }
        // A look-alike or fake comment screenshot is sent back (Departments). /*dp-proof*/
        if (function_exists('dp_proof_screen_check')) { $dpWhy = dp_proof_screen_check($pdo, $empId, $item, __DIR__ . '/' . $path); if ($dpWhy !== '') { proof_unlink($path); json_response(['error' => $dpWhy, 'retake' => true], 409); } }
        // ID card (live camera): the AI checks it is an ID card, and every day that it is the card this person enrolled.
        // AI not reachable = saved anyway, marked "not checked" for the admin (nobody is locked out by an AI outage).
        $aiNote = '';
        if (($item['capture'] ?? 'upload') === 'idcard') {
            $newJ = (string)@file_get_contents(__DIR__ . '/' . $path);
            $refRel = !empty($item['daily']) ? proof_card_ref($pdo, $empId, $ruleId) : '';
            $refJ = ($refRel !== '' && $refRel !== 'gone') ? footwear_read_file($refRel) : '';
            $ai = $newJ !== '' ? proof_card_ai($newJ, $refJ) : ['ok' => false];
            if (empty($ai['ok'])) $aiNote = '⚠ AI not checked';
            else {
                $bad = '';
                if (!$ai['card']) $bad = 'No ID card found in the photo — hold your ID card inside the box, close and clear, and take it again.';
                elseif ($ai['same'] === false && $ai['conf'] >= 0.6) $bad = 'This is not the ID card you enrolled. Show your own ID card.';
                if ($bad !== '') { proof_unlink($path); json_response(['error' => $bad, 'retake' => true, 'ai' => $ai], 422); }
                $aiNote = ($ai['same'] === true ? '✓ Same card as enrolled' : ($refJ !== '' ? '≈ Not sure it is the same card' : '✓ ID card')) . ($ai['name'] !== '' ? ' · ' . $ai['name'] : '');
            }
        }
        $pdo->prepare("INSERT INTO punch_proofs (employee_id, work_date, rule_id, file, file_hash, link, target_url, uploaded_at, status, note, clean_rating, clean_note, face_dist, ai_note) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'ok', '', ?, ?, ?, ?)")
            ->execute([$empId, $date, $ruleId, $path, $hash, $link, (string)($item['target_url'] ?? ''), date('Y-m-d H:i:s'), $cleanRating, $cleanNote, $faceDist, mb_substr($aiNote, 0, 160)]);
        $newId = (int)$pdo->lastInsertId();
        // Replace: the oldest screenshot of this proof goes once the new one is saved.
        if ($item['have'] >= $item['shots_required']) {
            $old = $pdo->prepare("SELECT proof_id, file FROM punch_proofs WHERE employee_id = ? AND work_date = ? AND rule_id = ? AND status = 'ok' AND proof_id <> ? ORDER BY proof_id LIMIT 1");
            $old->execute([$empId, $date, $ruleId, $newId]);
            if ($o = $old->fetch()) {
                $pdo->prepare("DELETE FROM punch_proofs WHERE proof_id = ?")->execute([(int)$o['proof_id']]);
                proof_unlink((string)$o['file']);
            }
        }
        json_response(['message' => 'Saved.'] + ($enrollStage ? proof_stage_state($pdo, $empId, 'enroll', '') + ['stage' => 'enroll'] : proof_state($pdo, $empId, $date)) + ['punched_in' => $punched ? 1 : 0]);
        break;
    }

    case 'proofs.remove': {
        // Take back a wrong screenshot — only before punching in.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Proof tables are missing.'], 500);
        $empId = (int)$auth['employee_id'];
        $proofId = (int)($_POST['proof_id'] ?? 0);
        $st = $pdo->prepare("SELECT proof_id, work_date, file FROM punch_proofs WHERE proof_id = ? AND employee_id = ? AND status = 'ok'");
        $st->execute([$proofId, $empId]);
        $row = $st->fetch();
        if (!$row) json_response(['error' => 'Screenshot not found.'], 404);
        $date = (string)$row['work_date'];
        $isEnroll = $date === PROOF_ENROLL_DAY;
        if ($isEnroll) {
            if (proof_face_enrolled($pdo, $empId)) {
                $st0 = proof_stage_state($pdo, $empId, 'enroll', ''); $okRm = false;
                $rid0 = (int)$pdo->query("SELECT rule_id FROM punch_proofs WHERE proof_id = " . (int)$proofId)->fetchColumn();
                foreach ($st0['items'] as $it0) if ($it0['rule_id'] === $rid0 && !$it0['done']) $okRm = true;
                if (!$okRm) json_response(['error' => 'Your face is already enrolled — this proof can no longer be changed.'], 409);
            }
        } else {
            $pi = $pdo->prepare("SELECT punch_in FROM attendance WHERE employee_id = ? AND punch_date = ?");
            $pi->execute([$empId, $date]);
            if ($pi->fetchColumn()) json_response(['error' => 'You have already punched in — this proof can no longer be changed.'], 409);
        }
        $pdo->prepare("DELETE FROM punch_proofs WHERE proof_id = ?")->execute([$proofId]);
        proof_unlink((string)$row['file']);
        json_response(['message' => 'Screenshot removed.'] + ($isEnroll ? proof_stage_state($pdo, $empId, 'enroll', '') + ['stage' => 'enroll'] : proof_state($pdo, $empId, $date)) + ['punched_in' => 0]);
        break;
    }

    case 'proofs.rules': {
        // Admin: every requirement, plus the departments / employees the scope picker needs.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Could not create the proof tables.'], 500);
        $rules = proof_rules_all($pdo);
        $depts = $pdo->query("SELECT department_id, department_name FROM departments ORDER BY department_name")->fetchAll();
        $emps = $pdo->query("SELECT e.employee_id, e.full_name, e.employee_code, e.department_id, d.department_name
                             FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id
                             WHERE e.status != 'ex' ORDER BY e.full_name")->fetchAll();
        $deptCount = [];
        foreach ($emps as &$e) { $e['employee_id'] = (int)$e['employee_id']; $e['department_id'] = (int)$e['department_id']; $deptCount[$e['department_id']] = ($deptCount[$e['department_id']] ?? 0) + 1; }
        unset($e);
        foreach ($depts as &$d) { $d['department_id'] = (int)$d['department_id']; $d['employees'] = $deptCount[$d['department_id']] ?? 0; }
        unset($d);
        foreach ($rules as &$r) {
            $n = 0;
            foreach ($emps as $e) if (proof_rule_applies(['active' => 1] + $r, $e['employee_id'], $e['department_id'])) $n++;
            $r['applies_count'] = $n;
        }
        unset($r);
        json_response(['rules' => $rules, 'departments' => $depts, 'employees' => $emps, 'total_employees' => count($emps)]);
        break;
    }

    case 'proofs.rule_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Could not create the proof tables.'], 500);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        $kind = (string)($in['kind'] ?? 'custom');
        if (!in_array($kind, ['instagram', 'youtube', 'custom'], true)) $kind = 'custom';
        $title = trim((string)($in['title'] ?? ''));
        $instr = trim((string)($in['instruction'] ?? ''));
        $hintTop = trim(preg_replace('/\s+/u', ' ', (string)($in['hint_top'] ?? '')));
        $hintBot = trim(preg_replace('/\s+/u', ' ', (string)($in['hint_bottom'] ?? '')));
        $shots = max(1, min(10, (int)($in['shots_required'] ?? 1)));
        $link = !empty($in['link_required']) ? 1 : 0;
        [$target, $terr] = proof_target_parse($kind, (string)($in['target_url'] ?? ''));
        if ($terr !== '') json_response(['error' => $terr], 422);
        $all = !empty($in['scope_all']) ? 1 : 0;
        $deps = $all ? [] : proof_ints($in['department_ids'] ?? []);
        $emps = $all ? [] : proof_ints($in['employee_ids'] ?? []);
        $active = array_key_exists('active', $in) ? (!empty($in['active']) ? 1 : 0) : 1;
        $stage = ((string)($in['stage'] ?? 'punch')) === 'enroll' ? 'enroll' : 'punch';
        // New fields — an older cached admin page that does not send them keeps what is saved.
        $old = [];
        if ($id) { $o0 = $pdo->prepare("SELECT capture, ask_enrolled, except_ids, daily_check FROM punch_proof_rules WHERE rule_id = ?"); $o0->execute([$id]); $old = $o0->fetch() ?: []; }
        $capture = array_key_exists('capture', $in) ? (in_array((string)$in['capture'], ['idcard', 'faceid'], true) ? 'idcard' : 'upload') : (in_array((string)($old['capture'] ?? ''), ['idcard', 'faceid'], true) ? 'idcard' : 'upload');
        $daily = array_key_exists('daily_check', $in) ? (!empty($in['daily_check']) ? 1 : 0) : (int)($old['daily_check'] ?? 0);
        if ($stage !== 'enroll' || $capture !== 'idcard') $daily = 0;
        $askEnr = array_key_exists('ask_enrolled', $in) ? (!empty($in['ask_enrolled']) ? 1 : 0) : (int)($old['ask_enrolled'] ?? 1);
        $except = array_key_exists('except_ids', $in) ? proof_ints($in['except_ids']) : proof_ints($old['except_ids'] ?? '');
        if ($title === '') json_response(['error' => 'Give the requirement a name.'], 422);
        if (mb_strlen($title) > 120) json_response(['error' => 'The name is too long (max 120 characters).'], 422);
        if (mb_strlen($instr) > 500) json_response(['error' => 'The wording is too long (max 500 characters).'], 422);
        if (mb_strlen($hintTop) > 80) json_response(['error' => 'The top handwritten line is too long (max 80 characters).'], 422);
        if (mb_strlen($hintBot) > 80) json_response(['error' => 'The bottom handwritten line is too long (max 80 characters).'], 422);
        if (!$all && !$deps && !$emps) json_response(['error' => 'Choose Everyone, or pick at least one department or employee.'], 422);
        if ($id) {
            $chk = $pdo->prepare("SELECT rule_id FROM punch_proof_rules WHERE rule_id = ? AND deleted = 0");
            $chk->execute([$id]);
            if (!$chk->fetchColumn()) json_response(['error' => 'That requirement no longer exists.'], 404);
            $pdo->prepare("UPDATE punch_proof_rules SET kind = ?, title = ?, instruction = ?, hint_top = ?, hint_bottom = ?, shots_required = ?, link_required = ?, target_url = ?, scope_all = ?, department_ids = ?, employee_ids = ?, active = ?, stage = ?, capture = ?, ask_enrolled = ?, except_ids = ?, daily_check = ? WHERE rule_id = ?")
                ->execute([$kind, $title, $instr, $hintTop, $hintBot, $shots, $link, $target, $all, implode(',', $deps), implode(',', $emps), $active, $stage, $capture, $askEnr, implode(',', $except), $daily, $id]);
        } else {
            $next = (int)$pdo->query("SELECT COALESCE(MAX(sort_order), 0) FROM punch_proof_rules")->fetchColumn() + 1;
            $pdo->prepare("INSERT INTO punch_proof_rules (kind, title, instruction, hint_top, hint_bottom, shots_required, link_required, target_url, scope_all, department_ids, employee_ids, active, stage, capture, ask_enrolled, except_ids, daily_check, sort_order, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                ->execute([$kind, $title, $instr, $hintTop, $hintBot, $shots, $link, $target, $all, implode(',', $deps), implode(',', $emps), $active, $stage, $capture, $askEnr, implode(',', $except), $daily, $next, date('Y-m-d H:i:s')]);
            $id = (int)$pdo->lastInsertId();
        }
        json_response(['message' => 'Saved.', 'rule_id' => $id, 'target_url' => $target, 'hint_top' => $hintTop, 'hint_bottom' => $hintBot, 'stage' => $stage]);
        break;
    }

    case 'proofs.rule_delete': {
        // Removed from the list and from Punch In; the screenshots already sent stay readable in the viewer.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Could not create the proof tables.'], 500);
        $id = (int)(json_input()['rule_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'rule_id is required.'], 422);
        $pdo->prepare("UPDATE punch_proof_rules SET deleted = 1, active = 0 WHERE rule_id = ?")->execute([$id]);
        json_response(['message' => 'Requirement deleted.']);
        break;
    }

    case 'proofs.day': {
        // Admin viewer: one employee's proofs for one day, screenshots included (sent-back ones too).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Could not create the proof tables.'], 500);
        $empId = (int)($_GET['employee_id'] ?? 0);
        $date = (string)($_GET['date'] ?? biz_today($pdo));
        if ($empId <= 0) json_response(['error' => 'Employee is required.'], 422);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $st = $pdo->prepare("SELECT full_name, employee_code FROM employees WHERE employee_id = ?");
        $st->execute([$empId]);
        $e = $st->fetch() ?: ['full_name' => '', 'employee_code' => ''];
        // Requirements that apply today, plus any (even switched off or deleted) that already have screenshots that day.
        $rules = proof_rules_for($pdo, $empId);
        $have = [];
        foreach ($rules as $r) $have[$r['rule_id']] = true;
        $rowsDay = proof_rows($pdo, $empId, $date);
        if (array_diff_key($rowsDay, $have)) {
            foreach (proof_rules_all($pdo, false, true) as $r) if (isset($rowsDay[$r['rule_id']]) && empty($have[$r['rule_id']])) $rules[] = $r;
        }
        $state = proof_state($pdo, $empId, $date, $rules, true);
        $pi = $pdo->prepare("SELECT punch_in FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $pi->execute([$empId, $date]);
        $state['punch_in'] = (string)($pi->fetchColumn() ?: '');
        // The proofs asked once at the face Enroll step (kept apart from the day).
        $state['enroll'] = proof_state($pdo, $empId, PROOF_ENROLL_DAY, proof_rules_for($pdo, $empId, 'enroll'), true);
        $state['enroll_day'] = PROOF_ENROLL_DAY;
        $fe = $pdo->prepare("SELECT face_descriptor IS NOT NULL FROM employees WHERE employee_id = ?");
        $fe->execute([$empId]);
        $state['face_enrolled'] = (int)$fe->fetchColumn();
        $state['employee_id'] = $empId;
        $state['full_name'] = $e['full_name'];
        $state['employee_code'] = $e['employee_code'];
        json_response($state);
        break;
    }

    case 'proofs.redo': {
        // Admin sends one proof back: the employee sees it in red with the reason and uploads it again.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_proof_tables($pdo)) json_response(['error' => 'Could not create the proof tables.'], 500);
        $in = json_input();
        $empId = (int)($in['employee_id'] ?? 0);
        $ruleId = (int)($in['rule_id'] ?? 0);
        $date = (string)($in['date'] ?? '');
        $note = trim((string)($in['note'] ?? ''));
        if ($empId <= 0 || $ruleId <= 0 || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Employee, proof and date are required.'], 422);
        if (mb_strlen($note) > 250) $note = mb_substr($note, 0, 250);
        $up = $pdo->prepare("UPDATE punch_proofs SET status = 'rejected', note = ? WHERE employee_id = ? AND work_date = ? AND rule_id = ? AND status = 'ok'");
        $up->execute([$note, $empId, $date, $ruleId]);
        if (!$up->rowCount()) json_response(['error' => 'There is no screenshot to send back.'], 404);
        json_response(['message' => 'Sent back — the employee will see it on their Attendance page.']);
        break;
    }

    // ============== ORDER TARGETS ==============
    case 'order_targets.day': {
        // One business day: every tracked employee with the day's target, the orders typed for each hour, and the pace.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $today = biz_today($pdo);
        $date = (string)($_GET['date'] ?? $today);
        if (!ot_date_ok($date)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        [$s, $e] = ot_window($pdo);
        $ids = ot_tracked_ids($pdo);
        if ($date < $today) {
            // Someone taken off the list keeps their numbers on the days that are over.
            foreach (['order_targets', 'order_target_hours'] as $t) {
                $q = $pdo->prepare("SELECT DISTINCT employee_id FROM $t WHERE target_date = ?");
                $q->execute([$date]);
                foreach ($q->fetchAll(PDO::FETCH_COLUMN) as $x) $ids[] = (int)$x;
            }
            $ids = array_values(array_unique($ids));
        }
        $targets = [];
        $q = $pdo->prepare("SELECT employee_id, target FROM order_targets WHERE target_date = ?");
        $q->execute([$date]);
        foreach ($q->fetchAll() as $r) $targets[(int)$r['employee_id']] = (int)$r['target'];
        $hours = []; $last = []; $qh = []; $ch = [];
        $q = $pdo->prepare("SELECT employee_id, hour_no, orders, query_orders, campaign_orders, updated_at FROM order_target_hours WHERE target_date = ?");
        $q->execute([$date]);
        $extra = [];      // hours outside the tracked window that have numbers: shown as extra columns so nothing is hidden
        foreach ($q->fetchAll() as $r) {
            $id = (int)$r['employee_id'];
            if ((int)$r['hour_no'] < $s || (int)$r['hour_no'] >= $e) $extra[(int)$r['hour_no']] = true;
            $hours[$id][(int)$r['hour_no']] = (int)$r['orders'];
            if ((int)$r['query_orders'] > 0) $qh[$id][(int)$r['hour_no']] = (int)$r['query_orders'];
            if ((int)$r['campaign_orders'] > 0) $ch[$id][(int)$r['hour_no']] = (int)$r['campaign_orders'];
            $at = (string)$r['updated_at'];
            if ($at !== '' && (!isset($last[$id]) || $at > $last[$id])) $last[$id] = $at;
        }
        $rows = [];
        foreach (ot_people($pdo, $ids) as $p) {
            $id = (int)$p['employee_id'];
            $h = $hours[$id] ?? [];
            ksort($h);
            $rows[] = [
                'employee_id' => $id,
                'full_name' => (string)$p['full_name'],
                'employee_code' => (string)$p['employee_code'],
                'department_name' => (string)($p['department_name'] ?? ''),
                'target' => $targets[$id] ?? 0,
                'hours' => (object)$h,
                'qhours' => (object)($qh[$id] ?? []),
                'chours' => (object)($ch[$id] ?? []),
                'query' => array_sum($qh[$id] ?? []),
                'campaign' => array_sum($ch[$id] ?? []),
                'achieved' => array_sum($h),
                'last_update' => isset($last[$id]) ? substr($last[$id], 11, 5) : '',
            ];
        }
        // Orders can be entered for ANY hour of the business day (not only the tracked window) once that hour has begun.
        $allHours = ot_all_hours($s);
        $open = [];
        foreach ($allHours as $h) if (ot_hour_open($date, $h, $s)) $open[] = $h;
        $cols = range($s, $e - 1);
        foreach ($allHours as $h) if (isset($extra[$h]) && !in_array($h, $cols, true)) $cols[] = $h;
        $pace = ot_pace($pdo, $date);
        $nowHour = null;
        if ($pace > 0 && $pace < 100) foreach ($open as $h) if ($h >= $s && $h < $e) $nowHour = $h;
        json_response([
            'date' => $date,
            'today' => $today,
            'now' => date('H:i'),
            'start' => $s,
            'end' => $e,
            'hours' => $cols,
            'all_hours' => $allHours,
            'open_hours' => $open,
            'now_hour' => $nowHour,
            'pace' => $pace,
            'rows' => $rows,
        ]);
        break;
    }

    case 'order_targets.mine': {
        // The signed-in employee's OWN order target for today (read-only): target, orders per hour, Query / Campaign, pace.
        // Shown on My Sales to every employee; one who is not on Order Targets gets a "no target set" card.
        $auth = require_auth();
        $emp = (int)($auth['employee_id'] ?? 0);
        if (!$emp) json_response(['tracked' => false, 'employee' => false]);
        if (!ensure_order_target_tables($pdo)) json_response(['tracked' => false, 'employee' => true]);
        $today = biz_today($pdo);
        [$s, $e] = ot_window($pdo);
        $tr = array_flip(ot_tracked_ids($pdo));
        // Not on Order Targets yet: the card still shows ("no target set") so the employee knows where it will appear.
        if (!ot_may_edit($pdo, $tr, $emp, $today)) json_response(['tracked' => false, 'employee' => true]);
        $q = $pdo->prepare("SELECT target FROM order_targets WHERE target_date = ? AND employee_id = ?");
        $q->execute([$today, $emp]);
        $target = (int)($q->fetchColumn() ?: 0);
        $q = $pdo->prepare("SELECT hour_no, orders, query_orders, campaign_orders, updated_at FROM order_target_hours WHERE target_date = ? AND employee_id = ?");
        $q->execute([$today, $emp]);
        $by = []; $last = '';
        foreach ($q->fetchAll() as $r) {
            $by[(int)$r['hour_no']] = ['orders' => (int)$r['orders'], 'q' => (int)$r['query_orders'], 'c' => (int)$r['campaign_orders']];
            if ((string)$r['updated_at'] > $last) $last = (string)$r['updated_at'];
        }
        // The tracked window, plus any other hour of the day that has numbers (orders can be entered for any hour).
        $list = range($s, $e - 1);
        foreach (ot_all_hours($s) as $h) if (isset($by[$h]) && !in_array($h, $list, true)) $list[] = $h;
        $hours = []; $ach = 0; $qq = 0; $cc = 0; $nowHour = null;
        foreach ($list as $h) {
            $x = $by[$h] ?? ['orders' => 0, 'q' => 0, 'c' => 0];
            $open = ot_hour_open($today, $h, $s);
            $ach += $x['orders']; $qq += $x['q']; $cc += $x['c'];
            if ($open && $h >= $s && $h < $e) $nowHour = $h;
            $hours[] = ['hour' => $h, 'label' => ot_hour_label($h), 'orders' => $x['orders'], 'query' => $x['q'], 'campaign' => $x['c'], 'open' => $open ? 1 : 0];
        }
        $pace = ot_pace($pdo, $today);
        $expected = $target > 0 ? (int)round($target * $pace / 100) : 0;
        $endTs = strtotime(sprintf('%s %02d:00:00', $today, $e));
        $hoursLeft = $pace >= 100 ? 0 : max(0, (int)ceil(($endTs - time()) / 3600));
        $remaining = max(0, $target - $ach);
        json_response([
            'tracked' => true, 'date' => $today, 'target' => $target, 'achieved' => $ach, 'query' => $qq, 'campaign' => $cc,
            'pace' => $pace, 'expected' => $expected, 'behind' => $target > 0 ? $expected - $ach : 0,
            'remaining' => $remaining, 'hours_left' => $hoursLeft,
            'per_hour' => ($hoursLeft > 0 && $remaining > 0) ? (int)ceil($remaining / $hoursLeft) : 0,
            'last_update' => $last !== '' ? substr($last, 11, 5) : '', 'now_hour' => $nowHour, 'hours' => $hours,
        ]);
        break;
    }

    case 'order_targets.staff': {
        // Who is tracked, everyone who could be added, the departments (for the filter) and the tracked hours.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $fix = function (array $r): array {
            return [
                'employee_id' => (int)$r['employee_id'],
                'full_name' => (string)$r['full_name'],
                'employee_code' => (string)$r['employee_code'],
                'department_id' => $r['department_id'] === null ? null : (int)$r['department_id'],
                'department_name' => (string)($r['department_name'] ?? ''),
            ];
        };
        $tracked = array_map($fix, ot_people($pdo, ot_tracked_ids($pdo)));
        $all = $pdo->query(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.department_id, d.department_name
               FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id
              WHERE e.status != 'ex' ORDER BY e.full_name"
        )->fetchAll();
        $deps = [];
        foreach ($pdo->query("SELECT department_id, department_name FROM departments ORDER BY department_name")->fetchAll() as $d) {
            $deps[] = ['department_id' => (int)$d['department_id'], 'department_name' => (string)$d['department_name']];
        }
        [$s, $e] = ot_window($pdo);
        json_response(['tracked' => $tracked, 'employees' => array_map($fix, $all), 'departments' => $deps, 'start' => $s, 'end' => $e]);
        break;
    }

    case 'order_targets.add_staff': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $ids = ot_ints(json_input()['employee_ids'] ?? []);
        if (!$ids) json_response(['error' => 'Pick at least one employee.'], 422);
        $in = implode(',', $ids);
        $valid = array_map('intval', $pdo->query("SELECT employee_id FROM employees WHERE employee_id IN ($in) AND status != 'ex'")->fetchAll(PDO::FETCH_COLUMN));
        $have = array_map('intval', $pdo->query("SELECT employee_id FROM order_target_staff WHERE employee_id IN ($in)")->fetchAll(PDO::FETCH_COLUMN));
        $added = 0;
        $ins = $pdo->prepare("INSERT INTO order_target_staff (employee_id, added_at) VALUES (?, ?)");
        foreach (array_diff($valid, $have) as $id) {
            $ins->execute([$id, date('Y-m-d H:i:s')]);
            $added++;
        }
        json_response(['message' => $added === 1 ? 'Employee added.' : $added . ' employees added.', 'added' => $added]);
        break;
    }

    case 'order_targets.remove_staff': {
        // Takes them off the daily table. Numbers already saved for past days stay.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $id = (int)(json_input()['employee_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'Employee is required.'], 422);
        $pdo->prepare("DELETE FROM order_target_staff WHERE employee_id = ?")->execute([$id]);
        json_response(['message' => 'Removed from Order Targets.']);
        break;
    }

    case 'order_targets.plan': {
        // The week (Monday to Sunday) around a date: each tracked employee's target for each day.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $today = biz_today($pdo);
        $any = (string)($_GET['week_start'] ?? $today);
        if (!ot_date_ok($any)) json_response(['error' => 'Date must be YYYY-MM-DD.'], 422);
        $ts = strtotime($any);
        $monday = date('Y-m-d', strtotime('-' . ((int)date('N', $ts) - 1) . ' days', $ts));
        $days = [];
        for ($i = 0; $i < 7; $i++) $days[] = date('Y-m-d', strtotime($monday . ' +' . $i . ' days'));
        $ids = ot_tracked_ids($pdo);
        $by = [];
        if ($ids) {
            $q = $pdo->prepare("SELECT employee_id, target_date, target FROM order_targets WHERE target_date >= ? AND target_date <= ?");
            $q->execute([$days[0], $days[6]]);
            foreach ($q->fetchAll() as $r) $by[(int)$r['employee_id']][(string)$r['target_date']] = (int)$r['target'];
        }
        $rows = [];
        foreach (ot_people($pdo, $ids) as $p) {
            $id = (int)$p['employee_id'];
            $rows[] = [
                'employee_id' => $id,
                'full_name' => (string)$p['full_name'],
                'employee_code' => (string)$p['employee_code'],
                'targets' => (object)($by[$id] ?? []),
            ];
        }
        json_response(['week_start' => $days[0], 'days' => $days, 'today' => $today, 'rows' => $rows]);
        break;
    }

    case 'order_targets.plan_save': {
        // cells: [{employee_id, date, target}] — a blank or 0 target clears that day (an off day).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $cells = json_input()['cells'] ?? [];
        if (!is_array($cells) || !$cells) json_response(['error' => 'Nothing to save.'], 422);
        if (count($cells) > 500) json_response(['error' => 'Too many boxes at once (max 500).'], 422);
        $trackedFlip = array_flip(ot_tracked_ids($pdo));
        $who = mb_substr((string)($auth['username'] ?? ''), 0, 60);
        $clean = [];
        foreach ($cells as $c) {
            $emp = (int)($c['employee_id'] ?? 0);
            $date = (string)($c['date'] ?? '');
            $n = ot_num($c['target'] ?? null);
            if ($emp <= 0 || !ot_date_ok($date)) json_response(['error' => 'Employee and date are required for every box.'], 422);
            if ($n === false) json_response(['error' => 'A target must be a whole number from 0 to 9999.'], 422);
            if (!ot_may_edit($pdo, $trackedFlip, $emp, $date)) json_response(['error' => 'Add the employee to the tracked list first.'], 422);
            $clean[] = [$emp, $date, (int)$n];
        }
        $pdo->beginTransaction();
        try {
            foreach ($clean as [$emp, $date, $n]) ot_set_target($pdo, $emp, $date, $n, $who);
            $pdo->commit();
        } catch (Throwable $ex) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            json_response(['error' => 'Could not save the targets.'], 500);
        }
        json_response(['message' => 'Saved.', 'saved' => count($clean)]);
        break;
    }

    case 'order_targets.hours_save': {
        // cells: [{employee_id, date, hour, orders}] — the orders done IN that hour; blank removes it.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $cells = json_input()['cells'] ?? [];
        if (!is_array($cells) || !$cells) json_response(['error' => 'Nothing to save.'], 422);
        if (count($cells) > 300) json_response(['error' => 'Too many boxes at once (max 300).'], 422);
        [$s, $e] = ot_window($pdo);
        $trackedFlip = array_flip(ot_tracked_ids($pdo));
        $who = mb_substr((string)($auth['username'] ?? ''), 0, 60);
        $clean = [];
        foreach ($cells as $c) {
            $emp = (int)($c['employee_id'] ?? 0);
            $date = (string)($c['date'] ?? '');
            $hour = (int)($c['hour'] ?? -1);
            $n = ot_num($c['orders'] ?? null);
            $hasQC = array_key_exists('query', $c) || array_key_exists('campaign', $c);
            $qn = $hasQC ? ot_num($c['query'] ?? 0) : null;
            $cn = $hasQC ? ot_num($c['campaign'] ?? 0) : null;
            if ($hasQC && ($qn === false || $cn === false)) json_response(['error' => 'Query and Campaign orders must be whole numbers from 0 to 9999.'], 422);
            if ($hasQC) { $qn = (int)$qn; $cn = (int)$cn; }
            if ($emp <= 0 || !ot_date_ok($date)) json_response(['error' => 'Employee and date are required for every box.'], 422);
            if ($hour < 0 || $hour > 23) json_response(['error' => 'Pick an hour of the day.'], 422);
            if ($n === false) json_response(['error' => 'Orders must be a whole number from 0 to 9999.'], 422);
            if (!ot_hour_open($date, $hour, $s)) json_response(['error' => ot_hour_label($hour) . ' has not started yet — you can enter it once the hour begins.'], 422);
            if (!ot_may_edit($pdo, $trackedFlip, $emp, $date)) json_response(['error' => 'Add the employee to the tracked list first.'], 422);
            if ($n !== null) {
                if ($hasQC) {
                    if ($qn + $cn > $n) json_response(['error' => 'Query (' . $qn . ') + Campaign (' . $cn . ') cannot be more than the orders of that hour (' . $n . ').'], 422);
                } else {
                    // Only the total was typed (hour grid): it may not go below the Query + Campaign already saved for that hour.
                    $ex = $pdo->prepare("SELECT query_orders + campaign_orders FROM order_target_hours WHERE target_date = ? AND employee_id = ? AND hour_no = ?");
                    $ex->execute([$date, $emp, $hour]);
                    $have = (int)$ex->fetchColumn();
                    if ($have > $n) json_response(['error' => ot_hour_label($hour) . ' already has ' . $have . ' Query + Campaign orders — use "+ Add orders" to change them together with the total.'], 422);
                }
            }
            $clean[] = [$emp, $date, $hour, $n, $qn, $cn];
        }
        $pdo->beginTransaction();
        try {
            foreach ($clean as [$emp, $date, $hour, $n, $qn, $cn]) ot_set_hour($pdo, $emp, $date, $hour, $n, $who, $qn, $cn);
            $pdo->commit();
        } catch (Throwable $ex) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            json_response(['error' => 'Could not save the orders.'], 500);
        }
        json_response(['message' => 'Saved.', 'saved' => count($clean)]);
        break;
    }

    case 'order_targets.settings_save': {
        // The hours that are tracked, e.g. start 10 / end 20 = 10 AM up to 8 PM.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_target_tables($pdo)) json_response(['error' => 'Could not create the Order Targets tables.'], 500);
        $in = json_input();
        $s = (int)($in['start'] ?? -1);
        $e = (int)($in['end'] ?? -1);
        if ($s < 0 || $s > 23) json_response(['error' => 'The first hour must be between 12 AM and 11 PM.'], 422);
        if ($e <= $s || $e > 24) json_response(['error' => 'The last hour must come after the first hour.'], 422);
        setting_set($pdo, 'order_targets_start', $s);
        setting_set($pdo, 'order_targets_end', $e);
        json_response(['message' => 'Saved.', 'start' => $s, 'end' => $e]);
        break;
    }

    // ============== TARGETS ==============
    case 'targets.get': {
        // One row per employee, with ONE target: their orders from every
        // house count together. `houses` lists the houses they belong to;
        // the house filter (store_group) only narrows WHICH employees are
        // listed — their numbers always stay combined. group_key is ''
        // (combined), which is also the key their daily targets use.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $month = $_GET['month'] ?? date('Y-m');
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $groupFilter = normalize_group_key($_GET['store_group'] ?? '');
        if (!isset(target_houses()[$groupFilter])) $groupFilter = '';
        ensure_group_key_column($pdo, 'targets', ['month', 'employee_id']);

        $monthStart = $month . '-01';
        $monthEnd = date('Y-m-t', strtotime($monthStart));

        // Saved targets for the month, keyed by employee+house.
        // employee_id 0 / group_key '' = legacy team target row.
        $tStmt = $pdo->prepare("SELECT * FROM targets WHERE month = ?");
        $tStmt->execute([$month]);
        $saved = [];
        $teamTarget = 0;
        foreach ($tStmt->fetchAll() as $t) {
            if ((int)$t['employee_id'] === 0) { $teamTarget = (float)$t['manual_target']; continue; }
            $saved[(int)$t['employee_id']][$t['group_key']] = $t;
        }

        // Attendance for the month (not house-specific).
        $aStmt = $pdo->prepare(
            "SELECT employee_id, punch_date, punch_in FROM attendance
             WHERE punch_date BETWEEN ? AND ?"
        );
        $aStmt->execute([$monthStart, $monthEnd]);
        $presentByEmp = [];
        $activeDays = [];
        foreach ($aStmt->fetchAll() as $a) {
            if ($a['punch_in']) {
                $presentByEmp[(int)$a['employee_id']][] = $a['punch_date'];
                $activeDays[$a['punch_date']] = true;
            }
        }
        $activeDayCount = count($activeDays);
        $today = date('Y-m-d');
        $daysInMonth = (int)date('t', strtotime($monthStart));

        [$sgSql, $sgParams] = store_group_filter_sql($pdo, $groupFilter);
        $stmt = $pdo->prepare(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.basic_salary, d.department_name
             FROM employees e
             JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex' AND d.department_name LIKE '%sales%'$sgSql
             ORDER BY e.full_name"
        );
        $stmt->execute($sgParams);
        $emps = $stmt->fetchAll();

        // Each employee's assigned houses (empty = never tagged yet).
        $memberships = [];
        if ($emps && ensure_store_groups_table($pdo)) {
            $ids = array_column($emps, 'employee_id');
            $in = implode(',', array_fill(0, count($ids), '?'));
            $gStmt = $pdo->prepare("SELECT employee_id, group_key FROM employee_store_groups WHERE employee_id IN ($in)");
            $gStmt->execute($ids);
            foreach ($gStmt->fetchAll() as $g) $memberships[(int)$g['employee_id']][] = $g['group_key'];
        }
        $groupLabels = target_houses();   // TM Perfume House, TM4U

        $rows = [];
        $achievedTotal = 0;
        foreach ($emps as $e) {
            $eid = (int)$e['employee_id'];
            $presentDates = $presentByEmp[$eid] ?? [];
            $present = count($presentDates);
            $absent = max(0, $activeDayCount - $present);
            $ratio = ($present + $absent) > 0 ? $present / ($present + $absent) : 1;
            $dailyTarget = (float)$e['basic_salary'];
            $monthlyBase = $dailyTarget > 0 ? $dailyTarget * $daysInMonth : ($teamTarget > 0 ? $teamTarget / max(1, count($emps)) : 0);
            $suggested = $monthlyBase > 0 ? round($monthlyBase * $ratio) : null;
            $todayStatus = in_array($today, $presentDates, true) ? 'present' : ($today >= $monthStart && $today <= $monthEnd ? 'absent' : null);

            // Only employees assigned to at least one house are listed —
            // assign a house on their profile to see them on Targets.
            $all = array_values(array_filter($memberships[$eid] ?? [], fn($g) => isset($groupLabels[$g])));
            if (!$all) continue;
            // TM Perfume House  share ONE combined row/target;
            // TM4U (orders tagged tm4u) is a separate row with its own target.
            $perfume = array_values(array_filter($all, fn($g) => $g !== 'tm4u'));
            $inTm4u = in_array('tm4u', $all, true);

            $rowSpecs = [];   // [group_key, houses, label]
            if ($perfume && ($groupFilter === '' || $groupFilter !== 'tm4u')) $rowSpecs[] = ['', $perfume, implode(', ', array_map(fn($g) => $groupLabels[$g], $perfume))];
            if ($inTm4u && ($groupFilter === '' || $groupFilter === 'tm4u')) $rowSpecs[] = ['tm4u', ['tm4u'], $groupLabels['tm4u']];

            foreach ($rowSpecs as [$gk, $houses, $label]) {
                // Monthly figures: the TM4U row reads its own saved rows; the
                // combined row adds up every other saved row for this person
                // (older per-house rows and the combined '' row alike).
                $manual = null; $achieved = 0.0; $ordersCount = 0;
                foreach ($saved[$eid] ?? [] as $row) {
                    $isTm4uRow = ($row['group_key'] ?? '') === 'tm4u';
                    if ($isTm4uRow !== ($gk === 'tm4u')) continue;
                    if ($row['manual_target'] !== null) $manual = ($manual ?? 0) + (float)$row['manual_target'];
                    $achieved += (float)$row['achieved'];
                    $ordersCount += (int)($row['orders_count'] ?? 0);
                }
                $achievedTotal += $achieved;

                $rows[] = [
                    'employee_id' => $eid,
                    'full_name' => $e['full_name'],
                    'employee_code' => $e['employee_code'],
                    'group_key' => $gk,
                    'houses' => $houses,
                    'group_label' => $label,
                    'present' => $present,
                    'absent' => $absent,
                    'today' => $todayStatus,
                    'suggested' => $suggested,
                    'manual_target' => $manual,
                    'achieved' => $achieved,
                    'orders_count' => $ordersCount,
                    'daily_target' => $dailyTarget,
                ];
            }
        }

        json_response([
            'month' => $month,
            'team_target' => $teamTarget,
            'achieved_total' => $achievedTotal,
            'active_days' => $activeDayCount,
            'days_in_month' => $daysInMonth,
            'rows' => $rows,
        ]);
        break;
    }

    case 'targets.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $month = $input['month'] ?? '';
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $empId = (int)($input['employee_id'] ?? -1); // 0 = team target
        if ($empId < 0) json_response(['error' => 'employee_id is required (0 for team).'], 422);
        $groupKey = normalize_group_key($input['group_key'] ?? ($input['store_group'] ?? ''));
        ensure_group_key_column($pdo, 'targets', ['month', 'employee_id']);

        $manual = array_key_exists('manual_target', $input)
            ? ($input['manual_target'] === null || $input['manual_target'] === '' ? null : (float)$input['manual_target'])
            : false; // false = not provided
        $achieved = array_key_exists('achieved', $input) ? (float)$input['achieved'] : false;

        $stmt = $pdo->prepare("SELECT target_id FROM targets WHERE month = ? AND employee_id = ? AND group_key = ?");
        $stmt->execute([$month, $empId, $groupKey]);
        $existing = $stmt->fetchColumn();

        if ($existing) {
            if ($manual !== false) {
                $pdo->prepare("UPDATE targets SET manual_target = ? WHERE target_id = ?")->execute([$manual, $existing]);
            }
            if ($achieved !== false) {
                $pdo->prepare("UPDATE targets SET achieved = ? WHERE target_id = ?")->execute([$achieved, $existing]);
            }
        } else {
            $pdo->prepare("INSERT INTO targets (month, employee_id, group_key, manual_target, achieved) VALUES (?, ?, ?, ?, ?)")
                ->execute([$month, $empId, $groupKey, $manual === false ? null : $manual, $achieved === false ? 0 : $achieved]);
        }
        json_response(['message' => 'Saved.']);
        break;
    }

    case 'employees.set_daily_target': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $empId = (int)($input['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'employee_id required.'], 422);
        $amount = (float)($input['amount'] ?? 0);
        $pdo->prepare("UPDATE employees SET basic_salary = ? WHERE employee_id = ?")->execute([$amount, $empId]);
        json_response(['message' => 'Daily target saved.']);
        break;
    }

    case 'targets.daily': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $date = $_GET['date'] ?? date('Y-m-d');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        ensure_group_key_column($pdo, 'daily_targets', ['target_date', 'employee_id']);
        $stmt = $pdo->prepare("SELECT employee_id, group_key, amount FROM daily_targets WHERE target_date = ?");
        $stmt->execute([$date]);
        $out = [];
        foreach ($stmt->fetchAll() as $r) $out[$r['employee_id'] . '|' . $r['group_key']] = (float)$r['amount'];
        // New Sales Executives (first four weeks): the automatic ladder for this day, on the row that carries the person's target
        // ('' = TM Perfume House only, 'tm4u'). A target set by hand can only go above it.
        $ladder = [];
        $le = [];
        foreach ($pdo->query("SELECT e.employee_id, e.joining_date, e.designation, d.department_name FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex'")->fetchAll() as $e) {
            $lad = sales_ladder_for($e, $date);
            if ($lad !== null) $le[(int)$e['employee_id']] = $lad;
        }
        foreach (first_panels($pdo, array_keys($le)) as $id => $fp) {
            $row = $fp === 'tm4u' ? 'tm4u' : (($fp === 'tmph') ? '' : null);
            if ($row !== null) $ladder[$id] = ['amount' => $le[$id]['amount'], 'week' => $le[$id]['week'], 'row' => $row];
        }
        // Employees with no target today: a full-day Leave mark, or Absent (same rule as the Orders page Employee sheet).
        $away = [];
        $marks = day_marks_between($pdo, $date, $date);
        $present = attendance_present_map($pdo, $date, $date);
        $bizNow = biz_today($pdo);
        foreach ($pdo->query("SELECT employee_id FROM employees WHERE status != 'ex'")->fetchAll() as $e) {
            $id = (int)$e['employee_id']; $mk = $marks[$date . '|' . $id] ?? '';
            if ($mk === 'leave') $away[$id] = 'leave';
            elseif ($mk === '' && $date <= $bizNow && empty($present[$id][$date])) $away[$id] = 'absent';
        }
        json_response(['overrides' => $out, 'ladder' => (object)$ladder, 'away' => (object)$away]);
        break;
    }

    case 'day_timing.get': {
        require_auth();
        json_response(['start' => day_timing_get($pdo)]);
        break;
    }

    case 'day_timing.save': {
        $auth = require_auth();
        // Day timing has a button on Attendance, Targets and Orders, so any
        // page's access is enough (Sales Head etc. with just one of them).
        if (!user_can($auth, 'attendance') && !user_can($auth, 'targets') && !orders_page_controls($auth)) require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $start = (array)($in['start'] ?? []);
        if (count($start) !== 7) json_response(['error' => 'Send a start time for all seven days.'], 422);
        ensure_day_timing_table($pdo);
        $ins = $pdo->prepare("INSERT INTO day_timing (weekday, start_time) VALUES (?, ?) ON DUPLICATE KEY UPDATE start_time = VALUES(start_time)");
        for ($wd = 0; $wd <= 6; $wd++) {
            $t = (string)($start[$wd] ?? '');
            if (!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $t)) json_response(['error' => 'Times must be HH:MM (24-hour).'], 422);
            $ins->execute([$wd, $t]);
        }
        json_response(['message' => 'Day timing saved. It applies to orders counted from now on; run Sync now on Targets to recount the month.']);
        break;
    }

    case 'target_rule.get': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        json_response(['rule' => target_rule_get($pdo), 'houses' => target_houses()]);
        break;
    }

    case 'target_rule.save': {
        // Replaces the whole rule set in one go (settings + every rule).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_target_rule_table($pdo)) json_response(['error' => 'Rule storage is not available.'], 500);
        $in = json_input();
        $enabled = empty($in['enabled']) ? 0 : 1;

        $valid = array_keys(target_houses());
        $groups = [];
        foreach ((array)($in['groups'] ?? []) as $g) {
            if (in_array((string)$g, $valid, true)) $groups[] = (string)$g;
        }
        $groups = array_values(array_unique($groups));
        if ($enabled && !$groups) json_response(['error' => 'Tick at least one house, or turn automatic targets off.'], 422);

        $dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
        $rulesIn = (array)($in['rules'] ?? []);
        if ($enabled && !$rulesIn) json_response(['error' => 'Add at least one rule, or turn automatic targets off.'], 422);
        if (count($rulesIn) > 10) json_response(['error' => 'Up to 10 rules.'], 422);

        $clean = []; $taken = [];
        foreach (array_values($rulesIn) as $i => $r) {
            $n = $i + 1;
            $name = mb_substr(trim((string)($r['name'] ?? '')), 0, 60) ?: "Rule $n";
            $days = array_values(array_unique(array_filter(array_map('intval', (array)($r['weekdays'] ?? [])), fn($d) => $d >= 0 && $d <= 6)));
            sort($days);
            if (!$days) json_response(['error' => "\"$name\": pick at least one day."], 422);
            foreach ($days as $d) {
                if (isset($taken[$d])) json_response(['error' => "{$dayNames[$d]} is in both \"{$taken[$d]}\" and \"$name\" — each day can only be in one rule."], 422);
                $taken[$d] = $name;
            }
            $basis = ($r['basis'] ?? '') === 'weekday' ? 'weekday' : 'days';
            $lookback = (int)($r['lookback'] ?? 3);
            $maxLb = $basis === 'weekday' ? 8 : 14;
            if ($lookback < 1 || $lookback > $maxLb) json_response(['error' => "\"$name\": average over 1 to $maxLb " . ($basis === 'weekday' ? 'weeks' : 'days') . '.'], 422);
            $pct = round((float)($r['pct'] ?? 0), 1);
            if ($pct < -90 || $pct > 500) json_response(['error' => "\"$name\": the % to add must be between -90 and 500."], 422);
            $min = round((float)($r['min_target'] ?? 0), 2);
            if ($min < 0) json_response(['error' => "\"$name\": minimum target cannot be negative."], 422);
            $clean[] = [$i, $name, implode(',', $days), $basis, $lookback, $pct, $min, empty($r['skip_zero']) ? 0 : 1];
        }

        $pdo->beginTransaction();
        try {
            $pdo->prepare(
                "INSERT INTO target_rule (rule_id, enabled, groups_csv, updated_by) VALUES (1, ?, ?, ?)
                 ON DUPLICATE KEY UPDATE enabled = VALUES(enabled), groups_csv = VALUES(groups_csv), updated_by = VALUES(updated_by)"
            )->execute([$enabled, implode(',', $groups), $auth['username'] ?? null]);
            $pdo->exec("DELETE FROM target_rules");
            $ins = $pdo->prepare(
                "INSERT INTO target_rules (sort_order, name, weekdays, basis, lookback, pct, min_target, skip_zero)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
            );
            foreach ($clean as $c) $ins->execute($c);
            $pdo->commit();
        } catch (PDOException $e) {
            $pdo->rollBack();
            json_response(['error' => 'Could not save the rules: ' . $e->getMessage()], 500);
        }
        json_response(['message' => 'Target rules saved.', 'rule' => target_rule_get($pdo)]);
        break;
    }

    case 'targets.save_daily': {
        $auth = require_auth();
        if (!orders_page_controls($auth)) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $date = trim($input['date'] ?? '');
        $empId = (int)($input['employee_id'] ?? 0);
        $groupKey = normalize_group_key($input['group_key'] ?? ($input['store_group'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date) || !$empId) json_response(['error' => 'date and employee_id required.'], 422);
        ensure_group_key_column($pdo, 'daily_targets', ['target_date', 'employee_id']);

        $amount = $input['amount'] ?? null;
        if ($amount === null || $amount === '') {
            $pdo->prepare("DELETE FROM daily_targets WHERE target_date = ? AND employee_id = ? AND group_key = ?")->execute([$date, $empId, $groupKey]);
            json_response(['message' => 'Daily target cleared — using automatic value.']);
        }
        // A target set by hand is saved as typed — for a new Sales Executive too (it replaces the ladder for that day, higher or lower).
        $pdo->prepare(
            "INSERT INTO daily_targets (target_date, employee_id, group_key, amount) VALUES (?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE amount = VALUES(amount)"
        )->execute([$date, $empId, $groupKey, (float)$amount]);
        json_response(['message' => 'Daily target saved.']);
        break;
    }

    case 'targets.diagnose': {
        // Troubleshooting for the Achieved total looking too high/low: shows
        // the raw match between Shopify orders and employee Sales Tags for
        // one month, and flags the single most common cause — an employee
        // whose Sales Tag collides with the Scout/Champion markers
        // ("query"/"campaign", or the older "s"/"c"),
        // which silently attributes every Scout- or Champion-tagged order
        // storewide to that one person.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $month = $_GET['month'] ?? date('Y-m');
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $monthStart = $month . '-01';
        $monthEnd = date('Y-m-t', strtotime($monthStart));

        $tagMap = sales_tag_map($pdo);
        $collisions = [];
        foreach ($tagMap as $tag => $emp) {
            // These tags mark an order's type (Scout / Champion). An employee
            // whose Sales Tag is one of them would be credited with every
            // Scout or Champion order in the store.
            if (in_array($tag, ['query', 'campaign', 's', 'c'], true)) $collisions[] = $emp['name'] . ' (Sales Tag = "' . $tag . '")';
        }

        $stores = shopify_stores();
        $tokens = [];
        $errors = [];
        foreach ($stores as $key => $store) {
            if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
            $token = shopify_get_token($key, $store);
            if (is_array($token)) { $errors[] = $token['error']; unset($stores[$key]); continue; }
            $tokens[$key] = $token;
        }
        if (!$stores) json_response(['error' => 'No Shopify store reachable. ' . implode(' ', $errors)], 502);

        $results = shopify_fetch_all($stores, $tokens, $monthStart, $monthEnd, 40, true);

        $storeTotal = 0.0; $storeCount = 0;
        $matchedTotal = 0.0; $matchedCount = 0;
        $perEmployee = [];
        $sMarkerTotal = 0.0; $sMarkerCount = 0;
        $cMarkerTotal = 0.0; $cMarkerCount = 0;
        $sampleUnmatched = [];

        foreach ($results as $st) {
            if ($st['error']) { $errors[] = $st['error']; continue; }
            foreach ($st['orders'] as $o) {
                $total = (float)$o['total'];
                $storeTotal += $total; $storeCount++;
                $tags = array_map('trim', explode(',', (string)($o['tags'] ?? '')));
                $tagsLower = array_map('mb_strtolower', $tags);
                if (in_array('s', $tagsLower, true)) { $sMarkerTotal += $total; $sMarkerCount++; }
                if (in_array('c', $tagsLower, true)) { $cMarkerTotal += $total; $cMarkerCount++; }

                $sm = match_salesman($tagMap, (string)($o['tags'] ?? ''));
                if ($sm) {
                    $matchedTotal += $total; $matchedCount++;
                    if (!isset($perEmployee[$sm['id']])) $perEmployee[$sm['id']] = ['name' => $sm['name'], 'total' => 0.0, 'count' => 0];
                    $perEmployee[$sm['id']]['total'] += $total;
                    $perEmployee[$sm['id']]['count']++;
                } else {
                    if (count($sampleUnmatched) < 10) $sampleUnmatched[] = ['order' => $o['order_name'], 'tags' => $o['tags'] ?? '', 'total' => $total];
                }
            }
        }

        usort($perEmployee, fn($a, $b) => $b['total'] <=> $a['total']);

        json_response([
            'month' => $month,
            'sales_tag_collisions_with_s_or_c' => $collisions,
            'store_wide' => ['orders' => $storeCount, 'total' => round($storeTotal, 2)],
            'matched_to_an_employee' => ['orders' => $matchedCount, 'total' => round($matchedTotal, 2)],
            'unmatched' => ['orders' => $storeCount - $matchedCount, 'total' => round($storeTotal - $matchedTotal, 2), 'sample' => $sampleUnmatched],
            'orders_tagged_s' => ['orders' => $sMarkerCount, 'total' => round($sMarkerTotal, 2)],
            'orders_tagged_c' => ['orders' => $cMarkerCount, 'total' => round($cMarkerTotal, 2)],
            'per_employee' => array_values($perEmployee),
            'errors' => $errors,
        ]);
        break;
    }

    case 'targets.sync_orders': {
        // Pull the whole month's Shopify orders from each real store and
        // write PER-HOUSE totals into targets (tmperfumehouse's store ->
        // house "tmph"). TM4U has no
        // live Shopify store yet, so its numbers stay whatever was entered
        // manually via targets.save — this sync never touches that house.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $month = $input['month'] ?? '';
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $force = !empty($input['force']);

        // Server-side throttle, shared across every browser/admin that has
        // Targets open — only an explicit "Sync now" click (force=true)
        // skips this and talks to Shopify immediately.
        $secondsAgo = targets_sync_seconds_ago($month);
        if (!$force && $secondsAgo !== null && $secondsAgo < TARGETS_SYNC_INTERVAL_SECONDS) {
            json_response([
                'skipped' => true,
                'synced_ago_seconds' => $secondsAgo,
                'message' => 'Up to date — synced ' . round($secondsAgo / 60) . ' min ago.',
            ]);
        }

        $monthStart = $month . '-01';
        $monthEnd = date('Y-m-t', strtotime($monthStart));

        $stores = shopify_stores();
        $tokens = [];
        $errors = [];
        foreach ($stores as $key => $store) {
            if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
            $token = shopify_get_token($key, $store);
            if (is_array($token)) { $errors[] = $token['error']; unset($stores[$key]); continue; }
            $tokens[$key] = $token;
        }
        if (!$stores) json_response(['error' => 'No Shopify store reachable. ' . implode(' ', $errors)], 502);

        $tagMap = sales_tag_map($pdo);
        $allocMap = order_allocations($pdo);
        if (!$tagMap && !$allocMap) json_response(['error' => 'No employee has an Order Tag set yet — add tags on the Employees page first.'], 422);

        $results = shopify_fetch_all($stores, $tokens, $monthStart, $monthEnd, 40, true);

        // Which house each real Shopify store belongs to.
        $storeToGroup = ['tmperfumehouse' => 'tmph'];

        $sums = [];        // "$empId|$groupKey" => amount
        $counts = [];
        $prepaidSums = [];
        $matched = 0; $unmatched = 0;
        $touchedGroups = []; // groups that actually had a live store this run

        foreach ($results as $storeKey => $st) {
            if ($st['error']) { $errors[] = $st['error']; continue; }
            // A house tag can route an order to any house, so every house is
            // "touched" once any store has been fetched.
            foreach (array_keys(house_labels()) as $hg) $touchedGroups[$hg] = true;
            foreach ($st['orders'] as $o) {
                $gk = order_house($storeKey, (string)($o['tags'] ?? ''));   // house tag wins
                $sm = match_salesman($tagMap, (string)($o['tags'] ?? ''));
                alloc_override($allocMap, $storeKey, $o['id'], $gk, $sm);   // Order Allocation page wins over both
                if ($sm) {
                    $key = $sm['id'] . '|' . $gk;
                    $total = (float)$o['total'];
                    $sums[$key] = ($sums[$key] ?? 0) + $total;
                    $counts[$key] = ($counts[$key] ?? 0) + 1;
                    // COD/cash-on-delivery orders are not prepaid; everything
                    // else (paid, partially_paid via online gateway) counts as
                    // prepaid for the commission's prepaid-share rule.
                    $fs = strtolower((string)($o['financial_status'] ?? ''));
                    if (strpos($fs, 'cod') === false && strpos($fs, 'pending') === false) {
                        $prepaidSums[$key] = ($prepaidSums[$key] ?? 0) + $total;
                    }
                    $matched++;
                } else {
                    $unmatched++;
                }
            }
        }

        // MySales orders moved to a house on the Order Allocation page.
        foreach (allocated_house_orders($pdo, $monthStart, $monthEnd, $errors) as $o) {
            if (!$o['emp_id']) { $unmatched++; continue; }
            $touchedGroups[$o['house']] = true;
            $key = $o['emp_id'] . '|' . $o['house'];
            $total = (float)$o['total'];
            $sums[$key] = ($sums[$key] ?? 0) + $total;
            $counts[$key] = ($counts[$key] ?? 0) + 1;
            $fs = strtolower((string)$o['financial_status']);
            if (strpos($fs, 'cod') === false && strpos($fs, 'pending') === false) $prepaidSums[$key] = ($prepaidSums[$key] ?? 0) + $total;
            $matched++;
        }

        ensure_targets_commission_columns($pdo);
        ensure_group_key_column($pdo, 'targets', ['month', 'employee_id']);
        $sel = $pdo->prepare("SELECT target_id FROM targets WHERE month = ? AND employee_id = ? AND group_key = ?");
        $upd = $pdo->prepare("UPDATE targets SET achieved = ?, orders_count = ?, prepaid_amount = ? WHERE target_id = ?");
        $insT = $pdo->prepare("INSERT INTO targets (month, employee_id, group_key, achieved, orders_count, prepaid_amount) VALUES (?, ?, ?, ?, ?, ?)");
        $per = [];
        // Employees to write: everyone with an Order Tag, plus anyone who
        // received orders on the Order Allocation page without a tag.
        $writeEmps = [];
        foreach ($tagMap as $tag => $emp) $writeEmps[$emp['id']] = ['id' => $emp['id'], 'name' => $emp['name'], 'tag' => $tag];
        foreach (array_keys($sums) as $k) {
            $eid = (int)strtok($k, '|');
            if ($eid && !isset($writeEmps[$eid])) $writeEmps[$eid] = ['id' => $eid, 'name' => employee_names_by_id($pdo)[$eid] ?? '', 'tag' => ''];
        }
        foreach ($writeEmps as $emp) {
            $tag = $emp['tag'];
            foreach (array_keys($touchedGroups) as $gk) {
                $key = $emp['id'] . '|' . $gk;
                $amount = round($sums[$key] ?? 0, 2);
                $cnt = (int)($counts[$key] ?? 0);
                $prepaid = round($prepaidSums[$key] ?? 0, 2);
                $sel->execute([$month, $emp['id'], $gk]);
                $tid = $sel->fetchColumn();
                if ($tid) $upd->execute([$amount, $cnt, $prepaid, $tid]);
                else $insT->execute([$month, $emp['id'], $gk, $amount, $cnt, $prepaid]);
                $per[] = ['name' => $emp['name'], 'tag' => $tag, 'group_key' => $gk, 'achieved' => $amount, 'orders' => $cnt, 'prepaid' => $prepaid];
            }
        }

        targets_sync_mark($month);
        json_response([
            'skipped' => false,
            'synced_ago_seconds' => 0,
            'message' => "Synced: $matched orders matched to employees, $unmatched without a matching tag.",
            'per_employee' => $per,
            'errors' => $errors,
        ]);
        break;
    }

    // ============== MANUAL ORDERS (counter / WhatsApp orders) ==============
    case 'manual_orders.save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();

        $customer = trim($input['customer_name'] ?? '');
        $orderDate = trim($input['order_date'] ?? '');
        if ($customer === '') json_response(['error' => 'Customer name is required.'], 422);
        if ($orderDate === '') $orderDate = date('Y-m-d H:i:s');

        $stmt = $pdo->prepare(
            "INSERT INTO manual_orders (order_no, customer_name, phone, items, total, payment_status, fulfillment_status, order_date, remarks, created_by)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        );
        $stmt->execute([
            trim($input['order_no'] ?? '') ?: null,
            $customer,
            trim($input['phone'] ?? ''),
            (int)($input['items'] ?? 1),
            (float)($input['total'] ?? 0),
            trim($input['payment_status'] ?? 'paid'),
            trim($input['fulfillment_status'] ?? 'unfulfilled'),
            $orderDate,
            trim($input['remarks'] ?? ''),
            $auth['username'],
        ]);
        $newId = (int)$pdo->lastInsertId();

        // Auto order number M0001-style when none given.
        if (!trim($input['order_no'] ?? '')) {
            $pdo->prepare("UPDATE manual_orders SET order_no = ? WHERE manual_order_id = ?")
                ->execute(['M' . str_pad((string)$newId, 4, '0', STR_PAD_LEFT), $newId]);
        }

        json_response(['message' => 'Order added.', 'manual_order_id' => $newId], 201);
        break;
    }

    case 'manual_orders.delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $input = json_input();
        $id = $input['manual_order_id'] ?? null;
        if (!$id) json_response(['error' => 'manual_order_id is required.'], 422);
        $pdo->prepare("DELETE FROM manual_orders WHERE manual_order_id = ?")->execute([$id]);
        json_response(['message' => 'Order deleted.']);
        break;
    }

    // ============== SHOPIFY ORDERS ==============
    case 'shopify.stores': {
        require_auth();
        $out = [];
        foreach (shopify_stores() as $key => $s) {
            $out[] = ['key' => $key, 'label' => $s['label']];
        }
        foreach (custom_stores() as $key => $s) {
            $out[] = ['key' => $key, 'label' => $s['label']];
        }
        json_response(['stores' => $out]);
        break;
    }

    case 'orders.dti_fill': {
        // Orders page "Dress to Impress" box: orders synced before the box existed have no Dress to Impress count yet. Re-reads them from
        // Shopify, a few days per call (the page calls again until nothing is left). Same access as the Orders page.
        $auth = require_auth();
        $from = (string)($_GET['from'] ?? ''); $to = (string)($_GET['to'] ?? '');
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to) || $to < $from) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        if (!ensure_shop_orders_table($pdo)) json_response(['error' => 'Order cache not available.'], 500);
        @set_time_limit(120);
        $q = $pdo->prepare("SELECT COUNT(*) FROM shop_orders WHERE dti IS NULL AND created_at >= ? AND created_at <= ?");
        $errors = []; $done = 0; $t0 = microtime(true);
        for ($d = $from; $d <= $to && microtime(true) - $t0 < 40; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
            $q->execute(biz_window($pdo, $d, $d));
            if ((int)$q->fetchColumn() === 0) continue;
            orders_sync_range($pdo, $d, $d, 40, $errors);
            $done++;
            if ($errors) break;
        }
        $q->execute(biz_window($pdo, $from, $to));
        json_response(['days_done' => $done, 'left' => (int)$q->fetchColumn(), 'errors' => $errors]);
        break;
    }

    case 'shopify.orders': {
        $auth = require_auth();
        // Employee logins only ever see their own tagged orders.
        $empScopeId = null;
        $scopeInfo = null;   // Employee view only: why the list may be empty (what Shopify returned vs. what is theirs)
        if (($auth['role'] ?? '') === 'Employee') {
            $st = $pdo->prepare("SELECT sales_tag FROM employees WHERE employee_id = ?");
            $st->execute([$auth['employee_id'] ?? 0]);
            $empTag = mb_strtolower(trim((string)$st->fetchColumn()));
            if ($empTag === '') json_response(['error' => 'No order tag set on your profile yet — ask Admin to add one.'], 422);
            $empScopeId = (int)$auth['employee_id'];
            $scopeInfo = ['tag' => $empTag, 'fetched' => 0, 'mine' => 0, 'elsewhere' => 0];
        }
        $dateFrom = $_GET['date_from'] ?? date('Y-m-d');
        $dateTo   = $_GET['date_to'] ?? $dateFrom;
        $storeKey = trim((string)($_GET['store'] ?? ''));
        // Several stores / houses at once: "tmperfumehouse". Everything is fetched, then only the picked ones are kept
        // (each pick follows the same rule as picking it alone).
        $multi = [];
        if (strpos($storeKey, ',') !== false) {
            $multi = array_values(array_unique(array_filter(array_map('trim', explode(',', $storeKey)))));
            $storeKey = count($multi) === 1 ? $multi[0] : '';
            if (count($multi) === 1) $multi = [];
        }
        // Every house filter (TM Perfume House, TM4U) fetches
        // BOTH stores and keeps the orders whose house matches — a house tag
        // can move an order from one store's house to the other's.
        $houseFilter = '';
        if (isset(house_labels()[$storeKey])) { $houseFilter = $storeKey; $storeKey = ''; }
        elseif (isset(['tmperfumehouse' => 1][$storeKey])) { $houseFilter = order_house($storeKey, ''); $storeKey = ''; }

        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
            json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        }

        $stores = shopify_stores();
        $customs = custom_stores();
        if ($storeKey !== '' && $storeKey !== 'manual' && !isset($stores[$storeKey]) && !isset($customs[$storeKey])) {
            json_response(['error' => 'Unknown store.'], 422);
        }
        $targets = [];
        if ($storeKey === '') {
            $targets = $stores;
        } elseif ($storeKey !== 'manual' && isset($stores[$storeKey])) {
            $targets = [$storeKey => $stores[$storeKey]];
        }

        $allOrders = [];
        $errors = [];

        // Commission page (lite=1): read the Shopify orders from the local order cache (MySQL) instead of paging through Shopify
        // on every open. Yesterday + today are re-synced every 3 minutes, older days are settled every 30 minutes, and
        // fresh=1 (the page's Refresh button) re-syncs the last 10 days of the range right now.
        $lite = !empty($_GET['lite']);      // employees too (My Sales): their own orders are picked out of the cache below
        $liteResults = null; $settleAfter = false;
        if ($lite && $targets && ensure_shop_orders_table($pdo)) {
            $bizToday = biz_today($pdo);
            if (!empty($_GET['fresh']) && $empScopeId === null) {
                @unlink(sys_get_temp_dir() . '/hrms_orders_last_sync.txt');
                $fs = max($dateFrom, date('Y-m-d', strtotime($bizToday . ' -10 day')));
                if ($fs <= $dateTo) orders_sync_range($pdo, $fs, $dateTo, 40, $errors);
                @file_put_contents(sys_get_temp_dir() . '/hrms_orders_settle.txt', (string)time());
            } elseif (orders_settle_due()) {
                if (function_exists('fastcgi_finish_request') || function_exists('litespeed_finish_request')) $settleAfter = true;
                else orders_settle_old_days($pdo);
            }
            $cachedRows = code_orders_cached($pdo, $dateFrom, $dateTo, $errors);
            if ($cachedRows !== null) {
                $liteResults = [];
                foreach ($targets as $key => $store) $liteResults[$key] = ['store' => $store, 'orders' => [], 'error' => null];
                foreach ($cachedRows as $cr) { if (isset($liteResults[$cr['store_key']])) $liteResults[$cr['store_key']]['orders'][] = $cr; }
            }
        }

        // LIVE fetch straight from Shopify, all stores in parallel.
        $tokens = [];
        if ($liteResults === null) foreach ($targets as $key => $store) {
            if (strpos($store['client_id'], 'PASTE_') !== false || strpos($store['domain'], 'YOUR-STORE') !== false) {
                $errors[] = $store['label'] . ': not configured yet (add domain + Client ID/Secret in api.php).';
                unset($targets[$key]);
                continue;
            }
            $token = shopify_get_token($key, $store);
            if (is_array($token)) { // error shape
                $errors[] = $token['error'];
                unset($targets[$key]);
                continue;
            }
            $tokens[$key] = $token;
        }

        $allocMap = order_allocations($pdo);
        if ($targets) {
            $tagMap = sales_tag_map($pdo);
            $results = $liteResults ?? shopify_fetch_all($targets, $tokens, $dateFrom, $dateTo, 40);
            foreach ($results as $key => $st) {
                if ($st['error']) {
                    $errors[] = $st['error'];
                    continue;
                }
                foreach ($st['orders'] as $o) {
                    $o['store_key'] = $key;
                    $o['store'] = $st['store']['label'];
                    // House the order counts under (a house tag beats the store).
                    $o['house'] = order_house($key, (string)($o['tags'] ?? ''));
                    $o['house_tags'] = order_house_tags((string)($o['tags'] ?? ''));
                    $o['store'] = house_labels()[$o['house']] ?? $o['store'];
                    // Business day per the Day timing setting (Shopify gives UTC).
                    $o['biz_date'] = biz_day_of($pdo, strtotime((string)$o['created_at']));
                    $sm = match_salesman($tagMap, (string)($o['tags'] ?? ''));
                    $o['salesman'] = $sm ? $sm['name'] : '';
                    // Order Allocation page: chosen panel / employee / type win.
                    apply_allocation($o, $key, $allocMap);
                    if ($o['allocated'] && $o['allocated_emp']) $sm = ['id' => $o['allocated_emp'], 'name' => $o['salesman']];
                    if (!empty($o['allocated_direct'])) $sm = null;   // Direct order: no employee
                    if ($houseFilter !== '' && $o['house'] !== $houseFilter) continue;
                    if ($scopeInfo !== null) {
                        $scopeInfo['fetched']++;
                        // Tagged with their tag but handed to someone else on Order Allocation.
                        $tagged = match_salesman($tagMap, (string)($o['tags'] ?? ''));
                        if ($tagged && (int)$tagged['id'] === $empScopeId && $sm !== null && (int)$sm['id'] !== $empScopeId) $scopeInfo['elsewhere']++;
                    }
                    if ($empScopeId !== null && (!$sm || (int)$sm['id'] !== $empScopeId)) continue;
                    if ($scopeInfo !== null) $scopeInfo['mine']++;
                    if ($sm && (int)$sm['id'] > 0 && in_array((string)$o['house'], sheet_panels(), true)) {   // the seller's panel ("seat"): added once, automatically, so target + commission count there
                        static $__seat = []; $__sk = (int)$sm['id'] . '|' . $o['house'];
                        if (!isset($__seat[$__sk])) { $__seat[$__sk] = 1; try { if (ensure_store_groups_table($pdo)) $pdo->prepare("INSERT IGNORE INTO employee_store_groups (employee_id, group_key) VALUES (?, ?)")->execute([(int)$sm['id'], (string)$o['house']]); } catch (Throwable $e) { } }
                    }
                    $o['employee_id'] = $sm ? (int)$sm['id'] : 0;
                    $allOrders[] = $o;
                }
            }
        }

        // Custom (personal-site) stores. Salesman comes from the order's
        // broadcast rather than Shopify tags, so these rows now carry
        // attribution too — including for an employee-scoped view, which
        // matches on the panel's salesman name.
        if (true) {
            $scopeName = null;
            if ($empScopeId !== null) {
                $nq = $pdo->prepare("SELECT full_name FROM employees WHERE employee_id = ?");
                $nq->execute([$empScopeId]);
                $scopeName = (string)$nq->fetchColumn();
            }
            foreach ($customs as $csKey => $cs) {
                if ($storeKey !== '' && $storeKey !== $csKey) continue;
                // A house filter shows only the MySales orders allocated to
                // that house; the MySales filter shows only the unallocated.
                if ($houseFilter !== '' && !$allocMap) continue;
                if ($lite && !$allocMap) continue;   // Commission page: only MySales orders moved to a house count, and none were moved
                $result = fetch_custom_store($cs, $dateFrom, $dateTo);
                if (isset($result['error'])) {
                    $errors[] = $result['error'];
                    continue;
                }
                foreach ($result['orders'] as $o) {
                    $o['store_key'] = $csKey;
                    $o['store'] = $cs['label'];
                    $o['currency'] = $o['currency'] ?? 'INR';
                    $o['salesman'] = (string)($o['panel_salesman'] ?? '');
                    $o['custom_store'] = 1;
                    $o['employee_id'] = (int)(employee_ids_by_name($pdo)[mb_strtolower(trim($o['salesman']))] ?? 0);
                    apply_allocation($o, $csKey, $allocMap);
                    if (!empty($o['allocated_emp'])) $o['employee_id'] = (int)$o['allocated_emp'];
                    if (!empty($o['allocated_direct'])) { $o['employee_id'] = 0; $o['salesman'] = ''; }   // Direct order: no employee
                    if ($houseFilter !== '' && ($o['house'] ?? '') !== $houseFilter) continue;
                    if ($storeKey === $csKey && $o['allocated']) continue;   // moved out of MySales
                    if ($lite && empty($o['allocated'])) continue;           // Commission page: not moved to a house = not counted
                    // Employee-scoped view: only that person's orders.
                    if ($scopeName !== null && strcasecmp(trim($o['salesman']), trim($scopeName)) !== 0) continue;
                    $allOrders[] = $o;
                }
            }
        }

        // Manual (counter/WhatsApp) orders from the local DB, unless a
        // specific Shopify store was selected.
        if ($empScopeId === null && !$lite && $houseFilter === '' && ($storeKey === '' || $storeKey === 'manual')) {
            $mStmt = $pdo->prepare(
                "SELECT * FROM manual_orders
                 WHERE order_date >= ? AND order_date <= ?
                 ORDER BY order_date DESC"
            );
            // Same business-day window as Shopify orders (Day timing setting).
            $mStmt->execute(biz_window($pdo, $dateFrom, $dateTo));
            foreach ($mStmt->fetchAll() as $m) {
                $allOrders[] = [
                    'order_name' => '#' . $m['order_no'],
                    'created_at' => str_replace(' ', 'T', $m['order_date']) . '+05:30',
                    'customer' => $m['customer_name'],
                    'phone' => $m['phone'] ?: '',
                    'items' => (int)$m['items'],
                    'total' => $m['total'],
                    'currency' => 'INR',
                    'financial_status' => $m['payment_status'],
                    'fulfillment_status' => $m['fulfillment_status'],
                    'store_key' => 'manual',
                    'store' => 'Manual',
                    'manual_order_id' => (int)$m['manual_order_id'],
                    'salesman' => '',
                    'remarks' => $m['remarks'] ?: '',
                    'created_by' => $m['created_by'] ?: '',
                ];
            }
        }

        // Only the stores / houses that were picked (several at once).
        if ($multi) {
            $allOrders = array_values(array_filter($allOrders, function ($o) use ($multi) {
                foreach ($multi as $t) {
                    if (isset(house_labels()[$t])) { if (($o['house'] ?? '') === $t) return true; }
                    elseif ($t === 'tmperfumehouse') { if (($o['house'] ?? '') === order_house($t, '')) return true; }
                    elseif ($t === 'manual') { if (($o['store_key'] ?? '') === 'manual') return true; }
                    elseif (($o['store_key'] ?? '') === $t && empty($o['allocated'])) return true;
                }
                return false;
            }));
        }


        // Newest first across all stores.
        usort($allOrders, fn($a, $b) => strcmp($b['created_at'], $a['created_at']));

        // Per-order "Ticket size convincing" rating (the same rating the Order Allocation and Performance pages use),
        // so every order can be rated on this page. order_key + employee_id say what a rating belongs to.
        $rated = [];
        if ($allOrders && (!$lite || !empty($_GET['ratings'])) && ensure_order_ratings_table($pdo)) {
            $rk = [];
            foreach ($allOrders as $ro) if (isset($ro['id']) && !empty($ro['store_key']) && $ro['store_key'] !== 'manual') $rk[] = $ro['store_key'] . ':' . $ro['id'];
            foreach (array_chunk($rk, 400) as $chunk) {
                $rs = $pdo->prepare("SELECT order_key, ticket_rating FROM order_ratings WHERE order_key IN (" . implode(',', array_fill(0, count($chunk), '?')) . ")");
                $rs->execute($chunk);
                foreach ($rs->fetchAll() as $r) $rated[$r['order_key']] = $r['ticket_rating'] === null ? null : (float)$r['ticket_rating'];
            }
        }
        foreach ($allOrders as &$ao) {
            $ao['order_key'] = isset($ao['id']) && !empty($ao['store_key']) ? $ao['store_key'] . ':' . $ao['id'] : '';
            $ao['ticket_rating'] = $ao['order_key'] !== '' ? ($rated[$ao['order_key']] ?? null) : null;
        }
        unset($ao);

        // Cancelled on the Orders page (the page lists them under "Cancelled orders" and leaves them out of every total).
        $cancelMap = order_cancels_map($pdo);
        foreach ($allOrders as &$ao) {
            $ck = (string)($ao['store_key'] ?? '') . '|' . (string)($ao['id'] ?? '');
            $ao['cancelled'] = isset($ao['id']) && isset($cancelMap[$ck]) ? $cancelMap[$ck] : null;
        }
        unset($ao);
        // Community = Yes (Order Allocation page), for the Orders page's Employee sheet.
        $commYes = [];
        if ($allOrders && ensure_order_community_table($pdo)) {
            try { foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $r) $commYes[$r['source'] . '|' . $r['order_id']] = true; } catch (PDOException $e) {}
        }
        foreach ($allOrders as &$ao) $ao['community'] = isset($ao['id']) && isset($commYes[(string)($ao['store_key'] ?? '') . '|' . (string)$ao['id']]) ? 'yes' : 'no';
        unset($ao);
        // Orders removed from "Extra ml" by hand: their 10 ml count is kept as ml10_was and zeroed, so the Platform summary leaves them out.
        $mlSkip = [];
        if ($allOrders && ensure_order_ml_skip_table($pdo)) {
            try { foreach ($pdo->query("SELECT source, order_id FROM order_ml_skip")->fetchAll() as $r) $mlSkip[$r['source'] . '|' . $r['order_id']] = true; } catch (PDOException $e) {}
        }
        foreach ($allOrders as &$ao) {
            $skip = isset($ao['id']) && isset($mlSkip[(string)($ao['store_key'] ?? '') . '|' . (string)$ao['id']]);
            $ao['ml_skip'] = $skip ? 1 : 0;
            if ($skip && isset($ao['colors']['ml10'])) { $ao['colors']['ml10_was'] = $ao['colors']['ml10']; $ao['colors']['ml10'] = 0; }
        }
        unset($ao);
        // Total ML / extra ML of every order (ML price slab): "Extra ml" switched off = its 10 ml pieces are not counted.
        orders_ml_extra($pdo, $allOrders);

        // Order code (Order Codes page / Shopify tag) on every order.
        foreach ($allOrders as &$ao) {
            $ao['code'] = isset($ao['id']) ? order_code_for($pdo, (string)($ao['store_key'] ?? ''), $ao['id'], (string)($ao['tags'] ?? '')) : '';
        }
        unset($ao);

        if ($lite) {
            // Only what the Commission page reads — a much smaller download.
            // report=1 (Detailed Performance Report): also keep items, tags and the Chain flag.
            $repKeep = !empty($_GET['report']);
            $repChain = [];
            if ($repKeep && ensure_order_chain_table($pdo)) {
                try { foreach ($pdo->query("SELECT source, order_id FROM order_chain")->fetchAll() as $cr) $repChain[$cr['source'] . '|' . $cr['order_id']] = true; } catch (PDOException $e) {}
            }
            foreach ($allOrders as &$ao) {
                if ($repKeep) {
                    $ao['chain'] = isset($repChain[(string)($ao['store_key'] ?? '') . '|' . (string)($ao['id'] ?? '')]) ? 'yes' : 'no';
                    unset($ao['customer'], $ao['phone'], $ao['house_tags'], $ao['fulfillment_status'], $ao['colors'], $ao['paid'], $ao['outstanding'], $ao['currency'], $ao['salesman'], $ao['order_key']);
                } else {
                    unset($ao['customer'], $ao['phone'], $ao['items'], $ao['tags'], $ao['house_tags'], $ao['fulfillment_status'], $ao['colors'], $ao['paid'], $ao['outstanding'], $ao['currency'], $ao['salesman'], $ao['order_key']);
                }
                if (empty($_GET['ratings'])) unset($ao['ticket_rating']);
            }
            unset($ao);
            if ($settleAfter) {
                // Send the answer first, then settle the older days in the background of this request.
                ignore_user_abort(true); @set_time_limit(180);
                http_response_code(200);
                echo json_encode(['orders' => $allOrders, 'errors' => $errors, 'scope' => null]);
                while (ob_get_level() > 0) @ob_end_flush();
                flush();
                if (function_exists('litespeed_finish_request')) litespeed_finish_request(); else fastcgi_finish_request();
                orders_settle_old_days($pdo);
                exit;
            }
        }
        json_response(['orders' => $allOrders, 'errors' => $errors, 'scope' => $scopeInfo]);
        break;
    }

    // ============== ORDER ALLOCATION (any order -> employee + panel + type) ==============
    case 'allocation.access_get': {
        // Admin: which departments' employees may open Order Allocation (Employee-role logins only).
        $auth = require_auth();
        if (($auth['role'] ?? '') !== 'Admin') json_response(['error' => 'Only Admin can see or change who can open Order Allocation.'], 403);
        $counts = [];
        try {
            foreach ($pdo->query("SELECT COALESCE(d.department_name, '') AS dn, COUNT(*) AS n FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex' GROUP BY d.department_name ORDER BY d.department_name")->fetchAll() as $r) $counts[] = ['name' => trim((string)$r['dn']), 'count' => (int)$r['n']];
        } catch (PDOException $e) {}
        $defaults = [];
        try { foreach ($pdo->query("SELECT department_name FROM departments ORDER BY department_name")->fetchAll() as $r) if (sales_sheet_role_ok((string)$r['department_name'], '')) $defaults[] = (string)$r['department_name']; } catch (PDOException $e) {}
        json_response(['departments' => $counts, 'selected' => allocation_allowed_departments($pdo), 'default_departments' => $defaults, 'saved' => allocation_departments_saved($pdo) !== null]);
        break;
    }

    case 'allocation.access_set': {
        $auth = require_auth();
        if (($auth['role'] ?? '') !== 'Admin') json_response(['error' => 'Only Admin can change who can open Order Allocation.'], 403);
        $input = json_input();
        $in = $input['departments'] ?? null;
        if (!is_array($in)) json_response(['error' => 'departments must be a list.'], 422);
        $names = [];
        foreach ($in as $n) { $n = trim((string)$n); if ($n !== '' && mb_strlen($n) <= 80 && !in_array($n, $names, true)) $names[] = $n; }
        setting_set($pdo, 'allocation_departments', json_encode($names, JSON_UNESCAPED_UNICODE));
        json_response(['message' => 'Saved.', 'selected' => $names]);
        break;
    }

    case 'allocation.list': {
        // Every order in the date range — TM Perfume House 
        // (Shopify) + MySales + MySales 4P — with its allocation state, plus
        // the employee list (grouped panel-wise) for the page's dropdown.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        @set_time_limit(300);            // a long date range pulls many Shopify pages + the MySales orders: never cut off half-way
        $dateFrom = $_GET['date_from'] ?? date('Y-m-d');
        $dateTo = $_GET['date_to'] ?? $dateFrom;
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        $map = order_allocations($pdo);
        $byName = employee_ids_by_name($pdo);
        $tagMap = sales_tag_map($pdo);
        $codes = [];
        foreach ($pdo->query("SELECT employee_id, employee_code FROM employees")->fetchAll() as $e) $codes[(int)$e['employee_id']] = $e['employee_code'];
        $orders = []; $errors = [];

        // Shopify stores, all in parallel.
        $stores = shopify_stores(); $tokens = [];
        foreach ($stores as $key => $store) {
            if (strpos($store['client_id'], 'PASTE_') !== false) { unset($stores[$key]); continue; }
            $token = shopify_get_token($key, $store);
            if (is_array($token)) { $errors[] = $token['error']; unset($stores[$key]); continue; }
            $tokens[$key] = $token;
        }
        if ($stores) {
            // A long range (more than a week) is read from the local order copy (shop_orders, kept up to date by the Shopify webhooks):
            // pulling months of orders live from Shopify takes longer than the server allows and the page shows "Failed to fetch".
            $spanDays = (int)round((strtotime($dateTo) - strtotime($dateFrom)) / 86400) + 1;
            $shopRes = $spanDays > 7 ? orders_by_store_cached($pdo, $stores, $dateFrom, $dateTo) : null;
            if ($shopRes === null) $shopRes = shopify_fetch_all($stores, $tokens, $dateFrom, $dateTo, 40);
            foreach ($shopRes as $key => $st) {   // 🤖 new pending orders → the salesperson of the customer's WhatsApp chat, before the list is shown
                if (!empty($st['error'])) continue;
                foreach ($st['orders'] as $o) { if (isset($map[$key . '|' . (string)$o['id']])) continue; $r = order_auto_alloc($pdo, (string)$key, $o); if (is_array($r)) $map[$key . '|' . (string)$o['id']] = $r + ['direct' => 0]; }
            }
            foreach ($shopRes as $key => $st) {
                if ($st['error']) { $errors[] = $st['error']; continue; }
                foreach ($st['orders'] as $o) {
                    $o['store_key'] = $key;
                    $o['source_label'] = $st['store']['label'];
                    $o['store'] = $st['store']['label'];
                    $o['house'] = order_house($key, (string)($o['tags'] ?? ''));
                    $o['biz_date'] = biz_day_of($pdo, strtotime((string)$o['created_at']));
                    $sm = match_salesman($tagMap, (string)($o['tags'] ?? ''));
                    $o['salesman'] = $sm ? $sm['name'] : '';
                    $o['employee_id'] = $sm ? (int)$sm['id'] : 0;
                    $o['employee_from'] = $sm ? 'order tag' : '';
                    // Query / Campaign already on the order's tags (same tags
                    // the Orders and Targets pages read: query / s, campaign / c).
                    $o['tag_type'] = '';
                    foreach (explode(',', (string)($o['tags'] ?? '')) as $t) {
                        $t = strtolower(trim($t));
                        if ($t === 'query' || $t === 's') { $o['tag_type'] = 'query'; break; }
                        if ($t === 'campaign' || $t === 'c') { $o['tag_type'] = 'campaign'; break; }
                    }
                    apply_allocation($o, $key, $map);
                    if (!$o['allocated']) $o['order_type'] = $o['tag_type'];
                    if ($o['allocated_emp']) $o['employee_id'] = $o['allocated_emp'];
                    if ($o['allocated_direct']) { $o['employee_id'] = 0; $o['employee_from'] = ''; }
                    $o['employee_code'] = $o['employee_id'] ? ($codes[$o['employee_id']] ?? '') : '';
                    $orders[] = $o;
                }
            }
        }

        // MySales only (MySales 4P is not allocated here).
        foreach (array_intersect_key(custom_stores(), ['mysales' => 1]) as $csKey => $cs) {
            $res = fetch_custom_store($cs, $dateFrom, $dateTo);
            if (isset($res['error'])) { $errors[] = $res['error']; continue; }
            foreach ($res['orders'] as $o) {
                $o['store_key'] = $csKey;
                $o['source_label'] = $cs['label'];
                $o['custom_store'] = 1;
                $o['store'] = $cs['label'];
                $o['house'] = '';
                $o['salesman'] = (string)($o['panel_salesman'] ?? '');
                $eid = $byName[mb_strtolower(trim($o['salesman']))] ?? 0;
                $o['employee_id'] = $eid;
                $o['employee_from'] = $o['salesman'] !== '' ? 'panel salesman' : '';
                apply_allocation($o, $csKey, $map);
                if ($o['allocated_emp']) $o['employee_id'] = $o['allocated_emp'];
                if ($o['allocated_direct']) { $o['employee_id'] = 0; $o['employee_from'] = ''; }
                $o['employee_code'] = $o['employee_id'] ? ($codes[$o['employee_id']] ?? '') : '';
                $orders[] = $o;
            }
        }
        usort($orders, fn($a, $b) => strcmp((string)$b['created_at'], (string)$a['created_at']));

        // Per-order "Ticket size convincing" rating (same order_ratings rows
        // the Performance page reads and writes), so it can be given here.
        $ratings = []; $ratedBy = [];      // order_key => stars; order_key => ['by', 'at'] (who gave the stars, when)
        if ($orders && ensure_order_ratings_table($pdo)) {
            ensure_order_ratings_ticket_columns($pdo);
            $keys = array_map(fn($o) => $o['store_key'] . ':' . $o['id'], $orders);
            foreach (array_chunk($keys, 400) as $chunk) {
                $in = implode(',', array_fill(0, count($chunk), '?'));
                try {
                    $st = $pdo->prepare("SELECT order_key, ticket_rating, COALESCE(ticket_by, updated_by) AS by_who, COALESCE(ticket_at, updated_at) AS at_when FROM order_ratings WHERE order_key IN ($in)");
                    $st->execute($chunk);
                } catch (PDOException $e) {
                    $st = $pdo->prepare("SELECT order_key, ticket_rating, updated_by AS by_who, updated_at AS at_when FROM order_ratings WHERE order_key IN ($in)");
                    $st->execute($chunk);
                }
                foreach ($st->fetchAll() as $r) {
                    $ratings[$r['order_key']] = $r['ticket_rating'] === null ? null : (float)$r['ticket_rating'];
                    if ($r['ticket_rating'] !== null) $ratedBy[$r['order_key']] = ['by' => (string)($r['by_who'] ?? ''), 'at' => (string)($r['at_when'] ?? '')];
                }
            }
        }
        // Extra customer mobile number typed on this page.
        $xPhones = [];
        if ($orders && ensure_order_phones_table($pdo)) {
            try {
                foreach ($pdo->query("SELECT source, order_id, phone FROM order_extra_phones")->fetchAll() as $r) $xPhones[$r['source'] . '|' . $r['order_id']] = $r['phone'];
            } catch (PDOException $e) {}
        }
        // Chain = Yes orders (Order Allocation page).
        $chainYes = [];
        if ($orders && ensure_order_chain_table($pdo)) {
            try {
                foreach ($pdo->query("SELECT source, order_id FROM order_chain")->fetchAll() as $r) $chainYes[$r['source'] . '|' . $r['order_id']] = true;
            } catch (PDOException $e) {}
        }
        // Address = Yes orders (Order Allocation page).
        $addrYes = [];
        if ($orders && ensure_order_address_table($pdo)) {
            try {
                foreach ($pdo->query("SELECT source, order_id FROM order_address")->fetchAll() as $r) $addrYes[$r['source'] . '|' . $r['order_id']] = true;
            } catch (PDOException $e) {}
        }
        // Community = Yes orders (Order Allocation page).
        $commYes = [];
        if ($orders && ensure_order_community_table($pdo)) {
            try {
                foreach ($pdo->query("SELECT source, order_id FROM order_community")->fetchAll() as $r) $commYes[$r['source'] . '|' . $r['order_id']] = true;
            } catch (PDOException $e) {}
        }
        // Old / New price per order (Order Allocation page).
        $priceType = [];
        if ($orders && ensure_order_price_type_table($pdo)) {
            try {
                foreach ($pdo->query("SELECT source, order_id, price_type FROM order_price_type")->fetchAll() as $r) $priceType[$r['source'] . '|' . $r['order_id']] = (string)$r['price_type'];
            } catch (PDOException $e) {}
        }
        foreach ($orders as &$o) $o['price_type'] = ($priceType[$o['store_key'] . '|' . $o['id']] ?? '') === 'old' ? 'old' : 'new';   // not chosen = New
        unset($o);
        $cancelMap = order_cancels_map($pdo);
        orders_ml_extra($pdo, $orders);   // total ML + free 10 ml pieces of each order (ML column)
        foreach ($orders as &$o) { $o['chain'] = isset($chainYes[$o['store_key'] . '|' . $o['id']]) ? 'yes' : 'no'; $o['address'] = isset($addrYes[$o['store_key'] . '|' . $o['id']]) ? 'yes' : 'no'; $o['community'] = isset($commYes[$o['store_key'] . '|' . $o['id']]) ? 'yes' : 'no'; $o['extra_phone'] = $xPhones[$o['store_key'] . '|' . $o['id']] ?? ''; $o['order_key'] = $o['store_key'] . ':' . $o['id']; $o['ticket_rating'] = $ratings[$o['order_key']] ?? null; $o['rating_by'] = $ratedBy[$o['order_key']]['by'] ?? ''; $o['rating_at'] = $ratedBy[$o['order_key']]['at'] ?? ''; $o['cancelled'] = $cancelMap[$o['store_key'] . '|' . $o['id']] ?? null; $o['code'] = order_code_for($pdo, (string)$o['store_key'], $o['id'], (string)($o['tags'] ?? '')); }
        unset($o);

        // Employees for the dropdown, with their panels (store groups).
        ensure_store_groups_table($pdo);
        $groups = [];
        try {
            foreach ($pdo->query("SELECT employee_id, group_key FROM employee_store_groups")->fetchAll() as $g) $groups[(int)$g['employee_id']][] = $g['group_key'];
        } catch (PDOException $e) {}
        $employees = [];
        foreach ($pdo->query("SELECT employee_id, employee_code, full_name FROM employees WHERE status != 'ex' ORDER BY full_name")->fetchAll() as $e) {
            $employees[] = ['id' => (int)$e['employee_id'], 'code' => $e['employee_code'], 'name' => $e['full_name'], 'groups' => $groups[(int)$e['employee_id']] ?? []];
        }

        $sources = [];
        foreach (shopify_stores() as $k => $st) $sources[$k] = $st['label'];
        foreach (array_intersect_key(custom_stores(), ['mysales' => 1]) as $k => $cs) $sources[$k] = $cs['label'];

        json_response([
            'orders' => $orders, 'errors' => $errors, 'houses' => house_labels(),
            'types' => ['query' => 'Query', 'campaign' => 'Campaign'],
            'employees' => $employees, 'sources' => $sources,
        ]);
        break;
    }

    case 'allocation.customer_search':
    case 'order_codes.customer_search': {      // same lookup for the Order Allocation and Order Codes pages (each gated by its own module)
        // Find a customer by mobile number across ALL dates (not just the day on screen): every order saved with
        // that number — as the order's own phone or as the extra mobile typed on this page — from the Shopify
        // stores (shop_orders) and MySales, each with the employee / panel it is counted under.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $digits = preg_replace('/\D+/', '', (string)($_GET['phone'] ?? ''));
        if (strlen($digits) > 10) $digits = substr($digits, -10);          // +91 / 0 in front of the number
        if (strlen($digits) < 6) json_response(['error' => 'Type at least 6 digits of the mobile number.'], 422);
        $like = '%' . $digits . '%';
        $strip = function (string $c): string { return "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE($c,' ',''),'-',''),'+',''),'(',''),')','')"; };
        $tail = function ($p): string { $d = preg_replace('/\D+/', '', (string)$p); return $d === '' ? '' : substr($d, -10); };

        $map = order_allocations($pdo);
        $tagMap = sales_tag_map($pdo);
        $cancelMap = order_cancels_map($pdo);
        $labels = [];
        foreach (shopify_stores() as $k => $st) $labels[$k] = $st['label'];
        $labels['mysales'] = custom_stores()['mysales']['label'];
        $errors = []; $orders = [];

        // Extra mobile numbers typed on the Order Allocation page: all of them (to show on each order), and the ones that match.
        $xPhones = []; $xHits = [];
        if (ensure_order_phones_table($pdo)) {
            try {
                foreach ($pdo->query("SELECT source, order_id, phone FROM order_extra_phones")->fetchAll() as $r) {
                    $xPhones[$r['source'] . '|' . $r['order_id']] = $r['phone'];
                    if (strpos($tail($r['phone']), $digits) !== false) $xHits[] = [(string)$r['source'], (string)$r['order_id']];
                }
            } catch (PDOException $e) {}
        }
        $xHits = array_slice($xHits, 0, 60);

        // Shopify stores (the order records kept in the HRMS database).
        if (ensure_shop_orders_table($pdo)) {
            try {
                $sql = "SELECT shopify_id, store_key, order_name, created_at, customer, phone, items, total, currency, financial_status, fulfillment_status, tags
                        FROM shop_orders WHERE " . $strip('phone') . " LIKE ?";
                $params = [$like];
                foreach ($xHits as [$s, $i]) {
                    if ($s === 'mysales' || !ctype_digit($i)) continue;
                    $sql .= " OR (store_key = ? AND shopify_id = ?)"; $params[] = $s; $params[] = $i;
                }
                $stmt = $pdo->prepare($sql . " ORDER BY created_at DESC LIMIT 400");
                $stmt->execute($params);
                foreach ($stmt->fetchAll() as $r) {
                    $key = $r['store_key'];
                    if (!isset($labels[$key])) continue;   // a removed store (TM Fragrance) is not searched
                    $o = [
                        'id' => (string)$r['shopify_id'], 'order_name' => $r['order_name'], 'store_key' => $key,
                        'source_label' => $labels[$key] ?? $key, 'store' => $labels[$key] ?? $key,
                        'created_at' => str_replace(' ', 'T', $r['created_at']) . '+05:30',
                        'customer' => $r['customer'] !== '' ? $r['customer'] : 'Guest', 'phone' => $r['phone'],
                        'items' => (int)$r['items'], 'total' => $r['total'], 'currency' => $r['currency'],
                        'financial_status' => $r['financial_status'], 'fulfillment_status' => $r['fulfillment_status'], 'tags' => (string)$r['tags'],
                    ];
                    $o['house'] = order_house($key, $o['tags']);
                    $o['biz_date'] = biz_day_of($pdo, strtotime($r['created_at']));
                    $sm = match_salesman($tagMap, $o['tags']);
                    $o['salesman'] = $sm ? $sm['name'] : '';
                    $o['tag_type'] = '';
                    foreach (explode(',', $o['tags']) as $t) {
                        $t = strtolower(trim($t));
                        if ($t === 'query' || $t === 's') { $o['tag_type'] = 'query'; break; }
                        if ($t === 'campaign' || $t === 'c') { $o['tag_type'] = 'campaign'; break; }
                    }
                    apply_allocation($o, $key, $map);
                    if (!$o['allocated']) $o['order_type'] = $o['tag_type'];
                    $o['code'] = order_code_for($pdo, (string)$key, $o['id'], $o['tags']);
                    $orders[] = $o;
                }
            } catch (PDOException $e) { $errors[] = 'Shopify orders: ' . $e->getMessage(); }
        }

        // MySales (the panel's own database).
        $db = sales_db();
        if (!$db) {
            $errors[] = sales_db_problem('MySales') . ' MySales orders were not searched.';
        } else {
            try {
                $nmq = sales_order_name_sql($db, custom_stores()['mysales']['table']);
                $sql = "SELECT o.id, o.customerNumber, o.`date`, o.`time`, o.prepaid, o.COD,
                               COALESCE(NULLIF(o.totalAmount, 0), o.finalPrice) AS amount, o.overall_quantity, o.isRTO, o.delivered, o.in_transit,
                               b.name AS broadcast_name, CASE WHEN cn.user_count = 1 THEN s.name ELSE NULL END AS salesman_name, {$nmq['select']}
                        FROM `" . custom_stores()['mysales']['table'] . "` o
                        LEFT JOIN broadcast b ON b.id = o.broadcastId
                        LEFT JOIN (SELECT broadcastId, MIN(userId) AS userId, COUNT(DISTINCT userId) AS user_count FROM contactnumber GROUP BY broadcastId) cn ON cn.broadcastId = o.broadcastId
                        LEFT JOIN salesman s ON s.id = cn.userId
                        {$nmq['join']}
                        WHERE " . $strip('o.customerNumber') . " LIKE ?";
                $params = [$like];
                foreach ($xHits as [$s, $i]) {
                    if ($s !== 'mysales' || !ctype_digit($i)) continue;
                    $sql .= " OR o.id = ?"; $params[] = $i;
                }
                $stmt = $db->prepare($sql . " ORDER BY o.`date` DESC, o.id DESC LIMIT 300");
                $stmt->execute($params);
                foreach ($stmt->fetchAll() as $r) {
                    $ts = strtotime(trim($r['date'] . ' ' . (string)$r['time']));
                    if ($ts === false) $ts = strtotime($r['date'] . ' 12:00');
                    $prepaid = (float)($r['prepaid'] ?? 0); $cod = (float)($r['COD'] ?? 0);
                    $payment = ($cod > 0 && $prepaid > 0) ? 'partially_paid' : ($cod > 0 ? 'cod' : 'paid');
                    if ((int)($r['isRTO'] ?? 0) === 1) $fulfillment = 'RTO';
                    elseif (!empty($r['delivered'])) $fulfillment = 'fulfilled';
                    elseif (!empty($r['in_transit'])) $fulfillment = 'in transit';
                    else $fulfillment = 'unfulfilled';
                    $o = [
                        'id' => (string)$r['id'], 'order_name' => '#' . $r['id'], 'store_key' => 'mysales', 'source_label' => $labels['mysales'], 'store' => $labels['mysales'],
                        'custom_store' => 1, 'biz_date' => $r['date'], 'created_at' => date('Y-m-d\TH:i:s', $ts) . '+05:30',
                        'customer' => trim((string)($r['cust_name'] ?? '')) !== '' ? trim((string)$r['cust_name']) : 'Guest', 'phone' => (string)($r['customerNumber'] ?? ''), 'items' => (int)($r['overall_quantity'] ?? 1),
                        'total' => (string)($r['amount'] ?? '0'), 'currency' => 'INR', 'financial_status' => $payment,
                        'paid' => $payment === 'partially_paid' ? round($prepaid, 2) : null, 'outstanding' => $payment === 'partially_paid' ? round($cod, 2) : null,
                        'fulfillment_status' => $fulfillment, 'broadcast' => $r['broadcast_name'] ?? '', 'house' => '', 'salesman' => (string)($r['salesman_name'] ?? ''),
                    ];
                    apply_allocation($o, 'mysales', $map);
                    $o['code'] = order_code_for($pdo, 'mysales', $o['id']);
                    $orders[] = $o;
                }
            } catch (PDOException $e) { $errors[] = 'MySales: ' . $e->getMessage(); }
        }

        // One card per customer number (the number that matched; the order's own phone wins over an extra one).
        $customers = [];
        foreach ($orders as $o) {
            $o['extra_phone'] = $xPhones[$o['store_key'] . '|' . $o['id']] ?? '';
            $o['cancelled'] = $cancelMap[$o['store_key'] . '|' . $o['id']] ?? null;
            $o['house_label'] = $o['house'] !== '' ? (house_labels()[$o['house']] ?? $o['house']) : '';
            unset($o['tags'], $o['house_tags']);
            $m = $tail($o['phone']); $x = $tail($o['extra_phone']);
            if ($m !== '' && strpos($m, $digits) !== false) $gk = $m;
            elseif ($x !== '' && strpos($x, $digits) !== false) $gk = $x;
            else $gk = $m !== '' ? $m : ($x !== '' ? $x : $digits);
            if (!isset($customers[$gk])) $customers[$gk] = ['phone' => $gk, 'name' => '', 'other_phones' => [], 'orders' => [], 'order_count' => 0, 'cancelled_count' => 0, 'spent' => 0.0, 'first_at' => '', 'last_at' => '', 'stores' => []];
            $c = &$customers[$gk];
            foreach ([$m, $x] as $p) if ($p !== '' && $p !== $gk && !in_array($p, $c['other_phones'], true)) $c['other_phones'][] = $p;
            $c['orders'][] = $o;
            if ($o['cancelled']) $c['cancelled_count']++; else { $c['order_count']++; $c['spent'] += (float)$o['total']; }
            if ($c['first_at'] === '' || $o['created_at'] < $c['first_at']) $c['first_at'] = $o['created_at'];
            if ($o['created_at'] > $c['last_at']) $c['last_at'] = $o['created_at'];
            if (!in_array($o['source_label'], $c['stores'], true)) $c['stores'][] = $o['source_label'];
            unset($c);
        }
        foreach ($customers as &$c) {
            usort($c['orders'], fn($a, $b) => strcmp((string)$b['created_at'], (string)$a['created_at']));
            foreach ($c['orders'] as $o) if (($o['customer'] ?? '') !== '' && $o['customer'] !== 'Guest') { $c['name'] = $o['customer']; break; }   // newest real name
            if ($c['name'] === '') $c['name'] = 'Guest';
            $c['spent'] = round($c['spent'], 2);
        }
        unset($c);
        $list = array_values($customers);
        usort($list, fn($a, $b) => strcmp($b['last_at'], $a['last_at']));

        json_response(['customers' => array_slice($list, 0, 20), 'matches' => count($list), 'orders_found' => count($orders), 'errors' => $errors]);
        break;
    }

    case 'allocation.set': {
        // Save one order's employee + panel + type (house = '' removes it).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_allocations_table($pdo)) json_response(['error' => 'Could not create the order_allocations table.'], 500);
        $in = json_input();
        $source = (string)($in['source'] ?? '');
        $orderId = trim((string)($in['order_id'] ?? ''));
        $house = (string)($in['house'] ?? '');
        $type = strtolower(trim((string)($in['order_type'] ?? '')));
        $empId = (int)($in['employee_id'] ?? 0);
        $direct = !empty($in['direct']);      // Direct order: a panel, no employee
        if ($direct) $empId = 0;
        $known = isset(shopify_stores()[$source]) || $source === 'mysales';
        if (!$known || $orderId === '') json_response(['error' => 'source and order_id are required.'], 422);
        if ($house !== '' && !isset(house_labels()[$house])) json_response(['error' => 'Unknown panel.'], 422);
        if (!in_array($type, ['', 'query', 'campaign'], true)) json_response(['error' => 'Type must be Query or Campaign.'], 422);
        // Employee role: may only allocate a pending order — no undo, no changing an allocated one.
        if (strcasecmp(trim((string)($auth['role'] ?? '')), 'Employee') === 0) {
            if ($house === '') json_response(['error' => 'The Employee role cannot undo an allocation.'], 403);
            if ($type === '') json_response(['error' => 'Choose the Type (Query / Campaign) first.'], 422);
            $ex = $pdo->prepare("SELECT 1 FROM order_allocations WHERE source = ? AND order_id = ?");
            $ex->execute([$source, $orderId]);
            if ($ex->fetchColumn()) json_response(['error' => 'This order is already allocated — only Admin or Sales Head can change it.'], 403);
        }
        if ($house === '') {
            $pdo->prepare("DELETE FROM order_allocations WHERE source = ? AND order_id = ?")->execute([$source, $orderId]);
            json_response(['message' => 'Order #' . $orderId . ' allocation removed.']);
        }
        // (No proof gate any more: the chat screenshot / call recording needed before allocating ended on 1 Nov 2026.)
        if ($direct) {
            $empName = 'Direct order';
        } else {
            if ($empId <= 0) json_response(['error' => 'Choose an employee (or Direct order).'], 422);
            $chk = $pdo->prepare("SELECT full_name FROM employees WHERE employee_id = ? AND status != 'ex'");
            $chk->execute([$empId]);
            $empName = $chk->fetchColumn();
            if (!$empName) json_response(['error' => 'Unknown employee.'], 422);
        }
        $who = (string)($auth['username'] ?? 'admin');
        $pdo->prepare(
            "INSERT INTO order_allocations (source, order_id, house, order_type, employee_id, is_direct, allocated_by) VALUES (?, ?, ?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE house = VALUES(house), order_type = VALUES(order_type), employee_id = VALUES(employee_id), is_direct = VALUES(is_direct), allocated_by = VALUES(allocated_by), allocated_at = CURRENT_TIMESTAMP"
        )->execute([$source, $orderId, $house, $type, $empId, $direct ? 1 : 0, $who]);
        json_response([
            'message' => 'Order #' . $orderId . ' → ' . $empName . ' · ' . house_labels()[$house] . ($type ? ' · ' . ucfirst($type) : '') . '.',
            'allocated_by' => $who, 'allocated_at' => date('Y-m-d H:i:s'), 'employee_name' => $empName, 'direct' => $direct ? 1 : 0,
        ]);
        break;
    }

    // ---------------- Order codes ----------------
    case 'order_codes.lock_get': {
        $auth = require_auth();
        require_role(['Admin'], $auth);      // other roles: only when "Order Code Lock" is ticked for them on the Roles page
        json_response(code_lock_cfg($pdo));
        break;
    }

    case 'order_codes.lock_set': {
        // Admin, or any role ticked for "Order Code Lock" on the Roles page: how long after allocation an Employee
        // login may add / change a code.
        //   mode off | hours (+ hours) | time (+ time "HH:MM" — until the first such time after the allocation)
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $mode = (string)($in['mode'] ?? 'off');
        if (!in_array($mode, ['off', 'hours', 'time'], true)) json_response(['error' => 'Mode must be off, hours or time.'], 422);
        $cur = code_lock_cfg($pdo);
        $h = $cur['hours']; $t = $cur['time'];
        if (array_key_exists('hours', $in)) {
            $h = round((float)$in['hours'] * 2) / 2;      // steps of half an hour
            if ($h < 0 || $h > 720) json_response(['error' => 'Hours must be between 0 and 720.'], 422);
        }
        if (array_key_exists('time', $in) && (string)$in['time'] !== '') {
            $t = (string)$in['time'];
            if (!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $t)) json_response(['error' => 'Time must look like 18:00.'], 422);
        }
        if ($mode === 'hours' && $h <= 0) json_response(['error' => 'Type the hours (more than 0), or choose Off.'], 422);
        if ($mode === 'time' && $t === '') json_response(['error' => 'Pick the time.'], 422);
        setting_set($pdo, 'code_lock_mode', $mode);
        setting_set($pdo, 'code_lock_hours', (string)$h);
        setting_set($pdo, 'code_lock_time', $t);
        $msg = $mode === 'hours' ? 'Saved — Employees can add or change a code for ' . $h . ' hour' . ($h == 1 ? '' : 's') . ' after the order is allocated.'
            : ($mode === 'time' ? 'Saved — Employees can add or change a code until ' . code_lock_time_label($t) . ' after the order is allocated.' : 'Saved — no time limit on adding codes.');
        json_response(['message' => $msg, 'mode' => $mode, 'hours' => $h, 'time' => $t]);
        break;
    }

    case 'order_codes.list': {
        // Orders in the range with their code.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $dateFrom = $_GET['date_from'] ?? date('Y-m-d');
        $dateTo = $_GET['date_to'] ?? $dateFrom;
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        @set_time_limit(300);
        $errors = [];
        $orders = code_orders_range($pdo, $dateFrom, $dateTo, $errors);
        $sources = [];
        foreach (shopify_stores() as $k => $st) $sources[$k] = $st['label'];
        foreach (array_intersect_key(custom_stores(), ['mysales' => 1]) as $k => $cs) $sources[$k] = $cs['label'];
        // Plain count of saved codes, so the page can show whether Apply /
        // Save actually reached the database.
        $dbCodes = null; $dbErr = '';
        if (!ensure_order_codes_table($pdo)) $dbErr = 'The order_codes table could not be created — check the database user has CREATE rights.';
        else { try { $dbCodes = (int)$pdo->query("SELECT COUNT(*) FROM order_codes")->fetchColumn(); } catch (PDOException $e) { $dbErr = 'order_codes table: ' . $e->getMessage(); } }
        json_response(['orders' => $orders, 'errors' => $errors, 'sources' => $sources, 'houses' => house_labels(), 'db_codes' => $dbCodes, 'db_error' => $dbErr]);
        break;
    }

    case 'orders.cancel': {
        // Orders page: Cancel (cancel=1) / Undo (cancel=0) one order — saved in HRMS only.
        $auth = require_auth();
        // The Employee role can never cancel an order, whatever modules are ticked for it.
        if (strtolower(trim((string)($auth['role'] ?? ''))) === 'employee') json_response(['error' => 'Employees cannot cancel orders.'], 403);
        // Admin, or a role that has the Shopify Orders or Order Allocation module (the two pages with the button).
        if (($auth['role'] ?? '') !== 'Admin' && !user_can($auth, 'orders') && !user_can($auth, 'allocation')) json_response(['error' => 'You do not have permission to cancel orders.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_cancels_table($pdo)) json_response(['error' => 'Could not create the order_cancels table.'], 500);
        $in = json_input();
        $source = (string)($in['source'] ?? '');
        $orderId = trim((string)($in['order_id'] ?? ''));
        $name = trim((string)($in['order_name'] ?? ''));
        if ($source === '' || $orderId === '' || $source === 'manual') json_response(['error' => 'source and order_id are required.'], 422);
        if (!empty($in['cancel'])) {
            $by = (string)($auth['username'] ?? $auth['full_name'] ?? '');
            $pdo->prepare("INSERT INTO order_cancels (source, order_id, order_name, cancelled_by) VALUES (?, ?, ?, ?)
                           ON DUPLICATE KEY UPDATE order_name = VALUES(order_name), cancelled_by = VALUES(cancelled_by), cancelled_at = CURRENT_TIMESTAMP")
                ->execute([$source, $orderId, $name, $by]);
            json_response(['message' => ($name !== '' ? $name : 'Order') . ' cancelled.', 'by' => $by, 'at' => date('Y-m-d H:i:s')]);
        }
        $pdo->prepare("DELETE FROM order_cancels WHERE source = ? AND order_id = ?")->execute([$source, $orderId]);
        json_response(['message' => ($name !== '' ? $name : 'Order') . ' is back.']);
        break;
    }

    case 'order_phone.set': {
        // One order's extra customer mobile number (phone '' removes it).
        $auth = require_auth();
        // Same people as the order code box: Orders page controls, or any role that has Order Allocation (Employee included).
        if (!orders_page_controls($auth) && !user_can($auth, 'allocation')) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_phones_table($pdo)) json_response(['error' => 'Could not create the order_extra_phones table.'], 500);
        $in = json_input();
        $source = (string)($in['source'] ?? '');
        $orderId = trim((string)($in['order_id'] ?? ''));
        if (!(isset(shopify_stores()[$source]) || $source === 'mysales') || $orderId === '' || strlen($orderId) > 40) json_response(['error' => 'source and order_id are required.'], 422);
        $phone = preg_replace('/[\s().-]+/', '', trim((string)($in['phone'] ?? '')));
        if ($phone === '') {
            $pdo->prepare("DELETE FROM order_extra_phones WHERE source = ? AND order_id = ?")->execute([$source, $orderId]);
            json_response(['phone' => '', 'message' => 'Extra mobile number removed.']);
        }
        if (!preg_match('/^\+?\d{10,15}$/', $phone)) json_response(['error' => 'Enter a valid mobile number (10 to 15 digits).'], 422);
        $pdo->prepare(
            "INSERT INTO order_extra_phones (source, order_id, order_name, phone, updated_by) VALUES (?, ?, ?, ?, ?)
             ON DUPLICATE KEY UPDATE order_name = VALUES(order_name), phone = VALUES(phone), updated_by = VALUES(updated_by)"
        )->execute([$source, $orderId, mb_substr(trim((string)($in['order_name'] ?? '')), 0, 40), $phone, (string)($auth['username'] ?? '')]);
        json_response(['phone' => $phone, 'message' => 'Extra mobile number saved.']);
        break;
    }

    case 'order_chain.set': {
