        $auth = require_auth();
        if (strcasecmp(trim((string)($auth['role'] ?? '')), 'Employee') === 0) json_response(['error' => 'Employees cannot change the Chain option.'], 403);
        if (!orders_page_controls($auth) && !user_can($auth, 'allocation')) require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_chain_table($pdo)) json_response(['error' => 'Could not create the order_chain table.'], 500);
