        $chain = strtolower(trim((string)($in['chain'] ?? '')));
        if ($chain !== 'yes' && $chain !== 'no') json_response(['error' => 'Chain must be Yes or No.'], 422);
        if ($chain === 'no') {
            $pdo->prepare("DELETE FROM order_chain WHERE source = ? AND order_id = ?")->execute([$source, $orderId]);
        } else {
