            )->execute([$source, $orderId, mb_substr(trim((string)($in['order_name'] ?? '')), 0, 40), (string)($auth['username'] ?? '')]);
        }
        json_response(['chain' => $chain, 'message' => 'Chain: ' . ($chain === 'yes' ? 'Yes' : 'No') . '.']);
        break;
    }

