        $in = json_input();
        $dateFrom = (string)($in['date_from'] ?? ''); $dateTo = (string)($in['date_to'] ?? $dateFrom);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        $rows = (array)($in['rows'] ?? []);
        if (!$rows) json_response(['error' => 'No rows found in the file.'], 422);
        if (count($rows) > 5000) json_response(['error' => 'Upload up to 5000 rows at a time.'], 422);
        @set_time_limit(300);
        $errors = [];
        $orders = code_orders_range($pdo, $dateFrom, $dateTo, $errors);
        $byKey = [];   // "TMPH-58211" and "369910" → order
        foreach ($orders as $o) {
            $byKey[code_order_key($o['order_name'])] = $o;
            $byKey['ID:' . $o['source'] . ':' . $o['id']] = $o;
        }
        $out = []; $n = ['match' => 0, 'replace' => 0, 'notfound' => 0, 'skip' => 0];
        $seen = [];
        foreach ($rows as $i => $r) {
            $rawId = trim((string)($r['order_id'] ?? '')); $code = code_norm((string)($r['code'] ?? ''));
            $row = ['row' => (int)($r['row'] ?? ($i + 2)), 'order_id' => $rawId, 'code' => $code, 'status' => '', 'note' => '', 'order' => null];
            if ($rawId === '' && $code === '') continue;
            if ($rawId === '') { $row['status'] = 'skip'; $row['note'] = 'Blank Order ID'; $n['skip']++; $out[] = $row; continue; }
            if ($code === '') { $row['status'] = 'skip'; $row['note'] = 'Blank code'; $n['skip']++; $out[] = $row; continue; }
            if (!preg_match('/^[A-Z0-9_-]{2,40}$/', $code)) { $row['status'] = 'skip'; $row['note'] = 'Invalid code (letters / numbers only)'; $n['skip']++; $out[] = $row; continue; }
            $k = code_order_key($rawId);
            $o = $byKey[$k] ?? null;
            if (!$o && preg_match('/^\d+$/', $k)) $o = $byKey['ID:mysales:' . $k] ?? null;
            if (!$o) { $row['status'] = 'notfound'; $row['note'] = 'No such order between ' . $dateFrom . ' and ' . $dateTo; $n['notfound']++; $out[] = $row; continue; }
            $ok = $o['source'] . '|' . $o['id'];
            if (isset($seen[$ok])) { $row['status'] = 'skip'; $row['note'] = 'Duplicate of row ' . $seen[$ok]; $n['skip']++; $out[] = $row; continue; }
            $seen[$ok] = $row['row'];
            $row['order'] = ['source' => $o['source'], 'id' => $o['id'], 'order_name' => $o['order_name'], 'customer' => $o['customer'], 'total' => $o['total'], 'store' => $o['store'], 'can_tag' => $o['can_tag'], 'old_code' => $o['code']];
            if ($o['code'] !== '' && $o['code'] !== $code) { $row['status'] = 'replace'; $row['note'] = 'Has ' . $o['code'] . ' → will become ' . $code; $n['replace']++; }
            elseif ($o['code'] === $code) { $row['status'] = 'same'; $row['note'] = 'Already ' . $code; $n['skip']++; }
            else { $row['status'] = 'match'; $n['match']++; }
            $out[] = $row;
        }
        json_response(['rows' => $out, 'counts' => $n, 'errors' => $errors, 'date_from' => $dateFrom, 'date_to' => $dateTo]);
        break;
    }

    case 'order_codes.apply': {
        // Save the previewed rows (match + replace) and write their tags.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_order_codes_table($pdo)) json_response(['error' => 'Could not create the order_codes table.'], 500);
        $in = json_input();
        $items = (array)($in['items'] ?? []);
        if (!$items) json_response(['error' => 'Nothing to apply.'], 422);
        if (count($items) > 2000) json_response(['error' => 'Apply up to 2000 orders at a time.'], 422);
        set_time_limit(600);
        $saved = 0; $tagged = 0; $tagFail = []; $results = [];
        foreach ($items as $it) {
            $source = (string)($it['source'] ?? ''); $id = trim((string)($it['id'] ?? '')); $code = code_norm((string)($it['code'] ?? ''));
            if (!(isset(shopify_stores()[$source]) || $source === 'mysales') || $id === '' || $code === '') continue;
            $o = ['source' => $source, 'id' => $id, 'order_name' => (string)($it['order_name'] ?? ''), 'can_tag' => $source !== 'mysales' ? 1 : 0, 'code' => code_norm((string)($it['old_code'] ?? ''))];
            $r = order_code_save($pdo, $auth, $o, $code, 'excel');
            $saved++;
            if ($o['can_tag']) { if ($r['tag_written']) $tagged++; else $tagFail[] = $o['order_name'] . ': ' . $r['tag_error']; }
            $results[] = ['source' => $source, 'id' => $id] + $r;
        }
        // Re-read what actually landed in the table, so the page can tell
        // the difference between "saved" and "request finished".
        $verified = 0;
        try {
            $chk = $pdo->prepare("SELECT code FROM order_codes WHERE source = ? AND order_id = ?");
            foreach ($results as $r) { $chk->execute([$r['source'], $r['id']]); if ((string)$chk->fetchColumn() === $r['code']) $verified++; }
        } catch (PDOException $e) {}
        json_response([
            'message' => $saved . ' order' . ($saved === 1 ? '' : 's') . ' updated · ' . $tagged . ' Shopify tag' . ($tagged === 1 ? '' : 's') . ' written' . ($tagFail ? ' · ' . count($tagFail) . ' tag' . (count($tagFail) === 1 ? '' : 's') . ' failed' : ''),
            'saved' => $saved, 'verified' => $verified, 'tagged' => $tagged, 'tag_failed' => $tagFail, 'results' => $results,
        ]);
        break;
    }

    // ---------------- Punch-in reminders ----------------
    case 'presence.report': {
        // The punch page says where the phone is. Inside an office radius
        // and not punched in yet → remembered as "at the office since …"
        // so the reminder can go out after N minutes.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_reminder_tables($pdo);
        $in = json_input();
        $lat = isset($in['lat']) ? (float)$in['lat'] : null; $lng = isset($in['lng']) ? (float)$in['lng'] : null; $acc = isset($in['accuracy']) ? (float)$in['accuracy'] : null;
        $empId = (int)$auth['employee_id'];
        $date = attendance_day_now($pdo);
        $s = reminder_settings($pdo);
        $st = $pdo->prepare("SELECT punch_in FROM attendance WHERE employee_id = ? AND punch_date = ?");
        $st->execute([$empId, $date]);
        $punchedIn = (string)($st->fetchColumn() ?: '');
        [$inside, $office, $dist] = geo_check_punch($pdo, $empId, $lat, $lng, $acc);
        $row = null;
        $now = date('Y-m-d H:i:s');
        if ($inside && $office) {
            $pdo->prepare(
                "INSERT INTO office_presence (employee_id, presence_date, office_id, first_seen, last_seen, inside, last_inside, distance_m) VALUES (?, ?, ?, ?, ?, 1, ?, ?)
                 ON DUPLICATE KEY UPDATE last_seen = VALUES(last_seen), inside = 1, last_inside = VALUES(last_inside), office_id = VALUES(office_id), distance_m = VALUES(distance_m)"
            )->execute([$empId, $date, (int)$office['office_id'], $now, $now, $now, (int)round($dist)]);
        } else {
            // Out of the area now: remember that, so no reminder follows them home.
            $pdo->prepare("UPDATE office_presence SET inside = 0, last_seen = ?, distance_m = ? WHERE employee_id = ? AND presence_date = ?")
                ->execute([$now, $dist === null ? 0 : (int)round($dist), $empId, $date]);
        }
        $q = $pdo->prepare("SELECT p.first_seen, o.office_name FROM office_presence p LEFT JOIN offices o ON o.office_id = p.office_id WHERE p.employee_id = ? AND p.presence_date = ?");
        $q->execute([$empId, $date]);
        $row = $q->fetch() ?: null;
        $since = $row ? strtotime((string)$row['first_seen']) : null;
        json_response([
            'inside' => $inside ? 1 : 0, 'office' => $office ? $office['office_name'] : '', 'punched_in' => $punchedIn !== '' ? 1 : 0,
            'at_office_since' => $row ? (string)$row['first_seen'] : null, 'at_office_name' => $row ? (string)$row['office_name'] : '',
            'minutes_here' => $since ? (int)floor((time() - $since) / 60) : 0,
            'remind_after' => $s['after_arrive'], 'reminders_on' => $s['enabled'],
        ]);
        break;
    }

    case 'me.reminder_status': {
        // Polled by the employee's open HRMS page (about once a minute): is a
        // "you haven't punched in" pop-up due right now?
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['show' => 0]);
        json_response(reminder_popup_for($pdo, (int)$auth['employee_id']));
        break;
    }

    case 'reminders.settings': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        json_response(['settings' => reminder_settings($pdo), 'day_start' => day_start_for($pdo, biz_today($pdo))]);
        break;
    }

    case 'reminders.settings_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_reminder_tables($pdo)) json_response(['error' => 'Could not create the settings tables.'], 500);
        $in = json_input();
        $map = ['enabled' => 'rem_enabled', 'after_arrive' => 'rem_after_arrive', 'after_shift' => 'rem_after_shift', 'repeat_every' => 'rem_repeat_every', 'max_reminders' => 'rem_max', 'quiet_until' => 'rem_quiet_until', 'push_enabled' => 'rem_push', 'office_only' => 'rem_office_only', 'presence_fresh' => 'rem_presence_fresh'];
        foreach ($map as $k => $key) if (array_key_exists($k, $in)) setting_set($pdo, $key, is_bool($in[$k]) ? (int)$in[$k] : trim((string)$in[$k]));
        json_response(['message' => 'Reminder settings saved.']);
        break;
    }

    case 'reminders.diag': {
        // "Why is no reminder going out?" — answered in one place.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $tables = ensure_reminder_tables($pdo);
        $s = reminder_settings($pdo);
        $date = biz_today($pdo);
        $dayStart = day_start_for($pdo, $date);
        $now = time();
        $startTs = strtotime($date . ' ' . $dayStart . ':00');
        $problems = []; $notes = [];

        if (!$tables) $problems[] = 'The reminder tables could not be created in the database.';
        if (!$s['enabled']) $problems[] = 'Reminders are OFF — tick "Reminders on" in Settings below and save.';
        if ($s['office_only']) $notes[] = 'Office-only is ON: a reminder goes out only when the phone is inside an office area (last position not older than ' . $s['presence_fresh'] . ' min), the punch-in time (' . $dayStart . ' + ' . $s['after_shift'] . ' min) has passed, and there is still no punch in. Outside the area: nothing.';
        elseif ($s['after_shift'] <= 0) $notes[] = 'The "after day start" rule is off (0), so only employees seen at an office get reminded.';
        else $notes[] = 'Office-only is OFF, so employees are also reminded ' . $s['after_shift'] . ' min after the day starts even when they are not at the office.';
        if ($s['quiet_until'] !== '' && date('H:i') < $s['quiet_until']) $problems[] = 'Quiet time: nothing is sent before ' . $s['quiet_until'] . '.';
        if ($now < $startTs) $notes[] = 'The day has not started yet (starts ' . $dayStart . ').';

        // Who would get one right now, and the first reason each of the others does not.
        $cand = $s['enabled'] ? reminder_candidates($pdo, $s) : [];
        $why = [];
        $emps = $pdo->query("SELECT employee_id, full_name FROM employees WHERE status != 'ex' ORDER BY full_name")->fetchAll();
        $punched = []; $st = $pdo->prepare("SELECT employee_id FROM attendance WHERE punch_date = ? AND punch_in IS NOT NULL"); $st->execute([$date]);
        foreach ($st->fetchAll() as $r) $punched[(int)$r['employee_id']] = 1;
        $marks = []; try { $st = $pdo->prepare("SELECT employee_id FROM day_marks WHERE mark_date = ?"); $st->execute([$date]); foreach ($st->fetchAll() as $r) $marks[(int)$r['employee_id']] = 1; } catch (PDOException $e) {}
        $sentToday = []; try { $st = $pdo->prepare("SELECT employee_id, COUNT(*) AS n FROM punch_reminders WHERE reminder_date = ? GROUP BY employee_id"); $st->execute([$date]); foreach ($st->fetchAll() as $r) $sentToday[(int)$r['employee_id']] = (int)$r['n']; } catch (PDOException $e) {}
        $candIds = [];
        foreach ($cand as $c) $candIds[(int)$c['emp']['employee_id']] = 1;
        $counts = ['due_now' => count($cand), 'punched_in' => 0, 'on_leave' => 0, 'limit_reached' => 0, 'waiting' => 0];
        foreach ($emps as $e) {
            $id = (int)$e['employee_id'];
            if (isset($punched[$id])) { $counts['punched_in']++; continue; }
            if (isset($marks[$id])) { $counts['on_leave']++; continue; }
            if (isset($candIds[$id])) continue;
            if (($sentToday[$id] ?? 0) >= $s['max_reminders']) { $counts['limit_reached']++; continue; }
            $counts['waiting']++;
        }

        // Phones
        $pushReady = push_vapid($pdo) ? 1 : 0;
        $phones = 0; $lastErr = '';
        if (ensure_push_table($pdo)) {
            $phones = (int)$pdo->query("SELECT COUNT(*) FROM push_subscriptions")->fetchColumn();
            try { $lastErr = (string)$pdo->query("SELECT error FROM punch_reminders WHERE channel = 'push' AND ok = 0 AND error IS NOT NULL ORDER BY reminder_id DESC LIMIT 1")->fetchColumn(); } catch (PDOException $e) {}
        }
        if (!$s['push_enabled']) $notes[] = 'Phone notifications (HRMS closed) are switched off in Settings.';
        elseif (!$pushReady) $problems[] = 'This server could not make the notification keys (OpenSSL EC missing) — only the in-app pop-up will work.';
        elseif ($phones === 0) $problems[] = 'No employee has tapped "Allow notifications" yet — with HRMS closed nothing can reach a phone. The pop-up still shows while HRMS is open.';
        if ($lastErr !== '') $notes[] = 'Last phone-notification error: ' . $lastErr;

        $lastPass = (int)@filemtime(sys_get_temp_dir() . '/hrms_push_tick');
        if ($s['enabled'] && $s['push_enabled'] && $phones > 0 && (!$lastPass || $now - $lastPass > 900)) $notes[] = 'The phone pass has not run in the last 15 minutes — it runs when someone uses the HRMS. Add a cron on api.php?action=reminders.tick every 5 minutes for quiet hours.';

        json_response([
            'ok' => empty($problems) ? 1 : 0,
            'problems' => $problems,
            'notes' => $notes,
            'settings' => $s,
            'server_time' => date('Y-m-d H:i:s'),
            'business_day' => $date,
            'day_start' => $dayStart,
            'counts' => $counts,
            'due_now' => array_map(function ($c) { return ['employee_id' => (int)$c['emp']['employee_id'], 'name' => $c['emp']['full_name'], 'reason' => $c['reason'], 'seq' => $c['seq']]; }, $cand),
            'push_ready' => $pushReady,
            'phones' => $phones,
            'last_pass' => $lastPass ? date('Y-m-d H:i:s', $lastPass) : null,
        ]);
        break;
    }

    case 'reminders.test_one': {
        // Force one reminder to a single employee right now, and say exactly
        // what happened — pop-up queued, phone notified, or why not.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_reminder_tables($pdo)) json_response(['error' => 'Could not create the reminder tables.'], 500);
        $empId = (int)(json_input()['employee_id'] ?? 0);
        $st = $pdo->prepare("SELECT employee_id, full_name FROM employees WHERE employee_id = ?");
        $st->execute([$empId]);
        $emp = $st->fetch();
        if (!$emp) json_response(['error' => 'Employee not found.'], 404);
        $s = reminder_settings($pdo);
        $date = biz_today($pdo);
        $title = 'Punch-in reminder (test)';
        $body = 'Test from HR — this is how the punch-in reminder looks. No action needed.';
        $sent = 0; $failed = 0; $err = '';
        if ($s['push_enabled']) [$sent, $failed, $err] = push_send_employee($pdo, $empId, ['title' => $title, 'body' => $body, 'url' => 'attendance.html', 'tag' => 'hrms-test']);
        // The in-app pop-up is shown by whatever HRMS page that employee has open.
        $pdo->prepare("INSERT INTO punch_reminders (employee_id, reminder_date, seq, reason, channel, sent_to, sent_at, ok, error) VALUES (?, ?, 0, 'test', ?, 'test', ?, ?, ?)")
            ->execute([$empId, $date, $sent > 0 ? 'push' : 'app', date('Y-m-d H:i:s'), $sent > 0 ? 1 : 0, $sent > 0 ? null : mb_substr($err, 0, 255)]);
        $phones = 0;
        if (ensure_push_table($pdo)) { $q = $pdo->prepare("SELECT COUNT(*) FROM push_subscriptions WHERE employee_id = ?"); $q->execute([$empId]); $phones = (int)$q->fetchColumn(); }
        $msg = $sent > 0
            ? ('Sent to ' . $sent . ' phone' . ($sent === 1 ? '' : 's') . ' of ' . $emp['full_name'] . '.')
            : ($phones === 0
                ? ($emp['full_name'] . ' has not allowed notifications on any phone yet, so nothing could be sent. They must open the punch page once and tap "Allow notifications". The pop-up will still appear if they have HRMS open.')
                : ('Could not reach the phone: ' . ($err ?: 'unknown error') . '.'));
        json_response(['message' => $msg, 'sent' => $sent, 'failed' => $failed, 'phones' => $phones, 'error' => $err]);
        break;
    }

    case 'reminders.today': {
        // Admin view: who is not punched in today, since when at the office, reminders sent.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_reminder_tables($pdo);
        $date = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['date'] ?? '')) ? $_GET['date'] : biz_today($pdo);
        $rows = [];
        $emps = $pdo->query("SELECT employee_id, full_name, employee_code FROM employees WHERE status != 'ex' ORDER BY full_name")->fetchAll();
        $punched = []; $st = $pdo->prepare("SELECT employee_id, punch_in FROM attendance WHERE punch_date = ? AND punch_in IS NOT NULL"); $st->execute([$date]);
        foreach ($st->fetchAll() as $r) $punched[(int)$r['employee_id']] = (string)$r['punch_in'];
        $marks = []; try { $st = $pdo->prepare("SELECT employee_id, mark FROM day_marks WHERE mark_date = ?"); $st->execute([$date]); foreach ($st->fetchAll() as $r) $marks[(int)$r['employee_id']] = (string)$r['mark']; } catch (PDOException $e) {}
        $presence = []; $st = $pdo->prepare("SELECT p.employee_id, p.first_seen, p.last_seen, o.office_name FROM office_presence p LEFT JOIN offices o ON o.office_id = p.office_id WHERE p.presence_date = ?"); $st->execute([$date]);
        foreach ($st->fetchAll() as $r) $presence[(int)$r['employee_id']] = $r;
        $sent = []; $st = $pdo->prepare("SELECT employee_id, seq, channel, sent_at, ok, error FROM punch_reminders WHERE reminder_date = ? ORDER BY sent_at"); $st->execute([$date]);
        foreach ($st->fetchAll() as $r) $sent[(int)$r['employee_id']][] = ['seq' => (int)$r['seq'], 'channel' => $r['channel'], 'at' => $r['sent_at'], 'ok' => (int)$r['ok'], 'error' => $r['error']];
        $phones = []; if (ensure_push_table($pdo)) { foreach ($pdo->query("SELECT employee_id, COUNT(*) AS n FROM push_subscriptions GROUP BY employee_id")->fetchAll() as $r) $phones[(int)$r['employee_id']] = (int)$r['n']; }
        foreach ($emps as $e) {
            $id = (int)$e['employee_id'];
            $rows[] = [
                'employee_id' => $id, 'full_name' => $e['full_name'], 'employee_code' => $e['employee_code'],
                'punch_in' => $punched[$id] ?? null, 'mark' => $marks[$id] ?? '',
                'office' => $presence[$id]['office_name'] ?? '', 'at_office_since' => $presence[$id]['first_seen'] ?? null, 'last_seen' => $presence[$id]['last_seen'] ?? null,
                'reminders' => $sent[$id] ?? [], 'phones' => $phones[$id] ?? 0,
            ];
        }
        $lastTick = (int)@filemtime(sys_get_temp_dir() . '/hrms_push_tick');
        json_response(['date' => $date, 'rows' => $rows, 'settings' => reminder_settings($pdo), 'day_start' => day_start_for($pdo, $date),
            'push_ready' => push_vapid($pdo) ? 1 : 0, 'phones_total' => count($phones), 'employees_total' => count($emps), 'last_pass' => $lastTick ? date('Y-m-d H:i:s', $lastTick) : null]);
        break;
    }

    // ---------------- Phone notifications (Web Push) ----------------
    case 'push.key': {
        // The site's public VAPID key — the phone subscribes with it.
        $auth = require_auth();
        $keys = push_vapid($pdo);
        if (!$keys) json_response(['error' => 'This server cannot make push keys (OpenSSL EC missing).'], 500);
        json_response(['key' => $keys[0], 'enabled' => reminder_settings($pdo)['push_enabled']]);
        break;
    }

    case 'push.subscribe': {
        // Save (or refresh) this phone's subscription for the logged-in employee.
        $auth = require_auth();
        if (empty($auth['employee_id'])) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_push_table($pdo)) json_response(['error' => 'Could not create the push table.'], 500);
        $in = json_input();
        $endpoint = trim((string)($in['endpoint'] ?? ''));
        $p256dh = trim((string)($in['keys']['p256dh'] ?? ($in['p256dh'] ?? '')));
        $authKey = trim((string)($in['keys']['auth'] ?? ($in['auth'] ?? '')));
        if (!preg_match('#^https://#', $endpoint) || $p256dh === '' || $authKey === '') json_response(['error' => 'Incomplete subscription.'], 422);
        $device = mb_substr(trim((string)($in['device'] ?? ($_SERVER['HTTP_USER_AGENT'] ?? ''))), 0, 160);
        $now = date('Y-m-d H:i:s');
        // The push service already told us this exact entry is gone: do not save it again — the
        // phone must make a brand-new one (the page does that when it sees dead = true).
        if (in_array(sha1($endpoint), push_dead_hashes($pdo), true)) {
            json_response(['dead' => true, 'message' => 'This phone\'s notification link has expired — a new one is needed.']);
        }
        $pdo->prepare(
            "INSERT INTO push_subscriptions (endpoint_hash, employee_id, user_id, endpoint, p256dh, auth_key, device, created_at, last_seen, fail_count)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
             ON DUPLICATE KEY UPDATE employee_id = VALUES(employee_id), user_id = VALUES(user_id), p256dh = VALUES(p256dh), auth_key = VALUES(auth_key), device = VALUES(device), last_seen = VALUES(last_seen), fail_count = 0"
        )->execute([sha1($endpoint), (int)$auth['employee_id'], (int)($auth['user_id'] ?? 0) ?: null, $endpoint, $p256dh, $authKey, $device, $now, $now]);
        // The phone replaced its subscription with this one: forget the old entry so it never
        // shows up later as a "failed" phone.
        $oldEp = trim((string)($in['old_endpoint'] ?? ''));
        if ($oldEp !== '' && $oldEp !== $endpoint) {
            $pdo->prepare("DELETE FROM push_subscriptions WHERE endpoint_hash = ? AND employee_id = ?")->execute([sha1($oldEp), (int)$auth['employee_id']]);
        }
        $n = $pdo->prepare("SELECT COUNT(*) FROM push_subscriptions WHERE employee_id = ?"); $n->execute([(int)$auth['employee_id']]);
        json_response(['message' => 'This phone will get punch-in reminders.', 'phones' => (int)$n->fetchColumn()]);
        break;
    }

    case 'push.unsubscribe': {
        $auth = require_auth();
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_push_table($pdo);
        $in = json_input();
        $endpoint = trim((string)($in['endpoint'] ?? ''));
        if ($endpoint !== '') $pdo->prepare("DELETE FROM push_subscriptions WHERE endpoint_hash = ?")->execute([sha1($endpoint)]);
        json_response(['message' => 'Removed.']);
        break;
    }

    case 'push.test': {
        // Send a test notification to one employee's phones (Admin/HR), or to your own.
        $auth = require_auth();
        $in = json_input();
        $empId = (int)($in['employee_id'] ?? 0);
        if ($empId && $empId !== (int)($auth['employee_id'] ?? 0)) require_role(['Admin', 'HR'], $auth);
        if (!$empId) $empId = (int)($auth['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'No employee to send to.'], 422);
        $tid = substr(preg_replace('/[^A-Za-z0-9]/', '', (string)($in['tid'] ?? '')), 0, 24);
        $testPayload = ['title' => 'HRMS test notification', 'body' => 'Phone reminders are working. You will be reminded here if you forget to punch in.', 'url' => 'attendance.html', 'tag' => 'hrms-test', 'tid' => $tid];
        // "This phone" mode: the page names its own subscription, so the answer is about that
        // one phone only (not mixed up with an old phone / another browser of the same person).
        $thisEp = trim((string)($in['endpoint'] ?? ''));
        if ($thisEp !== '' && $empId === (int)($auth['employee_id'] ?? 0)) {
            if (!ensure_push_table($pdo)) json_response(['error' => 'Could not create the push table.'], 500);
            $q = $pdo->prepare("SELECT * FROM push_subscriptions WHERE endpoint_hash = ? AND employee_id = ?");
            $q->execute([sha1($thisEp), $empId]);
            $row = $q->fetch();
            if (!$row) json_response(['error' => 'This phone is not saved on the server yet.', 'code' => 'not_saved'], 409);
            $r = push_deliver($pdo, $row, $testPayload);
            if ($r['ok']) {
                $pdo->prepare("UPDATE push_subscriptions SET last_sent = ?, fail_count = 0 WHERE endpoint_hash = ?")->execute([date('Y-m-d H:i:s'), $row['endpoint_hash']]);
                json_response(['message' => 'The push service accepted the notification for this phone.', 'sent' => 1, 'failed' => 0, 'status' => $r['status']]);
            }
            if ($r['gone']) {
                $pdo->prepare("DELETE FROM push_subscriptions WHERE endpoint_hash = ?")->execute([$row['endpoint_hash']]);
                push_mark_dead($pdo, (string)$row['endpoint_hash']);
                json_response(['error' => 'This phone\'s notification link has expired.', 'code' => 'gone', 'status' => $r['status']], 409);
            }
            $pdo->prepare("UPDATE push_subscriptions SET fail_count = fail_count + 1 WHERE endpoint_hash = ?")->execute([$row['endpoint_hash']]);
            json_response(['error' => $r['error'], 'code' => 'push_error', 'status' => $r['status']], 502);
        }
        [$sent, $failed, $err] = push_send_employee($pdo, $empId, $testPayload);
        if ($sent === 0) json_response(['error' => $failed ? $err : 'No phone has allowed notifications for this employee yet.'], 502);
        json_response(['message' => 'Sent to ' . $sent . ' phone' . ($sent === 1 ? '' : 's') . '.' . ($failed ? ' ' . $failed . ' failed: ' . $err : ''), 'sent' => $sent, 'failed' => $failed]);
        break;
    }

    case 'reminders.tick': {
        // The detached phone pass (fired by reminders_push_kick, or by a cron
        // URL). No login needed: it only does what would happen anyway, at
        // most once a minute. Keeps running even after the caller hangs up.
        ignore_user_abort(true);
        @set_time_limit(120);
        $rp = reminders_push_pass($pdo, isset($_GET['force']) || isset($_GET['bg']));
        try { ct_run($pdo, false); } catch (Throwable $e) {}        // Control Tower alerts + Message Doctor ride on the same cron / tick
        json_response($rp);
        break;
    }

    // ---------------- Penalty Management ----------------
    case 'penalties.rules': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_penalty_tables($pdo)) json_response(['error' => 'Could not create the penalty tables.'], 500);
        $rules = $pdo->query("SELECT * FROM penalty_rules ORDER BY FIELD(category,'common','customer_care','sales','dept','store'), department, name")->fetchAll();
        $used = [];
        foreach ($pdo->query("SELECT rule_id, COUNT(*) AS c FROM employee_penalties WHERE rule_id IS NOT NULL GROUP BY rule_id")->fetchAll() as $r) $used[(int)$r['rule_id']] = (int)$r['c'];
        foreach ($rules as &$r) {
            $r['rule_id'] = (int)$r['rule_id']; $r['amount'] = (float)$r['amount']; $r['active'] = (int)$r['active'];
            $r['grace_min'] = $r['grace_min'] !== null ? (int)$r['grace_min'] : null; $r['used'] = $used[$r['rule_id']] ?? 0;
            $r['ladder_on'] = (int)($r['ladder_on'] ?? 0); $r['ladder_inc'] = (float)($r['ladder_inc'] ?? 0); $r['ladder_reset'] = (string)($r['ladder_reset'] ?? 'month') === 'never' ? 'never' : 'month'; unset($r['ladder']);
        }
        unset($r);
        $depts = array_map(fn($r) => $r['department_name'], $pdo->query("SELECT department_name FROM departments ORDER BY department_name")->fetchAll());
        json_response(['rules' => $rules, 'departments' => $depts]);
        break;
    }

    case 'penalties.rule_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_penalty_tables($pdo)) json_response(['error' => 'Could not create the penalty tables.'], 500);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        $name = trim((string)($in['name'] ?? ''));
        if ($name === '') json_response(['error' => 'Penalty name is required.'], 422);
        $cat = (string)($in['category'] ?? 'common');
        if (!in_array($cat, ['common', 'customer_care', 'sales', 'dept', 'store'], true)) json_response(['error' => 'Bad category.'], 422);
        $dept = $cat === 'dept' ? trim((string)($in['department'] ?? '')) : '';
        if ($cat === 'dept' && $dept === '') json_response(['error' => 'Choose the department for this rule.'], 422);
        $trig = (string)($in['trigger_type'] ?? 'manual');
        if (!in_array($trig, ['manual', 'late_punch', 'short_hours', 'no_punch_out', 'rs_cp_rejected', 'rs_uniform', 'rs_cash', 'rs_task_late', 'rs_open_missed'], true)) json_response(['error' => 'Bad trigger.'], 422);
        $amount = round((float)($in['amount'] ?? 0), 2);
        if ($amount < 0 || $amount > 1000000) json_response(['error' => 'Amount must be between ₹0 and ₹10,00,000.'], 422);
        // "Increases each time": the amount is the 1st time; every next time adds ladder_inc
        $ladderOn = !empty($in['ladder_on']) ? 1 : 0;
        $ladderInc = round((float)($in['ladder_inc'] ?? 0), 2);
        if ($ladderOn) {
            if ($ladderInc <= 0 || $ladderInc > 1000000) json_response(['error' => 'Type how much it increases each time (more than ₹0).'], 422);
            if ($amount <= 0) json_response(['error' => 'Type the amount of the 1st time.'], 422);
        } else $ladderInc = 0;
        $ladderReset = (string)($in['ladder_reset'] ?? 'month') === 'never' ? 'never' : 'month';
        $grace = ($trig === 'manual' || $trig === 'no_punch_out' || strpos($trig, 'rs_') === 0 || !isset($in['grace_min']) || $in['grace_min'] === '' || $in['grace_min'] === null) ? null : max(0, min(240, (int)$in['grace_min']));
        $done = ($trig === 'late_punch' || $trig === 'no_punch_out') ? (string)($in['on_hours_done'] ?? 'keep') : 'keep';   // no_punch_out: remove = when the punch-out is added later
        if (!in_array($done, ['remove', 'reduce_50', 'keep'], true)) json_response(['error' => 'Bad option for completed hours.'], 422);
        $tpl = trim((string)($in['notify_text'] ?? ''));
        if ($tpl === '') $tpl = 'A penalty of {amount} has been applied to you for {rule}.';
        $tpl = mb_substr($tpl, 0, 255);
        $active = !isset($in['active']) || (int)$in['active'] ? 1 : 0;
        $now = date('Y-m-d H:i:s');
        if ($id) {
            $old = $pdo->prepare("SELECT active, active_since FROM penalty_rules WHERE rule_id = ?");
            $old->execute([$id]);
            $o = $old->fetch();
            if (!$o) json_response(['error' => 'Rule not found.'], 404);
            // Switched on now → only days from today onwards can be charged by it.
            $since = $active ? ((int)$o['active'] === 1 && $o['active_since'] ? $o['active_since'] : biz_today($pdo)) : $o['active_since'];
            $pdo->prepare("UPDATE penalty_rules SET name = ?, category = ?, department = ?, trigger_type = ?, amount = ?, grace_min = ?, on_hours_done = ?, notify_text = ?, active = ?, active_since = ?, ladder_on = ?, ladder_inc = ?, ladder_reset = ?, updated_at = ? WHERE rule_id = ?")
                ->execute([$name, $cat, $dept, $trig, $amount, $grace, $done, $tpl, $active, $since, $ladderOn, $ladderInc, $ladderReset, $now, $id]);
        } else {
            $pdo->prepare("INSERT INTO penalty_rules (name, category, department, trigger_type, amount, grace_min, on_hours_done, notify_text, active, active_since, ladder_on, ladder_inc, ladder_reset, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                ->execute([$name, $cat, $dept, $trig, $amount, $grace, $done, $tpl, $active, $active ? biz_today($pdo) : null, $ladderOn, $ladderInc, $ladderReset, $now, $now]);
            $id = (int)$pdo->lastInsertId();
        }
        json_response(['message' => 'Rule saved.', 'rule_id' => $id]);
        break;
    }

    case 'penalties.rule_toggle': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_penalty_tables($pdo);
        $in = json_input();
        $id = (int)($in['rule_id'] ?? 0);
        $on = !empty($in['active']) ? 1 : 0;
        // Switching a rule on starts it from today — nothing already past is charged.
        $pdo->prepare("UPDATE penalty_rules SET active = ?, active_since = CASE WHEN ? = 1 THEN ? ELSE active_since END, updated_at = ? WHERE rule_id = ?")
            ->execute([$on, $on, biz_today($pdo), date('Y-m-d H:i:s'), $id]);
        json_response(['message' => $on ? 'Rule switched on.' : 'Rule switched off.']);
        break;
    }

    case 'penalties.rule_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_penalty_tables($pdo);
        $id = (int)(json_input()['rule_id'] ?? 0);
        $c = $pdo->prepare("SELECT COUNT(*) FROM employee_penalties WHERE rule_id = ?");
        $c->execute([$id]);
        if ((int)$c->fetchColumn() > 0) json_response(['error' => 'This rule already has penalties in the history. Switch it off instead — the history stays.'], 409);
        $pdo->prepare("DELETE FROM penalty_rules WHERE rule_id = ?")->execute([$id]);
        json_response(['message' => 'Rule deleted.']);
        break;
    }

    case 'penalties.employees': {
        // Everyone a penalty can be written for, with what it will be taken from.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $rows = $pdo->query(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.monthly_salary, d.department_name
             FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id WHERE e.status != 'ex' ORDER BY e.full_name"
        )->fetchAll();
        foreach ($rows as &$r) {
            $r['employee_id'] = (int)$r['employee_id']; $r['monthly_salary'] = (float)$r['monthly_salary'];
            $r['pays_from'] = penalty_pays_from($r);
            $r['fixed_hours'] = $r['pays_from'] === 'salary' && $r['monthly_salary'] > 0 ? 1 : 0;
        }
        unset($r);
        json_response(['employees' => $rows]);
        break;
    }

    case 'penalties.apply': {
        // A penalty written by hand, for anyone, any time.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_penalty_tables($pdo)) json_response(['error' => 'Could not create the penalty tables.'], 500);
        $in = json_input();
        $empId = (int)($in['employee_id'] ?? 0);
        $emp = $empId ? penalty_employee($pdo, $empId) : null;
        if (!$emp) json_response(['error' => 'Choose an employee.'], 422);
        $title = trim((string)($in['title'] ?? ''));
        if ($title === '') json_response(['error' => 'Write what the penalty is for.'], 422);
        $amount = round((float)($in['amount'] ?? 0), 2);
        $date = trim((string)($in['date'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) $date = biz_today($pdo);
        // A saved rule with the same name carries its own notification wording (and its ladder).
        $rs = $pdo->prepare("SELECT * FROM penalty_rules WHERE LOWER(name) = LOWER(?) LIMIT 1");
        $rs->execute([$title]);
        $rule = $rs->fetch() ?: null;
        $step = $rule ? penalty_ladder_pick($pdo, $rule, $empId, $date) : null;        // "Increases each time": which time this is, and the step's amount
        if ($step && $amount <= 0) $amount = (float)$step['amount'];
        if ($amount <= 0 || $amount > 1000000) json_response(['error' => 'Enter an amount more than ₹0.'], 422);
        $notify = !isset($in['notify']) || !empty($in['notify']);
        $pid = penalty_create($pdo, $emp, $rule, $title, $date, $amount, 'manual', trim((string)($in['note'] ?? '')), (string)($auth['username'] ?? 'Admin'), null, $notify, $step);
        json_response(['message' => 'Penalty applied to ' . $emp['full_name'] . ($step ? ' (' . $step['label'] . ')' : '') . ($notify ? ' and they were notified.' : '.'), 'penalty_id' => $pid, 'deducted_from' => penalty_pays_from($emp), 'nth' => $step ? $step['nth'] : null]);
        break;
    }

    case 'penalties.next_step': {
        // GET employee_id, rule_id (or title), date → which time this would be for that employee and what the ladder pays (null = rule has no ladder)
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_penalty_tables($pdo)) json_response(['error' => 'Could not create the penalty tables.'], 500);
        $empId = (int)($_GET['employee_id'] ?? 0);
        $date = trim((string)($_GET['date'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) $date = biz_today($pdo);
        $rule = null;
        if (!empty($_GET['rule_id'])) { $q = $pdo->prepare("SELECT * FROM penalty_rules WHERE rule_id = ?"); $q->execute([(int)$_GET['rule_id']]); $rule = $q->fetch() ?: null; }
        elseif (trim((string)($_GET['title'] ?? '')) !== '') { $q = $pdo->prepare("SELECT * FROM penalty_rules WHERE LOWER(name) = LOWER(?) LIMIT 1"); $q->execute([trim((string)$_GET['title'])]); $rule = $q->fetch() ?: null; }
        $step = ($rule && $empId) ? penalty_ladder_pick($pdo, $rule, $empId, $date) : null;
        json_response(['step' => $step, 'amount' => $step ? $step['amount'] : ($rule ? (float)$rule['amount'] : null), 'ladder_on' => $rule ? (int)($rule['ladder_on'] ?? 0) : 0]);
        break;
    }

    case 'penalties.list': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_penalty_tables($pdo)) json_response(['error' => 'Could not create the penalty tables.'], 500);
        $month = (string)($_GET['month'] ?? date('Y-m'));
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $sql = "SELECT p.*, e.full_name, e.employee_code, d.department_name
                FROM employee_penalties p JOIN employees e ON e.employee_id = p.employee_id LEFT JOIN departments d ON d.department_id = e.department_id
                WHERE 1 = 1";
        $args = [];
        // History of one employee can cover every month (all=1, only with an employee picked); otherwise the picked month.
        if (!(!empty($_GET['all']) && !empty($_GET['employee_id']))) { $sql .= " AND p.penalty_date >= ? AND p.penalty_date <= ?"; array_push($args, $month . '-01', date('Y-m-t', strtotime($month . '-01'))); }
        foreach (['status' => 'p.status', 'source' => 'p.source', 'category' => 'p.category'] as $k => $col) {
            $v = trim((string)($_GET[$k] ?? ''));
            if ($v !== '') { $sql .= " AND $col = ?"; $args[] = $v; }
        }
        if (!empty($_GET['employee_id'])) { $sql .= " AND p.employee_id = ?"; $args[] = (int)$_GET['employee_id']; }
        $q = trim((string)($_GET['q'] ?? ''));
        if ($q !== '') { $sql .= " AND (e.full_name LIKE ? OR e.employee_code LIKE ? OR p.title LIKE ?)"; $like = '%' . $q . '%'; array_push($args, $like, $like, $like); }
        $sql .= " ORDER BY p.penalty_date DESC, p.penalty_id DESC LIMIT 1000";
        $st = $pdo->prepare($sql);
        $st->execute($args);
        $rows = $st->fetchAll();
        $stats = ['applied' => 0, 'total' => 0.0, 'salary' => 0.0, 'commission' => 0.0, 'removed' => 0, 'waived' => 0];
        foreach ($rows as &$r) {
            $r['penalty_id'] = (int)$r['penalty_id']; $r['employee_id'] = (int)$r['employee_id']; $r['amount'] = (float)$r['amount'];
            $r['orig_amount'] = $r['orig_amount'] !== null ? (float)$r['orig_amount'] : null;
            $r['nth'] = isset($r['nth']) && $r['nth'] !== null ? (int)$r['nth'] : null; $r['nth_label'] = $r['nth'] ? penalty_ordinal($r['nth']) . ' time' : '';
            if ($r['status'] === 'applied') { $stats['applied']++; $stats['total'] += $r['amount']; $stats[$r['deducted_from'] === 'commission' ? 'commission' : 'salary'] += $r['amount']; }
            elseif ($r['status'] === 'removed') $stats['removed']++;
            elseif ($r['status'] === 'waived') $stats['waived']++;
        }
        unset($r);
        json_response(['month' => $month, 'rows' => $rows, 'stats' => $stats]);
        break;
    }

    case 'penalties.waive': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_penalty_tables($pdo);
        $in = json_input();
        $id = (int)($in['penalty_id'] ?? 0);
        $why = trim((string)($in['reason'] ?? ''));
        $st = $pdo->prepare("SELECT * FROM employee_penalties WHERE penalty_id = ?");
        $st->execute([$id]);
        $p = $st->fetch();
        if (!$p) json_response(['error' => 'Penalty not found.'], 404);
        if ($p['status'] !== 'applied') json_response(['error' => 'This penalty is already ' . $p['status'] . '.'], 409);
        $pdo->prepare("UPDATE employee_penalties SET status = 'waived', resolved_by = ?, resolved_at = ?, resolve_note = ? WHERE penalty_id = ?")
            ->execute([(string)($auth['username'] ?? 'Admin'), date('Y-m-d H:i:s'), mb_substr($why, 0, 255), $id]);
        penalty_notify($pdo, (int)$p['employee_id'], $id, 'waived', 'Penalty waived', 'Your penalty of ' . penalty_inr((float)$p['amount']) . ' for ' . $p['title'] . ' has been waived.' . ($why !== '' ? ' ' . $why : ''));
        json_response(['message' => 'Penalty waived and the employee was told.']);
        break;
    }

    case 'penalties.run': {
        // "Run the check now" — the same pass that runs by itself every minute.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_penalty_tables($pdo);
        json_response(['result' => penalties_auto_pass($pdo, true)]);
        break;
    }

    case 'penalties.statement': {
        // Original → penalties → final, for every employee in a month: salary employees from the Salary page's
        // figure, Sales employees from the Commission figure.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_penalty_tables($pdo);
        $month = (string)($_GET['month'] ?? date('Y-m'));
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $rules = salary_rules_load($pdo);
        $rows = [];
        $emps = $pdo->query(
            "SELECT e.employee_id, e.full_name, e.employee_code, e.monthly_salary, d.department_name
             FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id
             WHERE e.status != 'ex' AND e.monthly_salary > 0 AND (d.department_name IS NULL OR d.department_name NOT LIKE '%sales%') ORDER BY e.full_name"
        )->fetchAll();
        foreach ($emps as $e) {
            $c = salary_calc($pdo, $e, $month, $rules);
            $rows[] = ['employee_id' => (int)$e['employee_id'], 'full_name' => $e['full_name'], 'employee_code' => $e['employee_code'], 'department' => $e['department_name'], 'paid_on' => 'salary',
                'original' => $c['earned'], 'penalty_total' => $c['penalty_total'], 'final' => $c['net_pay'], 'items' => $c['penalties']];
        }
        $pen = penalty_commission_map($pdo, $month);
        $byEmp = [];
        foreach (commission_rows_compute($pdo, $month, '') as $r) {
            $id = (int)$r['employee_id'];
            if (!isset($byEmp[$id])) $byEmp[$id] = ['employee_id' => $id, 'full_name' => $r['full_name'], 'employee_code' => $r['employee_code'], 'department' => 'Sales', 'paid_on' => 'commission', 'original' => 0.0];
            $byEmp[$id]['original'] += (float)$r['final_amount'];
        }
        foreach ($byEmp as $id => $r) {
            $t = (float)($pen[$id]['total'] ?? 0);
            $r['penalty_total'] = $t; $r['final'] = max(0, round($r['original'] - $t, 2)); $r['items'] = $pen[$id]['items'] ?? [];
            $rows[] = $r;
        }
        json_response(['month' => $month, 'rows' => $rows]);
        break;
    }

    // ---- the employee's own side (no module needed: everyone sees only their own) ----
    case 'my_penalties.list': {
        $auth = require_auth();
        $empId = (int)($auth['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if (!ensure_penalty_tables($pdo)) json_response(['penalties' => [], 'unread' => []]);
        $month = (string)($_GET['month'] ?? date('Y-m'));
        if (!preg_match('/^\d{4}-\d{2}$/', $month)) json_response(['error' => 'month must be YYYY-MM.'], 422);
        $st = $pdo->prepare("SELECT penalty_id, title, penalty_date, amount, orig_amount, deducted_from, status, source, note, resolve_note FROM employee_penalties WHERE employee_id = ? AND penalty_date >= ? AND penalty_date <= ? ORDER BY penalty_date DESC, penalty_id DESC");
        $st->execute([$empId, $month . '-01', date('Y-m-t', strtotime($month . '-01'))]);
        $rows = $st->fetchAll();
        foreach ($rows as &$r) { $r['penalty_id'] = (int)$r['penalty_id']; $r['amount'] = (float)$r['amount']; $r['orig_amount'] = $r['orig_amount'] !== null ? (float)$r['orig_amount'] : null; }
        unset($r);
        $un = $pdo->prepare("SELECT notif_id, kind, title, body, created_at FROM penalty_notifications WHERE employee_id = ? AND read_at IS NULL ORDER BY notif_id DESC LIMIT 20");
        $un->execute([$empId]);
        $unread = $un->fetchAll();
        foreach ($unread as &$u) $u['notif_id'] = (int)$u['notif_id'];
        unset($u);
        json_response(['month' => $month, 'penalties' => $rows, 'unread' => $unread]);
        break;
    }

    case 'my_penalties.read': {
        $auth = require_auth();
        $empId = (int)($auth['employee_id'] ?? 0);
        if (!$empId) json_response(['error' => 'Your login is not linked to an employee.'], 422);
        if (ensure_penalty_tables($pdo)) $pdo->prepare("UPDATE penalty_notifications SET read_at = ? WHERE employee_id = ? AND read_at IS NULL")->execute([date('Y-m-d H:i:s'), $empId]);
        json_response(['message' => 'ok']);
        break;
    }

    // ---------------- Retail shops ----------------
    case 'retail.shops': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $area = trim((string)($_GET['area'] ?? ''));
        $city = retail_city_get();
        $q = trim((string)($_GET['q'] ?? ''));
        $sql = "SELECT s.*, " . retail_city_sql($pdo, 's') . " AS city_name, e.full_name AS pinned_by_name FROM retail_shops s LEFT JOIN employees e ON e.employee_id = s.pinned_by WHERE 1=1";
        $args = [];
        if ($area !== '') { $sql .= " AND s.area = ?"; $args[] = $area; }
        if ($city !== '') { $sql .= " AND " . retail_city_sql($pdo, 's') . " = ?"; $args[] = $city; }
        $pick = retail_shop_ids($_GET['shop_ids'] ?? '');
        if ($pick) $sql .= " AND s.shop_id IN (" . implode(',', $pick) . ")";
        if ($q !== '') { $sql .= " AND (s.shop_name LIKE ? OR s.owner_name LIKE ? OR s.mobile LIKE ? OR s.address LIKE ?)"; $like = '%' . $q . '%'; array_push($args, $like, $like, $like, $like); }
        $sql .= " ORDER BY s.status = 'active' DESC, s.shop_name";
        $st = $pdo->prepare($sql); $st->execute($args);
        $shops = $st->fetchAll();
        $stats = retail_shop_stats($pdo, array_map(fn($r) => (int)$r['shop_id'], $shops));
        foreach ($shops as &$r) { $r['city'] = (string)$r['city_name']; unset($r['city_name']); $r['stats'] = $stats[(int)$r['shop_id']] ?? ['orders_count' => 0, 'qty' => 0, 'amount' => 0, 'display_qty' => 0, 'pending' => 0, 'last_date' => null, 'last_qty' => 0, 'last_total' => 0]; $r['lat'] = $r['lat'] !== null ? (float)$r['lat'] : null; $r['lng'] = $r['lng'] !== null ? (float)$r['lng'] : null; }
        unset($r);
        $ast = $pdo->prepare("SELECT DISTINCT area FROM retail_shops s WHERE area != ''" . ($city !== '' ? " AND " . retail_city_sql($pdo, 's') . " = ?" : "") . " ORDER BY area"); $ast->execute($city !== '' ? [$city] : []);
        $areas = array_map(fn($r) => $r['area'], $ast->fetchAll());
        $month = date('Y-m-01');
        $tot = $pdo->prepare("SELECT COUNT(*) AS n, COALESCE(SUM(CASE WHEN order_date >= ? THEN 1 ELSE 0 END),0) AS month_orders, COALESCE(SUM(CASE WHEN order_type='display' THEN qty ELSE 0 END),0) + (SELECT COALESCE(SUM(qty),0) FROM retail_display) AS display_qty, COALESCE(SUM(CASE WHEN payment='pending' THEN billed_total - paid_amount ELSE 0 END),0) AS pending FROM retail_orders");
        $tot->execute([$month]);
        $t = $tot->fetch();
        json_response(['shops' => $shops, 'areas' => $areas, 'totals' => ['shops' => count($shops), 'month_orders' => (int)$t['month_orders'], 'display_qty' => (int)$t['display_qty'], 'pending' => round(array_sum(array_map(fn($b) => max(0.0, $b), retail_ledger_balances($pdo, $city !== '' ? array_map(fn($r) => (int)$r['shop_id'], $shops) : null))), 2)], 'city' => $city, 'cities' => retail_cities_list($pdo), 'default_city' => retail_default_city($pdo)]);
        break;
    }

    case 'retail.shop': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_retail_tables($pdo);
        $id = (int)($_GET['id'] ?? 0);
        $st = $pdo->prepare("SELECT s.*, e.full_name AS pinned_by_name FROM retail_shops s LEFT JOIN employees e ON e.employee_id = s.pinned_by WHERE s.shop_id = ?");
        $st->execute([$id]);
        $shop = $st->fetch();
        if (!$shop) json_response(['error' => 'Shop not found.'], 404);
        $shop['lat'] = $shop['lat'] !== null ? (float)$shop['lat'] : null; $shop['lng'] = $shop['lng'] !== null ? (float)$shop['lng'] : null;
        if ((string)$shop['city'] === '') $shop['city'] = retail_default_city($pdo);
        $st = $pdo->prepare("SELECT o.*, e.full_name AS created_by_name, e.employee_code FROM retail_orders o LEFT JOIN employees e ON e.employee_id = o.created_by WHERE o.shop_id = ? ORDER BY o.order_date DESC, o.order_id DESC");
        $st->execute([$id]);
        $orders = $st->fetchAll();
        $items = [];
        if ($orders) {
            $in = implode(',', array_fill(0, count($orders), '?'));
            $st = $pdo->prepare("SELECT * FROM retail_order_items WHERE order_id IN ($in) ORDER BY item_id");
            $st->execute(array_map(fn($o) => (int)$o['order_id'], $orders));
            foreach ($st->fetchAll() as $it) $items[(int)$it['order_id']][] = ['item_id' => (int)$it['item_id'], 'product_name' => $it['product_name'], 'ml' => (string)($it['ml'] ?? ''), 'qty' => (int)$it['qty'], 'delivered' => (int)($it['delivered'] ?? 0), 'price' => (float)$it['price'], 'total' => (float)$it['total']];
        }
        $duesBy = retail_dues_load($pdo, array_map(fn($o) => (int)$o['order_id'], $orders));
        foreach ($orders as &$o) {
            $o['items'] = $items[(int)$o['order_id']] ?? [];
            $o['total'] = (float)$o['total']; $o['paid_amount'] = (float)$o['paid_amount']; $o['qty'] = (int)$o['qty'];
            $o['pay_mode'] = (string)($o['pay_mode'] ?? '');
            $o['dues'] = isset($duesBy[(int)$o['order_id']]) ? retail_dues_state($duesBy[(int)$o['order_id']], (float)($o['billed_total'] ?? $o['total']), $o['paid_amount']) : [];
            $o['delivered_qty'] = (int)($o['delivered_qty'] ?? 0); $o['delivered_total'] = (float)($o['delivered_total'] ?? 0);
            $o['billed_total'] = (float)($o['billed_total'] ?? $o['total']); $o['bill_delivered'] = (int)($o['bill_delivered'] ?? 0);
            $o['discount_type'] = (string)($o['discount_type'] ?? ''); $o['discount_value'] = (float)($o['discount_value'] ?? 0); $o['discount_amount'] = (float)($o['discount_amount'] ?? 0);
            $o['delivery'] = retail_delivery_status($o['qty'], $o['delivered_qty']);
        }
        unset($o);
        // What is on display at the shop right now: entries added by hand, and old Display orders (both minus returns).
        $display = retail_display_rows($pdo, $id);
        $shop['perfumes'] = retail_shop_perfumes_load($pdo, $id);
        $st = $pdo->prepare("SELECT v.*, e.full_name AS employee_name, e.employee_code FROM retail_visits v LEFT JOIN employees e ON e.employee_id = v.employee_id WHERE v.shop_id = ? ORDER BY v.visit_at DESC, v.visit_id DESC");
        $st->execute([$id]);
        $visits = [];
        foreach ($st->fetchAll() as $v) $visits[] = ['visit_id' => (int)$v['visit_id'], 'visit_at' => $v['visit_at'], 'photo' => $v['photo'], 'note' => $v['note'], 'employee_id' => $v['employee_id'] !== null ? (int)$v['employee_id'] : null, 'employee_name' => $v['employee_name'], 'employee_code' => $v['employee_code'], 'distance_m' => $v['distance_m'] !== null ? (int)$v['distance_m'] : null];
        $stats = retail_shop_stats($pdo, [$id]);
        $schedule = null;
        try {
            $L = retail_ledger_load($pdo, $id);
            if (isset($L['shops'][$id])) {
                $today = date('Y-m-d');
                $c = retail_ledger_calc($L['shops'][$id], $L['orders'][$id] ?? [], $L['pays'][$id] ?? [], $L['byOrder'], $L['byPay'], (float)($L['open'][$id] ?? 0), $today, false);
                $schedule = retail_pay_schedule($pdo, $c, $L['pays'][$id] ?? [], $today);
                $schedule['balance'] = $c['balance']; $schedule['overdue'] = $c['overdue']; $schedule['overdue_days'] = $c['overdue_days']; $schedule['on_account'] = $c['on_account']; $schedule['status'] = $c['status'];
            }
        } catch (Throwable $e) { $schedule = null; }
        json_response(['shop' => $shop, 'orders' => $orders, 'display' => $display, 'visits' => $visits, 'stats' => $stats[$id] ?? null, 'schedule' => $schedule]);
        break;
    }

    case 'retail.shop_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $id = (int)($in['shop_id'] ?? 0);
        $name = trim((string)($in['shop_name'] ?? ''));
        if ($name === '') json_response(['error' => 'Shop name is required.'], 422);
        $mobile = preg_replace('/[^\d+]/', '', (string)($in['mobile'] ?? ''));
        $lat = isset($in['lat']) && $in['lat'] !== '' && $in['lat'] !== null ? (float)$in['lat'] : null;
        $lng = isset($in['lng']) && $in['lng'] !== '' && $in['lng'] !== null ? (float)$in['lng'] : null;
        if (($lat === null) !== ($lng === null) || ($lat !== null && (abs($lat) > 90 || abs($lng) > 180))) json_response(['error' => 'Location is not valid.'], 422);
        $acc = isset($in['accuracy_m']) && $in['accuracy_m'] !== '' ? (int)$in['accuracy_m'] : null;
        $status = in_array((string)($in['status'] ?? ''), ['active', 'inactive'], true) ? (string)$in['status'] : 'active';
        $now = date('Y-m-d H:i:s');
        $vals = [$name, mb_substr(trim((string)($in['owner_name'] ?? '')), 0, 80), mb_substr($mobile, 0, 20), mb_substr(trim((string)($in['area'] ?? '')), 0, 60), mb_substr(trim((string)($in['address'] ?? '')), 0, 255), mb_substr(trim((string)($in['note'] ?? '')), 0, 255), $status];
        // The city: the one picked in the form; else (a pin was given) the city of the pin; else the shop keeps its city / gets the default city.
        $city = retail_city_ensure($pdo, $in['city'] ?? '');
        $cityFrom = $city !== '' ? 'picked' : '';
        if ($city === '' && $lat !== null) { $d = retail_city_detect($pdo, $lat, $lng); $city = $d['city']; $cityFrom = $city !== '' ? $d['source'] : ''; }
        if ($id) {
            $old = $pdo->prepare("SELECT lat, lng FROM retail_shops WHERE shop_id = ?"); $old->execute([$id]); $o = $old->fetch();
            if (!$o) json_response(['error' => 'Shop not found.'], 404);
            $moved = $lat !== null && ((string)$o['lat'] !== (string)$lat || (string)$o['lng'] !== (string)$lng);
            $pdo->prepare("UPDATE retail_shops SET shop_name = ?, owner_name = ?, mobile = ?, area = ?, address = ?, note = ?, status = ?, lat = ?, lng = ?, accuracy_m = ?, " . ($moved ? "pinned_by = ?, pinned_at = ?, " : "") . "updated_at = ? WHERE shop_id = ?")
                ->execute(array_merge($vals, [$lat, $lng, $acc], $moved ? [$auth['employee_id'] ?? null, $now] : [], [$now, $id]));
        } else {
            // A new shop is not added while the person adding it has overdue payments (an Admin can go on with a reason).
            $block = retail_shop_block($pdo, !empty($auth['employee_id']) ? (int)$auth['employee_id'] : null);
            $overrideNote = '';
            if ($block) {
                $why = mb_substr(trim((string)($in['override_reason'] ?? '')), 0, 200);
                if (($auth['role'] ?? '') === 'Admin' && $why !== '') $overrideNote = $why;
                else json_response(['error' => 'You cannot add a new shop yet - ' . count($block) . ' payment' . (count($block) === 1 ? ' is' : 's are') . ' overdue on your shops (' . number_format(array_sum(array_map(fn($b) => $b['amount'], $block))) . ' Rs).', 'blocked' => 1, 'items' => $block, 'can_override' => ($auth['role'] ?? '') === 'Admin'], 409);
            }
            $pdo->prepare("INSERT INTO retail_shops (shop_name, owner_name, mobile, area, address, note, status, lat, lng, accuracy_m, pinned_by, pinned_at, created_by, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                ->execute(array_merge($vals, [$lat, $lng, $acc, $lat !== null ? ($auth['employee_id'] ?? null) : null, $lat !== null ? $now : null, $auth['employee_id'] ?? null, $now]));
            $id = (int)$pdo->lastInsertId();
            if ($overrideNote !== '') $pdo->prepare("UPDATE retail_shops SET block_override = ? WHERE shop_id = ?")->execute([$overrideNote, $id]);
        }
        if (array_key_exists('perfumes', $in)) {
            $setId = (int)($in['perfume_set_id'] ?? 0);
            if ($setId) { $q = $pdo->prepare("SELECT COUNT(*) FROM retail_perfume_sets WHERE set_id = ?"); $q->execute([$setId]); if (!(int)$q->fetchColumn()) $setId = 0; }
            retail_shop_perfumes_save($pdo, $id, retail_perfume_list($in['perfumes']), $setId ?: null);
        }
        if (array_key_exists('opening_balance', $in)) {
            $ob = round((float)$in['opening_balance'], 2);
            $od = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['opening_date'] ?? '')) ? (string)$in['opening_date'] : null;
            $pdo->prepare("UPDATE retail_shops SET opening_balance = ?, opening_date = ? WHERE shop_id = ?")->execute([$ob, $ob != 0.0 ? $od : null, $id]);
            retail_reconcile_shop($pdo, $id);
        }
        if ($city === '') {
            $c0 = $pdo->prepare("SELECT city FROM retail_shops WHERE shop_id = ?"); $c0->execute([$id]);
            $city = (string)$c0->fetchColumn();
            if ($city === '') $city = retail_city_ensure($pdo, retail_default_city($pdo));
        }
        $pdo->prepare("UPDATE retail_shops SET city = ? WHERE shop_id = ?")->execute([$city, $id]);
        json_response(['message' => 'Shop saved.', 'shop_id' => $id, 'city' => $city, 'city_from' => $cityFrom]);
        break;
    }

    case 'retail.shop_pin': {
        // Save the phone's GPS position (or a pasted Maps link) as the shop's pin.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $in = json_input();
        $id = (int)($in['shop_id'] ?? 0);
        $lat = isset($in['lat']) && $in['lat'] !== '' ? (float)$in['lat'] : null; $lng = isset($in['lng']) && $in['lng'] !== '' ? (float)$in['lng'] : null;
        if ($lat === null && !empty($in['link'])) { $p = retail_parse_location((string)$in['link']); if ($p) { $lat = $p['lat']; $lng = $p['lng']; } }
        if ($lat === null || $lng === null || abs($lat) > 90 || abs($lng) > 180) json_response(['error' => 'No coordinates found — use "Pin my current location" or paste a Google Maps link.'], 422);
        $st = $pdo->prepare("UPDATE retail_shops SET lat = ?, lng = ?, accuracy_m = ?, pinned_by = ?, pinned_at = ?, updated_at = ? WHERE shop_id = ?");
        $st->execute([$lat, $lng, isset($in['accuracy_m']) ? (int)$in['accuracy_m'] : null, $auth['employee_id'] ?? null, date('Y-m-d H:i:s'), date('Y-m-d H:i:s'), $id]);
        if (!$st->rowCount() && !$id) json_response(['error' => 'Shop not found.'], 404);
        // The pin tells which city the shop is in.
        $d = retail_city_detect($pdo, $lat, $lng);
        if ($d['city'] !== '' && $id) $pdo->prepare("UPDATE retail_shops SET city = ? WHERE shop_id = ?")->execute([$d['city'], $id]);
        json_response(['message' => 'Location pinned.', 'lat' => $lat, 'lng' => $lng, 'city' => $d['city'], 'city_from' => $d['source']]);
        break;
    }

    case 'retail.parse_link': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $in = json_input();
        $p = retail_parse_location((string)($in['link'] ?? ($_GET['link'] ?? '')));
        if (!$p) json_response(['error' => 'Could not find coordinates in that link. In Google Maps, long-press the shop → copy the "21.19…, 72.79…" numbers, or use Share → copy link.'], 422);
        ensure_retail_tables($pdo);
        $d = retail_city_detect($pdo, (float)$p['lat'], (float)$p['lng']);
        json_response($p + ['city' => $d['city'], 'city_from' => $d['source']]);
        break;
    }

    case 'retail.geo_city': {
        // Which city is this pin in? (lat + lng, or a pasted Maps link) -> {city, source: known | map | ''}
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $lat = isset($in['lat']) && $in['lat'] !== '' ? (float)$in['lat'] : (isset($_GET['lat']) && $_GET['lat'] !== '' ? (float)$_GET['lat'] : null);
        $lng = isset($in['lng']) && $in['lng'] !== '' ? (float)$in['lng'] : (isset($_GET['lng']) && $_GET['lng'] !== '' ? (float)$_GET['lng'] : null);
        if ($lat === null && !empty($in['link'])) { $p = retail_parse_location((string)$in['link']); if ($p) { $lat = $p['lat']; $lng = $p['lng']; } }
        if ($lat === null || $lng === null) json_response(['error' => 'No coordinates found.'], 422);
        $d = retail_city_detect($pdo, $lat, $lng);
        json_response(['city' => $d['city'], 'source' => $d['source'], 'lat' => $lat, 'lng' => $lng]);
        break;
    }

    case 'retail.cities': {
        // Every city with its shop count (default city first), and the default city.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        json_response(['cities' => retail_cities_list($pdo), 'default_city' => retail_default_city($pdo)]);
        break;
    }

    case 'retail.city_save': {
        // Add a city ("name"), or rename one ("old_name" + "name": its shops and its stock move with it), or make it the default ("make_default": true).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $name = trim(preg_replace('/\s+/u', ' ', (string)($in['name'] ?? '')));
        if ($name === '' || mb_strlen($name) > 60) json_response(['error' => 'Enter the city name (up to 60 letters).'], 422);
        $old = trim((string)($in['old_name'] ?? ''));
        if ($old !== '') {
            $old = retail_city_canon($pdo, $old);
            if (mb_strtolower($old) === mb_strtolower($name) && $old === $name) json_response(['message' => 'City saved.', 'city' => $old]);
            $new = mb_strtolower($old) === mb_strtolower($name) ? $name : retail_city_canon($pdo, $name);
            if (mb_strtolower($old) !== mb_strtolower($name)) {
                $ex = $pdo->prepare("SELECT COUNT(*) FROM retail_cities WHERE name = ? AND name <> ?"); $ex->execute([$new, $old]);
                if ((int)$ex->fetchColumn()) json_response(['error' => $new . ' already exists. Move its shops there instead of renaming.'], 409);
            }
            $isDef = mb_strtolower(retail_default_city($pdo)) === mb_strtolower($old);
            $pdo->prepare("UPDATE retail_cities SET name = ? WHERE name = ?")->execute([$new, $old]);
            $pdo->prepare("UPDATE retail_shops SET city = ? WHERE city = ?")->execute([$new, $old]);
            $pdo->prepare("UPDATE retail_stock_log SET city = ? WHERE city = ?")->execute([$new, $old]);
            $pdo->prepare("UPDATE retail_stock_items SET city = ?, item_key = CONCAT(?, SUBSTRING(item_key, ?)) WHERE city = ?")->execute([$new, mb_strtolower($new), mb_strlen($old) + 1, $old]);
            $pdo->prepare("UPDATE retail_stock_alerts SET city = ?, item_key = IF(item_key = '', '', CONCAT(?, SUBSTRING(item_key, ?))) WHERE city = ?")->execute([$new, mb_strtolower($new), mb_strlen($old) + 1, $old]);
            if ($isDef) setting_set($pdo, 'retail_default_city', $new);
            $city = $new;
        } else {
            $city = retail_city_ensure($pdo, $name);
        }
        if (!empty($in['make_default'])) setting_set($pdo, 'retail_default_city', $city);
        json_response(['message' => 'City saved.', 'city' => $city, 'cities' => retail_cities_list($pdo), 'default_city' => retail_default_city($pdo)]);
        break;
    }

    case 'retail.city_delete': {
        // Remove a city from the list — only when no shop is in it and it holds no stock.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $name = retail_city_canon($pdo, json_input()['name'] ?? '');
        if ($name === '') json_response(['error' => 'Pick a city.'], 422);
        if (mb_strtolower($name) === mb_strtolower(retail_default_city($pdo))) json_response(['error' => $name . ' is the default city and cannot be removed.'], 409);
        $sc = retail_city_sql($pdo, 's'); $lc = retail_city_sql($pdo, 'l');
        $n = $pdo->prepare("SELECT COUNT(*) FROM retail_shops s WHERE $sc = ?"); $n->execute([$name]);
        if ((int)$n->fetchColumn()) json_response(['error' => $name . ' still has shops. Move them to another city first.'], 409);
        $n = $pdo->prepare("SELECT COUNT(*) FROM retail_stock_log l WHERE $lc = ?"); $n->execute([$name]);
        if ((int)$n->fetchColumn()) json_response(['error' => $name . ' still has inventory. Remove it first.'], 409);
        $pdo->prepare("DELETE FROM retail_cities WHERE name = ?")->execute([$name]);
        json_response(['message' => $name . ' removed.', 'cities' => retail_cities_list($pdo)]);
        break;
    }

    case 'retail.shop_delete': {
        // Admin only. Without "force" a shop that already has orders is kept
        // (marked inactive) so its history is not lost by accident; with
        // force it goes for good, together with its orders and photos.
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $in = json_input();
        $id = (int)($in['shop_id'] ?? 0);
        $force = !empty($in['force']);
        $st = $pdo->prepare("SELECT shop_name FROM retail_shops WHERE shop_id = ?"); $st->execute([$id]);
        $name = $st->fetchColumn();
        if ($name === false) json_response(['error' => 'Shop not found.'], 404);
        $n = $pdo->prepare("SELECT COUNT(*) FROM retail_orders WHERE shop_id = ?"); $n->execute([$id]);
        $orders = (int)$n->fetchColumn();
        $v = $pdo->prepare("SELECT COUNT(*) FROM retail_visits WHERE shop_id = ?"); $v->execute([$id]);
        $photos = (int)$v->fetchColumn();
        $pc = $pdo->prepare("SELECT COUNT(*) FROM retail_payments WHERE shop_id = ?"); $pc->execute([$id]);
        $pays = (int)$pc->fetchColumn();
        $ob = (float)$pdo->query("SELECT opening_balance FROM retail_shops WHERE shop_id = " . $id)->fetchColumn();

        if (($orders > 0 || $pays > 0 || abs($ob) > 0.004) && !$force) {
            $pdo->prepare("UPDATE retail_shops SET status = 'inactive', updated_at = ? WHERE shop_id = ?")->execute([date('Y-m-d H:i:s'), $id]);
            $hist = array_filter([$orders ? $orders . ' order' . ($orders === 1 ? '' : 's') : '', $pays ? $pays . ' payment' . ($pays === 1 ? '' : 's') : '', abs($ob) > 0.004 ? 'an opening balance' : '']);
            json_response(['message' => $name . ' has ' . implode(' and ', $hist) . ', so it was marked inactive instead of deleted. Delete it for good to remove its history too.', 'kept' => 1, 'orders' => $orders, 'photos' => $photos]);
        }

        $pdo->beginTransaction();
        try {
            // Photo files on disk go with the shop.
            $ph = $pdo->prepare("SELECT photo FROM retail_visits WHERE shop_id = ?"); $ph->execute([$id]);
            $files = array_column($ph->fetchAll(), 'photo');
            $oi = $pdo->prepare("SELECT order_id FROM retail_orders WHERE shop_id = ?"); $oi->execute([$id]);
            $oids = array_map('intval', array_column($oi->fetchAll(), 'order_id'));
            if ($oids) {
                $ph2 = implode(',', array_fill(0, count($oids), '?'));
                $pdo->prepare("DELETE FROM retail_order_items WHERE order_id IN ($ph2)")->execute($oids);
                $pdo->prepare("DELETE FROM retail_due_notices WHERE order_id IN ($ph2)")->execute($oids);
                $pdo->prepare("DELETE FROM retail_order_dues WHERE order_id IN ($ph2)")->execute($oids);
            }
            $pdo->prepare("DELETE FROM retail_payment_alloc WHERE payment_id IN (SELECT payment_id FROM retail_payments WHERE shop_id = ?)")->execute([$id]);
            $pdo->prepare("DELETE FROM retail_payments WHERE shop_id = ?")->execute([$id]);
            $pdo->prepare("DELETE FROM retail_orders WHERE shop_id = ?")->execute([$id]);
            $pdo->prepare("DELETE FROM retail_visits WHERE shop_id = ?")->execute([$id]);
            $pdo->prepare("DELETE FROM retail_display WHERE shop_id = ?")->execute([$id]);
            $pdo->prepare("DELETE FROM retail_shop_perfumes WHERE shop_id = ?")->execute([$id]);
            $pdo->prepare("DELETE FROM retail_shops WHERE shop_id = ?")->execute([$id]);
            $pdo->commit();
            foreach ($files as $f) { if ($f) { $abs = find_upload_on_account((string)$f); if ($abs && is_file($abs)) @unlink($abs); } }
        } catch (PDOException $e) {
            $pdo->rollBack();
            json_response(['error' => 'Could not delete the shop: ' . $e->getMessage()], 500);
        }
        $bits = [];
        if ($orders) $bits[] = $orders . ' order' . ($orders === 1 ? '' : 's');
        if ($photos) $bits[] = $photos . ' photo' . ($photos === 1 ? '' : 's');
        json_response(['message' => $name . ' deleted' . ($bits ? ' with ' . implode(' and ', $bits) : '') . '.', 'deleted' => 1]);
        break;
    }

    case 'retail.order_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $oid = (int)($in['order_id'] ?? 0);
        $shopId = (int)($in['shop_id'] ?? 0);
        $chk = $pdo->prepare("SELECT shop_id FROM retail_shops WHERE shop_id = ?"); $chk->execute([$shopId]);
        if (!$chk->fetchColumn()) json_response(['error' => 'Shop not found.'], 404);
        $type = in_array((string)($in['order_type'] ?? ''), ['display', 'sale', 'replacement', 'return'], true) ? (string)$in['order_type'] : 'sale';
        $payment = in_array((string)($in['payment'] ?? ''), ['pending', 'cash', 'upi', 'on_sale', 'free'], true) ? (string)$in['payment'] : 'pending';
        $payMode = in_array((string)($in['pay_mode'] ?? ''), ['cod', 'upi', 'cheque'], true) ? (string)$in['pay_mode'] : '';
        $status = in_array((string)($in['status'] ?? ''), ['delivered', 'ordered', 'returned'], true) ? (string)$in['status'] : 'delivered';
        $date = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['order_date'] ?? '')) ? (string)$in['order_date'] : date('Y-m-d');
        $items = []; $qty = 0; $total = 0.0; $delQty = 0; $delTotal = 0.0;
        foreach ((array)($in['items'] ?? []) as $it) {
            $nm = mb_substr(trim((string)($it['product_name'] ?? '')), 0, 160);
            $ml = mb_substr(trim((string)($it['ml'] ?? '')), 0, 20);
            if ($ml !== '' && preg_match('/^\d+(\.\d+)?$/', $ml)) $ml .= ' ml';
            $q = (int)($it['qty'] ?? 0); $pr = (float)($it['price'] ?? 0);
            if ($nm === '' || $q <= 0) continue;
            // Delivered defaults to the full quantity when the field is left empty.
            $d = array_key_exists('delivered', $it) && $it['delivered'] !== '' && $it['delivered'] !== null ? (int)$it['delivered'] : $q;
            $d = max(0, min($d, $q));
            $items[] = [$nm, $ml, $q, $d, $pr, round($q * $pr, 2)];
            $qty += $q; $total += $q * $pr; $delQty += $d; $delTotal += $d * $pr;
        }
        if (!$items) json_response(['error' => 'Add at least one perfume line (name and quantity).'], 422);
        // Retail Inventory: a Sale / Display / Replacement order cannot take more pieces than are in stock. Admin may save anyway ("allow_short").
        $short = retail_stock_shortage($pdo, $oid, $type, $items, $shopId);
        if ($short) {
            $isAdminUser = ($auth['role'] ?? '') === 'Admin';
            if (!$isAdminUser || empty($in['allow_short'])) {
                json_response(['error' => 'Not enough stock: ' . implode(', ', array_map(fn($x) => trim($x['product_name'] . ' ' . $x['ml_text']) . ' (need ' . $x['need'] . ', have ' . $x['have'] . ')', $short)) . '.', 'short' => $short, 'can_override' => $isAdminUser], 422);
            }
        }
        $billDelivered = !empty($in['bill_delivered']) ? 1 : 0;
        $discType = in_array((string)($in['discount_type'] ?? ''), ['pct', 'amt'], true) ? (string)$in['discount_type'] : '';
        $discVal = max(0.0, round((float)($in['discount_value'] ?? 0), 2));
        if ($discType === 'pct') $discVal = min($discVal, 100.0);
        $discAmt = retail_discount_amount($billDelivered ? $delTotal : $total, $discType, $discVal);
        if ($discAmt <= 0) { $discType = ''; $discVal = 0.0; }
        $billed = ($billDelivered ? $delTotal : $total) - $discAmt;
        $paid = $payment === 'pending' ? (float)($in['paid_amount'] ?? 0) : ($payment === 'on_sale' || $payment === 'free' ? 0 : round($billed, 2));
        if ($payment === 'pending' && $paid >= $billed && $billed > 0) $payment = $payMode === 'upi' ? 'upi' : 'cash';
        $dueDate = $payment === 'pending' && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['due_date'] ?? '')) ? (string)$in['due_date'] : null;
        // Several payment due dates (the order form sends "dues"); an older page sends one "due_date".
        $useDues = array_key_exists('dues', $in); $dues = [];
        if ($useDues && $payment === 'pending') {
            [$dues, $dueErr] = retail_dues_clean($in['dues'], round($billed, 2), round($paid, 2));
            if ($dueErr !== '') json_response(['error' => $dueErr], 422);
            $dueDate = $dues ? $dues[0]['due_date'] : null;
        } elseif ($useDues) $dueDate = null;
        $status = retail_delivery_status($qty, $delQty);
        $now = date('Y-m-d H:i:s');
        $isNew = !$oid;
        $pdo->beginTransaction();
        try {
            if ($oid) {
                $pdo->prepare("UPDATE retail_orders SET shop_id = ?, order_type = ?, order_date = ?, qty = ?, delivered_qty = ?, total = ?, delivered_total = ?, billed_total = ?, bill_delivered = ?, discount_type = ?, discount_value = ?, discount_amount = ?, payment = ?, pay_mode = ?, paid_amount = ?, due_date = ?, status = ?, note = ?, updated_at = ? WHERE order_id = ?")
                    ->execute([$shopId, $type, $date, $qty, $delQty, round($total, 2), round($delTotal, 2), round($billed, 2), $billDelivered, $discType, $discVal, $discAmt, $payment, $payMode, $paid, $dueDate, $status, mb_substr(trim((string)($in['note'] ?? '')), 0, 255), $now, $oid]);
                $pdo->prepare("DELETE FROM retail_order_items WHERE order_id = ?")->execute([$oid]);
                $no = (string)$pdo->query("SELECT order_no FROM retail_orders WHERE order_id = " . $oid)->fetchColumn();
            } else {
                $no = retail_next_order_no($pdo);
                $pdo->prepare("INSERT INTO retail_orders (shop_id, order_no, order_type, order_date, qty, delivered_qty, total, delivered_total, billed_total, bill_delivered, discount_type, discount_value, discount_amount, payment, pay_mode, paid_amount, due_date, status, note, created_by, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
                    ->execute([$shopId, $no, $type, $date, $qty, $delQty, round($total, 2), round($delTotal, 2), round($billed, 2), $billDelivered, $discType, $discVal, $discAmt, $payment, $payMode, $paid, $dueDate, $status, mb_substr(trim((string)($in['note'] ?? '')), 0, 255), $auth['employee_id'] ?? null, $now]);
                $oid = (int)$pdo->lastInsertId();
            }
            $ins = $pdo->prepare("INSERT INTO retail_order_items (order_id, product_name, ml, qty, delivered, price, total) VALUES (?, ?, ?, ?, ?, ?, ?)");
            foreach ($items as $it) $ins->execute([$oid, $it[0], $it[1], $it[2], $it[3], $it[4], $it[5]]);
            if ($useDues) {
                $pdo->prepare("DELETE FROM retail_order_dues WHERE order_id = ?")->execute([$oid]);
                $insD = $pdo->prepare("INSERT INTO retail_order_dues (order_id, due_date, amount) VALUES (?, ?, ?)");
                foreach ($dues as $d) $insD->execute([$oid, $d['due_date'], $d['amount']]);
            }
            $pdo->commit();
        } catch (PDOException $e) { $pdo->rollBack(); json_response(['error' => 'Could not save the order: ' . $e->getMessage()], 500); }
        try { retail_order_apply_paid($pdo, $oid, $shopId, $paid, $payment, $isNew ? $date : date('Y-m-d'), $auth['employee_id'] ?? null, $payMode); retail_order_sync_due($pdo, $oid); }
        catch (PDOException $e) { json_response(['error' => 'The order was saved but the ledger could not be updated: ' . $e->getMessage()], 500); }
        retail_stock_after_order($pdo, $no, $isNew, $type, $items, $shopId, (string)($auth['username'] ?? ''));
        json_response(['message' => 'Order ' . $no . ' saved.' . ($delQty < $qty ? ' ' . ($qty - $delQty) . ' pcs still to deliver.' : ''), 'order_id' => $oid, 'order_no' => $no, 'qty' => $qty, 'delivered_qty' => $delQty, 'total' => round($total, 2), 'billed_total' => round($billed, 2)]);
        break;
    }

    // ---------------- Retail shops: daily visit plan (Done / Pending) ----------------
    case 'retail.visit_plan': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        json_response(retail_visit_day($pdo, retail_visit_date($_GET['date'] ?? '', date('Y-m-d'))));
        break;
    }

    // retail.visit_plan_done — multipart: plan_id, photo (taken now), note, lat, lng, accuracy_m. The photo is the proof: without it a visit cannot be completed.
    case 'retail.visit_plan_done': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        ensure_retail_visit_approval_columns($pdo);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        $pid = (int)($_POST['plan_id'] ?? 0);
        $st = $pdo->prepare("SELECT plan_id, plan_date, shop_id, status FROM retail_visit_plan WHERE plan_id = ?"); $st->execute([$pid]); $plan = $st->fetch();
        if (!$plan) json_response(['error' => 'That visit is no longer in the plan.'], 404);
        if (!isset($_FILES['photo']) || (int)($_FILES['photo']['error'] ?? 1) !== 0 || (int)($_FILES['photo']['size'] ?? 0) <= 0) json_response(['error' => 'Take a photo at the shop to complete the visit.'], 422);
        $shopId = (int)$plan['shop_id'];
        $sq = $pdo->prepare("SELECT shop_id, lat, lng FROM retail_shops WHERE shop_id = ?"); $sq->execute([$shopId]); $shop = $sq->fetch();
        if (!$shop) json_response(['error' => 'Shop not found.'], 404);
        [$path, $err] = retail_save_photo($_FILES['photo'], $shopId);
        if ($path === null) json_response(['error' => $err], 422);
        $lat = isset($_POST['lat']) && $_POST['lat'] !== '' ? (float)$_POST['lat'] : null; $lng = isset($_POST['lng']) && $_POST['lng'] !== '' ? (float)$_POST['lng'] : null;
        $dist = ($lat !== null && $lng !== null && $shop['lat'] !== null) ? (int)round(geo_distance_m($lat, $lng, (float)$shop['lat'], (float)$shop['lng'])) : null;
        $now = date('Y-m-d H:i:s');
        $note = mb_substr(trim((string)($_POST['note'] ?? '')), 0, 255);
        $pdo->prepare("INSERT INTO retail_visits (shop_id, employee_id, visit_at, photo, note, lat, lng, distance_m) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
            ->execute([$shopId, $auth['employee_id'] ?? null, $now, $path, $note, $lat, $lng, $dist]);
        $vid = (int)$pdo->lastInsertId();
        if ($shop['lat'] === null && $lat !== null && $lng !== null && abs($lat) <= 90 && abs($lng) <= 180) {
            $pdo->prepare("UPDATE retail_shops SET lat = ?, lng = ?, accuracy_m = ?, pinned_by = ?, pinned_at = ?, updated_at = ? WHERE shop_id = ?")
                ->execute([$lat, $lng, isset($_POST['accuracy_m']) ? (int)$_POST['accuracy_m'] : null, $auth['employee_id'] ?? null, $now, $now, $shopId]);
        }
        $pdo->prepare("UPDATE retail_visit_plan SET status = 'done', done_at = ?, done_by = ?, note = ?, approval = 'waiting', visit_id = ?, approved_by = NULL, approved_name = '', approved_at = NULL, reject_note = '', updated_at = ? WHERE plan_id = ?")
            ->execute([$now, $auth['employee_id'] ?? null, $note, $vid, $now, $pid]);
        json_response(['message' => 'Visit done — waiting for approval.', 'visit_id' => $vid, 'photo' => $path, 'distance_m' => $dist] + retail_visit_day($pdo, substr((string)$plan['plan_date'], 0, 10)));
        break;
    }

    // retail.visit_plan_approve — POST {plan_id, decision: approved | rejected, note}. Only roles with the 'visit_approval' permission (Admin always).
    case 'retail.visit_plan_approve': {
        $auth = require_auth();
        if (!retail_visit_can_approve($auth)) json_response(['error' => 'You do not have the Retail Visit Approval permission.'], 403);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        ensure_retail_visit_approval_columns($pdo);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        $in = json_input();
        $pid = (int)($in['plan_id'] ?? 0);
        $dec = strtolower(trim((string)($in['decision'] ?? '')));
        if (!in_array($dec, ['approved', 'rejected'], true)) json_response(['error' => 'Decision must be approved or rejected.'], 422);
        $st = $pdo->prepare("SELECT plan_id, plan_date, status, approval FROM retail_visit_plan WHERE plan_id = ?"); $st->execute([$pid]); $plan = $st->fetch();
        if (!$plan) json_response(['error' => 'That visit is no longer in the plan.'], 404);
        if ((string)$plan['status'] !== 'done') json_response(['error' => 'This visit is not marked done yet.'], 422);
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 255);
        if ($dec === 'rejected' && $note === '') json_response(['error' => 'Write why it is rejected (the salesman sees it).'], 422);
        $now = date('Y-m-d H:i:s');
        $who = (string)(!empty($auth['employee_id']) ? (employee_names_by_id($pdo)[(int)$auth['employee_id']] ?? $auth['username']) : ($auth['username'] ?? ''));   // name kept even when the login has no employee record
        if ($dec === 'approved') {
            $pdo->prepare("UPDATE retail_visit_plan SET approval = 'approved', approved_by = ?, approved_name = ?, approved_at = ?, reject_note = '', updated_at = ? WHERE plan_id = ?")->execute([$auth['employee_id'] ?? null, mb_substr($who, 0, 100), $now, $now, $pid]);
        } else {
            // rejected: back to Pending — a new photo is needed; the old photo stays in the shop's Display photos
            $pdo->prepare("UPDATE retail_visit_plan SET status = 'pending', done_at = NULL, done_by = NULL, approval = 'rejected', approved_by = ?, approved_name = ?, approved_at = ?, reject_note = ?, updated_at = ? WHERE plan_id = ?")->execute([$auth['employee_id'] ?? null, mb_substr($who, 0, 100), $now, $note, $now, $pid]);
        }
        json_response(['message' => $dec === 'approved' ? 'Visit approved.' : 'Visit rejected — it is pending again.'] + retail_visit_day($pdo, substr((string)$plan['plan_date'], 0, 10)));
        break;
    }

    case 'retail.visit_plan_save': {
        // The shops to visit on a day: new ones are added as Pending, unticked ones are taken off, the rest keep their status.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $date = retail_visit_date($in['date'] ?? '', date('Y-m-d'));
        $want = retail_shop_ids(implode(',', array_map('intval', is_array($in['shop_ids'] ?? null) ? $in['shop_ids'] : [])));
        if ($want) {
            $q = $pdo->query("SELECT shop_id FROM retail_shops WHERE shop_id IN (" . implode(',', $want) . ")");
            $want = array_values(array_map('intval', $q->fetchAll(PDO::FETCH_COLUMN)));
        }
        $now = date('Y-m-d H:i:s');
        $have = $pdo->prepare("SELECT shop_id FROM retail_visit_plan WHERE plan_date = ?"); $have->execute([$date]);
        $have = array_map('intval', $have->fetchAll(PDO::FETCH_COLUMN));
        $pdo->beginTransaction();
        try {
            foreach (array_diff($have, $want) as $sid) $pdo->prepare("DELETE FROM retail_visit_plan WHERE plan_date = ? AND shop_id = ?")->execute([$date, $sid]);
            $ins = $pdo->prepare("INSERT INTO retail_visit_plan (plan_date, shop_id, status, created_by, created_at) VALUES (?, ?, 'pending', ?, ?)");
            foreach (array_diff($want, $have) as $sid) $ins->execute([$date, $sid, $auth['employee_id'] ?? null, $now]);
            $pdo->commit();
        } catch (PDOException $e) { $pdo->rollBack(); json_response(['error' => 'Could not save the plan: ' . $e->getMessage()], 500); }
        $d = retail_visit_day($pdo, $date);
        json_response(['message' => $d['counts']['total'] . ' shop' . ($d['counts']['total'] === 1 ? '' : 's') . ' planned for ' . date('d M', strtotime($date)) . '.'] + $d);
        break;
    }

    case 'retail.visit_plan_mark': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        ensure_retail_visit_approval_columns($pdo);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        $in = json_input();
        $pid = (int)($in['plan_id'] ?? 0); $done = (string)($in['status'] ?? '') === 'done';
        if ($done) json_response(['error' => 'Take a photo at the shop to complete the visit (tap "Mark visit done" and use the camera).'], 422);   // a visit is completed only with a new photo: retail.visit_plan_done
        $st = $pdo->prepare("SELECT plan_date FROM retail_visit_plan WHERE plan_id = ?"); $st->execute([$pid]); $date = $st->fetchColumn();
        if (!$date) json_response(['error' => 'That visit is no longer in the plan.'], 404);
        $note = array_key_exists('note', $in) ? mb_substr(trim((string)$in['note']), 0, 255) : null;
        // back to pending (undo): the approval state is cleared, the photo stays in the shop's Display photos
        $pdo->prepare("UPDATE retail_visit_plan SET status = 'pending', done_at = NULL, done_by = NULL, approval = '', visit_id = NULL, approved_by = NULL, approved_name = '', approved_at = NULL, reject_note = '', " . ($note !== null ? "note = ?, " : "") . "updated_at = ? WHERE plan_id = ?")
            ->execute(array_merge($note !== null ? [$note] : [], [date('Y-m-d H:i:s'), $pid]));
        json_response(['message' => $done ? 'Marked as visited.' : 'Marked as pending.'] + retail_visit_day($pdo, substr((string)$date, 0, 10)));
        break;
    }

    case 'retail.visit_plan_move': {
        // Pending visits go to another day (tomorrow by default). A shop already planned there is not added twice.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $ids = retail_shop_ids(implode(',', array_map('intval', is_array($in['plan_ids'] ?? null) ? $in['plan_ids'] : [])));
        $from = retail_visit_date($in['date'] ?? '', date('Y-m-d'));
        $to = retail_visit_date($in['to_date'] ?? '', date('Y-m-d', strtotime($from . ' +1 day')));
        if ($to === $from) json_response(['error' => 'Pick a different day.'], 422);
        $moved = 0;
        foreach ($ids as $pid) {
            $st = $pdo->prepare("SELECT shop_id, status FROM retail_visit_plan WHERE plan_id = ? AND plan_date = ?"); $st->execute([$pid, $from]); $r = $st->fetch();
            if (!$r || (string)$r['status'] === 'done') continue;
            $ex = $pdo->prepare("SELECT COUNT(*) FROM retail_visit_plan WHERE plan_date = ? AND shop_id = ?"); $ex->execute([$to, (int)$r['shop_id']]);
            if ((int)$ex->fetchColumn() > 0) $pdo->prepare("DELETE FROM retail_visit_plan WHERE plan_id = ?")->execute([$pid]);
            else $pdo->prepare("UPDATE retail_visit_plan SET plan_date = ?, updated_at = ? WHERE plan_id = ?")->execute([$to, date('Y-m-d H:i:s'), $pid]);
            $moved++;
        }
        json_response(['message' => $moved . ' shop' . ($moved === 1 ? '' : 's') . ' moved to ' . date('d M', strtotime($to)) . '.', 'moved' => $moved] + retail_visit_day($pdo, $from));
        break;
    }

    case 'retail.visit_plan_remove': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        $GLOBALS['RETAIL_VISIT_AUTH'] = $auth;
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $pid = (int)(json_input()['plan_id'] ?? 0);
        $st = $pdo->prepare("SELECT plan_date FROM retail_visit_plan WHERE plan_id = ?"); $st->execute([$pid]); $date = $st->fetchColumn();
        if (!$date) json_response(['error' => 'That visit is no longer in the plan.'], 404);
        $pdo->prepare("DELETE FROM retail_visit_plan WHERE plan_id = ?")->execute([$pid]);
        json_response(['message' => 'Removed from the plan.'] + retail_visit_day($pdo, substr((string)$date, 0, 10)));
        break;
    }

    case 'retail.visit_history': {
        // Past visits, day by day, between two dates (From - To). Optional: shop_ids (several parties), status (done / pending).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $today = date('Y-m-d');
        $to = retail_visit_date($_GET['to'] ?? '', $today);
        $from = retail_visit_date($_GET['from'] ?? '', date('Y-m-d', strtotime($to . ' -29 days')));
        if ($from > $to) { $t = $from; $from = $to; $to = $t; }
        if (strtotime($to) - strtotime($from) > 366 * 86400) $from = date('Y-m-d', strtotime($to . ' -366 days'));
        $status = (string)($_GET['status'] ?? '');
        $rows = retail_visit_rows($pdo, $from, $to, retail_shop_ids($_GET['shop_ids'] ?? ''), $status, retail_city_get());
        $days = []; $tot = ['planned' => 0, 'done' => 0, 'pending' => 0, 'shops' => []];
        foreach ($rows as $r) {
            $d = $r['date'];
            if (!isset($days[$d])) $days[$d] = ['date' => $d, 'total' => 0, 'done' => 0, 'pending' => 0, 'rows' => []];
            $days[$d]['total']++; $days[$d][$r['status'] === 'done' ? 'done' : 'pending']++; $days[$d]['rows'][] = $r;
            $tot['planned']++; $tot[$r['status'] === 'done' ? 'done' : 'pending']++; $tot['shops'][$r['shop_id']] = 1;
        }
        json_response(['from' => $from, 'to' => $to, 'today' => $today, 'days' => array_values($days),
            'totals' => ['days' => count($days), 'planned' => $tot['planned'], 'done' => $tot['done'], 'pending' => $tot['pending'], 'shops' => count($tot['shops']), 'pct' => $tot['planned'] ? (int)round($tot['done'] * 100 / $tot['planned']) : 0]]);
        break;
    }

    case 'retail.order_pay': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $in = json_input();
        $oid = (int)($in['order_id'] ?? 0);
        $payment = in_array((string)($in['payment'] ?? ''), ['pending', 'cash', 'upi', 'on_sale', 'free'], true) ? (string)$in['payment'] : 'cash';
        $payMode = in_array((string)($in['pay_mode'] ?? ''), ['cod', 'upi', 'cheque'], true) ? (string)$in['pay_mode'] : '';
        if ($payMode === 'upi' && $payment === 'cash') $payment = 'upi';
        if ($payMode !== 'upi' && $payMode !== '' && $payment === 'upi') $payment = 'cash';
        $st = $pdo->prepare("SELECT shop_id, billed_total, paid_amount FROM retail_orders WHERE order_id = ?"); $st->execute([$oid]); $o = $st->fetch();
        if (!$o) json_response(['error' => 'Order not found.'], 404);
        $paid = isset($in['paid_amount']) && $in['paid_amount'] !== '' ? (float)$in['paid_amount'] : (float)$o['billed_total'];
        if ($payment === 'pending' && $paid >= (float)$o['billed_total'] && (float)$o['billed_total'] > 0) $payment = $payMode === 'upi' ? 'upi' : 'cash';
        if ($payment === 'on_sale' || $payment === 'free') $paid = 0;
        // Due date: dropped once nothing is pending any more; kept as it is unless the page sends one.
        $dueSql = ''; $dueArg = [];
        $hasDues = (int)$pdo->query("SELECT COUNT(*) FROM retail_order_dues WHERE order_id = " . $oid)->fetchColumn() > 0;
        // The payment box sends the due dates (date + amount, one reminder each) the same way the order form does.
        $newDues = null;
        if ($payment === 'pending' && isset($in['dues']) && is_array($in['dues'])) {
            [$newDues, $dueErr] = retail_dues_clean($in['dues'], round((float)$o['billed_total'], 2), round($paid, 2));
            if ($dueErr !== '') json_response(['error' => $dueErr], 422);
        }
        if ($payment !== 'pending') $dueSql = ', due_date = NULL';
        elseif ($newDues !== null) { $dueSql = ', due_date = ?'; $dueArg = [$newDues ? $newDues[0]['due_date'] : null]; }
        elseif (!$hasDues && array_key_exists('due_date', $in)) { $dueSql = ', due_date = ?'; $dueArg = [preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$in['due_date']) ? (string)$in['due_date'] : null]; }
        $modeSql = $payMode !== '' ? ', pay_mode = ?' : ''; $modeArg = $payMode !== '' ? [$payMode] : [];
        $pdo->prepare("UPDATE retail_orders SET payment = ?, paid_amount = ?, updated_at = ?" . $dueSql . $modeSql . " WHERE order_id = ?")->execute(array_merge([$payment, $paid, date('Y-m-d H:i:s')], $dueArg, $modeArg, [$oid]));
        if ($newDues !== null || $payment !== 'pending') {
            $pdo->prepare("DELETE FROM retail_order_dues WHERE order_id = ?")->execute([$oid]);
            if ($newDues) { $insD = $pdo->prepare("INSERT INTO retail_order_dues (order_id, due_date, amount) VALUES (?, ?, ?)"); foreach ($newDues as $d) $insD->execute([$oid, $d['due_date'], $d['amount']]); }
        }
        try { retail_order_apply_paid($pdo, $oid, (int)$o['shop_id'], $paid, $payment, preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['pay_date'] ?? '')) && (string)$in['pay_date'] <= date('Y-m-d') ? (string)$in['pay_date'] : date('Y-m-d'), $auth['employee_id'] ?? null, $payMode); }
        catch (PDOException $e) { json_response(['error' => 'The payment was saved but the ledger could not be updated: ' . $e->getMessage()], 500); }
        retail_order_sync_due($pdo, $oid);
        json_response(['message' => 'Payment updated.']);
        break;
    }

    case 'retail.order_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $oid = (int)(json_input()['order_id'] ?? 0);
        $sidDel = (int)$pdo->query("SELECT shop_id FROM retail_orders WHERE order_id = " . $oid)->fetchColumn();
        retail_alloc_release($pdo, $oid, null, true);
        $pdo->prepare("DELETE FROM retail_order_items WHERE order_id = ?")->execute([$oid]);
        $pdo->prepare("DELETE FROM retail_due_notices WHERE order_id = ?")->execute([$oid]);
        $pdo->prepare("DELETE FROM retail_order_dues WHERE order_id = ?")->execute([$oid]);
        $pdo->prepare("DELETE FROM retail_orders WHERE order_id = ?")->execute([$oid]);
        if ($sidDel) retail_reconcile_shop($pdo, $sidDel);
        retail_stock_check($pdo);      // the pieces of the deleted order are back in stock
        json_response(['message' => 'Order deleted.']);
        break;
    }

    // ---------------- Retail inventory ----------------
    case 'retail.stock': {
        // ?city=Surat = that city's stock; no city = every city together (each perfume summed, with a per-city breakdown).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the inventory tables.'], 500);
        $city = retail_city_get();
        if ($city !== '') $city = retail_city_canon($pdo, $city);
        $forShop = (int)($_GET['shop_id'] ?? 0);        // the order form asks for the stock of the city that shop is in
        if ($forShop > 0) $city = retail_shop_city($pdo, $forShop);
        $rows = retail_stock_rows($pdo, $city);
        $sumOf = function (array $rs): array {
            $s = ['pieces' => 0, 'tracked' => count($rs), 'perfumes' => count(array_unique(array_map(fn($r) => mb_strtolower($r['product_name']), $rs))), 'low' => 0, 'out' => 0];
            foreach ($rs as $r) { $s['pieces'] += max(0, $r['on_hand']); if ($r['state'] === 'low') $s['low']++; elseif ($r['state'] === 'out') $s['out']++; }
            return $s;
        };
        $by = [];
        foreach (retail_cities_list($pdo) as $c) { $s = $sumOf(retail_stock_city_rows($pdo, $c['name'])); $by[] = ['city' => $c['name'], 'shops' => $c['shops']] + $s; }
        json_response(['items' => $rows, 'city' => $city, 'summary' => $sumOf($rows), 'by_city' => $by, 'cities' => array_map(fn($c) => $c['name'], retail_cities_list($pdo)), 'default_city' => retail_default_city($pdo), 'default_limit' => retail_stock_default_limit($pdo), 'since' => retail_stock_start($pdo), 'can_override' => ($auth['role'] ?? '') === 'Admin']);
        break;
    }

    case 'retail.stock_add': {
        // Stock in ("qty") or a physical count ("set_to": the new on-hand number; the difference is logged as an adjustment) — always for ONE city.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the inventory tables.'], 500);
        $in = json_input();
        $city = retail_city_ensure($pdo, $in['city'] ?? '');
        if ($city === '') json_response(['error' => 'Pick the city this stock is in.'], 422);
        $name = mb_substr(trim(preg_replace('/\s+/', ' ', (string)($in['product_name'] ?? ''))), 0, 160);
        $mlK = retail_ml_key((string)($in['ml'] ?? ''));
        if ($name === '') json_response(['error' => 'Enter the perfume name.'], 422);
        if ($mlK === '') json_response(['error' => 'Pick the size (ml).'], 422);
        $key = retail_stock_key($name, $mlK);
        $cur = null;
        foreach (retail_stock_city_rows($pdo, $city) as $r) if ($r['key'] === $key) { $cur = $r; break; }
        if ($cur) $name = $cur['product_name'];      // keep one spelling for the same perfume
        else foreach (retail_stock_rows($pdo) as $r) if ($r['key'] === $key) { $name = $r['product_name']; break; }
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 255);
        if (array_key_exists('set_to', $in) && $in['set_to'] !== '' && $in['set_to'] !== null) {
            $to = (int)$in['set_to'];
            if ($to < 0 || $to > 1000000) json_response(['error' => 'Enter the counted pieces (0 or more).'], 422);
            $delta = $to - ($cur ? $cur['on_hand'] : 0);
            $kind = $cur ? 'adjust' : 'opening';
            if ($delta === 0 && $cur) json_response(['message' => 'Already ' . $to . ' in stock in ' . $city . ' — nothing to change.', 'item' => $cur]);
            if (!$cur && $delta === 0) json_response(['error' => 'Enter how many pieces you have (more than 0).'], 422);
            $qty = $delta;
            if ($note === '') $note = $cur ? 'Stock count' : 'Opening stock';
        } else {
            $qty = (int)($in['qty'] ?? 0);
            if ($qty < 1 || $qty > 1000000) json_response(['error' => 'Enter how many pieces came in (1 or more).'], 422);
            $kind = $cur ? 'in' : 'opening';
            if ($kind === 'opening' && $note === '') $note = 'Opening stock';
        }
        $pdo->prepare("INSERT INTO retail_stock_log (product_name, ml, qty, kind, note, city, created_by, created_by_name, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
            ->execute([$name, $mlK . ' ml', $qty, $kind, $note, $city, $auth['employee_id'] ?? null, mb_substr((string)($auth['username'] ?? ''), 0, 100), date('Y-m-d H:i:s')]);
        retail_stock_check($pdo);
        $item = null;
        foreach (retail_stock_city_rows($pdo, $city) as $r) if ($r['key'] === $key) { $item = $r; break; }
        json_response(['message' => ($qty >= 0 ? '+' : '') . $qty . ' pcs · ' . trim($name . ' ' . $mlK . ' ml') . ' is now ' . ($item ? $item['on_hand'] : 0) . ' in stock in ' . $city . '.', 'item' => $item, 'city' => $city]);
        break;
    }

    case 'retail.stock_log': {
        // Stock in / adjustments and every order that took pieces out (or brought them back), newest first. ?city= limits it to one city.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the inventory tables.'], 500);
        $only = mb_strtolower(trim((string)($_GET['key'] ?? '')));
        $city = retail_city_get(); if ($city !== '') $city = retail_city_canon($pdo, $city);
        $lc = retail_city_sql($pdo, 'l'); $sc = retail_city_sql($pdo, 's');
        $tracked = [];       // city (lowercase) => [product key => 1]
        foreach (retail_stock_cities($pdo) as $c) foreach (retail_stock_city_rows($pdo, $c) as $r) $tracked[mb_strtolower($c)][$r['key']] = 1;
        $ev = [];
        $lq = $pdo->prepare("SELECT product_name, ml, qty, kind, note, $lc AS c, created_by_name, created_at FROM retail_stock_log l " . ($city !== '' ? "WHERE $lc = ? " : "") . "ORDER BY log_id DESC LIMIT 400");
        $lq->execute($city !== '' ? [$city] : []);
        foreach ($lq->fetchAll() as $r) {
            $k = retail_stock_key((string)$r['product_name'], (string)$r['ml']);
            if ($only !== '' && $k !== $only) continue;
            $ev[] = ['at' => (string)$r['created_at'], 'kind' => (string)$r['kind'], 'product_name' => (string)$r['product_name'], 'ml_text' => retail_stock_ml_text((string)$r['ml']), 'qty' => (int)$r['qty'], 'note' => (string)$r['note'], 'by' => (string)$r['created_by_name'], 'order_no' => '', 'shop' => '', 'city' => (string)$r['c']];
        }
        $oq = $pdo->prepare("SELECT i.product_name, i.ml, i.qty, o.order_type, o.order_no, o.created_at, s.shop_name, $sc AS c FROM retail_order_items i JOIN retail_orders o ON o.order_id = i.order_id LEFT JOIN retail_shops s ON s.shop_id = o.shop_id WHERE o.created_at >= ? " . ($city !== '' ? "AND $sc = ? " : "") . "ORDER BY o.created_at DESC, i.item_id DESC LIMIT 800");
        $oq->execute($city !== '' ? [retail_stock_start($pdo), $city] : [retail_stock_start($pdo)]);
        foreach ($oq->fetchAll() as $r) {
            $k = retail_stock_key((string)$r['product_name'], (string)$r['ml']);
            if (!isset($tracked[mb_strtolower((string)$r['c'])][$k]) || ($only !== '' && $k !== $only)) continue;
            $t = (string)$r['order_type'];
            if (!in_array($t, ['sale', 'display', 'replacement', 'return'], true)) continue;
            $ev[] = ['at' => (string)$r['created_at'], 'kind' => $t === 'return' ? 'return' : 'order', 'product_name' => (string)$r['product_name'], 'ml_text' => retail_stock_ml_text((string)$r['ml']), 'qty' => $t === 'return' ? (int)$r['qty'] : -(int)$r['qty'], 'note' => '', 'by' => '', 'order_no' => (string)$r['order_no'], 'shop' => (string)$r['shop_name'], 'city' => (string)$r['c']];
        }
        usort($ev, fn($a, $b) => strcmp($b['at'], $a['at']));
        json_response(['log' => array_slice($ev, 0, 300), 'city' => $city]);
        break;
    }

    case 'retail.stock_limit_save': {
        // The low-stock limit: one for a perfume + size in a city ("low_limit", empty = the default), or the default for everything ("default_limit").
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the inventory tables.'], 500);
        $in = json_input();
        if (array_key_exists('default_limit', $in)) {
            $v = (int)$in['default_limit'];
            if ($v < 0 || $v > 100000) json_response(['error' => 'Enter a limit between 0 and 100000.'], 422);
            setting_set($pdo, 'retail_stock_low_default', (string)$v);
        } else {
            $city = retail_city_canon($pdo, $in['city'] ?? '');
            if ($city === '') json_response(['error' => 'Pick the city.'], 422);
            $name = trim((string)($in['product_name'] ?? '')); $mlK = retail_ml_key((string)($in['ml'] ?? ''));
            if ($name === '' || $mlK === '') json_response(['error' => 'Perfume and size are needed.'], 422);
            $lim = ($in['low_limit'] ?? '') === '' || ($in['low_limit'] ?? null) === null ? null : (int)$in['low_limit'];
            if ($lim !== null && ($lim < 0 || $lim > 100000)) json_response(['error' => 'Enter a limit between 0 and 100000.'], 422);
            $pdo->prepare("INSERT INTO retail_stock_items (item_key, product_name, ml, city, low_limit, state, updated_at) VALUES (?, ?, ?, ?, ?, 'ok', ?) ON DUPLICATE KEY UPDATE low_limit = VALUES(low_limit), updated_at = VALUES(updated_at)")
                ->execute([retail_stock_item_key(retail_stock_key($name, $mlK), $city), $name, $mlK . ' ml', $city, $lim, date('Y-m-d H:i:s')]);
        }
        retail_stock_check($pdo);
        json_response(['message' => 'Limit saved.']);
        break;
    }

    case 'retail.stock_remove': {
        // Stop tracking one perfume + size in one city (its stock entries and alerts there are removed; orders are untouched).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_stock_tables($pdo)) json_response(['error' => 'Could not create the inventory tables.'], 500);
        $in = json_input();
        $key = mb_strtolower(trim((string)($in['key'] ?? '')));
        $city = retail_city_canon($pdo, $in['city'] ?? '');
        if ($key === '') json_response(['error' => 'Nothing to remove.'], 422);
        if ($city === '') json_response(['error' => 'Pick the city to remove it from.'], 422);
        $lc = retail_city_sql($pdo, 'l');
        $del = $pdo->prepare("DELETE FROM retail_stock_log WHERE log_id = ?");
        $q = $pdo->prepare("SELECT log_id, product_name, ml FROM retail_stock_log l WHERE $lc = ?"); $q->execute([$city]);
        foreach ($q->fetchAll() as $r) if (retail_stock_key((string)$r['product_name'], (string)$r['ml']) === $key) $del->execute([(int)$r['log_id']]);
        $ik = retail_stock_item_key($key, $city);
        $pdo->prepare("DELETE FROM retail_stock_items WHERE item_key = ?")->execute([$ik]);
        $pdo->prepare("DELETE FROM retail_stock_alerts WHERE item_key = ?")->execute([$ik]);
        json_response(['message' => 'Removed from ' . $city . ' inventory.']);
        break;
    }

    case 'retail.stock_alerts': {
        // The bell: latest alerts, and how many Low / Out ones this person has not seen yet.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_stock_tables($pdo)) json_response(['alerts' => [], 'unread' => 0]);
        $uid = (int)($auth['user_id'] ?? 0);
        $seen = $pdo->prepare("SELECT last_id FROM retail_stock_seen WHERE user_id = ?"); $seen->execute([$uid]);
        $last = (int)$seen->fetchColumn();
        $unread = $pdo->prepare("SELECT COUNT(*) FROM retail_stock_alerts WHERE alert_id > ? AND kind IN ('low', 'out')"); $unread->execute([$last]);
        $out = [];
        if (empty($_GET['badge'])) {
            foreach ($pdo->query("SELECT alert_id, kind, title, body, order_no, city, created_at FROM retail_stock_alerts ORDER BY alert_id DESC LIMIT 40")->fetchAll() as $r) {
                $out[] = ['alert_id' => (int)$r['alert_id'], 'kind' => (string)$r['kind'], 'title' => (string)$r['title'], 'body' => (string)$r['body'], 'order_no' => (string)$r['order_no'], 'city' => (string)$r['city'], 'at' => (string)$r['created_at'], 'unread' => (int)$r['alert_id'] > $last];
            }
        }
        json_response(['alerts' => $out, 'unread' => (int)$unread->fetchColumn()]);
        break;
    }

    case 'retail.stock_alerts_seen': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_stock_tables($pdo)) json_response(['ok' => true]);
        $uid = (int)($auth['user_id'] ?? 0);
        $max = (int)$pdo->query("SELECT COALESCE(MAX(alert_id), 0) FROM retail_stock_alerts")->fetchColumn();
        $pdo->prepare("INSERT INTO retail_stock_seen (user_id, last_id) VALUES (?, ?) ON DUPLICATE KEY UPDATE last_id = VALUES(last_id)")->execute([$uid, $max]);
        json_response(['ok' => true]);
        break;
    }

    // ---------------- Retail shops: display stock added by hand ----------------
    case 'retail.display_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $did = (int)($in['display_id'] ?? 0);
        $sid = (int)($in['shop_id'] ?? 0);
        $name = mb_substr(trim((string)($in['product_name'] ?? '')), 0, 160);
        $ml = mb_substr(trim((string)($in['ml'] ?? '')), 0, 20);
        if ($ml !== '' && preg_match('/^\d+(\.\d+)?$/', $ml)) $ml .= ' ml';
        $qty = (int)($in['qty'] ?? 0);
        $price = round((float)($in['price'] ?? 0), 2);
        $since = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['since'] ?? '')) ? (string)$in['since'] : date('Y-m-d');
        if ($did > 0) {
            $q = $pdo->prepare("SELECT shop_id FROM retail_display WHERE display_id = ?"); $q->execute([$did]);
            $sid = (int)$q->fetchColumn();
            if (!$sid) json_response(['error' => 'That display entry no longer exists.'], 404);
        }
        $q = $pdo->prepare("SELECT COUNT(*) FROM retail_shops WHERE shop_id = ?"); $q->execute([$sid]);
        if (!$sid || !(int)$q->fetchColumn()) json_response(['error' => 'Shop not found.'], 404);
        if ($ml === '' && $name === '') json_response(['error' => 'Enter the size (ml) or the perfume name.'], 422);
        if ($qty < 1 || $qty > 100000) json_response(['error' => 'Quantity must be 1 or more.'], 422);
        if ($price < 0 || $price > 10000000) json_response(['error' => 'Enter a valid price per piece.'], 422);
        $now = date('Y-m-d H:i:s');
        if ($did > 0) {
            $pdo->prepare("UPDATE retail_display SET product_name = ?, ml = ?, qty = ?, price = ?, since = ?, updated_at = ? WHERE display_id = ?")->execute([$name, $ml, $qty, $price, $since, $now, $did]);
        } else {
            $pdo->prepare("INSERT INTO retail_display (shop_id, product_name, ml, qty, price, since, created_by, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")->execute([$sid, $name, $ml, $qty, $price, $since, $auth['employee_id'] ?? null, $now, $now]);
            $did = (int)$pdo->lastInsertId();
        }
        json_response(['message' => 'Display saved.', 'display_id' => $did, 'display' => retail_display_rows($pdo, $sid)]);
        break;
    }

    case 'retail.display_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $did = (int)(json_input()['display_id'] ?? 0);
        $q = $pdo->prepare("SELECT shop_id FROM retail_display WHERE display_id = ?"); $q->execute([$did]);
        $sid = (int)$q->fetchColumn();
        if (!$sid) json_response(['error' => 'That display entry no longer exists.'], 404);
        $pdo->prepare("DELETE FROM retail_display WHERE display_id = ?")->execute([$did]);
        json_response(['message' => 'Display removed.', 'display' => retail_display_rows($pdo, $sid)]);
        break;
    }

    // ---------------- Retail shops: saved perfume sets ----------------
    case 'retail.sets': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        json_response(['sets' => retail_sets_load($pdo)]);
        break;
    }

    case 'retail.set_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $sid = (int)($in['set_id'] ?? 0);
        $name = mb_substr(trim((string)preg_replace('/\s+/u', ' ', (string)($in['name'] ?? ''))), 0, 80);
        $list = retail_perfume_list($in['perfumes'] ?? []);
        if ($name === '') json_response(['error' => 'Give the set a name.'], 422);
        if (!$list) json_response(['error' => 'Pick at least one perfume for the set.'], 422);
        $dup = $pdo->prepare("SELECT set_id FROM retail_perfume_sets WHERE LOWER(set_name) = LOWER(?) AND set_id <> ?"); $dup->execute([$name, $sid]);
        if ($dup->fetchColumn()) json_response(['error' => 'A set called "' . $name . '" already exists.'], 422);
        $now = date('Y-m-d H:i:s');
        $pdo->beginTransaction();
        try {
            if ($sid) {
                $q = $pdo->prepare("SELECT COUNT(*) FROM retail_perfume_sets WHERE set_id = ?"); $q->execute([$sid]);
                if (!(int)$q->fetchColumn()) { $pdo->rollBack(); json_response(['error' => 'That set no longer exists.'], 404); }
                $pdo->prepare("UPDATE retail_perfume_sets SET set_name = ?, updated_at = ? WHERE set_id = ?")->execute([$name, $now, $sid]);
                $pdo->prepare("DELETE FROM retail_perfume_set_items WHERE set_id = ?")->execute([$sid]);
            } else {
                $pdo->prepare("INSERT INTO retail_perfume_sets (set_name, created_by, created_at) VALUES (?, ?, ?)")->execute([$name, $auth['employee_id'] ?? null, $now]);
                $sid = (int)$pdo->lastInsertId();
            }
            $ins = $pdo->prepare("INSERT INTO retail_perfume_set_items (set_id, perfume, sort_no) VALUES (?, ?, ?)");
            foreach ($list as $i => $n) $ins->execute([$sid, $n, $i]);
            $pdo->commit();
        } catch (PDOException $e) { if ($pdo->inTransaction()) $pdo->rollBack(); json_response(['error' => 'Could not save the set: ' . $e->getMessage()], 500); }
        json_response(['message' => 'Set saved.', 'set_id' => $sid, 'sets' => retail_sets_load($pdo)]);
        break;
    }

    case 'retail.set_delete': {
        // Shops that used the set keep their own perfume list; they just stop being linked to it.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $sid = (int)(json_input()['set_id'] ?? 0);
        $pdo->prepare("DELETE FROM retail_perfume_set_items WHERE set_id = ?")->execute([$sid]);
        $pdo->prepare("DELETE FROM retail_perfume_sets WHERE set_id = ?")->execute([$sid]);
        $pdo->prepare("UPDATE retail_shops SET perfume_set_id = NULL WHERE perfume_set_id = ?")->execute([$sid]);
        json_response(['message' => 'Set deleted.', 'sets' => retail_sets_load($pdo)]);
        break;
    }

    case 'retail.shop_perfumes': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_retail_tables($pdo);
        $id = (int)($_GET['id'] ?? 0);
        $q = $pdo->prepare("SELECT perfume_set_id FROM retail_shops WHERE shop_id = ?"); $q->execute([$id]);
        $sid = $q->fetchColumn();
        json_response(['perfumes' => retail_shop_perfumes_load($pdo, $id), 'perfume_set_id' => $sid ? (int)$sid : null]);
        break;
    }

    case 'retail.shop_block': {
        // Asked when the "Add shop" form opens: does this login have overdue payments that stop a new shop?
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $items = retail_shop_block($pdo, !empty($auth['employee_id']) ? (int)$auth['employee_id'] : null);
        json_response(['blocked' => $items ? 1 : 0, 'items' => $items, 'total' => round(array_sum(array_map(fn($b) => $b['amount'], $items)), 2), 'can_override' => ($auth['role'] ?? '') === 'Admin']);
        break;
    }

    // ---------------- Retail shops: price per bottle size (fills the price on the order form) ----------------
    case 'retail.ml_prices': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        // first use: the standard per-piece prices (20 ml 175, 50 ml 525, 100 ml 875) — once only, so a list that is later cleared stays cleared
        if (!setting_get($pdo, 'retail_ml_prices_seeded', null)) {
            if (!retail_ml_prices($pdo)) {
                $now = date('Y-m-d H:i:s'); $ins = $pdo->prepare("INSERT INTO retail_ml_prices (ml, price, updated_at) VALUES (?, ?, ?)");
                foreach ([['20', 175], ['50', 525], ['100', 875]] as $r) $ins->execute([$r[0], $r[1], $now]);
            }
            setting_set($pdo, 'retail_ml_prices_seeded', '1');
        }
        json_response(['prices' => retail_ml_prices($pdo)]);
        break;
    }

    case 'retail.ml_prices_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $rows = []; $seen = [];
        foreach (array_slice((array)(json_input()['prices'] ?? []), 0, 60) as $r) {
            $ml = retail_ml_key((string)($r['ml'] ?? ''));
            if ($ml === '') { if (trim((string)($r['ml'] ?? '')) === '' && (float)($r['price'] ?? 0) == 0.0) continue; json_response(['error' => 'A size is not a valid number of ml.'], 422); }
            $pr = round((float)($r['price'] ?? 0), 2);
            if ($pr < 0 || $pr > 10000000) json_response(['error' => 'A price is not valid.'], 422);
            if (isset($seen[$ml])) json_response(['error' => 'The size ' . $ml . ' ml is listed twice.'], 422);
            $seen[$ml] = 1; $rows[] = [$ml, $pr];
        }
        $now = date('Y-m-d H:i:s');
        $pdo->beginTransaction();
        try {
            $pdo->exec("DELETE FROM retail_ml_prices");
            $ins = $pdo->prepare("INSERT INTO retail_ml_prices (ml, price, updated_at) VALUES (?, ?, ?)");
            foreach ($rows as $r) $ins->execute([$r[0], $r[1], $now]);
            $pdo->commit();
        } catch (PDOException $e) { if ($pdo->inTransaction()) $pdo->rollBack(); json_response(['error' => 'Could not save the prices: ' . $e->getMessage()], 500); }
        json_response(['message' => 'Prices saved.', 'prices' => retail_ml_prices($pdo)]);
        break;
    }

    // ---------------- Retail shops: perfume names for the name search ----------------
    case 'retail.perfumes': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_retail_tables($pdo);
        $r = retail_perfume_names(!empty($_GET['refresh']));
        // names already typed on orders / display stay searchable too (old or one-off perfumes)
        $names = $r['names']; $seen = []; foreach ($names as $n) $seen[mb_strtolower($n)] = 1;
        foreach (['SELECT DISTINCT product_name, ml FROM retail_order_items', 'SELECT DISTINCT product_name, ml FROM retail_display'] as $q) {
            try { foreach ($pdo->query($q)->fetchAll() as $row) { $n = retail_name_with_ml((string)$row['product_name'], (string)($row['ml'] ?? '')); if ($n !== '' && !isset($seen[mb_strtolower($n)])) { $seen[mb_strtolower($n)] = 1; $names[] = $n; } } } catch (PDOException $e) {}
        }
        usort($names, fn($a, $b) => strcasecmp($a, $b));
        json_response(['perfumes' => $names, 'count' => count($names), 'source' => $r['source'], 'error' => $r['error'], 'fetched_at' => $r['fetched_at']]);
        break;
    }

    // ---------------- Retail shops: ledger ----------------
    case 'retail.ledger': {
        // One shop's account statement: opening dues, bills (debit), payments and credit notes (credit), running balance.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $id = (int)($_GET['id'] ?? 0);
        $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['from'] ?? '')) ? (string)$_GET['from'] : null;
        $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['to'] ?? '')) ? (string)$_GET['to'] : null;
        $L = retail_ledger_load($pdo, $id);
        if (!isset($L['shops'][$id])) json_response(['error' => 'Shop not found.'], 404);
        $shop = $L['shops'][$id]; $today = date('Y-m-d');
        $c = retail_ledger_calc($shop, $L['orders'][$id] ?? [], $L['pays'][$id] ?? [], $L['byOrder'], $L['byPay'], (float)($L['open'][$id] ?? 0), $today, true);
        $ent = $c['entries'];
        usort($ent, fn($a, $b) => [$a['sort'], $a['rank'], $a['id']] <=> [$b['sort'], $b['rank'], $b['id']]);
        // which lines are inside the date range, with the running balance
        $run = 0.0; $bf = 0.0; $closing = 0.0; $sel = [];
        $sum = ['billed' => 0.0, 'received' => 0.0, 'returns' => 0.0, 'bills' => 0, 'receipts' => 0];
        $openAmt = 0.0;
        foreach ($ent as $e) {
            $run = round($run + $e['debit'] - $e['credit'], 2);
            $d = $e['date'];
            if ($from !== null && ($d === null || $d < $from)) { $bf = $run; $closing = $run; continue; }
            if ($to !== null && $d !== null && $d > $to) continue;
            $e['balance'] = $run; $closing = $run; $sel[] = $e;
            if ($e['kind'] === 'opening') $openAmt += $e['debit'] - $e['credit'];
            elseif ($e['kind'] === 'bill') { $sum['billed'] += $e['debit']; $sum['bills']++; }
            elseif ($e['kind'] === 'receipt') { if ($e['p']['pay_mode'] === 'credit') $sum['returns'] += $e['credit']; else { $sum['received'] += $e['credit']; $sum['receipts']++; } }
        }
        // item names of the bills / returns shown, names of the people who collected, where each receipt went
        $oids = []; $emps = []; $pids = [];
        foreach ($sel as $e) {
            if ($e['kind'] === 'bill') { $oids[] = (int)$e['id']; if ($e['o']['created_by'] !== null) $emps[] = (int)$e['o']['created_by']; }
            if ($e['kind'] === 'receipt') { $pids[] = (int)$e['id']; if ($e['p']['created_by'] !== null) $emps[] = (int)$e['p']['created_by']; }
        }
        $itemTxt = [];
        if ($oids) {
            $in = implode(',', array_fill(0, count($oids), '?'));
            $st = $pdo->prepare("SELECT order_id, product_name, ml, qty FROM retail_order_items WHERE order_id IN ($in) ORDER BY item_id"); $st->execute($oids);
            foreach ($st->fetchAll() as $r) $itemTxt[(int)$r['order_id']][] = $r['product_name'] . ($r['ml'] !== '' ? ' ' . $r['ml'] : '') . ' ×' . (int)$r['qty'];
        }
        $names = [];
        if ($emps) {
            $in = implode(',', array_fill(0, count(array_unique($emps)), '?'));
            $st = $pdo->prepare("SELECT employee_id, full_name FROM employees WHERE employee_id IN ($in)"); $st->execute(array_values(array_unique($emps)));
            foreach ($st->fetchAll() as $r) $names[(int)$r['employee_id']] = (string)$r['full_name'];
        }
        $allocOf = [];
        if ($pids) {
            $in = implode(',', array_fill(0, count($pids), '?'));
            $st = $pdo->prepare("SELECT a.payment_id, a.order_id, a.amount, o.order_no FROM retail_payment_alloc a LEFT JOIN retail_orders o ON o.order_id = a.order_id WHERE a.payment_id IN ($in) ORDER BY a.alloc_id"); $st->execute($pids);
            foreach ($st->fetchAll() as $r) $allocOf[(int)$r['payment_id']][] = ['order_id' => (int)$r['order_id'], 'ref' => (int)$r['order_id'] === 0 ? 'Opening dues' : (string)($r['order_no'] ?? ''), 'amount' => round((float)$r['amount'], 2)];
        }
        $t0 = strtotime($today . ' 00:00:00');
        $rows = [];
        foreach ($sel as $e) {
            $r = ['kind' => $e['kind'], 'id' => (int)$e['id'], 'date' => $e['date'], 'ref' => $e['ref'], 'debit' => round($e['debit'], 2), 'credit' => round($e['credit'], 2), 'balance' => $e['balance']];
            if ($e['kind'] === 'bill') {
                $o = $e['o'];
                $r += ['type' => (string)$o['order_type'], 'qty' => (int)$o['qty'], 'items' => implode(', ', $itemTxt[(int)$e['id']] ?? []), 'note' => (string)$o['note'], 'by' => $o['created_by'] !== null ? ($names[(int)$o['created_by']] ?? '') : ''];
                $r += ['payment' => (string)$o['payment'], 'paid' => round($e['paid'], 2), 'remaining' => round($e['remaining'], 2), 'due_date' => $e['due'], 'discount_type' => (string)$o['discount_type'], 'discount_value' => (float)$o['discount_value'], 'discount_amount' => (float)$o['discount_amount']];
                $r['overdue_days'] = $e['remaining'] > 0.004 && $e['due'] !== null && (string)$o['payment'] === 'pending' ? max(0, (int)round(($t0 - strtotime($e['due'] . ' 00:00:00')) / 86400)) : 0;
            }
            if ($e['kind'] === 'receipt') {
                $p = $e['p'];
                $r += ['mode' => (string)$p['pay_mode'], 'reference' => (string)$p['reference'], 'note' => (string)$p['note'], 'by' => $p['created_by'] !== null ? ($names[(int)$p['created_by']] ?? '') : '', 'allocs' => $allocOf[(int)$e['id']] ?? [], 'on_account' => round($e['on_account'], 2)];
            }
            $rows[] = $r;
        }
        $pending = array_map(fn($i) => ['order_id' => (int)$i['id'], 'ref' => $i['ref'], 'date' => $i['date'], 'due_date' => $i['due'], 'remaining' => $i['rem'], 'billed' => $i['billed']], $c['items']);
        json_response([
            'shop' => ['shop_id' => $id, 'shop_name' => $shop['shop_name'], 'owner_name' => $shop['owner_name'], 'mobile' => $shop['mobile'], 'area' => $shop['area'], 'opening_balance' => round((float)$shop['opening_balance'], 2), 'opening_date' => !empty($shop['opening_date']) ? substr((string)$shop['opening_date'], 0, 10) : null],
            'range' => ['from' => $from, 'to' => $to],
            'rows' => $rows,
            'summary' => ['opening' => round($bf + $openAmt, 2), 'billed' => round($sum['billed'], 2), 'received' => round($sum['received'], 2), 'returns' => round($sum['returns'], 2), 'closing' => round($closing, 2), 'bills' => $sum['bills'], 'receipts' => $sum['receipts']],
            'now' => ['balance' => $c['balance'], 'overdue' => $c['overdue'], 'overdue_days' => $c['overdue_days'], 'status' => $c['status'], 'next_due' => $c['next_due'], 'on_account' => $c['on_account'], 'buckets' => $c['buckets'], 'last_payment' => $c['last_payment']],
            'pending' => $pending,
            'schedule' => retail_pay_schedule($pdo, $c, $L['pays'][$id] ?? [], $today),
            'today' => $today,
        ]);
        break;
    }

    // retail.cash_get — GET from, to, city: collected from shops vs used (paid out) in the dates, cash / upi, what is in hand till "to",
    // the use entries of the dates, party-wise totals and the parties used before (for the form's quick chips).
    case 'retail.cash_get': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo) || !ensure_retail_cash_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $today = date('Y-m-d');
        $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['from'] ?? '')) ? (string)$_GET['from'] : substr($today, 0, 8) . '01';
        $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['to'] ?? '')) ? (string)$_GET['to'] : $today;
        if ($from > $to) json_response(['error' => 'From date must be before To date.'], 422);
        $city = retail_city_get();
        $col = retail_cash_collected($pdo, $from, $to, $city);
        $use = retail_cash_used($pdo, $from, $to, $city);
        $add = retail_cash_used($pdo, $from, $to, $city, 'add');            // money put in by hand (outside the ledger)
        $colAll = retail_cash_collected($pdo, null, $to, $city);
        $useAll = retail_cash_used($pdo, null, $to, $city);
        $addAll = retail_cash_used($pdo, null, $to, $city, 'add');
        $hand = ['total' => round($colAll['total'] + $addAll['total'] - $useAll['total'], 2), 'cash' => round($colAll['cash'] + $addAll['cash'] - $useAll['cash'], 2), 'upi' => round($colAll['upi'] + $addAll['upi'] - $useAll['upi'], 2), 'till' => $to];
        $w = ['u.use_date >= ?', 'u.use_date <= ?']; $a = [$from, $to];
        if ($city !== '') { $w[] = "(u.city = ? OR u.city = '')"; $a[] = $city; }
        $st = $pdo->prepare("SELECT u.use_id, u.use_date, u.city, u.amount, u.mode, u.kind, u.party, u.shop_id, u.note, u.created_by, u.created_by_name, u.created_at, u.updated_at FROM retail_cash_use u WHERE " . implode(' AND ', $w) . " ORDER BY u.use_date DESC, u.use_id DESC");
        $st->execute($a);
        $entries = []; $parties = [];
        foreach ($st->fetchAll() as $r) {
            $r['amount'] = (float)$r['amount']; $r['use_id'] = (int)$r['use_id']; $r['shop_id'] = $r['shop_id'] === null ? 0 : (int)$r['shop_id'];
            $entries[] = $r;
            if ($r['kind'] === 'add') continue;                                   // party-wise = where the money WENT
            $k = mb_strtolower(trim((string)$r['party']));
            if (!isset($parties[$k])) $parties[$k] = ['party' => (string)$r['party'], 'n' => 0, 'cash' => 0.0, 'upi' => 0.0, 'total' => 0.0];
            $parties[$k]['n']++; $parties[$k]['total'] += $r['amount']; $parties[$k][$r['mode'] === 'cash' ? 'cash' : 'upi'] += $r['amount'];
        }
        $pw = array_values($parties);
        usort($pw, fn($x, $y) => $y['total'] <=> $x['total']);
        $recent = [];
        try { foreach ($pdo->query("SELECT party, MAX(use_id) AS m FROM retail_cash_use WHERE party <> '' GROUP BY party ORDER BY m DESC LIMIT 12")->fetchAll() as $r) $recent[] = (string)$r['party']; } catch (PDOException $e) {}
        // the shops for the form's dropdown (the city's shops when a city is picked, else every shop)
        $shops = [];
        try {
            $sq = $pdo->prepare("SELECT s.shop_id, s.shop_name, s.area, " . retail_city_sql($pdo, 's') . " AS city_name FROM retail_shops s" . ($city !== '' ? " WHERE " . retail_city_sql($pdo, 's') . " = ?" : '') . " ORDER BY s.shop_name");
            $sq->execute($city !== '' ? [$city] : []);
            foreach ($sq->fetchAll() as $r) $shops[] = ['shop_id' => (int)$r['shop_id'], 'name' => (string)$r['shop_name'], 'area' => (string)$r['area'], 'city' => (string)$r['city_name']];
        } catch (PDOException $e) {}
        $disp = null;   // the display pending total (till today), so a "Display payment" entry can show what it pays off
        try { if (ensure_retail_demo_display_table($pdo)) $disp = retail_display_pending($pdo, $city); } catch (Throwable $e) { $disp = null; }
        json_response(['from' => $from, 'to' => $to, 'city' => $city, 'collected' => $col, 'added' => $add, 'used' => $use, 'in_hand' => $hand, 'entries' => $entries, 'parties' => $pw, 'recent_parties' => $recent, 'shops' => $shops, 'display' => $disp, 'can_edit' => true]);
    }

    // retail.cash_breakdown — GET what = hand | collected | added | used, from (ignored for hand = all time), to, city, mode (''|cash|upi).
    // Every line that makes up a cash-box card: the ledger receipts from shops (with the orders each one paid), money added by hand,
    // money used — so the card's amount can be checked line by line.
    case 'retail.cash_breakdown': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo) || !ensure_retail_cash_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $what = (string)($_GET['what'] ?? 'hand');
        if (!in_array($what, ['hand', 'collected', 'added', 'used'], true)) $what = 'hand';
        $today = date('Y-m-d');
        $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['to'] ?? '')) ? (string)$_GET['to'] : $today;
        $from = $what === 'hand' ? null : (preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['from'] ?? '')) ? (string)$_GET['from'] : substr($today, 0, 8) . '01');
        $mode = in_array((string)($_GET['mode'] ?? ''), ['cash', 'upi'], true) ? (string)$_GET['mode'] : '';
        $city = retail_city_get();
        $receipts = []; $adds = []; $uses = [];
        if ($what === 'hand' || $what === 'collected') {
            $w = ["p.pay_mode <> 'credit'"]; $a = [];
            if ($from !== null) { $w[] = 'p.pay_date >= ?'; $a[] = $from; }
            $w[] = 'p.pay_date <= ?'; $a[] = $to;
            if ($city !== '') { $w[] = retail_city_sql($pdo, 's') . ' = ?'; $a[] = $city; }
            $st = $pdo->prepare("SELECT p.payment_id, p.receipt_no, p.pay_date, p.amount, p.pay_mode, p.reference, p.note, s.shop_id, s.shop_name, s.area
                                 FROM retail_payments p JOIN retail_shops s ON s.shop_id = p.shop_id WHERE " . implode(' AND ', $w) . " ORDER BY p.pay_date DESC, p.payment_id DESC");
            $st->execute($a);
            $ids = [];
            foreach ($st->fetchAll() as $r) {
                $bk = retail_cash_bucket((string)$r['pay_mode']);
                if ($mode !== '' && $bk !== $mode) continue;
                $receipts[(int)$r['payment_id']] = ['payment_id' => (int)$r['payment_id'], 'receipt_no' => (string)$r['receipt_no'], 'date' => (string)$r['pay_date'], 'amount' => (float)$r['amount'],
                    'mode' => (string)$r['pay_mode'], 'bucket' => $bk, 'reference' => (string)$r['reference'], 'note' => (string)$r['note'],
                    'shop_id' => (int)$r['shop_id'], 'shop' => (string)$r['shop_name'], 'area' => (string)$r['area'], 'orders' => []];
                $ids[] = (int)$r['payment_id'];
            }
            foreach (array_chunk($ids, 500) as $chunk) {
                $q = $pdo->prepare("SELECT a.payment_id, a.amount, o.order_id, o.order_no, o.bill_no, o.order_date, o.billed_total, o.total
                                    FROM retail_payment_alloc a LEFT JOIN retail_orders o ON o.order_id = a.order_id WHERE a.payment_id IN (" . implode(',', array_fill(0, count($chunk), '?')) . ") ORDER BY a.alloc_id");
                $q->execute($chunk);
                foreach ($q->fetchAll() as $r) {
                    $receipts[(int)$r['payment_id']]['orders'][] = ['order_id' => (int)$r['order_id'], 'order_no' => (string)($r['order_no'] ?? ''), 'bill_no' => (string)($r['bill_no'] ?? ''),
                        'order_date' => (string)($r['order_date'] ?? ''), 'bill' => (float)(($r['billed_total'] ?? 0) > 0 ? $r['billed_total'] : ($r['total'] ?? 0)), 'paid' => (float)$r['amount']];
                }
            }
        }
        foreach (['add' => 'hand|added|collected', 'use' => 'hand|used'] as $kind => $whos) {      // the Collected card shows ledger receipts + money added by hand
            if (!in_array($what, explode('|', $whos), true)) continue;
            $w = ['u.kind = ?']; $a = [$kind];
            if ($from !== null) { $w[] = 'u.use_date >= ?'; $a[] = $from; }
            $w[] = 'u.use_date <= ?'; $a[] = $to;
            if ($city !== '') { $w[] = "(u.city = ? OR u.city = '')"; $a[] = $city; }
            if ($mode !== '') { $w[] = 'u.mode = ?'; $a[] = $mode; }
            $st = $pdo->prepare("SELECT u.use_id, u.use_date, u.amount, u.mode, u.party, u.note, u.created_by_name, s.shop_id, s.shop_name FROM retail_cash_use u LEFT JOIN retail_shops s ON s.shop_id = u.shop_id WHERE " . implode(' AND ', $w) . " ORDER BY u.use_date DESC, u.use_id DESC");
            $st->execute($a);
            foreach ($st->fetchAll() as $r) {
                $row = ['use_id' => (int)$r['use_id'], 'date' => (string)$r['use_date'], 'amount' => (float)$r['amount'], 'mode' => (string)$r['mode'], 'party' => (string)$r['party'],
                        'shop' => (string)($r['shop_name'] ?? ''), 'shop_id' => (int)($r['shop_id'] ?? 0), 'note' => (string)$r['note'], 'by' => (string)($r['created_by_name'] ?? '')];
                if ($kind === 'add') $adds[] = $row; else $uses[] = $row;
            }
        }
        $sum = fn($rows) => round(array_sum(array_column($rows, 'amount')), 2);
        $tot = ['collected' => $sum(array_values($receipts)), 'added' => $sum($adds), 'used' => $sum($uses)];
        $tot['total'] = $what === 'used' ? $tot['used'] : round($tot['collected'] + $tot['added'] - ($what === 'hand' ? $tot['used'] : 0), 2);
        json_response(['what' => $what, 'from' => $from, 'to' => $to, 'city' => $city, 'mode' => $mode, 'receipts' => array_values($receipts), 'added' => $adds, 'used' => $uses, 'totals' => $tot]);
    }

    // retail.cash_use_save — POST {use_id (0 = new), date, amount, mode (cash | upi), party, note, city}
    case 'retail.cash_use_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo) || !ensure_retail_cash_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $id = (int)($in['use_id'] ?? 0);
        $date = trim((string)($in['date'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Pick the date.'], 422);
        if ($date > date('Y-m-d')) json_response(['error' => 'The date cannot be in the future.'], 422);
        $amt = (float)str_replace([',', '₹', ' '], '', (string)($in['amount'] ?? ''));
        if (!($amt > 0) || $amt > 99999999) json_response(['error' => 'Type the amount (more than 0).'], 422);
        $mode = strtolower(trim((string)($in['mode'] ?? 'cash')));
        if (!in_array($mode, ['cash', 'upi'], true)) json_response(['error' => 'From must be Cash or UPI.'], 422);
        $kind = strtolower(trim((string)($in['kind'] ?? 'use'))) === 'add' ? 'add' : 'use';   // add = money put in by hand, use = paid out
        $shopId = (int)($in['shop_id'] ?? 0);
        $party = mb_substr(trim(preg_replace('/\s+/u', ' ', (string)($in['party'] ?? ''))), 0, 120);
        if ($shopId > 0) {
            $sq = $pdo->prepare("SELECT shop_name FROM retail_shops WHERE shop_id = ?"); $sq->execute([$shopId]);
            $sn = (string)$sq->fetchColumn();
            if ($sn === '') json_response(['error' => 'That shop is not in the list any more.'], 422);
            $party = $sn;                                  // a shop: its name is the party
        }
        if ($party === '' && $kind === 'add') $party = 'Direct add';   // where-from is optional when adding: it just goes into the total in hand
        if ($party === '') json_response(['error' => 'Pick the party / what the money was used for.'], 422);
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 255);
        $city = mb_substr(trim((string)($in['city'] ?? '')), 0, 60);
        $now = date('Y-m-d H:i:s');
        if ($id > 0) {
            $chk = $pdo->prepare("SELECT use_id FROM retail_cash_use WHERE use_id = ?"); $chk->execute([$id]);
            if (!$chk->fetch()) json_response(['error' => 'That entry is gone already.'], 404);
            $pdo->prepare("UPDATE retail_cash_use SET use_date = ?, city = ?, amount = ?, mode = ?, kind = ?, party = ?, shop_id = ?, note = ?, updated_at = ? WHERE use_id = ?")
                ->execute([$date, $city, round($amt, 2), $mode, $kind, $party, $shopId > 0 ? $shopId : null, $note, $now, $id]);
        } else {
            $pdo->prepare("INSERT INTO retail_cash_use (use_date, city, amount, mode, kind, party, shop_id, note, created_by, created_by_name, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)")
                ->execute([$date, $city, round($amt, 2), $mode, $kind, $party, $shopId > 0 ? $shopId : null, $note, (int)($auth['user_id'] ?? 0), (string)(!empty($auth['employee_id']) ? (employee_names_by_id($pdo)[(int)$auth['employee_id']] ?? $auth['username']) : ($auth['username'] ?? '')), $now]);
            $id = (int)$pdo->lastInsertId();
        }
        $hand = retail_cash_collected($pdo, null, date('Y-m-d'), $city); $used = retail_cash_used($pdo, null, date('Y-m-d'), $city); $added = retail_cash_used($pdo, null, date('Y-m-d'), $city, 'add');
        json_response(['message' => 'Saved.', 'use_id' => $id, 'in_hand' => ['cash' => round($hand['cash'] + $added['cash'] - $used['cash'], 2), 'upi' => round($hand['upi'] + $added['upi'] - $used['upi'], 2)]]);
    }

    // retail.cash_use_delete — POST {use_id}
    case 'retail.cash_use_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_cash_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $id = (int)($in['use_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'use_id is required.'], 422);
        $pdo->prepare("DELETE FROM retail_cash_use WHERE use_id = ?")->execute([$id]);
        json_response(['message' => 'Entry removed.']);
    }

    // retail.demo_get — GET from, to (both optional: empty = all time), status (all | pending | paid), city
    case 'retail.demo_get': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo) || !ensure_retail_demo_display_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['from'] ?? '')) ? (string)$_GET['from'] : null;
        $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['to'] ?? '')) ? (string)$_GET['to'] : null;
        if ($from !== null && $to !== null && $from > $to) json_response(['error' => 'From date must be before To date.'], 422);
        $status = strtolower(trim((string)($_GET['status'] ?? 'all')));
        if (!in_array($status, ['all', 'pending', 'paid'], true)) $status = 'all';
        $city = retail_city_get();
        $tot = retail_demo_display_totals($pdo, $from, $to, $city);
        $cashPaid = retail_display_cash_paid($pdo, $from, $to, $city);          // "Display payment" entries of the cash box in these dates
        $tot['cash_paid'] = $cashPaid['total']; $tot['cash_paid_n'] = $cashPaid['n'];
        $allTime = retail_display_pending($pdo, $city);                         // till today: total, paid, cash_paid, net_pending
        $w = ['1=1']; $a = [];
        if ($from !== null) { $w[] = 'd.disp_date >= ?'; $a[] = $from; }
        if ($to !== null) { $w[] = 'd.disp_date <= ?'; $a[] = $to; }
        if ($city !== '') { $w[] = "(d.city = ? OR d.city = '')"; $a[] = $city; }
        if ($status !== 'all') { $w[] = 'd.pay_status = ?'; $a[] = $status; }
        $st = $pdo->prepare("SELECT d.disp_id, d.disp_date, d.city, d.shop_id, d.shop_name, s.area, d.qty, d.price, d.total, d.pay_status, d.pay_mode, d.paid_date, d.note, d.created_by, d.created_by_name, d.created_at, d.updated_at FROM retail_demo_display d LEFT JOIN retail_shops s ON s.shop_id = d.shop_id WHERE " . implode(' AND ', $w) . " ORDER BY d.disp_date DESC, d.disp_id DESC");
        $st->execute($a);
        $entries = []; $byShop = [];
        foreach ($st->fetchAll() as $r) {
            $r['disp_id'] = (int)$r['disp_id']; $r['shop_id'] = $r['shop_id'] === null ? 0 : (int)$r['shop_id']; $r['qty'] = (int)$r['qty'];
            $r['price'] = (float)$r['price']; $r['total'] = (float)$r['total']; $r['area'] = (string)($r['area'] ?? '');
            $entries[] = $r;
            $k = $r['shop_id'] > 0 ? 'id:' . $r['shop_id'] : 'nm:' . mb_strtolower(trim((string)$r['shop_name']));
            if (!isset($byShop[$k])) $byShop[$k] = ['shop_id' => $r['shop_id'], 'shop_name' => (string)$r['shop_name'], 'n' => 0, 'qty' => 0, 'pending' => 0.0, 'paid' => 0.0, 'total' => 0.0];
            $byShop[$k]['n']++; $byShop[$k]['qty'] += $r['qty']; $byShop[$k]['total'] += $r['total'];
            $byShop[$k][$r['pay_status'] === 'paid' ? 'paid' : 'pending'] += $r['total'];
        }
        $sw = array_values($byShop);
        usort($sw, fn($x, $y) => ($y['pending'] <=> $x['pending']) ?: ($y['total'] <=> $x['total']));
        $shops = [];
        try {
            $sq = $pdo->prepare("SELECT s.shop_id, s.shop_name, s.area, " . retail_city_sql($pdo, 's') . " AS city_name FROM retail_shops s" . ($city !== '' ? " WHERE " . retail_city_sql($pdo, 's') . " = ?" : '') . " ORDER BY s.shop_name");
            $sq->execute($city !== '' ? [$city] : []);
            foreach ($sq->fetchAll() as $r) $shops[] = ['shop_id' => (int)$r['shop_id'], 'name' => (string)$r['shop_name'], 'area' => (string)$r['area'], 'city' => (string)$r['city_name']];
        } catch (PDOException $e) {}
        json_response(['from' => $from, 'to' => $to, 'status' => $status, 'city' => $city, 'totals' => $tot, 'all_time' => $allTime, 'entries' => $entries, 'cash_entries' => $cashPaid['entries'], 'shop_wise' => $sw, 'shops' => $shops, 'can_edit' => true]);
    }

    // retail.demo_save — POST {disp_id (0 = new), date, display (text), total (amount), pay_status (pending | paid), pay_mode (cash | upi), paid_date, note, city}; qty / price / shop_id optional
    case 'retail.demo_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo) || !ensure_retail_demo_display_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $id = (int)($in['disp_id'] ?? 0);
        $date = trim((string)($in['date'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Pick the date.'], 422);
        if ($date > date('Y-m-d')) json_response(['error' => 'The date cannot be in the future.'], 422);
        $shopId = (int)($in['shop_id'] ?? 0);
        $shopName = mb_substr(trim(preg_replace('/\s+/u', ' ', (string)($in['display'] ?? ($in['shop_name'] ?? '')))), 0, 120);   // "Display": what / whom (free text)
        if ($shopId > 0) {
            $sq = $pdo->prepare("SELECT shop_name FROM retail_shops WHERE shop_id = ?"); $sq->execute([$shopId]);
            $sn = (string)$sq->fetchColumn();
            if ($sn === '') json_response(['error' => 'That shop is not in the list any more.'], 422);
            $shopName = $sn;
        }
        if ($shopName === '') json_response(['error' => 'Type the display.'], 422);
        $qty = (int)($in['qty'] ?? 0);
        if ($qty < 0 || $qty > 100000) json_response(['error' => 'Bottles must be 0 or more.'], 422);
        $price = (float)str_replace([',', '₹', ' '], '', (string)($in['price'] ?? ''));
        if ($price < 0 || $price > 99999999) json_response(['error' => 'Price must be 0 or more.'], 422);
        $total = (float)str_replace([',', '₹', ' '], '', (string)($in['total'] ?? ''));
        if (!($total > 0)) $total = $qty * $price;                                   // blank total = qty × price
        if (!($total > 0) || $total > 99999999) json_response(['error' => 'Type the amount (more than 0).'], 422);
        $status = strtolower(trim((string)($in['pay_status'] ?? 'pending'))) === 'paid' ? 'paid' : 'pending';
        $mode = strtolower(trim((string)($in['pay_mode'] ?? '')));
        if ($status === 'paid') { if (!in_array($mode, ['cash', 'upi'], true)) json_response(['error' => 'Paid by Cash or UPI?'], 422); } else $mode = '';
        $paidDate = trim((string)($in['paid_date'] ?? ''));
        if ($status === 'paid') { if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $paidDate)) $paidDate = date('Y-m-d'); } else $paidDate = null;
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 255);
        $city = mb_substr(trim((string)($in['city'] ?? '')), 0, 60);
        $now = date('Y-m-d H:i:s');
        if ($id > 0) {
            $chk = $pdo->prepare("SELECT disp_id FROM retail_demo_display WHERE disp_id = ?"); $chk->execute([$id]);
            if (!$chk->fetch()) json_response(['error' => 'That display entry is gone already.'], 404);
            $pdo->prepare("UPDATE retail_demo_display SET disp_date = ?, city = ?, shop_id = ?, shop_name = ?, qty = ?, price = ?, total = ?, pay_status = ?, pay_mode = ?, paid_date = ?, note = ?, updated_at = ? WHERE disp_id = ?")
                ->execute([$date, $city, $shopId > 0 ? $shopId : null, $shopName, $qty, round($price, 2), round($total, 2), $status, $mode, $paidDate, $note, $now, $id]);
        } else {
            $pdo->prepare("INSERT INTO retail_demo_display (disp_date, city, shop_id, shop_name, qty, price, total, pay_status, pay_mode, paid_date, note, created_by, created_by_name, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)")
                ->execute([$date, $city, $shopId > 0 ? $shopId : null, $shopName, $qty, round($price, 2), round($total, 2), $status, $mode, $paidDate, $note, (int)($auth['user_id'] ?? 0), (string)(!empty($auth['employee_id']) ? (employee_names_by_id($pdo)[(int)$auth['employee_id']] ?? $auth['username']) : ($auth['username'] ?? '')), $now]);
            $id = (int)$pdo->lastInsertId();
        }
        json_response(['message' => 'Saved.', 'disp_id' => $id, 'totals' => retail_display_pending($pdo, $city)]);
    }

    // retail.demo_paid — POST {disp_id, pay_status (paid | pending), pay_mode (cash | upi), paid_date}: mark paid / back to pending
    case 'retail.demo_paid': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_demo_display_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $id = (int)($in['disp_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'disp_id is required.'], 422);
        $status = strtolower(trim((string)($in['pay_status'] ?? 'paid'))) === 'paid' ? 'paid' : 'pending';
        $mode = strtolower(trim((string)($in['pay_mode'] ?? 'cash')));
        if ($status === 'paid' && !in_array($mode, ['cash', 'upi'], true)) json_response(['error' => 'Paid by Cash or UPI?'], 422);
        $paidDate = trim((string)($in['paid_date'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $paidDate) || $paidDate > date('Y-m-d')) $paidDate = date('Y-m-d');
        $chk = $pdo->prepare("SELECT disp_id FROM retail_demo_display WHERE disp_id = ?"); $chk->execute([$id]);
        if (!$chk->fetch()) json_response(['error' => 'That display entry is gone already.'], 404);
        $pdo->prepare("UPDATE retail_demo_display SET pay_status = ?, pay_mode = ?, paid_date = ?, updated_at = ? WHERE disp_id = ?")
            ->execute([$status, $status === 'paid' ? $mode : '', $status === 'paid' ? $paidDate : null, date('Y-m-d H:i:s'), $id]);
        json_response(['message' => $status === 'paid' ? 'Marked paid.' : 'Back to pending.']);
    }

    // retail.demo_delete — POST {disp_id}
    case 'retail.demo_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_demo_display_table($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $id = (int)($in['disp_id'] ?? 0);
        if ($id <= 0) json_response(['error' => 'disp_id is required.'], 422);
        $pdo->prepare("DELETE FROM retail_demo_display WHERE disp_id = ?")->execute([$id]);
        json_response(['message' => 'Display entry removed.']);
    }

    case 'retail.daybook': {
        // One day's business: bills made (per shop), money received that day (any bill), and what is left of the day's bills.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $today = date('Y-m-d');
        $date = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($_GET['date'] ?? '')) ? (string)$_GET['date'] : $today;
        if ($date > $today) $date = $today;
        $rows = [];
        $row = function (int $sid, string $name) use (&$rows) {
            if (!isset($rows[$sid])) $rows[$sid] = ['shop_id' => $sid, 'shop_name' => $name, 'orders' => 0, 'refs' => [], 'billed' => 0.0, 'collected' => 0.0, 'cash' => 0.0, 'upi' => 0.0, 'other' => 0.0];
        };
        $city = retail_city_get(); $cityW = $city !== '' ? " AND " . retail_city_sql($pdo, 's') . " = ?" : ''; $cityA = $city !== '' ? [$city] : [];
        $st = $pdo->prepare("SELECT o.order_id, o.shop_id, o.order_no, o.order_type, o.payment, o.billed_total, s.shop_name FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id WHERE DATE(o.order_date) = ?" . $cityW . " ORDER BY o.order_id");
        $st->execute(array_merge([$date], $cityA));
        foreach ($st->fetchAll() as $o) {
            if (!retail_is_bill($o)) continue;
            $sid = (int)$o['shop_id']; $row($sid, (string)$o['shop_name']);
            $rows[$sid]['orders']++; $rows[$sid]['refs'][] = (string)$o['order_no']; $rows[$sid]['billed'] += (float)$o['billed_total'];
        }
        $st = $pdo->prepare("SELECT p.shop_id, p.amount, p.pay_mode, s.shop_name FROM retail_payments p JOIN retail_shops s ON s.shop_id = p.shop_id WHERE DATE(p.pay_date) = ?" . $cityW . " ORDER BY p.payment_id");
        $st->execute(array_merge([$date], $cityA));
        foreach ($st->fetchAll() as $p) {
            $mode = (string)$p['pay_mode'];
            if ($mode === 'credit') continue;                         // a credit note is not money received
            $sid = (int)$p['shop_id']; $row($sid, (string)$p['shop_name']);
            $amt = (float)$p['amount']; $rows[$sid]['collected'] += $amt;
            $rows[$sid][$mode === 'cash' ? 'cash' : ($mode === 'upi' ? 'upi' : 'other')] += $amt;
        }
        $tot = ['orders' => 0, 'shops' => 0, 'billed' => 0.0, 'collected' => 0.0, 'cash' => 0.0, 'upi' => 0.0, 'other' => 0.0, 'left' => 0.0];
        $out = [];
        foreach ($rows as $r) {
            $r['billed'] = round($r['billed'], 2); $r['collected'] = round($r['collected'], 2);
            $r['left'] = round(max(0.0, $r['billed'] - $r['collected']), 2);
            $r['older'] = round(max(0.0, $r['collected'] - $r['billed']), 2);   // received more than the day's bills: that part cleared older bills
            $tot['orders'] += $r['orders']; $tot['billed'] += $r['billed']; $tot['collected'] += $r['collected']; $tot['left'] += $r['left'];
            $tot['cash'] += $r['cash']; $tot['upi'] += $r['upi']; $tot['other'] += $r['other'];
            if ($r['orders'] > 0) $tot['shops']++;
            $r['cash'] = round($r['cash'], 2); $r['upi'] = round($r['upi'], 2); $r['other'] = round($r['other'], 2);
            $out[] = $r;
        }
        usort($out, fn($a, $b) => [-$a['billed'], -$a['collected'], $a['shop_name']] <=> [-$b['billed'], -$b['collected'], $b['shop_name']]);
        foreach (['billed', 'collected', 'cash', 'upi', 'other', 'left'] as $k) $tot[$k] = round($tot[$k], 2);
        json_response(['date' => $date, 'today' => $today, 'city' => $city, 'rows' => $out, 'totals' => $tot]);
        break;
    }

    case 'retail.outstanding': {
        // Every shop's balance with ageing — who owes what.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $area = trim((string)($_GET['area'] ?? ''));
        $city = retail_city_get();
        $L = retail_ledger_load($pdo, null, $area, $city);
        $pick = retail_shop_ids($_GET['shop_ids'] ?? '');
        $today = date('Y-m-d'); $m0 = date('Y-m-01');
        $shops = []; $tot = ['outstanding' => 0.0, 'outstanding_shops' => 0, 'overdue' => 0.0, 'overdue_shops' => 0, 'collected_month' => 0.0, 'collected_month_n' => 0, 'billed_month' => 0.0, 'billed_month_n' => 0, 'buckets' => [0.0, 0.0, 0.0, 0.0]];
        foreach ($L['shops'] as $sid => $s) {
            if ($pick && !in_array((int)$sid, $pick, true)) continue;
            $orders = $L['orders'][$sid] ?? []; $pays = $L['pays'][$sid] ?? [];
            $c = retail_ledger_calc($s, $orders, $pays, $L['byOrder'], $L['byPay'], (float)($L['open'][$sid] ?? 0), $today);
            foreach ($orders as $o) { if (retail_is_bill($o) && substr((string)$o['order_date'], 0, 10) >= $m0) { $tot['billed_month'] += (float)$o['billed_total']; $tot['billed_month_n']++; } }
            foreach ($pays as $p) { if ((string)$p['pay_mode'] !== 'credit' && substr((string)$p['pay_date'], 0, 10) >= $m0) { $tot['collected_month'] += (float)$p['amount']; $tot['collected_month_n']++; } }
            if ($c['balance'] > 0.004) {
                $tot['outstanding'] += $c['balance']; $tot['outstanding_shops']++;
                foreach ($c['buckets'] as $k => $v) $tot['buckets'][$k] += $v;
            }
            if ($c['overdue'] > 0.004) { $tot['overdue'] += $c['overdue']; $tot['overdue_shops']++; }
            $shops[] = ['shop_id' => $sid, 'shop_name' => $s['shop_name'], 'owner_name' => $s['owner_name'], 'mobile' => $s['mobile'], 'area' => $s['area'], 'city' => (string)($s['city'] !== '' ? $s['city'] : retail_default_city($pdo)), 'active' => $s['status'] === 'active',
                'debit' => $c['debit'], 'credit' => $c['credit'], 'balance' => $c['balance'], 'buckets' => $c['buckets'], 'overdue' => $c['overdue'], 'overdue_days' => $c['overdue_days'],
                'next_due' => $c['next_due'], 'status' => $c['status'], 'last_payment' => $c['last_payment'], 'bills' => $c['bills'], 'receipts' => $c['receipts']];
        }
        usort($shops, fn($a, $b) => [-$a['balance'], $a['shop_name']] <=> [-$b['balance'], $b['shop_name']]);
        $tot = array_map(fn($v) => is_array($v) ? array_map(fn($x) => round($x, 2), $v) : (is_float($v) ? round($v, 2) : $v), $tot);
        $ast = $pdo->prepare("SELECT DISTINCT area FROM retail_shops s WHERE area != ''" . ($city !== '' ? " AND " . retail_city_sql($pdo, 's') . " = ?" : "") . " ORDER BY area"); $ast->execute($city !== '' ? [$city] : []);
        $areas = array_map(fn($r) => $r['area'], $ast->fetchAll());
        json_response(['shops' => $shops, 'totals' => $tot, 'areas' => $areas, 'today' => $today]);
        break;
    }

    case 'retail.payment_add': {
        // Money received from a shop. Without "allocations" it clears the oldest bills first (opening dues first).
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $shopId = (int)($in['shop_id'] ?? 0);
        $amount = round((float)($in['amount'] ?? 0), 2);
        if ($amount <= 0) json_response(['error' => 'Enter the amount received.'], 422);
        if ($amount > 99999999) json_response(['error' => 'That amount is too large.'], 422);
        $today = date('Y-m-d');
        $date = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['pay_date'] ?? '')) ? (string)$in['pay_date'] : $today;
        if ($date > $today) json_response(['error' => 'Payment date cannot be in the future.'], 422);
        $mode = in_array((string)($in['mode'] ?? ''), RETAIL_PAY_MODES, true) ? (string)$in['mode'] : 'cash';
        $ref = mb_substr(trim((string)($in['reference'] ?? '')), 0, 120);
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 255);
        $L = retail_ledger_load($pdo, $shopId);
        if (!isset($L['shops'][$shopId])) json_response(['error' => 'Shop not found.'], 404);
        $c = retail_ledger_calc($L['shops'][$shopId], $L['orders'][$shopId] ?? [], $L['pays'][$shopId] ?? [], $L['byOrder'], $L['byPay'], (float)($L['open'][$shopId] ?? 0), $today);
        $alloc = [];
        if (isset($in['allocations']) && is_array($in['allocations'])) {
            $remOf = [];
            foreach ($c['items'] as $i) $remOf[(int)$i['id']] = (float)$i['rem'];
            $sum = 0.0;
            foreach ($in['allocations'] as $a) {
                $oid = (int)($a['order_id'] ?? 0); $x = round((float)($a['amount'] ?? 0), 2);
                if ($x <= 0) continue;
                if (!isset($remOf[$oid])) json_response(['error' => 'One of the chosen bills is already paid or does not belong to this shop.'], 422);
                $alloc[$oid] = round(($alloc[$oid] ?? 0) + $x, 2); $sum += $x;
                if ($alloc[$oid] > $remOf[$oid] + 0.005) json_response(['error' => 'You entered more than is pending on a bill (₹' . number_format($remOf[$oid], 2) . ').'], 422);
            }
            if ($sum > $amount + 0.005) json_response(['error' => 'The bills add up to more than the amount received.'], 422);
        } else {
            $left = $amount;
            foreach ($c['items'] as $i) {
                if ($left < 0.005) break;
                $x = round(min($left, (float)$i['rem']), 2);
                if ($x > 0) { $alloc[(int)$i['id']] = $x; $left = round($left - $x, 2); }
            }
        }
        $pdo->beginTransaction();
        try {
            $no = retail_next_receipt_no($pdo);
            $pdo->prepare("INSERT INTO retail_payments (shop_id, receipt_no, pay_date, amount, pay_mode, reference, note, created_by, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
                ->execute([$shopId, $no, $date, $amount, $mode, $ref, $note, $auth['employee_id'] ?? null, date('Y-m-d H:i:s')]);
            $pid = (int)$pdo->lastInsertId();
            $insA = $pdo->prepare("INSERT INTO retail_payment_alloc (payment_id, order_id, amount) VALUES (?, ?, ?)");
            foreach ($alloc as $oid => $x) $insA->execute([$pid, (int)$oid, $x]);
            $pdo->commit();
        } catch (PDOException $e) { $pdo->rollBack(); json_response(['error' => 'Could not save the payment: ' . $e->getMessage()], 500); }
        retail_reconcile_shop($pdo, $shopId, array_filter(array_keys($alloc), fn($k) => (int)$k > 0));
        $bal = retail_ledger_balances($pdo, [$shopId])[$shopId] ?? 0;
        $used = round(array_sum($alloc), 2);
        json_response(['message' => 'Receipt ' . $no . ' saved — ' . '₹' . number_format($amount, 2) . ' received.' . ($amount - $used > 0.004 ? ' ₹' . number_format($amount - $used, 2) . ' is kept on account (advance).' : ''), 'payment_id' => $pid, 'receipt_no' => $no, 'balance' => $bal, 'on_account' => round($amount - $used, 2)]);
        break;
    }

    case 'retail.payment_delete': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $pid = (int)(json_input()['payment_id'] ?? 0);
        $st = $pdo->prepare("SELECT shop_id, receipt_no, amount FROM retail_payments WHERE payment_id = ?"); $st->execute([$pid]); $p = $st->fetch();
        if (!$p) json_response(['error' => 'Payment not found.'], 404);
        $st = $pdo->prepare("SELECT DISTINCT order_id FROM retail_payment_alloc WHERE payment_id = ? AND order_id > 0"); $st->execute([$pid]);
        $oids = array_map('intval', array_column($st->fetchAll(), 'order_id'));
        $pdo->beginTransaction();
        try {
            $pdo->prepare("DELETE FROM retail_payment_alloc WHERE payment_id = ?")->execute([$pid]);
            $pdo->prepare("DELETE FROM retail_payments WHERE payment_id = ?")->execute([$pid]);
            $pdo->commit();
        } catch (PDOException $e) { $pdo->rollBack(); json_response(['error' => 'Could not delete the payment: ' . $e->getMessage()], 500); }
        retail_reconcile_shop($pdo, (int)$p['shop_id'], $oids);
        json_response(['message' => 'Receipt ' . $p['receipt_no'] . ' deleted.']);
        break;
    }

    case 'retail.payment_update': {
        // Change a receipt / credit note: date, mode, reference, note and (re-spread over the oldest bills) the amount.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $pid = (int)($in['payment_id'] ?? 0);
        $st = $pdo->prepare("SELECT shop_id, receipt_no, amount FROM retail_payments WHERE payment_id = ?"); $st->execute([$pid]); $p = $st->fetch();
        if (!$p) json_response(['error' => 'Payment not found.'], 404);
        $amount = round((float)($in['amount'] ?? 0), 2);
        if ($amount <= 0) json_response(['error' => 'Enter the amount received.'], 422);
        if ($amount > 99999999) json_response(['error' => 'That amount is too large.'], 422);
        $today = date('Y-m-d');
        $date = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['pay_date'] ?? '')) ? (string)$in['pay_date'] : $today;
        if ($date > $today) json_response(['error' => 'Payment date cannot be in the future.'], 422);
        $mode = in_array((string)($in['mode'] ?? ''), RETAIL_PAY_MODES, true) ? (string)$in['mode'] : 'cash';
        $ref = mb_substr(trim((string)($in['reference'] ?? '')), 0, 120);
        $note = mb_substr(trim((string)($in['note'] ?? '')), 0, 255);
        $st = $pdo->prepare("SELECT DISTINCT order_id FROM retail_payment_alloc WHERE payment_id = ? AND order_id > 0"); $st->execute([$pid]);
        $oids = array_map('intval', array_column($st->fetchAll(), 'order_id'));
        $sameAmt = abs($amount - (float)$p['amount']) < 0.005;
        $pdo->beginTransaction();
        try {
            $pdo->prepare("UPDATE retail_payments SET pay_date = ?, amount = ?, pay_mode = ?, reference = ?, note = ? WHERE payment_id = ?")->execute([$date, $amount, $mode, $ref, $note, $pid]);
            if (!$sameAmt) $pdo->prepare("DELETE FROM retail_payment_alloc WHERE payment_id = ?")->execute([$pid]);   // the money is spread again, oldest bill first
            $pdo->commit();
        } catch (PDOException $e) { $pdo->rollBack(); json_response(['error' => 'Could not save the payment: ' . $e->getMessage()], 500); }
        retail_reconcile_shop($pdo, (int)$p['shop_id'], $oids);
        json_response(['message' => 'Receipt ' . $p['receipt_no'] . ' updated.' . ($sameAmt ? '' : ' The amount was spread over the oldest pending bills again.')]);
        break;
    }

    case 'retail.opening_save': {
        // Change a shop's opening dues (what it owed before the ledger started) and the date.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $in = json_input();
        $sid = (int)($in['shop_id'] ?? 0);
