        if (!$chk->fetchColumn()) json_response(['error' => 'Shop not found.'], 404);
        $amt = round((float)($in['opening_balance'] ?? 0), 2);
        if (abs($amt) > 99999999) json_response(['error' => 'That amount is too large.'], 422);
        $od = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)($in['opening_date'] ?? '')) && abs($amt) > 0.004 ? (string)$in['opening_date'] : null;
        $pdo->prepare("UPDATE retail_shops SET opening_balance = ?, opening_date = ?, updated_at = ? WHERE shop_id = ?")->execute([$amt, $od, date('Y-m-d H:i:s'), $sid]);
        retail_reconcile_shop($pdo, $sid);
