        break;
    }

    case 'retail.import': {
        // Old data from Excel: shops (with opening dues), orders and payments. Without "commit" it only checks the rows and reports.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        @set_time_limit(300);
        $in = json_input();
        $n = 0;
        foreach (['shops', 'orders', 'payments'] as $k) $n += is_array($in[$k] ?? null) ? count($in[$k]) : 0;
        if ($n === 0) json_response(['error' => 'No rows to import.'], 422);
        if ($n > RETAIL_IMP_MAX_ROWS) json_response(['error' => 'Too many rows in one go (' . $n . ', the limit is ' . RETAIL_IMP_MAX_ROWS . ').'], 422);
        try { $res = retail_import_run($pdo, $in, !empty($in['commit']), isset($auth['employee_id']) ? (int)$auth['employee_id'] : null); }
        catch (Throwable $e) { json_response(['error' => 'The import stopped: ' . $e->getMessage() . ' - nothing from this batch was saved.'], 500); }
        json_response($res);
        break;
    }

    // ---------------- Retail shops: orders register ----------------
    case 'retail.register': {
        // Every order of every shop in the register's columns. Filters: q, from, to, kind, status, pay, shop_id. page / per, or all=1 for the Excel download.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        [$w, $a] = retail_register_filter($_GET, $pdo);
        $from = "FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id WHERE " . $w;
        $freeSql = "(o.payment = 'free' OR o.order_type = 'return')";
        $t = $pdo->prepare("SELECT COUNT(*) AS n, COALESCE(SUM(o.qty),0) AS qty, COALESCE(SUM(o.total),0) AS total, COALESCE(SUM(o.billed_total),0) AS billed,
                COALESCE(SUM(CASE WHEN $freeSql THEN 0 ELSE LEAST(o.prepaid_amt, o.billed_total) END),0) AS prepaid,
                COALESCE(SUM(CASE WHEN $freeSql THEN 0 ELSE GREATEST(0, o.billed_total - LEAST(o.prepaid_amt, o.billed_total)) END),0) AS cod,
                COALESCE(SUM(CASE WHEN o.order_kind = 'sample' THEN 1 ELSE 0 END),0) AS samples " . $from);
        $t->execute($a); $tt = $t->fetch();
        $all = !empty($_GET['all']);
        $per = $all ? 5000 : max(10, min(500, (int)($_GET['per'] ?? 100)));
        $page = $all ? 1 : max(1, (int)($_GET['page'] ?? 1));
        $st = $pdo->prepare("SELECT o.*, s.shop_name, s.mobile, s.area, " . retail_city_sql($pdo, 's') . " AS shop_city,
                (SELECT COUNT(*) FROM retail_order_items i WHERE i.order_id = o.order_id) AS `lines`,
                (SELECT MIN(i.product_name) FROM retail_order_items i WHERE i.order_id = o.order_id) AS product " . $from . " ORDER BY o.order_date DESC, o.order_id DESC LIMIT " . $per . " OFFSET " . (($page - 1) * $per));
        $st->execute($a);
        $rows = array_map('retail_register_row', $st->fetchAll());
        json_response(['rows' => $rows, 'page' => $page, 'per' => $per, 'count' => (int)$tt['n'],
            'totals' => ['qty' => (int)$tt['qty'], 'total' => round((float)$tt['total'], 2), 'billed' => round((float)$tt['billed'], 2), 'prepaid' => round((float)$tt['prepaid'], 2), 'cod' => round((float)$tt['cod'], 2), 'samples' => (int)$tt['samples']]]);
        break;
    }

    case 'retail.register_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        try { $res = retail_register_save($pdo, json_input(), $auth['employee_id'] ?? null); }
        catch (InvalidArgumentException $e) { json_response(['error' => $e->getMessage()], 422); }
        catch (PDOException $e) { json_response(['error' => 'Could not save the order: ' . $e->getMessage()], 500); }
        json_response(['message' => 'Order ' . $res['order_no'] . ' saved.' . ($res['created_shop'] !== '' ? ' New shop "' . $res['created_shop'] . '" created.' : '') . ($res['warning'] !== '' ? ' ' . $res['warning'] : '')] + $res);
