    case 'retail.due': {
        // Payments to collect: overdue, due today and due within the next few days, for the reminder card on the Retail Shops page.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if (!ensure_retail_tables($pdo)) json_response(['error' => 'Could not create the retail tables.'], 500);
        $today = date('Y-m-d');
        $all = retail_due_items($pdo, $today);
        $items = array_values(array_filter($all, fn($i) => $i['days'] <= RETAIL_DUE_SOON_DAYS));
        $sum = fn(string $state) => ['n' => count(array_filter($items, fn($i) => $i['state'] === $state)), 'amount' => round(array_sum(array_map(fn($i) => $i['state'] === $state ? $i['amount'] : 0, $items)), 2)];
        $noDate = (int)$pdo->query("SELECT COUNT(*) FROM retail_orders WHERE payment = 'pending' AND due_date IS NULL AND billed_total > paid_amount")->fetchColumn();
        $phones = 0;
        if (!empty($auth['employee_id']) && ensure_push_table($pdo)) {
            $c = $pdo->prepare("SELECT COUNT(*) FROM push_subscriptions WHERE employee_id = ?"); $c->execute([(int)$auth['employee_id']]);
            $phones = (int)$c->fetchColumn();
        }
        json_response([
            'today' => $today, 'items' => $items, 'overdue' => $sum('overdue'), 'due_today' => $sum('today'), 'soon' => $sum('soon'),
            'no_date' => $noDate, 'phones' => $phones, 'linked' => !empty($auth['employee_id']) ? 1 : 0, 'push_hour' => RETAIL_DUE_HOUR, 'late_days' => RETAIL_DUE_LATE_DAYS,
        ]);
        break;
    }

