        if ($sent === 0) json_response(['error' => $failed ? $err : 'No phone has allowed notifications for your login yet — tap “Turn on phone alerts” first.'], 502);
        json_response(['message' => 'Sent to ' . $sent . ' phone' . ($sent === 1 ? '' : 's') . '.' . ($failed ? ' ' . $failed . ' failed.' : ''), 'sent' => $sent]);
