    case 'retail.order_deliver': {
        // Mark what actually reached the shop: per line, or the whole order.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        ensure_retail_tables($pdo);
        $in = json_input();
        $oid = (int)($in['order_id'] ?? 0);
        $st = $pdo->prepare("SELECT order_id FROM retail_orders WHERE order_id = ?"); $st->execute([$oid]);
        if (!$st->fetchColumn()) json_response(['error' => 'Order not found.'], 404);
        if (!empty($in['all'])) {
            $pdo->prepare("UPDATE retail_order_items SET delivered = qty WHERE order_id = ?")->execute([$oid]);
        } else {
            $qtyOf = [];
            $q = $pdo->prepare("SELECT item_id, qty FROM retail_order_items WHERE order_id = ?"); $q->execute([$oid]);
            foreach ($q->fetchAll() as $r) $qtyOf[(int)$r['item_id']] = (int)$r['qty'];
            $up = $pdo->prepare("UPDATE retail_order_items SET delivered = ? WHERE item_id = ? AND order_id = ?");
            foreach ((array)($in['items'] ?? []) as $it) {
                $iid = (int)($it['item_id'] ?? 0);
                if (!$iid || !isset($qtyOf[$iid])) continue;
                $up->execute([max(0, min((int)($it['delivered'] ?? 0), $qtyOf[$iid])), $iid, $oid]);
            }
        }
        if (array_key_exists('bill_delivered', $in)) $pdo->prepare("UPDATE retail_orders SET bill_delivered = ? WHERE order_id = ?")->execute([!empty($in['bill_delivered']) ? 1 : 0, $oid]);
        $r = retail_recalc_order($pdo, $oid);
        $sidDel = (int)$pdo->query("SELECT shop_id FROM retail_orders WHERE order_id = " . $oid)->fetchColumn();
        if ($sidDel) retail_reconcile_shop($pdo, $sidDel, [$oid]);
        $msg = $r['status'] === 'delivered' ? 'All pieces marked delivered.' : ($r['delivered_qty'] . ' of ' . $r['qty'] . ' delivered · ' . ($r['qty'] - $r['delivered_qty']) . ' still pending.');
        json_response(['message' => $msg] + $r);
        break;
    }

    case 'retail.totals': {
        // Shop-wise / monthly / today totals across every shop.
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        @set_time_limit(60);
        try {
            ensure_retail_tables($pdo);
            $today = date('Y-m-d');
            $period = (string)($_GET['period'] ?? 'month');
            $month = preg_match('/^\d{4}-\d{2}$/', (string)($_GET['month'] ?? '')) ? (string)$_GET['month'] : date('Y-m');
            $dateOk = function ($v) { return preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$v) ? (string)$v : null; };
            if ($period === 'today') { $from = $to = $today; $label = 'Today'; }
            elseif ($period === 'custom') {
                $from = $dateOk($_GET['from'] ?? '') ?: date('Y-m-01');
                $to = $dateOk($_GET['to'] ?? '') ?: $today;
                if ($from > $to) { $tmp = $from; $from = $to; $to = $tmp; }
                $label = 'Custom';
            } else {
                $from = $month . '-01'; $to = date('Y-m-t', strtotime($from));
                $label = date('F Y', strtotime($from));
                $period = 'month';
            }
            $area = trim((string)($_GET['area'] ?? ''));
            $areaSql = $area !== '' ? " AND s.area = ?" : '';
            $areaArg = $area !== '' ? [$area] : [];
            $areaSqlAll = $areaSql; $areaArgAll = $areaArg;      // without the city (for the city-by-city table)
            $city = retail_city_get();
            if ($city !== '') { $areaSql .= " AND " . retail_city_sql($pdo, 's') . " = ?"; $areaArg[] = $city; }
            $pickIds = retail_shop_ids($_GET['shop_ids'] ?? '');
            if ($pickIds) $areaSql .= ' AND s.shop_id IN (' . implode(',', $pickIds) . ')';

            $sum = function (string $where, array $args) use ($pdo, $areaSql, $areaArg) {
                $st = $pdo->prepare("SELECT COUNT(*) AS orders, COALESCE(SUM(o.qty),0) AS qty, COALESCE(SUM(o.delivered_qty),0) AS delivered_qty,
                                            COALESCE(SUM(o.billed_total),0) AS amount, COALESCE(SUM(o.delivered_total),0) AS delivered_amount,
                                            COALESCE(SUM(o.paid_amount),0) AS paid,
                                            COALESCE(SUM(CASE WHEN o.payment = 'pending' THEN o.billed_total - o.paid_amount ELSE 0 END),0) AS due
                                     FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id WHERE " . $where . $areaSql);
                $st->execute(array_merge($args, $areaArg));
                $r = $st->fetch() ?: [];
                return ['orders' => (int)($r['orders'] ?? 0), 'qty' => (int)($r['qty'] ?? 0), 'delivered_qty' => (int)($r['delivered_qty'] ?? 0),
                        'amount' => (float)($r['amount'] ?? 0), 'delivered_amount' => (float)($r['delivered_amount'] ?? 0),
                        'paid' => (float)($r['paid'] ?? 0), 'due' => (float)($r['due'] ?? 0)];
            };

            $range = $sum("o.order_date BETWEEN ? AND ?", [$from, $to]);
            $todayTot = $sum("o.order_date = ?", [$today]);

            // Still to deliver / still to be paid: as of now, not only in the range.
            $st = $pdo->prepare("SELECT COUNT(*) AS orders, COALESCE(SUM(o.qty - o.delivered_qty),0) AS qty, COALESCE(SUM(o.total - o.delivered_total),0) AS amount
                                 FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id WHERE o.delivered_qty < o.qty" . $areaSql);
            $st->execute($areaArg);
            $pd = $st->fetch() ?: [];
            $st = $pdo->prepare("SELECT COUNT(*) AS orders, COALESCE(SUM(o.billed_total - o.paid_amount),0) AS amount
                                 FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id WHERE o.payment = 'pending' AND o.billed_total > o.paid_amount" . $areaSql);
            $st->execute($areaArg);
            $pp = $st->fetch() ?: [];

            // Shop-wise, inside the range.
            $st = $pdo->prepare("SELECT s.shop_id, s.shop_name, s.area, s.city AS shop_city, COUNT(o.order_id) AS orders, COALESCE(SUM(o.qty),0) AS qty,
                                        COALESCE(SUM(o.delivered_qty),0) AS delivered, COALESCE(SUM(o.billed_total),0) AS amount,
                                        COALESCE(SUM(o.paid_amount),0) AS paid,
                                        COALESCE(SUM(CASE WHEN o.payment = 'pending' THEN o.billed_total - o.paid_amount ELSE 0 END),0) AS due
                                 FROM retail_shops s JOIN retail_orders o ON o.shop_id = s.shop_id AND o.order_date BETWEEN ? AND ?
                                 WHERE 1=1" . $areaSql . " GROUP BY s.shop_id, s.shop_name, s.area, s.city ORDER BY 8 DESC, s.shop_name");
            $st->execute(array_merge([$from, $to], $areaArg));
            $shops = [];
            foreach ($st->fetchAll() as $r) {
                $shops[] = ['shop_id' => (int)$r['shop_id'], 'shop_name' => $r['shop_name'], 'area' => $r['area'], 'city' => (string)($r['shop_city'] !== '' ? $r['shop_city'] : retail_default_city($pdo)), 'orders' => (int)$r['orders'],
                            'qty' => (int)$r['qty'], 'delivered' => (int)$r['delivered'], 'to_deliver' => max(0, (int)$r['qty'] - (int)$r['delivered']),
                            'amount' => (float)$r['amount'], 'paid' => (float)$r['paid'], 'due' => (float)$r['due']];
            }
            $cq = $pdo->prepare("SELECT COUNT(*) FROM retail_shops s WHERE 1=1" . $areaSql); $cq->execute($areaArg);
            $shopCount = (int)$cq->fetchColumn();
            // City by city (inside the range) — always across all cities, so the All view can compare them.
            $cx = retail_city_sql($pdo, 's');
            $st = $pdo->prepare("SELECT $cx AS c, COUNT(DISTINCT s.shop_id) AS shops, COUNT(o.order_id) AS orders, COALESCE(SUM(o.qty),0) AS qty, COALESCE(SUM(o.billed_total),0) AS amount,
                                        COALESCE(SUM(o.paid_amount),0) AS paid, COALESCE(SUM(CASE WHEN o.payment = 'pending' THEN o.billed_total - o.paid_amount ELSE 0 END),0) AS due
                                 FROM retail_shops s JOIN retail_orders o ON o.shop_id = s.shop_id AND o.order_date BETWEEN ? AND ?
                                 WHERE 1=1" . $areaSqlAll . " GROUP BY c ORDER BY amount DESC, c");
            $st->execute(array_merge([$from, $to], $areaArgAll));
            $byCity = [];
            foreach ($st->fetchAll() as $r) $byCity[] = ['city' => (string)$r['c'], 'shops' => (int)$r['shops'], 'orders' => (int)$r['orders'], 'qty' => (int)$r['qty'], 'amount' => (float)$r['amount'], 'paid' => (float)$r['paid'], 'due' => (float)$r['due']];

            // Last 6 months in one pass.
            $m0 = date('Y-m-01', strtotime($month . '-01 -5 month'));
            $m1 = date('Y-m-t', strtotime($month . '-01'));
            $st = $pdo->prepare("SELECT SUBSTRING(o.order_date, 1, 7) AS ym, COUNT(*) AS orders, COALESCE(SUM(o.qty),0) AS qty,
                                        COALESCE(SUM(o.billed_total),0) AS amount, COALESCE(SUM(o.delivered_total),0) AS delivered_amount
                                 FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id
                                 WHERE o.order_date BETWEEN ? AND ?" . $areaSql . " GROUP BY ym");
            $st->execute(array_merge([$m0, $m1], $areaArg));
            $byMonth = [];
            foreach ($st->fetchAll() as $r) $byMonth[(string)$r['ym']] = $r;
            $months = [];
            for ($i = 5; $i >= 0; $i--) {
                $mk = date('Y-m', strtotime($month . '-01 -' . $i . ' month'));
                $r = $byMonth[$mk] ?? [];
                $months[] = ['month' => $mk, 'label' => date('M', strtotime($mk . '-01')),
                             'amount' => (float)($r['amount'] ?? 0), 'delivered_amount' => (float)($r['delivered_amount'] ?? 0),
                             'orders' => (int)($r['orders'] ?? 0), 'qty' => (int)($r['qty'] ?? 0)];
            }

            // Every order made today, across shops.
            $st = $pdo->prepare("SELECT o.order_id, o.order_no, o.qty, o.delivered_qty, o.billed_total, o.payment, s.shop_id, s.shop_name, e.full_name AS by_name
                                 FROM retail_orders o JOIN retail_shops s ON s.shop_id = o.shop_id LEFT JOIN employees e ON e.employee_id = o.created_by
                                 WHERE o.order_date = ?" . $areaSql . " ORDER BY o.order_id DESC");
            $st->execute(array_merge([$today], $areaArg));
            $todayRows = $st->fetchAll();
            $itemsBy = [];
            if ($todayRows) {
                $in2 = implode(',', array_fill(0, count($todayRows), '?'));
                $st = $pdo->prepare("SELECT order_id, product_name, ml, qty FROM retail_order_items WHERE order_id IN ($in2) ORDER BY item_id");
                $st->execute(array_map(function ($r) { return (int)$r['order_id']; }, $todayRows));
                foreach ($st->fetchAll() as $r) $itemsBy[(int)$r['order_id']][] = trim($r['product_name'] . ' ' . (string)$r['ml']);
            }
            $todayList = [];
            foreach ($todayRows as $r) {
                $todayList[] = ['order_id' => (int)$r['order_id'], 'order_no' => $r['order_no'], 'shop_id' => (int)$r['shop_id'], 'shop_name' => $r['shop_name'],
                                'items' => implode(', ', $itemsBy[(int)$r['order_id']] ?? []), 'qty' => (int)$r['qty'], 'delivered' => (int)$r['delivered_qty'],
                                'amount' => (float)$r['billed_total'], 'payment' => $r['payment'], 'by' => $r['by_name']];
            }

            json_response([
                'range' => ['from' => $from, 'to' => $to, 'label' => $label, 'period' => $period, 'month' => $month],
                'cards' => [
                    'today' => $todayTot,
                    'range' => $range,
                    'pending_delivery' => ['qty' => (int)($pd['qty'] ?? 0), 'amount' => (float)($pd['amount'] ?? 0), 'orders' => (int)($pd['orders'] ?? 0)],
                    'pending_payment' => ['amount' => (float)($pp['amount'] ?? 0), 'orders' => (int)($pp['orders'] ?? 0)],
                ],
                'months' => $months,
                'shops' => $shops,
                'shop_count' => $shopCount,
                'city' => $city,
                'by_city' => $byCity,
                'today' => $todayList,
                'today_date' => $today,
            ]);
        } catch (Throwable $e) {
            // Never let this page die silently — say what the database said.
            json_response(['error' => 'Totals could not be built: ' . $e->getMessage()], 500);
        }
        break;
    }

    case 'retail.map': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        ensure_retail_tables($pdo);
        $city = retail_city_get();
        $st = $pdo->prepare("SELECT s.shop_id, s.shop_name, s.owner_name, s.mobile, s.area, " . retail_city_sql($pdo, 's') . " AS city, s.address, s.lat, s.lng, s.status, MAX(o.order_date) AS last_date, COUNT(o.order_id) AS orders_count
                             FROM retail_shops s LEFT JOIN retail_orders o ON o.shop_id = s.shop_id WHERE s.lat IS NOT NULL" . ($city !== '' ? " AND " . retail_city_sql($pdo, 's') . " = ?" : "") . " GROUP BY s.shop_id ORDER BY s.shop_name");
        $st->execute($city !== '' ? [$city] : []);
        $rows = $st->fetchAll();
        foreach ($rows as &$r) { $r['lat'] = (float)$r['lat']; $r['lng'] = (float)$r['lng']; $r['orders_count'] = (int)$r['orders_count']; }
        unset($r);
        json_response(['shops' => $rows]);
        break;
    }

    case 'shopify.order_detail': {
        $auth = require_auth();
        $storeKey = $_GET['store'] ?? '';
        $orderId = $_GET['id'] ?? '';
        $stores = shopify_stores();
        if (!isset($stores[$storeKey])) json_response(['error' => 'Unknown store.'], 422);
        if (!preg_match('/^\d+$/', (string)$orderId)) json_response(['error' => 'Invalid order id.'], 422);
        $store = $stores[$storeKey];
        $token = shopify_get_token($storeKey, $store);
        if (is_array($token)) json_response(['error' => $token['error']], 502);

        $ch = curl_init("https://{$store['domain']}/admin/api/2024-10/orders/" . $orderId . ".json");
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER => [
                'X-Shopify-Access-Token: ' . $token,
                'Content-Type: application/json',
            ],
            CURLOPT_TIMEOUT => 20,
        ]);
        $resp = curl_exec($ch);
        $status = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        if ($resp === false || $status !== 200) {
            json_response(['error' => 'Could not load order from Shopify (HTTP ' . $status . ').'], 502);
        }
        $o = json_decode($resp, true)['order'] ?? null;
        if (!$o) json_response(['error' => 'Order not found.'], 404);

        if (($auth['role'] ?? '') === 'Employee') {
            $st = $pdo->prepare("SELECT sales_tag FROM employees WHERE employee_id = ?");
            $st->execute([$auth['employee_id'] ?? 0]);
            $empTag = mb_strtolower(trim((string)$st->fetchColumn()));
            $owns = false;
            foreach (explode(',', (string)($o['tags'] ?? '')) as $t) {
                if (mb_strtolower(trim($t)) === $empTag && $empTag !== '') { $owns = true; break; }
            }
            if (!$owns) json_response(['error' => 'This order is not yours.'], 403);
        }

        $addr = $o['shipping_address'] ?? $o['billing_address'] ?? null;
        $tracking = [];
        foreach (($o['fulfillments'] ?? []) as $f) {
            foreach (($f['tracking_numbers'] ?? []) as $i => $tn) {
                $tracking[] = [
                    'number' => $tn,
                    'company' => $f['tracking_company'] ?? '',
                    'url' => $f['tracking_urls'][$i] ?? '',
                ];
            }
        }

        json_response(['order' => [
            'order_name' => $o['name'],
            'store' => $store['label'],
            'created_at' => $o['created_at'],
            'customer' => trim(($o['customer']['first_name'] ?? '') . ' ' . ($o['customer']['last_name'] ?? '')) ?: 'Guest',
            'email' => $o['email'] ?? ($o['customer']['email'] ?? ''),
            'phone' => $o['phone'] ?? ($o['customer']['phone'] ?? ($addr['phone'] ?? '')),
            'address' => $addr ? array_values(array_filter([
                $addr['address1'] ?? '', $addr['address2'] ?? '',
                trim(($addr['city'] ?? '') . ' ' . ($addr['zip'] ?? '')),
                trim(($addr['province'] ?? '') . ', ' . ($addr['country'] ?? ''), ', '),
            ])) : [],
            'line_items' => array_map(fn($li) => [
                'title' => $li['title'],
                'variant' => $li['variant_title'] ?? '',
                'quantity' => (int)$li['quantity'],
                'price' => $li['price'],
                'total' => number_format((float)$li['price'] * (int)$li['quantity'], 2, '.', ''),
            ], $o['line_items'] ?? []),
            'subtotal' => $o['subtotal_price'] ?? '0',
            'discounts' => $o['total_discounts'] ?? '0',
            // Discount code(s) the customer used, with what each took off.
            'discount_codes' => array_values(array_filter(array_map(fn($dc) => [
                'code' => trim((string)($dc['code'] ?? '')),
                'amount' => (string)($dc['amount'] ?? '0'),
            ], is_array($o['discount_codes'] ?? null) ? $o['discount_codes'] : []), fn($dc) => $dc['code'] !== '')),
            'shipping' => $o['total_shipping_price_set']['shop_money']['amount'] ?? '0',
            'tax' => $o['total_tax'] ?? '0',
            'total' => $o['total_price'] ?? '0',
            'currency' => $o['currency'] ?? 'INR',
            'financial_status' => $o['financial_status'] ?? '',
            'outstanding' => isset($o['total_outstanding']) ? (float)$o['total_outstanding'] : null,
            'paid' => (($o['financial_status'] ?? '') === 'partially_paid' && isset($o['total_outstanding'])) ? round(max(0, (float)($o['total_price'] ?? 0) - (float)$o['total_outstanding']), 2) : null,
            'fulfillment_status' => $o['fulfillment_status'] ?? 'unfulfilled',
            'gateway' => implode(', ', $o['payment_gateway_names'] ?? []),
            'note' => $o['note'] ?? '',
            'tags' => $o['tags'] ?? '',
            'tracking' => $tracking,
        ]]);
        break;
    }

    // ============== DASHBOARD ==============
    case 'dashboard.stats': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);   // custom roles: needs the Dashboard module
        $totalEmployees   = (int) $pdo->query("SELECT COUNT(*) FROM employees WHERE status != 'ex'")->fetchColumn();
        $totalDepartments = (int) $pdo->query("SELECT COUNT(*) FROM departments")->fetchColumn();
        $byDept = $pdo->query(
            "SELECT d.department_id, d.department_name, COUNT(e.employee_id) AS total
             FROM departments d
             LEFT JOIN employees e ON e.department_id = d.department_id AND e.status != 'ex'
             GROUP BY d.department_id, d.department_name
             ORDER BY d.department_name"
        )->fetchAll();

        // Documents expiring within 30 days, or already expired.
        // Capped at 10 on the dashboard — the full list is always on the Documents page.
        $expiringTotal = (int) $pdo->query(
            "SELECT COUNT(*) FROM employee_documents ed
             JOIN employees e ON e.employee_id = ed.employee_id AND e.status != 'ex'
             WHERE ed.expiry_date IS NOT NULL AND ed.expiry_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY)"
        )->fetchColumn();

        $expiring = $pdo->query(
            "SELECT ed.employee_document_id, ed.expiry_date, dt.document_name,
                    e.employee_id, e.full_name, e.employee_code,
                    DATEDIFF(ed.expiry_date, CURDATE()) AS days_left
             FROM employee_documents ed
             JOIN document_types dt ON dt.document_type_id = ed.document_type_id
             JOIN employees e ON e.employee_id = ed.employee_id
             WHERE e.status != 'ex'
               AND ed.expiry_date IS NOT NULL
               AND ed.expiry_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY)
             ORDER BY ed.expiry_date ASC
             LIMIT 10"
        )->fetchAll();

        // Required document types each employee hasn't uploaded yet.
        // Capped at 20 rows on the dashboard — the full picture is on each employee's profile.
        $pendingTotal = (int) $pdo->query(
            "SELECT COUNT(*)
             FROM employees e
             CROSS JOIN document_types dt
             WHERE e.status != 'ex'
               AND dt.is_required = 1
               AND NOT EXISTS (
                   SELECT 1 FROM employee_documents ed
                   WHERE ed.employee_id = e.employee_id AND ed.document_type_id = dt.document_type_id
               )"
        )->fetchColumn();

        $pending = $pdo->query(
            "SELECT e.employee_id, e.full_name, e.employee_code, dt.document_name
             FROM employees e
             CROSS JOIN document_types dt
             WHERE e.status != 'ex'
               AND dt.is_required = 1
               AND NOT EXISTS (
                   SELECT 1 FROM employee_documents ed
                   WHERE ed.employee_id = e.employee_id AND ed.document_type_id = dt.document_type_id
               )
             ORDER BY e.full_name, dt.document_name
             LIMIT 20"
        )->fetchAll();

        // Items awaiting Admin approval (added/uploaded by HR). Only meaningful
        // for Admin — computed regardless, but the frontend only surfaces it
        // to Admin users.
        $pendingApprovalEmployees = $pdo->query(
            "SELECT employee_id, full_name, employee_code, created_at
             FROM employees WHERE status = 'pending' ORDER BY created_at DESC"
        )->fetchAll();

        $pendingApprovalDocuments = $pdo->query(
            "SELECT ed.employee_document_id, ed.uploaded_at, ed.document_file, dt.document_name,
                    e.employee_id, e.full_name, e.employee_code
             FROM employee_documents ed
             JOIN document_types dt ON dt.document_type_id = ed.document_type_id
             JOIN employees e ON e.employee_id = ed.employee_id
             WHERE ed.status = 'pending' AND e.status != 'ex'
             ORDER BY ed.uploaded_at DESC"
        )->fetchAll();

        json_response([
            'total_employees' => $totalEmployees,
            'total_departments' => $totalDepartments,
            'by_department' => $byDept,
            'expiring_documents' => $expiring,
            'expiring_documents_total' => $expiringTotal,
            'pending_documents' => $pending,
            'pending_documents_total' => $pendingTotal,
            'pending_approval_employees' => user_can($auth, 'approvals') ? $pendingApprovalEmployees : [],
            'pending_approval_documents' => user_can($auth, 'approvals') ? $pendingApprovalDocuments : [],
        ]);
        break;
    }

    // ============== TMPH ASSISTANT (Google Gemini) ==============
    // ai.status — tells the page whether to show the TMPH button for this person.
    case 'ai.status': {
        $auth = require_auth();
        json_response([
            'enabled' => tmph_allowed($auth),
            'name' => 'TMPH',
            'stream' => (bool)tmph_cfg('TMPH_STREAM', true),
            'max_chars' => (int)tmph_cfg('TMPH_MAX_CHARS', 2000),
            'caps' => tmph_caps(),
            'provider' => tmph_provider(),
            'model' => tmph_chat_models()[0],
        ]);
    }

    // ai.usage — Admin: this month's AI spend by day / model / purpose (tokens and USD), the budget and what is left.
    case 'ai.usage': {
        $auth = require_auth();
        require_role(['Admin'], $auth);
        if (!ensure_ai_usage_table($pdo)) json_response(['error' => 'Usage table not available.'], 500);
        $month = preg_match('/^\d{4}-\d{2}$/', (string)($_GET['month'] ?? '')) ? (string)$_GET['month'] : date('Y-m');
        $q = $pdo->prepare("SELECT use_date, model, purpose, calls, in_tokens, out_tokens, cost_usd FROM ai_usage WHERE use_date LIKE ? ORDER BY use_date, model, purpose"); $q->execute([$month . '%']);
        $rows = $q->fetchAll(); $tot = ['calls' => 0, 'in' => 0, 'out' => 0, 'usd' => 0.0]; $byP = [];
        foreach ($rows as $r) { $tot['calls'] += (int)$r['calls']; $tot['in'] += (int)$r['in_tokens']; $tot['out'] += (int)$r['out_tokens']; $tot['usd'] += (float)$r['cost_usd'];
            $byP[$r['purpose']] = ($byP[$r['purpose']] ?? 0) + (float)$r['cost_usd']; }
        $budget = (float)tmph_cfg('TMPH_MONTH_BUDGET_USD', 180);
        json_response(['month' => $month, 'provider' => tmph_provider(), 'rows' => $rows, 'total' => $tot, 'by_purpose' => $byP, 'budget_usd' => $budget, 'left_usd' => max(0, $budget - $tot['usd'])]);
    }

    // ai.chat — POST {messages:[{role:'user'|'ai', text}], stream?:bool}. Streams the reply as server-sent events:
    //   data: {"t":"piece of text"}   …   data: {"done":true}   (or data: {"error":"friendly message"})
    // With stream off it answers plain JSON {reply}. Problems before Gemini is called answer JSON {error} with a status code.
    case 'ai.chat': {
        $auth = require_auth();
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        if (!tmph_allowed($auth)) json_response(['error' => 'TMPH is not turned on for your account.'], 403);
        $gKey = tmph_key();
        if ($gKey === '') json_response(['error' => 'TMPH is not set up yet. The admin needs to add ANTHROPIC_API_KEY in config.php.'], 503);
        if (tmph_is_claude() && tmph_over_budget()) json_response(['error' => 'The AI budget for this month is used up. Please tell the admin.'], 402);

        $in = json_input();
        $maxChars = max(100, (int)tmph_cfg('TMPH_MAX_CHARS', 2000));
        // Attachments: only the newest message carries the files themselves; earlier turns keep just a note of the file names.
        $msgs = is_array($in['messages'] ?? null) ? array_values($in['messages']) : [];
        $newFiles = null;
        foreach ($msgs as $mi => $mm) {
            if (!is_array($mm)) continue;
            $names = [];
            if (is_array($mm['files'] ?? null)) foreach ($mm['files'] as $ff) if (is_array($ff)) $names[] = mb_substr((string)($ff['name'] ?? 'file'), 0, 80);
            if ($mi === count($msgs) - 1 && ($mm['role'] ?? '') === 'user' && is_array($mm['files'] ?? null) && $mm['files']) $newFiles = $mm['files'];
            elseif ($names) $msgs[$mi]['text'] = trim((string)($mm['text'] ?? '') . ' [attached earlier: ' . implode(', ', array_slice($names, 0, 5)) . ']');
            unset($msgs[$mi]['files']);
        }
        if ($newFiles !== null && trim((string)($msgs[count($msgs) - 1]['text'] ?? '')) === '') $msgs[count($msgs) - 1]['text'] = 'Please look at the attached file(s).';
        [$contents, $badMsg] = tmph_clean_messages($msgs ?: null, $maxChars);
        if ($badMsg) json_response(['error' => $badMsg], 422);
        $GLOBALS['tmph_files'] = []; $GLOBALS['tmph_media_list'] = []; $GLOBALS['tmph_emit_media'] = null; $GLOBALS['tmph_actions_list'] = []; $GLOBALS['tmph_emit_actions'] = null;
        [$fileParts, $fileImgs, $fileNames, $fileErr] = tmph_prepare_files($newFiles);
        if ($fileErr) json_response(['error' => $fileErr], 422);
        if ($fileParts) { foreach ($fileParts as $fp) $contents[count($contents) - 1]['parts'][] = $fp; $GLOBALS['tmph_files'] = $fileImgs; }
        if (!ensure_tmph_table($pdo)) json_response(['error' => 'TMPH could not start (database problem).'], 500);

        [$limitMsg, $limitCode, $logId] = tmph_take_slot($pdo, (int)($auth['user_id'] ?? 0), (string)($_SERVER['REMOTE_ADDR'] ?? ''));
        if ($limitMsg) json_response(['error' => $limitMsg], $limitCode);
        // A reply that fails does not use up the person's daily allowance.
        $refund = function () use ($pdo, $logId): void {
            if ($logId) { try { $pdo->prepare("DELETE FROM tmph_log WHERE id = ?")->execute([$logId]); } catch (PDOException $e) {} }
        };

        $models = tmph_chat_models();           // main model + backups, tried in order when one is overloaded / rate-limited
        if (tmph_is_claude()) {                 // the assistant gets the strongest model (TMPH_ASSISTANT_MODEL in config.php changes or switches this off with '')
            $am = (string)tmph_cfg('TMPH_ASSISTANT_MODEL', 'claude-opus-5-5');
            if ($am !== '' && preg_match('/^claude[A-Za-z0-9._-]{2,55}$/', $am) && !in_array($am, [$models[0]], true)) array_unshift($models, $am);
        }
        $GLOBALS['tmph_purpose'] = 'chat';
        @set_time_limit(150);
        $bearer = get_bearer_token();
        $pg = is_array($in['page'] ?? null) ? $in['page'] : []; $pgTxt = '';       // what the person is looking at (sent by the chat panel): lets "this week" / "here" mean what is on screen
        if ($pg) { $t = mb_substr(preg_replace('/[\r\n]+/', ' ', (string)($pg['title'] ?? '')), 0, 120); $u = mb_substr(preg_replace('/[\r\n]+/', ' ', (string)($pg['url'] ?? '')), 0, 160); $c = is_array($pg['ctx'] ?? null) ? mb_substr(json_encode($pg['ctx'], JSON_UNESCAPED_UNICODE), 0, 400) : '';
            if ($t !== '' || $u !== '') $pgTxt = "\n\nThe person is looking at the page \"" . $t . "\" (" . $u . ")." . ($c !== '' ? ' What is selected on it: ' . $c . '. Treat words like "this", "here", "this week" as that.' : ''); }
        $toolDecls = $bearer ? tmph_tools_for($auth) : [];                 // data tools this person's role may use (none = plain chat)
        $sysText = tmph_system_prompt() . ($toolDecls ? "\n\n" . tmph_tools_prompt($pdo) : '') . $pgTxt;
        if (function_exists('brain_context')) { try { $sysText .= "\n" . brain_context($pdo, 'internal', 'any', ['rules' => true]); } catch (Throwable $e) { } }   // one brain: the staff assistant knows what the company brain knows
        $gBody = [
            'systemInstruction' => ['parts' => [['text' => $sysText]]],
            'contents' => $contents,
            'generationConfig' => ['maxOutputTokens' => 4096],   // no temperature (Google deprecated it for 3.x models); 4096 leaves room for hidden thinking
        ];
        if ($toolDecls) $gBody['tools'] = [['functionDeclarations' => $toolDecls]];
        $wantStream = (bool)tmph_cfg('TMPH_STREAM', true) && (($in['stream'] ?? true) !== false);
        $blockedMsg = "I can't answer that one. Please try asking in a different way.";

        if (!$wantStream) {
            $r = tmph_chat_loop($gKey, $models, $gBody, false, function ($t) {}, $auth, $bearer);
            ll_hook_assistant($auth, $msgs, (string)$r['text']);
            if (trim($r['text']) === '' && (!empty($GLOBALS['tmph_media_list']) || !empty($GLOBALS['tmph_actions_list']))) $r['text'] = !empty($GLOBALS['tmph_actions_list']) ? 'Please check the changes below.' : 'Here you go.';
            if (trim($r['text']) === '') {
                $refund();
                json_response(['error' => $r['blocked'] ? $blockedMsg : ($r['status'] === 200 ? 'TMPH could not make an answer. Please try again.' : tmph_friendly_error($r) . tmph_admin_note($r, $auth))], $r['status'] === 429 ? 429 : 502);
            }
            json_response(['reply' => $r['text'], 'media' => $GLOBALS['tmph_media_list'] ?? [], 'actions' => $GLOBALS['tmph_actions_list'] ?? []]);
        }

        // Streaming: switch off every layer that could hold the reply back until it is finished.
        while (ob_get_level() > 0) @ob_end_clean();
        @ini_set('zlib.output_compression', '0');
        @ini_set('output_buffering', '0');
        header('Content-Type: text/event-stream; charset=UTF-8');
        header('Cache-Control: no-cache, no-transform');
        header('X-Accel-Buffering: no');
        $emit = function (array $o): void {
            echo 'data: ' . json_encode($o, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n\n";
            @ob_flush(); @flush();
        };
        echo ': ' . str_repeat(' ', 2048) . "\n\n";            // padding so proxies start passing the stream on
        @ob_flush(); @flush();
        $GLOBALS['tmph_emit_media'] = function (array $pub) use ($emit): void { $emit(['media' => $pub]); };
        $GLOBALS['tmph_emit_actions'] = function (array $pack) use ($emit): void { $emit(['actions' => $pack]); };
        $r = tmph_chat_loop($gKey, $models, $gBody, true, function ($t) use ($emit) { $emit(['t' => $t]); }, $auth, $bearer);
        ll_hook_assistant($auth, $msgs, (string)$r['text']);
        if (trim($r['text']) === '' && (!empty($GLOBALS['tmph_media_list']) || !empty($GLOBALS['tmph_actions_list']))) { $r['text'] = !empty($GLOBALS['tmph_actions_list']) ? 'Please check the changes below.' : 'Here you go.'; $emit(['t' => $r['text']]); }
        if (trim($r['text']) === '') {
            $refund();
            $emit(['error' => $r['blocked'] ? $blockedMsg : ($r['status'] === 200 ? 'TMPH could not make an answer. Please try again.' : tmph_friendly_error($r) . tmph_admin_note($r, $auth))]);
        } else {
            $emit(['done' => true]);
        }
        exit;
    }

    // report_detail.get — GET date_from, date_to (max 93 days), house ('' = all). The Detailed Performance Report sheet (see report_detail_build()).
    case 'report_detail.get': {
        $auth = require_auth();
        if (strtolower((string)($auth['role'] ?? '')) === 'employee' && !user_can($auth, 'detailed_report')) json_response(['error' => 'You do not have permission to do this.'], 403);
        require_role(['Admin', 'HR'], $auth);
        $bearer = get_bearer_token();
        if (!$bearer) json_response(['error' => 'Please log in again.'], 401);
        $from = trim((string)($_GET['date_from'] ?? biz_today($pdo))); $to = trim((string)($_GET['date_to'] ?? $from));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to)) json_response(['error' => 'Dates must be YYYY-MM-DD.'], 422);
        if ($from > $to) json_response(['error' => 'From date must be before To date.'], 422);
        if ((int)round((strtotime($to) - strtotime($from)) / 86400) + 1 > 93) json_response(['error' => 'Pick at most 93 days.'], 422);
        $house = trim((string)($_GET['house'] ?? ''));
        if ($house !== '' && !in_array($house, report_houses(), true)) json_response(['error' => 'Unknown house.'], 422);
        @set_time_limit(150);
        $r = report_detail_build($pdo, $from, $to, $house, $bearer);
        if (isset($r['error'])) json_response(['error' => $r['error']], 502);
        $r += ['from' => $from, 'to' => $to, 'house' => $house, 'houses' => store_group_options(), 'people' => report_people($pdo), 'today' => biz_today($pdo)];
        $ac = [];
        try { if (ensure_report_manual_table($pdo)) $ac = $pdo->query("SELECT txt FROM report_manual WHERE field = 'acct' AND txt <> '' GROUP BY txt ORDER BY MAX(rep_date) DESC LIMIT 12")->fetchAll(PDO::FETCH_COLUMN); } catch (PDOException $e) {}
        $r['accounts'] = $ac;
        json_response($r);
    }

    // report_detail.set — POST {date, house ('' = All houses view), field, value}. Types a value over the automatic figure (value '' / null clears it).
    // field 'ad' is the Orders page ad spend (same table); 'acct' is text; every other field is a number.
    case 'report_detail.set': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $date = trim((string)($in['date'] ?? '')); $house = trim((string)($in['house'] ?? '')); $field = trim((string)($in['field'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) json_response(['error' => 'Bad date.'], 422);
        if ($house !== '' && !in_array($house, report_houses(), true)) json_response(['error' => 'Unknown house.'], 422);
        $isNum = in_array($field, array_merge(report_num_fields(), ['ad']), true);
        if (!$isNum && $field !== 'acct') json_response(['error' => 'This column is calculated and cannot be typed.'], 422);
        $val = $in['value'] ?? null;
        $blank = $val === null || (is_string($val) && trim($val) === '');
        $by = (string)($auth['username'] ?? '');
        if ($field === 'ad') {
            ensure_panel_spend_table($pdo);
            $panel = $house === '' ? 'all' : $house;
            if ($blank) { $pdo->prepare("DELETE FROM panel_ad_spend WHERE spend_date = ? AND panel = ?")->execute([$date, $panel]); json_response(['message' => 'Back to automatic.']); }
            if (!is_numeric($val) || (float)$val < 0 || (float)$val > 100000000) json_response(['error' => 'Type the ad spend in rupees.'], 422);
            $pdo->prepare("INSERT INTO panel_ad_spend (spend_date, panel, amount, updated_by) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE amount = VALUES(amount), updated_by = VALUES(updated_by)")->execute([$date, $panel, round((float)$val, 2), $by]);
            json_response(['message' => 'Saved.']);
        }
        if (!ensure_report_manual_table($pdo)) json_response(['error' => 'Could not create the report table.'], 500);
        if ($blank) { $pdo->prepare("DELETE FROM report_manual WHERE rep_date = ? AND house = ? AND field = ?")->execute([$date, $house, $field]); json_response(['message' => 'Back to automatic.']); }
        if ($isNum) {
            $v = is_string($val) ? str_replace([',', '₹', ' '], '', $val) : $val;
            if (!is_numeric($v) || (float)$v < 0 || (float)$v > 9999999999) json_response(['error' => 'Type a number (0 or more).'], 422);
            if (in_array($field, ['order', 'qty', 'q', 'qo', 'camp'], true)) $v = round((float)$v); else $v = round((float)$v, 2);
            $pdo->prepare("INSERT INTO report_manual (rep_date, house, field, num, txt, updated_by) VALUES (?, ?, ?, ?, NULL, ?) ON DUPLICATE KEY UPDATE num = VALUES(num), txt = NULL, updated_by = VALUES(updated_by)")->execute([$date, $house, $field, $v, $by]);
        } else {
            $t = mb_substr(trim(preg_replace('/\s+/', ' ', (string)$val)), 0, 200);
            $pdo->prepare("INSERT INTO report_manual (rep_date, house, field, num, txt, updated_by) VALUES (?, ?, ?, NULL, ?, ?) ON DUPLICATE KEY UPDATE txt = VALUES(txt), num = NULL, updated_by = VALUES(updated_by)")->execute([$date, $house, $field, $t, $by]);
        }
        json_response(['message' => 'Saved.']);
    }

    // report_detail.people_save — POST {people: "Pradeep, Dipti, Ayaz"}: whose commission "Combined Commission" adds up.
    case 'report_detail.people_save': {
        $auth = require_auth();
        require_role(['Admin', 'HR'], $auth);
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') json_response(['error' => 'Method not allowed.'], 405);
        $in = json_input();
        $list = [];
        foreach (preg_split('/[,\n;]+/', (string)($in['people'] ?? '')) as $p) { $p = trim($p); if ($p !== '') $list[] = mb_substr($p, 0, 40); }
        if (!$list) json_response(['error' => 'Type at least one name.'], 422);
        setting_set($pdo, 'report_people', implode(', ', array_slice($list, 0, 12)));
        json_response(['message' => 'Saved.', 'people' => report_people($pdo)]);
    }

    // ai.media — GET ?id=… : state of a picture / video TMPH made ({media:{id,kind,status,error}}). For a video that is still working it asks Google.
    case 'ai.media': {
        $auth = require_auth();
        if (!tmph_allowed($auth)) json_response(['error' => 'TMPH is not turned on for your account.'], 403);
        if (!ensure_tmph_media_table($pdo)) json_response(['error' => 'Not available.'], 500);
        $row = tmph_media_get($pdo, (string)($_GET['id'] ?? ''));
        if (!$row || ((int)$row['user_id'] !== (int)($auth['user_id'] ?? 0) && strtolower((string)($auth['role'] ?? '')) !== 'admin')) json_response(['error' => 'Not found.'], 404);
        @set_time_limit(180);
        if ($row['kind'] === 'video' && $row['status'] === 'working') $row = tmph_video_poll($pdo, $row);
        json_response(['media' => tmph_media_public($row)]);
    }

    // ai.media_file — GET ?id=…&download=1&token=… : the picture / video itself (owner or Admin only). Works in <img>/<video>/<a> through ?token=.
    case 'ai.media_file': {
        if (empty($_GET['token'])) { $auth = require_auth(); }
        else { $auth = verify_token((string)$_GET['token']); if (!$auth) json_response(['error' => 'Unauthorized. Please log in again.'], 401); $auth = refresh_auth($auth); }
        if (!tmph_allowed($auth)) json_response(['error' => 'TMPH is not turned on for your account.'], 403);
        if (!ensure_tmph_media_table($pdo)) json_response(['error' => 'Not available.'], 500);
        $row = tmph_media_get($pdo, (string)($_GET['id'] ?? ''));
        if (!$row || $row['status'] !== 'done' || ((int)$row['user_id'] !== (int)($auth['user_id'] ?? 0) && strtolower((string)($auth['role'] ?? '')) !== 'admin')) json_response(['error' => 'Not found.'], 404);
        tmph_media_send($row, !empty($_GET['download']));
    }

    default:
        json_response(['error' => 'Unknown action.'], 404);
}